window.DATA_BUILD='20261024-211825';
window.MANKIW_DATA = {"chapters":[{"num":1,"title":"The Science of Macroeconomics","questions":[{"num":1,"type":"mc","question":"Macroeconomics does not try to answer the question of:","options":["why some countries experience rapid growth.","what is the rate of return on education.","why some countries have high rates of inflation.","what causes recessions and depressions."],"answer":"B","images":null,"translation":{"question":"宏观经济学不试图回答以下哪个问题：","options":["为什么一些国家经历快速增长。","教育的回报率是多少。","为什么一些国家通胀率高。","什么引起衰退和萧条。"]},"topics":["macro-intro"]},{"num":2,"type":"mc","question":"A typical trend during a recession is that:","options":["the unemployment rate falls.","the popularity of the incumbent president rises.","incomes fall.","the inflation rate rises."],"answer":"C","images":null,"translation":{"question":"衰退期间的一个典型趋势是：","options":["失业率下降。","现任总统的支持率上升。","收入下降。","通胀率上升。"]},"topics":["macro-intro"]},{"num":3,"type":"mc","question":"Macroeconomics is the study of the:","options":["activities of individual units of the economy.","decisionmaking by households and firms.","economy as a whole.","interaction of firms and households in the marketplace."],"answer":"C","images":null,"translation":{"question":"宏观经济学研究的是：","options":["经济中个体单位的活动。","家庭和企业的决策。","整体经济。","市场中企业与家庭的相互作用。"]},"topics":["macro-intro"]},{"num":4,"type":"mc","question":"The study of the economy as a whole is called:","options":["household economics.","business economics.","microeconomics.","macroeconomics."],"answer":"D","images":null,"translation":{"question":"把经济作为一个整体来研究被称为：","options":["家庭经济学。","企业经济学。","微观经济学。","宏观经济学。"]},"topics":["macro-intro"]},{"num":5,"type":"mc","question":"The ability of macroeconomists to predict the future course of economic events:","options":["is no better than a meteorologist's ability to predict the next month's weather.","is much better than a meteorologist's ability to predict the next month's weather.","has gotten worse over time.","is less precise than it was in the 1920s."],"answer":"A","images":null,"translation":{"question":"宏观经济学家预测未来经济走势的能力：","options":["并不比气象学家预测下个月天气的能力更好。","远好于气象学家预测下个月天气的能力。","随着时间推移变差了。","不如20世纪20年代时精确。"]},"topics":["macro-intro"]},{"num":6,"type":"mc","question":"Which of the combinations listed is not a U.S. president and an important economic issue of his administration?","options":["President Carter, inflation","President Reagan, budget deficits","President G. H. W. Bush, budget deficits","President Clinton, inflation"],"answer":"D","images":null,"translation":{"question":"下面哪组搭配不是“美国总统及其任期内的重大经济议题”？","options":["卡特总统，通货膨胀","里根总统，预算赤字","老布什总统，预算赤字","克林顿总统，通货膨胀"]},"topics":["macro-intro"]},{"num":7,"type":"mc","question":"All of the following are types of macroeconomics data except the:","options":["price of a computer.","growth rate of real GDP.","inflation rate.","unemployment rate."],"answer":"A","images":null,"translation":{"question":"以下都是宏观经济数据的类型，除了：","options":["一台电脑的价格。","实际GDP增长率。","通胀率。","失业率。"]},"topics":["macro-intro"]},{"num":8,"type":"mc","question":"All of the following except _______ are important macroeconomic variables.","options":["real GDP","the unemployment rate","the marginal rate of substitution","the inflation rate"],"answer":"C","images":null,"translation":{"question":"以下除 _______ 外都是重要的宏观经济变量。","options":["实际GDP","失业率","边际替代率","通胀率"]},"topics":["macro-intro"]},{"num":9,"type":"mc","question":"The total income of everyone in the economy adjusted for the level of base year prices is called:","options":["a recession.","an inflation.","real GDP.","a business fluctuation."],"answer":"C","images":null,"translation":{"question":"经济中所有人的总收入按基年价格水平调整后被称为：","options":["衰退。","通货膨胀。","实际GDP。","经济波动。"]},"topics":["macro-intro"]},{"num":10,"type":"mc","question":"A measure of how fast the general level of prices is rising is called the:","options":["growth rate of real GDP.","inflation rate.","unemployment rate.","market-clearing rate."],"answer":"B","images":null,"translation":{"question":"衡量物价总水平上升速度的指标被称为：","options":["实际GDP增长率。","通胀率。","失业率。","市场出清率。"]},"topics":["macro-intro"]},{"num":11,"type":"mc","question":"The inflation rate is a measure of how fast:","options":["the total income of the economy is growing.","unemployment in the economy is increasing.","the general level of prices in the economy is rising.","the number of jobs in the economy is expanding."],"answer":"C","images":null,"translation":{"question":"通胀率衡量的是：","options":["经济总收入增长的速度。","经济中失业增加的速度。","经济中物价总水平上升的速度。","经济中工作岗位增加的速度。"]},"topics":["macro-intro"]},{"num":12,"type":"mc","question":"Real GDP ______ over time, and the growth rate of real GDP ______.","options":["grows; fluctuates","is steady; is steady","grows; is steady","is steady; fluctuates"],"answer":"A","images":null,"translation":{"question":"实际GDP随时间 ______，实际GDP的增长率 ______。","options":["增长；波动","稳定；稳定","增长；稳定","稳定；波动"]},"topics":["macro-intro"]},{"num":13,"type":"mc","question":"Two striking features of a graph of U.S. real GDP per capita over the twentieth century are the:","options":["overall upward trend interrupted by a large downturn due to the economic depression in the 1930s.","nearly constant level with a large downturn in the 1930s.","downward trend in the first half of the century followed by the upward trend in the second half.","constant level in the first half of the century followed by the upward trend in the second half."],"answer":"A","images":null,"translation":{"question":"20世纪美国人均实际GDP图形的两个显著特征是：","options":["整体上升趋势，被1930年代大萧条造成的大幅下滑打断。","水平基本不变，但在1930年代大幅下滑。","前半世纪下降趋势，后半世纪上升趋势。","前半世纪水平不变，后半世纪上升趋势。"]},"topics":["macro-intro"]},{"num":14,"type":"mc","question":"In the U.S. economy today, real GDP per person, compared with its level in 1900, is about:","options":["50 percent higher.","twice as high.","three times as high.","eight times as high."],"answer":"D","images":null,"translation":{"question":"与1900年的水平相比，今天美国经济的人均实际GDP约为其：","options":["高出50%。","两倍。","三倍。","八倍。"]},"topics":["macro-intro"]},{"num":15,"type":"mc","question":"Recessions are periods when real GDP:","options":["increases slowly.","increases rapidly.","decreases mildly.","decreases severely."],"answer":"C","images":null,"translation":{"question":"衰退是实际GDP：","options":["缓慢增长的时期。","快速增长的时期。","温和下降的时期。","严重下降的时期。"]},"topics":["macro-intro"]},{"num":16,"type":"mc","question":"Compared with real GDP during a recession, real GDP during a depression:","options":["increases more rapidly.","increases at approximately the same rate.","decreases at approximately the same rate.","decreases more severely."],"answer":"D","images":null,"translation":{"question":"与衰退期间的实际GDP相比，萧条期间的实际GDP：","options":["增长更快。","以大致相同的速度增长。","以大致相同的速度下降。","下降更严重。"]},"topics":["macro-intro"]},{"num":17,"type":"mc","question":"A severe recession is called a(n):","options":["depression.","deflation.","exogenous event.","market-clearing assumption."],"answer":"A","images":null,"translation":{"question":"严重的衰退被称为：","options":["萧条。","通货紧缩。","外生事件。","市场出清假设。"]},"topics":["macro-intro"]},{"num":18,"type":"mc","question":"The annual inflation rate in the United States averaged:","options":["nearly zero between 1900 and 1950.","nearly zero between 1950 and 2000.","about 10 percent between 1900 and 1950.","about 10 percent between 1950 and 2000."],"answer":"A","images":null,"translation":{"question":"美国的年通胀率平均：","options":["在1900到1950年间接近零。","在1950到2000年间接近零。","在1900到1950年间约为10%。","在1950到2000年间约为10%。"]},"topics":["macro-intro"]},{"num":19,"type":"mc","question":"Deflation occurs when:","options":["real GDP decreases.","the unemployment rate decreases.","prices fall.","prices increase but at a slower rate."],"answer":"C","images":null,"translation":{"question":"当 ______ 时发生通货紧缩：","options":["实际GDP下降。","失业率下降。","物价下跌。","物价上涨但速度更慢。"]},"topics":["macro-intro"]},{"num":20,"type":"mc","question":"A period of falling prices is called:","options":["deflation.","inflation.","a depression.","a recession."],"answer":"A","images":null,"translation":{"question":"物价下跌的时期被称为：","options":["通货紧缩。","通货膨胀。","萧条。","衰退。"]},"topics":["macro-intro"]},{"num":21,"type":"mc","question":"A graph of the rate of inflation in the United States over the twentieth century shows:","options":["an overall upward trend interrupted by a large downturn in the 1930s.","some periods of deflation mixed with mostly positive rates of inflation before 1955 but only positive rates of inflation after 1955.","a relatively steady, positive level throughout the century except for deflation in the 1930s.","a constant rate of inflation in the first half of the century followed by an upward trend in the second half."],"answer":"B","images":null,"translation":{"question":"20世纪美国通胀率图形显示：","options":["整体上升趋势，被1930年代的大幅下滑打断。","1955年之前，通缩时期与多数正通胀率混合出现；1955年之后只有正通胀率。","除1930年代通缩外，整个世纪都保持相对稳定的正水平。","前半世纪通胀率恒定，后半世纪上升。"]},"topics":["macro-intro"]},{"num":22,"type":"mc","question":"A graph of the U.S. unemployment rate over the twentieth century shows:","options":["an overall upward trend in the unemployment rate interrupted by a large upturn in the 1930s.","an overall downward trend in the unemployment rate interrupted by a large upturn in the 1930s.","rates of unemployment always greater than zero with substantial variations from year to year.","alternating periods of positive and negative rates of unemployment."],"answer":"C","images":null,"translation":{"question":"20世纪美国失业率图形显示：","options":["失业率整体上升趋势，被1930年代的大幅上升打断。","失业率整体下降趋势，被1930年代的大幅上升打断。","失业率始终大于零，且逐年有大幅波动。","正失业率与负失业率交替出现。"]},"topics":["macro-intro"]},{"num":23,"type":"mc","question":"During the period between 1900 and 2000, the unemployment rate in the United States was highest in the:","options":["1920s.","1930s.","1970s.","1980s."],"answer":"B","images":null,"translation":{"question":"在1900到2000年间，美国失业率最高出现在：","options":["1920年代。","1930年代。","1970年代。","1980年代。"]},"topics":["macro-intro"]},{"num":24,"type":"mc","question":"The unemployment rate:","options":["was zero during the 1990s in the United States.","was zero on average between 1900 and 1950 in the United States.","has never been zero in the United States.","is usually zero when the economy is not in a recession or depression."],"answer":"C","images":null,"translation":{"question":"失业率：","options":["在1990年代的美国为零。","在1900到1950年间美国平均为零。","在美国从未为零。","当经济不处于衰退或萧条时通常为零。"]},"topics":["macro-intro"]},{"num":25,"type":"mc","question":"Exogenous variables are:","options":["determined outside the model.","determined within the model.","the outputs of the model.","explained by the model."],"answer":"A","images":null,"translation":{"question":"外生变量是：","options":["模型外部决定的变量。","模型内部决定的变量。","模型的输出。","由模型解释的变量。"]},"topics":["macro-models"]},{"num":26,"type":"mc","question":"Endogenous variables are:","options":["fixed at the moment they enter the model.","determined within the model.","the inputs of the model.","from outside the model."],"answer":"B","images":null,"translation":{"question":"内生变量是：","options":["进入模型时就被固定的变量。","模型内部决定的变量。","模型的输入。","来自模型外部的变量。"]},"topics":["macro-models"]},{"num":27,"type":"mc","question":"In an economic model:","options":["exogenous variables and endogenous variables are both determined outside the model.","endogenous variables and exogenous variables are both determined within the model.","endogenous variables affect exogenous variables.","exogenous variables affect endogenous variables."],"answer":"D","images":null,"translation":{"question":"在经济模型中：","options":["外生变量和内生变量都由模型外部决定。","内生变量和外生变量都由模型内部决定。","内生变量影响外生变量。","外生变量影响内生变量。"]},"topics":["macro-models"]},{"num":28,"type":"mc","question":"Variables that a model tries to explain are called:","options":["endogenous.","exogenous.","market clearing.","fixed."],"answer":"A","images":null,"translation":{"question":"模型试图解释的变量被称为：","options":["内生的。","外生的。","市场出清的。","固定的。"]},"topics":["macro-models"]},{"num":29,"type":"mc","question":"Variables that a model takes as given are called:","options":["endogenous.","exogenous.","market clearing.","macroeconomic."],"answer":"B","images":null,"translation":{"question":"模型视为给定的变量被称为：","options":["内生的。","外生的。","市场出清的。","宏观经济的。"]},"topics":["macro-models"]},{"num":30,"type":"mc","question":"Macroeconomic models are used to explain how ______ variables influence ______ variables.","options":["endogenous; exogenous","exogenous; endogenous","microeconomic; macroeconomic","macroeconomic; microeconomic"],"answer":"B","images":null,"translation":{"question":"宏观经济模型用于解释 ______ 变量如何影响 ______ 变量。","options":["内生；外生","外生；内生","微观；宏观","宏观；微观"]},"topics":["macro-models"]},{"num":31,"type":"mc","question":"Important characteristics of macroeconomic models include all of the following except:","options":["simplifying assumptions.","functional relationships based on randomized control trials.","endogenous and exogenous variables.","implicit or explicit consistency with microeconomic foundations."],"answer":"B","images":null,"translation":{"question":"宏观经济模型的重要特征包括以下所有，除了：","options":["简化假设。","基于随机对照试验的函数关系。","内生和外生变量。","与微观经济基础的显性或隐性一致性。"]},"topics":["macro-models"]},{"num":32,"type":"mc","question":"In a simple model of the supply and demand for pizza, the endogenous variables are:","options":["the price of pizza and the price of cheese.","aggregate income and the quantity of pizza sold.","aggregate income and the price of cheese.","the price of pizza and the quantity of pizza sold."],"answer":"D","images":null,"translation":{"question":"在比萨供求的简单模型中，内生变量是：","options":["比萨的价格和奶酪的价格。","总收入与比萨的销售量。","总收入与奶酪的价格。","比萨的价格与比萨的销售量。"]},"topics":["macro-models"]},{"num":33,"type":"mc","question":"In a simple model of the supply and demand for pizza, when buyers' income increases, the price of pizza ______ and the quantity purchased ______.","options":["increases; decreases","increases; increases","decreases; increases","decreases; decreases"],"answer":"B","images":null,"translation":{"question":"在比萨供求的简单模型中，当买者收入增加时，比萨价格 ______，购买量 ______。","options":["上升；减少","上升；增加","下降；增加","下降；减少"]},"topics":["macro-models"]},{"num":34,"type":"mc","question":"In a simple model of the supply and demand for pizza, when the price of cheese increases, the price of pizza ______ and the quantity purchased ______.","options":["increases; increases","decreases; increases","decreases; decreases","increases; decreases"],"answer":"D","images":null,"translation":{"question":"在比萨供求的简单模型中，当奶酪价格上涨时，比萨价格 ______，购买量 ______。","options":["上升；增加","下降；增加","下降；减少","上升；减少"]},"topics":["macro-models"]},{"num":35,"type":"mc","question":"Which statement below best illustrates the “art,?rather than the “science,?of macroeconomics?","options":["Macroeconomic data provide the motivation for new macroeconomic theory.","Macroeconomic relationships can be expressed using symbols and equations.","Macroeconomists must determine which simplifying assumptions clarify our thinking and which ones mislead us.","Graphs and charts can be used to illustrate the history of macroeconomic variables."],"answer":"C","images":null,"translation":{"question":"下面哪句话最好地说明了宏观经济学中的“艺术”而非“科学”？","options":["宏观经济数据为新宏观经济理论提供动力。","宏观经济关系可以用符号和方程表示。","宏观经济学家必须判断哪些简化假设能厘清思路、哪些会误导我们。","图表可用于展示宏观经济变量的历史。"]},"topics":["macro-intro"]},{"num":36,"type":"mc","question":"In the relationship expressed in functional form Y = G(K, L), Y stands for real GDP, K stands for the amount of capital in the economy, and L stands for the amount of labor in the economy. In this case G( ):","options":["is the growth rate of real GDP when the amount of capital and labor in the economy is fixed.","indicates that the variables inside the parentheses are endogenous variables in the model.","is the symbol that stands for government input into the production process.","is the function telling how the variables in the parentheses determine real GDP."],"answer":"D","images":null,"translation":{"question":"在函数形式 Y = G(K, L) 表示的关系中，Y 代表实际GDP，K 代表经济中的资本量，L 代表经济中的劳动量。此时 G( )：","options":["是当资本和劳动量固定时实际GDP的增长率。","表明括号内的变量是模型中的内生变量。","是代表生产过程中政府投入的符号。","是说明括号中的变量如何决定实际GDP的函数。"]},"topics":["macro-models"]},{"num":37,"type":"mc","question":"Which of the following statements about economic models is true?","options":["There is only one correct economic model.","All economic models are based on the same assumptions.","The purpose of economic models is to show how endogenous variables affect exogenous variables.","Economists use different models to address different economic phenomena."],"answer":"D","images":null,"translation":{"question":"以下关于经济模型的陈述哪个正确？","options":["只有一个正确的经济模型。","所有经济模型基于相同的假设。","经济模型的目的是说明内生变量如何影响外生变量。","经济学家用不同的模型来研究不同的经济现象。"]},"topics":["macro-models"]},{"num":38,"type":"mc","question":"Macroeconomic models:","options":["assume that all wages and prices are sticky.","assume that all wages and prices are flexible.","make different assumptions to explain different aspects of the macroeconomy.","focus primarily on the optimizing behavior of households and firms."],"answer":"C","images":null,"translation":{"question":"宏观经济模型：","options":["假设所有工资和价格都是粘性的。","假设所有工资和价格都是弹性的。","做不同的假设来解释宏观经济的各个方面。","主要关注家庭和企业的最优化行为。"]},"topics":["macro-models"]},{"num":39,"type":"mc","question":"The assumption of continuous market clearing means that:","options":["sellers can sell all that they want at the going price.","buyers can buy all that they want at the going price.","in any given month, buyers can buy all that they want and sellers can sell all that they want at the going price.","at any given instant, buyers can buy all that they want and sellers can sell all that they want at the going price."],"answer":"D","images":null,"translation":{"question":"连续市场出清假设意味着：","options":["卖方能以现行价格卖出所有想卖的数量。","买方能以现行价格买到所有想买的数量。","在任何给定月份，买方和卖方都能以现行价格买卖所有想要的数量。","在任何给定时刻，买方和卖方都能以现行价格买卖所有想要的数量。"]},"topics":["market-clearing"]},{"num":40,"type":"mc","question":"All of the following statements about sticky prices are true except:","options":["in the short run, some wages and prices are sticky.","the sticky-price model describes the equilibrium toward which the economy slowly gravitates.","for studying year-to-year fluctuations, most macroeconomists believe that price stickiness is a better assumption than is price flexibility.","magazine publishers tend to change their newsstand prices only every three or four years."],"answer":"B","images":null,"translation":{"question":"以下关于粘性价格的陈述都是正确的，除了：","options":["短期内，一些工资和价格是粘性的。","粘性价格模型描述了经济缓慢趋向的均衡。","研究年度波动时，多数宏观经济学家认为价格粘性比价格弹性是更好的假设。","杂志出版商往往每三四年才改变一次报刊亭售价。"]},"topics":["market-clearing"]},{"num":41,"type":"mc","question":"The assumption of flexible prices is a more plausible assumption when applied to price changes that occur:","options":["from minute to minute.","from year to year.","in the long run.","in the short run."],"answer":"C","images":null,"translation":{"question":"弹性价格假设更适合应用于发生在 ______ 的价格变化：","options":["每分钟。","每年。","长期。","短期。"]},"topics":["market-clearing"]},{"num":42,"type":"mc","question":"An assumption of _______ is more plausible for studying the short-run behavior of the economy, while an assumption of ______ is more plausible for studying the long-run, equilibrium behavior of the economy.","options":["deflation; inflation","inflation; deflation","flexible prices; sticky prices","sticky prices; flexible prices"],"answer":"D","images":null,"translation":{"question":"研究经济短期行为时 ______ 的假设更合理，而研究经济长期均衡行为时 ______ 的假设更合理。","options":["通缩；通胀","通胀；通缩","弹性价格；粘性价格","粘性价格；弹性价格"]},"topics":["market-clearing"]},{"num":43,"type":"mc","question":"When studying the short-run behavior of the economy, an assumption of ______ is more plausible, whereas when studying the long-run equilibrium behavior of an economy, an assumption of ______ is more plausible.","options":["inflation; unemployment","unemployment; inflation","flexible prices; sticky prices","sticky prices; flexible prices"],"answer":"D","images":null,"translation":{"question":"研究经济短期行为时 ______ 的假设更合理，而研究经济长期均衡行为时 ______ 的假设更合理。","options":["通胀；失业","失业；通胀","弹性价格；粘性价格","粘性价格；弹性价格"]},"topics":["market-clearing"]},{"num":44,"type":"mc","question":"Which of the following is the best example of a sticky price?","options":["the price of a barrel of oil","the price of the U.S. dollar in terms of euros","the price of a share of stock","the price of a soda in a vending machine"],"answer":"D","images":null,"translation":{"question":"以下哪个是粘性价格的最好例子？","options":["一桶石油的价格。","美元兑欧元的汇率。","一只股票的价格。","自动售货机里一瓶汽水的价格。"]},"topics":["market-clearing"]},{"num":45,"type":"mc","question":"Which of the following is the best example of a flexible price?","options":["the price of a cup of coffee in a coffee shop","the price of gasoline at a service station","the price of a ticket at a movie theater","the price of a book in a bookstore"],"answer":"B","images":null,"translation":{"question":"以下哪个是弹性价格的最好例子？","options":["咖啡店里一杯咖啡的价格。","加油站汽油的价格。","电影院一张票的价格。","书店里一本书的价格。"]},"topics":["market-clearing"]},{"num":46,"type":"mc","question":"Macroeconomists are like scientists in that they both:","options":["design data and conduct controlled experiments to test their theories.","rely on data analyzed from experiments they set up in a laboratory.","are unlimited in their use of controlled experiments.","collect data, develop hypotheses, and analyze the results."],"answer":"D","images":null,"translation":{"question":"宏观经济学家与科学家相似，因为他们都：","options":["设计数据并做受控实验来检验理论。","依赖从自己实验室搭建的实验分析出的数据。","不受限制地使用受控实验。","收集数据、提出假设并分析结果。"]},"topics":["macro-intro"]},{"num":47,"type":"mc","question":"Using a market-clearing model to analyze the labor market is ______ because wages usually change ______.","options":["realistic; frequently","realistic; infrequently","unrealistic; frequently","unrealistic; infrequently"],"answer":"D","images":null,"translation":{"question":"用市场出清模型分析劳动力市场是 ______ 的，因为工资通常 ______ 变化。","options":["现实的；频繁","现实的；不频繁","不现实的；频繁","不现实的；不频繁"]},"topics":["market-clearing"]},{"num":48,"type":"sa","question":"Assume that the equation for demand for bread at a small bakery is Qd = 60 ?10Pb + 3Y, where Qd is the quantity of bread demanded in loaves and Y is the average income in the town in thousands of dollars. a.If the average income in the town is 10, state the equation for Qd in terms of Pb. *b.Draw a graph of the demand curve with Qd on the horizontal axis and Pb on the vertical axis. Label the curve DD.*","options":null,"answer":null,"images":null,"translation":{"question":"假设某小面包店的面包需求方程为 Qd = 60 − 10Pb + 3Y，其中 Qd 为面包需求量（条），Y 为该镇平均收入（千美元）。a. 若该镇平均收入为 10，写出 Qd 关于 Pb 的方程。b. 画出需求曲线图，横轴为 Qd、纵轴为 Pb，并标注曲线 DD。","options":null},"topics":["macro-models"],"answer_ref":"a. 代入 Y=10：Qd = 60 − 10Pb + 3×10 = 90 − 10Pb。b. 需求曲线为直线：纵轴 Pb、横轴 Qd，截距为 Pb=9 时 Qd=0、Pb=0 时 Qd=90，连接两点即得向下倾斜的直线，标注 DD。"},{"num":49,"type":"sa","question":"Assume that the equation for demand for bread at a small bakery is Qd = 60 ?10Pb + 3Y, where Qd is the quantity of bread demanded in loaves, Pb is the price of bread in dollars per loaf, and Y is the average income in the town in thousands of dollars. Assume also that the equation for supply of bread is Qs = 30 + 20Pb ?30Pf, where Qs is the quantity supplied and Pf is the price of flour in dollars per pound. Assume finally that markets clear, so that Qd = Qs. a.If Y is 10 and Pf is $1, solve mathematically for equilibrium Q and Pb.*b.If the average income in the town increases to 15, solve for the new equilibrium Q and Pb.*","options":null,"answer":null,"images":null,"translation":{"question":"假设某小面包店面包需求方程 Qd = 60 − 10Pb + 3Y，其中 Qd 为需求量（条）、Pb 为面包价格（美元/条）、Y 为该镇平均收入（千美元）；面包供给方程 Qs = 30 + 20Pb − 30Pf，其中 Qs 为供给量、Pf 为面粉价格（美元/磅）。市场出清，故 Qd = Qs。a. 若 Y = 10 且 Pf = 1美元，求均衡 Q 和 Pb。b. 若该镇平均收入增至 15，求新的均衡 Q 和 Pb。","options":null},"topics":["macro-models"],"answer_ref":"a. Y=10、Pf=1 时：Qd = 90 − 10Pb，Qs = 30 + 20Pb − 30 = 20Pb。令 Qd=Qs：90 − 10Pb = 20Pb，得 Pb=3 美元，Q=60 条。b. Y=15 时：Qd = 105 − 10Pb，令 105 − 10Pb = 20Pb，得 Pb=3.5 美元，Q=70 条。收入提高使需求曲线右移，均衡价与均衡量都上升。"},{"num":50,"type":"sa","question":"The production function for an economy can be expressed as Y = F(K,L), where Y is real GDP, K is the quantity of capital in the economy, and L is the quantity of labor in the economy. a.If F( ) = 100 + 3K + 9L, what is real GDP if the quantity of capital is 200 and the quantity of labor is 500?*b.What is/are the endogenous variable(s) in this model?*c. What is/are the exogenous variable(s) in this model?*","options":null,"answer":null,"images":null,"translation":{"question":"某经济的生产函数可表示为 Y = F(K,L)，其中 Y 为实际GDP、K 为资本量、L 为劳动量。a. 若 F() = 100 + 3K + 9L，当资本量为 200、劳动量为 500 时，实际GDP是多少？b. 该模型中的内生变量是什么？c. 该模型中的外生变量是什么？","options":null},"topics":["macro-models"],"answer_ref":"a. Y = 100 + 3×200 + 9×500 = 100 + 600 + 4500 = 5200。b. 内生变量：Y（由模型内部决定的实际GDP）。c. 外生变量：K 和 L（模型给定的资本量与劳动量）。"},{"num":51,"type":"sa","question":"The quantity of coffee demanded, Qd, depends on the price of coffee, Pc, and the price of tea, PT. The quantity of coffee supplied, Qs, depends on the price of coffee, Pc, and the price of electricity, PE , according to the following equation: Qd = 17 ?2Pc + 10PT*Qs = 2 + 3Pc ?5PE*a.If the price of tea is $1.00 and the price of electricity is $0.50, what are the equilibrium price and quantity of coffee?*b.What is/are the endogenous variable(s) in this model?*c.What is/are the exogenous variable(s) in this model?*","options":null,"answer":null,"images":null,"translation":{"question":"咖啡需求量 Qd 取决于咖啡价格 Pc 和茶价格 PT；咖啡供给量 Qs 取决于咖啡价格 Pc 和电价格 PE，方程如下：Qd = 17 − 2Pc + 10PT，Qs = 2 + 3Pc − 5PE。a. 若茶价格为 1.00 美元、电价格为 0.50 美元，咖啡的均衡价格和数量是多少？b. 该模型的内生变量是什么？c. 该模型的外生变量是什么？","options":null},"topics":["macro-models"],"answer_ref":"a. 代入 PT=1、PE=0.5：Qd = 17 − 2Pc + 10 = 27 − 2Pc；Qs = 2 + 3Pc − 2.5 = 3Pc − 0.5。令 Qd=Qs：27 − 2Pc = 3Pc − 0.5，得 Pc=5.5 美元，Q = 3×5.5 − 0.5 = 16。b. 内生变量：Pc 与 Q（咖啡的价格和数量）。c. 外生变量：PT 与 PE（茶价和电价，由模型外部给定）。"},{"num":52,"type":"sa","question":"What is the difference between recession and depression in an economy? Provide an example of depression from the real world that has hit the global economy.","options":null,"answer":null,"images":null,"translation":{"question":"经济中衰退与萧条有什么区别？举一个现实中冲击全球经济的萧条例子。","options":null},"topics":["macro-intro"],"answer_ref":"衰退（recession）是温和、较短期的经济活动下滑（实际GDP温和下降、通常持续几个季度到一两年）；萧条（depression）是严重且持久的经济崩溃（产出大幅萎缩、失业极高、持续数年）。典型例子：1929—1939 年的大萧条（Great Depression），起源于美国并蔓延至全球。"},{"num":53,"type":"sa","question":"Refer to the following graph and identify the years for which Country A and Country B experienced recession.","options":null,"answer":null,"images":["c1_img0.png"],"translation":{"question":"参照下图，指出 A 国和 B 国经历衰退的年份。","options":null},"topics":["macro-intro"],"answer_ref":"判断方法：衰退期就是实际GDP（产出）比上一年下降的年份，即图中曲线向下倾斜/出现凹口的年份。逐年比较两国GDP的变化即可：凡当年GDP低于上一年的年份即为该国衰退年份。（对照图形中曲线下降段读取出对应年份。）"},{"num":54,"type":"sa","question":"Why do we call macroeconomics an imperfect science? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"为什么我们说宏观经济学是一门不完美的科学？请解释。","options":null},"topics":["macro-intro"],"answer_ref":"因为宏观经济系统极其复杂，研究者必须做大量简化假设、抽象掉许多细节；统计数据 imperfect 且常需修订；无法像自然科学那样做可控实验；不同模型对同一问题常给出不同结论；政策效果存在时滞且受预期影响。因此宏观经济学只能近似地解释和预测经济，是一门\"不完美\"的科学。"},{"num":55,"type":"sa","question":"Are the terms “market clearing?and “equilibrium?one and the same? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"“市场出清”与“均衡”这两个术语是一回事吗？请解释。","options":null},"topics":["market-clearing"],"answer_ref":"不完全相同。市场出清（market clearing）指某一市场上需求量等于供给量、无过剩也无短缺的状态；均衡（equilibrium）含义更广，指所有市场同时出清、所有经济主体都没有改变行为的意愿的整体状态。单一市场出清是（局部）均衡的条件，但一般均衡还要求所有市场联动平衡。日常讨论单一商品时两词常互换使用。"},{"num":56,"type":"sa","question":"Do you agree with the statement “macroeconomics rests on the foundation of microeconomics? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"你同意“宏观经济学建立在微观经济学基础之上”这一说法吗？请解释。","options":null},"topics":["macro-models"],"answer_ref":"基本同意。宏观总量（总消费、总产出、就业）由无数微观个体和企业的优化决策加总而成，微观经济学关于消费者选择、厂商生产和要素定价的分析是宏观模型的基础。但宏观并非微观的简单加总：aggregation 会产生协调失灵、外部性、总需求波动等微观层面不存在的现象。因此宏观建立在微观基础之上，又超越微观。"},{"num":57,"type":"sa","question":"Give two examples of macroeconomic variables and microeconomic variables.","options":null,"answer":null,"images":null,"translation":{"question":"各举两个宏观经济变量和微观经济变量的例子。","options":null},"topics":["macro-intro"],"answer_ref":"宏观变量：GDP（总产出）、通货膨胀率（或失业率）。微观变量：某种具体商品的价格（如面包价格）、某个行业或个人的工资水平（或单个家庭的消费量）。"},{"num":58,"type":"sa","question":"Refer the following table, which shows the quantity of tubes of toothpaste that are demanded at different prices. Identify the price (as shown in the first column below in the table) that represents the market clearing. Price (US$/tube)Quantity demanded (thousands of tubes)Quantity supplied (thousands of tubes)*20520*16816*131212*8158*5175*4183*","options":null,"answer":null,"images":null,"translation":{"question":"参照下表（显示不同价格下牙膏的需求量与供给量），指出代表市场出清的价格。","options":null},"topics":["market-clearing"],"answer_ref":"市场出清的价格是需求量等于供给量的价格。查表：价格为 13 美元/支时，需求量=供给量=12（千支），故 13 美元是市场出清价格。"},{"num":59,"type":"sa","question":"What is the difference between sticky prices and flexible prices? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"粘性价格与弹性价格有什么区别？请解释。","options":null},"topics":["market-clearing"],"answer_ref":"弹性价格（flexible prices）能随供求变化迅速调整（如大宗商品、金融资产价格），是古典模型的假设；粘性价格（sticky prices）调整缓慢，因为存在菜单成本、长期合同、错觉等因素（如工资、许多零售标价）。价格粘性意味着市场短期内可能不能出清，是凯恩斯短期经济波动分析的关键。"},{"num":60,"type":"sa","question":"What is an exogenous variable? Illustrate with graphs the effect of a change in the exogenous variable on a demand and supply relationship. Mark the x-axis and y-axis clearly.","options":null,"answer":null,"images":null,"translation":{"question":"什么是外生变量？用图形说明外生变量变化对供求关系的影响，并清楚标注 x 轴和 y 轴。","options":null},"topics":["macro-models"],"answer_ref":"外生变量是由模型外部给定、其变化被模型视为原因的变量（如需求函数 Qd = a − bP + cY 中的收入 Y，或农产品供给中的天气）。图示：纵轴为价格 P、横轴为数量 Q。外生变量变化使整条曲线移动——如收入上升使需求曲线右移，在原供给曲线上达到更高价、更高量的新均衡；要素（投入品）价格上升使供给曲线左移，新均衡价升量减。"},{"num":61,"type":"sa","question":"Column A below lists the names of four U.S. presidents, and Column B lists four economic events that occurred during the tenures of those U.S. presidents. Match each president to the economic event that occurred during his tenure. Column AColumn B*1. Jimmy Cartera. budget surplus*2. Ronald Reganb. inflation*3. Bill Clintonc. steep rise in mortgage defaults*4. Barack Obamad. budget deficit*","options":null,"answer":null,"images":null,"translation":{"question":"下表 A 栏列出四位美国总统的名字，B 栏列出这些总统任期内发生的四件经济事件。请将每位总统与其任期内发生的经济事件配对。","options":null},"topics":["macro-intro"],"answer_ref":"1. Jimmy Carter — b. 通货膨胀（20 世纪 70 年代末高通胀）；2. Ronald Reagan — d. 预算赤字（80 年代大规模减税与国防开支）；3. Bill Clinton — a. 预算盈余（90 年代末财政盈余）；4. Barack Obama — c. 抵押贷款违约骤增（2008 年次贷危机后止赎潮）。"}]},{"num":2,"title":"The Data of Macroeconomics","questions":[{"num":1,"type":"mc","question":"The economic statistic used to measure the level of prices is:","options":["GDP.","CPI.","GNP.","real GDP."],"answer":"B","images":null,"translation":{"question":"用来衡量物价水平的经济统计指标是：","options":["GDP。","CPI。","GNP。","实际GDP。"]},"topics":["cpi-inflation"]},{"num":2,"type":"mc","question":"The statistic economists use to measure the value of economic output is:","options":["the CPI.","GDP.","the GDP deflator.","the unemployment rate."],"answer":"B","images":null,"translation":{"question":"经济学家用来衡量经济产出价值的统计指标是：","options":["CPI。","GDP。","GDP平减指数。","失业率。"]},"topics":["gdp-accounting"]},{"num":3,"type":"mc","question":"GDP is all of the following except:","options":["the total expenditure of everyone in the economy.","the total income of everyone in the economy.","the overall expenditure on the economy's output of goods and services.","the total output of the economy."],"answer":"A","images":null,"translation":{"question":"GDP 是以下所有各项，除了：","options":["经济中每个人的总支出。","经济中每个人的总收入。","对经济中商品和服务产出的总支出。","经济的总产出。"]},"topics":["gdp-accounting"]},{"num":4,"type":"mc","question":"The total income of everyone in the economy is exactly equal to the total:","options":["expenditure on the economy's output of goods and services.","consumption expenditures of everyone in the economy.","expenditures of all businesses in the economy.","government expenditures."],"answer":"A","images":null,"translation":{"question":"经济中每个人的总收入恰好等于总的：","options":["对经济中商品和服务产出的支出。","经济中每个人的消费支出。","经济中所有企业的支出。","政府支出。"]},"topics":["gdp-accounting"]},{"num":5,"type":"mc","question":"An economy's ______ equals its ______.","options":["consumption; income","consumption; expenditure on goods and services","expenditure on goods; expenditures on services","total income; total expenditure on goods and services"],"answer":"D","images":null,"translation":{"question":"一个经济的 ______ 等于它的 ______。","options":["消费；收入","消费；商品和服务支出","商品支出；服务支出","总收入；商品和服务总支出"]},"topics":["gdp-accounting"]},{"num":6,"type":"mc","question":"Two equivalent ways to view GDP are as the:","options":["total payments made to all workers in the economy or the total profits of all firms and businesses in the economy.","total expenditures on all goods produced in the economy or the total income earned from producing all services in the economy.","total profits of all firms and businesses in the economy or the total consumption of goods and services by all households in the economy.","total income of everyone in the economy or the total expenditure on the economy's output of goods and services."],"answer":"D","images":null,"translation":{"question":"看待 GDP 的两种等价方式是把它看作：","options":["支付给经济中所有工人的总报酬，或经济中所有企业和商行的总利润。","对经济中生产的所有商品的总支出，或生产经济中所有服务所赚取的总收入。","经济中所有企业和商行的总利润，或经济中所有家庭对商品和服务的总消费。","经济中每个人的总收入，或对经济中商品和服务产出的总支出。"]},"topics":["gdp-accounting"]},{"num":7,"type":"mc","question":"In the circular flow model, the flow of dollars from firms to households is paid _____, and the flow of dollars from households to firms is paid _____.","options":["as wages, capital income, and profits; for goods and services","for value added; as imputed values","in current dollars; in constant dollars","as interest and dividends; for depreciation and taxes"],"answer":"A","images":null,"translation":{"question":"在循环流动模型中，从企业流向家庭的货币流支付的是 ______，从家庭流向企业的货币流支付的是 ______。","options":["工资、资本收入和利润；用于商品和服务","增加值；作为估算值","以现价美元；以不变价美元","作为利息和股息；用于折旧和税收"]},"topics":["gdp-accounting"]},{"num":8,"type":"mc","question":"Which of the following is a flow variable?","options":["wealth","the number unemployed","government debt","income"],"answer":"D","images":null,"translation":{"question":"以下哪项是流量变量？","options":["财富","失业人数","政府债务","收入"]},"topics":["gdp-accounting"]},{"num":9,"type":"mc","question":"Which of the following is a stock variable?","options":["wealth","consumption","investment","income"],"answer":"A","images":null,"translation":{"question":"以下哪项是存量变量？","options":["财富","消费","投资","收入"]},"topics":["gdp-accounting"]},{"num":10,"type":"mc","question":"All of the following are stocks variables except:","options":["a consumer's wealth.","the government budget deficit.","the number of unemployed people.","the amount of capital in the economy."],"answer":"B","images":null,"translation":{"question":"以下都是存量变量，除了：","options":["消费者的财富。","政府预算赤字。","失业人数。","经济中的资本数量。"]},"topics":["gdp-accounting"]},{"num":11,"type":"mc","question":"All of the following are flows variables except:","options":["the number of new automobile purchases.","the number of people losing their jobs.","business expenditures on plant and equipment.","the government debt."],"answer":"D","images":null,"translation":{"question":"以下都是流量变量，除了：","options":["新购汽车的数量。","失去工作的人数。","企业在厂房设备上的支出。","政府债务。"]},"topics":["gdp-accounting"]},{"num":12,"type":"mc","question":"The amount of capital in an economy is a(n) ______, and the amount of investment is a(n) ______.","options":["flow; stock","stock; flow","final good; intermediate good","intermediate good; final good"],"answer":"B","images":null,"translation":{"question":"一个经济中的资本数量是 ______，投资数量是 ______。","options":["流量；存量","存量；流量","最终产品；中间产品","中间产品；最终产品"]},"topics":["gdp-accounting"]},{"num":13,"type":"mc","question":"The market value of all final goods and services produced within an economy in a given period of time is called:","options":["industrial production.","gross domestic product.","the GDP deflator.","general durable purchases."],"answer":"B","images":null,"translation":{"question":"在一个给定时期内，一个经济内生产的所有最终商品和服务的市场价值被称为：","options":["工业生产。","国内生产总值。","GDP平减指数。","一般耐用品购买。"]},"topics":["gdp-accounting"]},{"num":14,"type":"mc","question":"GDP is the market value of all ______ goods and services produced within an economy in a given period of time.","options":["used","intermediate","consumer","final"],"answer":"D","images":null,"translation":{"question":"GDP 是在一个给定时期内，一个经济内生产的所有 ______ 商品和服务的市场价值。","options":["二手的","中间的","消费的","最终的"]},"topics":["gdp-accounting"]},{"num":15,"type":"mc","question":"Assume that total output consists of 4 apples and 6 oranges and that apples cost $1 each and oranges cost $0.50 each. In this case, the value of GDP is:","options":["10 pieces of fruit.","$7.","$8.","$10."],"answer":"B","images":null,"translation":{"question":"假设总产出包括 4 个苹果和 6 个橙子，苹果每个 1 美元，橙子每个 0.50 美元。在这种情况下，GDP 的值为：","options":["10 个水果。","7 美元。","8 美元。","10 美元。"]},"topics":["gdp-accounting"]},{"num":16,"type":"mc","question":"All of the following transactions that took place in 2009 would be included in GDP for 2009 except the purchase of a:","options":["book titled The Year 3000 that was printed in 2009.","2001 Jeep Cherokee.","year 2010 calendar printed in 2009.","ticket to see the movie 2001."],"answer":"B","images":null,"translation":{"question":"以下 2009 年发生的交易中，除了一项外都会被计入 2009 年的 GDP，那项是购买：","options":["一本 2009 年印刷的、书名为《公元3000年》的书。","一辆 2001 年的吉普切诺基。","一本 2009 年印刷的 2010 年日历。","一张观看电影《2001》的电影票。"]},"topics":["gdp-accounting"]},{"num":17,"type":"mc","question":"When a firm sells a product out of inventory, GDP:","options":["increases.","decreases.","is not changed.","increases or decreases, depending on the year the product was produced."],"answer":"C","images":null,"translation":{"question":"当一家企业出售存货中的产品时，GDP：","options":["增加。","减少。","不变。","或增或减，取决于产品生产的年份。"]},"topics":["gdp-accounting"]},{"num":18,"type":"mc","question":"When a firm sells a product out of inventory, investment expenditures ______, and consumption expenditures ______.","options":["increase; decrease","decrease; increase","decrease; remain unchanged","remain unchanged; increase"],"answer":"B","images":null,"translation":{"question":"当一家企业出售存货中的产品时，投资支出 ______，消费支出 ______。","options":["增加；减少","减少；增加","减少；不变","不变；增加"]},"topics":["gdp-accounting"]},{"num":19,"type":"mc","question":"Assume that a bakery hires more workers and pays them wages and that the workers produce more bread. GDP increases in all of the following cases except when the bread:","options":["is sold to households.","is stored away for later sale.","grows stale and is thrown away.","is sold to other firms."],"answer":"C","images":null,"translation":{"question":"假设一家面包店雇佣更多工人并支付工资，工人生产了更多面包。GDP 在以下所有情况下都会增加，除了当面包：","options":["出售给家庭时。","被储存起来留待以后出售时。","变质而被扔掉时。","出售给其他企业时。"]},"topics":["gdp-accounting"]},{"num":20,"type":"mc","question":"When bread is baked but put away for later sale, this is called:","options":["waste.","saving.","fixed investment.","investment in inventory."],"answer":"D","images":null,"translation":{"question":"当面包被烤好但存放起来留待以后出售时，这被称为：","options":["浪费。","储蓄。","固定投资。","存货投资。"]},"topics":["gdp-accounting"]},{"num":21,"type":"mc","question":"Assume that a rancher sells McDonald's a quarter-pound of meat for $1 and that McDonald's sells you a hamburger made from that meat for $2. In this case, GDP increases by:","options":["$0.50.","$1.","$2.","$3."],"answer":"C","images":null,"translation":{"question":"假设一位牧场主以 1 美元把四分之一磅肉卖给麦当劳，麦当劳用这块肉做成汉堡以 2 美元卖给你。在这种情况下，GDP 增加：","options":["0.50 美元。","1 美元。","2 美元。","3 美元。"]},"topics":["gdp-accounting"]},{"num":22,"type":"mc","question":"Assume that a tire company sells four tires to an automobile company for $400, another company sells a compact disc player for $500, and the automobile company puts all of these items in or on a car that it sells for $20,000. In this case, the amount from these transactions that should be counted in GDP is:","options":["$20,000.","$20,000 less the automobile company's profit on the car.","$20,900.","$20,900 less the profits of all three companies on the items that they sold."],"answer":"A","images":null,"translation":{"question":"假设一家轮胎公司以 400 美元把四个轮胎卖给一家汽车公司，另一家公司以 500 美元出售一台 CD 播放器，汽车公司把这些东西都装进一辆以 20,000 美元出售的汽车里。在这种情况下，这些交易中应计入 GDP 的金额是：","options":["20,000 美元。","20,000 美元减去汽车公司在汽车上的利润。","20,900 美元。","20,900 美元减去三家公司在其所售商品上的利润。"]},"topics":["gdp-accounting"]},{"num":23,"type":"mc","question":"The value added of an item produced refers to:","options":["a firm's profits on the item sold.","the value of the labor inputs in the production of an item.","the value of a firm's output less the value of its costs.","the value of a firm's output less the value of the intermediate goods that the firm purchases."],"answer":"D","images":null,"translation":{"question":"一件所生产商品的增加值指的是：","options":["企业在该商品出售上的利润。","生产该商品中劳动投入的价值。","企业产出的价值减去其成本的价值。","企业产出的价值减去企业购买的中间商品的价值。"]},"topics":["gdp-accounting"]},{"num":24,"type":"mc","question":"Assume that a firm buys all the parts that it puts into an automobile for $10,000, pays its workers $10,000 to fabricate the automobile, and sells the automobile for $22,000. In this case, the value added by the automobile company is:","options":["$10,000.","$12,000.","$20,000.","$22,000."],"answer":"B","images":null,"translation":{"question":"假设一家企业以 10,000 美元购买装进汽车的所有零部件，支付工人 10,000 美元来组装汽车，并以 22,000 美元出售汽车。在这种情况下，该汽车公司的增加值是：","options":["10,000 美元。","12,000 美元。","20,000 美元。","22,000 美元。"]},"topics":["gdp-accounting"]},{"num":25,"type":"mc","question":"In computing GDP:","options":["expenditures on used goods are included.","production added to inventories is excluded.","the amount of production in the underground economy is imputed.","the value of intermediate goods is included in the market price of the final goods."],"answer":"D","images":null,"translation":{"question":"在计算 GDP 时：","options":["二手商品的支出被计入。","增加到存货中的产出被排除在外。","地下经济中的产出量被估算计入。","中间商品的价值包含在最终商品的市场价格中。"]},"topics":["gdp-accounting"]},{"num":26,"type":"mc","question":"To avoid double counting in the computation of GDP, GDP includes only the value of ______ goods.","options":["final","used","intermediate","investment"],"answer":"A","images":null,"translation":{"question":"为避免 GDP 计算中的重复计算，GDP 只计入 ______ 商品的价值。","options":["最终","二手","中间","投资"]},"topics":["gdp-accounting"]},{"num":27,"type":"mc","question":"An example of an imputed value in the GDP is the:","options":["value added of meals cooked at home.","housing services enjoyed by homeowners.","rental services of automobiles to their owners.","value of illegal drugs sold."],"answer":"B","images":null,"translation":{"question":"GDP 中一个估算价值的例子是：","options":["在家做饭的餐食的增加值。","房主享有的住房服务。","汽车对其车主的租赁服务。","非法毒品的价值。"]},"topics":["gdp-accounting"]},{"num":28,"type":"mc","question":"In principle, the GDP accounts should—but do not—have an imputation for:","options":["housing services enjoyed by homeowners.","rental services of automobiles driven by owners.","meals cooked in restaurants.","housing services enjoyed by renters."],"answer":"B","images":null,"translation":{"question":"原则上，GDP 核算应当——但并没有——对以下哪项进行估算：","options":["房主享有的住房服务。","车主驾驶汽车的服务。","餐馆烹制的餐食。","租户享有的住房服务。"]},"topics":["gdp-accounting"]},{"num":29,"type":"mc","question":"The underground economy:","options":["is included in the latest GDP accounts.","includes only illegal activities.","includes domestic workers for whom Social Security tax is not collected.","excludes the illegal drug trade."],"answer":"C","images":null,"translation":{"question":"地下经济：","options":["被包括在最新的 GDP 核算中。","只包括非法活动。","包括未征收社会保障税的家政工人。","不包括非法毒品交易。"]},"topics":["gdp-accounting"]},{"num":30,"type":"mc","question":"Nominal GDP means the value of goods and services is measured in ______ prices.","options":["current","real","constant","average"],"answer":"A","images":null,"translation":{"question":"名义 GDP 意味着商品和服务的价值是按 ______ 价格衡量的。","options":["现行","实际","不变","平均"]},"topics":["gdp-accounting"]},{"num":31,"type":"mc","question":"Real GDP means the value of goods and services is measured in ______ prices.","options":["current","actual","constant","average"],"answer":"C","images":null,"translation":{"question":"实际 GDP 意味着商品和服务的价值是按 ______ 价格衡量的。","options":["现行","实际","不变","平均"]},"topics":["gdp-accounting"]},{"num":32,"type":"mc","question":"Assume that apples cost $0.50 in 2002 and $1 in 2009, whereas oranges cost $1 in 2002 and $1.50 in 2009. If 4 apples were produced in 2002 and 5 in 2009, whereas 3 oranges were produced in 2002 and 4 in 2009, then real GDP (in 2002 prices) in 2009 was:","options":["$5.","$6.50.","$9.50.","$11."],"answer":"B","images":null,"translation":{"question":"假设苹果在 2002 年价格为 0.50 美元、2009 年为 1 美元，而橙子在 2002 年为 1 美元、2009 年为 1.50 美元。如果 2002 年生产了 4 个苹果、2009 年生产了 5 个，而 2002 年生产了 3 个橙子、2009 年生产了 4 个，那么 2009 年的实际 GDP（按 2002 年价格计算）为：","options":["5 美元。","6.50 美元。","9.50 美元。","11 美元。"]},"topics":["gdp-accounting"]},{"num":33,"type":"mc","question":"If nominal GDP in 2009 equals $14 trillion and real GDP in 2009 equals $11 trillion, what is the value of the GDP deflator?","options":["0.79","1.03","1.27","3.2"],"answer":"C","images":null,"translation":{"question":"如果 2009 年名义 GDP 为 14 万亿美元，实际 GDP 为 11 万亿美元，那么 GDP 平减指数的值是多少？","options":["0.79","1.03","1.27","3.2"]},"topics":["gdp-accounting"]},{"num":34,"type":"mc","question":"If the GDP deflator in 2009 equals 1.25 and nominal GDP in 2009 equals $15 trillion, what is the value of real GDP in 2009?","options":["$12 trillion","$12.5 trillion","$15 trillion","$18.75 trillion"],"answer":"A","images":null,"translation":{"question":"如果 2009 年 GDP 平减指数为 1.25，名义 GDP 为 15 万亿美元，那么 2009 年实际 GDP 的值是多少？","options":["12 万亿美元","12.5 万亿美元","15 万亿美元","18.75 万亿美元"]},"topics":["gdp-accounting"]},{"num":35,"type":"mc","question":"The GDP deflator is equal to:","options":["the ratio of nominal GDP to real GDP.","the ratio of real GDP to nominal GDP.","real GDP minus national GDP.","nominal GDP minus real GDP."],"answer":"A","images":null,"translation":{"question":"GDP 平减指数等于：","options":["名义 GDP 与实际 GDP 之比。","实际 GDP 与名义 GDP 之比。","实际 GDP 减去国民 GDP。","名义 GDP 减去实际 GDP。"]},"topics":["gdp-accounting"]},{"num":36,"type":"mc","question":"Assume that apples cost $0.50 in 2002 and $1 in 2009, whereas oranges cost $1 in 2002 and $1.50 in 2009. If 4 apples were produced in 2002 and 5 in 2009, whereas 3 oranges were produced in 2002 and 5 in 2009, then the GDP deflator in 2009, using a base year of 2002, was approximately:","options":["1.5.","1.7.","1.9.","2.0."],"answer":"B","images":null,"translation":{"question":"假设苹果在 2002 年为 0.50 美元、2009 年为 1 美元，橙子在 2002 年为 1 美元、2009 年为 1.50 美元。如果 2002 年生产 4 个苹果、2009 年生产 5 个，2002 年生产 3 个橙子、2009 年生产 5 个，那么以 2002 年为基年，2009 年的 GDP 平减指数约为：","options":["1.5。","1.7。","1.9。","2.0。"]},"topics":["gdp-accounting"]},{"num":37,"type":"mc","question":"If nominal GDP grew by 5 percent and real GDP grew by 3 percent, then the GDP deflator grew by approximately ______ percent.","options":["2","3","5","8"],"answer":"A","images":null,"translation":{"question":"如果名义 GDP 增长 5%，实际 GDP 增长 3%，那么 GDP 平减指数大约增长 ______%。","options":["2","3","5","8"]},"topics":["gdp-accounting"]},{"num":38,"type":"mc","question":"If nominal GDP increased by 5 percent and the GDP deflator increased by 3 percent, then real GDP ______ by ______ percent.","options":["increased; 2","decreased; 2","increased; 8","decreased; 8"],"answer":"A","images":null,"translation":{"question":"如果名义 GDP 增长 5%，GDP 平减指数增长 3%，那么实际 GDP ______ ______%。","options":["增长；2","下降；2","增长；8","下降；8"]},"topics":["gdp-accounting"]},{"num":39,"type":"mc","question":"Real GDP is a better measure of economic well-being than nominal GDP because real GDP:","options":["excludes the value of goods and services exported abroad.","includes the value of government transfer payments.","measures changes in the quantity of goods and services produced by holding prices constant.","adjusts the value of goods and services produced for changes in the foreign exchange rate."],"answer":"C","images":null,"translation":{"question":"实际 GDP 比名义 GDP 更能衡量经济福利，因为实际 GDP：","options":["排除了出口到国外的商品和服务的价值。","包括了政府转移支付的价值。","通过保持价格不变来衡量所生产商品和服务数量的变化。","根据汇率变化调整所生产商品和服务的价值。"]},"topics":["gdp-accounting"]},{"num":40,"type":"mc","question":"Chain-weighted measures of real GDP make use of prices from:","options":["an unchanging base year.","a continuously changing base year.","a base year that is changed approximately every 5 years.","a base year that is changed approximately every 10 years."],"answer":"B","images":null,"translation":{"question":"实际 GDP 的链式加权衡量使用的是来自以下哪项的价格：","options":["一个不变的基年。","一个不断变化的基年。","一个大约每 5 年更换一次的基年。","一个大约每 10 年更换一次的基年。"]},"topics":["gdp-accounting"]},{"num":41,"type":"mc","question":"The national income accounts identity for an open economy is:","options":["Y = C + I + G ?NX.","Y = C + I + G + NX.","Y = C + I + G.","Y = C + I ?G."],"answer":"B","images":null,"translation":{"question":"开放经济下的国民收入核算恒等式是：","options":["Y = C + I + G − NX。","Y = C + I + G + NX。","Y = C + I + G。","Y = C + I − G。"]},"topics":["gdp-accounting"]},{"num":42,"type":"mc","question":"If GDP measured in billions of current dollars is $5,465, consumption is $3,657, investment is $741, and government purchases are $1,098, then net exports are:","options":["$131.","?131.","$31.","?31."],"answer":"D","images":null,"translation":{"question":"如果以十亿现价美元衡量的 GDP 为 5,465 美元，消费为 3,657 美元，投资为 741 美元，政府购买为 1,098 美元，那么净出口为：","options":["131 美元。","−131 美元。","31 美元。","−31 美元。"]},"topics":["gdp-accounting"]},{"num":43,"type":"mc","question":"If GDP measured in billions of current dollars is $5,465, consumption is $3,657, investment is $741, and net exports are ?1,910, then government purchases are:","options":["$2,977.","$1,910.","?843.","$1,067."],"answer":"A","images":null,"translation":{"question":"如果以十亿现价美元衡量的 GDP 为 5,465 美元，消费为 3,657 美元，投资为 741 美元，净出口为 −1,910 美元，那么政府购买为：","options":["2,977 美元。","1,910 美元。","−843 美元。","1,067 美元。"]},"topics":["gdp-accounting"]},{"num":44,"type":"mc","question":"If real GDP grew by 6 percent and population grew by 2 percent, then real GDP per person grew by approximately ______ percent.","options":["2","3","4","8"],"answer":"C","images":null,"translation":{"question":"如果实际 GDP 增长 6%，人口增长 2%，那么人均实际 GDP 大约增长 ______%。","options":["2","3","4","8"]},"topics":["gdp-accounting"]},{"num":45,"type":"mc","question":"In the national income accounts, consumption expenditures include all of the following except household purchases of:","options":["durable goods.","nondurable goods.","new residential housing.","services."],"answer":"C","images":null,"translation":{"question":"在国民收入核算中，消费支出包括以下所有各项，除了家庭购买：","options":["耐用消费品。","非耐用消费品。","新建住宅。","服务。"]},"topics":["gdp-accounting"]},{"num":46,"type":"mc","question":"In the national income accounts, the purchases of durables, nondurables, and services by households are classified as:","options":["consumption.","investment.","government purchases.","net exports."],"answer":"A","images":null,"translation":{"question":"在国民收入核算中，家庭对耐用消费品、非耐用消费品和服务的购买被归类为：","options":["消费。","投资。","政府购买。","净出口。"]},"topics":["gdp-accounting"]},{"num":47,"type":"mc","question":"In the national income accounts, goods bought for future use are classified as which type of expenditure?","options":["services","investment","government purchases","net exports"],"answer":"B","images":null,"translation":{"question":"在国民收入核算中，为将来使用而购买的商品被归类为哪种支出？","options":["服务","投资","政府购买","净出口"]},"topics":["gdp-accounting"]},{"num":48,"type":"mc","question":"If total investment measured in billions of current dollars equals $741, business fixed investment is $524, and residential fixed investment is $222, then inventory investment is:","options":["$5.","?5.","$15.","?15."],"answer":"B","images":null,"translation":{"question":"如果以十亿现价美元衡量的总投资为 741 美元，企业固定投资为 524 美元，住宅固定投资为 222 美元，那么存货投资为：","options":["5 美元。","−5 美元。","15 美元。","−15 美元。"]},"topics":["gdp-accounting"]},{"num":49,"type":"mc","question":"In the national income accounts, all of the following are classified as government purchases except:","options":["payments made to Social Security recipients.","services provided by police officers.","purchases of military hardware.","services provided by U.S. senators."],"answer":"A","images":null,"translation":{"question":"在国民收入核算中，以下都被归类为政府购买，除了：","options":["支付给社会保障领取者的款项。","警察提供的服务。","购买军事装备。","美国参议员提供的服务。"]},"topics":["gdp-accounting"]},{"num":50,"type":"mc","question":"In the national income accounts, government purchases are goods and services purchased by:","options":["the federal government.","the federal and state governments.","the state and local governments.","the federal, state, and local governments."],"answer":"D","images":null,"translation":{"question":"在国民收入核算中，政府购买是由以下哪项购买的商品和服务：","options":["联邦政府。","联邦政府和州政府。","州政府和地方政府。","联邦政府、州政府和地方政府。"]},"topics":["gdp-accounting"]},{"num":51,"type":"mc","question":"In the national income accounts, net exports equal:","options":["exported goods minus imported goods.","exported goods and services minus imported goods and services.","exported goods minus imported services.","exported goods and services plus imported goods and services."],"answer":"B","images":null,"translation":{"question":"在国民收入核算中，净出口等于：","options":["出口商品减去进口商品。","出口商品和服务减去进口商品和服务。","出口商品减去进口服务。","出口商品和服务加上进口商品和服务。"]},"topics":["gdp-accounting"]},{"num":52,"type":"mc","question":"If GDP measured in billions of current dollars is $5,465 and the sum of consumption, investment, and government purchases is $5,496, while exports equal $673, imports are:","options":["$673.","?673.","$704.","?704."],"answer":"C","images":null,"translation":{"question":"如果以十亿现价美元衡量的 GDP 为 5,465 美元，消费、投资和政府购买之和为 5,496 美元，而出口为 673 美元，那么进口为：","options":["673 美元。","−673 美元。","704 美元。","−704 美元。"]},"topics":["gdp-accounting"]},{"num":53,"type":"mc","question":"All of the following actions are investments in the sense of the term used by macroeconomists except:","options":["Apple's building a new factory.","a corner candy store's buying a new computer.","John Smith's buying a newly constructed home.","Sandra Santiago's buying 100 shares of Apple stock."],"answer":"D","images":null,"translation":{"question":"以下行为在宏观经济学家所用术语的意义上都是投资，除了：","options":["苹果公司建造一座新工厂。","街角糖果店购买一台新电脑。","约翰·史密斯购买一套新建的住房。","桑德拉·圣地亚哥购买 100 股苹果公司股票。"]},"topics":["gdp-accounting"]},{"num":54,"type":"mc","question":"In 2013, the GDP of the United States totaled about:","options":["$16.8 billion.","$168 billion.","$16.8 trillion.","$168 trillion."],"answer":"C","images":null,"translation":{"question":"2013 年，美国 GDP 总计约为：","options":["168 亿美元。","1,680 亿美元。","16.8 万亿美元。","168 万亿美元。"]},"topics":["gdp-accounting"]},{"num":55,"type":"mc","question":"GNP equals GDP ______ income earned domestically by foreigners ______ income that nationals earn abroad.","options":["plus; plus","minus; minus","minus; plus","plus; minus"],"answer":"C","images":null,"translation":{"question":"GNP 等于 GDP ______ 外国人在国内赚取的收入 ______ 本国国民在国外赚取的收入。","options":["加上；加上","减去；减去","减去；加上","加上；减去"]},"topics":["gdp-accounting"]},{"num":56,"type":"mc","question":"Net national product equals GNP:","options":["plus net investment.","minus net investment.","plus depreciation.","minus depreciation."],"answer":"D","images":null,"translation":{"question":"国民生产净值等于 GNP：","options":["加上净投资。","减去净投资。","加上折旧。","减去折旧。"]},"topics":["gdp-accounting"]},{"num":57,"type":"mc","question":"National income differs from net national product by an amount called:","options":["depreciation.","indirect business taxes.","statistical discrepancy.","net foreign factor income payments."],"answer":"C","images":null,"translation":{"question":"国民收入与国民生产净值相差一个被称为以下哪项的数量：","options":["折旧。","间接企业税。","统计误差。","净外国要素收入支付。"]},"topics":["gdp-accounting"]},{"num":58,"type":"mc","question":"The largest component of national income is:","options":["corporate profits.","compensation of employees.","proprietors' income.","net interest."],"answer":"B","images":null,"translation":{"question":"国民收入的最大组成部分是：","options":["公司利润。","雇员报酬。","业主收入。","净利息。"]},"topics":["gdp-accounting"]},{"num":59,"type":"mc","question":"Disposable personal income:","options":["is computed by subtracting personal tax from personal income.","is generally greater than personal income.","includes corporate profits but not dividends.","does not include government transfers to individuals."],"answer":"A","images":null,"translation":{"question":"个人可支配收入：","options":["由个人收入减去个人所得税计算得出。","通常大于个人收入。","包括公司利润但不包括股息。","不包括政府对个人的转移支付。"]},"topics":["gdp-accounting"]},{"num":60,"type":"mc","question":"According to the usual seasonal pattern of the U.S. economy, GDP is highest in the quarter of the year that includes:","options":["January, February, and March.","April, May, and June.","July, August, and September.","October, November, and December."],"answer":"D","images":null,"translation":{"question":"根据美国经济通常的季节性模式，GDP 最高出现在包括以下哪几个月的季度：","options":["1月、2月和3月。","4月、5月和6月。","7月、8月和9月。","10月、11月和12月。"]},"topics":["gdp-accounting"]},{"num":61,"type":"mc","question":"The CPI is determined by computing:","options":["an average of prices of all goods and services.","the price of a basket of goods and services that changes every year, relative to the same basket in a base year.","the price of a fixed basket of goods and services, relative to the price of the same basket in a base year.","nominal GDP relative to real GDP."],"answer":"C","images":null,"translation":{"question":"CPI 是通过计算以下哪项来确定的：","options":["所有商品和服务价格的平均值。","每年都变化的一篮子商品和服务的价格，相对于基年中同一篮子的价格。","固定一篮子商品和服务的价格，相对于基年中同一篮子的价格。","名义 GDP 相对于实际 GDP。"]},"topics":["cpi-inflation"]},{"num":62,"type":"mc","question":"Prices of items included in the CPI are:","options":["averaged, with the price of every item weighted equally.","weighted according to the amount of the item produced in GDP.","weighted according to the quantity of the item purchased by the typical household.","chained to the base year by the year-to-year growth rate of the item."],"answer":"C","images":null,"translation":{"question":"CPI 中所包含项目的价格是：","options":["进行平均的，每个项目的价格被等权处理。","按照该项目在 GDP 中生产的数量加权。","按照典型家庭购买该项目的数量加权。","通过该项目逐年增长率链接到基年。"]},"topics":["cpi-inflation"]},{"num":63,"type":"mc","question":"The core inflation rate:","options":["measures the change in producer prices.","is measured using a Paasche index.","excludes food and energy prices.","includes the price of exports and includes the price of imports."],"answer":"C","images":null,"translation":{"question":"核心通胀率：","options":["衡量生产者价格的变化。","使用帕氏指数来衡量。","排除食品和能源价格。","包括出口价格和进口价格。"]},"topics":["cpi-inflation"]},{"num":64,"type":"mc","question":"Measuring the rate of inflation using a market basket that excludes food and energy prices is preferred by some analysts because this measure, called core inflation,","options":["provides a real, rather than a nominal, rate of inflation.","gives a better measure of ongoing, sustained price changes.","is more consistent with measures of inflation used in other countries.","fluctuates more than measures of inflation that include food and energy prices."],"answer":"B","images":null,"translation":{"question":"一些分析人士偏好使用排除食品和能源价格的市场篮子来衡量通胀率，因为这种被称为核心通胀的指标：","options":["提供的是实际而非名义通胀率。","能更好地衡量持续进行的价格变化。","与其他国家使用的通胀衡量指标更一致。","比包括食品和能源价格的通胀指标波动更大。"]},"topics":["cpi-inflation"]},{"num":65,"type":"mc","question":"An increase in the price of goods bought by firms and the government will show up in:","options":["the CPI but not in the GDP deflator.","the GDP deflator but not in the CPI.","both the CPI and the GDP deflator.","neither the CPI nor the GDP deflator."],"answer":"B","images":null,"translation":{"question":"企业和政府所购买商品价格的上涨会体现在：","options":["CPI 中，但不在 GDP 平减指数中。","GDP 平减指数中，但不在 CPI 中。","CPI 和 GDP 平减指数中都有。","CPI 和 GDP 平减指数中都没有。"]},"topics":["cpi-inflation"]},{"num":66,"type":"mc","question":"An increase in the price of imported goods will show up in:","options":["the CPI but not in the GDP deflator.","the GDP deflator but not in the CPI.","both the CPI and the GDP deflator.","neither the CPI nor the GDP deflator."],"answer":"A","images":null,"translation":{"question":"进口商品价格的上涨会体现在：","options":["CPI 中，但不在 GDP 平减指数中。","GDP 平减指数中，但不在 CPI 中。","CPI 和 GDP 平减指数中都有。","CPI 和 GDP 平减指数中都没有。"]},"topics":["cpi-inflation"]},{"num":67,"type":"mc","question":"Assume that the market basket of goods and services purchased in 2004 by the average family in the United States costs $14,000 in 2004 prices, whereas the same basket costs $21,000 in 2009 prices. However, the basket of goods and services actually purchased by the average family in 2009 costs $20,000 in 2009 prices, whereas this same basket would have cost $15,000 in 2004 prices. Given these data, a Laspeyres price index of 2009 prices using 2004 as the base year would be:","options":["1.05.","approximately 1.07.","approximately 1.33.","1.50."],"answer":"D","images":null,"translation":{"question":"假设 2004 年美国普通家庭购买的一篮子商品和服务按 2004 年价格计算为 14,000 美元，而同一篮子按 2009 年价格计算为 21,000 美元。但是，2009 年普通家庭实际购买的一篮子商品和服务按 2009 年价格计算为 20,000 美元，而同一篮子按 2004 年价格计算本应为 15,000 美元。根据这些数据，以 2004 年为基年的 2009 年拉斯佩尔价格指数将为：","options":["1.05。","约 1.07。","约 1.33。","1.50。"]},"topics":["cpi-inflation"]},{"num":68,"type":"mc","question":"Assume that the market basket of goods and services purchased in 2004 by the average family in the United States costs $14,000 in 2004 prices, whereas the same basket costs $21,000 in 2009 prices. However, the basket of goods and services actually purchased by the average family in 2009 costs $20,000 in 2009 prices, whereas this same basket would have cost $15,000 in 2004 prices. Given these data, a Paasche index for 2009 using 2004 prices would be:","options":["1.05.","approximately 1.07.","approximately 1.33.","1.50."],"answer":"B","images":null,"translation":{"question":"假设 2004 年美国普通家庭购买的一篮子商品和服务按 2004 年价格计算为 14,000 美元，而同一篮子按 2009 年价格计算为 21,000 美元。但是，2009 年普通家庭实际购买的一篮子商品和服务按 2009 年价格计算为 20,000 美元，而同一篮子按 2004 年价格计算本应为 15,000 美元。根据这些数据，以 2004 年为基年的 2009 年帕氏指数将为：","options":["1.05。","约 1.07。","约 1.33。","1.50。"]},"topics":["cpi-inflation"]},{"num":69,"type":"mc","question":"The CPI is a:","options":["Laspeyres price index.","Paasche price index.","Laspeyres quantity index.","Paasche quantity index."],"answer":"A","images":null,"translation":{"question":"CPI 是一种：","options":["拉斯佩尔价格指数。","帕氏价格指数。","拉斯佩尔数量指数。","帕氏数量指数。"]},"topics":["cpi-inflation"]},{"num":70,"type":"mc","question":"The GDP deflator is a:","options":["Laspeyres price index.","Paasche price index.","Laspeyres quantity index.","Paasche quantity index."],"answer":"B","images":null,"translation":{"question":"GDP 平减指数是一种：","options":["拉斯佩尔价格指数。","帕氏价格指数。","拉斯佩尔数量指数。","帕氏数量指数。"]},"topics":["cpi-inflation"]},{"num":71,"type":"mc","question":"When prices of different goods are increasing by different amounts, the price index that will rise the fastest is:","options":["the PCE index.","the CPI.","the GDP deflator.","a Paasche index."],"answer":"B","images":null,"translation":{"question":"当不同商品的价格以不同幅度上涨时，上涨最快的价格指数是：","options":["PCE 指数。","CPI。","GDP 平减指数。","帕氏指数。"]},"topics":["cpi-inflation"]},{"num":72,"type":"mc","question":"The panel of economists appointed by the Senate Finance Committee estimated that the CPI ______ inflation by approximately ______ percentage point(s) per year.","options":["overestimates; 1","overestimates; 10","underestimates; 1","underestimates; 10"],"answer":"A","images":null,"translation":{"question":"由参议院财政委员会任命的经济学家小组估计，CPI 每年将通胀 ______ 大约 ______ 个百分点。","options":["高估；1","高估；10","低估；1","低估；10"]},"topics":["cpi-inflation"]},{"num":73,"type":"mc","question":"According to the definition used by the U.S. Bureau of Labor Statistics, a person is not in the labor force if that person:","options":["is going to school full time.","is temporarily absent from a job because of illness.","has been temporarily laid off.","is out of a job and was looking for work during the previous four weeks."],"answer":"A","images":null,"translation":{"question":"根据美国劳工统计局使用的定义，如果一个人符合以下哪种情况，就不属于劳动力：","options":["正在全日制上学。","因生病暂时缺勤。","被暂时解雇。","没有工作并在过去四周内正在找工作。"]},"topics":["unemployment-measure"]},{"num":74,"type":"mc","question":"According to the definition used by the U.S. Bureau of Labor Statistics, people are considered to be unemployed if they:","options":["are out of a job but not looking for work.","retired from the labor force before age 65.","do not have a job but have looked for work in the past four weeks.","are absent from work because of bad weather or illness."],"answer":"C","images":null,"translation":{"question":"根据美国劳工统计局使用的定义，如果人们符合以下哪种情况，就被视为失业：","options":["没有工作但不找工作。","在 65 岁之前退出劳动力队伍（退休）。","没有工作但在过去四周内找过工作。","因恶劣天气或生病而缺勤。"]},"topics":["unemployment-measure"]},{"num":75,"type":"mc","question":"The labor force equals the:","options":["adult population.","number of employed individuals.","number of unemployed individuals.","number of employed and unemployed individuals."],"answer":"D","images":null,"translation":{"question":"劳动力等于：","options":["成年人口。","就业人数。","失业人数。","就业人数与失业人数之和。"]},"topics":["unemployment-measure"]},{"num":76,"type":"mc","question":"If 7 million workers are unemployed, 143 million workers are employed, and the adult population equals 200 million, then the unemployment rate equals approximately ______ percent.","options":["3.5","4.7","4.9","7"],"answer":"B","images":null,"translation":{"question":"如果 700 万工人失业，1.43 亿工人就业，成年人口为 2 亿，那么失业率约为 ______%。","options":["3.5","4.7","4.9","7"]},"topics":["unemployment-measure"]},{"num":77,"type":"mc","question":"The labor-force participation rate is the percentage of the:","options":["adult population that is employed.","adult population that is in the labor force.","labor force that is employed.","labor force that is unemployed."],"answer":"B","images":null,"translation":{"question":"劳动力参与率是以下哪项所占的百分比：","options":["成年人口中就业的部分。","成年人口中处于劳动力队伍的部分。","劳动力中就业的部分。","劳动力中失业的部分。"]},"topics":["unemployment-measure"]},{"num":78,"type":"mc","question":"If the unemployment rate is 6 percent and the number of employed is 188 million, then the labor force equals ______ million.","options":["11.28","176.72","188","200"],"answer":"D","images":null,"translation":{"question":"如果失业率为 6%，就业人数为 1.88 亿，那么劳动力等于 ______ 百万。","options":["11.28","176.72","188","200"]},"topics":["unemployment-measure"]},{"num":79,"type":"mc","question":"If an increasing proportion of the adult population is retired, then the labor-force participation rate:","options":["will increase.","will decrease.","will remain constant.","may increase, decrease, or remain constant."],"answer":"B","images":null,"translation":{"question":"如果成年人口中退休的比例不断上升，那么劳动力参与率：","options":["将上升。","将下降。","将保持不变。","可能上升、下降或保持不变。"]},"topics":["unemployment-measure"]},{"num":80,"type":"mc","question":"If the adult population equals 250 million, of which 145 million are employed and 5 million are unemployed, the labor-force participation rate equals ______ percent.","options":["50","58","60","67"],"answer":"C","images":null,"translation":{"question":"如果成年人口为 2.5 亿，其中 1.45 亿人就业、500 万人失业，那么劳动力参与率等于 ______%。","options":["50","58","60","67"]},"topics":["unemployment-measure"]},{"num":81,"type":"mc","question":"If the number of employed increases while the number of unemployed does not change, the unemployment rate:","options":["will increase.","will decrease.","will not change.","may either increase or decrease."],"answer":"B","images":null,"translation":{"question":"如果就业人数增加而失业人数不变，那么失业率：","options":["将上升。","将下降。","将不变。","可能上升或下降。"]},"topics":["unemployment-measure"]},{"num":82,"type":"mc","question":"In the United States since the end of World War II:","options":["the labor-force participation rates of both men and women have increased.","the labor-force participation rates of both men and women have decreased.","the labor-force participation rate of men has increased, while the labor-force participation rate of women has decreased.","the labor-force participation rate of men has decreased, while the labor-force participation rate of women has increased."],"answer":"D","images":null,"translation":{"question":"自第二次世界大战结束以来，美国：","options":["男性和女性的劳动力参与率都上升了。","男性和女性的劳动力参与率都下降了。","男性的劳动力参与率上升，而女性的劳动力参与率下降。","男性的劳动力参与率下降，而女性的劳动力参与率上升。"]},"topics":["unemployment-measure"]},{"num":83,"type":"mc","question":"The household survey conducted by the Bureau of Labor Statistics provides estimates of the number of workers ______, while the establishment survey provides estimates of the number of workers ______.","options":["self-employed; unemployed","unemployed; self-employed","with jobs; on firms' payrolls","on firms' payrolls; with jobs"],"answer":"C","images":null,"translation":{"question":"劳工统计局进行的住户调查提供的是 ______ 工人数量的估计，而机构调查提供的是 ______ 工人数量的估计。","options":["自雇的；失业的","失业的；自雇的","有工作的；在企业工资单上的","在企业工资单上的；有工作的"]},"topics":["unemployment-measure"]},{"num":84,"type":"mc","question":"The employment statistics computed from the establishment survey do not include:","options":["workers with two jobs.","those who are self-employed.","workers on firms' payrolls.","part-time workers on firms' payrolls."],"answer":"B","images":null,"translation":{"question":"根据机构调查计算的就业统计不包括：","options":["有两份工作的工人。","自雇者。","在企业工资单上的工人。","在企业工资单上的兼职工人。"]},"topics":["unemployment-measure"]},{"num":85,"type":"mc","question":"A worker with two jobs is counted:","options":["once in both the household and the establishment surveys.","once in the household survey but twice in the establishment survey.","once in the establishment survey but twice in the household survey.","twice in both the household survey and the establishment survey."],"answer":"B","images":null,"translation":{"question":"一位有两份工作的工人被计入：","options":["住户调查和机构调查中各计一次。","住户调查中计一次，但机构调查中计两次。","机构调查中计一次，但住户调查中计两次。","住户调查和机构调查中各计两次。"]},"topics":["unemployment-measure"]},{"num":86,"type":"mc","question":"An estimate of the number of unemployed workers in the economy can be obtained from:","options":["both the household survey and the establishment survey.","the household survey but not from the establishment survey.","the establishment survey but not from the household survey.","neither the household survey nor the establishment survey."],"answer":"B","images":null,"translation":{"question":"经济中失业工人数量的估计可以从以下哪项获得：","options":["住户调查和机构调查都可以。","住户调查可以，但机构调查不行。","机构调查可以，但住户调查不行。","住户调查和机构调查都不行。"]},"topics":["unemployment-measure"]},{"num":87,"type":"mc","question":"Economists can calculate the U.S. unemployment rate by using:","options":["both the household survey and the establishment survey.","the household survey but not the establishment survey.","the establishment survey but not the household survey.","neither the household survey nor the establishment survey."],"answer":"A","images":null,"translation":{"question":"经济学家可以利用以下哪项计算美国失业率：","options":["住户调查和机构调查都可以。","住户调查可以，但机构调查不行。","机构调查可以，但住户调查不行。","住户调查和机构调查都不行。"]},"topics":["unemployment-measure"]},{"num":88,"type":"mc","question":"A farmer grows wheat and sells it to a miller for $1; the miller turns the wheat into flour and sells it to a baker for $3; the baker uses the flour to make bread and sells the bread for $6. The value added by the miller is:","options":["$1.","$2.","$3.","$6."],"answer":"B","images":null,"translation":{"question":"一位农民种植小麦并以 1 美元卖给磨坊主；磨坊主把小麦磨成面粉并以 3 美元卖给面包师；面包师用面粉制作面包并以 6 美元出售。磨坊主创造的增加值是：","options":["1 美元。","2 美元。","3 美元。","6 美元。"]},"topics":["gdp-accounting"]},{"num":89,"type":"mc","question":"A woman marries her butler. Before they were married, she paid him $60,000 per year. He continues to wait on her as before (but as a husband rather than as a wage earner). She earns $1,000,000 per year both before and after her marriage. The marriage:","options":["does not change GDP.","decreases GDP by $60,000.","increases GDP by $60,000.","increases GDP by more than $60,000."],"answer":"B","images":null,"translation":{"question":"一位女士嫁给了她的管家。结婚前，她每年付给他 60,000 美元。婚后他仍像以前一样服侍她（但身份是丈夫而不是挣工资者）。她结婚前后每年都赚 1,000,000 美元。这段婚姻：","options":["不改变 GDP。","使 GDP 减少 60,000 美元。","使 GDP 增加 60,000 美元。","使 GDP 增加超过 60,000 美元。"]},"topics":["gdp-accounting"]},{"num":90,"type":"mc","question":"A fixed-weight price index like the CPI ______ the change in the cost of living because it ______ take into account that people can substitute less expensive goods for ones that have become more expensive.","options":["underestimates; does not","overestimates; does","accurately estimates; does","overestimates; does not"],"answer":"D","images":null,"translation":{"question":"像 CPI 这样的固定权重价格指数 ______ 生活成本的变化，因为它 ______ 考虑到人们可以用较便宜的商品替代已变贵的商品。","options":["低估；没有","高估；有","准确估计；有","高估；没有"]},"topics":["cpi-inflation"]},{"num":91,"type":"sa","question":"Exhibit: Totals Recorded for United States In the exhibit above, what were GDP, consumption expenditures, investment expenditures, government purchases, and net exports?","options":null,"answer":null,"images":null,"translation":{"question":"展表：美国记录的总量。在上面的展表中，GDP、消费支出、投资支出、政府购买和净出口分别是多少？","options":null},"topics":["gdp-accounting"],"answer_ref":"GDP 按支出法等于 C+I+G+NX：从展表中分别读出消费支出、投资支出、政府购买、净出口四个分量，相加即得 GDP，并与表中 GDP 行核对（四者之和应等于 GDP）。"},{"num":92,"type":"sa","question":"Exhibit: Totals Recorded for United States In the exhibit above, what were net national product, national income, personal income, and disposable personal income?","options":null,"answer":null,"images":["c2_img0.png"],"translation":{"question":"展表：美国记录的总量。在上面的展表中，国民生产净值、国民收入、个人收入和个人可支配收入分别是多少？","options":null},"topics":["gdp-accounting"],"answer_ref":"自上而下逐级推导：国民生产净值 NNP = GDP − 折旧；国民收入 NI = NNP − 统计误差（间接税净额等）；个人收入 PI = NI − 公司未分配利润 − 社会保险税 − 净利息调整 + 政府对个人的转移支付；个人可支配收入 DPI = PI − 个人所得税。用展表中对应行的数值逐步计算。"},{"num":93,"type":"sa","question":"Exhibit: Totals Recorded for United States In the exhibit above, what were the approximate ratios of consumption, investment, and government purchases to GDP?","options":null,"answer":null,"images":["c2_img1.png"],"translation":{"question":"展表：美国记录的总量。在上面的展表中，消费、投资和政府购买占 GDP 的大致比例分别是多少？","options":null},"topics":["gdp-accounting"],"answer_ref":"用表中各项除以 GDP 即可。参照近年美国数据的大致比例：消费约占 GDP 的 65%–70%，投资约占 15%–18%，政府购买约占 17%–20%。"},{"num":94,"type":"sa","question":"Exhibit: Quantity Consumed and Price of Good Base YearLater Year*Price of good A100200*Quantity of good A100200*Price of good B100100*Quantity of good B100100*In the exhibit, the citizens of country XYZ come to desire more of good A. As a result, the quantity and price of the good both rise. a.Compute nominal GDP in the base year and later year.*b.Compute real GDP in the base year and later year.*c.Compute the GDP deflator in the later year, using your answers to parts (a) and (b).*d.Compute a fixed-weight price index for the later year, using the base-year quantities as weights.*e.Which price index rises faster, the GDP deflator (Paasche) index or the fixed-weight index (Laspeyres) index?*","options":null,"answer":null,"images":["c2_img2.png"],"translation":{"question":"展表：商品的消费量与价格（基年/后一年）。表格数据：商品 A 价格——基年 100、后一年 200；商品 A 数量——基年 100、后一年 200；商品 B 价格——基年 100、后一年 100；商品 B 数量——基年 100、后一年 100。在展表中，XYZ 国的公民开始渴望消费更多商品 A。结果，该商品的数量和价格都上升了。a. 计算基年和后一年的名义 GDP。b. 计算基年和后一年的实际 GDP。c. 利用你对 (a) 和 (b) 部分的答案，计算后一年的 GDP 平减指数。d. 以基年数量为权重，计算后一年的固定权重价格指数。e. 哪个价格指数上升得更快——GDP 平减指数（帕氏指数）还是固定权重指数（拉斯佩尔指数）？","options":null},"topics":["gdp-accounting","cpi-inflation"],"answer_ref":"a. 名义GDP：基年 = 100×100 + 100×100 = 20,000；后一年 = 200×200 + 100×100 = 50,000。b. 实际GDP（基年价格）：基年 = 20,000；后一年 = 100×200 + 100×100 = 30,000。c. 后一年 GDP 平减指数 = 50,000/30,000×100 ≈ 166.7。d. 固定权重指数（拉氏，基年数量为权）= (200×100 + 100×100)/(100×100 + 100×100) = 30,000/20,000×100 = 150。e. GDP 平减指数（帕氏）上升更快：它用当期数量加权，价格上涨最多的 A 商品当期数量大、权重高，而拉氏指数仍用基期数量加权。"},{"num":95,"type":"sa","question":"Assume that two countries have the same nominal GDP (measured in the same currency using the same accounting rules). Provide at least three reasons why you cannot assume that citizens in each country enjoy approximately the same level of economic well-being.","options":null,"answer":null,"images":null,"translation":{"question":"假设两个国家有相同的名义 GDP（用相同货币并按相同核算规则衡量）。给出至少三个理由，说明为什么你不能认为每个国家的公民享有大致相同的经济福利水平。","options":null},"topics":["gdp-accounting"],"answer_ref":"名义GDP相同不代表福利相同，因为：① 两国物价水平不同，同样的名义收入购买力不同；② 收入分配不同，平均收入掩盖贫富差距；③ 家庭自给自足生产、地下经济规模不同，未计入GDP的部分有别；④ 工作时长、闲暇、环境质量、健康与预期寿命等非市场因素不同。（任答三点即可）"},{"num":96,"type":"sa","question":"Economic statistics are not perfect. Explain at least one way in which each of the following statistics as currently calculated in the United States fails to completely or accurately measure the corresponding economic concept (in parentheses): a.real GDP per person (economic well-being)*b.CPI (cost of living)*c.unemployment rate (involuntary unemployment)*","options":null,"answer":null,"images":null,"translation":{"question":"经济统计并不完美。对于以下每种统计指标，请至少说明一种它目前在美国的计算方式未能完全或准确衡量其相应经济概念（括号内）的方式：a. 人均实际 GDP（经济福利）b. CPI（生活成本）c. 失业率（非自愿失业）","options":null},"topics":["gdp-accounting","cpi-inflation"],"answer_ref":"a. 人均实际GDP不计算家庭生产、地下经济和闲暇，也不反映收入分配与环境质量，因此只是福利的近似。b. CPI用固定篮子，存在替代偏差、新商品偏差和质量偏差，高估生活成本上升（通常高估约0.5–1个百分点）。c. 失业率把因找不到全职而从事兼职者计为\"就业\"，把丧失信心的工人（discouraged workers）排除在劳动力之外，且无法区分自愿与非自愿失业，因此不能准确度量非自愿失业。"},{"num":97,"type":"sa","question":"A number of statistics are computed to measure the price level, such as the GDP deflator and the CPI. The choice of which of these measures to use depends in many cases on the specific question in which you are interested. For each of the following situations, state whether the CPI or GDP deflator is a more appropriate measure to use and explain why the statistic is preferred. a.You are interested in looking at the impact of higher prices of imported oil in the overall cost of living.*b.The government is interested in whether increases in defense spending are affecting the price level.*c.An economic consulting firm is investigating the impact on the aggregate price level of more computers and electronic technology used in production. *","options":null,"answer":null,"images":null,"translation":{"question":"为衡量物价水平，人们计算了多种统计指标，如 GDP 平减指数和 CPI。在许多情况下，选择使用哪种指标取决于你所关注的具体问题。对于以下每种情况，说明使用 CPI 还是 GDP 平减指数更合适，并解释为什么该指标更受青睐。a. 你想考察进口石油价格上涨对总体生活成本的影响。b. 政府想了解国防支出的增加是否正在影响物价水平。c. 一家经济咨询公司正在研究生产中更多使用计算机和电子技术对总体物价水平的影响。","options":null},"topics":["cpi-inflation","gdp-accounting"],"answer_ref":"a. 用 CPI：进口石油直接进入消费者的购物篮子，影响生活成本；GDP 平减指数只含国内生产的产品，不含进口品。b. 用 GDP 平减指数：国防物资是国内生产的商品与服务，计入GDP，CPI 不覆盖。c. 用 GDP 平减指数：生产中使用的电脑与技术属于投资品/国内生产品，其价格变化进入平减指数而不进入 CPI。"},{"num":98,"type":"sa","question":"One senator criticizes the government for making an inadequate effort to stimulate the economy based on data from the BLS establishment survey which shows that the number of jobs in the economy has fallen. Another senator counters that the number of employed workers in the economy has increased over the same period, based on the BLS household survey. Explain how both senators can be correct.","options":null,"answer":null,"images":null,"translation":{"question":"一位参议员根据劳工统计局机构调查的数据（显示经济中的工作岗位数量已经下降）批评政府在刺激经济方面努力不足。另一位参议员则根据劳工统计局住户调查反驳说，同期经济中的就业工人数量有所增加。请解释两位参议员为何都可能正确。","options":null},"topics":["unemployment-measure"],"answer_ref":"两项调查口径不同：机构（薪资）调查统计的是非农企业的就业岗位数；住户调查统计的是有工作的家庭人数。两者可以同时成立，因为：① 一人多职会使就业人数多于岗位数；② 自雇者计入住户调查但不计入机构调查；③ 两项调查覆盖范围、样本和统计误差不同。故岗位减少与人手增加并不矛盾。"},{"num":99,"type":"sa","question":"There are a number of measures of aggregate economic activity, such as GDP, GNP, national income, personal income, and disposable personal income. Each of these measures can be a good indicator, depending on the issue under consideration. For each of the following issues, give your reasons for selecting one of the measures just mentioned as the best indicator to use in studying the issue: a.the proportion of income households save*b.the relative share of earnings going to labor versus capital*c.the total output of final goods and services*","options":null,"answer":null,"images":null,"translation":{"question":"衡量总体经济活动的指标有很多，如 GDP、GNP、国民收入、个人收入和个人可支配收入。根据所研究的问题，每种指标都可以是一个好的指标。对于以下每个问题，说明你选择上述指标之一作为研究该问题的最佳指标的理由：a. 家庭储蓄占收入的比例 b. 劳动与资本各自所得报酬的相对份额 c. 最终商品和服务的总产出","options":null},"topics":["gdp-accounting"],"answer_ref":"a. 家庭储蓄占收入的比例 → 个人可支配收入（DPI）：储蓄额与家庭实际拿到的收入对比才有意义。b. 劳动与资本的相对份额 → 国民收入（NI）：它是按要素报酬（工资、利息、租金、利润）核算的。c. 最终产品与服务的总产出 → GDP：其定义就是一国境内生产的最终产品与服务的市场价值。"},{"num":100,"type":"sa","question":"Real GDP per capita is an imperfect measure of economic well-being because it does not value home production or production in the underground economy, among other factors. Give at least two examples that show why the omission of these types of items will make a difference in evaluating economic well-being. One example should explain how the omissions distort comparisons of economic well-being across countries, and another example should explain how the omission distorts comparisons of economic well-being in the same country over time.","options":null,"answer":null,"images":null,"translation":{"question":"人均实际 GDP 是衡量经济福利的一个不完美指标，因为它不把家庭生产或地下经济的生产计入价值，此外还有其他因素。请至少给出两个例子，说明为什么遗漏这些类型的项目会影响到对经济福利的评估。其中一个例子应解释这些遗漏如何扭曲各国之间经济福利的比较，另一个例子应解释这种遗漏如何扭曲同一国家在不同时期经济福利的比较。","options":null},"topics":["gdp-accounting"],"answer_ref":"跨国比较：自给自足农业比重高的发展中国家存在大量未计价的家内生产（自种自吃、手工劳作），其真实产出被严重低估，GDP 会低估其福利，使穷国与福利差距看起来比实际更大。同一国家跨期比较：如越来越多的女性走出家庭就业，原本不计价的家庭烹饪、育儿转为市场化的餐饮、托育服务，GDP 随之上调，但真实产出未必增加——遗漏项目使跨期福利比较失真。"},{"num":101,"type":"sa","question":"Based on the data in the table below, explain what happened to output and prices in the economy between 2009 and 2010. 20092010*Nominal GDP ($ billions)$14,700$15,200*Real GDP ($ billions 2000 chain weighted)$12,100$11,900 *","options":null,"answer":null,"images":null,"translation":{"question":"根据下表中的数据，解释 2009 年至 2010 年间经济中的产出和价格发生了什么变化。表：2009 年 / 2010 年——名义 GDP（十亿美元）：14,700 美元 / 15,200 美元；实际 GDP（十亿美元，2000 年链式加权）：12,100 美元 / 11,900 美元。","options":null},"topics":["gdp-accounting"],"answer_ref":"名义GDP从 14,700 升至 15,200（+3.4%），实际GDP从 12,100 降至 11,900（−1.7%）。GDP 平减指数约上升 5.2%。结论：这一年物价水平明显上升，而实际产出下降——经济呈现\"价格上涨+产出下降\"的组合（类滞胀）。"},{"num":102,"type":"sa","question":"Explain why the value of GDP in 2012 would or would not change as a result of each transaction described below: a.In 2012, the Smith family purchases a new house that was built in 2012.*b.In 2012, the Jones family purchases a house that was built in 2001.*c.In 2012, a construction company purchases windows to put in the Smith family home that was built in 2012.*d.In 2012, Mr. Jones paints all of the rooms of the Jones family house purchased in 2009, using paint and supplies purchased in 2012.*e.In 2012, Mr. Smith uses an online brokerage service to purchases shares of stock in a construction company. *","options":null,"answer":null,"images":null,"translation":{"question":"解释下述每笔交易会使 2012 年的 GDP 价值发生或不发生变化的原因：a. 2012 年，史密斯一家购买一套 2012 年建造的新房。b. 2012 年，琼斯一家购买一套 2001 年建造的房子。c. 2012 年，一家建筑公司购买窗户，用来安装到 2012 年建造的史密斯家的新房上。d. 2012 年，琼斯先生使用 2012 年购买的油漆和材料，粉刷了 2009 年购买的琼斯家房子的所有房间。e. 2012 年，史密斯先生通过在线经纪服务购买了一家建筑公司的股票。","options":null},"topics":["gdp-accounting"],"answer_ref":"a. 计入：2012 年新建住房属于住宅投资。b. 不计入：房子是 2001 年建的，当年已计入；二手房买卖只是资产转移，只有经纪服务费计入。c. 不计入：窗户是中间产品，其价值已包含在新建房屋的价值中，单独计入会重复计算。d. 计入：粉刷是当年提供的服务，油漆等是最终产品（家庭购买的最终使用）。e. 不计入：股票是金融资产转移，不代表当期的产品与服务产出（经纪佣金才计入）。"},{"num":103,"type":"sa","question":"Explain which expenditure category of GDP changes and the direction of the change that results for each transaction described. a.A domestic business purchases a domestically produced computer to use in a business office.*b.A domestic business produces a computer that is sold to a foreign company.*c.The federal government purchases a domestically produced computer to use in a courthouse.*d.A domestic household purchases a domestically produced computer to use in a home.*e.A domestic household purchases a computer produced in a foreign country to use in a home.*","options":null,"answer":null,"images":null,"translation":{"question":"解释下述每笔交易导致 GDP 的哪个支出类别发生变化以及变化的方向。a. 一家国内企业购买一台国内生产的计算机，用于商务办公室。b. 一家国内企业生产一台计算机并出售给一家外国公司。c. 联邦政府购买一台国内生产的计算机，用于法院。d. 一个国内家庭购买一台国内生产的计算机，供家庭使用。e. 一个国内家庭购买一台外国生产的计算机，供家庭使用。","options":null},"topics":["gdp-accounting"],"answer_ref":"a. 投资 I 增加（企业购买资本品）。b. 净出口 NX 增加（出口增加）。c. 政府购买 G 增加。d. 消费 C 增加（家庭购买耐用消费品）。e. 消费 C 增加、进口增加使 NX 减少；C 与 NX 同额反向，GDP 总量不变，但消费项上升。"},{"num":104,"type":"sa","question":"Into which of the three categories—employed, unemployed, out of the labor force—would an interviewer for the Current Population Survey place each of the following people? Explain. a.Jennifer Temple is working as a second-grade schoolteacher.*b.Frank Peabody is attending college full-time to earn a degree in elementary education.*c.Martin Hampton is working as a high school social science teacher but is at home sick with the flu.*d.Kyle Brown does not currently have a job. He wants to be an elementary-school teacher. He has the appropriate degree. He has not looked for a position in the past month because he doesn't believe schools are currently hiring.*e.Brenda Dewey does not currently have a job. She has sent her resume to several school districts in the past week in the hope of finding a teaching position.*","options":null,"answer":null,"images":null,"translation":{"question":"当前人口调查的访问员会把以下每个人归入三个类别（就业、失业、不在劳动力队伍）中的哪一类？请解释。a. 珍妮弗·坦普尔是一名小学二年级教师。b. 弗兰克·皮博迪正在全日制上大学，以取得小学教育学位。c. 马丁·汉普顿是一名高中社会科学教师，但正因流感在家休病假。d. 凯尔·布朗目前没有工作。他想成为一名小学教师。他有相应的学位。过去一个月他没有找工作，因为他不相信学校目前正在招聘。e. 布伦达·杜威目前没有工作。过去一周她向几个学区寄送了简历，希望找到一份教师职位。","options":null},"topics":["unemployment-measure"],"answer_ref":"a. 就业：正在工作者。b. 不在劳动力中：全日制学生，未求职。c. 就业：因病暂时缺勤但有工作，仍计为就业。d. 不在劳动力中：近一个月未求职，属丧失信心的工人（discouraged worker）。e. 失业：无工作但在过去四周内积极求职。"},{"num":105,"type":"sa","question":"Sam wants a loan from Dean. While discussing the interest, Dean told Sam that he will give him two options. Which one should Sam choose and why? The options are: a. Sam will pay the nominal interest of 8 percent per annum. b. Sam will pay real interest of 4 percent per annum.","options":null,"answer":null,"images":null,"translation":{"question":"萨姆想向迪恩借一笔贷款。在讨论利息时，迪恩告诉萨姆他会给出两个选项。萨姆应该选择哪一个，为什么？选项是：a. 萨姆将支付每年 8% 的名义利率。b. 萨姆将支付每年 4% 的实际利率。","options":null},"topics":["cpi-inflation"],"answer_ref":"关键看通胀预期：实际利率 ≈ 名义利率 − 通胀率。a 选项的实际负担 = 8% − 通胀率；b 选项恒为 4%。若预期通胀率高于 4%，8% 名义利率对应的实际利率低于 4%，借款人萨姆应选 a；若预期通胀率低于 4%，应选 b。举例：预期通胀 6% 时，a 的实际利率仅 2%，选 a 更划算；通胀 2% 时，a 的实际利率为 6%，选 b 更划算。"},{"num":106,"type":"sa","question":"?GDP deflator is a better price level indicator than CPI.?Give reasons both supporting and opposing this statement.","options":null,"answer":null,"images":null,"translation":{"question":"“GDP 平减指数是比 CPI 更好的物价水平指标。”请给出支持和反对这一说法的理由。","options":null},"topics":["cpi-inflation","gdp-accounting"],"answer_ref":"支持：GDP 平减指数覆盖国内生产的全部最终产品（含投资品、政府购买），用当期产量加权（帕氏指数），不存在拉氏指数那样的替代偏差，可衡量整体物价水平。反对：平减指数不含进口消费品，与生活成本关系弱；使用变动权重，不能解释为固定生活篮子的\"生活成本\"；同样存在新产品和质量偏差。衡量消费者生活成本仍以 CPI 更合适，两者各有适用场景。"},{"num":107,"type":"sa","question":"City A has a total population of 10 million, of which 70 percent are adults. Assume that 20 percent of the adult population is not looking for a job and 60 percent of the remaining adult population is employed. Compute the following: a. Labor-force participation rate b. Unemployment rate","options":null,"answer":null,"images":null,"translation":{"question":"A 市总人口为 1,000 万，其中 70% 是成年人。假设成年人中有 20% 不找工作，其余成年人口中有 60% 就业。计算以下各项：a. 劳动力参与率 b. 失业率","options":null},"topics":["unemployment-measure"],"answer_ref":"成年人口 = 1000万×70% = 700万。不求职者 700万×20% = 140万，余 560万；就业者 = 560万×60% = 336万，失业者 = 224万；劳动力 = 560万。a. 劳动参与率 = 560/700 = 80%。b. 失业率 = 224/560 = 40%。"},{"num":108,"type":"sa","question":"Is real GDP a better measure of economic well-being of a country than nominal GDP? Give an explanation for your answer.","options":null,"answer":null,"images":null,"translation":{"question":"实际 GDP 是否比名义 GDP 更能衡量一个国家的经济福利？请对你的回答作出解释。","options":null},"topics":["gdp-accounting"],"answer_ref":"是。实际GDP按不变价格计算，其变化反映产品和服务的数量变化；名义GDP同时受产量和价格影响，物价上涨也会使其上升，无法区分\"东西更多\"还是\"价格更贵\"。衡量经济福利（人们能消费多少实际物品）应使用实际GDP。当然实际GDP仍遗漏分配、非市场活动等因素，只是更好的指标而非完美指标。"},{"num":109,"type":"sa","question":"In 2015, John buys a factory built in 2009 and constructs a new storage house within the premises. The transaction of buying the factory is not counted in the GDP, but the construction of the storage house in the same factory is counted in GDP. Why?","options":null,"answer":null,"images":null,"translation":{"question":"2015 年，约翰购买了一座 2009 年建造的工厂，并在厂区内建造了一座新的仓库。购买工厂的交易不计入 GDP，但在同一工厂内建造仓库却计入 GDP。为什么？","options":null},"topics":["gdp-accounting"],"answer_ref":"GDP 只计入当期生产的最终产品与服务。2009 年建厂时其价值已计入 2009 年 GDP，2015 年买入工厂只是既有资产的产权转移，不产生新价值；而新建仓库是 2015 年发生的建筑活动，属于当年的新增产出（计入投资），所以计入 2015 年 GDP。"},{"num":110,"type":"sa","question":"“I like eating mangoes daily, but when their price rises, I switch to papayas.?Does this statement support the fact that CPI overstates inflation? (Assume that mangoes are included in the goods basket used to calculate the CPI, but papayas are not included.)","options":null,"answer":null,"images":null,"translation":{"question":"“我每天都喜欢吃芒果，但当芒果价格上涨时，我就改吃木瓜。”这句话是否支持 CPI 高估通胀这一事实？（假设芒果包含在计算 CPI 使用的商品篮子中，而木瓜不包含在内。）","options":null},"topics":["cpi-inflation"],"answer_ref":"支持。这是替代效应的体现：芒果涨价后消费者改用木瓜。CPI 使用固定篮子，假定消费者仍按原比例购买芒果，从而高估了维持原有生活水平的真实成本——即高估了通胀。若篮子能随消费结构调整，实际生活成本上升幅度会更小。"},{"num":111,"type":"sa","question":"Cass was paid $500 in Social Security from the government. Though it was an expenditure made by the government, it is not included in the G component of GDP. Explain why.","options":null,"answer":null,"images":null,"translation":{"question":"卡斯从政府那里领取了 500 美元的社会保障金。虽然这是政府的一项支出，但它不计入 GDP 的 G 部分。请解释原因。","options":null},"topics":["gdp-accounting"],"answer_ref":"GDP 中的 G 只包括政府为购买当期商品和服务所做的支出。社会保障金是转移支付（transfer payment）：政府把购买力转移给居民，但没有换取任何当期产品或服务，不计入政府购买，也就不计入GDP。"},{"num":112,"type":"sa","question":"Bob bought $5,000 worth of Adobe Systems stock. This transaction was brokered by John, who received $50 for his help. I think the $5,000 should be included in GDP, and the $50 should not be included in GDP. State whether I am right or wrong and provide an explanation for your answer.","options":null,"answer":null,"images":null,"translation":{"question":"鲍勃购买了价值 5,000 美元的 Adobe Systems 股票。这笔交易由约翰撮合，约翰因此获得 50 美元报酬。我认为 5,000 美元应计入 GDP，而 50 美元不应计入 GDP。请说明我的看法是对还是错，并解释你的回答。","options":null},"topics":["gdp-accounting"],"answer_ref":"你的看法正好相反。购买股票 5,000 美元只是现有金融资产的所有权转移，不创造新产品或服务，不计入GDP；约翰收取的 50 美元是当期提供的经纪服务报酬，属于服务产出，应计入GDP。"}]},{"num":3,"title":"National Income","questions":[{"num":1,"type":"mc","question":"The circular flow model shows that households use income for:","options":["consumption, saving, and factor payments.","consumption, taxes, and factor payments.","taxes, saving, and factor payments.","consumption, taxes, and saving."],"answer":"D","images":null,"translation":{"question":"循环流动模型表明，家庭把收入用于：","options":["消费、储蓄和要素支付。","消费、税收和要素支付。","税收、储蓄和要素支付。","消费、税收和储蓄。"]},"topics":["national-income"]},{"num":2,"type":"mc","question":"In the circular flow diagram, firms receive revenue from the _____ market, which is used to purchase inputs in the _____ market.","options":["goods; financial","factor; financial","goods; factor","factor; goods"],"answer":"C","images":null,"translation":{"question":"在循环流动图中，企业从 ______ 市场获得收入，并用这些收入在 ______ 市场购买投入品。","options":["商品；金融","要素；金融","商品；要素","要素；商品"]},"topics":["national-income"]},{"num":3,"type":"mc","question":"In the circular flow model, households receive income from the _____ market and save through the _____ market.","options":["goods; financial","factor; financial","goods; factor","factor; goods"],"answer":"B","images":null,"translation":{"question":"在循环流动模型中，家庭从 ______ 市场获得收入，并通过 ______ 市场储蓄。","options":["商品；金融","要素；金融","商品；要素","要素；商品"]},"topics":["national-income"]},{"num":4,"type":"mc","question":"In the long run, the level of national income in an economy is determined by its:","options":["factors of production and production function.","real and nominal interest rate.","government budget surplus or deficit.","rate of economic and accounting profit."],"answer":"A","images":null,"translation":{"question":"在长期，一个经济中的国民收入水平由以下哪项决定：","options":["生产要素和生产函数。","实际利率和名义利率。","政府预算盈余或赤字。","经济利润率和会计利润率。"]},"topics":["national-income"]},{"num":5,"type":"mc","question":"An economy's factors of production and its production function determine the economy's:","options":["labor-force participation rate.","budget surplus or deficit.","population growth rate.","output of goods and services."],"answer":"D","images":null,"translation":{"question":"一个经济的生产要素及其生产函数决定该经济的：","options":["劳动力参与率。","预算盈余或赤字。","人口增长率。","商品和服务的产出。"]},"topics":["national-income"]},{"num":6,"type":"mc","question":"The two most important factors of production are:","options":["goods and services.","labor and energy.","capital and labor.","saving and investment."],"answer":"C","images":null,"translation":{"question":"两个最重要的生产要素是：","options":["商品和服务。","劳动和能源。","资本和劳动。","储蓄和投资。"]},"topics":["national-income"]},{"num":7,"type":"mc","question":"Unlike the real world, the classical model with fixed output assumes that:","options":["capital and labor are fully utilized.","all capital is fully utilized, but some labor is unemployed.","all labor is fully employed, but some capital lies idle.","some capital lies idle, and some labor is unemployed."],"answer":"A","images":null,"translation":{"question":"与现实世界不同，具有固定产出的古典模型假设：","options":["资本和劳动被充分利用。","所有资本被充分利用，但部分劳动失业。","所有劳动被充分就业，但部分资本闲置。","部分资本闲置，且部分劳动失业。"]},"topics":["national-income"]},{"num":8,"type":"mc","question":"A production function is a mathematical relationship between:","options":["factor prices and the marginal product of factors.","factors of production and factor prices.","factors of production and the quantity of output produced.","factor prices and the quantity of output produced."],"answer":"C","images":null,"translation":{"question":"生产函数是以下两者之间的数学关系：","options":["要素价格和要素的边际产品。","生产要素和要素价格。","生产要素和所生产的产出数量。","要素价格和所生产的产出数量。"]},"topics":["national-income"]},{"num":9,"type":"mc","question":"The production function feature called “constant returns to scale” means that if we:","options":["multiply capital by z1 and labor by z2, we multiply output by z3.","increase capital and labor by 10 percent each, we increase output by 10 percent.","increase capital and labor by 5 percent each, we increase output by 10 percent.","increase capital by 10 percent and increase labor by 5 percent, we increase output by 7.5 percent."],"answer":"B","images":null,"translation":{"question":"被称为“规模报酬不变”的生产函数特征意味着，如果我们：","options":["将资本乘以 z1、劳动乘以 z2，则产出乘以 z3。","将资本和劳动各增加 10%，则产出增加 10%。","将资本和劳动各增加 5%，则产出增加 10%。","资本增加 10% 而劳动增加 5%，则产出增加 7.5%。"]},"topics":["cobb-douglas"]},{"num":10,"type":"mc","question":"If an increase of an equal percentage in all factors of production increases output of the same percentage, then a production function has the property called:","options":["constant marginal product of labor.","increasing marginal product of labor.","constant returns to scale.","increasing returns to scale."],"answer":"C","images":null,"translation":{"question":"如果所有生产要素以相同百分比增加会使产出以相同百分比增加，那么该生产函数具有被称为以下哪项的性质：","options":["劳动边际产品不变。","劳动边际产品递增。","规模报酬不变。","规模报酬递增。"]},"topics":["cobb-douglas"]},{"num":11,"type":"mc","question":"If bread is produced using a constant returns to scale production function, then if the:","options":["number of workers is doubled, twice as much bread will be produced.","amount of equipment is doubled, twice as much bread will be produced.","amounts of equipment and workers are both doubled, twice as much bread will be produced.","amounts of equipment and workers are both doubled, four times as much bread will be produced."],"answer":"C","images":null,"translation":{"question":"如果面包是用规模报酬不变的生产函数生产的，那么如果：","options":["工人数量翻倍，生产的面包将是原来的两倍。","设备数量翻倍，生产的面包将是原来的两倍。","设备和工人的数量都翻倍，生产的面包将是原来的两倍。","设备和工人的数量都翻倍，生产的面包将是原来的四倍。"]},"topics":["cobb-douglas"]},{"num":12,"type":"mc","question":"The neoclassical theory of distribution:","options":["was developed by Karl Marx.","is rejected by most economists today.","shows that the national income of an economy is not equal to total output.","is a theory of how national income is divided among the factors of production."],"answer":"D","images":null,"translation":{"question":"新古典分配理论：","options":["由卡尔·马克思提出。","被当今大多数经济学家所拒绝。","表明一个经济的国民收入不等于总产出。","是关于国民收入如何在各生产要素之间分配的理论。"]},"topics":["national-income"]},{"num":13,"type":"mc","question":"The price received by each factor of production is determined by:","options":["demand for output and supply of factors.","demand for factors and supply of output.","demand and supply of output.","demand and supply of factors."],"answer":"D","images":null,"translation":{"question":"每种生产要素获得的价格由以下哪项决定：","options":["产出的需求和要素的供给。","要素的需求和产出的供给。","产出的需求和供给。","要素的需求和供给。"]},"topics":["national-income"]},{"num":14,"type":"mc","question":"The assumption that the factor's supply is fixed will imply that the factor's","options":["supply curve is horizontal.","supply curve is vertical.","supply curve slopes up to the right.","demand curve slopes up to the right."],"answer":"B","images":null,"translation":{"question":"要素供给固定的假设意味着该要素的：","options":["供给曲线是水平的。","供给曲线是垂直的。","供给曲线向右上方倾斜。","需求曲线向右上方倾斜。"]},"topics":["national-income"]},{"num":15,"type":"mc","question":"A firm's economic profit is:","options":["the price of output minus the wage minus the rental price of capital.","revenue minus costs.","revenue plus capital costs.","the price of output minus labor costs."],"answer":"B","images":null,"translation":{"question":"一个企业的经济利润是：","options":["产出价格减去工资再减去资本租赁价格。","收入减去成本。","收入加上资本成本。","产出价格减去劳动成本。"]},"topics":["national-income"]},{"num":16,"type":"mc","question":"A competitive firm chooses the:","options":["price at which to sell the product produced.","wage to pay labor.","quantity of labor and capital to employ.","rental price to pay capital."],"answer":"C","images":null,"translation":{"question":"竞争性企业选择：","options":["其生产产品的销售价格。","支付给劳动的工资。","雇佣的劳动和资本数量。","支付给资本的租赁价格。"]},"topics":["national-income"]},{"num":17,"type":"mc","question":"The marginal product of labor is:","options":["output divided by labor input.","additional output produced when one additional unit of labor is added.","additional output produced when one additional unit of labor and one additional unit of capital are added.","value of additional output when one dollar's worth of additional labor is added."],"answer":"B","images":null,"translation":{"question":"劳动的边际产品是：","options":["产出除以劳动投入。","当增加一单位劳动时所增加的产出。","当增加一单位劳动和一单位资本时所增加的产出。","当增加一美元劳动时所增加产出的价值。"]},"topics":["national-income"]},{"num":18,"type":"mc","question":"A competitive, profit-maximizing firm hires labor until the:","options":["marginal product of labor equals the wage.","price of output multiplied by the marginal product of labor equals the wage.","real wage equals the real rental price of capital.","wage equals the rental price of capital."],"answer":"B","images":null,"translation":{"question":"竞争性的、追求利润最大化的企业会一直雇佣劳动，直到：","options":["劳动的边际产品等于工资。","产出价格乘以劳动的边际产品等于工资。","实际工资等于资本的实际租赁价格。","工资等于资本的租赁价格。"]},"topics":["national-income"]},{"num":19,"type":"mc","question":"The real wage is the return to labor measured in:","options":["dollars.","units of output.","units of labor.","units of capital."],"answer":"B","images":null,"translation":{"question":"实际工资是以以下哪项衡量的劳动回报：","options":["美元。","产出单位。","劳动单位。","资本单位。"]},"topics":["national-income"]},{"num":20,"type":"mc","question":"The marginal product of capital is:","options":["output divided by capital input.","additional output produced when one additional unit of capital is added.","additional output produced when one additional unit of capital and one additional unit of labor are added.","the value of additional output when one dollar's worth of additional capital is added."],"answer":"B","images":null,"translation":{"question":"资本的边际产品是：","options":["产出除以资本投入。","当增加一单位资本时所增加的产出。","当增加一单位资本和一单位劳动时所增加的产出。","当增加一美元资本时所增加产出的价值。"]},"topics":["national-income"]},{"num":21,"type":"mc","question":"The real rental price of capital is the price per unit of capital measured in:","options":["dollars.","units of output.","units of labor.","units of capital."],"answer":"B","images":null,"translation":{"question":"资本的实际租赁价格是以以下哪项衡量的每单位资本价格：","options":["美元。","产出单位。","劳动单位。","资本单位。"]},"topics":["national-income"]},{"num":22,"type":"mc","question":"The real wage will increase if:","options":["the supply of labor increases.","the productivity of labor increases.","the price of output increases.","the supply of capital decreases."],"answer":"B","images":null,"translation":{"question":"在以下哪种情况下实际工资会上升：","options":["劳动供给增加。","劳动生产率提高。","产出价格上升。","资本供给减少。"]},"topics":["national-income"]},{"num":23,"type":"mc","question":"An increase in the supply of capital will:","options":["increase the real rental price of capital.","decrease the real rental price of capital.","increase the productivity of capital.","increase the marginal product of capital."],"answer":"B","images":null,"translation":{"question":"资本供给的增加将：","options":["提高资本的实际租赁价格。","降低资本的实际租赁价格。","提高资本的生产率。","提高资本的边际产品。"]},"topics":["national-income"]},{"num":24,"type":"mc","question":"In the classical model, what adjusts to eliminate any unemployment of labor in the economy?","options":["the average price level","the interest rate","the real rental price of capital","the real wage"],"answer":"D","images":null,"translation":{"question":"在古典模型中，什么进行调整以消除经济中的任何劳动失业？","options":["平均物价水平","利率","资本的实际租赁价格","实际工资"]},"topics":["national-income"]},{"num":25,"type":"mc","question":"The neoclassical theory of distribution explains the allocation of:","options":["output between goods and services.","output among consumption, investment, and government spending.","income among factors of production.","income between saving and investment."],"answer":"C","images":null,"translation":{"question":"新古典分配理论解释的是以下哪项的分配：","options":["商品和服务之间的产出。","消费、投资和政府支出之间的产出。","各生产要素之间的收入。","储蓄和投资之间的收入。"]},"topics":["national-income"]},{"num":26,"type":"mc","question":"Assuming that all firms maximize profits, economic profit is zero if:","options":["all factors are paid their marginal products and the law of diminishing returns is valid.","all factors are paid their marginal products, and there are constant returns to scale.","no firms are competitive.","all factors are paid their marginal products."],"answer":"B","images":null,"translation":{"question":"假设所有企业都追求利润最大化，如果满足以下哪项条件，经济利润为零：","options":["所有要素都按其边际产品获得报酬，且边际收益递减规律成立。","所有要素都按其边际产品获得报酬，且规模报酬不变。","没有企业是竞争性的。","所有要素都按其边际产品获得报酬。"]},"topics":["national-income"]},{"num":27,"type":"mc","question":"According to Euler's theorem, if competitive firms pay each factor its marginal product and the production function has constant returns to scale, the sum of all factor payments will equal:","options":["total investment.","total saving.","total profits.","total output."],"answer":"D","images":null,"translation":{"question":"根据欧拉定理，如果竞争性企业按每种要素的边际产品支付报酬，且生产函数规模报酬不变，那么所有要素报酬之和将等于：","options":["总投资。","总储蓄。","总利润。","总产出。"]},"topics":["national-income"]},{"num":28,"type":"mc","question":"Accounting profit is:","options":["economic profit minus the return to capital.","equal to economic profit.","economic profit plus the return to capital.","equal to the economic return to capital."],"answer":"C","images":null,"translation":{"question":"会计利润是：","options":["经济利润减去资本回报。","等于经济利润。","经济利润加上资本回报。","等于资本的经济回报。"]},"topics":["national-income"]},{"num":29,"type":"mc","question":"According to the neoclassical theory of distribution, if firms are competitive and subject to constant returns to scale, total income in the economy is distributed:","options":["only to the labor used in production.","partly between labor and capital used in production, with the surplus going to the owners of the firm as profits.","equally between the labor and capital used in production.","between the labor and capital used in production, according to their marginal productivities."],"answer":"D","images":null,"translation":{"question":"根据新古典分配理论，如果企业是竞争性的且规模报酬不变，那么经济中的总收入被分配：","options":["只给生产中使用的劳动。","部分在生产中使用的劳动和资本之间，剩余部分作为利润归企业所有者。","在生产中使用的劳动和资本之间平分。","在生产中使用的劳动和资本之间，按其边际生产率分配。"]},"topics":["national-income"]},{"num":30,"type":"mc","question":"According to the neoclassical theory of distribution, total output is divided between payments to capital and payments to labor depending on their:","options":["supply.","equilibrium growth rates.","relative political power.","marginal productivities."],"answer":"D","images":null,"translation":{"question":"根据新古典分配理论，总产出在资本报酬和劳动报酬之间分配，取决于它们的：","options":["供给。","均衡增长率。","相对政治权力。","边际生产率。"]},"topics":["national-income"]},{"num":31,"type":"mc","question":"What determines the ratio of the wage to rental rate of capital in a competitive, profit-maximizing economy with constant returns to scale?","options":["the quantity of economic profits earned by firm owners","the interest rate","the ratio of public saving to private saving","the marginal productivity of labor relative to the marginal productivity of capital"],"answer":"D","images":null,"translation":{"question":"在一个竞争性的、追求利润最大化且规模报酬不变的经济中，什么决定工资与资本租赁价格之比？","options":["企业所有者赚取的经济利润数量","利率","公共储蓄与私人储蓄之比","劳动的边际生产率相对于资本的边际生产率"]},"topics":["national-income"]},{"num":32,"type":"mc","question":"With a Cobb–Douglas production function, the share of output going to labor:","options":["decreases as the amount of labor increases.","increases as the amount of labor increases.","increases as the amount of capital increases.","does not depend on the amount of labor in the economy."],"answer":"D","images":null,"translation":{"question":"在柯布-道格拉斯生产函数下，产出中归劳动所有的份额：","options":["随着劳动数量的增加而下降。","随着劳动数量的增加而上升。","随着资本数量的增加而上升。","不取决于经济中的劳动数量。"]},"topics":["cobb-douglas"]},{"num":33,"type":"mc","question":"If output is described by the production function Y = AK0.2L0.8, then the production function has:","options":["constant returns to scale.","diminishing returns to scale.","increasing returns to scale.","a degree of returns to scale that cannot be determined from the information given."],"answer":"A","images":null,"translation":{"question":"如果产出由生产函数 Y = AK0.2L0.8 描述，那么该生产函数具有：","options":["规模报酬不变。","规模报酬递减。","规模报酬递增。","根据所给信息无法确定规模报酬的类型。"]},"topics":["cobb-douglas"]},{"num":34,"type":"mc","question":"If Y = AK0.5L0.5 and A, K, and L are all 100, the marginal product of capital is:","options":["50.","100.","200.","1000."],"answer":"A","images":null,"translation":{"question":"如果 Y = AK0.5L0.5，且 A、K、L 都为 100，那么资本的边际产品为：","options":["50。","100。","200。","1000。"]},"topics":["cobb-douglas"]},{"num":35,"type":"mc","question":"Since 1960, the U.S. ratio of labor income to total income has:","options":["been about 2.5 to 1.","remained relatively steady.","increased steadily.","decreased steadily."],"answer":"B","images":null,"translation":{"question":"自 1960 年以来，美国劳动收入占总收入的比例：","options":["约为 2.5 比 1。","保持相对稳定。","稳步上升。","稳步下降。"]},"topics":["cobb-douglas"]},{"num":36,"type":"mc","question":"If the production function describing an economy is Y = 100 K.25L.75, then the share of output going to labor:","options":["is 25 percent.","is 75 percent.","depends on the quantities of labor and capital.","depends on the state of technology."],"answer":"B","images":null,"translation":{"question":"如果描述某经济的生产函数是 Y = 100 K.25L.75，那么产出中归劳动所有的份额：","options":["是 25%。","是 75%。","取决于劳动和资本的数量。","取决于技术状况。"]},"topics":["cobb-douglas"]},{"num":37,"type":"mc","question":"In a Cobb–Douglas production function, the marginal product of labor will increase if:","options":["the quantity of labor increases.","the quantity of capital increases.","capital's share of output increases.","average labor productivity decreases."],"answer":"B","images":null,"translation":{"question":"在柯布-道格拉斯生产函数中，如果满足以下哪项条件，劳动的边际产品将增加：","options":["劳动数量增加。","资本数量增加。","资本的产出份额增加。","平均劳动生产率下降。"]},"topics":["cobb-douglas"]},{"num":38,"type":"mc","question":"In a Cobb–Douglas production function, the marginal product of capital will increase if:","options":["the quantity of labor increases.","the quantity of capital increases.","labor's share of output increases.","average capital productivity decreases."],"answer":"A","images":null,"translation":{"question":"在柯布-道格拉斯生产函数中，如果满足以下哪项条件，资本的边际产品将增加：","options":["劳动数量增加。","资本数量增加。","劳动的产出份额增加。","平均资本生产率下降。"]},"topics":["cobb-douglas"]},{"num":39,"type":"mc","question":"According to Goldin and Katz, the increasing income inequality of recent decades is the result of:","options":["increases in the rates of skill-biased technological advancement and educational attainment.","decreases in the rates of skill-biased technological advancement and educational attainment.","an increase in the rate of skill-biased technological advancement and a slowdown in educational advancement.","a decrease in the rate of skill-biased technological advancement and an increase in the rate of educational advancement."],"answer":"C","images":null,"translation":{"question":"根据 Goldin 和 Katz 的观点，近几十年来不断加剧的收入不平等是以下哪项的结果：","options":["技能偏向型技术进步和受教育程度提升速度的加快。","技能偏向型技术进步和受教育程度提升速度的放缓。","技能偏向型技术进步速度的加快和受教育程度提升速度的放缓。","技能偏向型技术进步速度的放缓和受教育程度提升速度的加快。"]},"topics":["national-income"]},{"num":40,"type":"mc","question":"Skill-biased technological change ______ the demand for high-skilled workers, while a slowdown in the pace of educational advancement reduces the supply of skilled workers. If we observed both of these phenomena, we would expect _____ wages for skilled workers.","options":["increases; higher","increases; lower","decreases; higher","decreases; lower"],"answer":"A","images":null,"translation":{"question":"技能偏向型技术进步 ______ 对高技能工人的需求，而受教育程度提升速度的放缓减少了技能工人的供给。如果我们观察到这两种现象，我们会预期技能工人的工资 ______。","options":["提高；更高","提高；更低","降低；更高","降低；更低"]},"topics":["national-income"]},{"num":41,"type":"mc","question":"For much of the twentieth century, skill-biased technological change ______ the demand for high-skilled workers, while the increase in the pace of educational advancement increased the supply of skilled workers. Because educational advancement _______ skill-biased technological change, we should expect _____ wages for skilled workers.","options":["increased; outpaced; higher","increased; outpaced; lower","decreased; slowed down; higher","decreased; slowed down; lower"],"answer":"B","images":null,"translation":{"question":"在 20 世纪的大部分时间里，技能偏向型技术进步 ______ 对高技能工人的需求，而受教育程度提升速度的加快增加了技能工人的供给。因为受教育程度的提升 ______ 技能偏向型技术进步，我们应该预期技能工人的工资 ______。","options":["提高；超过；更高","提高；超过；更低","降低；放缓；更高","降低；放缓；更低"]},"topics":["national-income"]},{"num":42,"type":"mc","question":"Estimates by Goldin and Katz indicate that the financial returns of a year of college _____ between 1980 and 2005.","options":["increased","decreased","did not change","were negative"],"answer":"A","images":null,"translation":{"question":"Goldin 和 Katz 的估计表明，1980 年至 2005 年间，一年大学教育的财务回报 ______。","options":["增加了","减少了","没有变化","为负"]},"topics":["national-income"]},{"num":43,"type":"mc","question":"According to the neoclassical theory of distribution, in an economy described by a Cobb–Douglas production function, workers should experience high rates of real wage growth when:","options":["real interest rates are high.","real interest rates are low.","labor productivity is growing rapidly.","capital's share of income is growing rapidly."],"answer":"C","images":null,"translation":{"question":"根据新古典分配理论，在由柯布-道格拉斯生产函数描述的经济中，工人应在以下哪种情况下经历较高的实际工资增长率：","options":["实际利率高时。","实际利率低时。","劳动生产率快速增长时。","资本占收入的份额快速增长时。"]},"topics":["national-income"]},{"num":44,"type":"mc","question":"Assume that an economy is described by a Cobb–Douglas production function. If average labor productivity is growing rapidly:","options":["labor's share of total income will be increasing.","labor's share of total income will be decreasing.","workers will experience high rates of real wage growth.","economic profits will be positive."],"answer":"C","images":null,"translation":{"question":"假设某经济由柯布-道格拉斯生产函数描述。如果平均劳动生产率快速增长：","options":["劳动占总收入的份额将上升。","劳动占总收入的份额将下降。","工人将经历较高的实际工资增长率。","经济利润将为正。"]},"topics":["cobb-douglas"]},{"num":45,"type":"mc","question":"In a closed economy, the components of GDP are:","options":["consumption, investment, government purchases, and exports.","consumption, investment, government purchases, and net exports.","consumption, investment, and government purchases.","consumption and investment."],"answer":"C","images":null,"translation":{"question":"在封闭经济中，GDP 的组成部分是：","options":["消费、投资、政府购买和出口。","消费、投资、政府购买和净出口。","消费、投资和政府购买。","消费和投资。"]},"topics":["national-income"]},{"num":46,"type":"mc","question":"The demand for output in a closed economy is the sum of:","options":["public saving and private saving.","the quantity of capital and labor and production technology.","consumption, investment, and government purchases.","government purchases and transfer payments minus tax receipts."],"answer":"C","images":null,"translation":{"question":"封闭经济中对产出的需求是以下哪项之和：","options":["公共储蓄和私人储蓄。","资本和劳动的数量以及生产技术。","消费、投资和政府购买。","政府购买和转移支付减去税收收入。"]},"topics":["national-income"]},{"num":47,"type":"mc","question":"Disposable personal income is defined as income after the payment of all:","options":["taxes.","interest.","loans.","social insurance contributions."],"answer":"A","images":null,"translation":{"question":"个人可支配收入被定义为支付所有以下哪项之后的收入：","options":["税收。","利息。","贷款。","社会保险缴款。"]},"topics":["national-income"]},{"num":48,"type":"mc","question":"A consumption function shows the relationship between consumption and:","options":["income.","personal income.","disposable income.","taxes."],"answer":"C","images":null,"translation":{"question":"消费函数表明消费与以下哪项之间的关系：","options":["收入。","个人收入。","可支配收入。","税收。"]},"topics":["national-income"]},{"num":49,"type":"mc","question":"Consumption depends ______ on disposable income, and investment depends ______ on the real interest rate.","options":["positively; positively","positively; negatively","negatively; negatively","negatively; positively"],"answer":"B","images":null,"translation":{"question":"消费 ______ 地取决于可支配收入，投资 ______ 地取决于实际利率。","options":["正；正","正；负","负；负","负；正"]},"topics":["national-income"]},{"num":50,"type":"mc","question":"The marginal propensity to consume is:","options":["expected to be between zero and one.","equal to disposable income divided by consumption.","the amount by which consumption changes when wealth increases by one dollar.","normally assumed to increase as taxes increase."],"answer":"A","images":null,"translation":{"question":"边际消费倾向：","options":["预期介于 0 和 1 之间。","等于可支配收入除以消费。","是当财富增加 1 美元时消费变化的数量。","通常被假设为随税收增加而增加。"]},"topics":["national-income"]},{"num":51,"type":"mc","question":"If the consumption function is given by C = 500 + 0.5(Y – T), and Y is 6,000 and T is given by T = 200 + 0.2Y, then C equals:","options":["2,500.","2,800.","3,500.","4,200."],"answer":"B","images":null,"translation":{"question":"如果消费函数为 C = 500 + 0.5(Y – T)，Y 为 6,000，T 由 T = 200 + 0.2Y 给出，那么 C 等于：","options":["2,500。","2,800。","3,500。","4,200。"]},"topics":["national-income"]},{"num":52,"type":"mc","question":"If the consumption function is given by the equation C = 500 + 0.5Y, the production function is Y = 50K0.5L0.5, where K = 100 and L = 100, then C equals:","options":["1,000.","2,500.","3,000.","5,000."],"answer":"C","images":null,"translation":{"question":"如果消费函数为方程 C = 500 + 0.5Y，生产函数为 Y = 50K0.5L0.5，其中 K = 100、L = 100，那么 C 等于：","options":["1,000。","2,500。","3,000。","5,000。"]},"topics":["national-income"]},{"num":53,"type":"mc","question":"If the consumption function is given by C = 150 + 0.85Y and Y increases by 1 unit, then C increases by:","options":["0.15 units.","0.5 units.","0.85 units.","1 unit."],"answer":"C","images":null,"translation":{"question":"如果消费函数为 C = 150 + 0.85Y，且 Y 增加 1 单位，那么 C 增加：","options":["0.15 单位。","0.5 单位。","0.85 单位。","1 单位。"]},"topics":["national-income"]},{"num":54,"type":"mc","question":"If the consumption function is given by C = 150 + 0.85Y and Y increases by 1 unit, then saving:","options":["decreases by 0.85 units.","decreases by 0.15 units.","increases by 0.15 units.","increases by 0.85 units."],"answer":"C","images":null,"translation":{"question":"如果消费函数为 C = 150 + 0.85Y，且 Y 增加 1 单位，那么储蓄：","options":["减少 0.85 单位。","减少 0.15 单位。","增加 0.15 单位。","增加 0.85 单位。"]},"topics":["national-income"]},{"num":55,"type":"mc","question":"If the consumption function is given by C = 150 + 0.85(Y – T) and T increases by 1 unit, then saving","options":["decreases by 0.85 units.","decreases by 0.15 units.","increases by 0.15 units.","increases by 0.85 units."],"answer":"B","images":null,"translation":{"question":"如果消费函数为 C = 150 + 0.85(Y – T)，且 T 增加 1 单位，那么储蓄：","options":["减少 0.85 单位。","减少 0.15 单位。","增加 0.15 单位。","增加 0.85 单位。"]},"topics":["national-income"]},{"num":56,"type":"mc","question":"Assume that the consumption function is given by C = 150 + 0.85(Y – T) and the tax function is given by T = t0 + t1Y. If t0 increases by 1 unit, then consumption:","options":["decreases by 0.85 units.","decreases by 0.15 units.","increases by 0.15 units.","increases by 0.85 units."],"answer":"A","images":null,"translation":{"question":"假设消费函数为 C = 150 + 0.85(Y – T)，税收函数为 T = t0 + t1Y。如果 t0 增加 1 单位，那么消费：","options":["减少 0.85 单位。","减少 0.15 单位。","增加 0.15 单位。","增加 0.85 单位。"]},"topics":["national-income"]},{"num":57,"type":"mc","question":"Assume that the consumption function is given by C = 150 + 0.85(Y – T), the tax function is given by T = t0 + t1Y, and Y is 5,000. If t1 decreases from 0.3 to 0.2, then consumption increases by:","options":["85.","425.","500.","525."],"answer":"B","images":null,"translation":{"question":"假设消费函数为 C = 150 + 0.85(Y – T)，税收函数为 T = t0 + t1Y，Y 为 5,000。如果 t1 从 0.3 下降到 0.2，那么消费增加：","options":["85。","425。","500。","525。"]},"topics":["national-income"]},{"num":58,"type":"mc","question":"Assume that the consumption function is given by C = 200 + 0.7(Y – T), the tax function is given by T = 100 + t1Y, and Y = 50K0.5L0.5, where K = 100 and L = 100. If t1 increases from 0.2 to 0.25, then consumption decreases by:","options":["70.","140.","175.","250."],"answer":"C","images":null,"translation":{"question":"假设消费函数为 C = 200 + 0.7(Y – T)，税收函数为 T = 100 + t1Y，Y = 50K0.5L0.5，其中 K = 100、L = 100。如果 t1 从 0.2 增加到 0.25，那么消费减少：","options":["70。","140。","175。","250。"]},"topics":["national-income"]},{"num":59,"type":"mc","question":"Assume that the consumption function is given by C = 200 + 0.7(Y – T), the tax function is given by T = 100 + 0.2Y, and Y = 50K0.5L0.5, where K = 100. If L increases from 100 to 144, then consumption increases by:","options":["560.","840.","1,120.","2,120."],"answer":"A","images":null,"translation":{"question":"假设消费函数为 C = 200 + 0.7(Y – T)，税收函数为 T = 100 + 0.2Y，Y = 50K0.5L0.5，其中 K = 100。如果 L 从 100 增加到 144，那么消费增加：","options":["560。","840。","1,120。","2,120。"]},"topics":["national-income"]},{"num":60,"type":"mc","question":"Private investment goods as measured in GDP are purchased by:","options":["business firms alone.","households alone.","business firms and households.","business firms, households, and governments."],"answer":"C","images":null,"translation":{"question":"GDP 中衡量的私人投资品是由以下哪项购买的：","options":["仅企业。","仅家庭。","企业和家庭。","企业、家庭和政府。"]},"topics":["national-income"]},{"num":61,"type":"mc","question":"Total investment in the United States averages about ______ percent of GDP.","options":["10","15","20","25"],"answer":"B","images":null,"translation":{"question":"美国的总投资平均约占 GDP 的 ______%。","options":["10","15","20","25"]},"topics":["national-income"]},{"num":62,"type":"mc","question":"Other things equal, an increase in the interest rate leads to:","options":["a decrease in the quantity of investment goods demanded.","no change in the quantity of investment goods demanded.","an increase in the quantity of investment goods demanded.","sometimes an increase and sometimes a decrease in the quantity of investment goods demanded."],"answer":"A","images":null,"translation":{"question":"在其他条件相同的情况下，利率上升导致：","options":["投资品需求量减少。","投资品需求量不变。","投资品需求量增加。","投资品需求量有时增加、有时减少。"]},"topics":["national-income"]},{"num":63,"type":"mc","question":"When economists speak of “the” interest rate, they mean:","options":["the rate on 90-day Treasury bills.","the Fed Funds rate.","the “prime” rate on mortgage loans.","no particular interest rate; it's usually an innocuous assumption since real interest rates tend to move up and down together."],"answer":"D","images":null,"translation":{"question":"当经济学家谈到“那个”利率时，他们指的是：","options":["90 天国库券的利率。","联邦基金利率。","抵押贷款的“优惠”利率。","并非特指某种利率；这通常是一个无害的假设，因为实际利率往往同涨同跌。"]},"topics":["national-income"]},{"num":64,"type":"mc","question":"Assume that a firm wants to build a factory that will cost $5 million. It believes that it can get a return of $600,000 in one year and then can sell the used factory for its original cost. The rate of return on this investment would be:","options":["6 percent.","12 percent.","18 percent.","30 percent."],"answer":"B","images":null,"translation":{"question":"假设一家企业想建造一座耗资 500 万美元的工厂。它相信一年后可获得 600,000 美元的回报，之后还能以原价出售这座二手工厂。这项投资的回报率将是：","options":["6%。","12%。","18%。","30%。"]},"topics":["national-income"]},{"num":65,"type":"mc","question":"Assume that a firm is considering building a factory that will cost $5 million. It believes that it can get a profit from this factory of $600,000 per year for many years. The interest rate at which the firm can borrow money is 15 percent. After evaluating whether it should build the factory, the firm decides that it should:","options":["not build because the rate of return on the factory is only 6 percent.","not build because the rate of return on the factory is only 12 percent.","build because the rate of return on the factory is 30 percent.","build because the rate of return on the factory is 35 percent."],"answer":"B","images":null,"translation":{"question":"假设一家企业正在考虑建造一座耗资 500 万美元的工厂。它相信多年内每年可从该工厂获得 600,000 美元的利润。企业借款的利率为 15%。在评估是否应建造该工厂后，企业决定应该：","options":["不建造，因为工厂的回报率仅为 6%。","不建造，因为工厂的回报率仅为 12%。","建造，因为工厂的回报率为 30%。","建造，因为工厂的回报率为 35%。"]},"topics":["national-income"]},{"num":66,"type":"mc","question":"The nominal interest rate is the:","options":["rate of interest that investors pay to borrow money.","same as the real interest rate.","rate of inflation minus the real rate of interest.","real rate of interest minus the rate of inflation."],"answer":"A","images":null,"translation":{"question":"名义利率是：","options":["投资者借款所支付的利率。","与实际利率相同。","通胀率减去实际利率。","实际利率减去通胀率。"]},"topics":["national-income"]},{"num":67,"type":"mc","question":"The real interest rate is the:","options":["rate of interest actually paid by consumers.","rate of interest actually paid by banks.","rate of inflation minus the nominal interest rate.","nominal interest rate minus the rate of inflation."],"answer":"D","images":null,"translation":{"question":"实际利率是：","options":["消费者实际支付的利率。","银行实际支付的利率。","通胀率减去名义利率。","名义利率减去通胀率。"]},"topics":["national-income"]},{"num":68,"type":"mc","question":"Assume that the investment function is given by I = 1,000 – 30r, where r is the real rate of interest (in percent). Assume further that the nominal rate of interest is 10 percent and the inflation rate is 2 percent. According to the investment function, investment will be:","options":["240.","700.","760.","970."],"answer":"C","images":null,"translation":{"question":"假设投资函数为 I = 1,000 – 30r，其中 r 为实际利率（以百分比计）。进一步假设名义利率为 10%，通胀率为 2%。根据投资函数，投资将为：","options":["240。","700。","760。","970。"]},"topics":["national-income"]},{"num":69,"type":"mc","question":"The investment function slopes ______ because there are ______ investment projects that are profitable as the interest rate decreases.","options":["upward; fewer","upward; more","downward; fewer","downward; more"],"answer":"D","images":null,"translation":{"question":"投资函数 ______ 倾斜，因为随着利率下降，可盈利的投资项目 ______。","options":["向上；更少","向上；更多","向下；更少","向下；更多"]},"topics":["national-income"]},{"num":70,"type":"mc","question":"The government purchases component of GDP includes all of the following except:","options":["federal spending on goods.","state and local spending on goods.","federal spending on transfer payments.","federal spending on services."],"answer":"C","images":null,"translation":{"question":"GDP 中的政府购买部分包括以下所有各项，除了：","options":["联邦政府在商品上的支出。","州和地方政府在商品上的支出。","联邦政府在转移支付上的支出。","联邦政府在服务上的支出。"]},"topics":["national-income"]},{"num":71,"type":"mc","question":"If government purchases exceed taxes minus transfer payments, then the government budget is:","options":["balanced.","in deficit.","in surplus.","endogenous."],"answer":"B","images":null,"translation":{"question":"如果政府购买超过税收减去转移支付，那么政府预算处于：","options":["平衡。","赤字。","盈余。","内生状态。"]},"topics":["national-income"]},{"num":72,"type":"mc","question":"All of the following actions increase government purchases of goods and services except the:","options":["federal government's sending a Social Security check to Betty Jones.","federal government's sending a paycheck to the president of the United States.","federal government's buying a Patriot missile.","city of Boston's buying a library book."],"answer":"A","images":null,"translation":{"question":"以下行为都会增加政府对商品和服务的购买，除了：","options":["联邦政府向贝蒂·琼斯寄出一张社会保障支票。","联邦政府向美国总统发放工资。","联邦政府购买一枚爱国者导弹。","波士顿市购买一本图书馆藏书。"]},"topics":["national-income"]},{"num":73,"type":"mc","question":"Government transfer payments:","options":["are included as part of government purchases, G.","can be viewed as negative tax payments, T.","are received as payment for inputs in the factor market.","do not affect the level of public or private saving."],"answer":"B","images":null,"translation":{"question":"政府转移支付：","options":["作为政府购买 G 的一部分计入。","可以视为负的税收 T。","作为要素市场中的投入品报酬被接收。","不影响公共或私人储蓄的水平。"]},"topics":["national-income"]},{"num":74,"type":"mc","question":"In examining the impact of fiscal policy, it is assumed that:","options":["consumption, investment, and the interest rate are endogenous variables.","consumption, investment, and the interest rate are exogenous variables.","government purchases, taxes, and interest rates are endogenous variables.","government purchases, taxes, and interest rates are exogenous variables."],"answer":"A","images":null,"translation":{"question":"在考察财政政策的影响时，假设：","options":["消费、投资和利率是内生变量。","消费、投资和利率是外生变量。","政府购买、税收和利率是内生变量。","政府购买、税收和利率是外生变量。"]},"topics":["national-income"]},{"num":75,"type":"mc","question":"In a classical model with fixed factors of production and flexible prices, the amount of consumption spending depends on _____ , the amount of investment spending depends on _____, and the amount of government spending is determined _____.","options":["the interest rate; disposable income; by tax revenue","the real wage; the real rental price of capital; by factor prices","labor's share of output; capital's share of output; by the interest rate","disposable income; the interest rate; exogenously"],"answer":"D","images":null,"translation":{"question":"在生产要素固定、价格具有弹性的古典模型中，消费支出的数量取决于 ______，投资支出的数量取决于 ______，政府支出的数量是 ______ 决定的。","options":["利率；可支配收入；由税收收入","实际工资；资本的实际租赁价格；由要素价格","劳动占产出的份额；资本占产出的份额；由利率","可支配收入；利率；外生地"]},"topics":["national-income"]},{"num":76,"type":"mc","question":"In the classical model with fixed output, the supply and demand for goods and services are balanced by:","options":["government spending.","taxes.","fiscal policy.","the interest rate."],"answer":"D","images":null,"translation":{"question":"在固定产出的古典模型中，商品和服务的供求通过以下哪项达到平衡：","options":["政府支出。","税收。","财政政策。","利率。"]},"topics":["national-income"]},{"num":77,"type":"mc","question":"The demand for the economy's output:","options":["is always equal to the supply, regardless of the interest rate.","may be computed provided that we know disposable income.","is equal to consumption, investment, and government purchases.","is determined by government purchases and taxes."],"answer":"C","images":null,"translation":{"question":"对经济产出的需求：","options":["无论利率如何，总是等于供给。","只要知道可支配收入就可以计算出来。","等于消费、投资和政府购买之和。","由政府购买和税收决定。"]},"topics":["national-income"]},{"num":78,"type":"mc","question":"In the classical model with fixed income, if the demand for goods and services is less than the supply, the interest rate will:","options":["increase.","decrease.","remain unchanged.","either increase or decrease, depending on whether consumption is greater or less than investment."],"answer":"B","images":null,"translation":{"question":"在固定收入的古典模型中，如果商品和服务的需求小于供给，利率将：","options":["上升。","下降。","保持不变。","或升或降，取决于消费是大于还是小于投资。"]},"topics":["national-income"]},{"num":79,"type":"mc","question":"In the classical model with fixed income, if the demand for goods and services is greater than the supply, the interest rate will:","options":["increase.","decrease.","remain unchanged.","either increase or decrease, depending on whether consumption is greater or less than investment."],"answer":"A","images":null,"translation":{"question":"在固定收入的古典模型中，如果商品和服务的需求大于供给，利率将：","options":["上升。","下降。","保持不变。","或升或降，取决于消费是大于还是小于投资。"]},"topics":["national-income"]},{"num":80,"type":"mc","question":"In the classical model with fixed income, if the interest rate is too low, then investment is too ______, and the demand for output ______ the supply.","options":["high; exceeds","high; falls short of","low; exceeds","low; falls short of"],"answer":"A","images":null,"translation":{"question":"在固定收入的古典模型中，如果利率过低，那么投资过 ______，产出需求 ______ 供给。","options":["高；超过","高；低于","低；超过","低；低于"]},"topics":["national-income"]},{"num":81,"type":"mc","question":"In the classical model with fixed income, if the interest rate is too high, then investment is too ______, and the demand for output ______ the supply.","options":["high; exceeds","high; falls short of","low; exceeds","low; falls short of"],"answer":"D","images":null,"translation":{"question":"在固定收入的古典模型中，如果利率过高，那么投资过 ______，产出需求 ______ 供给。","options":["高；超过","高；低于","低；超过","低；低于"]},"topics":["national-income"]},{"num":82,"type":"mc","question":"National saving refers to:","options":["disposable income minus consumption.","taxes minus government spending.","income minus consumption minus government purchases.","income minus investment."],"answer":"C","images":null,"translation":{"question":"国民储蓄指的是：","options":["可支配收入减去消费。","税收减去政府支出。","收入减去消费再减去政府购买。","收入减去投资。"]},"topics":["national-income"]},{"num":83,"type":"mc","question":"Public saving:","options":["is always positive.","is the overall level of household wealth held in government bonds.","is decided by the Federal Reserve.","depends on the government's tax collections relative to its expenditures."],"answer":"D","images":null,"translation":{"question":"公共储蓄：","options":["总是为正。","是家庭以政府债券形式持有的总财富水平。","由美联储决定。","取决于政府征税相对于其支出的情况。"]},"topics":["national-income"]},{"num":84,"type":"mc","question":"In a closed economy, Y – C – G equals:","options":["national saving.","private saving.","public saving.","financial saving."],"answer":"A","images":null,"translation":{"question":"在封闭经济中，Y – C – G 等于：","options":["国民储蓄。","私人储蓄。","公共储蓄。","金融储蓄。"]},"topics":["national-income"]},{"num":85,"type":"mc","question":"In a closed economy, private saving equals:","options":["Y – C – G.","Y – T – C.","Y – I – C.","Y – T."],"answer":"B","images":null,"translation":{"question":"在封闭经济中，私人储蓄等于：","options":["Y – C – G。","Y – T – C。","Y – I – C。","Y – T。"]},"topics":["national-income"]},{"num":86,"type":"mc","question":"The factor that makes national saving equal investment, in equilibrium, is:","options":["the interest rate.","private saving.","public saving.","fiscal policy."],"answer":"A","images":null,"translation":{"question":"在均衡状态下，使国民储蓄等于投资的因素是：","options":["利率。","私人储蓄。","公共储蓄。","财政政策。"]},"topics":["national-income"]},{"num":87,"type":"mc","question":"Private saving is:","options":["income minus consumption minus government spending.","disposable income minus consumption.","disposable income minus government spending.","taxes minus government spending."],"answer":"B","images":null,"translation":{"question":"私人储蓄是：","options":["收入减去消费再减去政府支出。","可支配收入减去消费。","可支配收入减去政府支出。","税收减去政府支出。"]},"topics":["national-income"]},{"num":88,"type":"mc","question":"Public saving is:","options":["income minus consumption minus government spending.","disposable income minus consumption.","disposable income minus government spending.","government revenue minus government spending."],"answer":"D","images":null,"translation":{"question":"公共储蓄是：","options":["收入减去消费再减去政府支出。","可支配收入减去消费。","可支配收入减去政府支出。","政府收入减去政府支出。"]},"topics":["national-income"]},{"num":89,"type":"mc","question":"National saving is:","options":["private saving.","public saving.","private saving plus public saving.","private saving minus public saving."],"answer":"C","images":null,"translation":{"question":"国民储蓄是：","options":["私人储蓄。","公共储蓄。","私人储蓄加公共储蓄。","私人储蓄减公共储蓄。"]},"topics":["national-income"]},{"num":90,"type":"mc","question":"If disposable income is 4,000, consumption is 3,500, government purchases is 1,000, and taxes minus transfers are 800, national saving is equal to:","options":["300.","500.","700.","1,000."],"answer":"A","images":null,"translation":{"question":"如果可支配收入为 4,000，消费为 3,500，政府购买为 1,000，税收减去转移支付为 800，那么国民储蓄等于：","options":["300。","500。","700。","1,000。"]},"topics":["national-income"]},{"num":91,"type":"mc","question":"If income is 4,800, consumption is 3,500, government spending is 1,000, and taxes minus transfers are 800, private saving is:","options":["300.","500.","1,000.","1,300."],"answer":"B","images":null,"translation":{"question":"如果收入为 4,800，消费为 3,500，政府支出为 1,000，税收减去转移支付为 800，那么私人储蓄为：","options":["300。","500。","1,000。","1,300。"]},"topics":["national-income"]},{"num":92,"type":"mc","question":"If income is 4,800, consumption is 3,500, government purchases is 1,000, and taxes minus transfers are 800, public saving is:","options":["–200.","200.","500.","1,800."],"answer":"A","images":null,"translation":{"question":"如果收入为 4,800，消费为 3,500，政府购买为 1,000，税收减去转移支付为 800，那么公共储蓄为：","options":["−200。","200。","500。","1,800。"]},"topics":["national-income"]},{"num":93,"type":"mc","question":"In equilibrium, total investment equals:","options":["private saving.","public saving.","national saving.","household saving."],"answer":"C","images":null,"translation":{"question":"在均衡状态下，总投资等于：","options":["私人储蓄。","公共储蓄。","国民储蓄。","家庭储蓄。"]},"topics":["national-income"]},{"num":94,"type":"mc","question":"The demand for loanable funds is equivalent to:","options":["national saving.","private saving.","public saving.","investment."],"answer":"D","images":null,"translation":{"question":"可贷资金的需求等同于：","options":["国民储蓄。","私人储蓄。","公共储蓄。","投资。"]},"topics":["national-income"]},{"num":95,"type":"mc","question":"The supply of loanable funds is equivalent to:","options":["national saving.","private saving.","public saving.","investment."],"answer":"A","images":null,"translation":{"question":"可贷资金的供给等同于：","options":["国民储蓄。","私人储蓄。","公共储蓄。","投资。"]},"topics":["national-income"]},{"num":96,"type":"mc","question":"The supply and demand for loanable funds determine the:","options":["real wage.","real rental price of capital.","real interest rate.","nominal interest rate."],"answer":"C","images":null,"translation":{"question":"可贷资金的供求决定：","options":["实际工资。","资本的实际租赁价格。","实际利率。","名义利率。"]},"topics":["national-income"]},{"num":97,"type":"mc","question":"If saving exceeds investment demand and consumption is not a function of the interest rate:","options":["the demand for loans exceeds the supply of loans.","the interest rate will fall.","the interest rate will rise.","saving will fall."],"answer":"B","images":null,"translation":{"question":"如果储蓄超过投资需求，且消费不是利率的函数：","options":["贷款需求超过贷款供给。","利率将下降。","利率将上升。","储蓄将下降。"]},"topics":["national-income"]},{"num":98,"type":"mc","question":"In the classical model with fixed income, if households want to save more than firms want to invest, then:","options":["the interest rate rises.","the interest rate falls.","output increases.","output falls."],"answer":"B","images":null,"translation":{"question":"在固定收入的古典模型中，如果家庭想储蓄的数额多于企业想投资的数额，那么：","options":["利率上升。","利率下降。","产出增加。","产出下降。"]},"topics":["national-income"]},{"num":99,"type":"mc","question":"When the demand for loanable funds exceeds the supply of loanable funds, households want to save ______ than firms want to invest, and the interest rate ______.","options":["more; rises","more; falls","less; rises","less; falls"],"answer":"C","images":null,"translation":{"question":"当可贷资金的需求超过可贷资金的供给时，家庭想储蓄的数额 ______ 于企业想投资的数额，利率 ______。","options":["多；上升","多；下降","少；上升","少；下降"]},"topics":["national-income"]},{"num":100,"type":"mc","question":"Assume that equilibrium GDP (Y) is 5,000. Consumption (C) is given by the equation C = 500 + 0.6Y. In addition, assume G=0. In this case, equilibrium investment is:","options":["1,500.","2,000.","2,500.","3,000."],"answer":"A","images":null,"translation":{"question":"假设均衡 GDP (Y) 为 5,000。消费 (C) 由方程 C = 500 + 0.6Y 给出。此外，假设 G = 0。在这种情况下，均衡投资为：","options":["1,500。","2,000。","2,500。","3,000。"]},"topics":["national-income"]},{"num":101,"type":"mc","question":"Assume that equilibrium GDP (Y) is 5,000. Consumption (C) is given by the equation C = 500 + 0.6(Y – T). Taxes (T) are equal to 1,000. Government spending is 600. In this case, equilibrium investment is:","options":["600.","1,100.","1,500.","2,200."],"answer":"C","images":null,"translation":{"question":"假设均衡 GDP (Y) 为 5,000。消费 (C) 由方程 C = 500 + 0.6(Y – T) 给出。税收 (T) 等于 1,000。政府支出为 600。在这种情况下，均衡投资为：","options":["600。","1,100。","1,500。","2,200。"]},"topics":["national-income"]},{"num":102,"type":"mc","question":"Assume that equilibrium GDP (Y) is 5,000. Consumption (C) is given by the equation C = 500 + 0.6Y. Investment (I) is given by the equation I = 2,000 – 100r, where r is the real interest rate, in percent. In addition, assume that G=0. In this case, the equilibrium real interest rate is:","options":["2 percent.","5 percent.","10 percent.","20 percent."],"answer":"B","images":null,"translation":{"question":"假设均衡 GDP (Y) 为 5,000。消费 (C) 由方程 C = 500 + 0.6Y 给出。投资 (I) 由方程 I = 2,000 – 100r 给出，其中 r 为实际利率（以百分比计）。此外，假设 G = 0。在这种情况下，均衡实际利率为：","options":["2%。","5%。","10%。","20%。"]},"topics":["national-income"]},{"num":103,"type":"mc","question":"Assume that equilibrium GDP (Y) is 5,000. Consumption (C) is given by the equation C = 500 + 0.6(Y – T). Taxes (T) are equal to 600. Government spending is equal to 1,000. Investment is given by the equation I = 2,160 – 100r, where r is the real interest rate, in percent. In this case, the equilibrium real interest rate is:","options":["5 percent.","8 percent.","10 percent.","13 percent."],"answer":"D","images":null,"translation":{"question":"假设均衡 GDP (Y) 为 5,000。消费 (C) 由方程 C = 500 + 0.6(Y – T) 给出。税收 (T) 等于 600。政府支出等于 1,000。投资由方程 I = 2,160 – 100r 给出，其中 r 为实际利率（以百分比计）。在这种情况下，均衡实际利率为：","options":["5%。","8%。","10%。","13%。"]},"topics":["national-income"]},{"num":104,"type":"mc","question":"According to the model developed in Chapter 3, when government spending increases without a change in taxes:","options":["consumption increases.","consumption decreases.","investment increases.","investment decreases."],"answer":"D","images":null,"translation":{"question":"根据第 3 章建立的模型，当政府支出增加而税收不变时：","options":["消费增加。","消费减少。","投资增加。","投资减少。"]},"topics":["national-income"]},{"num":105,"type":"mc","question":"According to the model developed in Chapter 3, when taxes decrease without a change in government spending:","options":["consumption and investment both increase.","consumption and investment both decrease.","consumption increases and investment decreases.","consumption decreases and investment increases."],"answer":"C","images":null,"translation":{"question":"根据第 3 章建立的模型，当税收减少而政府支出不变时：","options":["消费和投资都增加。","消费和投资都减少。","消费增加而投资减少。","消费减少而投资增加。"]},"topics":["national-income"]},{"num":106,"type":"mc","question":"According to the model developed in Chapter 3, when government spending increases and taxes increase by an equal amount:","options":["consumption and investment both increase.","consumption and investment both decrease.","consumption increases and investment decreases.","consumption decreases and investment increases."],"answer":"B","images":null,"translation":{"question":"根据第 3 章建立的模型，当政府支出增加且税收以相同数额增加时：","options":["消费和投资都增加。","消费和投资都减少。","消费增加而投资减少。","消费减少而投资增加。"]},"topics":["national-income"]},{"num":107,"type":"mc","question":"According to the model developed in Chapter 3, when government spending increases but taxes stay the same, interest rates:","options":["increase.","are unchanged.","decrease.","can vary."],"answer":"A","images":null,"translation":{"question":"根据第 3 章建立的模型，当政府支出增加但税收保持不变时，利率：","options":["上升。","不变。","下降。","可能变动。"]},"topics":["national-income"]},{"num":108,"type":"mc","question":"According to the model developed in Chapter 3, when taxes are increased but government spending is unchanged, interest rates:","options":["increase.","are unchanged.","decrease.","can vary wildly."],"answer":"C","images":null,"translation":{"question":"根据第 3 章建立的模型，当税收增加但政府支出不变时，利率：","options":["上升。","不变。","下降。","可能剧烈变动。"]},"topics":["national-income"]},{"num":109,"type":"mc","question":"In a closed economy with fixed output, when government spending increases:","options":["private saving decreases.","private saving increases.","public saving decreases.","public saving increases."],"answer":"C","images":null,"translation":{"question":"在固定产出的封闭经济中，当政府支出增加时：","options":["私人储蓄减少。","私人储蓄增加。","公共储蓄减少。","公共储蓄增加。"]},"topics":["national-income"]},{"num":110,"type":"mc","question":"In the neoclassical model with fixed income, if there is a decrease in government spending with no change in taxes, then public saving ______ and private saving ______.","options":["increases; increases","increases; does not change","decreases; increases","decreases; does not change"],"answer":"B","images":null,"translation":{"question":"在固定收入的新古典模型中，如果政府支出减少而税收不变，那么公共储蓄 ______，私人储蓄 ______。","options":["增加；增加","增加；不变","减少；增加","减少；不变"]},"topics":["national-income"]},{"num":111,"type":"mc","question":"Crowding out occurs when an increase in government spending ______ the interest rate and investment ______.","options":["increases; increases","increases; decreases","decreases; increases","decreases; decreases"],"answer":"B","images":null,"translation":{"question":"当政府支出增加 ______ 利率且投资 ______ 时，就会发生挤出效应。","options":["提高；增加","提高；减少","降低；增加","降低；减少"]},"topics":["national-income"]},{"num":112,"type":"mc","question":"The reduction in investment brought about by the increase in the interest rate caused by increased government spending is called:","options":["a budget deficit.","fiscal policy.","the identification problem.","crowding out."],"answer":"D","images":null,"translation":{"question":"由政府支出增加引起利率上升而导致的投资减少被称为：","options":["预算赤字。","财政政策。","识别问题。","挤出。"]},"topics":["national-income"]},{"num":113,"type":"mc","question":"In the classical model with fixed income, an increase in the real interest rate could be the result of:","options":["an increase in government spending.","a decrease in government spending.","a decrease in desired investment.","an increase in taxes."],"answer":"A","images":null,"translation":{"question":"在固定收入的古典模型中，实际利率的上升可能是以下哪项的结果：","options":["政府支出增加。","政府支出减少。","合意投资减少。","税收增加。"]},"topics":["national-income"]},{"num":114,"type":"mc","question":"In the classical model with fixed income a decrease in the real interest rate could be the result of:","options":["an increase in government spending.","an increase in desired investment.","an increase in taxes.","a decrease in taxes."],"answer":"C","images":null,"translation":{"question":"在固定收入的古典模型中，实际利率的下降可能是以下哪项的结果：","options":["政府支出增加。","合意投资增加。","税收增加。","税收减少。"]},"topics":["national-income"]},{"num":115,"type":"mc","question":"In the classical model with fixed income, a reduction in the government budget deficit will lead to a:","options":["higher real interest rate.","lower real interest rate.","higher level of output.","lower level of output."],"answer":"B","images":null,"translation":{"question":"在固定收入的古典模型中，政府预算赤字的减少将导致：","options":["更高的实际利率。","更低的实际利率。","更高的产出水平。","更低的产出水平。"]},"topics":["national-income"]},{"num":116,"type":"mc","question":"When government spending increases and taxes are increased by an equal amount, interest rates:","options":["increase.","remain the same.","decrease.","can vary wildly."],"answer":"A","images":null,"translation":{"question":"当政府支出增加且税收以相同数额增加时，利率：","options":["上升。","保持不变。","下降。","可能剧烈变动。"]},"topics":["national-income"]},{"num":117,"type":"mc","question":"In the neoclassical model with fixed income, if there is a decrease in taxes with no change in government spending, then public saving ______ and private saving ______.","options":["increases; increases","increases; decreases","decreases; increases","decreases; does not change"],"answer":"C","images":null,"translation":{"question":"在固定收入的新古典模型中，如果税收减少而政府支出不变，那么公共储蓄 ______，私人储蓄 ______。","options":["增加；增加","增加；减少","减少；增加","减少；不变"]},"topics":["national-income"]},{"num":118,"type":"mc","question":"Exhibit: Saving, Investment, and the Interest Rate 1 The economy begins in equilibrium at point E, representing the real interest rate r1 at which saving S1 equals desired investment I1. What will be the new equilibrium combination of real interest rate, saving, and investment if the government cuts spending, holding other factors constant?","options":["point A","point B","point C","point D"],"answer":"B","images":null,"translation":{"question":"展表：储蓄、投资与利率 1。经济从点 E 的均衡开始，点 E 代表实际利率 r1，在该利率下储蓄 S1 等于合意投资 I1。如果政府在其他因素不变的情况下削减支出，新的实际利率、储蓄和投资的均衡组合将是哪一点？","options":["点 A","点 B","点 C","点 D"]},"topics":["national-income"]},{"num":119,"type":"mc","question":"Exhibit: Saving, Investment, and the Interest Rate 1 The economy begins in equilibrium at point E, representing the real interest rate r1 at which saving S1 equals desired investment I1. What will be the new equilibrium combination of real interest rate, saving, and investment if the government cuts taxes, holding other factors constant?","options":["point A","point B","point C","point D"],"answer":"A","images":["c3_img0.png"],"translation":{"question":"展表：储蓄、投资与利率 1。经济从点 E 的均衡开始，点 E 代表实际利率 r1，在该利率下储蓄 S1 等于合意投资 I1。如果政府在其他因素不变的情况下减税，新的实际利率、储蓄和投资的均衡组合将是哪一点？","options":["点 A","点 B","点 C","点 D"]},"topics":["national-income"]},{"num":120,"type":"mc","question":"Exhibit: Saving, Investment, and the Interest Rate 1 The economy begins in equilibrium at point E, representing the real interest rate r1 at which saving S1 equals desired investment I1. What will be the new equilibrium combination of real interest rate, saving, and investment if the government increases spending, holding other factors constant?","options":["point A","point B","point C","point D"],"answer":"A","images":["c3_img1.png"],"translation":{"question":"展表：储蓄、投资与利率 1。经济从点 E 的均衡开始，点 E 代表实际利率 r1，在该利率下储蓄 S1 等于合意投资 I1。如果政府在其他因素不变的情况下增加支出，新的实际利率、储蓄和投资的均衡组合将是哪一点？","options":["点 A","点 B","点 C","点 D"]},"topics":["national-income"]},{"num":121,"type":"mc","question":"Exhibit: Saving, Investment, and the Interest Rate 1 The economy begins in equilibrium at point E, representing the real interest rate r1 at which saving S1 equals desired investment I1. What will be the new equilibrium combination of real interest rate, saving, and investment if the government raises taxes, holding other factors constant?","options":["point A","point B","point C","point D"],"answer":"B","images":["c3_img2.png"],"translation":{"question":"展表：储蓄、投资与利率 1。经济从点 E 的均衡开始，点 E 代表实际利率 r1，在该利率下储蓄 S1 等于合意投资 I1。如果政府在其他因素不变的情况下提高税收，新的实际利率、储蓄和投资的均衡组合将是哪一点？","options":["点 A","点 B","点 C","点 D"]},"topics":["national-income"]},{"num":122,"type":"mc","question":"Use the model developed in Chapter 3 and assume that consumption does not depend on the interest rate. Holding other things constant, when the government lowers taxes on business investment, thus increasing investment demand, the quantity of investment:","options":["increases and the interest rate rises.","is unchanged and the interest rate rises.","and the interest rate are both unchanged.","decreases and the interest rate rises."],"answer":"D","images":["c3_img3.png"],"translation":{"question":"使用第 3 章建立的模型，并假设消费不取决于利率。在其他条件不变的情况下，当政府降低对企业投资的税收，从而增加投资需求时，投资数量：","options":["增加且利率上升。","不变而利率上升。","和利率都不变。","减少且利率上升。"]},"topics":["national-income"]},{"num":123,"type":"mc","question":"When there is a fixed supply of loanable funds, an increase in investment demand results in:","options":["a higher interest rate.","a lower interest rate.","an increase in investment.","a decrease in investment."],"answer":"A","images":null,"translation":{"question":"当可贷资金供给固定时，投资需求的增加导致：","options":["更高的利率。","更低的利率。","投资增加。","投资减少。"]},"topics":["national-income"]},{"num":124,"type":"mc","question":"When saving (the supply of loanable funds) increases as the interest rate increases, an increase in investment demand results in a ______ interest rate and ______ in the quantity of investment.","options":["higher; no change","higher; an increase","lower; no change","lower; an increase"],"answer":"B","images":null,"translation":{"question":"当储蓄（可贷资金的供给）随利率上升而增加时，投资需求的增加导致利率 ______，投资数量 ______。","options":["更高；不变","更高；增加","更低；不变","更低；增加"]},"topics":["national-income"]},{"num":125,"type":"mc","question":"Suppose that GDP (Y) is 5,000. Consumption (C) is given by the equation C = 500 + 0.5(Y – T). Investment (I) is given by the equation I = 2,000 – 100r, where r is the real interest rate, in percent. Government spending (G) is 1,000, and taxes (T) is also 1,000. When a technological innovation changes the investment function to I = 3,000 – 100r:","options":["I rises by 1,000 and r rises by 10 percentage points.","I rises by 1,000 and r is unchanged.","I is unchanged and r rises by 10 percentage points.","I is unchanged and r rises by 15 percentage points."],"answer":"C","images":null,"translation":{"question":"假设 GDP (Y) 为 5,000。消费 (C) 由方程 C = 500 + 0.5(Y – T) 给出。投资 (I) 由方程 I = 2,000 – 100r 给出，其中 r 为实际利率（以百分比计）。政府支出 (G) 为 1,000，税收 (T) 也为 1,000。当一项技术创新使投资函数变为 I = 3,000 – 100r 时：","options":["I 增加 1,000，r 上升 10 个百分点。","I 增加 1,000，r 不变。","I 不变，r 上升 10 个百分点。","I 不变，r 上升 15 个百分点。"]},"topics":["national-income"]},{"num":126,"type":"mc","question":"Exhibit: Saving, Investment, and the Interest Rate 2 The economy begins in equilibrium at point E, representing the real interest rate r1 at which saving S1 equals desired investment I1. What will be the new equilibrium combination of real interest rate, saving, and investment if there is a technological innovation that increases the demand for investment goods?","options":["point A","point B","point C","point D"],"answer":"B","images":null,"translation":{"question":"展表：储蓄、投资与利率 2。经济从点 E 的均衡开始，点 E 代表实际利率 r1，在该利率下储蓄 S1 等于合意投资 I1。如果有一项技术创新增加了对投资品的需求，新的实际利率、储蓄和投资的均衡组合将是哪一点？","options":["点 A","点 B","点 C","点 D"]},"topics":["national-income"]},{"num":127,"type":"mc","question":"Exhibit: Saving, Investment, and the Interest Rate 2 The economy begins in equilibrium at point E, representing the real interest rate r1 at which saving S1 equals desired investment I1. What will be the new equilibrium combination of real interest rate, saving, and investment if there is a tax law change that makes investment projects less profitable and decreases the demand for investment goods (but does not change the amount of taxes collected in the economy)?","options":["point A","point B","point C","point D"],"answer":"A","images":["c3_img4.png"],"translation":{"question":"展表：储蓄、投资与利率 2。经济从点 E 的均衡开始，点 E 代表实际利率 r1，在该利率下储蓄 S1 等于合意投资 I1。如果一项税法变动使投资项目利润下降并减少了对投资品的需求（但不改变经济中征收的税收数额），新的实际利率、储蓄和投资的均衡组合将是哪一点？","options":["点 A","点 B","点 C","点 D"]},"topics":["national-income"]},{"num":128,"type":"mc","question":"If increased immigration raises the labor force, the neoclassical theory of distribution predicts that:","options":["the real wage will rise, and the real rental price of capital will fall.","both the real wage and the real rental price of capital will fall.","both the real wage and the real rental price of capital will rise.","the real wage will fall, and the real rental price of capital will rise."],"answer":"D","images":["c3_img5.png"],"translation":{"question":"如果增加的移民使劳动力增加，新古典分配理论预测：","options":["实际工资将上升，资本的实际租赁价格将下降。","实际工资和资本的实际租赁价格都将下降。","实际工资和资本的实际租赁价格都将上升。","实际工资将下降，资本的实际租赁价格将上升。"]},"topics":["national-income"]},{"num":129,"type":"mc","question":"If an earthquake destroys some of the capital stock, the neoclassical theory of distribution predicts that:","options":["the real wage will rise, and the real rental price of capital will fall.","both the real wage and the real rental price of capital will fall.","both the real wage and the real rental price of capital will rise.","the real wage will fall, and the real rental price of capital will rise."],"answer":"D","images":null,"translation":{"question":"如果地震摧毁了部分资本存量，新古典分配理论预测：","options":["实际工资将上升，资本的实际租赁价格将下降。","实际工资和资本的实际租赁价格都将下降。","实际工资和资本的实际租赁价格都将上升。","实际工资将下降，资本的实际租赁价格将上升。"]},"topics":["national-income"]},{"num":130,"type":"mc","question":"If a technological advancement increases productivity, the neoclassical theory of distribution predicts that:","options":["the real wage will rise, and the real rental price of capital will fall.","both the real wage and the real rental price of capital will fall.","both the real wage and the real rental price of capital will rise.","the real wage will fall, and the real rental price of capital will rise."],"answer":"C","images":null,"translation":{"question":"如果技术进步提高了生产率，新古典分配理论预测：","options":["实际工资将上升，资本的实际租赁价格将下降。","实际工资和资本的实际租赁价格都将下降。","实际工资和资本的实际租赁价格都将上升。","实际工资将下降，资本的实际租赁价格将上升。"]},"topics":["national-income"]},{"num":131,"type":"mc","question":"An example of decreasing returns to scale is when capital and labor inputs:","options":["both increase 10 percent and output increases 5 percent.","both increase 10 percent and output increases 10 percent.","both increase 5 percent and output increases 10 percent.","do not change and output increases 5 percent."],"answer":"A","images":null,"translation":{"question":"规模报酬递减的一个例子是当资本和劳动投入：","options":["都增加 10% 而产出增加 5%。","都增加 10% 而产出增加 10%。","都增加 5% 而产出增加 10%。","不变而产出增加 5%。"]},"topics":["cobb-douglas"]},{"num":132,"type":"mc","question":"An example of increasing returns to scale is when capital and labor inputs:","options":["both increase 10 percent and output increases 5 percent.","both increase 10 percent and output increases 10 percent.","both increase 5 percent and output increases 10 percent.","do not change and output decreases 5 percent."],"answer":"C","images":null,"translation":{"question":"规模报酬递增的一个例子是当资本和劳动投入：","options":["都增加 10% 而产出增加 5%。","都增加 10% 而产出增加 10%。","都增加 5% 而产出增加 10%。","不变而产出减少 5%。"]},"topics":["cobb-douglas"]},{"num":133,"type":"mc","question":"If the productivity of farmers has risen substantially over time because of technological progress, and workers can move freely between being farmers and barbers, the neoclassical theory of distribution predicts that the real wages of:","options":["both barbers and farmers should have remained constant over time.","both barbers and farmers should have risen over time.","farmers should have risen while the real wage of barbers should have remained constant.","barbers should have risen while the real wage of farmers should have remained constant."],"answer":"B","images":null,"translation":{"question":"如果由于技术进步，农民的生产率随着时间大幅提高，并且工人可以在农民和理发师之间自由流动，新古典分配理论预测：","options":["理发师和农民的实际工资都应随时间保持不变。","理发师和农民的实际工资都应随时间上升。","农民的实际工资应上升，而理发师的实际工资应保持不变。","理发师的实际工资应上升，而农民的实际工资应保持不变。"]},"topics":["national-income"]},{"num":134,"type":"mc","question":"The government raises lump-sum taxes on income by $100 billion, and the neoclassical economy adjusts so that output does not change. If the marginal propensity to consume is 0.6, private saving:","options":["rises by $40 billion.","rises by $60 billion.","falls by $60 billion.","falls by $40 billion."],"answer":"D","images":null,"translation":{"question":"政府将收入上的一次性税收提高 1,000 亿美元，新古典经济随之调整，使产出不变。如果边际消费倾向为 0.6，那么私人储蓄：","options":["增加 400 亿美元。","增加 600 亿美元。","减少 600 亿美元。","减少 400 亿美元。"]},"topics":["national-income"]},{"num":135,"type":"mc","question":"The government raises lump-sum taxes on income by $100 billion, and the neoclassical economy adjusts so that output does not change. If the marginal propensity to consume is 0.6, public saving:","options":["rises by $100 billion.","rises by $60 billion.","falls by $60 billion.","falls by $100 billion."],"answer":"A","images":null,"translation":{"question":"政府将收入上的一次性税收提高 1,000 亿美元，新古典经济随之调整，使产出不变。如果边际消费倾向为 0.6，那么公共储蓄：","options":["增加 1,000 亿美元。","增加 600 亿美元。","减少 600 亿美元。","减少 1,000 亿美元。"]},"topics":["national-income"]},{"num":136,"type":"mc","question":"The government raises lump-sum taxes on income by $100 billion, and the neoclassical economy adjusts so that output does not change. If the marginal propensity to consume is 0.6, national saving:","options":["rises by $100 billion.","rises by $60 billion.","falls by $60 billion.","falls by $100 billion."],"answer":"B","images":null,"translation":{"question":"政府将收入上的一次性税收提高 1,000 亿美元，新古典经济随之调整，使产出不变。如果边际消费倾向为 0.6，那么国民储蓄：","options":["增加 1,000 亿美元。","增加 600 亿美元。","减少 600 亿美元。","减少 1,000 亿美元。"]},"topics":["national-income"]},{"num":137,"type":"mc","question":"The government raises lump-sum taxes on income by $100 billion, and the neoclassical economy adjusts so that output does not change. If the marginal propensity to consume is 0.6, investment:","options":["rises by $100 billion.","rises by $60 billion.","falls by $60 billion.","falls by $100 billion."],"answer":"B","images":null,"translation":{"question":"政府将收入上的一次性税收提高 1,000 亿美元，新古典经济随之调整，使产出不变。如果边际消费倾向为 0.6，那么投资：","options":["增加 1,000 亿美元。","增加 600 亿美元。","减少 600 亿美元。","减少 1,000 亿美元。"]},"topics":["national-income"]},{"num":138,"type":"mc","question":"Assume that an increase in consumer confidence raises consumers' expectations of future income and thus the amount they want to consume today for any given level of disposable income. This shift, in a neoclassical economy, will:","options":["lower investment and raise the interest rate.","raise investment and lower the interest rate.","lower both investment and the interest rate.","raise both investment and the interest rate."],"answer":"A","images":null,"translation":{"question":"假设消费者信心的提高提高了消费者对未来收入的预期，从而在任何给定可支配收入水平下，他们今天想要消费的数额增加。在新古典经济中，这一移动将：","options":["降低投资并提高利率。","提高投资并降低利率。","同时降低投资和利率。","同时提高投资和利率。"]},"topics":["national-income"]},{"num":139,"type":"mc","question":"In a neoclassical economy, assume that the government lowers both government spending and taxes by the same amount. This causes:","options":["investment to fall and the interest rate to rise.","investment to rise and the interest rate to fall.","investment and the interest rate to both fall.","investment and the interest rate to both rise."],"answer":"B","images":null,"translation":{"question":"在新古典经济中，假设政府以相同数额同时降低政府支出和税收。这会导致：","options":["投资下降而利率上升。","投资上升而利率下降。","投资和利率都下降。","投资和利率都上升。"]},"topics":["national-income"]},{"num":140,"type":"mc","question":"In a neoclassical economy, assume that the government lowers both government spending and taxes by $100 billion. If the marginal propensity to consume is 0.6, investment will:","options":["rise by $100 billion.","rise by $60 billion.","rise by $40 billion.","not change."],"answer":"C","images":null,"translation":{"question":"在新古典经济中，假设政府把政府支出和税收都降低 1,000 亿美元。如果边际消费倾向为 0.6，那么投资将：","options":["增加 1,000 亿美元。","增加 600 亿美元。","增加 400 亿美元。","不变。"]},"topics":["national-income"]},{"num":141,"type":"mc","question":"In a neoclassical economy, if consumption increases as the interest rate decreases, then a $10 billion rise in government spending would:","options":["still crowd out exactly $10 billion of investment.","crowd out between zero and $10 billion of investment.","not crowd out any investment.","crowd out more than $10 billion of investment."],"answer":"B","images":null,"translation":{"question":"在新古典经济中，如果消费随利率下降而增加，那么政府支出增加 100 亿美元将：","options":["仍恰好挤出 100 亿美元的投资。","挤出 0 到 100 亿美元之间的投资。","不会挤出任何投资。","挤出超过 100 亿美元的投资。"]},"topics":["national-income"]},{"num":142,"type":"mc","question":"Assume that the production function is Cobb–Douglas with parameter a = 0.3. If capital and labor are paid their marginal products, they receive the shares of income:","options":["0.3 and 0.3.","0.7 and 0.7.","0.3 and 0.7.","0.7 and 0.3."],"answer":"C","images":null,"translation":{"question":"假设生产函数为柯布-道格拉斯型，参数 a = 0.3。如果资本和劳动按其边际产品获得报酬，它们获得的收入份额为：","options":["0.3 和 0.3。","0.7 和 0.7。","0.3 和 0.7。","0.7 和 0.3。"]},"topics":["cobb-douglas"]},{"num":143,"type":"mc","question":"Assume that the production function is Cobb–Douglas with parameter a = 0.3. In the neoclassical model, if the labor force increases by 10 percent, then output:","options":["increases by about 10 percent.","increases by about 7 percent.","increases by about 3 percent.","does not increase since the new workers are unemployed."],"answer":"B","images":null,"translation":{"question":"假设生产函数为柯布-道格拉斯型，参数 a = 0.3。在新古典模型中，如果劳动力增加 10%，那么产出：","options":["约增加 10%。","约增加 7%。","约增加 3%。","不增加，因为新工人处于失业状态。"]},"topics":["cobb-douglas"]},{"num":144,"type":"sa","question":"In an economy with flexible prices, competitive factor markets, and fixed supplies of the factors of production, graphically illustrate the impact of a change in immigration policy in a country that permits a huge influx of foreign workers into the labor market, ceteris paribus. Be sure to label the axes, the curves, the initial equilibrium values, the direction the curve's shift, and the terminal equilibrium values. Explain in words how the equilibrium values of labor, the real wage, saving, investment, and the real interest rate change.","options":null,"answer":null,"images":null,"translation":{"question":"在一个价格有弹性、要素市场竞争、生产要素供给固定的经济中，用图形说明一国移民政策变动（允许大量外国工人涌入劳动力市场）在其他条件不变的情况下产生的影响。务必标注坐标轴、曲线、初始均衡值、曲线移动的方向和最终均衡值。用文字解释劳动、实际工资、储蓄、投资和实际利率的均衡值如何变化。","options":null},"topics":["national-income"],"answer_ref":"图形（要素市场与可贷资金市场）：劳动供给曲线因移民右移。实际工资从 W₁ 降到 W₂，就业 L₁→L₂ 增加；产出 Y=F(K,L) 上升。收入增加使国民储蓄增加，可贷资金供给曲线右移，实际利率 r₁→r₂ 下降，储蓄与投资 S₁→S₂ 增加。结论：劳动↑、实际工资↓、储蓄↑、投资↑、实际利率↓、产出↑。"},{"num":145,"type":"sa","question":"Assume that the production function is given by Y = AK0.5L0.5, where Y is GDP, K is capital stock, and L is labor. The parameter A is equal to 10. Assume also that capital is 100, labor is 400, and both capital and labor are paid for their marginal products. a. What is Y? b. What is the real wage of labor? c. What is the real rental price of capital (the amount of output paid per unit of capital)?","options":null,"answer":null,"images":null,"translation":{"question":"假设生产函数为 Y = AK0.5L0.5，其中 Y 为 GDP，K 为资本存量，L 为劳动。参数 A 等于 10。还假设资本为 100、劳动为 400，且资本和劳动都按其边际产品获得报酬。a. Y 是多少？b. 劳动的实际工资是多少？c. 资本的实际租赁价格（每单位资本所支付的产出数量）是多少？","options":null},"topics":["cobb-douglas","national-income"],"answer_ref":"a. Y = 10×100^0.5×400^0.5 = 10×10×20 = 2000。b. 实际工资 = MPL = 0.5·Y/L = 0.5×2000/400 = 2.5。c. 实际租赁价格 = MPK = 0.5·Y/K = 0.5×2000/100 = 10。"},{"num":146,"type":"sa","question":"Assume that GDP (Y) is 6,000. Consumption (C) is given by the equation C = 600 + 0.6(Y – T). Investment (I) is given by the equation I = 2,000 – 100r, where r is the real rate of interest, in percent. Taxes (T) are 500, and government spending (G) is also 500. a. What are the equilibrium values of C, I, and r? b. What are the values of private saving, public saving, and national saving? c. If government spending rises to 1,000, what are the new equilibrium values of C, I, and r? d. What are the new equilibrium values of private saving, public saving, and national saving?","options":null,"answer":null,"images":null,"translation":{"question":"假设 GDP (Y) 为 6,000。消费 (C) 由方程 C = 600 + 0.6(Y – T) 给出。投资 (I) 由方程 I = 2,000 – 100r 给出，其中 r 为实际利率（以百分比计）。税收 (T) 为 500，政府支出 (G) 也为 500。a. C、I 和 r 的均衡值是多少？b. 私人储蓄、公共储蓄和国民储蓄的值是多少？c. 如果政府支出上升到 1,000，C、I 和 r 的新均衡值是多少？d. 私人储蓄、公共储蓄和国民储蓄的新均衡值是多少？","options":null},"topics":["national-income"],"answer_ref":"a. C = 600 + 0.6×(6000−500) = 3900；I = Y−C−G = 6000−3900−500 = 1600；由 1600 = 2000−100r 得 r = 4%。b. 私人储蓄 = Y−T−C = 1600；公共储蓄 = T−G = 0；国民储蓄 = 1600。c. G=1000 时 C 不变=3900；I = 6000−3900−1000 = 1100；r = 9%。d. 私人储蓄 =1600；公共储蓄 = 500−1000 = −500；国民储蓄 = 1100。"},{"num":147,"type":"sa","question":"Assume that GDP (Y) is 5,000. Consumption (C) is given by the equation C = 1,000 + 0.3(Y – T). Investment (I) is given by the equation I = 1,500 – 50r, where r is the real interest rate, in percent. Taxes (T) are 1,000, and government spending (G) is 1,500. a. What are the equilibrium values of C, I, and r? b. What are the values of private saving, public saving, and national saving? c. Now assume there is a technological innovation that makes business want to invest more. It raises the investment equation to I = 2,000 – 50r. What are the new equilibrium values of C, I, and r? d. What are the new values of private saving, public saving, and national saving?","options":null,"answer":null,"images":null,"translation":{"question":"假设 GDP (Y) 为 5,000。消费 (C) 由方程 C = 1,000 + 0.3(Y – T) 给出。投资 (I) 由方程 I = 1,500 – 50r 给出，其中 r 为实际利率（以百分比计）。税收 (T) 为 1,000，政府支出 (G) 为 1,500。a. C、I 和 r 的均衡值是多少？b. 私人储蓄、公共储蓄和国民储蓄的值是多少？c. 现在假设有一项技术创新使企业想要更多投资。它把投资方程提高到 I = 2,000 – 50r。C、I 和 r 的新均衡值是多少？d. 私人储蓄、公共储蓄和国民储蓄的新值是多少？","options":null},"topics":["national-income"],"answer_ref":"a. C = 1000 + 0.3×(5000−1000) = 2200；I = 5000−2200−1500 = 1300；由 1300 = 1500−50r 得 r = 4%。b. 私人储蓄 = 5000−1000−2200 = 1800；公共储蓄 = 1000−1500 = −500；国民储蓄 = 1300。c. 技术创新使 I = 2000−50r：C 仍=2200，I = 5000−2200−1500 = 1300；由 1300 = 2000−50r 得 r = 14%。d. 储蓄各项不变：私人 1800、公共 −500、国民 1300（投资需求增加只推高利率，在储蓄固定时量不变）。"},{"num":148,"type":"sa","question":"Assume that GDP (Y) is 5,000. Consumption (C) is given by the equation C = 1,200 + 0.3(Y – T) – 50r, where r is the real interest rate, in percent. Investment (I) is given by the equation I = 1,500 – 50r. Taxes (T) are 1,000, and government spending (G) is 1,500. a. What are the equilibrium values of C, I, and r? b. What are the values of private saving, public saving, and national saving? c. Now assume there is a technological innovation that makes business want to invest more. It raises the investment equation to I = 2,000 – 50r. What are the new equilibrium values of C, I, and r? d. What are the new values of private saving, public saving, and national saving?","options":null,"answer":null,"images":null,"translation":{"question":"假设 GDP (Y) 为 5,000。消费 (C) 由方程 C = 1,200 + 0.3(Y – T) – 50r 给出，其中 r 为实际利率（以百分比计）。投资 (I) 由方程 I = 1,500 – 50r 给出。税收 (T) 为 1,000，政府支出 (G) 为 1,500。a. C、I 和 r 的均衡值是多少？b. 私人储蓄、公共储蓄和国民储蓄的值是多少？c. 现在假设有一项技术创新使企业想要更多投资。它把投资方程提高到 I = 2,000 – 50r。C、I 和 r 的新均衡值是多少？d. 私人储蓄、公共储蓄和国民储蓄的新值是多少？","options":null},"topics":["national-income"],"answer_ref":"a. C = 1200 + 0.3×4000 − 50r = 2400 − 50r；均衡条件 I = Y−C−G：1500−50r = 1100+50r，得 r = 4%，C = 2200，I = 1300。b. 私人储蓄 = 5000−1000−2200 = 1800；公共储蓄 = −500；国民储蓄 = 1300。c. 新投资方程：2000−50r = 1100+50r，得 r = 9%；C = 2400−450 = 1950；I = 1550。d. 私人储蓄 = 5000−1000−1950 = 2050；公共储蓄 = −500；国民储蓄 = 1550。"},{"num":149,"type":"sa","question":"a. Suppose a government moves to reduce a budget deficit. Using the long-run model of the economy developed in Chapter 3, graphically illustrate the impact of reducing a government's budget deficit by reducing government purchases. Be sure to label the axes, the curves, the initial equilibrium values, the direction curves shift, and the terminal equilibrium values. b. State in words what happens to (i) the real interest rate; (ii) national saving; (iii) investment; (iv) consumption; and (v) output.","options":null,"answer":null,"images":null,"translation":{"question":"a. 假设一个政府采取措施减少预算赤字。使用第 3 章建立的长期经济模型，用图形说明通过减少政府购买来减少政府预算赤字所产生的影响。务必标注坐标轴、曲线、初始均衡值、曲线移动的方向和最终均衡值。b. 用文字说明 (i) 实际利率；(ii) 国民储蓄；(iii) 投资；(iv) 消费；和 (v) 产出会发生什么变化。","options":null},"topics":["national-income"],"answer_ref":"a. 图：可贷资金市场，供给 S=国民储蓄（储蓄曲线右移），需求 I(r) 不变；r₁→r₂ 下降，S、I 由 I₁ 增至 I₂。b. (i) 实际利率下降；(ii) 国民储蓄增加；(iii) 投资增加；(iv) 消费不变（税收与收入未变）；(v) 产出不变（古典模型中要素固定、产出由供给决定）。"},{"num":150,"type":"sa","question":"a. Suppose a government moves to reduce a budget deficit. Using the long-run model of the economy developed in Chapter 3, graphically illustrate the impact of reducing a government's budget deficit by increasing (lump-sum) taxes on household income. Be sure to label the axes, the curves, the initial equilibrium values, the direction curves shift, and the terminal equilibrium values. b. State in words what happens to (i) the real interest rate; (ii) national saving; (iii) investment; (iv) consumption; and (v) output.","options":null,"answer":null,"images":null,"translation":{"question":"a. 假设一个政府采取措施减少预算赤字。使用第 3 章建立的长期经济模型，用图形说明通过提高对家庭收入的一次性税收来减少政府预算赤字所产生的影响。务必标注坐标轴、曲线、初始均衡值、曲线移动的方向和最终均衡值。b. 用文字说明 (i) 实际利率；(ii) 国民储蓄；(iii) 投资；(iv) 消费；和 (v) 产出会发生什么变化。","options":null},"topics":["national-income"],"answer_ref":"a. 图：提高一次性税收→可支配收入减少→消费下降 MPC·ΔT→私人储蓄减少 (1−MPC)·ΔT，但公共储蓄增加 ΔT，国民储蓄净增 MPC·ΔT，储蓄曲线右移；r 下降，投资增加。b. (i) r 下降；(ii) 国民储蓄增加 MPC·ΔT；(iii) 投资增加；(iv) 消费减少 MPC·ΔT；(v) 产出不变。"},{"num":151,"type":"sa","question":"a. Suppose a government education program succeeds in getting households to save more (you may interpret this as a downward shift in the consumption function). Using the long-run model of the economy developed in Chapter 3, graphically illustrate the impact of the higher saving rate by households. Be sure to label the axes, the curves, the initial equilibrium values, the direction curves shift, and the terminal equilibrium values. b. State in words what happens to (i) the real interest rate; (ii) national saving; (iii) investment; (iv) consumption; and (v) output.","options":null,"answer":null,"images":null,"translation":{"question":"a. 假设一项政府教育计划成功地让家庭储蓄更多（你可以把这解释为消费函数向下移动）。使用第 3 章建立的长期经济模型，用图形说明家庭储蓄率提高所产生的影响。务必标注坐标轴、曲线、初始均衡值、曲线移动的方向和最终均衡值。b. 用文字说明 (i) 实际利率；(ii) 国民储蓄；(iii) 投资；(iv) 消费；和 (v) 产出会发生什么变化。","options":null},"topics":["national-income"],"answer_ref":"a. 图：消费函数下移→私人储蓄与国民储蓄增加，储蓄曲线右移；r 下降，投资增加。b. (i) r 下降；(ii) 国民储蓄增加；(iii) 投资增加；(iv) 消费减少（储蓄率上升意味着消费相应下降）；(v) 产出不变。"},{"num":152,"type":"sa","question":"a. Suppose there is a technological breakthrough that increases the productivity of all capital and, consequently, increases the demand for investment. Assuming factors of production are fixed, use the long-run model of the economy developed in Chapter 3 to graphically illustrate the impact of the increased investment demand. Be sure to label the axes, the curves, the initial equilibrium values, the direction curves shift, and the terminal equilibrium values. b. State in words what happens to (i) the real interest rate; (ii) national saving; (iii) investment; (iv) consumption; and (v) output.","options":null,"answer":null,"images":null,"translation":{"question":"a. 假设有一项技术突破提高了所有资本的生产率，从而增加了投资需求。假设生产要素固定，使用第 3 章建立的长期经济模型，用图形说明投资需求增加所产生的影响。务必标注坐标轴、曲线、初始均衡值、曲线移动的方向和最终均衡值。b. 用文字说明 (i) 实际利率；(ii) 国民储蓄；(iii) 投资；(iv) 消费；和 (v) 产出会发生什么变化。","options":null},"topics":["national-income"],"answer_ref":"a. 图：投资需求曲线 I(r) 右移，储蓄供给（由收入和产出决定）不变；r₁→r₂ 上升，均衡投资量不变（仍等于国民储蓄）。b. (i) r 上升；(ii) 国民储蓄不变；(iii) 投资不变（储蓄决定投资量）；(iv) 消费不变；(v) 产出不变。本模型中只有利率调整出清可贷资金市场。"},{"num":153,"type":"sa","question":"a. Suppose a government decides to reduce spending and (lump-sum) income taxes by the same amount. Using the long-run model of the economy developed in Chapter 3, graphically illustrate the impact of the equal reductions in spending and taxes. Be sure to label the axes, the curves, the initial equilibrium values, the direction curves shift, and the terminal equilibrium values. b. State in words what happens to (i) the real interest rate; (ii) national saving; (iii) investment; (iv) consumption; and (v) output.","options":null,"answer":null,"images":null,"translation":{"question":"a. 假设一个政府决定以相同数额减少支出和（一次性）所得税。使用第 3 章建立的长期经济模型，用图形说明支出和税收等额减少所产生的影响。务必标注坐标轴、曲线、初始均衡值、曲线移动的方向和最终均衡值。b. 用文字说明 (i) 实际利率；(ii) 国民储蓄；(iii) 投资；(iv) 消费；和 (v) 产出会发生什么变化。","options":null},"topics":["national-income"],"answer_ref":"a. 图：G 与 T 同减 Δ：可支配收入增加 Δ，消费增加 MPC·Δ，国民储蓄变化 ΔS = Δ − MPC·Δ = (1−MPC)Δ > 0，储蓄曲线右移；r 下降，投资增加。b. (i) r 下降；(ii) 国民储蓄增加 (1−MPC)·Δ；(iii) 投资增加；(iv) 消费增加 MPC·Δ（这正是所谓的平衡预算乘数效应）；(v) 产出不变。"},{"num":154,"type":"sa","question":"Consider two competitive economies that have the same quantities of labor (L = 400) and capital (K = 400), as well as the same technology (A = 100). The economies of the countries are described by the following Cobb–Douglas production functions: North Economy: Y = A L.3K.7 South Economy: Y = A L.7K.3 a. Which economy has the larger total production? Explain. b. In which economy is the marginal product of labor larger? Explain. c. In which economy is the real wage larger? Explain. d. In which economy is labor's share of income larger? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"考虑两个竞争性经济，它们有相同数量的劳动（L = 400）和资本（K = 400），以及相同的技术（A = 100）。这两个国家的经济由以下柯布-道格拉斯生产函数描述：北方经济：Y = A L.3K.7；南方经济：Y = A L.7K.3。a. 哪个经济的总产出更大？请解释。b. 在哪个经济中劳动的边际产品更大？请解释。c. 在哪个经济中实际工资更大？请解释。d. 在哪个经济中劳动占收入的份额更大？请解释。","options":null},"topics":["cobb-douglas"],"answer_ref":"a. 总产量相同。L=K=400 时两式都等于 100×400^(0.3+0.7) = 100×400 = 40,000。b. 南方经济的 MPL 更大：MPL_N = 0.3Y/L = 30，MPL_S = 0.7Y/L = 70。c. 竞争性经济中实际工资 = MPL，故南方更高（70 对 30）。d. 柯布-道格拉斯中要素收入份额等于指数：劳动份额北方 0.3、南方 0.7，南方更大。"},{"num":155,"type":"sa","question":"Assume that a competitive economy can be described by a constant returns to scale (Cobb–Douglas) production function and all factors of production are fully employed. Holding other factors constant, including the quantity of capital and technology, carefully explain how a one-time, 10-percent increase in the quantity of labor (perhaps as a result of a special immigration policy) will change each of the following: a. the level of output produced b. the real wage of labor c. the real rental price of capital d. labor's share of total income","options":null,"answer":null,"images":null,"translation":{"question":"假设一个竞争性经济可以用规模报酬不变（柯布-道格拉斯）生产函数描述，且所有生产要素都得到充分利用。在其他因素（包括资本数量和技术）不变的情况下，仔细解释劳动数量一次性增加 10%（也许是特殊移民政策的结果）将如何改变以下各项：a. 生产的产出水平 b. 劳动的实际工资 c. 资本的实际租赁价格 d. 劳动占总收入的份额","options":null},"topics":["cobb-douglas"],"answer_ref":"a. 产出增加约 (1−α)×10%（若资本份额 α=1/3，则 Y 增约 6.7%）。b. 实际工资下降约 α×10%（约 3.3%）：劳动增多使 MPL = (1−α)Y/L 下降。c. 实际租赁价格上升约 (1−α)×10%（约 6.7%）：劳动与资本互补，更多劳动使每单位资本更富生产力。d. 劳动份额不变：柯布-道格拉斯函数中劳动份额恒等于 1−α。"},{"num":156,"type":"sa","question":"Assume that a competitive economy can be described by a constant returns to scale (Cobb–Douglas) production function, and all factors of production are fully employed. Holding other factors constant, including the quantity of labor and technology, carefully explain how a one-time, 50-percent decrease in the quantity of capital (perhaps the result of war damage) will change each of the following: a. the level of output produced b. the real wage of labor c. the real rental price of capital d. capital's share of total income","options":null,"answer":null,"images":null,"translation":{"question":"假设一个竞争性经济可以用规模报酬不变（柯布-道格拉斯）生产函数描述，且所有生产要素都得到充分利用。在其他因素（包括劳动数量和技术）不变的情况下，仔细解释资本数量一次性减少 50%（也许是战争破坏的结果）将如何改变以下各项：a. 生产的产出水平 b. 劳动的实际工资 c. 资本的实际租赁价格 d. 资本占总收入的份额","options":null},"topics":["cobb-douglas"],"answer_ref":"a. 产出下降约 α×50%（α=1/3 时约降 16.7%）。b. 实际工资上升：劳动相对稀缺，MPL = (1−α)Y/L 上升（约 +16.7%）。c. 实际租赁价格上升更多：资本稀缺使每单位资本产出大增，MPK = αY/K 约上升 33%。d. 资本份额不变：柯布-道格拉斯中恒等于 α。"},{"num":157,"type":"sa","question":"Consider a competitive economy in which factor prices adjust to keep the factors of production fully employed. In addition, the interest rate adjusts to keep the supply and demand for goods and services in equilibrium. The economy can be described by the following set of equations: Y = AKa L(1 – a) Y = C + I + G C = C (Y – T) I = I(r) Suggest at least two policies that a government could use to increase the equilibrium quantity of investment in the economy and carefully explain how these policies produce this result.","options":null,"answer":null,"images":null,"translation":{"question":"考虑一个竞争性经济，其中要素价格进行调整以使生产要素保持充分就业。此外，利率进行调整以使商品和服务的供求保持均衡。该经济可以用以下方程组描述：Y = AKa L(1 – a)；Y = C + I + G；C = C (Y – T)；I = I(r)。请提出政府可以用来增加经济中均衡投资数量的至少两项政策，并仔细解释这些政策如何产生这一结果。","options":null},"topics":["national-income"],"answer_ref":"两条思路都着眼于扩大国民储蓄（使储蓄供给曲线右移，r 降、I 升）：① 削减财政赤字——减少 G 或提高税收，公共储蓄增加（提高税收时私人储蓄略降，但国民储蓄净增 MPC·ΔT），可贷资金供给右移，r 下降，I 上升；② 鼓励私人储蓄的政策——如对储蓄/利息收入减税、引入强制储蓄计划，使消费函数下移，私人与国民储蓄增加，同样压低利率、扩大均衡投资。注意：单纯补贴投资（使 I(r) 右移）在本模型储蓄供给垂直时只会抬高利率而不会增加投资量。"},{"num":158,"type":"sa","question":"Consider a competitive economy in which factor prices adjust to keep the factors of production fully employed and the interest rate adjusts to keep the supply and demand for goods and services in equilibrium. The economy can be described by the following set of equations: Y = AKaL(1 – a) Y = C + I + G C = C(Y – T) I = I(r) How does an increase in government spending, holding other factors constant, affect the level of: a. public saving? b. private saving? c. national saving? d. the equilibrium interest rate? e. the equilibrium quantity of investment?","options":null,"answer":null,"images":null,"translation":{"question":"考虑一个竞争性经济，其中要素价格进行调整以使生产要素保持充分就业，利率进行调整以使商品和服务的供求保持均衡。该经济可以用以下方程组描述：Y = AKaL(1 – a)；Y = C + I + G；C = C(Y – T)；I = I(r)。在其他因素不变的情况下，政府支出的增加如何影响以下各项的水平：a. 公共储蓄？b. 私人储蓄？c. 国民储蓄？d. 均衡利率？e. 均衡投资数量？","options":null},"topics":["national-income"],"answer_ref":"a. 公共储蓄 = T−G，减少。b. 私人储蓄不变：Y、T 未变，C=C(Y−T) 不变。c. 国民储蓄减少（等于公共储蓄减少额）。d. 储蓄供给曲线左移，均衡利率上升。e. 均衡投资减少——这就是政府支出对私人投资的\"挤出效应\"。"},{"num":159,"type":"sa","question":"Price flexibility plays a key role in the classical model by ensuring that the markets reach equilibrium. a. Explain which price adjusts to bring equilibrium in the labor market. Describe how the price adjusts when demand exceeds supply in this market. b. Explain which price adjusts to bring equilibrium in the loanable funds market. Describe how the price adjusts when supply exceeds demand in this market.","options":null,"answer":null,"images":null,"translation":{"question":"价格弹性在古典模型中起着关键作用，它确保市场达到均衡。a. 解释哪种价格进行调整以使劳动力市场达到均衡。描述当该市场中需求超过供给时价格如何调整。b. 解释哪种价格进行调整以使可贷资金市场达到均衡。描述当该市场中供给超过需求时价格如何调整。","options":null},"topics":["national-income"],"answer_ref":"a. 劳动力市场由实际工资调整出清：当劳动需求超过供给时，企业竞雇工人，实际工资上升；工资升高使企业减少雇佣、劳动供给增加，直至供求相等。b. 可贷资金市场由实际利率调整出清：当储蓄（供给）超过投资（需求）时，资金供过于求，利率下降；低利率刺激企业投资、抑制储蓄，直至可贷资金供求平衡。"},{"num":160,"type":"sa","question":"Consider a production function for an economy: Y = 20(L.5K.4N.1) where L is labor, K is capital, and N is land. In this economy, the factors of production are in fixed supply with L = 100, K = 100, and N = 100. a. What is the level of output in this country? b. Does this production function exhibit constant returns to scale? Demonstrate by example. c. If the economy is competitive so that factors of production are paid the value of their marginal products, what is the share of total income will go to land?","options":null,"answer":null,"images":null,"translation":{"question":"考虑一个经济的生产函数：Y = 20(L.5K.4N.1)，其中 L 为劳动，K 为资本，N 为土地。在该经济中，生产要素供给固定，L = 100、K = 100、N = 100。a. 该国的产出水平是多少？b. 该生产函数是否表现出规模报酬不变？请举例说明。c. 如果该经济是竞争性的，因而生产要素按其边际产品的价值获得报酬，那么土地将获得总收入的多少份额？","options":null},"topics":["cobb-douglas"],"answer_ref":"a. Y = 20×(100^0.5×100^0.4×100^0.1) = 20×100 = 2000。b. 规模报酬不变：指数之和 0.5+0.4+0.1=1；例如 L=K=N=200 时 Y = 20×200 = 4000 = 2×2000，所有投入翻倍产出恰好翻倍。c. 土地份额 = 其指数 0.1，即总收入的 10%。"},{"num":161,"type":"sa","question":"The production of an economy is explained by a function Y = 20 (L.5K.5), where L is labor and K is capital with L = 400 and K = 400. Does this economy support constant returns to scale?","options":null,"answer":null,"images":null,"translation":{"question":"一个经济的产出由函数 Y = 20 (L.5K.5) 解释，其中 L 为劳动，K 为资本，L = 400、K = 400。该经济是否支持规模报酬不变？","options":null},"topics":["cobb-douglas"],"answer_ref":"是。指数之和 0.5+0.5=1。验证：Y(2L,2K) = 20×(2L)^0.5×(2K)^0.5 = 20×2×L^0.5K^0.5 = 2Y，所有投入同比例翻倍，产出恰好翻倍，满足规模报酬不变。"},{"num":162,"type":"sa","question":"After studying the circular flow of dollars in the economy, explain with an example how saving done by households goes back into the circular flow. In reality, is all household saving used as investment?","options":null,"answer":null,"images":null,"translation":{"question":"在研究经济中货币的循环流动之后，请举例解释家庭所做的储蓄如何回到循环流动中。在现实中，所有家庭储蓄是否都被用作投资？","options":null},"topics":["national-income"],"answer_ref":"例子：家庭把储蓄存入银行，银行把资金贷给企业用于购买设备——企业投资支出又流回经济的循环流动；家庭也可直接购买债券、股票融资给企业。并非所有储蓄都变成国内投资：政府预算赤字会吸收国民储蓄（公共负储蓄），部分储蓄流向国外（资本净流出/购买外国资产），还可能持有为货币或闲置存款。"},{"num":163,"type":"sa","question":"What effect does advancement in technology have on the equilibrium real rental price and capital, assuming that the supply of capital is fixed?","options":null,"answer":null,"images":null,"translation":{"question":"假设资本供给固定，技术进步对均衡的实际租赁价格和资本有什么影响？","options":null},"topics":["national-income"],"answer_ref":"技术进步提高资本的边际产品 MPK，企业愿为使用资本支付更高价格；资本供给固定时，需求增加使均衡实际租赁价格上升，而资本使用量不变（固定供给），租金上涨完全反映资本的更高生产力。"},{"num":164,"type":"sa","question":"The government of an economy has increased its spending and its taxes by the same amount. What is the effect on investment?","options":null,"answer":null,"images":null,"translation":{"question":"一个经济的政府以相同数额增加了其支出和税收。这对投资有什么影响？","options":null},"topics":["national-income"],"answer_ref":"G 与 T 等额增加 Δ：可支配收入减少 Δ，消费减少 MPC·Δ，国民储蓄变化 ΔS = Δ(税收增加) + MPC·Δ(消费减少) = (1−MPC)·Δ > 0？方向：ΔS = ΔT − ΔC = Δ − MPC·Δ = (1−MPC)Δ… 注意公共储蓄增加 Δ、私人储蓄变化 = −Δ + MPC·Δ = −(1−MPC)Δ，国民储蓄净增 (1−MPC)Δ。等等——若 G 与 T 同增 Δ，则 ΔS = Δ(T) − Δ(C) − Δ(G) = Δ − (−MPC·Δ) − Δ = MPC·Δ？重算：S=Y−C−G，ΔS = −ΔC − ΔG = MPC·Δ − Δ = −(1−MPC)Δ < 0。即国民储蓄减少 (1−MPC)Δ，储蓄曲线左移，r 上升，投资减少（部分挤出）。产出不变。"}]},{"num":4,"title":"The Monetary System","questions":[{"num":1,"type":"mc","question":"Economists use the term money to refer to:","options":["income.","profits.","assets used for transactions.","earnings from labor."],"answer":"C","images":null,"translation":{"question":"经济学家用“货币”一词指代：","options":["收入。","利润。","用于交易的资产。","来自劳动的收入。"]},"topics":["money-functions"]},{"num":2,"type":"mc","question":"Macroeconomists call assets used to make transactions:","options":["real income.","nominal income.","money.","consumption."],"answer":"C","images":null,"translation":{"question":"宏观经济学家把用于进行交易的资产称为：","options":["实际收入。","名义收入。","货币。","消费。"]},"topics":["money-functions"]},{"num":3,"type":"mc","question":"All of the following are considered major functions of money except as a:","options":["medium of exchange.","way to display wealth.","unit of account.","store of value."],"answer":"B","images":null,"translation":{"question":"以下都是货币的主要职能，除了作为：","options":["交易媒介。","展示财富的方式。","计价单位。","价值储藏手段。"]},"topics":["money-functions"]},{"num":4,"type":"mc","question":"People use money as a store of value when they:","options":["hold money to transfer purchasing power into the future.","use money as a measure of economic transactions.","use money to buy goods and services.","hold money to gain power and esteem."],"answer":"A","images":null,"translation":{"question":"人们把货币作为价值储藏手段，是当他们：","options":["持有货币以将购买力转移到未来。","将货币用作经济交易的度量。","用货币购买商品和服务。","持有货币以获得权力和声望。"]},"topics":["money-functions"]},{"num":5,"type":"mc","question":"People use money as a unit of account when they:","options":["hold money to transfer purchasing power into the future.","use money as a measure of economic transactions.","use money to buy goods and services.","hold money to gain power and esteem."],"answer":"B","images":null,"translation":{"question":"人们把货币作为计价单位，是当他们：","options":["持有货币以将购买力转移到未来。","将货币用作经济交易的度量。","用货币购买商品和服务。","持有货币以获得权力和声望。"]},"topics":["money-functions"]},{"num":6,"type":"mc","question":"People use money as a medium of exchange when they:","options":["hold money to transfer purchasing power into the future.","use money as a measure of economic transactions.","use money to buy goods and services.","hold money to gain power and esteem."],"answer":"C","images":null,"translation":{"question":"人们把货币作为交易媒介，是当他们：","options":["持有货币以将购买力转移到未来。","将货币用作经济交易的度量。","用货币购买商品和服务。","持有货币以获得权力和声望。"]},"topics":["money-functions"]},{"num":7,"type":"mc","question":"When a pizza maker lists the price of a pizza as $10, this is an example of using money as a:","options":["store of value.","unit of account.","medium of exchange.","flow of value."],"answer":"B","images":null,"translation":{"question":"当一个披萨店主把披萨的价格标为10美元时，这是把货币用作：","options":["价值储藏手段。","计价单位。","交易媒介。","价值流动手段。"]},"topics":["money-functions"]},{"num":8,"type":"mc","question":"Money's liquidity refers to the ease with which:","options":["coins can be melted down.","illegally obtained money can be laundered.","loans can be floated.","money can be converted into goods and services."],"answer":"D","images":null,"translation":{"question":"货币的流动性指的是货币可以转换：","options":["硬币可以被熔化的容易程度。","非法所得的钱可以被洗白的容易程度。","贷款可以被筹得的容易程度。","为商品和服务的容易程度。"]},"topics":["money-functions"]},{"num":9,"type":"mc","question":"A trade in a barter economy requires:","options":["currency.","a check.","scrip.","a double coincidence of wants."],"answer":"D","images":null,"translation":{"question":"物物交换经济中的一笔交易需要：","options":["通货。","支票。","代币。","需求的双重巧合。"]},"topics":["money-functions"]},{"num":10,"type":"mc","question":"A country that is on a gold standard uses:","options":["commodity money.","fiat money.","credit money.","the barter system."],"answer":"A","images":null,"translation":{"question":"实行金本位制的国家使用：","options":["商品货币。","法定货币。","信用货币。","物物交换制度。"]},"topics":["money-functions"]},{"num":11,"type":"mc","question":"An important factor in the evolution of commodity money to fiat money is:","options":["a desire to reduce transaction costs.","a desire to increase transaction costs.","the fact that gold is no longer highly valued.","a desire to use gold for jewelry."],"answer":"A","images":null,"translation":{"question":"商品货币演变为法定货币的一个重要因素是：","options":["降低交易成本的愿望。","提高交易成本的愿望。","黄金不再受高度重视这一事实。","用黄金制作珠宝的愿望。"]},"topics":["money-functions"]},{"num":12,"type":"mc","question":"In a country on a gold standard, the quantity of money is determined by the:","options":["government.","central bank.","amount of gold.","buying and selling of government securities."],"answer":"C","images":null,"translation":{"question":"在金本位制国家，货币数量由：","options":["政府决定。","中央银行决定。","黄金数量决定。","政府债券的买卖决定。"]},"topics":["money-functions"]},{"num":13,"type":"mc","question":"The central bank in the United States is the:","options":["Bank of America.","U.S. Treasury.","U.S. National Bank.","Federal Reserve."],"answer":"D","images":null,"translation":{"question":"美国的中央银行是：","options":["美国银行。","美国财政部。","美国国家银行。","联邦储备（美联储）。"]},"topics":["money-supply-control"]},{"num":14,"type":"mc","question":"In the United States, monetary policy is conducted by:","options":["the president.","the Congress.","the Federal Reserve.","the Treasury Department."],"answer":"C","images":null,"translation":{"question":"在美国，货币政策由：","options":["总统执行。","国会执行。","联邦储备（美联储）执行。","财政部执行。"]},"topics":["money-supply-control"]},{"num":15,"type":"mc","question":"To increase the money supply, the Federal Reserve:","options":["buys government bonds.","sells government bonds.","buys corporate stocks.","sells corporate stocks."],"answer":"A","images":null,"translation":{"question":"为了增加货币供给，联邦储备：","options":["购买政府债券。","出售政府债券。","购买公司股票。","出售公司股票。"]},"topics":["money-supply-control"]},{"num":16,"type":"mc","question":"To reduce the money supply, the Federal Reserve:","options":["buys government bonds.","sells government bonds.","creates demand deposits.","destroys demand deposits."],"answer":"B","images":null,"translation":{"question":"为了减少货币供给，联邦储备：","options":["购买政府债券。","出售政府债券。","创造活期存款。","销毁活期存款。"]},"topics":["money-supply-control"]},{"num":17,"type":"mc","question":"Open-market operations are:","options":["Commerce Department efforts to open foreign markets to international trade.","Federal Reserve purchases and sales of government bonds.","Securities and Exchange Commission rules requiring open disclosure of market trades.","Treasury Department purchases and sales of the U.S. gold stock."],"answer":"B","images":null,"translation":{"question":"公开市场操作是：","options":["商务部为国际贸易开放外国市场的努力。","联邦储备对政府债券的买卖。","证券交易委员会要求公开披露市场交易的规定。","财政部对美国黄金储备的买卖。"]},"topics":["money-supply-control"]},{"num":18,"type":"mc","question":"Currency equals:","options":["M1.","the sum of funds in checking accounts.","the sum of checking accounts and paper money.","the sum of coins and paper money."],"answer":"D","images":null,"translation":{"question":"通货等于：","options":["M1。","支票账户中的资金总额。","支票账户与纸币之和。","硬币与纸币之和。"]},"topics":["money-functions"]},{"num":19,"type":"mc","question":"Demand deposits are funds held in:","options":["currency.","certificates of deposit.","checking accounts.","money markets."],"answer":"C","images":null,"translation":{"question":"活期存款是存放在：","options":["通货中的资金。","存单中的资金。","支票账户中的资金。","货币市场中的资金。"]},"topics":["money-functions"]},{"num":20,"type":"mc","question":"All of the following assets are included in M1 except:","options":["currency.","demand deposits.","traveler's checks.","money market deposit accounts."],"answer":"D","images":null,"translation":{"question":"以下资产都包含在M1中，除了：","options":["通货。","活期存款。","旅行支票。","货币市场存款账户。"]},"topics":["money-functions"]},{"num":21,"type":"mc","question":"Money market mutual fund shares are included in:","options":["M1 only.","M2 only.","both M1 and M2.","neither M1 nor M2."],"answer":"B","images":null,"translation":{"question":"货币市场共同基金份额包含在：","options":["仅M1中。","仅M2中。","M1和M2两者中。","M1和M2都不包含。"]},"topics":["money-functions"]},{"num":22,"type":"mc","question":"Credit card balances are included in:","options":["M1 only.","M2 only.","both M1 and M2.","neither M1 nor M2."],"answer":"D","images":null,"translation":{"question":"信用卡余额包含在：","options":["仅M1中。","仅M2中。","M1和M2两者中。","M1和M2都不包含。"]},"topics":["money-functions"]},{"num":23,"type":"mc","question":"Checking account balances that are linked to debit cards are included in:","options":["M1.","M2 only.","both M1 and M2.","neither M1 nor M2."],"answer":"C","images":null,"translation":{"question":"与借记卡关联的支票账户余额包含在：","options":["M1中。","仅M2中。","M1和M2两者中。","M1和M2都不包含。"]},"topics":["money-functions"]},{"num":24,"type":"mc","question":"Payment is deferred by using _______, but immediate access to funds occurs when using ______.","options":["currency; demand deposits","credit cards; debit cards","demand deposits; savings deposits","debit cards; credit cards"],"answer":"B","images":null,"translation":{"question":"使用______会推迟支付，而使用______则能立即动用资金。","options":["通货；活期存款","信用卡；借记卡","活期存款；储蓄存款","借记卡；信用卡"]},"topics":["money-functions"]},{"num":25,"type":"mc","question":"In the United States, the money supply is determined:","options":["only by the Fed.","only by the behavior of individuals who hold money and of banks in which money is held.","jointly by the Fed and by the behavior of individuals who hold money and of banks in which money is held.","according to a constant-growth-rate rule."],"answer":"C","images":null,"translation":{"question":"在美国，货币供给：","options":["仅由美联储决定。","仅由持有货币的个人和持有货币的银行的行为决定。","由美联储与持有货币的个人及银行的行为共同决定。","按照固定增长率规则决定。"]},"topics":["money-supply-control"]},{"num":26,"type":"mc","question":"The money supply consists of:","options":["currency plus reserves.","currency plus the monetary base.","currency plus demand deposits.","the monetary base plus demand deposits."],"answer":"C","images":null,"translation":{"question":"货币供给包括：","options":["通货加准备金。","通货加基础货币。","通货加活期存款。","基础货币加活期存款。"]},"topics":["money-supply-control"]},{"num":27,"type":"mc","question":"Bank reserves equal:","options":["gold kept in bank vaults.","gold kept at the central bank.","currency plus demand deposits.","deposits that banks have received but have not lent out."],"answer":"D","images":null,"translation":{"question":"银行准备金等于：","options":["银行金库中的黄金。","存放在中央银行的黄金。","通货加活期存款。","银行收到但尚未贷出的存款。"]},"topics":["banking-fractional"]},{"num":28,"type":"mc","question":"In the United States, bank reserves consist of:","options":["currency and demand deposits.","vault cash and deposits at the Federal Reserve.","gold deposits at the Federal Reserve.","the money supply."],"answer":"B","images":null,"translation":{"question":"在美国，银行准备金包括：","options":["通货和活期存款。","库存现金和存放在联邦储备的存款。","存放在联邦储备的黄金存款。","货币供给。"]},"topics":["banking-fractional"]},{"num":29,"type":"mc","question":"Assets of banks include:","options":["money market mutual funds.","currency in the hands of the public.","loans to customers.","demand deposits."],"answer":"C","images":null,"translation":{"question":"银行的资产包括：","options":["货币市场共同基金。","公众手中的通货。","对客户的贷款。","活期存款。"]},"topics":["banking-fractional"]},{"num":30,"type":"mc","question":"Liabilities of banks include:","options":["reserves.","currency in the hands of the public.","loans to customers.","demand deposits."],"answer":"D","images":null,"translation":{"question":"银行的负债包括：","options":["准备金。","公众手中的通货。","对客户的贷款。","活期存款。"]},"topics":["banking-fractional"]},{"num":31,"type":"mc","question":"In a system with 100-percent-reserve banking:","options":["all banks must hold reserves equal to 100 percent of their loans.","no banks can make loans using deposits made at their institutions.","the banking system completely controls the size of the money supply.","no banks can accept deposits."],"answer":"B","images":null,"translation":{"question":"在100%准备金银行制度下：","options":["所有银行必须持有等于其贷款100%的准备金。","任何银行都不能用存入其机构的存款发放贷款。","银行体系完全控制货币供给的规模。","任何银行都不能接受存款。"]},"topics":["banking-fractional"]},{"num":32,"type":"mc","question":"In a 100-percent-reserve banking system, if a customer deposits $100 of currency into a bank, then the money supply:","options":["increases by $100.","decreases by $100.","increases by more than $100.","remains the same."],"answer":"D","images":null,"translation":{"question":"在100%准备金银行制度下，如果一个客户把100美元通货存入银行，那么货币供给：","options":["增加100美元。","减少100美元。","增加超过100美元。","保持不变。"]},"topics":["banking-fractional"]},{"num":33,"type":"mc","question":"In a 100-percent-reserve banking system, banks:","options":["can increase the money supply.","can decrease the money supply.","can either increase or decrease the money supply.","cannot affect the money supply."],"answer":"D","images":null,"translation":{"question":"在100%准备金银行制度下，银行：","options":["能够增加货币供给。","能够减少货币供给。","既能增加也能减少货币供给。","不能影响货币供给。"]},"topics":["banking-fractional"]},{"num":34,"type":"mc","question":"In a system with fractional-reserve banking:","options":["all banks must hold reserves equal to a fraction of their loans.","no banks can make loans.","the banking system completely controls the size of the money supply.","all banks must hold reserves equal to a fraction of their deposits."],"answer":"D","images":null,"translation":{"question":"在部分准备金银行制度下：","options":["所有银行必须持有等于其贷款一部分的准备金。","任何银行都不能发放贷款。","银行体系完全控制货币供给的规模。","所有银行必须持有等于其存款一部分的准备金。"]},"topics":["banking-fractional"]},{"num":35,"type":"mc","question":"Banks create money in:","options":["a 100-percent-reserve banking system but not in a fractional-reserve banking system.","a fractional-reserve banking system but not in a 100-percent-reserve banking system.","both a 100-percent-reserve banking system and a fractional-reserve banking system.","neither a 100-percent-reserve banking system nor a fractional-reserve banking system."],"answer":"B","images":null,"translation":{"question":"银行创造货币：","options":["发生在100%准备金银行制度下，而不是部分准备金银行制度下。","发生在部分准备金银行制度下，而不是100%准备金银行制度下。","在100%准备金银行制度和部分准备金银行制度下都会发生。","在100%准备金银行制度和部分准备金银行制度下都不会发生。"]},"topics":["banking-fractional"]},{"num":36,"type":"mc","question":"In a fractional-reserve banking system, banks create money when they:","options":["accept deposits.","make loans.","hold reserves.","exchange currency for deposits."],"answer":"B","images":null,"translation":{"question":"在部分准备金银行制度下，银行在：","options":["接受存款时创造货币。","发放贷款时创造货币。","持有准备金时创造货币。","用通货兑换存款时创造货币。"]},"topics":["banking-fractional"]},{"num":37,"type":"mc","question":"In a fractional-reserve banking system, banks create money because:","options":["each dollar of reserves generates many dollars of demand deposits.","banks have the legal authority to issue new currency.","funds are transferred from households wishing to save to firms wishing to borrow.","the wealth of the economy expands when borrowers undertake new debt obligations."],"answer":"A","images":null,"translation":{"question":"在部分准备金银行制度下，银行创造货币是因为：","options":["每一美元准备金会产生许多美元的活期存款。","银行拥有发行新通货的法定权力。","资金从希望储蓄的家庭转移到希望借款的企业。","当借款者承担新的债务时，经济的财富会扩大。"]},"topics":["banking-fractional"]},{"num":38,"type":"mc","question":"Financial intermediation is the process of:","options":["settling disputes between borrowers and lenders.","advising corporations how to invest.","transferring funds from savers to borrowers.","converting from a barter economy to a money economy."],"answer":"C","images":null,"translation":{"question":"金融中介是：","options":["解决借款者与贷款者之间纠纷的过程。","为企业提供投资建议的过程。","将资金从储蓄者转移到借款者的过程。","从物物交换经济转变为货币经济的过程。"]},"topics":["banking-fractional"]},{"num":39,"type":"mc","question":"The value of a bank's owners' equity is called bank:","options":["deposits.","reserves.","capital.","liquidity."],"answer":"C","images":null,"translation":{"question":"银行所有者权益的价值被称为银行：","options":["存款。","准备金。","资本。","流动性。"]},"topics":["banking-fractional"]},{"num":40,"type":"mc","question":"A bank balance sheet consists of only the following items: Deposits $1,000 Reserves $100 Securities $400 Bonds Issued $500 Loans $2,000 What is the value of bank capital?","options":["–$1,000","+$500","+$1,000","+$1,500"],"answer":"C","images":null,"translation":{"question":"某银行的资产负债表仅由以下项目构成：存款 1,000美元，准备金 100美元，证券 400美元，已发行债券 500美元，贷款 2,000美元。银行资本的价值是多少？","options":["–1,000美元","+500美元","+1,000美元","+1,500美元"]},"topics":["banking-fractional"]},{"num":41,"type":"mc","question":"The minimum amount of owners' equity in a bank mandated by regulators is called a _____ requirement.","options":["reserve","margin","liquidity","capital"],"answer":"D","images":null,"translation":{"question":"监管机构规定的银行必须持有的最低所有者权益称为______要求。","options":["准备金","保证金","流动性","资本"]},"topics":["banking-fractional"]},{"num":42,"type":"mc","question":"The use of borrowed funds to supplement existing funds for purposes of investment is called:","options":["arbitrage.","leverage.","convergence.","intermediation."],"answer":"B","images":null,"translation":{"question":"为投资目的而使用借入资金补充现有资金称为：","options":["套利。","杠杆。","收敛。","中介。"]},"topics":["banking-fractional"]},{"num":43,"type":"mc","question":"[[IMG:c4_img0.png]] Based on the table, what is the leverage ratio at the bank?","options":["3","4.67","5","10"],"answer":"C","images":null,"translation":{"question":"[[IMG:c4_img0.png]] 根据表格，该银行的杠杆率是多少？","options":["3","4.67","5","10"]},"topics":["banking-fractional"]},{"num":44,"type":"mc","question":"Table: Bank Balance Sheet Based on the table, what is the reserve–deposit ratio at the bank?","options":["3 percent","5 percent","10 percent","15 percent"],"answer":"C","images":null,"translation":{"question":"表格：银行资产负债表。根据表格，该银行的准备金-存款比率是多少？","options":["3%","5%","10%","15%"]},"topics":["banking-fractional"]},{"num":45,"type":"mc","question":"Table: Bank Balance Sheet Based on the table, owners' equity will fall to zero if loan defaults reduce the value of total assets by _____ percent.","options":["10","20","30","40"],"answer":"B","images":["c4_img1.png"],"translation":{"question":"表格：银行资产负债表。根据表格，如果贷款违约使总资产价值减少______%，所有者权益将降为零。","options":["10","20","30","40"]},"topics":["banking-fractional"]},{"num":46,"type":"mc","question":"The amount of capital that banks are required to hold depends on the:","options":["amount of deposits held at a bank.","riskiness of the bank's assets.","reserve requirements for deposits set by the Fed.","level of deposit insurance coverage."],"answer":"B","images":["c4_img2.png"],"translation":{"question":"银行必须持有的资本数量取决于：","options":["银行的存款数量。","银行资产的风险程度。","美联储设定的存款准备金要求。","存款保险的保障水平。"]},"topics":["banking-fractional"]},{"num":47,"type":"mc","question":"The size of the monetary base is determined by:","options":["the Federal Reserve.","the Federal Reserve and banks.","preferences of households about the form of money they wish to hold.","business policies of banks and the laws regulating banks."],"answer":"A","images":null,"translation":{"question":"基础货币的规模由：","options":["联邦储备决定。","联邦储备和银行决定。","家庭对其希望持有的货币形式的偏好决定。","银行的经营政策和监管银行的法律决定。"]},"topics":["money-supply-control"]},{"num":48,"type":"mc","question":"If currency held by the public equals $100 billion, reserves held by banks equal $50 billion, and bank deposits equal $500 billion, then the monetary base equals:","options":["$50 billion.","$100 billion.","$150 billion.","$600 billion."],"answer":"C","images":null,"translation":{"question":"如果公众持有的通货等于1,000亿美元，银行持有的准备金等于500亿美元，银行存款等于5,000亿美元，那么基础货币等于：","options":["500亿美元。","1,000亿美元。","1,500亿美元。","6,000亿美元。"]},"topics":["money-supply-control"]},{"num":49,"type":"mc","question":"If currency held by the public equals $100 billion, reserves held by banks equal $50 billion, and bank deposits equal $500 billion, then the money supply equals:","options":["$100 billion.","$150 billion.","$600 billion.","$650 billion."],"answer":"C","images":null,"translation":{"question":"如果公众持有的通货等于1,000亿美元，银行持有的准备金等于500亿美元，银行存款等于5,000亿美元，那么货币供给等于：","options":["1,000亿美元。","1,500亿美元。","6,000亿美元。","6,500亿美元。"]},"topics":["money-supply-control"]},{"num":50,"type":"mc","question":"The reserve–deposit ratio is determined by:","options":["the Federal Reserve.","business policies of banks and the laws regulating banks.","preferences of households about the form of money they wish to hold.","the Federal Deposit Insurance Corporation (FDIC)."],"answer":"B","images":null,"translation":{"question":"准备金-存款比率由：","options":["联邦储备决定。","银行的经营政策和监管银行的法律决定。","家庭对其希望持有的货币形式的偏好决定。","联邦存款保险公司（FDIC）决定。"]},"topics":["money-supply-control"]},{"num":51,"type":"mc","question":"The currency–deposit ratio is determined by:","options":["the Federal Reserve.","business policies of banks and the laws regulating banks.","preferences of households about the form of money they wish to hold.","the Federal Deposit Insurance Corporation (FDIC)."],"answer":"C","images":null,"translation":{"question":"通货-存款比率由：","options":["联邦储备决定。","银行的经营政策和监管银行的法律决定。","家庭对其希望持有的货币形式的偏好决定。","联邦存款保险公司（FDIC）决定。"]},"topics":["money-supply-control"]},{"num":52,"type":"mc","question":"The preferences of households determine the:","options":["reserve–deposit ratio.","currency–deposit ratio.","size of the monetary base.","loan–deposit ratio."],"answer":"B","images":null,"translation":{"question":"家庭的偏好决定：","options":["准备金-存款比率。","通货-存款比率。","基础货币的规模。","贷款-存款比率。"]},"topics":["money-supply-control"]},{"num":53,"type":"mc","question":"If the monetary base is denoted by B, rr is the ratio of reserves to deposits, and cr is the ratio of currency to deposits, then the money supply is equal to ______ multiplied by B.","options":["(rr + 1)/ (rr + cr)","(cr + 1)/ (cr + rr)","(rr + cr)/ (rr + 1)","(rr + cr)/ (cr + 1)"],"answer":"B","images":null,"translation":{"question":"如果用B表示基础货币，rr表示准备金对存款的比率，cr表示通货对存款的比率，那么货币供给等于______乘以B。","options":["(rr + 1)/(rr + cr)","(cr + 1)/(cr + rr)","(rr + cr)/(rr + 1)","(rr + cr)/(cr + 1)"]},"topics":["money-supply-control"]},{"num":54,"type":"mc","question":"The ratio of the money supply to the monetary base is called:","options":["the currency–deposit ratio.","the reserve–deposit ratio.","high-powered money.","the money multiplier."],"answer":"D","images":null,"translation":{"question":"货币供给与基础货币的比率被称为：","options":["通货-存款比率。","准备金-存款比率。","高能货币。","货币乘数。"]},"topics":["money-supply-control"]},{"num":55,"type":"mc","question":"High-powered money is another name for:","options":["currency.","demand deposits.","the monetary base.","M2."],"answer":"C","images":null,"translation":{"question":"高能货币是：","options":["通货的另一种叫法。","活期存款的另一种叫法。","基础货币的另一种叫法。","M2的另一种叫法。"]},"topics":["money-supply-control"]},{"num":56,"type":"mc","question":"If the ratio of reserves to deposits (rr) increases, while the ratio of currency to deposits (cr) is constant and the monetary base (B) is constant, then:","options":["it cannot be determined whether the money supply increases or decreases.","the money supply increases.","the money supply decreases.","the money supply does not change."],"answer":"C","images":null,"translation":{"question":"如果准备金对存款的比率(rr)上升，而通货对存款的比率(cr)和基础货币(B)保持不变，那么：","options":["无法确定货币供给是增加还是减少。","货币供给增加。","货币供给减少。","货币供给不变。"]},"topics":["money-supply-control"]},{"num":57,"type":"mc","question":"The money supply will increase if the:","options":["currency–deposit ratio increases.","reserve–deposit ratio increases.","monetary base increases.","discount rate increases."],"answer":"C","images":null,"translation":{"question":"如果：","options":["通货-存款比率上升，货币供给将增加。","准备金-存款比率上升，货币供给将增加。","基础货币增加，货币供给将增加。","贴现率上升，货币供给将增加。"]},"topics":["money-supply-control"]},{"num":58,"type":"mc","question":"The money supply will decrease if the:","options":["monetary base increases.","currency–deposit ratio increases.","discount rate decreases.","reserve–deposit ratio decreases."],"answer":"B","images":null,"translation":{"question":"如果：","options":["基础货币增加，货币供给将减少。","通货-存款比率上升，货币供给将减少。","贴现率下降，货币供给将减少。","准备金-存款比率下降，货币供给将减少。"]},"topics":["money-supply-control"]},{"num":59,"type":"mc","question":"If the reserve–deposit ratio is less than one, and the monetary base increases by $1 million, then the money supply will:","options":["increase by $1 million.","decrease by $1 million.","increase by more than $1 million.","decrease by more than $1 million."],"answer":"C","images":null,"translation":{"question":"如果准备金-存款比率小于1，且基础货币增加100万美元，那么货币供给将：","options":["增加100万美元。","减少100万美元。","增加超过100万美元。","减少超过100万美元。"]},"topics":["money-supply-control"]},{"num":60,"type":"mc","question":"If the currency–deposit ratio equals 0.5 and the reserve–deposit ratio equals 0.1, then the money multiplier equals:","options":["0.6.","1.67.","2.0.","2.5."],"answer":"D","images":null,"translation":{"question":"如果通货-存款比率等于0.5，准备金-存款比率等于0.1，那么货币乘数等于：","options":["0.6。","1.67。","2.0。","2.5。"]},"topics":["money-supply-control"]},{"num":61,"type":"mc","question":"If the monetary base equals $400 billion and the money multiplier equals 2, then the money supply equals:","options":["$200 billion.","$400 billion.","$800 billion.","$1,000 billion."],"answer":"C","images":null,"translation":{"question":"如果基础货币等于4,000亿美元，货币乘数等于2，那么货币供给等于：","options":["2,000亿美元。","4,000亿美元。","8,000亿美元。","1万亿美元。"]},"topics":["money-supply-control"]},{"num":62,"type":"mc","question":"When the Fed makes an open-market sale, it:","options":["increases the money multiplier (m).","increases the currency–deposit ratio (cr).","increases the monetary base (B).","decreases the monetary base (B)."],"answer":"D","images":null,"translation":{"question":"当美联储进行公开市场卖出时，它：","options":["提高货币乘数(m)。","提高通货-存款比率(cr)。","增加基础货币(B)。","减少基础货币(B)。"]},"topics":["money-supply-control"]},{"num":63,"type":"mc","question":"If you hear in the news that the Federal Reserve conducted open-market purchases, then you should expect ______ to increase.","options":["reserve requirements","the discount rate","the money supply","the reserve–deposit ratio"],"answer":"C","images":null,"translation":{"question":"如果你在新闻中听到联邦储备进行了公开市场买入，那么你应该预期______会增加。","options":["准备金要求","贴现率","货币供给","准备金-存款比率"]},"topics":["money-supply-control"]},{"num":64,"type":"mc","question":"When the Federal Reserve conducts an open-market purchase, it buys bonds from the:","options":["public.","U.S. Treasury.","Internal Revenue Service.","International Monetary Fund."],"answer":"A","images":null,"translation":{"question":"当联邦储备进行公开市场买入时，它从：","options":["公众手中购买债券。","美国财政部购买债券。","美国国税局购买债券。","国际货币基金组织购买债券。"]},"topics":["money-supply-control"]},{"num":65,"type":"mc","question":"For borrowing from the discount window, the Fed sets the _____ of borrowing, compared to borrowing using the Term Auction Facility, where the Fed sets the _____ of borrowing.","options":["maximum quantity; minimum quantity","minimum price; maximum price","quantity; price","price; quantity"],"answer":"D","images":null,"translation":{"question":"对于从贴现窗口借款，美联储设定借款的______；而对于通过定期拍卖工具（Term Auction Facility）借款，美联储设定借款的______。","options":["最大数量；最小数量","最低价格；最高价格","数量；价格","价格；数量"]},"topics":["money-supply-control"]},{"num":66,"type":"mc","question":"When banks borrow through the Term Auction Facility, the price of borrowing is determined by:","options":["the Federal Reserve.","a competitive bidding process.","the difference between the discount rate and the interest rate on three-month Treasury securities.","open-market operations."],"answer":"B","images":null,"translation":{"question":"当银行通过定期拍卖工具借款时，借款的价格由：","options":["联邦储备决定。","竞争性投标过程决定。","贴现率与三个月期国债利率之差决定。","公开市场操作决定。"]},"topics":["money-supply-control"]},{"num":67,"type":"mc","question":"The more funds that the Federal Reserve makes available for banks to borrow through the Term Auction Facility, the _____ the monetary base and the _____ the money supply.","options":["smaller; smaller","smaller; greater","greater; greater","greater; smaller"],"answer":"C","images":null,"translation":{"question":"美联储通过定期拍卖工具提供给银行借款的资金越多，基础货币越______，货币供给越______。","options":["小；小","小；大","大；大","大；小"]},"topics":["money-supply-control"]},{"num":68,"type":"mc","question":"Two ways for banks to borrow reserves from the Federal Reserve are through:","options":["the discount window and the Term Auction Facility.","open-market operations and excess reserve swaps.","decreasing the reserve–deposit ratio and decreasing the currency–deposit ratio.","fractional-reserve banking and financial intermediation."],"answer":"A","images":null,"translation":{"question":"银行从联邦储备借入准备金的两种途径是：","options":["贴现窗口和定期拍卖工具。","公开市场操作和超额准备金互换。","降低准备金-存款比率和降低通货-存款比率。","部分准备金银行和金融中介。"]},"topics":["money-supply-control"]},{"num":69,"type":"mc","question":"When the Fed decreases the interest rate paid on reserves, it:","options":["increases the reserve–deposit ratio (rr).","decreases the reserve–deposit ratio (rr).","increases the monetary base (B).","decreases the monetary base (B)."],"answer":"B","images":null,"translation":{"question":"当美联储降低支付给准备金的利率时，它：","options":["提高准备金-存款比率(rr)。","降低准备金-存款比率(rr)。","增加基础货币(B)。","减少基础货币(B)。"]},"topics":["money-supply-control"]},{"num":70,"type":"mc","question":"When the Fed increases the discount rate, it:","options":["increases the reserve to deposit ratio (rr).","decreases the reserve to deposit ratio (rr).","is likely to increase the monetary base (B).","is likely to decrease the monetary base (B)."],"answer":"D","images":null,"translation":{"question":"当美联储提高贴现率时，它：","options":["提高准备金对存款的比率(rr)。","降低准备金对存款的比率(rr)。","很可能增加基础货币(B)。","很可能减少基础货币(B)。"]},"topics":["money-supply-control"]},{"num":71,"type":"mc","question":"When the Fed increases the interest rate paid on reserves, it:","options":["increases the reserve–deposit ratio (rr).","decreases the reserve–deposit ratio (rr).","increases the monetary base (B).","decreases the monetary base (B)."],"answer":"A","images":null,"translation":{"question":"当美联储提高支付给准备金的利率时，它：","options":["提高准备金-存款比率(rr)。","降低准备金-存款比率(rr)。","增加基础货币(B)。","减少基础货币(B)。"]},"topics":["money-supply-control"]},{"num":72,"type":"mc","question":"If the Federal Reserve wishes to increase the money supply, it should:","options":["decrease the discount rate.","increase interest paid on reserves.","sell government bonds.","decrease the monetary base."],"answer":"A","images":null,"translation":{"question":"如果联邦储备希望增加货币供给，它应该：","options":["降低贴现率。","提高支付给准备金的利率。","出售政府债券。","减少基础货币。"]},"topics":["money-supply-control"]},{"num":73,"type":"mc","question":"The most frequently used tool of monetary policy is:","options":["open-market operations.","changes in the discount rate.","changes in reserve requirements.","changes in interest rate paid on reserves."],"answer":"A","images":null,"translation":{"question":"最常用的货币政策工具是：","options":["公开市场操作。","贴现率的变化。","准备金要求的变化。","支付给准备金的利率的变化。"]},"topics":["money-supply-control"]},{"num":74,"type":"mc","question":"To increase the monetary base, the Fed can:","options":["conduct open-market purchases.","conduct open-market sales.","raise the interest rate paid on reserves.","lower the required reserve ratio."],"answer":"A","images":null,"translation":{"question":"为了增加基础货币，美联储可以：","options":["进行公开市场买入。","进行公开市场卖出。","提高支付给准备金的利率。","降低法定准备金率。"]},"topics":["money-supply-control"]},{"num":75,"type":"mc","question":"To increase the money multiplier, the Fed can:","options":["conduct open-market purchases.","conduct open-market sales.","raise the interest rate paid on reserves.","lower the interest rate paid on reserves."],"answer":"D","images":null,"translation":{"question":"为了提高货币乘数，美联储可以：","options":["进行公开市场买入。","进行公开市场卖出。","提高支付给准备金的利率。","降低支付给准备金的利率。"]},"topics":["money-supply-control"]},{"num":76,"type":"mc","question":"If the Federal Reserve increases the interest rate paid on reserves, banks will tend to hold _____ excess reserves, which will _____ the money multiplier.","options":["more; increase","more; decrease","fewer; increase","fewer; decrease"],"answer":"B","images":null,"translation":{"question":"如果联邦储备提高支付给准备金的利率，银行倾向于持有______超额准备金，这将______货币乘数。","options":["更多；提高","更多；降低","更少；提高","更少；降低"]},"topics":["money-supply-control"]},{"num":77,"type":"mc","question":"Open-market operations change the ______; changes in interest rate paid on reserves change the ______; and changes in the discount rate change the ______.","options":["monetary base; monetary base; monetary base","money multiplier; money multiplier; money multiplier","monetary base; money multiplier; monetary base","money multiplier; monetary base; money multiplier"],"answer":"C","images":null,"translation":{"question":"公开市场操作改变______；支付给准备金的利率的变化改变______；贴现率的变化改变______。","options":["基础货币；基础货币；基础货币","货币乘数；货币乘数；货币乘数","基础货币；货币乘数；基础货币","货币乘数；基础货币；货币乘数"]},"topics":["money-supply-control"]},{"num":78,"type":"mc","question":"Excess reserves are reserves that banks keep:","options":["in their vaults.","at the central bank.","to meet legal reserve requirements.","above the legally required amount."],"answer":"D","images":null,"translation":{"question":"超额准备金是银行持有的：","options":["金库中的准备金。","在中央银行的准备金。","为满足法定准备金要求的准备金。","超过法定要求数量的准备金。"]},"topics":["money-supply-control"]},{"num":79,"type":"mc","question":"Compared to typical open-market operations, when engaging in quantitative easing operations conducted by the Federal Reserve between 2007 and 2011, Federal Reserve purchases tended to be _____ securities.","options":["safer and shorter-term","tax-favored and foreign","smaller-denomination and higher-grade","riskier and longer-term"],"answer":"D","images":null,"translation":{"question":"与典型的公开市场操作相比，在2007至2011年间联邦储备实施的量化宽松操作中，联邦储备的购买倾向于______的证券。","options":["更安全且期限更短","享受税收优惠且为外国","面额更小且等级更高","风险更高且期限更长"]},"topics":["money-supply-control"]},{"num":80,"type":"mc","question":"The quantitative easing operations conducted by the Federal Reserve between 2007 and 2011 resulted in _____ increases in the monetary base and _____ increases in money supply.","options":["no; no","large; larger","large; smaller","small; smaller"],"answer":"C","images":null,"translation":{"question":"联邦储备在2007至2011年间实施的量化宽松操作导致基础货币______增加，货币供给______增加。","options":["没有；没有","大幅；更大","大幅；较小","小幅；较小"]},"topics":["money-supply-control"]},{"num":81,"type":"mc","question":"The quantitative easing policy conducted by the Federal Reserve between 2007 and 2011 resulted in a large increase in the monetary base that was partially offset by:","options":["a significant increase in the reserve–deposit ratio.","a significant decrease in the reserve–deposit ratio.","open-market purchases.","open-market sales."],"answer":"A","images":null,"translation":{"question":"联邦储备在2007至2011年间实施的量化宽松政策导致基础货币大幅增加，但部分被：","options":["准备金-存款比率的大幅上升所抵消。","准备金-存款比率的大幅下降所抵消。","公开市场买入所抵消。","公开市场卖出所抵消。"]},"topics":["money-supply-control"]},{"num":82,"type":"mc","question":"Between August 1929 and March 1933, the money supply fell 28 percent. At that time the monetary base ______, and the currency–deposit and reserve–deposit ratios both ______.","options":["fell; fell","fell; rose","rose; fell","rose; rose"],"answer":"D","images":null,"translation":{"question":"1929年8月至1933年3月间，货币供给下降了28%。当时基础货币______，而通货-存款比率和准备金-存款比率都______。","options":["下降；下降","下降；上升","上升；下降","上升；上升"]},"topics":["money-supply-control"]},{"num":83,"type":"mc","question":"If many banks fail, this is likely to:","options":["increase the ratio of currency to deposits.","decrease the ratio of currency to deposits.","have no effect on the ratio of currency to deposits.","decrease the amount of currency in circulation if the Fed takes no action."],"answer":"A","images":null,"translation":{"question":"如果许多银行倒闭，这很可能：","options":["提高通货对存款的比率。","降低通货对存款的比率。","对通货对存款的比率没有影响。","在美联储不采取行动的情况下减少流通中的通货数量。"]},"topics":["money-supply-control"]},{"num":84,"type":"mc","question":"Based on historical observations, if many banks fail, this is likely to:","options":["cause surviving banks to lower their ratios of reserves to deposits.","cause surviving banks to raise their ratios of reserves to deposits.","have no effect on the ratio of reserves to deposits in surviving banks.","cause surviving banks to hold less currency."],"answer":"B","images":null,"translation":{"question":"根据历史观察，如果许多银行倒闭，这很可能：","options":["使幸存的银行降低其准备金对存款的比率。","使幸存的银行提高其准备金对存款的比率。","对幸存银行准备金对存款的比率没有影响。","使幸存的银行持有更少的通货。"]},"topics":["money-supply-control"]},{"num":85,"type":"mc","question":"In 1932, the U.S. government imposed a 2-cent tax on checks written on deposits in bank accounts. This action would be expected to ______ the currency–deposit ratio and ______ the money supply.","options":["increase; increase","increase; decrease","decrease; increase","decrease; decrease"],"answer":"B","images":null,"translation":{"question":"1932年，美国政府对银行账户存款签发的支票征收2美分的税。这一措施预期会______通货-存款比率，并______货币供给。","options":["提高；增加","提高；减少","降低；增加","降低；减少"]},"topics":["money-supply-control"]},{"num":86,"type":"sa","question":"Assume that the monetary base (B) is $100 billion, the reserve–deposit ratio (rr) is 0.1, and the currency–deposit ratio (cr) is 0.1. a. What is the money supply? b. If rr changes to 0.2, but cr is 0.1 and B is unchanged, what is the money supply? c. If rr is 0.1 and cr is 0.2, but B is unchanged, what is the money supply?","options":null,"answer":null,"images":null,"translation":{"question":"假设基础货币(B)为1,000亿美元，准备金-存款比率(rr)为0.1，通货-存款比率(cr)为0.1。a. 货币供给是多少？b. 如果rr变为0.2，但cr仍为0.1且B不变，货币供给是多少？c. 如果rr为0.1，cr为0.2，但B不变，货币供给是多少？","options":null},"topics":["money-supply-control"],"answer_ref":"货币乘数 m = (cr+1)/(cr+rr)。a. m = 1.1/0.2 = 5.5，M = 1000亿×5.5 = 5,500亿。b. rr=0.2：m = 1.1/0.3 ≈ 3.67，M ≈ 3,667亿。c. cr=0.2：m = 1.2/0.3 = 4，M = 4,000亿。"},{"num":87,"type":"sa","question":"As the U.S. economy approached the millennium, January 1, 2000, many people cautiously began to hold larger than normal quantities of currency as protection against a possible disruption of banking services that could result from computer glitches. a. How did this greater preference for currency affect the money supply? b. How could the Federal Reserve offset such an increase in currency preferences?","options":null,"answer":null,"images":null,"translation":{"question":"当美国经济临近千禧年（2000年1月1日）时，许多人谨慎地开始持有比平时更多的通货，以防计算机故障可能导致银行服务中断。a. 这种对通货更强的偏好如何影响货币供给？b. 联邦储备如何抵消这种通货偏好的增强？","options":null},"topics":["money-supply-control"],"answer_ref":"a. 公众持有更多通货使通货-存款比 cr 上升，货币乘数 (cr+1)/(cr+rr) 下降，在基础货币不变时货币供给减少。b. 美联储可通过公开市场买入债券增加基础货币（或降低贴现率、法定准备金率）来抵消乘数下降，维持货币供给。"},{"num":88,"type":"sa","question":"The Federal Reserve's tools to control the money supply include open-market operations, the discount rate, and interest payments on reserves. a. How should each instrument be changed if the Fed wishes to decrease the money supply? b. Will the change affect the monetary base and/or the money multiplier?","options":null,"answer":null,"images":null,"translation":{"question":"联邦储备控制货币供给的工具包括公开市场操作、贴现率和准备金利息。a. 如果美联储希望减少货币供给，每种工具应如何调整？b. 这种调整会影响基础货币和/或货币乘数吗？","options":null},"topics":["money-supply-control"],"answer_ref":"a. 减少货币供给：公开市场卖出债券（回收基础货币）；提高贴现率（减少银行向美联储的借款）；提高准备金利率（鼓励银行多持准备金、少放贷）。b. 公开市场操作和贴现率改变的是基础货币（B）；准备金利率影响银行持有准备金的意愿，改变的是货币乘数（m）。三者都使 M = m×B 下降。"},{"num":89,"type":"sa","question":"Why does the Federal Reserve not have complete control over the size of the money supply? Give at least two reasons.","options":null,"answer":null,"images":null,"translation":{"question":"为什么联邦储备不能完全控制货币供给的规模？请给出至少两个原因。","options":null},"topics":["money-supply-control"],"answer_ref":"① 美联储不能控制银行体系的准备金率 rr——银行自行决定持有多少超额准备金、放出多少贷款；② 不能控制公众的通货-存款比 cr——人们自行决定在现金与存款之间如何分配；③ 因此货币乘数会波动，基础货币的控制不能精确转化为货币供给的控制。"},{"num":90,"type":"sa","question":"Construct a bank balance sheet with the following items: reserves, deposits, loans, securities, capital, and debt. Choose values so that the reserve–deposit ratio is 10 percent and the leverage ratio is 10. Give an example of a change in asset values that would push bank capital to zero. What happens when bank capital is gone?","options":null,"answer":null,"images":null,"translation":{"question":"用以下项目构建一张银行资产负债表：准备金、存款、贷款、证券、资本和债务。选择数值，使准备金-存款比率为10%，杠杆率为10。举一个会使银行资本降为零的资产价值变化的例子。当银行资本耗尽时会发生什么？","options":null},"topics":["banking-fractional"],"answer_ref":"示例资产负债表（资产=负债+权益，各1000）：资产：准备金100、贷款700、证券200；负债与权益：存款900、债务0、所有者权益100。准备金率 = 100/1000 = 10%，杠杆率 = 1000/100 = 10 ✓。若资产价值下跌100（如10%的贷款违约），权益即降为零。资本耗尽意味着资不抵债：银行技术上已破产，监管者可责令其关闭、兼并或接管，超出存款保险的存款人可能遭受损失。"},{"num":91,"type":"sa","question":"As the 2008–2009 financial crisis unfolded, one major U.S. bank had a leverage ratio of 50 In Canada regulators put a ceiling of 20 on bank leverage ratios. Compare the change in asset values that would push the capital in the U.S. bank to zero with the change required to eliminate capital in a Canadian bank at the ceiling-leverage ratio. What is the implication of the differences in maximum leverage ratios for the stability of the banking system?","options":null,"answer":null,"images":null,"translation":{"question":"在2008–2009年金融危机展开之际，美国一家大银行的杠杆率为50。加拿大监管机构则对银行杠杆率设定了20的上限。比较能使美国银行资本降为零的资产价值变化，与能使处于杠杆率上限的加拿大银行资本消失所需的资产价值变化。最大杠杆率的这些差异对银行体系的稳定性意味着什么？","options":null},"topics":["banking-fractional"],"answer_ref":"资本为零需要的资产跌幅 = 1/杠杆率。美国银行杠杆50：资产跌 2% 即抹平资本；加拿大银行杠杆上限20：资产需跌 5% 才抹平资本。加拿大银行有2.5倍的缓冲空间，能承受大得多的资产损失。含义：较低的杠杆上限使银行体系对资产价格波动更稳健，大规模银行倒闭和系统性危机的风险更小。"},{"num":92,"type":"sa","question":"Economists occasionally speak of “helicopter money” as a shorthand approach to explaining increases in the money supply. Suppose the chair of the Federal Reserve flies over the country in a helicopter, dropping 10,000,000 newly printed $100 bills (a total of $1 billion). By how much will the money supply increase in the following scenarios, holding everything else constant: a. all of the new bills are held by the public as currency? b. all of the new bills are deposited in banks that choose to hold 10 percent of their deposits as reserves (and no one in the economy holds any currency)? c. all of the new bills are deposited in banks that practice 100-percent-reserve banking? d. people in the economy hold half of their money as currency and half as deposits, while banks choose to hold 10 percent of their deposits as reserves?","options":null,"answer":null,"images":null,"translation":{"question":"经济学家偶尔用“直升机撒钱”作为解释货币供给增加的一种简明说法。假设联邦储备主席乘直升机飞越全国，抛下1,000万张新印的100美元钞票（共计10亿美元）。在以下各种情形中（其他条件不变），货币供给会增加多少：a. 所有新钞票都被公众作为通货持有？b. 所有新钞票都被存入银行，而银行选择持有其存款的10%作为准备金（经济中没有人持有任何通货）？c. 所有新钞票都被存入实行100%准备金制度的银行？d. 经济中的人们将其货币的一半作为通货持有、一半作为存款持有，而银行选择持有其存款的10%作为准备金？","options":null},"topics":["banking-fractional"],"answer_ref":"a. 全部作为通货持有：无乘数效应，货币供给 +10亿美元。b. 存入10%准备金率的银行、无人持币：乘数=10，货币供给 +100亿美元。c. 百分之百准备金银行：不创造存款货币，货币供给 +10亿美元。d. cr=0.5、rr=0.1：m = 1.5/0.6 = 2.5，货币供给 +25亿美元。"},{"num":93,"type":"sa","question":"Explain at least three factors that will affect the quantity of reserves that a bank wishes to hold.","options":null,"answer":null,"images":null,"translation":{"question":"解释至少三个会影响银行希望持有的准备金数量的因素。","options":null},"topics":["banking-fractional"],"answer_ref":"影响银行准备金持有量的因素：① 预期存款提取量和交易量波动（提款风险越大持准备金越多）；② 市场利率——持有准备金的机会成本，利率越高越倾向少持；③ 法定准备金率（监管要求）；④ 存款的稳定性（核心存款多则可少持）；⑤ 从贴现窗口或其他渠道获得流动性的难易程度。"},{"num":94,"type":"sa","question":"The development of fiat money is quite perplexing, as people began to value something that is intrinsically useless. Explain why fiat money came into use.","options":null,"answer":null,"images":null,"translation":{"question":"法定货币的发展令人困惑，因为人们开始重视一种本质上无用的东西。解释法定货币为何开始被使用。","options":null},"topics":["money-functions"],"answer_ref":"物物交换需要\"需求的双重巧合\"，交易成本极高。货币作为交换媒介降低了交易成本：便于携带、可分割、易计价。法定货币（fiit money）本身无内在价值，其使用建立在共同信念和社会惯例之上——每个人都预期别人会接受它；加上政府的支持（法定清偿力、可用于纳税），使一套本身无用的符号体系得以履行货币职能。"},{"num":95,"type":"sa","question":"John withdraws $100 from his checking account and deposits it in his saving account. What will be the effect of this transaction on different measures of money, such as C, M1, and M2?","options":null,"answer":null,"images":null,"translation":{"question":"约翰从他的支票账户取出100美元，存入他的储蓄账户。这笔交易对不同的货币度量（如C、M1和M2）会产生什么影响？","options":null},"topics":["money-functions"],"answer_ref":"C（通货）不变：钱从支票账户取出后立即存入储蓄账户，公众手中通货量未变。M1 减少 100 美元：支票存款计入M1，储蓄存款不计入。M2 不变：支票存款与储蓄存款都计入M2，只是构成转移。"},{"num":96,"type":"sa","question":"The monetary base of Moneyland is $500 million. The currency–deposit ratio (cr) is 0.2, and the reserve–deposit ratio (rr) is 0.2. Calculate the money multiplier and money supply.","options":null,"answer":null,"images":null,"translation":{"question":"Moneyland的基础货币为5亿美元。通货-存款比率(cr)为0.2，准备金-存款比率(rr)为0.2。计算货币乘数和货币供给。","options":null},"topics":["money-supply-control"],"answer_ref":"m = (cr+1)/(cr+rr) = 1.2/0.4 = 3。货币供给 M = 3×5亿美元 = 15亿美元。"},{"num":97,"type":"sa","question":"How is the money supply affected by the purchase and sale of bonds through open-market operations?","options":null,"answer":null,"images":null,"translation":{"question":"通过公开市场操作买卖债券如何影响货币供给？","options":null},"topics":["money-supply-control"],"answer_ref":"买入债券：美联储向公众支付新创造的资金，银行准备金和公众存款增加，基础货币扩大，通过乘数货币供给增加。卖出债券：公众以存款支付，准备金和基础货币收缩，货币供给成倍减少。简言之：买债券→扩货币，卖债券→缩货币。"},{"num":98,"type":"sa","question":"“Some economists believe that the large decline in the money supply was the primary cause of the Great Depression of the 1930s.” Explain how this can be the case.","options":null,"answer":null,"images":null,"translation":{"question":"“一些经济学家认为，货币供给的大幅下降是1930年代大萧条的主要原因。”请解释这如何可能成立。","options":null},"topics":["money-supply-control"],"answer_ref":"根据货币数量论，货币供给大幅减少使总支出下降、物价总水平下跌（通缩）。其传导渠道：① 通缩提高货币的实际价值，人们减少支出、增加持币，总需求萎缩；② 未预期通缩提高实际利率、加重实际债务负担（债务-通缩），企业和家庭削减支出、违约增加；③ 物价下跌与挤兑导致银行大量倒闭，货币乘数崩溃，货币供给进一步收缩。于是货币收缩转化为深度衰退与萧条。"},{"num":99,"type":"sa","question":"What is the effect of the following on the money supply? a. Increase in currency–deposit ratio, keeping all other things constant b. Decrease in reserve–deposit ratio, keeping all other things constant","options":null,"answer":null,"images":null,"translation":{"question":"以下各项对货币供给有何影响？a. 通货-存款比率上升（其他条件不变）b. 准备金-存款比率下降（其他条件不变）","options":null},"topics":["money-supply-control"],"answer_ref":"a. cr 上升→货币乘数 (cr+1)/(cr+rr) 变小→货币供给减少。b. rr 下降→货币乘数变大→货币供给增加。"},{"num":100,"type":"sa","question":"The table below represents the balance sheet of a bank. What is the leverage ratio of the bank, and what does it mean? Assets Liabilities and Owners' Equity Reserves 500 Deposits 1,400 Loans 1,000 Debt 400 Securities 500 Owners' equity 200","options":null,"answer":null,"images":null,"translation":{"question":"下表是一家银行的资产负债表。该银行的杠杆率是多少？它意味着什么？资产 负债和所有者权益 准备金 500 存款 1,400 贷款 1,000 债务 400 证券 500 所有者权益 200","options":null},"topics":["banking-fractional"],"answer_ref":"杠杆率 = 总资产/所有者权益 = (500+1000+500)/200 = 10。含义：银行以10倍于自有资本的规模运营，资产价值只要下跌 1/10（10%），200的资本即被全部抹去——银行资不抵债。杠杆率越高，银行越脆弱。"},{"num":101,"type":"sa","question":"The Federal Reserve wants to increase the money supply by printing and distributing 1 million dollars. What will be the actual increase in money supply if the public holds one-fourth of the currency as cash and deposits rest of the money in banks that hold 5 percent of their deposits as reserves?","options":null,"answer":null,"images":null,"translation":{"question":"联邦储备希望通过印制并分发100万美元来增加货币供给。如果公众将四分之一的通货作为现金持有，并将其余的钱存入持有其存款5%作为准备金的银行，那么货币供给的实际增加是多少？","options":null},"topics":["money-supply-control"],"answer_ref":"公众把1/4持为现金、3/4存入银行，故 cr = (1/4)/(3/4) = 1/3；rr = 0.05。m = (1+1/3)/(1/3+0.05) = (4/3)/(0.3833) ≈ 3.48。货币供给实际增加 ≈ 3.48×100万 ≈ 348万美元。"}]},{"num":5,"title":"Inflation","questions":[{"num":1,"type":"mc","question":"The rate of inflation is the:","options":["median level of prices.","average level of prices.","percentage change in the level of prices.","measure of the overall level of prices."],"answer":"C","images":null,"translation":{"question":"通货膨胀率是：","options":["物价的中位数水平。","物价的平均水平。","物价水平的百分比变化。","物价总水平的度量。"]},"topics":["quantity-theory"]},{"num":2,"type":"mc","question":"The definition of the transactions velocity of money is:","options":["money multiplied by prices divided by transactions.","transactions divided by prices multiplied by money.","money divided by prices multiplied by transactions.","prices multiplied by transactions divided by money."],"answer":"D","images":null,"translation":{"question":"货币的交易流通速度的定义是：","options":["货币乘以价格除以交易量。","交易量除以价格乘以货币。","货币除以价格乘以交易量。","价格乘以交易量除以货币。"]},"topics":["quantity-theory"]},{"num":3,"type":"mc","question":"If there are 100 transactions in a year and the average value of each transaction is $10, then if there is $200 of money in the economy, transactions velocity is ______ times per year.","options":["0.2","2","5","10"],"answer":"C","images":null,"translation":{"question":"如果一年中有100笔交易，每笔交易的平均价值为10美元，那么如果经济中有200美元货币，交易流通速度为每年______次。","options":["0.2","2","5","10"]},"topics":["quantity-theory"]},{"num":4,"type":"mc","question":"If the transactions velocity of money remains constant while the quantity of money doubles, the:","options":["price of the average transaction must double.","number of transactions must remain constant.","price of the average transaction multiplied by the number of transactions must remain constant.","price of the average transaction multiplied by the number of transactions must double."],"answer":"D","images":null,"translation":{"question":"如果货币的交易流通速度保持不变，而货币数量翻倍，那么：","options":["平均交易的价格必须翻倍。","交易数量必须保持不变。","平均交易的价格乘以交易数量必须保持不变。","平均交易的价格乘以交易数量必须翻倍。"]},"topics":["quantity-theory"]},{"num":5,"type":"mc","question":"Real money balances equal the:","options":["sum of coin, currency, and balances in checking accounts.","amount of money expressed in terms of the quantity of goods and services it can purchase.","number of dollars used as a medium of exchange.","quantity of money created by the Federal Reserve."],"answer":"B","images":null,"translation":{"question":"实际货币余额等于：","options":["硬币、通货和支票账户余额之和。","以货币所能购买的商品和服务数量表示的货币数量。","用作交易媒介的美元数量。","联邦储备创造的货币数量。"]},"topics":["quantity-theory"]},{"num":6,"type":"mc","question":"If the average price of goods and services in the economy equals $10 and the quantity of money in the economy equals $200,000, then real balances in the economy equal:","options":["10.","20,000.","200,000.","2,000,000."],"answer":"B","images":null,"translation":{"question":"如果经济中商品和服务的平均价格为10美元，经济中的货币数量为200,000美元，那么经济中的实际余额等于：","options":["10。","20,000。","200,000。","2,000,000。"]},"topics":["quantity-theory"]},{"num":7,"type":"mc","question":"The demand for real money balances is generally assumed to:","options":["be exogenous.","be constant.","increase as real income increases.","decrease as real income increases."],"answer":"C","images":null,"translation":{"question":"通常假定对实际货币余额的需求：","options":["是外生的。","是不变的。","随着实际收入增加而增加。","随着实际收入增加而减少。"]},"topics":["quantity-theory"]},{"num":8,"type":"mc","question":"If the quantity of real money balances is kY, where k is a constant, then velocity is:","options":["k.","1/k.","kP.","P/k."],"answer":"B","images":null,"translation":{"question":"如果实际货币余额数量为 kY，其中 k 为常数，那么流通速度为：","options":["k。","1/k。","kP。","P/k。"]},"topics":["quantity-theory"]},{"num":9,"type":"mc","question":"If the demand for real money balances is proportional to real income, velocity will:","options":["increase as income increases.","increase as income decreases.","vary directly with the interest rate.","be constant."],"answer":"D","images":null,"translation":{"question":"如果对实际货币余额的需求与实际收入成比例，那么流通速度将：","options":["随着收入增加而增加。","随着收入减少而增加。","直接随利率变动。","保持不变。"]},"topics":["quantity-theory"]},{"num":10,"type":"mc","question":"Given that M / P = kY, when the demand for money parameter, k, is large, the velocity of money is ______, and money is changing hands ______.","options":["large; frequently","large; infrequently","small; frequently","small; infrequently"],"answer":"D","images":null,"translation":{"question":"给定 M / P = kY，当货币需求参数 k 较大时，货币流通速度______，货币换手______。","options":["大；频繁","大；不频繁","小；频繁","小；不频繁"]},"topics":["quantity-theory"]},{"num":11,"type":"mc","question":"Consider the money demand function that takes the form M / P = kY, where M is the quantity of money, P is the price level, k is a constant, and Y is real output. If the money supply is growing at a 10 percent rate, real output is growing at a 3 percent rate, and k is constant, what is the average inflation rate in this economy?","options":["3 percent","7 percent","10 percent","13 percent"],"answer":"B","images":null,"translation":{"question":"考虑形如 M / P = kY 的货币需求函数，其中 M 为货币数量，P 为价格水平，k 为常数，Y 为实际产出。如果货币供给以10%的速度增长，实际产出以3%的速度增长，且 k 不变，那么该经济的平均通货膨胀率是多少？","options":["3%","7%","10%","13%"]},"topics":["quantity-theory"]},{"num":12,"type":"mc","question":"When people want to hold _____ money, the income velocity of money increases, and the money demand parameter k ______ .","options":["more; increases","less; increases","more; decreases","less; decreases"],"answer":"D","images":null,"translation":{"question":"当人们希望持有______货币时，货币的收入流通速度增加，而货币需求参数 k ______。","options":["更多；增加","更少；增加","更多；减少","更少；减少"]},"topics":["quantity-theory"]},{"num":13,"type":"mc","question":"The quantity theory of money assumes that:","options":["income is constant.","velocity is constant.","prices are constant.","the money supply is constant."],"answer":"B","images":null,"translation":{"question":"货币数量论假定：","options":["收入不变。","流通速度不变。","价格不变。","货币供给不变。"]},"topics":["quantity-theory"]},{"num":14,"type":"mc","question":"If income velocity is assumed to be constant, but no other assumptions are made, the level of ______ is determined by M.","options":["prices","real GDP","transactions","nominal GDP"],"answer":"D","images":null,"translation":{"question":"如果假定收入流通速度不变，但不作其他假定，那么______的水平由 M 决定。","options":["价格","实际GDP","交易","名义GDP"]},"topics":["quantity-theory"]},{"num":15,"type":"mc","question":"If velocity is constant and, in addition, the factors of production and the production function determine real GDP, then:","options":["the price level is proportional to the money supply.","real GDP is proportional to the money supply.","the price level is fixed.","nominal GDP is fixed."],"answer":"A","images":null,"translation":{"question":"如果流通速度不变，且此外生产要素和生产函数决定实际GDP，那么：","options":["价格水平与货币供给成比例。","实际GDP与货币供给成比例。","价格水平是固定的。","名义GDP是固定的。"]},"topics":["quantity-theory"]},{"num":16,"type":"mc","question":"In the long run, according to the quantity theory of money and classical macroeconomic theory, if velocity is constant, then ______ determines real GDP and ______ determines nominal GDP.","options":["the productive capability of the economy; the money supply","the money supply; the productive capability of the economy","velocity; the money supply","the money supply; velocity"],"answer":"A","images":null,"translation":{"question":"在长期，根据货币数量论和古典宏观经济理论，如果流通速度不变，那么______决定实际GDP，______决定名义GDP。","options":["经济的生产能力；货币供给","货币供给；经济的生产能力","流通速度；货币供给","货币供给；流通速度"]},"topics":["quantity-theory"]},{"num":17,"type":"mc","question":"According to the quantity theory of money, ultimate control over the rate of inflation in the United States is exercised by:","options":["the Organization of the Petroleum Exporting Countries (OPEC).","the U.S. Treasury.","the Federal Reserve.","private citizens."],"answer":"C","images":null,"translation":{"question":"根据货币数量论，对美国通货膨胀率的最终控制权由：","options":["石油输出国组织（OPEC）行使。","美国财政部行使。","联邦储备（美联储）行使。","普通公民行使。"]},"topics":["quantity-theory"]},{"num":18,"type":"mc","question":"According to the quantity theory of money, if money is growing at a 10 percent rate and real output is growing at a 3 percent rate, but velocity is growing at increasingly faster rates over time as a result of financial innovation, the rate of inflation must be:","options":["increasing.","decreasing.","7 percent.","constant."],"answer":"A","images":null,"translation":{"question":"根据货币数量论，如果货币以10%的速度增长，实际产出以3%的速度增长，但由于金融创新，流通速度随时间以越来越快的速度增长，那么通货膨胀率必定：","options":["上升。","下降。","为7%。","不变。"]},"topics":["quantity-theory"]},{"num":19,"type":"mc","question":"If the money supply increases 12 percent, velocity decreases 4 percent, and the price level increases 5 percent, then the change in real GDP must be ______ percent.","options":["3","4","9","11"],"answer":"A","images":null,"translation":{"question":"如果货币供给增加12%，流通速度下降4%，价格水平上升5%，那么实际GDP的变化必定为______%。","options":["3","4","9","11"]},"topics":["quantity-theory"]},{"num":20,"type":"mc","question":"Percentage change in P is approximately equal to the percentage change in:","options":["M.","M minus the percentage change in Y.","M minus the percentage change in Y plus the percentage change in velocity.","M minus the percentage change in Y minus the percentage change in velocity."],"answer":"C","images":null,"translation":{"question":"P 的百分比变化近似等于：","options":["M 的百分比变化。","M 的百分比变化减去 Y 的百分比变化。","M 的百分比变化减去 Y 的百分比变化再加上流通速度的百分比变化。","M 的百分比变化减去 Y 的百分比变化再减去流通速度的百分比变化。"]},"topics":["quantity-theory"]},{"num":21,"type":"mc","question":"Using average rates of money growth and inflation in the United States over many decades, Friedman and Schwartz found that decades of high money growth tended to have ______ rates of inflation and decades of low money growth tended to have ______ rates of inflation.","options":["high; high","high; low","low; low","low; high"],"answer":"B","images":null,"translation":{"question":"利用美国数十年间货币增长与通货膨胀的平均数据，弗里德曼和施瓦茨发现，货币高增长的几十年往往有______的通货膨胀率，而货币低增长的几十年往往有______的通货膨胀率。","options":["高；高","高；低","低；低","低；高"]},"topics":["quantity-theory"]},{"num":22,"type":"mc","question":"The right of seigniorage is the right to:","options":["levy taxes on the public.","borrow money from the public.","draft citizens into the armed forces.","print money."],"answer":"D","images":null,"translation":{"question":"铸币税的权利是：","options":["向公众征税的权利。","向公众借款的权利。","征召公民入伍的权利。","印制货币的权利。"]},"topics":["seigniorage-hyper"]},{"num":23,"type":"mc","question":"“Inflation tax” means that:","options":["as the price level rises, taxpayers are pushed into higher tax brackets.","as the price level rises, the real value of money held by the public decreases.","as taxes increase, the rate of inflation also increases.","in a hyperinflation, the chief source of tax revenue is often the printing of money."],"answer":"B","images":null,"translation":{"question":"“通货膨胀税”意味着：","options":["随着价格水平上升，纳税人被推入更高的税率档。","随着价格水平上升，公众持有的货币的实际价值下降。","随着税收增加，通货膨胀率也上升。","在恶性通胀中，税收收入的主要来源往往是印制货币。"]},"topics":["seigniorage-hyper"]},{"num":24,"type":"mc","question":"The inflation tax is paid:","options":["only by the central bank.","by all holders of money.","only by government bond holders.","equally by every household."],"answer":"B","images":null,"translation":{"question":"通货膨胀税由：","options":["仅由中央银行支付。","所有货币持有者支付。","仅由政府债券持有者支付。","每个家庭均等地支付。"]},"topics":["seigniorage-hyper"]},{"num":25,"type":"mc","question":"The real interest rate is equal to the:","options":["amount of interest that a lender actually receives when making a loan.","nominal interest rate plus the inflation rate.","nominal interest rate minus the inflation rate.","nominal interest rate."],"answer":"C","images":null,"translation":{"question":"实际利率等于：","options":["贷款者发放贷款时实际收到的利息额。","名义利率加通货膨胀率。","名义利率减通货膨胀率。","名义利率。"]},"topics":["fisher-effect"]},{"num":26,"type":"mc","question":"If the nominal interest rate is 1 percent and the inflation rate is 5 percent, the real interest rate is:","options":["1 percent.","6 percent.","–4 percent.","–5 percent."],"answer":"C","images":null,"translation":{"question":"如果名义利率为1%，通货膨胀率为5%，那么实际利率为：","options":["1%。","6%。","–4%。","–5%。"]},"topics":["fisher-effect"]},{"num":27,"type":"mc","question":"If the real interest rate declines by 1 percent and the inflation rate increases by 2 percent, the nominal interest rate implied by the Fisher equation:","options":["increases by 2 percent.","increases by 1 percent.","remains constant.","decreases by 1 percent."],"answer":"B","images":null,"translation":{"question":"如果实际利率下降1%，通货膨胀率上升2%，那么费雪方程所隐含的名义利率：","options":["上升2%。","上升1%。","保持不变。","下降1%。"]},"topics":["fisher-effect"]},{"num":28,"type":"mc","question":"If the real interest rate and real national income are constant, according to the quantity theory and the Fisher effect, a 1 percent increase in money growth will lead to rises in:","options":["inflation of 1 percent and the nominal interest rate of less than 1 percent.","inflation of 1 percent and the nominal interest rate of 1 percent.","inflation of 1 percent and the nominal interest rate of more than 1 percent.","both inflation and the nominal interest rate of less than 1 percent."],"answer":"B","images":null,"translation":{"question":"如果实际利率和实际国民收入不变，根据货币数量论和费雪效应，货币增长增加1%将导致：","options":["通货膨胀率上升1%，名义利率上升不到1%。","通货膨胀率上升1%，名义利率上升1%。","通货膨胀率上升1%，名义利率上升超过1%。","通货膨胀率和名义利率都上升不到1%。"]},"topics":["fisher-effect"]},{"num":29,"type":"mc","question":"According to the quantity theory of money, a 5 percent increase in money growth increases inflation by ___ percent. According to the Fisher equation, a 5 percent increase in the rate of inflation increases the nominal interest rate by ____ percent.","options":["1; 5","5; 1","1; 1","5; 5"],"answer":"D","images":null,"translation":{"question":"根据货币数量论，货币增长增加5%会使通货膨胀率增加______%。根据费雪方程，通货膨胀率增加5%会使名义利率增加______%。","options":["1；5","5；1","1；1","5；5"]},"topics":["fisher-effect"]},{"num":30,"type":"mc","question":"According to the quantity theory of money and the Fisher equation, if the money growth increases by 3 percent and the real interest rate equals 2 percent, then the nominal interest rate will increase:","options":["2 percent.","3 percent.","5 percent.","6 percent."],"answer":"C","images":null,"translation":{"question":"根据货币数量论和费雪方程，如果货币增长增加3%，且实际利率等于2%，那么名义利率将增加：","options":["2%。","3%。","5%。","6%。"]},"topics":["fisher-effect"]},{"num":31,"type":"mc","question":"In the classical model, according to the quantity theory of money and the Fisher equation, an increase in money growth increases:","options":["output.","velocity.","the nominal interest rate.","the real interest rate."],"answer":"C","images":null,"translation":{"question":"在古典模型中，根据货币数量论和费雪方程，货币增长增加会提高：","options":["产出。","流通速度。","名义利率。","实际利率。"]},"topics":["fisher-effect"]},{"num":32,"type":"mc","question":"Evidence from the past 40 years in the United States supports the Fisher effect and shows that when the inflation rate is high, the ______ interest rate tends to be ______.","options":["nominal; high","nominal; low","real; high","real; low"],"answer":"A","images":null,"translation":{"question":"美国过去40年的证据支持费雪效应，并表明当通货膨胀率高时，______利率往往______。","options":["名义；高","名义；低","实际；高","实际；低"]},"topics":["fisher-effect"]},{"num":33,"type":"mc","question":"The ex ante real interest rate is equal to the nominal interest rate:","options":["minus the inflation rate.","plus the inflation rate.","minus the expected inflation rate.","plus the expected inflation rate."],"answer":"C","images":null,"translation":{"question":"事前实际利率等于名义利率：","options":["减通货膨胀率。","加通货膨胀率。","减预期通货膨胀率。","加预期通货膨胀率。"]},"topics":["fisher-effect"]},{"num":34,"type":"mc","question":"When a person purchases a 90-day Treasury bill, he or she cannot know the:","options":["ex post real interest rate.","ex ante real interest rate.","nominal interest rate.","expected rate of inflation."],"answer":"A","images":null,"translation":{"question":"当一个人购买90天期国债时，他（她）无法知道：","options":["事后实际利率。","事前实际利率。","名义利率。","预期通货膨胀率。"]},"topics":["fisher-effect"]},{"num":35,"type":"mc","question":"Equilibrium in the market for goods and services determines the ______ interest rate, and the expected rate of inflation determines the ______ interest rate.","options":["ex ante real; ex ante nominal","ex post real; ex post nominal","ex ante nominal; ex post real","ex post nominal; ex post real"],"answer":"A","images":null,"translation":{"question":"商品和服务市场的均衡决定______利率，预期通货膨胀率决定______利率。","options":["事前实际；事前名义","事后实际；事后名义","事前名义；事后实际","事后名义；事后实际"]},"topics":["fisher-effect"]},{"num":36,"type":"mc","question":"The ex ante real interest rate is based on _____ inflation, while the ex post real interest rate is based on _____ inflation.","options":["expected; actual","core; actual","actual; expected","expected; core"],"answer":"A","images":null,"translation":{"question":"事前实际利率基于______通货膨胀，而事后实际利率基于______通货膨胀。","options":["预期；实际","核心；实际","实际；预期","预期；核心"]},"topics":["fisher-effect"]},{"num":37,"type":"mc","question":"The ex post real interest rate will be greater than the ex ante real interest rate when the:","options":["rate of inflation is increasing.","rate of inflation is decreasing.","actual rate of inflation is greater than the expected rate of inflation.","actual rate of inflation is less than the expected rate of inflation."],"answer":"D","images":null,"translation":{"question":"当事后实际利率大于事前实际利率时，","options":["通货膨胀率正在上升。","通货膨胀率正在下降。","实际通货膨胀率大于预期通货膨胀率。","实际通货膨胀率小于预期通货膨胀率。"]},"topics":["fisher-effect"]},{"num":38,"type":"mc","question":"The opportunity cost of holding money is the:","options":["nominal interest rate.","real interest rate.","federal funds rate.","prevailing Treasury bill rate."],"answer":"A","images":null,"translation":{"question":"持有货币的机会成本是：","options":["名义利率。","实际利率。","联邦基金利率。","现行的国债利率。"]},"topics":["fisher-effect"]},{"num":39,"type":"mc","question":"The real return on holding money is","options":["the real interest rate.","minus the real interest rate.","the inflation rate.","minus the inflation rate."],"answer":"D","images":null,"translation":{"question":"持有货币的实际回报为：","options":["实际利率。","负的实际利率。","通货膨胀率。","负的通货膨胀率。"]},"topics":["fisher-effect"]},{"num":40,"type":"mc","question":"If the real return on government bonds is 3 percent and the expected rate of inflation is 4 percent, then the cost of holding money is ______ percent.","options":["1","3","4","7"],"answer":"D","images":null,"translation":{"question":"如果政府债券的实际回报为3%，预期通货膨胀率为4%，那么持有货币的成本为______%。","options":["1","3","4","7"]},"topics":["fisher-effect"]},{"num":41,"type":"mc","question":"In its most general formulation, the demand function for real balances depends on the level of income and the:","options":["real interest rate.","nominal interest rate.","rate of inflation.","price level."],"answer":"B","images":null,"translation":{"question":"在最一般的形式下，实际余额的需求函数取决于收入水平和：","options":["实际利率。","名义利率。","通货膨胀率。","价格水平。"]},"topics":["fisher-effect"]},{"num":42,"type":"mc","question":"If the nominal interest rate increases, then:","options":["the money supply increases.","the money supply decreases.","the demand for money increases.","the demand for money decreases."],"answer":"D","images":null,"translation":{"question":"如果名义利率上升，那么：","options":["货币供给增加。","货币供给减少。","货币需求增加。","货币需求减少。"]},"topics":["fisher-effect"]},{"num":43,"type":"mc","question":"Consider the money demand function that takes the form (M / P)d = Y / (4i), where M is the quantity of money, P is the price level, Y is real output, and i is the nominal interest rate. What is the average velocity of money in this economy?","options":["i","4","1 / (4i)","0.25"],"answer":"B","images":null,"translation":{"question":"考虑形如 (M / P)d = Y / (4i) 的货币需求函数，其中 M 为货币数量，P 为价格水平，Y 为实际产出，i 为名义利率。该经济中货币的平均流通速度是多少？","options":["i","4","1 / (4i)","0.25"]},"topics":["fisher-effect"]},{"num":44,"type":"mc","question":"If the Fed announces that it will raise the money supply in the future but does not change the money supply today,","options":["both the nominal interest rate and the current price level will decrease.","the nominal interest rate will increase and the current price level will decrease.","the nominal interest rate will decrease and the current price level will increase.","both the nominal interest rate and the current price level will increase."],"answer":"D","images":null,"translation":{"question":"如果美联储宣布未来将增加货币供给，但今天并不改变货币供给，","options":["名义利率和当前价格水平都会下降。","名义利率将上升，当前价格水平将下降。","名义利率将下降，当前价格水平将上升。","名义利率和当前价格水平都会上升。"]},"topics":["fisher-effect"]},{"num":45,"type":"mc","question":"If the money supply is held constant, then an increase in the nominal interest rate will ______ the demand for money and ______ the price level.","options":["increase; increase","increase; decrease","decrease; increase","decrease; decrease"],"answer":"C","images":null,"translation":{"question":"如果货币供给保持不变，那么名义利率上升将______货币需求，并______价格水平。","options":["增加；增加","增加；降低","减少；提高","减少；降低"]},"topics":["fisher-effect"]},{"num":46,"type":"mc","question":"If the demand for money depends on the nominal interest rate, then via the quantity theory and the Fisher equation, the price level depends on:","options":["only the current money supply.","only the expected future money supply.","both the current and expected future money supply.","neither the current nor the expected future money supply."],"answer":"C","images":null,"translation":{"question":"如果货币需求取决于名义利率，那么通过货币数量论和费雪方程，价格水平取决于：","options":["仅当前的货币供给。","仅预期的未来货币供给。","当前和预期的未来货币供给两者。","当前和预期的未来货币供给两者都不取决于。"]},"topics":["fisher-effect"]},{"num":47,"type":"mc","question":"According to the classical theory of money, reducing inflation will not make workers richer because firms will increase product prices ______ each year and give workers ______ raises.","options":["more; larger","more; smaller","less; larger","less; smaller"],"answer":"D","images":null,"translation":{"question":"根据古典货币理论，降低通货膨胀不会使工人更富有，因为企业将每年______地提高产品价格，并给工人______的加薪。","options":["更多；更大","更多；更小","更少；更大","更少；更小"]},"topics":["inflation-costs"]},{"num":48,"type":"mc","question":"According to the classical theory of money, inflation does not make workers poorer because wages increase:","options":["faster than the overall price level.","more slowly than the overall price level.","in proportion to the increase in the overall price level.","in real terms during periods of inflation."],"answer":"C","images":null,"translation":{"question":"根据古典货币理论，通货膨胀不会使工人更贫穷，因为工资增加：","options":["快于物价总水平的上升。","慢于物价总水平的上升。","与物价总水平的上升成比例。","在通货膨胀期间按实际值增加。"]},"topics":["inflation-costs"]},{"num":49,"type":"mc","question":"The inconvenience associated with reducing money holdings to avoid the inflation tax is called:","options":["menu costs.","shoeleather costs.","variable yardstick costs.","fixed costs."],"answer":"B","images":null,"translation":{"question":"为规避通货膨胀税而减少货币持有所带来的不便被称为：","options":["菜单成本。","皮鞋成本。","变动的尺码成本。","固定成本。"]},"topics":["inflation-costs"]},{"num":50,"type":"mc","question":"The costs of reprinting catalogs and price lists because of inflation are called:","options":["menu costs.","shoeleather costs.","variable yardstick costs.","fixed costs."],"answer":"A","images":null,"translation":{"question":"因通货膨胀而重新印制目录和价目表的成本被称为：","options":["菜单成本。","皮鞋成本。","变动的尺码成本。","固定成本。"]},"topics":["inflation-costs"]},{"num":51,"type":"mc","question":"Inflation ______ the variability of relative prices and ______ the efficiency of the allocation of resources.","options":["increases; increases","increases; decreases","decreases; decreases","decreases; increases"],"answer":"B","images":null,"translation":{"question":"通货膨胀______相对价格的波动性，并______资源配置的效率。","options":["增加；提高","增加；降低","降低；降低","降低；提高"]},"topics":["inflation-costs"]},{"num":52,"type":"mc","question":"In the case of an unanticipated increase in inflation:","options":["creditors with an unindexed contract are hurt because they get less than they expected in real terms.","creditors with an indexed contract gain because they get more than they contracted for in nominal terms.","debtors with an unindexed contract do not gain because they pay exactly what they contracted for in nominal terms.","debtors with an indexed contract are hurt because they pay more than they contracted for in nominal terms."],"answer":"A","images":null,"translation":{"question":"在未预期到的通货膨胀上升的情况下：","options":["持有非指数化合同的债权人受损，因为他们实际得到的少于预期。","持有指数化合同的债权人获益，因为他们名义上得到的多于合同规定。","持有非指数化合同的债务人不受益，因为他们名义上支付的正是合同规定。","持有指数化合同的债务人受损，因为他们名义上支付的多于合同规定。"]},"topics":["inflation-costs"]},{"num":53,"type":"mc","question":"The costs of unexpected inflation, but not of expected inflation, are:","options":["menu costs.","the arbitrary redistribution of wealth between debtors and creditors.","unintended distortions of individual tax liabilities.","the costs of relative price variability."],"answer":"B","images":null,"translation":{"question":"未预期通货膨胀（而非预期通货膨胀）的成本是：","options":["菜单成本。","债务人与债权人之间财富的任意再分配。","个人税负的意外扭曲。","相对价格波动的成本。"]},"topics":["inflation-costs"]},{"num":54,"type":"mc","question":"If inflation was 6 percent last year and a worker received a 4 percent nominal wage increase last year, then the worker's real wage:","options":["increased 4 percent.","increased 2 percent.","decreased 2 percent.","decreased 6 percent."],"answer":"C","images":null,"translation":{"question":"如果去年通货膨胀率为6%，一个工人去年获得了4%的名义工资增长，那么该工人的实际工资：","options":["增加了4%。","增加了2%。","减少了2%。","减少了6%。"]},"topics":["inflation-costs"]},{"num":55,"type":"mc","question":"If nominal wages cannot be cut, then the only way to reduce real wages is by:","options":["adjustments via inflation.","unions.","legislation.","productivity increases."],"answer":"A","images":null,"translation":{"question":"如果名义工资不能被削减，那么降低实际工资的唯一途径是：","options":["通过通货膨胀进行调整。","工会。","立法。","生产率提高。"]},"topics":["inflation-costs"]},{"num":56,"type":"mc","question":"A rate of inflation that exceeds 50 percent per month is typically referred to as a:","options":["conflagration.","hyperinflation.","deflation.","disinflation."],"answer":"B","images":null,"translation":{"question":"每月超过50%的通货膨胀率通常被称为：","options":["大爆发。","恶性通货膨胀。","通货紧缩。","反通货膨胀。"]},"topics":["seigniorage-hyper"]},{"num":57,"type":"mc","question":"Hyperinflations ultimately are the result of excessive growth rates of the money supply; the underlying motive for the excessive money growth rates is frequently a government's:","options":["desire to increase prices throughout the economy.","need to generate revenue to pay for spending.","responsibility to increase nominal interest rates by increasing expected inflation.","inability to buy government securities through open-market operations."],"answer":"B","images":null,"translation":{"question":"恶性通货膨胀最终是货币供给过度增长的结果；这种过度货币增长背后的动机往往是政府：","options":["希望提高整个经济的价格。","需要创造收入以支付开支。","有责任通过提高预期通货膨胀来提高名义利率。","无法通过公开市场操作购买政府债券。"]},"topics":["seigniorage-hyper"]},{"num":58,"type":"mc","question":"Which of the following would most likely be called a hyperinflation?","options":["Price increases averaged 300 percent per year.","The inflation rate was 10 percent per year.","Real GDP grew at a rate of 12 percent over a year.","A stock market index rose by 1,000 points over a year."],"answer":"A","images":null,"translation":{"question":"以下哪种情况最可能被称为恶性通货膨胀？","options":["价格平均每年上涨300%。","通货膨胀率为每年10%。","实际GDP在一年内增长12%。","股票市场指数在一年内上涨1,000点。"]},"topics":["seigniorage-hyper"]},{"num":59,"type":"mc","question":"During a hyperinflation, real tax revenue of the government often drops substantially because of the:","options":["delay between when a tax is levied and when it is collected.","significantly greater menu costs of printing tax forms.","additional deductions taken for increased shoeleather costs.","greater uncertainty associated with extreme rates of inflation."],"answer":"A","images":null,"translation":{"question":"在恶性通货膨胀期间，政府的实际税收收入往往大幅下降，原因是：","options":["征税与收税之间的时间延迟。","印制税表的菜单成本显著增大。","为增加的皮鞋成本而进行的额外扣除。","极端通货膨胀率带来的更大不确定性。"]},"topics":["seigniorage-hyper"]},{"num":60,"type":"mc","question":"The major source of government revenue in most countries that are experiencing hyperinflation is:","options":["customs duties.","income taxes.","seigniorage.","borrowing."],"answer":"C","images":null,"translation":{"question":"在大多数经历恶性通货膨胀的国家，政府收入的主要来源是：","options":["关税。","所得税。","铸币税。","借款。"]},"topics":["seigniorage-hyper"]},{"num":61,"type":"mc","question":"To end a hyperinflation, a government trying to reduce its reliance on seigniorage would:","options":["print more money.","raise taxes and cut spending.","lower taxes and increase spending.","lower interest rates."],"answer":"B","images":null,"translation":{"question":"为了结束恶性通货膨胀，试图减少对铸币税依赖的政府应当：","options":["印制更多货币。","提高税收并削减开支。","降低税收并增加开支。","降低利率。"]},"topics":["seigniorage-hyper"]},{"num":62,"type":"mc","question":"Most hyperinflations end with _____ reforms that eliminate the need for _____.","options":["monetary; taxes","monetary; currency","fiscal; seigniorage","fiscal; currency"],"answer":"C","images":null,"translation":{"question":"大多数恶性通货膨胀以______改革结束，这些改革消除了对______的需要。","options":["货币；税收","货币；通货","财政；铸币税","财政；通货"]},"topics":["seigniorage-hyper"]},{"num":63,"type":"mc","question":"Which of the following is an example of a relative price?","options":["the real interest rate","the capital stock","the dollar wage per hour","the price level"],"answer":"A","images":null,"translation":{"question":"以下哪项是相对价格的例子？","options":["实际利率","资本存量","每小时美元工资","价格水平"]},"topics":["quantity-theory"]},{"num":64,"type":"mc","question":"Variables expressed in terms of physical units or quantities are called ______ variables.","options":["real","nominal","endogenous","exogenous"],"answer":"A","images":null,"translation":{"question":"以实物单位或数量表示的变量被称为______变量。","options":["实际","名义","内生","外生"]},"topics":["quantity-theory"]},{"num":65,"type":"mc","question":"Variables expressed in terms of money are called ______ variables.","options":["real","nominal","endogenous","exogenous"],"answer":"B","images":null,"translation":{"question":"以货币表示的变量被称为______变量。","options":["实际","名义","内生","外生"]},"topics":["quantity-theory"]},{"num":66,"type":"mc","question":"An example of a real variable is the:","options":["dollar wage a person earns.","quantity of goods produced in a year.","price level.","nominal interest rate."],"answer":"B","images":null,"translation":{"question":"实际变量的一个例子是：","options":["一个人赚取的美元工资。","一年中生产的商品数量。","价格水平。","名义利率。"]},"topics":["quantity-theory"]},{"num":67,"type":"mc","question":"An example of a nominal variable is the:","options":["money supply.","quantity of goods produced in a year.","relative price of bread.","real wage."],"answer":"A","images":null,"translation":{"question":"名义变量的一个例子是：","options":["货币供给。","一年中生产的商品数量。","面包的相对价格。","实际工资。"]},"topics":["quantity-theory"]},{"num":68,"type":"mc","question":"The classical dichotomy:","options":["cannot hold if money is “neutral.”","is said to hold when the values of real variables can be determined without any reference to nominal variables or the existence of money.","fully describes the world in which we live, especially in the short run.","arises because money depends on the nominal interest rate."],"answer":"B","images":null,"translation":{"question":"古典二分法：","options":["如果货币是“中性”的，就不能成立。","当实际变量的值可以在不参照名义变量或货币存在的情况下确定时，就说它成立。","完全描述了我们所生活的世界，尤其是在短期。","之所以出现，是因为货币取决于名义利率。"]},"topics":["quantity-theory"]},{"num":69,"type":"mc","question":"According to the classical dichotomy, when the money supply decreases, _____ will decrease.","options":["real GDP","consumption spending","the price level","investment spending"],"answer":"C","images":null,"translation":{"question":"根据古典二分法，当货币供给减少时，______将减少。","options":["实际GDP","消费支出","价格水平","投资支出"]},"topics":["quantity-theory"]},{"num":70,"type":"mc","question":"The concept of monetary neutrality in the classical model means that an increase in the money supply growth rate will increase:","options":["real GDP.","real interest rates.","nominal interest rates.","both saving and investment by the same amount."],"answer":"C","images":null,"translation":{"question":"古典模型中的货币中性概念意味着，货币供给增长率的提高将提高：","options":["实际GDP。","实际利率。","名义利率。","储蓄和投资（提高相同的数量）。"]},"topics":["quantity-theory"]},{"num":71,"type":"mc","question":"The characteristic of the classical model that the money supply does not affect real variables is called:","options":["the monetary basis.","monetary policy.","the quantity theory of money.","monetary neutrality."],"answer":"D","images":null,"translation":{"question":"古典模型的这一特征——货币供给不影响实际变量——被称为：","options":["货币基础。","货币政策。","货币数量论。","货币中性。"]},"topics":["quantity-theory"]},{"num":72,"type":"mc","question":"The theoretical separation of real and monetary variables is called:","options":["the classical dichotomy.","monetary neutrality.","the Fisher effect.","the quantity theory of money."],"answer":"A","images":null,"translation":{"question":"实际变量与货币变量的理论分离被称为：","options":["古典二分法。","货币中性。","费雪效应。","货币数量论。"]},"topics":["quantity-theory"]},{"num":73,"type":"mc","question":"A small country might want to use the money of a large country rather than print its own money if the small country:","options":["is likely to be unstable, whereas the large country is likely to be stable.","is likely to be stable, whereas the large country is likely to be unstable.","needs the revenue for seigniorage.","wants to control its own inflation rate."],"answer":"A","images":null,"translation":{"question":"一个小国可能希望使用大国的货币而不是印制自己的货币，如果这个小国：","options":["可能不稳定，而大国可能稳定。","可能稳定，而大国可能不稳定。","需要铸币税收入。","希望控制自己的通货膨胀率。"]},"topics":["quantity-theory"]},{"num":74,"type":"mc","question":"If consumption depends positively on the level of real balances, and real balances depend negatively on the nominal interest rate, then:","options":["the classical dichotomy still holds.","a rise in money growth leads to a fall in consumption and a rise in investment.","a rise in money growth leads to a rise in consumption and a fall in investment.","a rise in money growth leads to a rise in both consumption and investment."],"answer":"B","images":null,"translation":{"question":"如果消费正向地取决于实际余额水平，而实际余额负向地取决于名义利率，那么：","options":["古典二分法仍然成立。","货币增长上升导致消费下降、投资上升。","货币增长上升导致消费上升、投资下降。","货币增长上升导致消费和投资都上升。"]},"topics":["quantity-theory"]},{"num":75,"type":"mc","question":"If consumption depends positively on the level of real balances and real balances depend negatively on the nominal interest rate, then the nominal interest rate:","options":["declines when the money growth rate rises.","is unchanged when the money growth rate rises.","rises 1 percent for each 1 percent rise in the money growth rate.","rises less than 1 percent for each 1 percent rise in the money growth rate."],"answer":"D","images":null,"translation":{"question":"如果消费正向地取决于实际余额水平，而实际余额负向地取决于名义利率，那么名义利率：","options":["在货币增长率上升时下降。","在货币增长率上升时不变。","货币增长率每上升1%就上升1%。","货币增长率每上升1%上升不到1%。"]},"topics":["quantity-theory"]},{"num":76,"type":"sa","question":"Assume that a series of inflation rates is 1 percent, 2 percent, and 4 percent, while nominal interest rates in the same three periods are 5 percent, 5 percent, and 6 percent, respectively. a. What are the ex post real interest rates in the same three periods? b. If the expected inflation rate in each period is the realized inflation rate in the previous period, what are the ex ante real interest rates in periods 2 and 3? c. If someone lends in period 2, based on the ex ante inflation expectation in part b, will he or she be pleasantly or unpleasantly surprised in period 3 when the loan is repaid?","options":null,"answer":null,"images":null,"translation":{"question":"假设一系列通货膨胀率为1%、2%和4%，而同一三个时期的名义利率分别为5%、5%和6%。a. 同一三个时期的事后实际利率是多少？b. 如果每个时期的预期通货膨胀率是上一时期的已实现通货膨胀率，那么第2期和第3期的事前实际利率是多少？c. 如果某人在第2期放贷，基于b部分的事前通货膨胀预期，他（她）在第3期贷款偿还时会感到愉快还是不愉快？","options":null},"topics":["fisher-effect"],"answer_ref":"a. 事后实际利率 = 名义利率 − 实际通胀：4%、3%、2%。b. 预期通胀=上一期实际通胀：第2期事前实际利率 = 5−1 = 4%；第3期 = 6−2 = 4%。c. 放贷者会大失所望（unpleasantly surprised）：第3期实际通胀高达4%，事后实际利率只有2%，低于放贷时预期的4%，实际收回的购买力缩水。"},{"num":77,"type":"sa","question":"Mary Tsai is paid $3,000 every 30 days. Her salary is deposited directly in her bank. She spends all her money at a constant rate over the 30 days and must pay cash. She can (1) withdraw all of the money at once; (2) withdraw half at once and the rest after 15 days; (3) withdraw one-third at once, one-third after 10 days, and one-third at 20 days; or (4) make any number of evenly spaced withdrawals. Each withdrawal costs her $2 in terms of time and inconvenience. For each day that Mary has a dollar in the bank, she gets .03 cents (.0003 per dollar) in interest. Thus, if she withdraws half of her money immediately and half in 15 days, she has $1,500 in the bank for 15 days and earns $6.75 interest. a. Create a table showing transaction costs, interest earned, and total net earnings (+) or cost (–) associated with one, two, three, or four withdrawals per month. b. How many withdrawals per month lead to the largest net earnings? If Mary chooses this number, what will be her average amount of cash on hand over the 30 days?","options":null,"answer":null,"images":null,"translation":{"question":"玛丽·蔡（Mary Tsai）每30天获得3,000美元的工资。她的工资直接存入她的银行账户。她在30天内以恒定速度花光所有钱，并且必须用现金支付。她可以（1）一次性取出所有钱；（2）先取一半，15天后再取其余；（3）先取三分之一，10天后取三分之一，20天后再取三分之一；或（4）进行任意次数的等间隔取款。每次取款在时间和不便方面花费她2美元。玛丽在银行里每存一天一美元，就能获得0.03美分（每美元0.0003）的利息。因此，如果她立即取出一半，15天后取另一半，她在银行里有1,500美元存15天，赚取6.75美元利息。a. 制作一个表格，显示每月取款一次、两次、三次或四次时的交易成本、赚取的利息以及总净收益（+）或成本（–）。b. 每月取款多少次能带来最大的净收益？如果玛丽选择这个次数，她在30天内的平均手持现金是多少？","options":null},"topics":["inflation-costs"],"answer_ref":"a. 净收益 = 利息 − 交易成本（每次取款的间隔为30/N天）：N=1：利息 0（钱全部取走），成本2，净 −2；N=2：利息6.75，成本4，净 +2.75；N=3：利息 = 0.0003×10×(2000+1000) = 9，成本6，净 +3；N=4：利息 = 0.0003×7.5×(2250+1500+750) = 10.125，成本8，净 +2.125。b. 每月取3次净收益最大（+3美元）。此时她手上的现金：每10天持有1000、2000、3000递减，平均现金持有 = (10×2500+10×1500+10×500)/30 = 1500美元。"},{"num":78,"type":"sa","question":"Assume that the demand for real money balance (M / P) is M / P = 0.6Y – 100i, where Y is national income, and i is the nominal interest rate (in percent). The real interest rate r is fixed at 3 percent by the investment and saving functions. The expected inflation rate equals the rate of nominal money growth. a. If Y is 1,000, M is 100, and the growth rate of nominal money is 1 percent, what must i and P be? b. If Y is 1,000, M is 100, and the growth rate of nominal money is 2 percent, what must i and P be?","options":null,"answer":null,"images":null,"translation":{"question":"假设对实际货币余额(M / P)的需求为 M / P = 0.6Y – 100i，其中 Y 为国民收入，i 为名义利率（以百分比计）。实际利率 r 由投资和储蓄函数固定为3%。预期通货膨胀率等于名义货币增长率。a. 如果 Y 为1,000，M 为100，名义货币增长率为1%，那么 i 和 P 必须是多少？b. 如果 Y 为1,000，M 为100，名义货币增长率为2%，那么 i 和 P 必须是多少？","options":null},"topics":["fisher-effect"],"answer_ref":"费雪方程 i = r + π^e，且 π^e = 货币增长率。a. i = 3% + 1% = 4%；实际货币需求 M/P = 0.6×1000 − 100×4 = 200，故 P = 100/200 = 0.5。b. i = 3% + 2% = 5%；M/P = 600 − 500 = 100，故 P = 100/100 = 1。"},{"num":79,"type":"sa","question":"Econoland finances government expenditures with an inflation tax. a. Explain who pays the tax and how it is paid. b. What are the costs associated with an inflation tax?","options":null,"answer":null,"images":null,"translation":{"question":"Econoland 用通货膨胀税为政府开支融资。a. 解释谁支付这种税以及如何支付。b. 与通货膨胀税相关的成本是什么？","options":null},"topics":["seigniorage-hyper"],"answer_ref":"a. 由持有货币的人（公众）缴纳：通胀使手中货币的实际购买力下降，相当于对实际货币余额征税，税基是实际货币持有量，税率是通胀率。b. 成本包括：鞋底成本（为减少持币而频繁往返银行）、菜单成本（频繁调价）、相对价格扭曲、税制扭曲（对名义资本收益征税）、计价单位变动带来的不便。"},{"num":80,"type":"sa","question":"If the demand for money depends positively on real income and depends inversely on the nominal interest rate, what will happen to the price level today if the central bank announces (and people believe) that it will decrease the money growth rate in the future, but it does not change the money supply today?","options":null,"answer":null,"images":null,"translation":{"question":"如果货币需求正向地取决于实际收入，负向地取决于名义利率，那么如果中央银行宣布（且人们相信）未来将降低货币增长率，但今天并不改变货币供给，今天的价格水平会发生什么变化？","options":null},"topics":["quantity-theory"],"answer_ref":"物价水平今天就会下降。央行可信地承诺未来降低货币增长→未来通胀预期下降→未来物价水平预期下降；向后归纳，今天的物价水平随之下降（今天货币供给未变，但货币需求因名义利率预期下降而增加，同样压低P）。一句话：预期影响当前行为，今天的价格已反映未来的货币政策。"},{"num":81,"type":"sa","question":"Although “inflation is always and everywhere a monetary phenomenon,” explain why: a. the start of a hyperinflation is typically related to the fiscal policy situation. b. the end of a hyperinflation is usually related to changes in fiscal policy.","options":null,"answer":null,"images":null,"translation":{"question":"尽管“通货膨胀无论何时何地都是一种货币现象”，请解释为什么：a. 恶性通货膨胀的开始通常与财政政策状况相关。b. 恶性通货膨胀的结束通常与财政政策的变化相关。","options":null},"topics":["seigniorage-hyper"],"answer_ref":"a. 恶性通胀通常源于财政困境：政府税收不足、借债无门，只能靠印钞（铸币税）弥补巨额赤字——财政赤字是货币失控的根源。b. 恶性通胀的结束也靠财政改革：通过增税、削减支出或建立独立央行等手段消除对印钞融资的依赖，货币增长才能降下去——单靠央行紧缩而不解决赤字，通胀会复燃。"},{"num":82,"type":"sa","question":"Consider two countries, Hitech and Lotech. In Hitech new arrangements for making payments, such as credit cards and ATMs, have been enthusiastically adopted by the population, thereby reducing the proportion of income that is held as real money balances. Over this period no such changes occurred in Lotech. If the rate of money growth and the growth rate of real GDP were the same in Hitech and Lotech over this period, then how would the rate of inflation differ between the two countries? Carefully explain your answer.","options":null,"answer":null,"images":null,"translation":{"question":"考虑两个国家，Hitech 和 Lotech。在 Hitech，人们热情地采用了信用卡和ATM等新的支付安排，从而降低了以实际货币余额形式持有的收入比例。在这一时期，Lotech 没有发生此类变化。如果在这一时期 Hitech 和 Lotech 的货币增长率和实际GDP增长率相同，那么两国的通货膨胀率会如何不同？请仔细解释你的答案。","options":null},"topics":["quantity-theory"],"answer_ref":"数量论：通胀率 ≈ 货币增长率 − 实际GDP增长率 + 货币流通速度变化率。两国货币增长与实际GDP增长相同，但 Hitech 的支付技术（信用卡、ATM）减少了实际货币余额持有，相当于流通速度上升——同样的货币增长支撑更高的名义支出，故 Hitech 的通胀率低于 Lotech。"},{"num":83,"type":"sa","question":"Interest rates played a part in the 1984 U.S. presidential debates. Some politicians claimed that interest rates rose over the 1981–1983 period, while others claimed rates fell. Below is a table showing interest rates and annual inflation rates from 1981 to 1983. Interest Rate Annual Year (annual %) Inflation Rate 1981 14.03% 10.3% 1982 10.69% 6.2% 1983 8.63% 3.2% Reconcile these conflicting claims.","options":null,"answer":null,"images":null,"translation":{"question":"利率在1984年美国总统辩论中起了一定作用。一些政客声称1981–1983年间利率上升了，而另一些人声称利率下降了。下面是一张显示1981年至1983年利率和年通货膨胀率的表格。利率 年度 年份（年%） 通货膨胀率 1981 14.03% 10.3% 1982 10.69% 6.2% 1983 8.63% 3.2% 请调和这些相互矛盾的说法。","options":null},"topics":["fisher-effect"],"answer_ref":"两种说法都对，只是口径不同：名义利率确实下降了（14.03%→8.63%）；但通胀率下降得更快（10.3%→3.2%），事后实际利率反而上升（约3.7%→5.4%）。一方说的是名义利率，另一方说的是实际利率。"},{"num":84,"type":"sa","question":"The costs of expected inflation cause productive resources of an economy to be expended on adjusting to changing prices. Explain how each of the following costs of expected inflation distort the allocation of productive resources: a. shoeleather costs b. menu costs","options":null,"answer":null,"images":null,"translation":{"question":"预期通货膨胀的成本使经济的生产性资源被耗费在适应价格变化上。解释以下每种预期通货膨胀的成本如何扭曲生产性资源的配置：a. 皮鞋成本 b. 菜单成本","options":null},"topics":["inflation-costs"],"answer_ref":"a. 鞋底成本：为少持现金人们更频繁地跑银行、花时间管理流动性——本可用于生产的时间和精力被耗费在金融事务上。b. 菜单成本：企业需不断更新价目表、标签、系统和广告——本可用于改进产品与服务的资源被耗费在重复调价上。两者都使生产性资源偏离了实际产出。"},{"num":85,"type":"sa","question":"Assume an economy where only burgers are traded. In a year, 100 burgers are traded at the rate of $5 per burger. Assume two scenarios: a. The economy has $100 in the form of 20 $5 bills. b. The economy has $100 in the form of 100 $1 bills. Calculate the velocity of money for both situations.","options":null,"answer":null,"images":null,"translation":{"question":"假设一个只交易汉堡的经济。一年中，100个汉堡以每个5美元的价格交易。假设两种情形：a. 经济中有100美元，形式为20张5美元钞票。b. 经济中有100美元，形式为100张1美元钞票。计算两种情形下货币的流通速度。","options":null},"topics":["quantity-theory"],"answer_ref":"交易总值 PT = 100×5 = 500美元。a. V = 500/100 = 5。b. V = 500/100 = 5。流通速度相同——它取决于名义总支出与货币量的比率，与纸币面额组合无关。"},{"num":86,"type":"sa","question":"For a country A, the GDP growth rate is 8 percent and inflation is 4 percent. If the velocity of money remains constant, what is the change in real money balances?","options":null,"answer":null,"images":null,"translation":{"question":"对于A国，GDP增长率为8%，通货膨胀率为4%。如果货币流通速度保持不变，实际货币余额的变化是多少？","options":null},"topics":["quantity-theory"],"answer_ref":"数量论（V不变）：货币增长率 = 通胀率 + 实际GDP增长率 = 4% + 8% = 12%。实际货币余额 M/P 的增长率 = 货币增长率 − 通胀率 = 12% − 4% = 8%（等于实际GDP增速）。"},{"num":87,"type":"sa","question":"Suppose a government has a tax revenue shortfall. Will hyperinflation inevitably follow unless the government cuts its fiscal expenditures?","options":null,"answer":null,"images":null,"translation":{"question":"假设一个政府出现税收收入短缺。除非政府削减其财政支出，否则恶性通货膨胀是否必然随之而来？","options":null},"topics":["seigniorage-hyper"],"answer_ref":"不一定。出现恶性通胀的必要条件是持续的巨额财政赤字只能通过增发货币（铸币税）来融资。政府还可以通过增税、削减支出、向国内外发债等非通胀方式弥补缺口。只要找到货币以外的融资来源或压缩赤字，就不会必然滑向恶性通胀。"},{"num":88,"type":"sa","question":"If there are no unexpected changes in money supply in an economy, can there still be unexpected inflation in the economy?","options":null,"answer":null,"images":null,"translation":{"question":"如果一个经济中货币供给没有意外变化，该经济中是否仍可能发生未预期到的通货膨胀？","options":null},"topics":["quantity-theory"],"answer_ref":"可以。通胀 = 货币增长 + 流通速度增长 − 实际产出增长。即使货币供给没有任何意外变化，流通速度的意外变化（支付习惯、金融创新、恐慌性持币）或实际产出的意外供给冲击（如石油危机）都会使物价出现意外的上涨。此外，货币需求函数的意外移动也会造成意外通胀。"}]},{"num":6,"title":"The Open Economy","questions":[{"num":1,"type":"mc","question":"Net exports equal GDP minus domestic spending on:","options":["all goods and services.","all goods and services plus foreign spending on domestic goods and services.","domestic goods and services.","domestic goods and services minus foreign spending on domestic goods and services."],"answer":"A","images":null,"translation":{"question":"净出口等于GDP减去用于以下方面的国内支出：","options":["所有商品和服务。","所有商品和服务加上外国对本国商品和服务的支出。","国内商品和服务。","国内商品和服务减去外国对本国商品和服务的支出。"]},"topics":["trade-nex"]},{"num":2,"type":"mc","question":"The value of net exports is also the value of:","options":["net investment.","net saving.","national saving.","the difference of national saving and domestic investment."],"answer":"D","images":null,"translation":{"question":"净出口的价值也等于：","options":["净投资。","净储蓄。","国民储蓄。","国民储蓄与国内投资之差。"]},"topics":["trade-nex"]},{"num":3,"type":"mc","question":"If net capital outflow is positive, then:","options":["imports must be positive.","exports must be negative.","the trade balance must be positive.","the trade balance must be negative."],"answer":"C","images":null,"translation":{"question":"如果净资本流出为正，那么：","options":["进口必为正。","出口必为负。","贸易余额必为正。","贸易余额必为负。"]},"topics":["trade-nex"]},{"num":4,"type":"mc","question":"Net capital outflow is equal to the amount that:","options":["foreign investors lend here.","domestic investors lend abroad.","foreign investors lend here minus the amount domestic investors lend abroad.","domestic investors lend abroad minus the amount that foreign investors lend here."],"answer":"D","images":null,"translation":{"question":"净资本流出等于以下金额：","options":["外国投资者借给本国的金额。","本国投资者借给国外的金额。","外国投资者借给本国的金额减去本国投资者借给国外的金额。","本国投资者借给国外的金额减去外国投资者借给本国的金额。"]},"topics":["trade-nex"]},{"num":5,"type":"mc","question":"If domestic saving exceeds domestic investment, then net exports are ______ and net capital outflows are ______.","options":["positive; positive","positive; negative","negative; negative","negative; positive"],"answer":"A","images":null,"translation":{"question":"如果国内储蓄超过国内投资，那么净出口为 ______，净资本流出为 ______。","options":["正；正","正；负","负；负","负；正"]},"topics":["trade-nex"]},{"num":6,"type":"mc","question":"In a small, open economy if net exports are negative, then:","options":["domestic spending is greater than output.","saving is greater than investment.","net capital outflows are positive.","imports are less than exports."],"answer":"A","images":null,"translation":{"question":"在小型开放经济中，如果净出口为负，那么：","options":["国内支出大于产出。","储蓄大于投资。","净资本流出为正。","进口小于出口。"]},"topics":["trade-nex"]},{"num":7,"type":"mc","question":"When exports exceed imports, all of the following are true except:","options":["net capital outflows are positive.","net exports are positive.","domestic investment exceeds domestic saving.","domestic output exceeds domestic spending."],"answer":"C","images":null,"translation":{"question":"当出口超过进口时，以下说法都是正确的，除了：","options":["净资本流出为正。","净出口为正。","国内投资超过国内储蓄。","国内产出超过国内支出。"]},"topics":["trade-nex"]},{"num":8,"type":"mc","question":"In a small open economy, if exports equal $20 billion, imports equal $30 billion, and domestic national saving equals $25 billion, then net capital outflow equals:","options":["–$25 billion.","–$10 billion.","$10 billion.","$25 billion."],"answer":"B","images":null,"translation":{"question":"在小型开放经济中，如果出口等于200亿美元，进口等于300亿美元，国内国民储蓄等于250亿美元，那么净资本流出等于：","options":["–250亿美元。","–100亿美元。","100亿美元。","250亿美元。"]},"topics":["trade-nex"]},{"num":9,"type":"mc","question":"In a small open economy, if exports equal $5 billion and imports equal $7 billion, then there is a trade ______ and ______ net capital outflow.","options":["deficit; negative","surplus; negative","deficit; positive","surplus; positive"],"answer":"A","images":null,"translation":{"question":"在小型开放经济中，如果出口等于50亿美元、进口等于70亿美元，那么存在贸易 ______ 和 ______ 的净资本流出。","options":["逆差；负","顺差；负","逆差；正","顺差；正"]},"topics":["trade-nex"]},{"num":10,"type":"mc","question":"In a small open economy, if domestic saving equals $50 billion and domestic investment equals $50 billion, then there is ______, and net capital outflow equals ______.","options":["a trade deficit; $100 billion","balanced trade; $0","a trade surplus; $100 billion","balanced trade; $100 billion"],"answer":"B","images":null,"translation":{"question":"在小型开放经济中，如果国内储蓄等于500亿美元、国内投资等于500亿美元，那么存在 ______，净资本流出等于 ______。","options":["贸易逆差；1000亿美元","贸易平衡；0","贸易顺差；1000亿美元","贸易平衡；1000亿美元"]},"topics":["trade-nex"]},{"num":11,"type":"mc","question":"In a small open economy, if domestic investment exceeds domestic saving, then the extra investment will be financed by:","options":["borrowing from abroad.","borrowing from domestic banks.","the domestic government.","the World Bank."],"answer":"A","images":null,"translation":{"question":"在小型开放经济中，如果国内投资超过国内储蓄，那么额外的投资将由以下方式融资：","options":["向国外借款。","向国内银行借款。","本国政府。","世界银行。"]},"topics":["trade-nex"]},{"num":12,"type":"mc","question":"In a small open economy, if domestic saving exceeds domestic investment, then the extra saving will be used to:","options":["make loans to the domestic government.","make loans to foreigners.","repay the national debt.","repay loans to the Federal Reserve."],"answer":"B","images":null,"translation":{"question":"在小型开放经济中，如果国内储蓄超过国内投资，那么额外的储蓄将用于：","options":["向本国政府提供贷款。","向外国人提供贷款。","偿还国债。","偿还对美联储的贷款。"]},"topics":["trade-nex"]},{"num":13,"type":"mc","question":"If a U.S. corporation sells a product in Europe and uses the proceeds to purchase shares in a European corporation, then U.S. net exports ______, and net capital outflows ______.","options":["increase; increase","increase; decrease","decrease; increase","decrease; decrease"],"answer":"A","images":null,"translation":{"question":"如果一家美国公司在欧洲出售产品，并用所得款项购买一家欧洲公司的股票，那么美国净出口 ______，净资本流出 ______。","options":["增加；增加","增加；减少","减少；增加","减少；减少"]},"topics":["trade-nex"]},{"num":14,"type":"mc","question":"If a U.S. corporation purchases a product made in Europe and the European producer uses the proceeds to purchase a U.S. government bond, then U.S. net exports ______, and net capital outflows ______.","options":["increase; increase","increase; decrease","decrease; increase","decrease; decrease"],"answer":"D","images":null,"translation":{"question":"如果一家美国公司购买欧洲制造的产品，而欧洲生产者用所得款项购买美国政府债券，那么美国净出口 ______，净资本流出 ______。","options":["增加；增加","增加；减少","减少；增加","减少；减少"]},"topics":["trade-nex"]},{"num":15,"type":"mc","question":"If a U.S. corporation sells a product to Canada and uses the proceeds to purchase a product manufactured in Canada, then U.S. net exports ______, and net capital outflows ______.","options":["increase; increase","decrease; decrease","do not change; do not change","do not change; increase"],"answer":"C","images":null,"translation":{"question":"如果一家美国公司向加拿大出售产品，并用所得款项购买加拿大制造的产品，那么美国净出口 ______，净资本流出 ______。","options":["增加；增加","减少；减少","不变；不变","不变；增加"]},"topics":["trade-nex"]},{"num":16,"type":"mc","question":"A “closed” economy is one in which the:","options":["level of output is fixed.","price level is fixed.","domestic interest rate equals the world interest rate.","domestic saving is less than domestic investment."],"answer":"C","images":null,"translation":{"question":"“封闭”经济是指以下哪项成立的经济：","options":["产出水平固定。","物价水平固定。","国内利率等于世界利率。","国内储蓄小于国内投资。"]},"topics":["trade-nex"]},{"num":17,"type":"mc","question":"The world interest rate:","options":["is equal to the domestic interest rate.","makes domestic saving equal to domestic investment.","is the interest rate charged on loans by the World Bank.","is the interest rate prevailing in world financial markets."],"answer":"D","images":null,"translation":{"question":"世界利率：","options":["等于国内利率。","使国内储蓄等于国内投资。","是世界银行贷款收取的利率。","是世界金融市场上通行的利率。"]},"topics":["trade-nex"]},{"num":18,"type":"mc","question":"A small open economy with perfect capital mobility is characterized by all of the following except that:","options":["its domestic interest rate always exceeds the world interest rate.","it engages in international trade.","its net capital outflows always equal the trade balance.","its government does not impede international borrowing or lending."],"answer":"A","images":null,"translation":{"question":"具有完全资本流动性的小型开放经济具有以下所有特征，除了：","options":["其国内利率总是高于世界利率。","它从事国际贸易。","其净资本流出总是等于贸易余额。","其政府不阻碍国际借贷。"]},"topics":["trade-nex"]},{"num":19,"type":"mc","question":"In a small open economy, if the world real interest rate is above the rate at which national saving equals domestic investment, then there will be a trade ______ and ______ net capital outflow.","options":["surplus; negative","deficit; positive","surplus; positive","deficit; negative"],"answer":"C","images":null,"translation":{"question":"在小型开放经济中，如果世界实际利率高于国民储蓄等于国内投资时的利率，那么将出现贸易 ______ 和 ______ 净资本流出。","options":["顺差；负","逆差；正","顺差；正","逆差；负"]},"topics":["trade-nex"]},{"num":20,"type":"mc","question":"[[IMG:c6_img0.png]] In a small open economy, if the world interest rate is r1, then the economy has:","options":["a trade surplus.","balanced trade.","a trade deficit.","negative capital outflows."],"answer":"A","images":null,"translation":{"question":"[[IMG:c6_img0.png]] 在小型开放经济中，如果世界利率为 r1，那么该经济存在：","options":["贸易顺差。","贸易平衡。","贸易逆差。","负的资本流出。"]},"topics":["trade-nex"]},{"num":21,"type":"mc","question":"[[IMG:c6_img1.png]] In a small open economy, if the world interest rate is r3, then the economy has:","options":["a trade surplus.","balanced trade.","a trade deficit.","positive capital outflows."],"answer":"C","images":null,"translation":{"question":"[[IMG:c6_img1.png]] 在小型开放经济中，如果世界利率为 r3，那么该经济存在：","options":["贸易顺差。","贸易平衡。","贸易逆差。","正的资本流出。"]},"topics":["trade-nex"]},{"num":22,"type":"mc","question":"In a small open economy, starting from a position of balanced trade, if the government increases domestic government purchases, this produces a tendency toward a trade ______ and ______ net capital outflow.","options":["deficit; negative","surplus; positive","deficit; positive","surplus; negative"],"answer":"A","images":null,"translation":{"question":"在小型开放经济中，从贸易平衡的状态出发，如果政府增加国内政府购买，这会产生贸易 ______ 和 ______ 净资本流出的趋势。","options":["逆差；负","顺差；正","逆差；正","顺差；负"]},"topics":["trade-nex"]},{"num":23,"type":"mc","question":"In a small open economy, starting from a position of balanced trade, if the government increases the income tax, this produces a tendency toward a trade ______ and ______ net capital outflow.","options":["deficit; negative","surplus; positive","deficit; positive","surplus; negative"],"answer":"B","images":null,"translation":{"question":"在小型开放经济中，从贸易平衡的状态出发，如果政府提高所得税，这会产生贸易 ______ 和 ______ 净资本流出的趋势。","options":["逆差；负","顺差；正","逆差；正","顺差；负"]},"topics":["trade-nex"]},{"num":24,"type":"mc","question":"Holding other factors constant, legislation to cut taxes in an open economy will:","options":["increase national saving and lead to a trade surplus.","increase national saving and lead to a trade deficit.","reduce national saving and lead to a trade surplus.","reduce national saving and lead to a trade deficit."],"answer":"D","images":null,"translation":{"question":"在其他因素不变的情况下，开放经济中减税的立法将：","options":["增加国民储蓄并导致贸易顺差。","增加国民储蓄并导致贸易逆差。","减少国民储蓄并导致贸易顺差。","减少国民储蓄并导致贸易逆差。"]},"topics":["trade-nex"]},{"num":25,"type":"mc","question":"Starting from a small open economy with balanced trade, if large foreign countries increase their domestic government purchases, this policy will tend to increase:","options":["investment in the small open economy.","saving in the small open economy.","exports by the small open economy.","imports by the small open economy."],"answer":"C","images":null,"translation":{"question":"从贸易平衡的小型开放经济出发，如果大型外国增加其国内政府购买，这一政策往往会增加：","options":["小型开放经济的投资。","小型开放经济的储蓄。","小型开放经济的出口。","小型开放经济的进口。"]},"topics":["trade-nex"]},{"num":26,"type":"mc","question":"Starting from a trade balance, if the world interest rate falls, then, holding other factors constant, in a small open economy the amount of domestic investment will _____, and net exports will _____.","options":["increase; increase","increase; decrease","increase; not change","decrease; increase"],"answer":"B","images":null,"translation":{"question":"从贸易平衡出发，如果世界利率下降，那么在其他因素不变的情况下，小型开放经济中国内投资量将 _____，净出口将 _____。","options":["增加；增加","增加；减少","增加；不变","减少；增加"]},"topics":["trade-nex"]},{"num":27,"type":"mc","question":"If the government of a small open economy wishes to reduce a trade deficit, which policy action will be successful in achieving this goal?","options":["increasing taxes","increasing government spending","increasing investment tax credits","imposing protectionist trade policies"],"answer":"A","images":null,"translation":{"question":"如果小型开放经济的政府希望减少贸易逆差，哪项政策措施能够成功实现这一目标？","options":["增税","增加政府支出","增加投资税收抵免","实施保护主义贸易政策"]},"topics":["trade-nex"]},{"num":28,"type":"mc","question":"The adoption of an investment tax credit in a small open economy is likely to lead to:","options":["no change in either domestic investment or domestic saving.","an increase in both domestic investment and domestic saving.","an increase in domestic saving but no change in domestic investment.","an increase in domestic investment but no change in domestic saving."],"answer":"D","images":null,"translation":{"question":"小型开放经济中采用投资税收抵免可能导致：","options":["国内投资和国内储蓄都不变。","国内投资和国内储蓄都增加。","国内储蓄增加但国内投资不变。","国内投资增加但国内储蓄不变。"]},"topics":["trade-nex"]},{"num":29,"type":"mc","question":"In a small open economy, policies that increase:","options":["investment tend to cause a trade surplus.","investment tend to cause a trade deficit.","saving do not affect the trade balance.","saving tend to cause a trade deficit."],"answer":"B","images":null,"translation":{"question":"在小型开放经济中，以下关于政策的陈述哪项正确？","options":["增加投资往往导致贸易顺差。","增加投资往往导致贸易逆差。","增加储蓄不影响贸易余额。","增加储蓄往往导致贸易逆差。"]},"topics":["trade-nex"]},{"num":30,"type":"mc","question":"Based on a Cobb–Douglas production function and perfect capital mobility, capital should flow to economies in which:","options":["capital is relatively scarce.","capital is relatively abundant.","technological production capabilities are inferior.","labor is relatively scarce."],"answer":"A","images":null,"translation":{"question":"基于柯布—道格拉斯生产函数和完全资本流动性，资本应流向以下哪种经济：","options":["资本相对稀缺的经济。","资本相对充裕的经济。","技术生产能力较差的经济。","劳动相对稀缺的经济。"]},"topics":["trade-nex"]},{"num":31,"type":"mc","question":"The nominal exchange rate between the U.S. dollar and the Japanese yen (measured in $ / yen) is the:","options":["number of yen you can get for lending one dollar in Japan for one year.","number of yen you can get for one dollar.","price of U.S. goods divided by the price of Japanese goods.","price of Japanese goods divided by the price of U.S. goods."],"answer":"B","images":null,"translation":{"question":"美元与日元之间的名义汇率（以美元/日元衡量）是：","options":["在日本贷出1美元一年所能获得的日元数量。","1美元所能兑换的日元数量。","美国商品价格除以日本商品价格。","日本商品价格除以美国商品价格。"]},"topics":["exchange-rate"]},{"num":32,"type":"mc","question":"The real exchange rate:","options":["measures how many Japanese yen you can get for one U.S. dollar.","is equal to the nominal exchange rate (measured in units of the foreign currency divided by units of home currency) multiplied by the domestic price level divided by the foreign price level.","is equal to the nominal exchange rate (measured in units of the foreign currency divided by units of home currency) multiplied by the foreign price level divided by the domestic price level.","is the price of a domestic car divided by the price of a foreign car."],"answer":"B","images":null,"translation":{"question":"实际汇率：","options":["衡量1美元能兑换多少日元。","等于名义汇率（以外币单位除以本币单位衡量）乘以国内物价水平除以外国物价水平。","等于名义汇率（以外币单位除以本币单位衡量）乘以外国物价水平除以国内物价水平。","是国内汽车价格除以国外汽车价格。"]},"topics":["exchange-rate"]},{"num":33,"type":"mc","question":"If the number of dollars per yen rises, this is called a(n):","options":["appreciation of the dollar.","appreciation of the yen.","increase in the terms of trade.","decrease in the terms of trade."],"answer":"B","images":null,"translation":{"question":"如果每日元兑换的美元数量上升，这被称为：","options":["美元升值。","日元升值。","贸易条件改善。","贸易条件恶化。"]},"topics":["exchange-rate"]},{"num":34,"type":"mc","question":"If 5 Swiss francs trade for $1, the U.S. price level equals $1 for a good, and the Swiss price level equals 2 francs for the same good, then the real exchange rate between Swiss goods and U.S. goods is ______ Swiss good(s) per U.S. good.","options":["0.4","2.5","5","10"],"answer":"B","images":null,"translation":{"question":"如果5瑞士法郎兑换1美元，美国物价水平为每件商品1美元，瑞士物价水平为同样的商品2法郎，那么瑞士商品与美国商品之间的实际汇率为每件美国商品对应 ______ 件瑞士商品。","options":["0.4","2.5","5","10"]},"topics":["exchange-rate"]},{"num":35,"type":"mc","question":"When the real exchange rate rises:","options":["exports will decrease but imports will be unaffected.","imports will decrease but exports will be unaffected.","exports will increase and imports will decrease.","exports will decrease and imports will increase."],"answer":"D","images":null,"translation":{"question":"当实际汇率上升时：","options":["出口将减少但进口不受影响。","进口将减少但出口不受影响。","出口将增加、进口将减少。","出口将减少、进口将增加。"]},"topics":["exchange-rate"]},{"num":36,"type":"mc","question":"If the real exchange rate depreciates from 1 Japanese good per U.S. good to 0.5 Japanese good per U.S. good, then U.S. exports ______, and U.S. imports ______.","options":["increase; increase","decrease; decrease","increase; decrease","decrease; increase"],"answer":"C","images":null,"translation":{"question":"如果实际汇率从每件美国商品对应1件日本商品贬值到每件美国商品对应0.5件日本商品，那么美国出口 ______，美国进口 ______。","options":["增加；增加","减少；减少","增加；减少","减少；增加"]},"topics":["exchange-rate"]},{"num":37,"type":"mc","question":"The lower the real exchange rate is, the ______ expensive domestic goods are relative to foreign goods, and the ______ the demand is for net exports.","options":["more; greater","more; smaller","less; greater","less; smaller"],"answer":"C","images":null,"translation":{"question":"实际汇率越低，国内商品相对外国商品越 ______，对净出口的需求越 ______。","options":["昂贵；大","昂贵；小","便宜；大","便宜；小"]},"topics":["exchange-rate"]},{"num":38,"type":"mc","question":"In a small open economy in equilibrium:","options":["saving is fixed, and investment is determined by the investment function and the world interest rate.","investment is fixed, and saving is determined by the saving function and the world interest rate.","saving is fixed, and investment is determined by the trade balance.","investment is fixed, and saving is determined by the trade balance."],"answer":"A","images":null,"translation":{"question":"在均衡状态下的小型开放经济中：","options":["储蓄是固定的，投资由投资函数和世界利率决定。","投资是固定的，储蓄由储蓄函数和世界利率决定。","储蓄是固定的，投资由贸易余额决定。","投资是固定的，储蓄由贸易余额决定。"]},"topics":["exchange-rate"]},{"num":39,"type":"mc","question":"If a graph is drawn with net exports on the horizontal axis and the real exchange rate on the vertical axis, then the real exchange rate is determined by the intersection of the ______ net-exports schedule and the ______ line representing saving minus investment.","options":["downward-sloping; vertical","upward-sloping; vertical","downward-sloping; upward-sloping","upward-sloping; downward-sloping"],"answer":"A","images":null,"translation":{"question":"如果以净出口为横轴、实际汇率为纵轴作图，那么实际汇率由 ______ 的净出口曲线与代表储蓄减去投资的 ______ 线的交点决定。","options":["向下倾斜；垂直","向上倾斜；垂直","向下倾斜；向上倾斜","向上倾斜；向下倾斜"]},"topics":["exchange-rate"]},{"num":40,"type":"mc","question":"The real exchange rate is determined by the equality of:","options":["saving and the demand for net exports.","investment and the demand for net exports.","net capital outflow and the demand for net exports.","the negative value of net capital outflow and the demand for net exports."],"answer":"C","images":null,"translation":{"question":"实际汇率由以下两者的相等决定：","options":["储蓄与对净出口的需求。","投资与对净出口的需求。","净资本流出与对净出口的需求。","净资本流出的负值与对净出口的需求。"]},"topics":["exchange-rate"]},{"num":41,"type":"mc","question":"In a small open economy with perfect capital mobility, a reduction in the government's budget deficit ______ net exports, and the real exchange rate ______.","options":["increases; appreciates","increases; depreciates","decreases; appreciates","decreases; depreciates"],"answer":"B","images":null,"translation":{"question":"在具有完全资本流动性的小型开放经济中，政府预算赤字的减少 ______ 净出口，实际汇率 ______。","options":["增加；升值","增加；贬值","减少；升值","减少；贬值"]},"topics":["exchange-rate"]},{"num":42,"type":"mc","question":"In a small open economy, when foreign governments reduce national saving in their countries, the equilibrium real exchange rate (measured in units of the home currency divided by units of foreign currency):","options":["rises, and home country net exports fall.","rises, and home country net exports rise.","falls, and home country net exports fall.","falls, and home country net exports rise."],"answer":"D","images":null,"translation":{"question":"在小型开放经济中，当外国政府减少其国内的国民储蓄时，均衡实际汇率（以本币单位除以外币单位衡量）：","options":["上升，本国净出口下降。","上升，本国净出口上升。","下降，本国净出口下降。","下降，本国净出口上升。"]},"topics":["exchange-rate"]},{"num":43,"type":"mc","question":"In a small open economy, if the world interest rate falls, then domestic investment will _____, and the real exchange rate will _____, holding all else constant.","options":["decrease; decrease","decrease; increase","increase; decrease","increase; increase"],"answer":"D","images":null,"translation":{"question":"在小型开放经济中，如果世界利率下降，那么在其他条件不变的情况下，国内投资将 _____，实际汇率将 _____。","options":["减少；下降","减少；上升","增加；下降","增加；上升"]},"topics":["exchange-rate"]},{"num":44,"type":"mc","question":"If the information technology boom increases investment demand in a small open economy, then net exports ______, and the real exchange rate ______.","options":["increase; appreciates","increase; depreciates","decrease; appreciates","decrease; depreciates"],"answer":"C","images":null,"translation":{"question":"如果信息技术繁荣增加了小型开放经济的投资需求，那么净出口 ______，实际汇率 ______。","options":["增加；升值","增加；贬值","减少；升值","减少；贬值"]},"topics":["exchange-rate"]},{"num":45,"type":"mc","question":"An appreciation of the real exchange rate in a small open economy could be the result of:","options":["an increase in government spending.","an increase in taxes.","a decrease in the world interest rate.","the expiration of an investment tax-credit provision."],"answer":"A","images":null,"translation":{"question":"小型开放经济中实际汇率升值可能是以下哪项的结果：","options":["政府支出增加。","税收增加。","世界利率下降。","投资税收抵免条款到期。"]},"topics":["exchange-rate"]},{"num":46,"type":"mc","question":"A depreciation of the real exchange rate in a small open economy could be the result of:","options":["a domestic tax cut.","an increase in government spending.","a decrease in the world interest rate.","the expiration of an investment tax-credit provision."],"answer":"D","images":null,"translation":{"question":"小型开放经济中实际汇率贬值可能是以下哪项的结果：","options":["国内减税。","政府支出增加。","世界利率下降。","投资税收抵免条款到期。"]},"topics":["exchange-rate"]},{"num":47,"type":"mc","question":"In a small open economy, if the government adopts a policy that lowers imports, then that policy:","options":["raises the real exchange rate and increases net exports.","raises the real exchange rate and does not change net exports.","raises the real exchange rate and decreases net exports.","lowers the real exchange rate."],"answer":"B","images":null,"translation":{"question":"在小型开放经济中，如果政府采取降低进口的政策，那么该政策：","options":["提高实际汇率并增加净出口。","提高实际汇率且不改变净出口。","提高实际汇率并减少净出口。","降低实际汇率。"]},"topics":["exchange-rate"]},{"num":48,"type":"mc","question":"An effective policy to reduce a trade deficit in a small open economy would be to:","options":["increase tariffs on imports.","impose stricter quotas on imported goods.","increase government spending.","increase taxes."],"answer":"D","images":null,"translation":{"question":"在小型开放经济中，减少贸易逆差的有效政策是：","options":["提高进口关税。","对进口商品实行更严格的配额。","增加政府支出。","增税。"]},"topics":["exchange-rate"]},{"num":49,"type":"mc","question":"Protectionist policies implemented in a small open economy with a trade deficit have the effect of ______ the trade deficit and ______ the quantity of imports and exports.","options":["decreasing; decreasing","not changing; decreasing","decreasing; not changing","not changing; not changing"],"answer":"B","images":null,"translation":{"question":"在存在贸易逆差的小型开放经济中实施保护主义政策，会 ______ 贸易逆差，并 ______ 进出口的数量。","options":["减少；减少","不改变；减少","减少；不改变","不改变；不改变"]},"topics":["exchange-rate"]},{"num":50,"type":"mc","question":"Which of the following would decrease the real exchange rate in a small open economy?","options":["a personal income tax cut","a reduction in government spending","a tariff on imports","an increase in investment"],"answer":"B","images":null,"translation":{"question":"以下哪项会降低小型开放经济的实际汇率？","options":["个人所得税减税","政府支出减少","对进口征收关税","投资增加"]},"topics":["exchange-rate"]},{"num":51,"type":"mc","question":"Exhibit: Policies Influence Real Exchange Rate Which of the panels illustrates the impact of contractionary fiscal policies at home on the real exchange rate?","options":["(A)","(B)","(C)","(D)"],"answer":"A","images":null,"translation":{"question":"图表：政策影响实际汇率 哪个图版说明了本国紧缩性财政政策对实际汇率的影响？","options":["(A)","(B)","(C)","(D)"]},"topics":["exchange-rate"]},{"num":52,"type":"mc","question":"Exhibit: Policies Influence Real Exchange Rate Which of the panels illustrates the impact of contractionary fiscal policies abroad on the real exchange rate?","options":["(A)","(B)","(C)","(D)"],"answer":"B","images":["c6_img2.png"],"translation":{"question":"图表：政策影响实际汇率 哪个图版说明了外国紧缩性财政政策对实际汇率的影响？","options":["(A)","(B)","(C)","(D)"]},"topics":["exchange-rate"]},{"num":53,"type":"mc","question":"Exhibit: Policies Influence Real Exchange Rate Which of the panels illustrates the impact of an increase in investment demand on the real exchange rate?","options":["(A)","(B)","(C)","(D)"],"answer":"C","images":["c6_img3.png"],"translation":{"question":"图表：政策影响实际汇率 哪个图版说明了投资需求增加对实际汇率的影响？","options":["(A)","(B)","(C)","(D)"]},"topics":["exchange-rate"]},{"num":54,"type":"mc","question":"Exhibit: Policies Influence Real Exchange Rate Which of the panels illustrates the impact on of protectionist trade policies on the real exchange rate?","options":["(A)","(B)","(C)","(D)"],"answer":"D","images":["c6_img4.png"],"translation":{"question":"图表：政策影响实际汇率 哪个图版说明了保护主义贸易政策对实际汇率的影响？","options":["(A)","(B)","(C)","(D)"]},"topics":["exchange-rate"]},{"num":55,"type":"mc","question":"Exhibit: Policies Influence Real Exchange Rate Which of the panels illustrates the impact of an increase in household saving on the real exchange rate?","options":["(A)","(B)","(C)","(D)"],"answer":"A","images":["c6_img5.png"],"translation":{"question":"图表：政策影响实际汇率 哪个图版说明了家庭储蓄增加对实际汇率的影响？","options":["(A)","(B)","(C)","(D)"]},"topics":["exchange-rate"]},{"num":56,"type":"mc","question":"The percentage change in the nominal exchange rate equals the percentage change in the real exchange rate plus the:","options":["foreign inflation rate minus the domestic inflation rate.","domestic inflation rate minus the foreign inflation rate.","foreign exchange rate minus the domestic exchange rate.","domestic interest rate minus the foreign interest rate."],"answer":"A","images":["c6_img6.png"],"translation":{"question":"名义汇率的百分比变化等于实际汇率的百分比变化加上：","options":["外国通胀率减去国内通胀率。","国内通胀率减去外国通胀率。","外国汇率减去国内汇率。","国内利率减去外国利率。"]},"topics":["exchange-rate"]},{"num":57,"type":"mc","question":"If a country has a high rate of inflation relative to the United States (holding the real exchange rate fixed), the dollar will buy:","options":["less of the foreign currency over time.","more of the foreign currency over time.","the same amount of the foreign currency over time.","an amount of foreign currency determined by the real exchange rate."],"answer":"B","images":null,"translation":{"question":"如果一国通胀率高于美国（实际汇率保持不变），美元将能够兑换：","options":["随时间推移越来越少的外国货币。","随时间推移越来越多的外国货币。","随时间推移数量不变的外国货币。","由实际汇率决定的外国货币数量。"]},"topics":["exchange-rate"]},{"num":58,"type":"mc","question":"If the real exchange rate between the United States and Japan remains unchanged, and the inflation rate in the United States is 6 percent and the inflation rate in Japan is 3 percent, the:","options":["dollar will appreciate by 3 percent against the yen.","yen will appreciate by 3 percent against the dollar.","yen will appreciate by 6 percent against the dollar.","yen will appreciate by 9 percent against the dollar."],"answer":"B","images":null,"translation":{"question":"如果美国与日本之间的实际汇率保持不变，美国通胀率为6%，日本通胀率为3%，那么：","options":["美元将对日元升值3%。","日元将对美元升值3%。","日元将对美元升值6%。","日元将对美元升值9%。"]},"topics":["exchange-rate"]},{"num":59,"type":"mc","question":"The U.S. dollar exchange rate (units of foreign currency per U.S. dollar) for currencies of countries with high inflation rates relative to the United States has tended to ______, and the U.S. dollar exchange rate (units of foreign currency per U.S. dollar) for currencies of countries with low inflation rates relative to the United States has tended to ______.","options":["appreciate; appreciate","appreciate; depreciate","depreciate; depreciate","depreciate; appreciate"],"answer":"D","images":null,"translation":{"question":"对于通胀率高于美国的国家的货币，美元汇率（每美元兑换的外币单位）往往 ______；对于通胀率低于美国的国家的货币，美元汇率（每美元兑换的外币单位）往往 ______。","options":["升值；升值","升值；贬值","贬值；贬值","贬值；升值"]},"topics":["exchange-rate"]},{"num":60,"type":"mc","question":"If the purchasing-power parity theory is true, then:","options":["the net exports schedule is very steep.","all changes in the real exchange rate result from changes in price levels.","all changes in the nominal exchange rate result from changes in price levels.","changes in saving or investment influence only the real exchange rate."],"answer":"C","images":null,"translation":{"question":"如果购买力平价理论成立，那么：","options":["净出口曲线非常陡峭。","实际汇率的所有变化都源于物价水平的变化。","名义汇率的所有变化都源于物价水平的变化。","储蓄或投资的变化只影响实际汇率。"]},"topics":["ppp"]},{"num":61,"type":"mc","question":"If purchasing-power parity holds, then changes in domestic saving will _____ the real exchange rate.","options":["increase","decrease","not change","either increase or decrease"],"answer":"C","images":null,"translation":{"question":"如果购买力平价成立，那么国内储蓄的变化将 _____ 实际汇率。","options":["提高","降低","不改变","提高或降低"]},"topics":["ppp"]},{"num":62,"type":"mc","question":"According to purchasing-power parity, if the dollar price of oil is higher in New York than in London, arbitrageurs will _____ oil in New York and _____ oil in London to drive _____ the price of oil in New York.","options":["buy; sell; up","buy; sell; down","sell; buy; up","sell; buy; down"],"answer":"D","images":null,"translation":{"question":"根据购买力平价，如果纽约的石油美元价格高于伦敦，套利者将在纽约 ______ 石油、在伦敦 ______ 石油，从而 ______ 纽约的石油价格。","options":["买入；卖出；推高","买入；卖出；压低","卖出；买入；推高","卖出；买入；压低"]},"topics":["ppp"]},{"num":63,"type":"mc","question":"Purchasing-power parity theory:","options":["is a completely accurate description of the real world.","would be entirely accurate if only goods were traded.","would be entirely accurate if all consumers had the same preferences.","provides a reason to expect that movements in the real exchange rate will typically be small or temporary."],"answer":"D","images":null,"translation":{"question":"购买力平价理论：","options":["是对现实世界的完全准确的描述。","如果只有商品被交易，将是完全准确的。","如果所有消费者偏好相同，将是完全准确的。","提供了一个理由，使我们预期实际汇率的变动通常会是微小的或暂时的。"]},"topics":["ppp"]},{"num":64,"type":"mc","question":"Net capital outflow in a large country:","options":["rises as the real domestic interest rate rises.","declines as the domestic interest rate rises.","depends on the foreign interest rate.","depends only on domestic saving."],"answer":"B","images":null,"translation":{"question":"大国的净资本流出：","options":["随国内实际利率上升而上升。","随国内利率上升而下降。","取决于外国利率。","只取决于国内储蓄。"]},"topics":["trade-nex"]},{"num":65,"type":"mc","question":"For a closed economy, when net capital outflow is measured along the horizontal axis and the real interest rate is measured along the vertical axis, net capital outflow is drawn as a:","options":["vertical line at 0.","horizontal line at the world real interest rate.","line that slopes up and to the right.","line that slopes down and to the right."],"answer":"A","images":null,"translation":{"question":"对于封闭经济，当以净资本流出为横轴、实际利率为纵轴时，净资本流出绘制为：","options":["在0处的垂直线。","在世界实际利率处的水平线。","向右上方倾斜的线。","向右下方倾斜的线。"]},"topics":["trade-nex"]},{"num":66,"type":"mc","question":"For an open economy with perfect capital mobility, when net capital outflow is measured along the horizontal axis and the real interest rate is measured along the vertical axis, net capital outflow is drawn as a:","options":["vertical line at 0.","horizontal line at the world real interest rate.","line that slopes up and to the right.","line that slopes down and to the right."],"answer":"B","images":null,"translation":{"question":"对于具有完全资本流动性的开放经济，当以净资本流出为横轴、实际利率为纵轴时，净资本流出绘制为：","options":["在0处的垂直线。","在世界实际利率处的水平线。","向右上方倾斜的线。","向右下方倾斜的线。"]},"topics":["trade-nex"]},{"num":67,"type":"mc","question":"In a large open economy, the real interest rate is determined by:","options":["national saving, the domestic investment function, and the net capital outflow function.","national saving, the domestic investment function, and the net exports function.","the domestic investment function, the net capital outflow function, and the net exports function.","national saving, the domestic investment function, the net capital outflow function, and the net exports function."],"answer":"A","images":null,"translation":{"question":"在大国开放经济中，实际利率由以下哪些因素决定：","options":["国民储蓄、国内投资函数和净资本流出函数。","国民储蓄、国内投资函数和净出口函数。","国内投资函数、净资本流出函数和净出口函数。","国民储蓄、国内投资函数、净资本流出函数和净出口函数。"]},"topics":["trade-nex"]},{"num":68,"type":"mc","question":"In a large open economy, the interest rate adjusts so that domestic saving equals:","options":["domestic investment.","net exports.","net capital outflow.","domestic investment plus net capital outflow."],"answer":"D","images":null,"translation":{"question":"在大国开放经济中，利率调整使国内储蓄等于：","options":["国内投资。","净出口。","净资本流出。","国内投资加净资本流出。"]},"topics":["trade-nex"]},{"num":69,"type":"mc","question":"In a large open economy, the exchange rate adjusts so that net exports equal:","options":["domestic saving.","domestic investment.","net capital outflow.","domestic investment plus net capital outflow."],"answer":"C","images":null,"translation":{"question":"在大国开放经济中，汇率调整使净出口等于：","options":["国内储蓄。","国内投资。","净资本流出。","国内投资加净资本流出。"]},"topics":["exchange-rate"]},{"num":70,"type":"mc","question":"Expansionary fiscal policy in a large open economy ______ the real interest rate and ______ the real exchange rate.","options":["does not change; increases","increases; increases","increases; decreases","decreases; increases"],"answer":"B","images":null,"translation":{"question":"大国开放经济中的扩张性财政政策 ______ 实际利率并 ______ 实际汇率。","options":["不改变；提高","提高；提高","提高；降低","降低；提高"]},"topics":["trade-nex","exchange-rate"]},{"num":71,"type":"mc","question":"In a large open economy, an investment tax credit raises the real interest rate, ______ the trade balance, and ______ net capital outflow.","options":["decreases; decreases","increases; increases","decreases; increases","increases; decreases"],"answer":"A","images":null,"translation":{"question":"在大国开放经济中，投资税收抵免提高实际利率，______ 贸易余额，并 ______ 净资本流出。","options":["减少；减少","增加；增加","减少；增加","增加；减少"]},"topics":["trade-nex"]},{"num":72,"type":"mc","question":"In a large open economy, if an import quota is adopted, then:","options":["net exports remain unchanged, as imports and exports decrease by equal amounts, while the real exchange rate rises.","net exports remain unchanged, as imports and exports decrease by equal amounts, while the real exchange rate falls.","net exports rise and the real exchange rate rises.","net exports rise and the real exchange rate falls."],"answer":"A","images":null,"translation":{"question":"在大国开放经济中，如果实行进口配额，那么：","options":["净出口保持不变，因为进口和出口以相等的数量减少，而实际汇率上升。","净出口保持不变，因为进口和出口以相等的数量减少，而实际汇率下降。","净出口上升、实际汇率上升。","净出口上升、实际汇率下降。"]},"topics":["exchange-rate"]},{"num":73,"type":"mc","question":"In a large open economy, if political instability abroad lowers the net capital outflow function, then the real interest rate:","options":["rises, while the real exchange rate rises and net exports fall.","rises, while the real exchange rate falls and net exports rise.","falls, while the real exchange rate rises and net exports rise.","falls, while the real exchange rate rises and net exports fall."],"answer":"D","images":null,"translation":{"question":"在大国开放经济中，如果国外的政治不稳定使净资本流出函数下移，那么实际利率：","options":["上升，而实际汇率上升、净出口下降。","上升，而实际汇率下降、净出口上升。","下降，而实际汇率上升、净出口上升。","下降，而实际汇率上升、净出口下降。"]},"topics":["trade-nex"]},{"num":74,"type":"mc","question":"In a small open economy, if consumer confidence falls and consumers decide to save more, then the real exchange rate:","options":["rises, and net exports fall.","and net exports both rise.","falls, and net exports rise.","and net exports both fall."],"answer":"C","images":null,"translation":{"question":"在小型开放经济中，如果消费者信心下降、消费者决定增加储蓄，那么实际汇率：","options":["上升，净出口下降。","与净出口都上升。","下降，净出口上升。","与净出口都下降。"]},"topics":["exchange-rate"]},{"num":75,"type":"mc","question":"In a small open economy, if consumers shift their preference toward Japanese cars, then net exports:","options":["fall, and the real exchange rate falls.","fall, but the real exchange rate remains unchanged.","remain unchanged, but the real exchange rate falls.","increase, and the real exchange rate remains unchanged."],"answer":"C","images":null,"translation":{"question":"在小型开放经济中，如果消费者偏好转向日本汽车，那么净出口：","options":["下降，实际汇率下降。","下降，但实际汇率保持不变。","保持不变，但实际汇率下降。","增加，实际汇率保持不变。"]},"topics":["exchange-rate"]},{"num":76,"type":"mc","question":"In a small open economy, if the introduction of automatic teller machines reduces the demand for money, then net exports:","options":["fall, and the real exchange rate falls.","fall, but the real exchange rate remains unchanged.","remain unchanged, but the real exchange rate falls.","increase, and the real exchange rate remains unchanged."],"answer":"D","images":null,"translation":{"question":"在小型开放经济中，如果自动柜员机的引入降低了货币需求，那么净出口：","options":["下降，实际汇率下降。","下降，但实际汇率保持不变。","保持不变，但实际汇率下降。","增加，实际汇率保持不变。"]},"topics":["exchange-rate"]},{"num":77,"type":"mc","question":"Assume that some large foreign countries decide to subsidize investment by instituting an investment tax credit. Then a small country's real exchange rate:","options":["will fall, and its net exports will rise.","will rise, and its net exports will fall.","and net exports will both fall.","and net exports will both rise."],"answer":"A","images":null,"translation":{"question":"假设一些大型外国决定通过设立投资税收抵免来补贴投资。那么小国的实际汇率：","options":["将下降，其净出口将上升。","将上升，其净出口将下降。","与净出口都将下降。","与净出口都将上升。"]},"topics":["exchange-rate"]},{"num":78,"type":"mc","question":"If the nominal interest rates in the United States and Canada are 8 percent and 12 percent, respectively, the real interest rates are the same, and the real exchange rate is fixed, then the market's expectation about the number of Canadian dollars to be received for a U.S. dollar a year from now will be that it will:","options":["decrease by 8 percent.","decrease by 4 percent.","increase by 4 percent.","increase by 5 percent."],"answer":"C","images":null,"translation":{"question":"如果美国和加拿大的名义利率分别为8%和12%，实际利率相同，实际汇率固定，那么市场预期一年后1美元所能兑换的加元数量将：","options":["减少8%。","减少4%。","增加4%。","增加5%。"]},"topics":["exchange-rate"]},{"num":79,"type":"mc","question":"Assume that a war breaks out abroad, and foreign investors choose to invest more in a large safe country, the United States. Then, the U.S. real interest rate:","options":["and net exports will both fall.","will fall, and net exports will rise.","will rise, and net exports will fall.","and net exports will both rise."],"answer":"A","images":null,"translation":{"question":"假设国外爆发战争，外国投资者选择更多投资于一个大型安全国家——美国。那么，美国实际利率：","options":["与净出口都将下降。","将下降，净出口将上升。","将上升，净出口将下降。","与净出口都将上升。"]},"topics":["trade-nex"]},{"num":80,"type":"sa","question":"Assume that in a small open economy with full employment, national saving is 300. a. If domestic investment is given by I = 400 – 20r, where r is the real interest rate in percent, what would the equilibrium interest rate be if the economy were closed? b. If the economy is open and the world interest rate is 10 percent, what will investment be? c. What will the current account surplus or deficit be? What will net capital outflow be?","options":null,"answer":null,"images":null,"translation":{"question":"假设在一个充分就业的小型开放经济中，国民储蓄为300。a. 如果国内投资由 I = 400 – 20r 给出，其中 r 为实际利率（以百分比计），那么如果该经济是封闭的，均衡利率是多少？b. 如果该经济是开放的且世界利率为10%，投资将是多少？c. 经常账户将是顺差还是逆差？净资本流出将是多少？","options":null},"topics":["trade-nex"],"answer_ref":"a. 封闭经济：S = I，300 = 400 − 20r，得 r = 5%。b. 开放经济 r = r* = 10%：I = 400 − 200 = 200。c. S − I = 100：经常账户顺差100；净资本流出 = 100（资本流向国外）。"},{"num":81,"type":"sa","question":"Assume that in a small open economy with full employment, consumption depends only on disposable income. National saving is 300, investment is given by I = 400 – 20r, where r is the real interest rate in percent, and the world interest rate is 10 percent. a. If government spending rises by 100, does investment change? What is the level of investment after the change? b. Does the trade balance change if G rises by 100? If it changes, does it increase or decrease, and by how much? c. Does net capital outflow change if G rises by 100? If it changes, does it increase or decrease, and by how much? d. Will the real exchange rate rise, fall, or remain constant as a result of the change in G?","options":null,"answer":null,"images":null,"translation":{"question":"假设在一个充分就业的小型开放经济中，消费只取决于可支配收入。国民储蓄为300，投资由 I = 400 – 20r 给出（r 为实际利率，以百分比计），世界利率为10%。a. 如果政府支出增加100，投资是否改变？变化后的投资水平是多少？b. 如果 G 增加100，贸易余额是否改变？如果改变，是增加还是减少，幅度多大？c. 如果 G 增加100，净资本流出是否改变？如果改变，是增加还是减少，幅度多大？d. 由于 G 的变化，实际汇率将上升、下降还是保持不变？","options":null},"topics":["trade-nex"],"answer_ref":"a. 投资不变。小国利率钉住世界利率10%，G↑使S降至200，但 I = I(r*) = 200 不变。b. 贸易平衡 S−I 由100降为0，减少100（顺差消失）。c. 净资本流出等于贸易平衡，也减少100。d. NCO减少→外汇市场上本币供给左移→实际汇率上升（本币升值）。"},{"num":82,"type":"sa","question":"Assume that the following equations characterize a large open economy: (1) Y = 5,000 (2) Y = C + I + G + NX (3) C = 1 / 2 (Y – T) (4) I = 2,000 – 100r (5) NX = 500 – 500e (6) CF = –100r (7) CF = NX (8) G = 1,500 (9) T = 1,000 where NX is net exports, CF is net capital outflow, and Î is the real exchange rate. Solve these equations for the equilibrium values of C, I, NX, CF, r, and e. (Hint: You can reduce the total number of equations to two through repeated substitutions. These two equations will be functions of r and e. Check your work by seeing that all of these equations balance, given your answers.)","options":null,"answer":null,"images":null,"translation":{"question":"假设以下方程刻画了一个大国开放经济：(1) Y = 5,000 (2) Y = C + I + G + NX (3) C = 1 / 2 (Y – T) (4) I = 2,000 – 100r (5) NX = 500 – 500ε (6) CF = –100r (7) CF = NX (8) G = 1,500 (9) T = 1,000 其中 NX 为净出口，CF 为净资本流出，ε 为实际汇率。解这些方程求 C、I、NX、CF、r 和 ε 的均衡值。（提示：你可以通过反复代入将方程总数化简为两个。这两个方程将是 r 和 ε 的函数。将你的答案代入，检验所有方程是否都平衡。）","options":null},"topics":["trade-nex"],"answer_ref":"C = 0.5×(5000−1000) = 2000。由 Y = C+I+G+NX 得 I+NX = 1500：(2000−100r)+(500−500e) = 1500 → r+5e = 10。由 CF = NX：−100r = 500−500e → 5e−r = 5。联立解得 e = 1.5，r = 2.5。回代：I = 2000−250 = 1750；NX = 500−750 = −250；CF = −250。验证：2000+1750+1500−250 = 5000 ✓。"},{"num":83,"type":"sa","question":"a. In April 1995, Michel Camdessus, managing director of the International Monetary Fund (IMF), criticized U.S. economic policy for allowing the dollar exchange rate to fall too low. He recommended that the United States reduce its budget deficit in order to raise the exchange rate. Use the long-run model of a small open economy to graphically illustrate the impact of reducing the government's budget deficit on the exchange rate and the trade balance. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; and v. the new long-run equilibrium values. b. Based on your graphical analysis, explain whether Mr. Camdessus's policy recommendation will work. Specifically state what happens to the exchange rate and the trade balance as a result of the government budget deficit reduction.","options":null,"answer":null,"images":null,"translation":{"question":"a. 1995年4月，国际货币基金组织(IMF)总裁米歇尔·康德苏批评美国经济政策让美元汇率跌得过低。他建议美国减少预算赤字以提高汇率。使用小型开放经济的长期模型，用图形说明减少政府预算赤字对汇率和贸易余额的影响。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 新的长期均衡值。b. 基于你的图形分析，说明康德苏先生的政策建议是否会奏效。具体说明由于政府预算赤字减少，汇率和贸易余额会发生什么变化。","options":null},"topics":["trade-nex"],"answer_ref":"a. 图（小国模型，外汇市场：纵轴实际汇率ε，横轴NX与NCO）：预算赤字减少→国民储蓄S↑→净资本流出NCO↑→外汇市场上美元供给曲线右移→ε下降，NX增加。b. 在模型中该建议适得其反：削减赤字使美元实际汇率下降（贬值而非升值），贸易余额改善。因此按这个模型，Camdessus 的提议无法抬高美元汇率——它会进一步压低美元、扩大净出口。"},{"num":84,"type":"sa","question":"a. In September 1995, Patrick Buchanan, a Republican candidate for president, proposed a 10 percent tariff on Japanese imports to the United States, a 20 percent tariff on Chinese imports to the United States, and an unspecified “social” tariff on imports from developing countries. Use the long-run model of a small open economy to graphically illustrate the impact of these trade policies on the U.S. exchange rate and the trade balance. Assume that the country starts from a position of trade balance. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; and v. the new long-run equilibrium values. b. Based on your graphical analysis, explain the predicted impact of Mr. Buchanan's proposed policies. Specifically state what happens to the exchange rate, the trade balance, the volume of imports, and the volume of exports.","options":null,"answer":null,"images":null,"translation":{"question":"a. 1995年9月，共和党总统候选人帕特·布坎南提议对从日本进口到美国的商品征收10%的关税，对从中国进口到美国的商品征收20%的关税，并对从发展中国家进口的商品征收一项未具体说明的“社会”关税。使用小型开放经济的长期模型，用图形说明这些贸易政策对美国汇率和贸易余额的影响。假设该国从贸易平衡状态出发。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 新的长期均衡值。b. 基于你的图形分析，说明布坎南先生提议政策的预期影响。具体说明汇率、贸易余额、进口量和出口量会发生什么变化。","options":null},"topics":["exchange-rate"],"answer_ref":"a. 图：关税使任一汇率下的净出口增加，NX(ε) 曲线右移；NCO（由储蓄与投资决定）不变→垂直供给不变。b. 预测结果：实际汇率ε上升（美元升值）；贸易平衡 NX = S−I 不变（起点为平衡则终点仍平衡）；进口量因关税直接减少，出口量因美元升值而减少——贸易总额萎缩，贸易平衡不变。"},{"num":85,"type":"sa","question":"a. Suppose that governments around the world begin to engage in expansionary fiscal policy (that is, run large budget deficits) in order to stimulate economic activity in their countries. Use the long-run model of a small open economy to graphically illustrate the impact of this expansionary fiscal policy by foreigners on the U.S. exchange rate and the trade balance. Assume that the country starts from a position of trade balance (that is, exports equal imports). Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; and v. the new long-run equilibrium values. b. Based on your graphical analysis, explain the predicted impact of the foreign expansionary fiscal policy on the U.S. exchange rate and the U.S. trade balance.","options":null,"answer":null,"images":null,"translation":{"question":"a. 假设世界各国政府开始实施扩张性财政政策（即实行大规模预算赤字）以刺激其国内经济活动。使用小型开放经济的长期模型，用图形说明外国实施这种扩张性财政政策对美国汇率和贸易余额的影响。假设该国从贸易平衡状态（即出口等于进口）出发。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 新的长期均衡值。b. 基于你的图形分析，说明外国扩张性财政政策对美国汇率和美国贸易余额的预期影响。","options":null},"topics":["trade-nex"],"answer_ref":"a. 图：外国扩张性财政政策抬高世界利率 r*→本国投资 I(r*) 下降→S−I 增加→NCO 增加→外汇供给右移→ε 下降（美元贬值），NX 增加。b. 影响：世界利率上升使美国投资减少，储蓄相对投资增加，净资本流出增加，美元实际汇率贬值，贸易余额改善（顺差扩大/逆差缩小）。"},{"num":86,"type":"sa","question":"a. If lack of job security causes consumers to spend less and save more, what will be the impact on the exchange rate and trade balance? Use the long-run model of a small open economy to graphically illustrate the impact of this decline in consumer confidence on the exchange rate and the trade balance. Assume that the country starts from a position of trade balance (that is, exports equal imports). Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; and v. the new long-run equilibrium values. b. Based on your graphical analysis, explain the predicted impact of a decline in consumer confidence on the exchange rate and the U.S. trade balance.","options":null,"answer":null,"images":null,"translation":{"question":"a. 如果缺乏就业保障使消费者减少支出、增加储蓄，这将对汇率和贸易余额产生什么影响？使用小型开放经济的长期模型，用图形说明消费者信心下降对汇率和贸易余额的影响。假设该国从贸易平衡状态（即出口等于进口）出发。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 新的长期均衡值。b. 基于你的图形分析，说明消费者信心下降对汇率和美国贸易余额的预期影响。","options":null},"topics":["exchange-rate"],"answer_ref":"a. 图：消费者信心下降→消费减少、国民储蓄S增加→NCO↑→外汇市场上本币供给右移→ε下降（本币贬值）→NX增加。b. 影响：实际汇率贬值，贸易余额改善（由平衡转为顺差）：储蓄增加使可贷资金外流增加，本币贬值刺激出口、抑制进口。"},{"num":87,"type":"sa","question":"Suppose that the large industrial countries of the world are concerned about the depreciating currencies of a number of small open economies. a. What type of fiscal policies must the large industrial countries undertake in order to promote currency appreciation in the small open economies? b. Graphically illustrate the impact of the industrial countries' policies on the exchange rate of the small open economies. c. What will happen to the trade balance of the typical small open economy, assuming that it starts from a position of balanced trade?","options":null,"answer":null,"images":null,"translation":{"question":"假设世界上的大型工业国担心若干小型开放经济的货币贬值。a. 大型工业国必须采取哪种类型的财政政策以促进小型开放经济的货币升值？b. 用图形说明工业国政策对小型开放经济汇率的影响。c. 假设一个典型的小型开放经济从贸易平衡状态出发，其贸易余额将发生什么变化？","options":null},"topics":["exchange-rate"],"answer_ref":"a. 大型工业国家应实行紧缩性（减少赤字的）财政政策：削减政府支出/增税，压低世界实际利率。b. 图（小国模型）：世界利率 r* 下降→小国国内投资 I↑→S−I↓→NCO↓→外汇市场上该国货币供给左移→实际汇率ε上升（升值）。c. 贸易平衡 NX = S−I 恶化（投资增加、储蓄不变），典型小国由平衡转为贸易逆差。"},{"num":88,"type":"sa","question":"Suppose that the International Monetary Fund (IMF) is concerned about currency depreciation in a small open economy. a. What type of fiscal policy should the IMF propose to the government of the small open economy to generate a currency appreciation? b. Graphically illustrate the impact of the IMF proposal on the exchange rate of the small open economy. c. What will happen to the trade balance of the small open economy, assuming that it started from a position of balanced trade?","options":null,"answer":null,"images":null,"translation":{"question":"假设国际货币基金组织(IMF)担心一个小型开放经济的货币贬值。a. IMF应向该小型开放经济政府提出哪种类型的财政政策以实现货币升值？b. 用图形说明IMF建议对该小型开放经济汇率的影响。c. 假设该小型开放经济从贸易平衡状态出发，其贸易余额将发生什么变化？","options":null},"topics":["exchange-rate"],"answer_ref":"a. IMF 应建议该国实行扩张性财政政策（增加支出或减税、扩大赤字）：国民储蓄减少→NCO减少→本币供给左移→货币升值。b. 图：S↓→NCO 曲线左移（外汇供给左移）→ε上升。c. 贸易平衡 = S−I 恶化：由平衡转为逆差（升值抑制出口、刺激进口）。"},{"num":89,"type":"sa","question":"The government of a small open economy wishes to promote trade policies that will result in currency appreciation. a. Would protectionist policies (higher tariffs and more quotas) or freer trade policies (tariff reductions and quota eliminations) be more effective in generating currency appreciation? b. Graphically illustrate the impact of the trade policy on the exchange rate of the small open economy. c. What will happen to the trade balance of the small open economy as a result of the trade policies, assuming that the country started from a position of free trade? d. What will happen to the quantity of exports and imports as a result of the trade policies?","options":null,"answer":null,"images":null,"translation":{"question":"一个小型开放经济的政府希望推行能带来货币升值的贸易政策。a. 保护主义政策（提高关税、增加配额）还是更自由的贸易政策（降低关税、取消配额）在产生货币升值方面更有效？b. 用图形说明该贸易政策对小型开放经济汇率的影响。c. 假设该国从自由贸易状态出发，由于这些贸易政策，该小型开放经济的贸易余额将发生什么变化？d. 由于这些贸易政策，出口量和进口量将发生什么变化？","options":null},"topics":["exchange-rate"],"answer_ref":"a. 保护主义政策（提高关税、增设配额）更有效：它使任一汇率下净出口增加，NX曲线右移推动本币升值；自由贸易政策方向相反。b. 图：NX(ε) 右移，NCO 垂直线不变→ε 由 ε₁ 升至 ε₂。c. 贸易平衡不变：NX 始终等于 S−I（储蓄与投资未变），关税只改变汇率而不改变净出口总量。d. 进口量因关税/配额直接下降；出口量因本币升值而下降。进出口双向萎缩。"},{"num":90,"type":"sa","question":"Compare the impact of an increase in the government's budget deficit on investment spending in a small open economy versus in a comparable closed economy. Assume that prices are flexible and that factors of production are fully employed in both economies. Assume that there is perfect capital mobility for the small open economy.","options":null,"answer":null,"images":null,"translation":{"question":"比较政府预算赤字增加对小型开放经济与一个可比的封闭经济中投资支出的影响。假设两个经济中价格都是弹性的、生产要素都被充分利用。假设小型开放经济具有完全的资本流动性。","options":null},"topics":["trade-nex"],"answer_ref":"封闭经济：赤字减少国民储蓄→可贷资金供给左移→国内利率上升→投资被挤出（I下降）。小型开放经济：利率钉住世界利率不变，投资 I(r*) 不受影响；赤字引起净资本流出减少、本币升值，被挤出的是净出口而非投资。"},{"num":91,"type":"sa","question":"Explain why government budget deficits crowd out private investment spending in a closed economy but crowd out net exports in a small open economy. Assume that prices are flexible and that factors of production are fully employed in both economies. Assume that there is perfect capital mobility for the small open economy.","options":null,"answer":null,"images":null,"translation":{"question":"解释为什么政府预算赤字在封闭经济中挤出私人投资支出，而在小型开放经济中挤出净出口。假设两个经济中价格都是弹性的、生产要素都被充分利用。假设小型开放经济具有完全的资本流动性。","options":null},"topics":["trade-nex"],"answer_ref":"封闭经济中没有对外部门，储蓄减少只能靠利率上升来出清可贷资金市场，利率上升压低私人投资——投资被挤出。小型开放经济中资本完全流动，利率固定在世界水平，可贷资金由国际资本流动调节：储蓄减少表现为净资本流出减少、外汇市场上本币供给减少、本币升值，从而净出口下降——被挤出的是净出口。"},{"num":92,"type":"sa","question":"Suppose a new technology is developed that increases investment demand. Holding other factors constant, will the quantity of investment spending increase more in a closed economy or in a comparable small open economy? Explain. Assume that prices are flexible and that factors of production are fully employed in both economies. Assume that there is perfect capital mobility for the small open economy.","options":null,"answer":null,"images":null,"translation":{"question":"假设开发出一项增加投资需求的新技术。在其他因素不变的情况下，封闭经济中还是一个可比的小型开放经济中投资支出的数量会增加更多？请解释。假设两个经济中价格都是弹性的、生产要素都被充分利用。假设小型开放经济具有完全的资本流动性。","options":null},"topics":["trade-nex"],"answer_ref":"封闭经济中投资增加得更多。封闭经济里投资需求右移使均衡投资量上升（利率随之上升有部分抑制）。小型开放经济中利率被钉在世界水平，投资量 I(r*) 由世界利率决定，本国投资需求增加完全不会改变投资量（也无利率、汇率变化）。"},{"num":93,"type":"sa","question":"The real interest rates and real exchanges rates are constant and equal in North Country and South Country. The Fisher equation and purchasing-power parity hold in both countries. If the nominal interest rate is 8 percent in North Country and 10 percent in South Country, do you expect North Country's nominal exchange rate to appreciate, depreciate, or remain the same? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"北方国和南方国的实际利率和实际汇率恒定且相等。费雪方程和购买力平价在两个国家都成立。如果北方国名义利率为8%、南方国名义利率为10%，你预期北方国的名义汇率会升值、贬值还是保持不变？请解释。","options":null},"topics":["ppp"],"answer_ref":"预期北方国家的名义汇率升值（以南方货币表示）。费雪方程：北方通胀 = 8% − r，南方通胀 = 10% − r，南方通胀率比北方高2个百分点。购买力平价意味着高通胀国家的货币贬值，即南方货币贬值、北方货币相对升值。"},{"num":94,"type":"sa","question":"In the 2008 global financial crisis, many investors considered the U.S. economy a safe place to move their assets. What is the predicted impact of this inflow of financial capital to the United States on the U.S. interest rate and the U.S. exchange rate, holding other factors constant? Illustrate your answer graphically and explain in words.","options":null,"answer":null,"images":null,"translation":{"question":"在2008年全球金融危机中，许多投资者认为美国经济是其资产转移的安全去处。在其他因素不变的情况下，这种金融资本流入美国对美国的利率和汇率会产生什么预期影响？用图形说明你的答案并用文字解释。","options":null},"topics":["trade-nex"],"answer_ref":"图形（大国模型）：资本流入使净资本流出 CF 曲线左移（每个利率下流出更少）。可贷资金市场：S = I + CF，CF 减少推动均衡利率 r 下降；外汇市场：CF 减少使美元供给减少，实际汇率ε上升。结论：美国利率下降、美元升值。文字解释：全球避险资金追逐美国资产，抬升美元并压低美国利率。"},{"num":95,"type":"sa","question":"In times of great economic uncertainty and potential job loss, many consumers may increase their saving as a precautionary measure. What is the predicted impact of an increase in national saving on the domestic interest rate and exchange rate in a large open economy, holding other factors constant? Illustrate your answer graphically and explain in words.","options":null,"answer":null,"images":null,"translation":{"question":"在巨大的经济不确定性和潜在失业风险时期，许多消费者可能出于预防性动机增加储蓄。在其他因素不变的情况下，国民储蓄增加对大国开放经济的国内利率和汇率会产生什么预期影响？用图形说明你的答案并用文字解释。","options":null},"topics":["trade-nex"],"answer_ref":"图形：国民储蓄 S 增加→可贷资金供给右移→r 下降；利率下降使净资本流出 CF 增加→外汇市场上本币供给右移→实际汇率ε下降（本币贬值）。结论：预防性储蓄增加使国内利率下降、本币贬值、净出口增加。"},{"num":96,"type":"sa","question":"Major improvements in computer information technology and communications in the late 1990s fueled an increase in investment demand in the United States, which is a large open economy. What is the predicted impact of this increased investment demand in the United States on the U.S. interest rate, the U.S. exchange rate, and U.S. net exports, holding other factors constant? Illustrate your answer graphically and explain in words.","options":null,"answer":null,"images":null,"translation":{"question":"1990年代末计算机信息技术和通信领域的重大进步推动了美国（一个大国开放经济）投资需求的增加。在其他因素不变的情况下，美国投资需求增加对美国的利率、汇率和净出口会产生什么预期影响？用图形说明你的答案并用文字解释。","options":null},"topics":["trade-nex"],"answer_ref":"图形：投资需求增加→I(r) 右移→均衡利率 r 上升；r 上升使 CF 减少（资本流入）→外汇市场上美元供给左移→ε 升值；NX = S−I 下降。结论：利率上升、美元升值、净出口减少（贸易状况恶化）。"},{"num":97,"type":"sa","question":"If the money supply in Mexico is increasing much more rapidly than the money supply in the United States, holding other factors constant, what would you predict will happen to the nominal exchange rate between the Mexican peso and the United States dollar if purchasing power parity holds? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"如果墨西哥的货币供应量增长速度远快于美国，在其他因素不变的情况下，若购买力平价成立，你预测墨西哥比索与美元之间的名义汇率会发生什么变化？请解释。","options":null},"topics":["ppp"],"answer_ref":"购买力平价下，两国物价水平之比决定名义汇率（比索/美元 = 墨西哥物价/美国物价）。墨西哥货币增长更快→其物价水平上升更快→比索名义汇率上升（比索对美元贬值），贬值幅度约等于两国货币增长率之差（若实际增长相近）。"},{"num":98,"type":"sa","question":"Compare the impact of an increase in investment demand in a small open economy and a large open economy. Assume that prices are flexible, factors of production are fully employed in both countries, and there is perfect capital mobility in the small open economy.","options":null,"answer":null,"images":null,"translation":{"question":"比较投资需求增加对小型开放经济和大型开放经济的影响。假设价格是弹性的、两个国家的生产要素都被充分利用，且小型开放经济具有完全的资本流动性。","options":null},"topics":["trade-nex"],"answer_ref":"小型开放经济：利率等于世界利率且不受本国投资需求影响，投资量 I(r*) 不变；投资需求增加对投资量、利率均无影响（NX = S−I 也不变）。大型开放经济：投资需求增加推高国内利率，投资量部分增加；高利率吸引资本流入（CF 减少），本币升值，净出口下降。"},{"num":99,"type":"sa","question":"Why is the domestic output not equal to the domestic spending in an open economy? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"为什么在开放经济中国内产出不等于国内支出？请解释。","options":null},"topics":["trade-nex"],"answer_ref":"因为产出的一部分卖给了外国人（出口X），而国内支出的一部分用于购买外国产品（进口）。国民收入核算恒等式 Y = C + I + G + NX 中，国内支出为 C+I+G，两者之差即净出口 NX：Y 超过国内支出的部分是净出口，反之则是净进口。"},{"num":100,"type":"sa","question":"Fill in the blanks: According to the national income accounts identity, an economy's _____________ must always equal the difference between its ____________ and its _____________.","options":null,"answer":null,"images":null,"translation":{"question":"填空：根据国民收入核算恒等式，一个经济的 _____________ 必须始终等于其 ____________ 与其 _____________ 之差。","options":null},"topics":["trade-nex"],"answer_ref":"净出口（贸易余额）= 产出（Y）− 国内支出（C+I+G）。"},{"num":101,"type":"sa","question":"What is the difference between trade surplus and trade deficit? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"贸易顺差与贸易逆差有什么区别？请解释。","options":null},"topics":["trade-nex"],"answer_ref":"贸易顺差：出口大于进口（NX>0），产出超过国内支出，国家对外净放贷（净资本流出为正）。贸易逆差：进口大于出口（NX<0），国内支出超过产出，国家从国外净借入（净资本流出为负）。"},{"num":102,"type":"sa","question":"[[IMG:c6_img7.png]] From this graph, what is the world interest rate at which there will be equilibrium in the capital market of a small open economy?","options":null,"answer":null,"images":null,"translation":{"question":"[[IMG:c6_img7.png]] 从这张图中，小型开放经济资本市场达到均衡时的世界利率是多少？","options":null},"topics":["trade-nex"],"answer_ref":"世界利率是使该小国可贷资金市场（S 与 I 之差）等于其净资本流出的利率：在图形上即 S−I（NCO）曲线与表示世界利率的水平线的交点所对应的利率；在交点处国内储蓄减投资的差额正好等于按世界利率所愿流出的资本，外汇市场出清。"},{"num":103,"type":"sa","question":"What will be the effect of an increase in fiscal expansion abroad by a large economy on the trade balance of a small open economy?","options":null,"answer":null,"images":null,"translation":{"question":"一个大型经济在国外进行财政扩张，这对一个小型开放经济的贸易余额会产生什么影响？","options":null},"topics":["trade-nex"],"answer_ref":"国外（大国）财政扩张→世界利率 r* 上升→小国国内投资减少→S−I 增加→净资本流出增加→外汇供给右移→本币实际汇率贬值→净出口增加。小国的贸易平衡改善。"},{"num":104,"type":"sa","question":"What is the difference between the strengthening and weakening of domestic currency? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"本币走强与本币走弱有什么区别？请解释。","options":null},"topics":["exchange-rate"],"answer_ref":"走强（升值）：一单位本币可兑换更多外币，本国产品对外国人变贵、外国产品对本国人变便宜，出口趋于减少、进口增加，NX 下降。走弱（贬值）：一单位本币兑换的外币更少，本国产品对外国人变便宜，出口趋于增加、进口减少，NX 上升。"},{"num":105,"type":"sa","question":"Graphically illustrate the relationship between the real exchange rate and net exports.","options":null,"answer":null,"images":null,"translation":{"question":"用图形说明实际汇率与净出口之间的关系。","options":null},"topics":["exchange-rate"],"answer_ref":"实际汇率 ε 与净出口 NX 反向关系：纵轴 ε、横轴 NX。ε 上升（本国产品相对变贵）→出口减少、进口增加→NX 减少，故曲线向右下方倾斜；净资本流出 NCO 与汇率无关，为垂直线；两线交点决定均衡汇率，且 NX = NCO。"},{"num":106,"type":"sa","question":"Why is purchasing power parity called “the law of one price”? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"为什么购买力平价被称为“一价定律”？请解释。","options":null},"topics":["ppp"],"answer_ref":"因为购买力平价认为同一种商品在所有国家应以相同价格出售（折算成同一货币后），即\"一物一价\"；套利的存在会促使价格趋同。把这一逻辑推广到整个物价水平，汇率就应等于两国物价水平之比——相当于把\"一物一价\"定律适用于所有商品的综合，因此被称为平价定律（law of one price）。"},{"num":107,"type":"sa","question":"What is the effect of investment enhancement measures on the trade balance of a small open economy?","options":null,"answer":null,"images":null,"translation":{"question":"投资促进措施对小型开放经济的贸易余额有什么影响？","options":null},"topics":["trade-nex"],"answer_ref":"小型开放经济中净贸易平衡 NX = S−I，而投资由世界利率决定（I = I(r*)）。投资促进措施使投资需求曲线右移，但世界利率不变，投资量不变，储蓄也不变，因此贸易平衡不变——此类政策改变的是汇率或没有实际效果，而不改变贸易余额。"}]},{"num":7,"title":"Unemployment","questions":[{"num":1,"type":"mc","question":"The macroeconomic problem that affects individuals most directly and severely is:","options":["inflation.","unemployment.","low savings.","low investment."],"answer":"B","images":null,"translation":{"question":"对个人影响最直接、最严重的宏观经济问题是：","options":["通货膨胀。","失业。","储蓄不足。","投资不足。"]},"topics":["natural-rate"]},{"num":2,"type":"mc","question":"The natural rate of unemployment is:","options":["the average rate of unemployment around which the economy fluctuates.","about 10 percent of the labor force.","a rate that never changes.","the transition of individuals between employment and unemployment."],"answer":"A","images":null,"translation":{"question":"自然失业率是：","options":["经济围绕其波动的平均失业率。","约占劳动力的10%。","一个从不改变的比率。","个人在就业与失业之间的转换。"]},"topics":["natural-rate"]},{"num":3,"type":"mc","question":"If the number of employed workers equals 200 million and the number of unemployed workers equals 20 million, the unemployment rate equals ______ percent (rounded to the nearest percent).","options":["0","9","11","20"],"answer":"B","images":null,"translation":{"question":"如果就业人数为2亿、失业人数为2000万，那么失业率等于 ______%（四舍五入到最接近的百分数）。","options":["0","9","11","20"]},"topics":["natural-rate"]},{"num":4,"type":"mc","question":"When the unemployment rate is at a steady state:","options":["no hiring or firings are occurring.","the number of people finding jobs equals the number of people losing jobs.","the number of people finding jobs exceeds the number of people losing jobs.","the number of people losing jobs exceeds the number of people finding jobs."],"answer":"B","images":null,"translation":{"question":"当失业率处于稳态时：","options":["没有任何雇佣或解雇发生。","找到工作的人数等于失去工作的人数。","找到工作的人数超过失去工作的人数。","失去工作的人数超过找到工作的人数。"]},"topics":["natural-rate"]},{"num":5,"type":"mc","question":"In the model of the steady-state unemployment rate with a fixed labor force, the rate of job finding equals the percentage of the ______ who find a job each month, while the rate of job separation equals the percentage of the ______ who lose their job each month.","options":["labor force; labor force","labor force; unemployed","employed; labor force","unemployed; employed"],"answer":"D","images":null,"translation":{"question":"在劳动力固定的稳态失业率模型中，就职率等于每月找到工作的 ______ 的百分比，而离职率等于每月失去工作的 ______ 的百分比。","options":["劳动力；劳动力","劳动力；失业者","就业者；劳动力","失业者；就业者"]},"topics":["natural-rate"]},{"num":6,"type":"mc","question":"A policy that increases the job-finding rate _____ the natural rate of unemployment.","options":["will increase","will decrease","will not change","could either increase or decrease"],"answer":"B","images":null,"translation":{"question":"提高就职率的政策 _____ 自然失业率。","options":["将提高","将降低","不会改变","可能提高也可能降低"]},"topics":["natural-rate"]},{"num":7,"type":"mc","question":"A policy that decreases the job separation rate _____ the natural rate of unemployment.","options":["will increase","will decrease","will not change","could either increase or decrease"],"answer":"B","images":null,"translation":{"question":"降低离职率的政策 _____ 自然失业率。","options":["将提高","将降低","不会改变","可能提高也可能降低"]},"topics":["natural-rate"]},{"num":8,"type":"mc","question":"If s is the rate of job separation, f is the rate of job finding, and both rates are constant, then the steady state unemployment rate is approximately:","options":["f / (f + s).","(f + s) / f.","s / (s + f).","(s + f) / s."],"answer":"C","images":null,"translation":{"question":"如果 s 为离职率、f 为就职率，且两者都恒定，那么稳态失业率约等于：","options":["f / (f + s)。","(f + s) / f。","s / (s + f)。","(s + f) / s。"]},"topics":["natural-rate"]},{"num":9,"type":"mc","question":"If the fraction of employed workers who lose their jobs each month (the rate of job separation) is 0.01 and the fraction of the unemployed who find a job each month is 0.09 (the rate of job findings), then the natural rate of unemployment is:","options":["1 percent.","9 percent.","10 percent.","about 11 percent."],"answer":"C","images":null,"translation":{"question":"如果每月失去工作的就业者比例（离职率）为0.01，每月找到工作的失业者比例（就职率）为0.09，那么自然失业率为：","options":["1%。","9%。","10%。","约11%。"]},"topics":["natural-rate"]},{"num":10,"type":"mc","question":"If the steady-state rate of unemployment equals 0.10 and the fraction of employed workers who lose their jobs each month (the rate of job separations) is 0.02, then the fraction of unemployed workers who find jobs each month (the rate of job findings) must be:","options":["0.02.","0.08.","0.10.","0.18."],"answer":"D","images":null,"translation":{"question":"如果稳态失业率等于0.10，每月失去工作的就业者比例（离职率）为0.02，那么每月找到工作的失业者比例（就职率）必定为：","options":["0.02。","0.08。","0.10。","0.18。"]},"topics":["natural-rate"]},{"num":11,"type":"mc","question":"If the steady-state rate of unemployment equals 0.125 and the fraction of unemployed workers who find jobs each month (the rate of job findings) is 0.56, then the fraction of employed workers who lose their jobs each month (the rate of job separations) must be:","options":["0.08.","0.125.","0.22.","0.435."],"answer":"A","images":null,"translation":{"question":"如果稳态失业率等于0.125，每月找到工作的失业者比例（就职率）为0.56，那么每月失去工作的就业者比例（离职率）必定为：","options":["0.08。","0.125。","0.22。","0.435。"]},"topics":["natural-rate"]},{"num":12,"type":"mc","question":"Any policy aimed at lowering the natural rate of unemployment must either ______ the rate of job separation or ______ the rate of job finding.","options":["reduce; reduce","increase; increase","reduce; increase","increase; reduce"],"answer":"C","images":null,"translation":{"question":"任何旨在降低自然失业率的政策都必须要么 ______ 离职率，要么 ______ 就职率。","options":["降低；降低","提高；提高","降低；提高","提高；降低"]},"topics":["natural-rate"]},{"num":13,"type":"mc","question":"One reason for unemployment is that:","options":["it takes time to match workers and jobs.","all jobs are identical.","the labor market is always in equilibrium.","a laid-off worker can immediately find a new job at the market wage."],"answer":"A","images":null,"translation":{"question":"失业的一个原因是：","options":["工人与工作岗位的匹配需要时间。","所有工作岗位都是相同的。","劳动力市场总是处于均衡。","被解雇的工人能立即按市场工资找到新工作。"]},"topics":["job-search"]},{"num":14,"type":"mc","question":"All of the following are reasons for frictional unemployment except:","options":["workers have different preferences and abilities.","unemployed workers accept the first job offer that they receive.","the flow of information is imperfect.","geographic mobility takes time."],"answer":"B","images":null,"translation":{"question":"以下都是摩擦性失业的原因，除了：","options":["工人有不同的偏好和能力。","失业工人接受他们收到的第一个工作录用。","信息流动是不完全的。","地域流动需要时间。"]},"topics":["job-search"]},{"num":15,"type":"mc","question":"Frictional unemployment is unemployment caused by:","options":["wage rigidity.","minimum-wage legislation.","the time it takes workers to search for a job.","clashes between the motives of insiders and outsiders."],"answer":"C","images":null,"translation":{"question":"摩擦性失业是由以下原因引起的失业：","options":["工资刚性。","最低工资立法。","工人寻找工作所需的时间。","内部人与外部人动机之间的冲突。"]},"topics":["job-search"]},{"num":16,"type":"mc","question":"Which of the following is an example of frictional unemployment?","options":["Dave searches for a new job after voluntarily moving to San Diego.","Elaine is willing to work for less than the minimum wage, but employers cannot hire her for less than the minimum wage.","Bill is qualified and would like to be an airline pilot, but airlines do not find it profitable to hire him at the wage established by the airline pilots' union.","Joan is willing to work for less than the going wage, but there are no jobs available."],"answer":"A","images":null,"translation":{"question":"以下哪项是摩擦性失业的例子？","options":["戴夫自愿搬到圣迭戈后寻找新工作。","伊莱恩愿意以低于最低工资的报酬工作，但雇主不能以低于最低工资的报酬雇佣她。","比尔有资格并想成为一名航空公司飞行员，但航空公司在航空公司飞行员工会确定的工资水平上雇佣他无利可图。","琼愿意以低于现行工资的报酬工作，但没有可得到的工作岗位。"]},"topics":["job-search"]},{"num":17,"type":"mc","question":"Sectoral shifts:","options":["lead to wage rigidity.","explain the payment of efficiency wages.","depend on the level of the minimum wage.","make frictional unemployment inevitable."],"answer":"D","images":null,"translation":{"question":"部门转移：","options":["导致工资刚性。","解释了效率工资的支付。","取决于最低工资的水平。","使摩擦性失业不可避免。"]},"topics":["job-search"]},{"num":18,"type":"mc","question":"Economists call the changes in the composition of demand among industries and regions:","options":["insider–outsider conflicts.","sectoral shifts.","moral hazard.","adverse selection."],"answer":"B","images":null,"translation":{"question":"经济学家把各行业和地区之间需求构成的变化称为：","options":["内部人—外部人冲突。","部门转移。","道德风险。","逆向选择。"]},"topics":["job-search"]},{"num":19,"type":"mc","question":"Frictional unemployment is inevitable because:","options":["different sectors do not shift.","the economy needs to be lubricated.","workers never quit their jobs to change careers.","the demand for different goods always fluctuates."],"answer":"D","images":null,"translation":{"question":"摩擦性失业不可避免是因为：","options":["不同部门不发生转移。","经济需要润滑。","工人从不辞职转行。","对不同商品的需求总是波动。"]},"topics":["job-search"]},{"num":20,"type":"mc","question":"Unemployment insurance increases the amount of frictional unemployment by:","options":["making workers more frantic in their search for new jobs.","inducing workers to accept the first job offer that they receive.","making employers more reluctant to lay off workers.","softening the economic hardship of unemployment."],"answer":"D","images":null,"translation":{"question":"失业保险通过以下方式增加摩擦性失业量：","options":["使工人更加急切地寻找新工作。","促使工人接受他们收到的第一个工作录用。","使雇主更不愿解雇工人。","减轻失业的经济困难。"]},"topics":["job-search"]},{"num":21,"type":"mc","question":"Which of the following policies were not adopted by the government in an attempt to reduce the natural rate of unemployment?","options":["unemployment insurance","government employment agencies","public retraining programs","the Illinois bonus program for unemployment insurance claimants who found jobs quickly"],"answer":"A","images":null,"translation":{"question":"以下哪项政策不是政府为降低自然失业率而采取的？","options":["失业保险","政府就业机构","公共再培训计划","伊利诺伊州针对迅速找到工作的失业保险领取者的奖金计划"]},"topics":["job-search"]},{"num":22,"type":"mc","question":"Government policies directed at reducing frictional unemployment include:","options":["abolishing minimum-wage laws.","making unemployment insurance 100 percent experience rated.","increasing the earned income credit.","making government part of the union–firm wage bargaining process."],"answer":"B","images":null,"translation":{"question":"旨在减少摩擦性失业的政府政策包括：","options":["废除最低工资法。","使失业保险100%实行经验费率。","提高劳动所得税抵免。","使政府成为工会—企业工资谈判过程的一部分。"]},"topics":["job-search"]},{"num":23,"type":"mc","question":"Public policy to increase the job finding rate includes _____, and public policy to decrease the job separation rate includes _____.","options":["government employment agencies; higher unemployment insurance benefits","government employment agencies; 100 percent experience-rated unemployment insurance","higher minimum wage laws; payment of unemployment benefits for longer periods","higher efficiency wages; partially experience-rated unemployment insurance"],"answer":"B","images":null,"translation":{"question":"提高就职率的公共政策包括 _____，降低离职率的公共政策包括 _____。","options":["政府就业机构；更高的失业保险金","政府就业机构；100%经验费率的失业保险","更高的最低工资法；延长失业保险金的支付期限","更高的效率工资；部分经验费率的失业保险"]},"topics":["job-search"]},{"num":24,"type":"mc","question":"According to studies of individual unemployed workers, these workers are most likely to find a job:","options":["about three months before their unemployment insurance runs out.","within a few weeks of their unemployment insurance running out.","about three months after their unemployment insurance runs out.","at a time not influenced by the remaining number of weeks of unemployment insurance."],"answer":"B","images":null,"translation":{"question":"根据对单个失业工人的研究，这些工人最有可能在以下时间找到工作：","options":["在其失业保险到期前约三个月。","在其失业保险到期后的几周内。","在其失业保险到期后约三个月。","在不受失业保险剩余周数影响的时间。"]},"topics":["job-search"]},{"num":25,"type":"mc","question":"The unemployment resulting when real wages are held above equilibrium is called ______ unemployment, while the unemployment that occurs as workers search for a job that best suits their skills is called ______ unemployment.","options":["efficiency; inefficiency","efficiency; structural","frictional; efficiency","structural; frictional"],"answer":"D","images":null,"translation":{"question":"当实际工资被维持在均衡水平之上时所导致的失业被称为 ______ 失业，而工人寻找最适合其技能的工作时所发生的失业被称为 ______ 失业。","options":["效率；无效率","效率；结构性","摩擦性；效率","结构性；摩擦性"]},"topics":["wage-rigidity","job-search"]},{"num":26,"type":"mc","question":"Wage rigidity:","options":["forces labor demand to equal labor supply.","is caused by sectoral shifts.","prevents labor demand and labor supply from reaching the equilibrium level.","increases the rate of job finding."],"answer":"C","images":null,"translation":{"question":"工资刚性：","options":["迫使劳动需求等于劳动供给。","由部门转移引起。","阻止劳动需求和劳动供给达到均衡水平。","提高就职率。"]},"topics":["wage-rigidity"]},{"num":27,"type":"mc","question":"When the real wage is above the level that equilibrates supply and demand:","options":["the quantity of labor supplied exceeds the quantity demanded.","the quantity of labor demanded exceeds the quantity supplied.","there is no unemployment.","the labor market clears."],"answer":"A","images":null,"translation":{"question":"当实际工资高于使供求均衡的水平时：","options":["劳动供给量超过劳动需求量。","劳动需求量超过劳动供给量。","不存在失业。","劳动力市场出清。"]},"topics":["wage-rigidity"]},{"num":28,"type":"mc","question":"Workers unemployed as a result of wage rigidity are:","options":["actively searching for a job to match their skills.","not eligible to receive unemployment insurance benefits.","waiting for a job to become available.","relocating to another part of the country as a result of sectoral shifts."],"answer":"C","images":null,"translation":{"question":"由于工资刚性而失业的工人：","options":["正在积极寻找与自身技能匹配的工作。","没有资格领取失业保险金。","正在等待工作岗位出现。","由于部门转移而迁往国内其他地区。"]},"topics":["wage-rigidity"]},{"num":29,"type":"mc","question":"Which of the following is the best example of structural unemployment?","options":["Tim is looking for a job with flexible hours but has not been offered one yet.","Vickie lost her job as a graphic artist at a movie studio because she did not have training in computer-generated animation.","Kirby is seeking a job as an airline pilot, but the high union wages in the industry have limited the number of jobs available.","Fatima lost her job at a packing plant but has not looked very intensively for a new job because she still has two months of unemployment insurance benefits left."],"answer":"C","images":null,"translation":{"question":"以下哪项是结构性失业的最好例子？","options":["蒂姆正在寻找工作时间灵活的工作，但尚未得到录用。","维姬失去了电影制片厂平面艺术家的工作，因为她没有接受过计算机生成动画方面的培训。","柯比正在寻找航空公司飞行员的工作，但该行业的高工会工资限制了可提供的工作岗位数量。","法蒂玛失去了包装厂的工作，但由于她还有两个月的失业保险金可领，所以她没有很积极地寻找新工作。"]},"topics":["wage-rigidity"]},{"num":30,"type":"mc","question":"All of the following are causes of structural unemployment except:","options":["minimum-wage laws.","the monopoly power of unions.","unemployment insurance.","efficiency wages."],"answer":"C","images":null,"translation":{"question":"以下都是结构性失业的原因，除了：","options":["最低工资法。","工会的垄断力量。","失业保险。","效率工资。"]},"topics":["wage-rigidity"]},{"num":31,"type":"mc","question":"If wage rigidity holds the real wage above the equilibrium level, an increase in the supply of labor will ______ the number unemployed.","options":["increase","decrease","not change","possibly increase, decrease, or leave unchanged"],"answer":"A","images":null,"translation":{"question":"如果工资刚性使实际工资维持在均衡水平之上，那么劳动供给的增加将 ______ 失业人数。","options":["增加","减少","不改变","可能增加、减少或保持不变"]},"topics":["wage-rigidity"]},{"num":32,"type":"mc","question":"Permitting a lower minimum wage for teenagers would likely:","options":["raise teenage unemployment.","raise teenage wages overall.","prevent teenagers from getting job experience.","raise unemployment among unskilled adults."],"answer":"D","images":null,"translation":{"question":"允许对青少年实行较低的最低工资很可能：","options":["提高青少年失业率。","总体上提高青少年工资。","阻止青少年获得工作经验。","提高非熟练成年人的失业率。"]},"topics":["wage-rigidity"]},{"num":33,"type":"mc","question":"The earned income tax credit:","options":["increases the government's tax revenue.","reduces the incomes of poor working families.","does not raise labor costs.","is not an alternative to raising the minimum wage."],"answer":"C","images":null,"translation":{"question":"劳动所得税抵免：","options":["增加政府的税收收入。","减少贫困工薪家庭的收入。","不提高劳动力成本。","不是提高最低工资的替代方案。"]},"topics":["wage-rigidity"]},{"num":34,"type":"mc","question":"Which of the following statements about minimum-wage workers in the United States is not correct:","options":["minimum-wage workers are more likely to be male.","minimum-wage workers are more likely to work part time.","minimum-wage workers are more likely to be less educated.","minimum-wage workers are more likely to be young."],"answer":"A","images":null,"translation":{"question":"以下关于美国最低工资工人的说法哪项不正确：","options":["最低工资工人更可能是男性。","最低工资工人更可能从事兼职工作。","最低工资工人更可能受教育程度较低。","最低工资工人更可能是年轻人。"]},"topics":["wage-rigidity"]},{"num":35,"type":"mc","question":"Unions contribute to structural unemployment when collective bargaining results in wages:","options":["above the equilibrium level.","below the minimum wage.","below the equilibrium level.","above the level of unemployment compensation."],"answer":"A","images":null,"translation":{"question":"当集体谈判使工资处于以下水平时，工会会导致结构性失业：","options":["高于均衡水平。","低于最低工资。","低于均衡水平。","高于失业补偿金水平。"]},"topics":["wage-rigidity"]},{"num":36,"type":"mc","question":"In the case of unions, the conflict of interest between different groups of workers results in insiders wanting ______, while outsiders want ______.","options":["more hirings; high wages","high wages; more hirings","high wages; fewer hirings","fewer hirings; high wages"],"answer":"B","images":null,"translation":{"question":"就工会而言，不同工人群体之间的利益冲突导致内部人想要 ______，而外部人想要 ______。","options":["更多的雇佣；高工资","高工资；更多的雇佣","高工资；更少的雇佣","更少的雇佣；高工资"]},"topics":["wage-rigidity"]},{"num":37,"type":"mc","question":"When insiders have a much greater impact on the wage-bargaining process than do outsiders, the negotiated wage is likely to be ______ the equilibrium wage.","options":["much greater than","much less than","almost equal to","about one-half of"],"answer":"A","images":null,"translation":{"question":"当内部人对工资谈判过程的影响远大于外部人时，谈判确定的工资很可能 ______ 均衡工资。","options":["远高于","远低于","几乎等于","约为其一半"]},"topics":["wage-rigidity"]},{"num":38,"type":"mc","question":"Centralized union wage bargaining with government intervention in Sweden gives relatively more influence to ______, while firm-level union wage bargaining in the United States gives relatively more influence to ______.","options":["efficiency wages; sectoral shifts","sectoral shifts; efficiency wages","insiders; outsiders","outsiders; insiders"],"answer":"D","images":null,"translation":{"question":"瑞典有政府介入的集中式工会工资谈判给予 ______ 相对更大的影响，而美国企业层面的工会工资谈判给予 ______ 相对更大的影响。","options":["效率工资；部门转移","部门转移；效率工资","内部人；外部人","外部人；内部人"]},"topics":["wage-rigidity"]},{"num":39,"type":"mc","question":"One efficiency-wage theory implies that firms pay high wages because:","options":["this practice increases the problem of moral hazard.","in wealthy countries, it is important to pay workers high wages to improve their health.","the more a firm pays its workers, the greater their incentive to stay with the firm.","paying high wages promotes adverse selection."],"answer":"C","images":null,"translation":{"question":"一种效率工资理论意味着企业支付高工资是因为：","options":["这种做法加剧了道德风险问题。","在富裕国家，向工人支付高工资以改善其健康很重要。","企业支付给工人的工资越多，工人留在企业的激励就越大。","支付高工资会促进逆向选择。"]},"topics":["wage-rigidity"]},{"num":40,"type":"mc","question":"Efficiency-wage theories suggest that a firm may pay workers more than the market-clearing wage for all of the following reasons except to:","options":["reduce labor turnover.","improve the quality of the firm's labor force.","increase worker effort.","reduce the firm's wage bill."],"answer":"D","images":null,"translation":{"question":"效率工资理论表明，企业可能因以下所有原因向工人支付高于市场出清水平的工资，除了：","options":["降低劳动力流动率。","提高企业劳动力的质量。","提高工人的努力程度。","降低企业的工资支出。"]},"topics":["wage-rigidity"]},{"num":41,"type":"mc","question":"According to efficiency-wage theories, firms benefit by paying higher-than-equilibrium wages because worker _____ increases.","options":["productivity","turnover","unionization","shirking"],"answer":"A","images":null,"translation":{"question":"根据效率工资理论，企业通过支付高于均衡水平的工资而受益，因为工人的 _____ 提高了。","options":["生产率","流动率","工会化程度","偷懒"]},"topics":["wage-rigidity"]},{"num":42,"type":"mc","question":"Paying efficiency wages helps firms reduce the problem of adverse selection by:","options":["generating additional profits that can be used to pay for more proficient hiring managers.","keeping labor unions from organizing workers in the firm.","encouraging unsupervised workers to maintain a high level of productivity.","providing an incentive for the best-qualified workers to remain with the firm."],"answer":"D","images":null,"translation":{"question":"支付效率工资通过以下方式帮助企业减少逆向选择问题：","options":["产生额外的利润，用于支付更称职的招聘经理。","阻止工会在企业内组织工人。","鼓励无人监督的工人保持高水平的生产率。","为最有资格的工人留在企业提供激励。"]},"topics":["wage-rigidity"]},{"num":43,"type":"mc","question":"Paying efficiency wages helps firms reduce the problem of moral hazard by:","options":["generating additional profits that can be used to improve working conditions.","matching the wages each worker is paid to the number of units of output each worker produces.","encouraging unsupervised workers to maintain a high level of productivity.","providing an incentive for the best-qualified workers to remain with the firm."],"answer":"C","images":null,"translation":{"question":"支付效率工资通过以下方式帮助企业减少道德风险问题：","options":["产生额外的利润，用于改善工作条件。","使每个工人的工资与其产出的单位数量相匹配。","鼓励无人监督的工人保持高水平的生产率。","为最有资格的工人留在企业提供激励。"]},"topics":["wage-rigidity"]},{"num":44,"type":"mc","question":"By paying efficiency wages, firms contribute to higher unemployment because they:","options":["increase the wage bill.","make workers more productive.","keep the wage below the equilibrium level.","keep the wage above the equilibrium level."],"answer":"D","images":null,"translation":{"question":"企业通过支付效率工资促成更高的失业，因为它们：","options":["增加了工资支出。","使工人生产率更高。","使工资低于均衡水平。","使工资高于均衡水平。"]},"topics":["wage-rigidity"]},{"num":45,"type":"mc","question":"Suppose that over the course of a year 100 people are unemployed for 4 weeks each (the short-term unemployed), while 10 people are unemployed for 52 weeks each (the long-term unemployed). Approximately what percentage of the total spells of unemployment were attributable to the long-term unemployed?","options":["9 percent","10 percent","43.5 percent","56.5 percent"],"answer":"A","images":null,"translation":{"question":"假设在一年中，有100人各失业4周（短期失业者），另有10人各失业52周（长期失业者）。总的失业期数中大约有多大比例应归因于长期失业者？","options":["9%","10%","43.5%","56.5%"]},"topics":["job-search"]},{"num":46,"type":"mc","question":"Suppose that over the course of a year 100 people are unemployed for 4 weeks each (the short-term unemployed), while 10 people are unemployed for 52 weeks each (the long-term unemployed). Approximately what percentage of the total weeks of unemployment were attributable to the long-term unemployed?","options":["9 percent","10 percent","43.5 percent","56.5 percent"],"answer":"D","images":null,"translation":{"question":"假设在一年中，有100人各失业4周（短期失业者），另有10人各失业52周（长期失业者）。总的失业周数中大约有多大比例应归因于长期失业者？","options":["9%","10%","43.5%","56.5%"]},"topics":["job-search"]},{"num":47,"type":"mc","question":"Policies to substantially reduce the natural rate of unemployment should be targeted at:","options":["the short-term unemployed.","the long-term unemployed.","discouraged workers.","insiders and outsiders."],"answer":"B","images":null,"translation":{"question":"旨在大幅降低自然失业率的政策应针对：","options":["短期失业者。","长期失业者。","沮丧的工人。","内部人和外部人。"]},"topics":["natural-rate"]},{"num":48,"type":"mc","question":"Short-term unemployment is most likely to be ______ unemployment, while long-term unemployment is mostly likely to be _____ unemployment.","options":["structural; frictional","structural; the natural rate of","the natural rate of; frictional","frictional; structural"],"answer":"D","images":null,"translation":{"question":"短期失业最可能是 ______ 失业，而长期失业最可能是 ______ 失业。","options":["结构性；摩擦性","结构性；自然","自然；摩擦性","摩擦性；结构性"]},"topics":["job-search","wage-rigidity"]},{"num":49,"type":"mc","question":"Most spells of unemployment are ______ term, and most weeks of unemployment are attributable to ______-term unemployment.","options":["short; short","short; long","long; long","long; short"],"answer":"B","images":null,"translation":{"question":"大多数失业期是 ______ 期的，而大多数失业周数应归因于 ______ 期失业。","options":["短；短","短；长","长；长","长；短"]},"topics":["job-search"]},{"num":50,"type":"mc","question":"Data on unemployment in the United States show that:","options":["most spells of unemployment are long.","most weeks of unemployment are attributable to the long-term unemployed.","members of the labor force over age 55 have the highest unemployment rates.","the duration of unemployment falls during recessions."],"answer":"B","images":null,"translation":{"question":"美国的失业数据表明：","options":["大多数失业期是长期的。","大多数失业周数应归因于长期失业者。","55岁以上劳动力的失业率最高。","失业持续时间在衰退期间下降。"]},"topics":["job-search"]},{"num":51,"type":"mc","question":"Which of the following characteristics made the 2008–2009 recession differ most sharply from previous recessions?","options":["a large spike in the duration of unemployment","a large increase in teenage unemployment","higher rates of female unemployment than rates of male unemployment","an increase in the rate of job separation and a decrease in the rate of job finding"],"answer":"A","images":null,"translation":{"question":"以下哪项特征使2008–2009年衰退与以往衰退最显著地不同？","options":["失业持续时间大幅飙升。","青少年失业大幅增加。","女性失业率高于男性失业率。","离职率上升、就职率下降。"]},"topics":["job-search"]},{"num":52,"type":"mc","question":"Differences in unemployment rates across demographic groups are most closely correlated with differences in:","options":["job-finding rates.","job-separation rates.","unionization rates.","efficiency wage rates."],"answer":"B","images":null,"translation":{"question":"各人口群体之间失业率的差异与以下哪方面的差异最密切相关：","options":["就职率。","离职率。","工会化率。","效率工资率。"]},"topics":["natural-rate"]},{"num":53,"type":"mc","question":"Entry into and exit from the labor force are important to the determination of the unemployment rate because:","options":["more than one-half of the unemployed have only recently entered the labor force.","most of the unemployed are young workers still looking for their first job.","discouraged workers are counted as part of the labor force.","almost one-half of all spells of unemployment end in the unemployed person's withdrawal from the labor market."],"answer":"D","images":null,"translation":{"question":"劳动力进入和退出对失业率的确定很重要，因为：","options":["超过一半的失业者只是最近才进入劳动力。","大多数失业者是仍在寻找第一份工作的年轻工人。","沮丧的工人被计入劳动力。","几乎一半的失业期以失业者退出劳动力市场而告终。"]},"topics":["job-search"]},{"num":54,"type":"mc","question":"Spells of unemployment end when the unemployed person finds a job or:","options":["withdraws from the labor force.","enters the labor force.","runs out of unemployment insurance compensation.","refuses to answer unemployment survey questions."],"answer":"A","images":null,"translation":{"question":"当失业者找到工作或 ______ 时，失业期就结束了：","options":["退出劳动力。","进入劳动力。","失业保险补偿金用完。","拒绝回答失业调查问题。"]},"topics":["job-search"]},{"num":55,"type":"mc","question":"Transitions into and out of the labor force:","options":["rarely occur.","do not affect unemployment statistics.","make the interpretation of unemployment statistics complicated.","reduce the amount of frictional unemployment."],"answer":"C","images":null,"translation":{"question":"进入和退出劳动力的转换：","options":["很少发生。","不影响失业统计。","使失业统计的解释变得复杂。","减少摩擦性失业量。"]},"topics":["job-search"]},{"num":56,"type":"mc","question":"Discouraged workers are counted as:","options":["part of the labor force.","out of the labor force.","employed.","unemployed."],"answer":"B","images":null,"translation":{"question":"沮丧的工人被计入：","options":["劳动力的一部分。","劳动力之外。","就业者。","失业者。"]},"topics":["job-search"]},{"num":57,"type":"mc","question":"Discouraged workers are individuals who:","options":["have jobs that do not match their skills (e.g., a Ph.D. driving a taxi cab).","have been unemployed for more than 26 weeks.","call themselves unemployed but are not seriously looking for a job.","want a job but have given up looking for one."],"answer":"D","images":null,"translation":{"question":"沮丧的工人是指：","options":["拥有与自身技能不匹配的工作的人（例如开出租车的博士）。","失业超过26周的人。","自称失业但并没有认真寻找工作的人。","想要工作但已放弃寻找的人。"]},"topics":["job-search"]},{"num":58,"type":"mc","question":"As the relative demand for unskilled workers falls, wages for unskilled workers ______, and unemployment compensation becomes a ______ attractive option.","options":["fall; more","fall; less","rise; more","rise; less"],"answer":"A","images":null,"translation":{"question":"随着对非熟练工人的相对需求下降，非熟练工人的工资 ______，而失业补偿成为一个 ______ 有吸引力的选择。","options":["下降；更","下降；不那么","上升；更","上升；不那么"]},"topics":["wage-rigidity"]},{"num":59,"type":"mc","question":"Much of the difference in unemployment rates across Europe is attributable to differences in:","options":["short-term unemployment.","long-term unemployment.","frictional unemployment.","the natural rate of unemployment."],"answer":"B","images":null,"translation":{"question":"欧洲各国失业率的差异在很大程度上归因于以下方面的差异：","options":["短期失业。","长期失业。","摩擦性失业。","自然失业率。"]},"topics":["wage-rigidity"]},{"num":60,"type":"mc","question":"Which of the following statements most closely describes the variation in unemployment rates across countries in Europe?","options":["Countries with higher rates of unionization tend to have higher unemployment rates, but this is partially mitigated if wage negotiations are coordinated among employers.","Countries with higher rates of unionization tend to have higher unemployment rates, and this tendency is exacerbated if wage negotiations are coordinated among employers.","Countries with more generous unemployment insurance benefits tend to have higher unemployment rates, but this is partially mitigated if the benefits are offered for a longer period of time.","Countries with more generous unemployment insurance tend to have lower unemployment rates, but this effect is completely offset if benefits are offered for a longer period of time."],"answer":"A","images":null,"translation":{"question":"以下哪项陈述最贴切地描述了欧洲各国失业率的差异？","options":["工会化率较高的国家往往失业率较高，但如果工资谈判在雇主之间协调进行，这种影响会被部分抵消。","工会化率较高的国家往往失业率较高，如果工资谈判在雇主之间协调进行，这种趋势会被加剧。","失业保险金更慷慨的国家往往失业率较高，但如果保险金支付期限更长，这种影响会被部分抵消。","失业保险更慷慨的国家往往失业率较低，但如果保险金支付期限更长，这种影响会被完全抵消。"]},"topics":["wage-rigidity"]},{"num":61,"type":"mc","question":"Across countries of Europe, greater spending on unemployment insurance tends to _____ unemployment, and more “active” labor-market policies tend to _____ unemployment.","options":["increase; increase","increase; decrease","decrease; decrease","decrease; increase"],"answer":"B","images":null,"translation":{"question":"在欧洲各国，失业保险支出的增加往往会 _____ 失业，而更多“积极”的劳动力市场政策往往会 _____ 失业。","options":["增加；增加","增加；减少","减少；减少","减少；增加"]},"topics":["job-search"]},{"num":62,"type":"mc","question":"Examples of “active” labor-market policies include all of the following except:","options":["job-search assistance","subsidized employment","unemployment insurance","job-training programs"],"answer":"C","images":null,"translation":{"question":"“积极”劳动力市场政策的例子包括以下所有，除了：","options":["求职援助","补贴性就业","失业保险","职业培训计划"]},"topics":["job-search"]},{"num":63,"type":"mc","question":"The generosity of unemployment insurance benefits is measured by:","options":["the replacement rate and the duration of benefits.","the median wage and the unemployment rate.","the price level and duration of unemployment.","the job-finding rate and the job-separation rate."],"answer":"A","images":null,"translation":{"question":"失业保险金的慷慨程度由以下指标衡量：","options":["替代率和保险金支付期限。","工资中位数和失业率。","物价水平和失业持续时间。","就职率和离职率。"]},"topics":["job-search"]},{"num":64,"type":"mc","question":"Earlier retirement in Europe than in the United States contributes to:","options":["higher employment-to-population ratios in Europe than in the United States.","lower employment-to-population ratios in Europe than in the United States.","more hours worked per year by the average employed person in Europe than the average employed person in the United States.","fewer hours worked per year by the average employed person in Europe than the average employed person in the United States."],"answer":"B","images":null,"translation":{"question":"欧洲比美国更早退休，这会导致：","options":["欧洲的就业人口比高于美国。","欧洲的就业人口比低于美国。","欧洲平均就业者每年工作时间多于美国平均就业者。","欧洲平均就业者每年工作时间少于美国平均就业者。"]},"topics":["natural-rate"]},{"num":65,"type":"mc","question":"More frequent holidays for workers in Europe than in the United States contribute to:","options":["higher employment-to-population ratios in Europe than in the United States.","lower employment-to-population ratios in Europe than in the United States.","more hours worked per year by the average employed person in Europe than the average employed person in the United States.","fewer hours worked per year by the average employed person in Europe than the average employed person in the United States."],"answer":"D","images":null,"translation":{"question":"欧洲工人比美国工人假期更频繁，这会导致：","options":["欧洲的就业人口比高于美国。","欧洲的就业人口比低于美国。","欧洲平均就业者每年工作时间多于美国平均就业者。","欧洲平均就业者每年工作时间少于美国平均就业者。"]},"topics":["natural-rate"]},{"num":66,"type":"mc","question":"Which of the following hypotheses is consistent with fewer hours worked per year in Europe than in the United States?","options":["fewer mandated holidays in Europe than in the United States","higher employment-to-population ratios in Europe than in the United States","higher tax rates in Europe than in the United States","a smaller underground economy in Europe than in the United States"],"answer":"C","images":null,"translation":{"question":"以下哪项假设与欧洲每年工作时间少于美国相一致？","options":["欧洲的法定假期少于美国。","欧洲的就业人口比高于美国。","欧洲的税率高于美国。","欧洲的地下经济小于美国。"]},"topics":["natural-rate"]},{"num":67,"type":"mc","question":"If the underground economy is larger in Europe than in the United States, then the difference in the _____ number of hours worked between Europe and the United States may be smaller than the difference in the _____ numbers of hours worked.","options":["measured; actual","actual; measured","annual; monthly","monthly; annual"],"answer":"B","images":null,"translation":{"question":"如果欧洲的地下经济大于美国，那么欧洲与美国之间 ______ 工作小时数的差异可能小于 ______ 工作小时数的差异。","options":["已计量的；实际的","实际的；已计量的","年度的；月度的","月度的；年度的"]},"topics":["natural-rate"]},{"num":68,"type":"mc","question":"According to Olivier Blanchard, Europeans are more likely to use increases in real wages resulting from technological progress to increase ______, and Americans are more likely to use these increases in real wages to increase ______.","options":["hours of work; hours of leisure","consumption of goods and services; hours of leisure","hours of leisure; consumption of goods and services","unemployment insurance benefits; efficiency wages"],"answer":"C","images":null,"translation":{"question":"根据奥利维尔·布兰查德的观点，欧洲人更可能利用技术进步带来的实际工资增加来增加 ______，而美国人更可能利用这些实际工资的增加来增加 ______。","options":["工作时间；闲暇时间","商品和服务的消费；闲暇时间","闲暇时间；商品和服务的消费","失业保险金；效率工资"]},"topics":["natural-rate"]},{"num":69,"type":"mc","question":"If the rate of separation is 0.02 and the rate of job finding is 0.08 but the current unemployment rate is 0.10, then the current unemployment rate is ______ the equilibrium rate, and in the next period it will move ______ the equilibrium rate.","options":["above; toward","above; away from","below; toward","below; away from"],"answer":"C","images":null,"translation":{"question":"如果离职率为0.02、就职率为0.08，但当前失业率为0.10，那么当前失业率 ______ 均衡失业率，在下一期它将向 ______ 均衡失业率的方向变动。","options":["高于；接近","高于；远离","低于；接近","低于；远离"]},"topics":["natural-rate"]},{"num":70,"type":"mc","question":"Assume that a country experiences a reduction in productivity that lowers the marginal product of labor for any given level of labor. In this case, the:","options":["labor supply curve shifts to the right.","labor supply curve shifts to the left.","labor demand curve shifts upward and to the right.","labor demand curve shifts downward and to the left."],"answer":"D","images":null,"translation":{"question":"假设一个国家经历了生产率下降，使任何给定劳动水平下劳动的边际产品都降低。在这种情况下：","options":["劳动供给曲线向右移动。","劳动供给曲线向左移动。","劳动需求曲线向上并向右移动。","劳动需求曲线向下并向左移动。"]},"topics":["wage-rigidity"]},{"num":71,"type":"mc","question":"Assume that a country experiences a reduction in productivity that shifts the labor demand curve downward and to the left. If the labor market were always in equilibrium, this would lead to:","options":["a lower real wage and a rise in unemployment.","a lower real wage and no change in unemployment.","a lower real wage and less unemployment.","no change in real wage or in unemployment."],"answer":"B","images":null,"translation":{"question":"假设一个国家经历了生产率下降，使劳动需求曲线向下并向左移动。如果劳动力市场始终处于均衡，这将导致：","options":["实际工资下降、失业上升。","实际工资下降、失业不变。","实际工资下降、失业减少。","实际工资和失业都不变。"]},"topics":["wage-rigidity"]},{"num":72,"type":"mc","question":"Assume that a country experiences a reduction in productivity that shifts the labor demand curve downward and to the left. If the real wage were rigid, this would lead to:","options":["no change in the real wage and a rise in unemployment.","no change in the real wage and no change in unemployment.","no change in the real wage and a fall in unemployment.","a decrease in the real wage."],"answer":"A","images":null,"translation":{"question":"假设一个国家经历了生产率下降，使劳动需求曲线向下并向左移动。如果实际工资是刚性的，这将导致：","options":["实际工资不变、失业上升。","实际工资不变、失业不变。","实际工资不变、失业下降。","实际工资下降。"]},"topics":["wage-rigidity"]},{"num":73,"type":"sa","question":"If the rate of job separation is 0.02 per month and the rate of job finding is 0.10 per month, what is the natural rate of unemployment?","options":null,"answer":null,"images":null,"translation":{"question":"如果离职率为每月0.02、就职率为每月0.10，自然失业率是多少？","options":null},"topics":["natural-rate"],"answer_ref":"自然失业率 U = s/(s+f) = 0.02/(0.02+0.10) = 0.02/0.12 ≈ 16.7%。"},{"num":74,"type":"sa","question":"If the economy were at a steady-state unemployment rate with a separation rate of 0.02 per month and a job-finding rate of 0.10 per month, and the labor force were 100 million, how many individuals would lose their jobs each month?","options":null,"answer":null,"images":null,"translation":{"question":"如果经济处于稳态失业率，离职率为每月0.02、就职率为每月0.10，劳动力为1亿，那么每月有多少人失去工作？","options":null},"topics":["natural-rate"],"answer_ref":"稳态失业率 16.7%，失业人数 1,667万，就业 8,333万。每月失去工作的人数 = s×E = 0.02×8,333万 ≈ 167万人（也等于 f×U = 0.10×1,667万，稳态下流入流出相等）。"},{"num":75,"type":"sa","question":"Assume that a society consists of two types of workers, A and B. For type A, 3 million workers lose their jobs each year, and each one takes a year to find a new one. For type B, 36 million workers lose their jobs each year (3 million per month), and each takes one month to find a new job. Thus, at any given time, 6 million are unemployed in this economy. a. How many “spells” of unemployment occur each year in this economy? b. What percentage of the “spells” are only one month long? c. If you take all the workers unemployed each year and multiply each by the length of his or her unemployment “spell,” how many “months” of unemployment would there be in this economy each year? d. Of all the “months” of unemployment, how many are accounted for by the workers unemployed a year at a time?","options":null,"answer":null,"images":null,"translation":{"question":"假设一个社会由A、B两类工人组成。对于A类，每年有300万工人失去工作，每个人要花一年时间找到新工作。对于B类，每年有3600万工人失去工作（每月300万），每个人要花一个月找到新工作。因此，在任何时刻，这个经济中都有600万人失业。a. 这个经济中每年发生多少次失业“期”？b. 这些“期”中有多大比例只有一个月长？c. 如果取每年所有失业的工人，并将每个人乘以其失业“期”的长度，那么每年这个经济中有多少“个月”的失业？d. 在所有失业“月份”中，有多少是由一次失业一年的工人造成的？","options":null},"topics":["job-search"],"answer_ref":"a. 失业 spells 总数 = 3百万（A类）+ 36百万（B类）= 39百万次/年。b. 平均失业时长 = 总失业月数/spells = (3百万×12 + 36百万×1)/39百万 = 72/39 ≈ 1.85 个月。说明：失业总量相同（600万）的经济体，失业体验可完全不同——A类是少数人长期失业，B类是多数人短期周转。"},{"num":76,"type":"sa","question":"Changes in economic policies will frequently have an impact on the unemployment rate. Explain whether each of the policy changes described is likely to (1) affect frictional or structural unemployment and (2) increase or decrease the measured unemployment rate. a. The government reduces the number of weeks of unemployment insurance that unemployed workers can receive. b. The government raises the minimum wage. c. The government increases spending on job-training programs.","options":null,"answer":null,"images":null,"translation":{"question":"经济政策的变化常常会对失业率产生影响。说明以下每项政策变化可能(1)影响摩擦性失业还是结构性失业，以及(2)提高还是降低所计量的失业率。a. 政府减少失业工人可领取失业保险的周数。b. 政府提高最低工资。c. 政府增加对职业培训计划的支出。","options":null},"topics":["job-search","wage-rigidity"],"answer_ref":"a. 缩短失业保险领取周数：(1) 主要影响摩擦性失业——降低求职的保险垫，缩短搜索时间；(2) 测得的失业率下降。b. 提高最低工资：(1) 影响结构性失业——工资被推到低技能工人市场出清水平之上；(2) 测得的失业率上升（低技能工人被排挤出就业）。"},{"num":77,"type":"sa","question":"The average unemployment rate in western Europe is higher than in the United States. a. Explain one difference between the European and U.S. economies that is consistent with more structural unemployment in Europe. b. Explain one difference between the European and U.S. economies that is consistent with more frictional unemployment in Europe.","options":null,"answer":null,"images":null,"translation":{"question":"西欧的平均失业率高于美国。a. 说明欧洲经济与美国经济的一个差异，该差异与欧洲存在更多结构性失业相一致。b. 说明欧洲经济与美国经济的一个差异，该差异与欧洲存在更多摩擦性失业相一致。","options":null},"topics":["wage-rigidity","job-search"],"answer_ref":"a. 结构性失业更多的解释：欧洲更高的最低工资、更强的工会力量和更慷慨的福利，使实际工资常高于市场出清水平，降低了企业创造岗位的意愿，失业更持久。b. 摩擦性失业更多的解释：欧洲失业保险更慷慨、领取时间更长，失业者搜索期更长，摩擦性失业因此更高。"},{"num":78,"type":"sa","question":"Assume that the real wage in an economy is held above equilibrium. a. Graphically illustrate how an increase in technology that raises the demand for labor will change the number of unemployed workers. Be sure to label the axes and the quantities of labor hired before and after the technological progress. b. Explain in words what happens to the number of unemployed as a result of this change.","options":null,"answer":null,"images":null,"translation":{"question":"假设一个经济中的实际工资被维持在均衡水平之上。a. 用图形说明提高劳动需求的技术进步将如何改变失业工人数量。务必标注坐标轴以及技术进步前后雇佣的劳动数量。b. 用文字说明由于这一变化，失业人数会发生什么变化。","options":null},"topics":["wage-rigidity"],"answer_ref":"a. 图：实际工资 W 固定在均衡之上，劳动需求曲线右移（技术进步）。雇佣量由 L₁ 增至 L₂，而工资刚性下劳动供给量 Ls 不变，失业 = Ls − 雇佣量。b. 失业人数减少：工资虽不能下降，但需求增加使企业雇用更多在岗工人，部分原来的失业者被吸纳。"},{"num":79,"type":"sa","question":"Assume that the real wage in an economy is held above equilibrium. a. Graphically illustrate how an increase in the supply of labor will change the number of unemployed workers. Be sure to label the axes and the quantities of labor hired before and after the increase in the labor supply. b. Explain in words what happens to the number of unemployed as a result of this change.","options":null,"answer":null,"images":null,"translation":{"question":"假设一个经济中的实际工资被维持在均衡水平之上。a. 用图形说明劳动供给的增加将如何改变失业工人数量。务必标注坐标轴以及劳动供给增加前后雇佣的劳动数量。b. 用文字说明由于这一变化，失业人数会发生什么变化。","options":null},"topics":["wage-rigidity"],"answer_ref":"a. 图：实际工资 W 固定在均衡之上，劳动供给曲线右移。该工资下愿意工作的人从 Ls₁ 增至 Ls₂，而企业雇佣量不变（L₁），失业 = Ls − L₁ 扩大。b. 失业人数增加：工资不能下降以出清市场，新增劳动者全部落入失业。"},{"num":80,"type":"sa","question":"Reducing the natural rate of unemployment requires reducing the rate of job separation and increasing the rate of job finding. Explain at least one policy that will impact each of these aspects of the natural rate of unemployment.","options":null,"answer":null,"images":null,"translation":{"question":"降低自然失业率需要降低离职率并提高就职率。至少说明一项会影响自然失业率这两个方面的政策。","options":null},"topics":["natural-rate"],"answer_ref":"降低离职率：如就业保护立法、短时工作补贴或雇用税收优惠，鼓励企业在需求波动时保留工人而非裁员。提高就职率：如公立就业介绍机构、求职辅导、再培训计划，帮助失业者更快找到匹配的工作。"},{"num":81,"type":"sa","question":"Consider two countries: Flexiland and Stuckland. The labor force in each country consists of 100,000 workers. In Flexiland a different 500 workers are unemployed each month. In Stuckland the same 500 workers are unemployed for the entire year. Compare and contrast the unemployment situation in the two countries by explaining: a. the unemployment rate. b. the number of spells of unemployment. c. the average duration of each unemployment spell. d. whether the unemployment is more likely to be frictional or structural.","options":null,"answer":null,"images":null,"translation":{"question":"考虑两个国家：灵活国和僵化国。每个国家的劳动力都由100,000名工人组成。在灵活国，每个月有500名不同的工人失业。在僵化国，同样的500名工人全年都失业。通过说明以下各项来比较和对比这两个国家的失业状况：a. 失业率。b. 失业期的数量。c. 每个失业期的平均持续时间。d. 失业更可能是摩擦性的还是结构性的。","options":null},"topics":["job-search"],"answer_ref":"a. 失业率相同：两国都是 500/100,000 = 0.5%。b. Spells：Flexiland 每月换一批人失业，全年 12×500 = 6,000 次；Stuckland 是同一批人持续失业，共 500 次（每人一次）。c. 平均失业时长：Flexiland 1 个月（高流动）；Stuckland 12 个月（长期失业）。失业率相同，但 Flexiland 的失业是短暂的周转，Stuckland 是少数人陷入长期失业，社会问题更严重。"},{"num":82,"type":"sa","question":"What type of wage rigidity is most likely to affect the unemployment rates of the following types of workers: a. workers with low marginal labor productivity? b. workers in the auto industry? c. workers engaged in creative work that is not easily monitored?","options":null,"answer":null,"images":null,"translation":{"question":"哪种类型的工资刚性最可能影响以下各类工人的失业率：a. 劳动边际生产率低的工人？b. 汽车行业的工人？c. 从事不易监督的创造性工作的工人？","options":null},"topics":["wage-rigidity"],"answer_ref":"a. 最低工资型工资刚性：低边际劳动生产率的工人最容易被法定最低工资定在均衡之上。b. 工会工资刚性：汽车业工会力量强，集体协议工资常高于市场出清水平。c. 效率工资：创造性工作难以监督，雇主主动支付高于市场的工资以激励努力，减少偷懒。"},{"num":83,"type":"sa","question":"Explain how paying efficiency wages can help employers overcome both moral hazard and adverse selection problems in employment.","options":null,"answer":null,"images":null,"translation":{"question":"解释支付效率工资如何帮助雇主克服就业中的道德风险和逆向选择问题。","options":null},"topics":["wage-rigidity"],"answer_ref":"道德风险（雇后偷懒难监督）：效率工资使被解雇的成本变高——失去一份高于市场工资的工作损失很大，工人因此自觉付出努力。逆向选择（雇前信息不对称）：高工资吸引更高素质的求职者（能力强的更愿意来应聘），同时降低优秀员工的离职率，改善雇员队伍的平均水平。高工资同时解决激励问题和选人问题。"},{"num":84,"type":"sa","question":"Explain how technological changes that have reduced the demand for low-skilled workers can change the natural rate of unemployment in the presence of rigid wages for this group.","options":null,"answer":null,"images":null,"translation":{"question":"解释在低技能工人工资刚性的情况下，减少低技能工人需求的技术变革如何改变自然失业率。","options":null},"topics":["wage-rigidity"],"answer_ref":"技术变革减少对低技能劳动的需求，而其工资因最低工资/制度刚性不能下降→该群体劳动市场出现供给过剩→结构性失业上升→自然失业率提高。"},{"num":85,"type":"sa","question":"In an economy, if 5 percent of the employed lose their job every month (s = 0.05) and 15 percent of the unemployed find a job every month (f = 0.15), what is the steady rate of unemployment of the economy?","options":null,"answer":null,"images":null,"translation":{"question":"在一个经济中，如果每月有5%的就业者失去工作（s = 0.05）、15%的失业者找到工作（f = 0.15），该经济的稳态失业率是多少？","options":null},"topics":["natural-rate"],"answer_ref":"稳态失业率 U = s/(s+f) = 0.05/(0.05+0.15) = 0.05/0.20 = 25%。"},{"num":86,"type":"sa","question":"When an economy enters expansion, the unemployment rate first increases and then decreases. Why does this happen?","options":null,"answer":null,"images":null,"translation":{"question":"当经济进入扩张期时，失业率先上升后下降。为什么会这样？","options":null},"topics":["job-search"],"answer_ref":"这是\"丧失信心工人效应\"的反向：经济复苏初期，就业前景改善使原本放弃求职的丧失信心工人重新进入劳动力队伍并开始找工作——他们在找到工作前先被计入失业，失业率反而上升；随后这些求职者陆续就业，且新增就业超过劳动力流入，失业率才掉头下降。"},{"num":87,"type":"sa","question":"If a country has a higher unionization rate, will that lead to a higher unemployment rate also?","options":null,"answer":null,"images":null,"translation":{"question":"如果一个国家的工会化率更高，是否也会导致更高的失业率？","options":null},"topics":["wage-rigidity"],"answer_ref":"没有自动的必然联系，但通常倾向如此：工会化提高内部人工资，可能把工资推到市场出清水平之上，减少低技能/非工会岗位，从而提高结构性失业率。不过影响取决于谈判结构、覆盖面以及工会是否通过降低离职率、提高培训来提高生产率——集中化谈判体系下甚至可能压低工资、降低失业率。经验研究多数发现工会化程度与失业率存在温和正相关。"},{"num":88,"type":"sa","question":"If 250 workers are unemployed for a period of 1 month, 150 for a period of 6 months, and 100 for a period of 12 months in a given year, how many spells and months of unemployment occur during a year?","options":null,"answer":null,"images":null,"translation":{"question":"如果在某一年中，有250名工人失业1个月，150名工人失业6个月，100名工人失业12个月，那么一年中发生多少次失业期和多少个月的失业？","options":null},"topics":["job-search"],"answer_ref":"Spells = 250 + 150 + 100 = 500 次（每个工人一段连续失业算一次）。失业总月数 = 250×1 + 150×6 + 100×12 = 250 + 900 + 1200 = 2,350 个月。平均失业时长 = 2,350/500 = 4.7 个月。"},{"num":89,"type":"sa","question":"The unemployment rate can be reduced by decreasing the rate of job separation and increasing the rate of job finding. What measures can government take to help control these rates? Give one example for each.","options":null,"answer":null,"images":null,"translation":{"question":"通过降低离职率、提高就职率可以降低失业率。政府可以采取哪些措施来帮助控制这些比率？各举一个例子。","options":null},"topics":["natural-rate"],"answer_ref":"控制离职率：例如对保留岗位的企业给予补贴（短时工作计划、雇用税收抵免），减少裁员。控制就职率：例如建立公立就业服务机构、提供求职辅导和再培训，提高失业者与岗位的匹配速度。"},{"num":90,"type":"sa","question":"Since 1960 there has been a substantial increase in unemployment rates in major European countries. Give two reasons for this happening in Europe.","options":null,"answer":null,"images":null,"translation":{"question":"自1960年以来，欧洲主要国家的失业率大幅上升。给出欧洲发生这种情况的两个原因。","options":null},"topics":["job-search","wage-rigidity"],"answer_ref":"① 失业救济更慷慨：替代率高、领取期限长（有的无限期），降低了找工作的紧迫性，摩擦性失业上升；② 劳动力市场制度刚性：高额最低工资、对在职者的强就业保护（企业不敢雇人）、集中化工资谈判把工资定在出清水平之上——共同造成持久的结构性失业。"},{"num":91,"type":"sa","question":"A country has changed its labor laws and decreased the minimum age of working from 18 years to 16 years. What is the effect of this change on equilibrium wages?","options":null,"answer":null,"images":null,"translation":{"question":"一个国家修改了劳动法，将最低工作年龄从18岁降低到16岁。这一变化对均衡工资有什么影响？","options":null},"topics":["wage-rigidity"],"answer_ref":"劳动供给增加（可工作人口扩大）→ 在劳动需求不变时，均衡工资下降。"},{"num":92,"type":"sa","question":"It is said that some frictional unemployment is inevitable. What is the reason that some frictional unemployment is inevitable?","options":null,"answer":null,"images":null,"translation":{"question":"有人说，一些摩擦性失业是不可避免的。为什么一些摩擦性失业是不可避免的？","options":null},"topics":["job-search"],"answer_ref":"因为经济永远在变动：行业兴衰带来部门转移（sectoral shifts），工人技能与偏好各异，岗位信息不完全，地域与职业间的匹配需要时间。工作变动与匹配不可能瞬时完成，所以动态经济中总有部分人处于\"在找工作\"的状态——摩擦性失业不可避免，甚至在相当程度上是健康经济的表现。"},{"num":93,"type":"sa","question":"What is active labor market policy? Give some examples of active labor market policies that help in reducing the unemployment rates.","options":null,"answer":null,"images":null,"translation":{"question":"什么是积极劳动力市场政策？举一些有助于降低失业率的积极劳动力市场政策的例子。","options":null},"topics":["job-search"],"answer_ref":"积极的劳动力市场政策是指政府不只发救济金，而是主动帮助失业者重返岗位的干预。例子：求职辅导与就业咨询、公立职业介绍所、再培训/技能提升项目、学徒制与就业补贴、以工代赈的公共就业岗位。这些措施通过提高就职率和改善匹配质量来降低失业率。"}]},{"num":8,"title":"Economic Growth I","questions":[{"num":1,"type":"mc","question":"The Solow growth model describes:","options":["how output is determined at a fixed point in time.","how output is determined with fixed amounts of capital and labor.","how saving, population growth, and technological change affect output over time.","the static allocation, production, and distribution of the economy's output."],"answer":"C","images":null,"translation":{"question":"索洛增长模型描述的是：","options":["产出如何在某一固定时点被决定。","在资本和劳动量固定时产出如何被决定。","储蓄、人口增长和技术进步如何影响产出随时间的变化。","经济产出的静态配置、生产和分配。"]},"topics":["solow-model"]},{"num":2,"type":"mc","question":"In the Solow growth model, the assumption of constant returns to scale means that:","options":["all economies have the same amount of capital per worker.","the steady-state level of output is constant, regardless of the number of workers.","the saving rate equals the constant rate of depreciation.","the number of workers in an economy does not affect the relationship between output per worker and capital per worker."],"answer":"D","images":null,"translation":{"question":"在索洛增长模型中，规模报酬不变假设意味着：","options":["所有经济都有相同的人均资本量。","无论工人数量多少，稳态产出水平都是恒定的。","储蓄率等于不变的折旧率。","经济中工人的数量不会影响人均产出与人均资本之间的关系。"]},"topics":["solow-model"]},{"num":3,"type":"mc","question":"The production function y = f (k) means:","options":["labor is not a factor of production.","output per worker is a function of labor productivity.","output per worker is a function of capital per worker.","the production function exhibits increasing returns to scale."],"answer":"C","images":null,"translation":{"question":"生产函数 y = f(k) 意味着：","options":["劳动不是生产要素。","人均产出是劳动生产率的函数。","人均产出是人均资本的函数。","该生产函数呈现规模报酬递增。"]},"topics":["solow-model"]},{"num":4,"type":"mc","question":"When f (k) is drawn on a graph with increases in k noted along the horizontal axis, the slope of the curve denotes:","options":["output per worker.","output per unit of capital.","the marginal product of labor.","the marginal product of capital."],"answer":"D","images":null,"translation":{"question":"当 f(k) 画在图上、横轴表示 k 的增加时，曲线的斜率表示：","options":["人均产出。","每单位资本的产出。","劳动的边际产量。","资本的边际产量。"]},"topics":["solow-model"]},{"num":5,"type":"mc","question":"Two economies are identical except that the level of capital per worker is higher in Highland than in Lowland. The production functions in both economies exhibit diminishing marginal product of capital. An extra unit of capital per worker increases output per worker:","options":["more in Highland.","more in Lowland.","by the same amount in Highland and Lowland.","in Highland but not in Lowland."],"answer":"B","images":null,"translation":{"question":"两个经济完全相同，只是高地（Highland）的人均资本水平高于低地（Lowland）。两个经济的生产函数都呈现资本边际产量递减。额外一单位的人均资本使人均产出增加：","options":["高地增加得更多。","低地增加得更多。","高地与低地增加相同数量。","高地会增加，而低地不会增加。"]},"topics":["solow-model"]},{"num":6,"type":"mc","question":"The consumption function in the Solow model assumes that society saves a:","options":["constant proportion of income.","smaller proportion of income as it becomes richer.","larger proportion of income as it becomes richer.","larger proportion of income when the interest rate is higher."],"answer":"A","images":null,"translation":{"question":"索洛模型中的消费函数假设社会储蓄：","options":["收入的一个固定比例。","随着变富，收入中储蓄的比例变小。","随着变富，收入中储蓄的比例变大。","当利率更高时，收入中储蓄的比例更大。"]},"topics":["solow-model"]},{"num":7,"type":"mc","question":"In the Solow growth model the demand for goods equals investment:","options":["minus depreciation.","plus saving.","plus consumption.","plus depreciation."],"answer":"C","images":null,"translation":{"question":"在索洛增长模型中，对商品的需求等于投资：","options":["减去折旧。","加上储蓄。","加上消费。","加上折旧。"]},"topics":["solow-model"]},{"num":8,"type":"mc","question":"In the Solow growth model, where s is the saving rate, y is output per worker, and i is investment per worker, consumption per worker (c) equals:","options":["sy","(1 – s) y","(1 + s) y","(1 – s) y – i"],"answer":"B","images":null,"translation":{"question":"在索洛增长模型中，设 s 为储蓄率、y 为人均产出、i 为人均投资，则人均消费 (c) 等于：","options":["sy","(1 – s)y","(1 + s)y","(1 – s)y – i"]},"topics":["solow-model"]},{"num":9,"type":"mc","question":"In the Solow growth model, investment equals:","options":["output.","consumption.","the marginal product of capital.","saving."],"answer":"D","images":null,"translation":{"question":"在索洛增长模型中，投资等于：","options":["产出。","消费。","资本的边际产量。","储蓄。"]},"topics":["solow-model"]},{"num":10,"type":"mc","question":"In the Solow growth model, for any given capital stock, the ______ determines how much output the economy produces, and the ______ determines the allocation of output between consumption and investment.","options":["saving rate; production function","depreciation rate; population growth rate","production function; saving rate","population growth rate; saving rate"],"answer":"C","images":null,"translation":{"question":"在索洛增长模型中，对于任何给定的资本存量，______ 决定经济生产多少产出，______ 决定产出在消费与投资之间的配置。","options":["储蓄率；生产函数","折旧率；人口增长率","生产函数；储蓄率","人口增长率；储蓄率"]},"topics":["solow-model"]},{"num":11,"type":"mc","question":"______ cause(s) the capital stock to rise, while ______ cause(s) the capital stock to fall.","options":["Inflation; deflation","Interest rates; the discount rate","Investment; depreciation","International trade; depressions"],"answer":"C","images":null,"translation":{"question":"______ 使资本存量上升，而 ______ 使资本存量下降。","options":["通货膨胀；通货紧缩","利率；贴现率","投资；折旧","国际贸易；萧条"]},"topics":["solow-model"]},{"num":12,"type":"mc","question":"Investment per worker (i) as a function of the saving ratio (s) and output per worker (f (k)) may be expressed as:","options":["s + f (k).","s – f (k).","sf (k).","s / f (k)."],"answer":"C","images":null,"translation":{"question":"人均投资 (i) 作为储蓄率 (s) 和人均产出 (f(k)) 的函数可以表示为：","options":["s + f(k)。","s – f(k)。","sf(k)。","s / f(k)。"]},"topics":["solow-model"]},{"num":13,"type":"mc","question":"Exhibit: Output, Consumption, and Investment In this graph, when the capital stock per worker is OA, AB represents:","options":["investment per worker, and AC represents consumption per worker.","consumption per worker, and AC represents investment per worker.","investment per worker, and BC represents consumption per worker.","consumption per worker, and BC represents investment per worker."],"answer":"C","images":null,"translation":{"question":"图表：产出、消费与投资 在该图中，当人均资本存量为 OA 时，AB 表示：","options":["人均投资，AC 表示人均消费。","人均消费，AC 表示人均投资。","人均投资，BC 表示人均消费。","人均消费，BC 表示人均投资。"]},"topics":["solow-model"]},{"num":14,"type":"mc","question":"If the capital stock equals 200 units in year 1 and the depreciation rate is 5 percent per year, then in year 2, assuming no new or replacement investment, the capital stock would equal _____ units.","options":["210","200","195","190"],"answer":"D","images":["c8_img0.png"],"translation":{"question":"如果第 1 年资本存量等于 200 单位，折旧率为每年 5%，则在第 2 年，假设没有新增或重置投资，资本存量将等于 _____ 单位。","options":["210","200","195","190"]},"topics":["solow-model"]},{"num":15,"type":"mc","question":"In the Solow model, it is assumed that a(n) ______ fraction of capital wears out as the capital–labor ratio increases.","options":["smaller","larger","constant","increasing"],"answer":"C","images":null,"translation":{"question":"在索洛模型中，假设随着资本—劳动比的上升，资本磨损的比例是 ______ 的。","options":["更小","更大","不变","递增"]},"topics":["solow-model"]},{"num":16,"type":"mc","question":"The steady-state level of capital occurs when the change in the capital stock per worker (Dk) equals:","options":["0.","the saving rate.","the depreciation rate.","the population growth rate."],"answer":"A","images":null,"translation":{"question":"当人均资本存量的变化量 (Δk) 等于 ______ 时，达到资本的稳态水平。","options":["0。","储蓄率。","折旧率。","人口增长率。"]},"topics":["solow-model"]},{"num":17,"type":"mc","question":"In the Solow growth model of Chapter 8, the economy ends up with a steady-state level of capital:","options":["only if it starts from a level of capital below the steady-state level.","only if it starts from a level of capital above the steady-state level.","only if it starts from a steady-state level of capital.","regardless of the starting level of capital."],"answer":"D","images":null,"translation":{"question":"在第 8 章的索洛增长模型中，经济最终达到稳态资本水平：","options":["只有当它从低于稳态的资本水平出发时。","只有当它从高于稳态的资本水平出发时。","只有当它从稳态资本水平出发时。","无论起始资本水平如何。"]},"topics":["solow-model"]},{"num":18,"type":"mc","question":"In the Solow growth model, the steady-state occurs when:","options":["capital per worker is constant.","the saving rate equals the depreciation rate.","output per worker equals consumption per worker.","consumption per worker is maximized."],"answer":"A","images":null,"translation":{"question":"在索洛增长模型中，稳态出现在：","options":["人均资本不变时。","储蓄率等于折旧率时。","人均产出等于人均消费时。","人均消费最大化时。"]},"topics":["solow-model"]},{"num":19,"type":"mc","question":"Exhibit: Capital per Worker and the Steady State In this graph, capital–labor ratio k2 is not the steady-state because:","options":["the saving rate is too high.","the investment ratio is too high.","gross investment is greater than depreciation.","depreciation is greater than gross investment."],"answer":"D","images":null,"translation":{"question":"图表：人均资本与稳态 在该图中，资本—劳动比 k2 不是稳态，因为：","options":["储蓄率过高。","投资率过高。","总投资大于折旧。","折旧大于总投资。"]},"topics":["solow-model"]},{"num":20,"type":"mc","question":"Exhibit: Steady-State Capital–Labor Ratio In this graph, the steady-state capital–labor ratio is:","options":["k0.","k1.","k2.","k3."],"answer":"C","images":["c8_img1.png"],"translation":{"question":"图表：稳态资本—劳动比 在该图中，稳态资本—劳动比是：","options":["k0。","k1。","k2。","k3。"]},"topics":["solow-model"]},{"num":21,"type":"mc","question":"Exhibit: The Capital–Labor Ratio In this graph, starting from capital–labor ratio k1, the capital–labor ratio will:","options":["decrease.","remain constant.","increase.","first decrease and then remain constant."],"answer":"C","images":["c8_img2.png"],"translation":{"question":"图表：资本—劳动比 在该图中，从资本—劳动比 k1 出发，资本—劳动比将：","options":["下降。","保持不变。","上升。","先下降然后保持不变。"]},"topics":["solow-model"]},{"num":22,"type":"mc","question":"In the Solow growth model, if investment exceeds depreciation, the capital stock will ______, and output will ______ until the steady state is attained.","options":["increase; increase","increase; decrease","decrease; decrease","decrease; increase"],"answer":"A","images":["c8_img3.png"],"translation":{"question":"在索洛增长模型中，如果投资超过折旧，资本存量将 ______，产出将 ______，直到达到稳态。","options":["增加；增加","增加；减少","减少；减少","减少；增加"]},"topics":["solow-model"]},{"num":23,"type":"mc","question":"If the per-worker production function is given by y = k1/2, the saving rate (s) is 0.2, and the depreciation rate is 0.1, then the steady-state ratio of capital to labor is:","options":["1.","2.","4.","9."],"answer":"C","images":null,"translation":{"question":"如果人均生产函数为 y = k^(1/2)，储蓄率 (s) 为 0.2，折旧率为 0.1，则稳态资本—劳动比为：","options":["1。","2。","4。","9。"]},"topics":["solow-model"]},{"num":24,"type":"mc","question":"If the per-worker production function is given by y = k1/2, the saving ratio is 0.3, and the depreciation rate is 0.1, then the steady-state ratio of capital to labor is:","options":["1.","2.","4.","9."],"answer":"D","images":null,"translation":{"question":"如果人均生产函数为 y = k^(1/2)，储蓄率为 0.3，折旧率为 0.1，则稳态资本—劳动比为：","options":["1。","2。","4。","9。"]},"topics":["solow-model"]},{"num":25,"type":"mc","question":"If a war destroys a large portion of a country's capital stock but the saving rate is unchanged, the Solow model predicts that output will grow and that the new steady state will approach:","options":["a higher level of output per person than before.","the same level of output per person as before.","a lower level of output per person than before.","the Golden Rule level of output per person."],"answer":"B","images":null,"translation":{"question":"如果一场战争摧毁了一个国家的大部分资本存量，但储蓄率不变，索洛模型预测产出将会增长，新的稳态将趋近于：","options":["比以前更高的人均产出水平。","与以前相同的人均产出水平。","比以前更低的人均产出水平。","人均产出的黄金律水平。"]},"topics":["solow-model"]},{"num":26,"type":"mc","question":"If the saving rate increases, the:","options":["economy will grow at a faster rate forever.","capital–labor ratio will increase forever.","economy will grow at a faster rate until a new, higher, steady-state capital–labor ratio is reached.","capital–labor ratio will eventually decline."],"answer":"C","images":null,"translation":{"question":"如果储蓄率上升，则：","options":["经济将永远以更快的速度增长。","资本—劳动比将永远上升。","经济将以更快的速度增长，直到达到一个新的、更高的稳态资本—劳动比。","资本—劳动比最终将下降。"]},"topics":["solow-model"]},{"num":27,"type":"mc","question":"Starting from a steady-state situation, if the saving rate increases, capital per worker will:","options":["increase and continue to increase unabated.","increase until the new steady state is reached.","decrease until the new steady state is reached.","decrease and continue to decrease unabated."],"answer":"B","images":null,"translation":{"question":"从稳态出发，如果储蓄率上升，人均资本将：","options":["增加并持续不断地增加。","增加直到达到新的稳态。","减少直到达到新的稳态。","减少并持续不断地减少。"]},"topics":["solow-model"]},{"num":28,"type":"mc","question":"The Solow model shows that a key determinant of the steady-state ratio of capital to labor is the:","options":["level of output.","labor force.","saving rate.","capital elasticity in the production function."],"answer":"C","images":null,"translation":{"question":"索洛模型表明，稳态资本—劳动比的一个关键决定因素是：","options":["产出水平。","劳动力。","储蓄率。","生产函数中的资本弹性。"]},"topics":["solow-model"]},{"num":29,"type":"mc","question":"A higher saving rate leads to a:","options":["higher rate of economic growth in both the short run and the long run.","higher rate of economic growth only in the long run.","higher rate of economic growth in the short run but a decline in the long run.","larger capital stock and a higher level of output in the long run."],"answer":"D","images":null,"translation":{"question":"更高的储蓄率会导致：","options":["短期和长期都有更高的经济增长率。","仅在长期有更高的经济增长率。","短期经济增长率更高，但长期会下降。","长期更大的资本存量和更高的产出水平。"]},"topics":["solow-model"]},{"num":30,"type":"mc","question":"Assume that two economies are identical in every way except that one has a higher saving rate. According to the Solow growth model, in the steady state the country with the higher saving rate will have ______ level of output per person and ______ rate of growth of output per worker compared to the country with the lower saving rate.","options":["the same; the same","the same; a higher","a higher; the same","a higher; a higher"],"answer":"C","images":null,"translation":{"question":"假设两个经济在所有方面都相同，只是其中一个储蓄率更高。根据索洛增长模型，在稳态下，与储蓄率较低的国家相比，储蓄率较高的国家将有 ______ 的人均产出水平和 ______ 的人均产出增长率。","options":["相同；相同","相同；更高","更高；相同","更高；更高"]},"topics":["solow-model"]},{"num":31,"type":"mc","question":"Examination of recent data for many countries shows that countries with high saving rates generally have high levels of output per person because:","options":["high saving rates mean permanently higher growth rates of output.","high saving rates lead to high levels of capital per worker.","countries with high levels of output per worker can afford to save a lot.","countries with large amounts of natural resources have both high output levels and high saving rates."],"answer":"B","images":null,"translation":{"question":"对许多国家近期数据的考察显示，高储蓄率的国家通常有高的人均产出水平，因为：","options":["高储蓄率意味着永久更高的产出增长率。","高储蓄率导致高的人均资本水平。","人均产出水平高的国家有能力储蓄很多。","拥有大量自然资源的国家既有高产出水平又有高储蓄率。"]},"topics":["solow-model"]},{"num":32,"type":"mc","question":"The Golden Rule level of capital accumulation is the steady state with the highest level of:","options":["output per worker.","capital per worker.","savings per worker.","consumption per worker."],"answer":"D","images":null,"translation":{"question":"资本积累的黄金律水平是 ______ 最高的稳态。","options":["人均产出","人均资本","人均储蓄","人均消费"]},"topics":["golden-rule"]},{"num":33,"type":"mc","question":"The formula for steady-state consumption per worker (c*) as a function of output per worker and investment per worker is:","options":["c* = f (k*) – dk*.","c* = f (k*) + dk*.","c* = f (k*) ÷ dk*.","c* = k* – df (k)*."],"answer":"A","images":null,"translation":{"question":"作为人均产出和人均投资的函数，稳态人均消费 (c*) 的公式是：","options":["c* = f(k*) – δk*。","c* = f(k*) + δk*。","c* = f(k*) ÷ δk*。","c* = k* – δf(k)*。"]},"topics":["golden-rule"]},{"num":34,"type":"mc","question":"In the Solow growth model, increases in capital ______ output and ______ the amount of output used to replace depreciating capital.","options":["increase; increase","increase; decrease","decrease; increase","decrease; decrease"],"answer":"A","images":null,"translation":{"question":"在索洛增长模型中，资本增加 ______ 产出，并 ______ 用于替换折旧资本的产出量。","options":["增加；增加","增加；减少","减少；增加","减少；减少"]},"topics":["golden-rule"]},{"num":36,"type":"mc","question":"Exhibit: Steady-State Consumption II The Golden Rule level of steady-state consumption per worker is:","options":["AC.","AB.","BC.","DE."],"answer":"B","images":["c8_img4.png"],"translation":{"question":"图表：稳态消费 II 稳态人均消费的黄金律水平是：","options":["AC。","AB。","BC。","DE。"]},"topics":["golden-rule"]},{"num":37,"type":"mc","question":"Exhibit: Steady-State Consumption II The Golden Rule level of steady-state investment per worker is:","options":["AC.","AB.","BC.","DE."],"answer":"C","images":["c8_img5.png"],"translation":{"question":"图表：稳态消费 II 稳态人均投资的黄金律水平是：","options":["AC。","AB。","BC。","DE。"]},"topics":["golden-rule"]},{"num":38,"type":"mc","question":"In an economy with no population growth and no technological change, steady-state consumption is at its greatest possible level when the marginal product of:","options":["labor equals the marginal product of capital.","labor equals the depreciation rate.","capital equals the depreciation rate.","capital equals zero."],"answer":"C","images":["c8_img6.png"],"translation":{"question":"在一个没有人口增长、没有技术进步的经济中，当 ______ 时稳态消费达到其最大可能水平。","options":["劳动的边际产量等于资本的边际产量","劳动的边际产量等于折旧率","资本的边际产量等于折旧率","资本的边际产量等于零"]},"topics":["golden-rule"]},{"num":39,"type":"mc","question":"If an economy is in a steady state with no population growth or technological change and the marginal product of capital is less than the depreciation rate:","options":["the economy is following the Golden Rule.","steady-state consumption per worker would be higher in a steady state with a lower saving rate.","steady-state consumption per worker would be higher in a steady state with a higher saving rate.","the depreciation rate should be decreased to achieve the Golden Rule level of consumption per worker."],"answer":"B","images":null,"translation":{"question":"如果一个经济处于没有人口增长或技术进步的稳态，且资本的边际产量小于折旧率，则：","options":["该经济正遵循黄金律。","在储蓄率较低的稳态中，稳态人均消费会更高。","在储蓄率较高的稳态中，稳态人均消费会更高。","应降低折旧率以达到黄金律水平的人均消费。"]},"topics":["golden-rule"]},{"num":40,"type":"mc","question":"If an economy with no population growth or technological change has a steady-state MPK of 0.125, a depreciation rate of 0.1, and a saving rate of 0.225, then the steady-state capital stock:","options":["is greater than the Golden Rule level.","is less than the Golden Rule level.","equals the Golden Rule level.","could be either above or below the Golden Rule level."],"answer":"B","images":null,"translation":{"question":"如果一个没有人口增长或技术进步的经济稳态 MPK 为 0.125，折旧率为 0.1，储蓄率为 0.225，则稳态资本存量：","options":["高于黄金律水平。","低于黄金律水平。","等于黄金律水平。","可能高于或低于黄金律水平。"]},"topics":["golden-rule"]},{"num":41,"type":"mc","question":"With a per-worker production function y = k1/2, the steady-state capital stock per worker (k*) as a function of the saving rate (s) is given by:","options":["k* = (s / d)2.","k* = (d / s)2.","k* = s / d.","k* = d / s."],"answer":"A","images":null,"translation":{"question":"对于人均生产函数 y = k^(1/2)，作为储蓄率 (s) 的函数的稳态人均资本存量 (k*) 为：","options":["k* = (s / δ)²。","k* = (δ / s)²。","k* = s / δ。","k* = δ / s。"]},"topics":["golden-rule"]},{"num":42,"type":"mc","question":"To determine whether an economy is operating at its Golden Rule level of capital stock, a policymaker must determine the steady-state saving rate that produces the:","options":["largest MPK.","smallest depreciation rate.","largest consumption per worker.","largest output per worker."],"answer":"C","images":null,"translation":{"question":"要判断一个经济是否运行在其资本存量的黄金律水平，政策制定者必须确定能产生 ______ 的稳态储蓄率。","options":["最大 MPK","最小折旧率","最大人均消费","最大人均产出"]},"topics":["golden-rule"]},{"num":43,"type":"mc","question":"Suppose that an economy is in its steady state and the capital stock is above the Golden Rule level. Assuming that there are no population growth or technological change, if the saving rate falls:","options":["output, consumption, investment, and depreciation will all decrease.","output and investment will decrease, and consumption and depreciation will increase.","output and investment will decrease, and consumption and depreciation will increase and then decrease but finally approach levels above their initial state.","output, investment, and depreciation will decrease, and consumption will increase and then decrease but finally approach a level above its initial state."],"answer":"D","images":null,"translation":{"question":"假设一个经济处于稳态，且资本存量高于黄金律水平。在没有人口增长或技术进步的假设下，如果储蓄率下降：","options":["产出、消费、投资和折旧都将减少。","产出和投资将减少，消费和折旧将增加。","产出和投资将减少，消费和折旧将先增加后减少，但最终趋近于高于初始状态的水平。","产出、投资和折旧将减少，消费将先增加后减少，但最终趋近于高于初始状态的水平。"]},"topics":["golden-rule"]},{"num":44,"type":"mc","question":"Suppose an economy is initially in a steady state with capital per worker exceeding the Golden Rule level. If the saving rate falls to a rate consistent with the Golden Rule, then in the transition to the new steady state, consumption per worker will:","options":["always exceed the initial level.","first fall below then rise above the initial level.","first rise above then fall below the initial level.","always be lower than the initial level."],"answer":"A","images":null,"translation":{"question":"假设一个经济最初处于稳态，人均资本超过黄金律水平。如果储蓄率下降到与黄金律一致的水平，那么向新稳态过渡的过程中，人均消费将：","options":["始终超过初始水平。","先下降到初始水平以下，然后上升到其以上。","先上升到初始水平以上，然后下降到其以下。","始终低于初始水平。"]},"topics":["golden-rule"]},{"num":45,"type":"mc","question":"A reduction in the saving rate starting from a steady state with more capital than the Golden Rule causes investment to ______ in the transition to the new steady state.","options":["increase","decrease","first increase and then decrease","first decrease and then increase"],"answer":"B","images":null,"translation":{"question":"从资本多于黄金律的稳态出发，降低储蓄率会在向新稳态过渡的过程中使投资 ______。","options":["增加","减少","先增加后减少","先减少后增加"]},"topics":["golden-rule"]},{"num":46,"type":"mc","question":"When an economy begins above the Golden Rule level, reaching the Golden Rule level:","options":["results in lower consumption at all times in the future.","results in higher consumption at all times in the future.","requires initially reducing consumption to increase consumption in the future.","requires initially increasing consumption to decrease consumption in the future."],"answer":"B","images":null,"translation":{"question":"当一个经济从高于黄金律水平起步时，达到黄金律水平：","options":["会导致未来任何时候的消费都更低。","会导致未来任何时候的消费都更高。","要求先减少消费，以在未来增加消费。","要求先增加消费，以在未来减少消费。"]},"topics":["golden-rule"]},{"num":47,"type":"mc","question":"If an economy is in a steady state with a saving rate below the Golden Rule level, efforts to increase the saving rate result in:","options":["both higher per-capita output and higher per-capita depreciation, but the increase in per-capita output would be greater.","both higher per-capita output and higher per-capita depreciation, but the increase in per-capita depreciation would be greater.","higher per-capita output and lower per-capita depreciation.","lower per-capita output and higher per-capita depreciation."],"answer":"A","images":null,"translation":{"question":"如果一个经济处于储蓄率低于黄金律水平的稳态，那么提高储蓄率的努力会导致：","options":["人均产出和人均折旧都更高，但人均产出的增加会更大。","人均产出和人均折旧都更高，但人均折旧的增加会更大。","人均产出更高，人均折旧更低。","人均产出更低，人均折旧更高。"]},"topics":["golden-rule"]},{"num":48,"type":"mc","question":"Suppose an economy is initially in a steady state with capital per worker below the Golden Rule level. If the saving rate increases to a rate consistent with the Golden Rule, then in the transition to the new steady state consumption per worker will:","options":["always exceed the initial level.","first fall below and then rise above the initial level.","first rise above and then fall below the initial level.","always be lower than the initial level."],"answer":"B","images":null,"translation":{"question":"假设一个经济最初处于稳态，人均资本低于黄金律水平。如果储蓄率上升到与黄金律一致的水平，那么向新稳态过渡的过程中人均消费将：","options":["始终超过初始水平。","先下降到初始水平以下，然后上升到其以上。","先上升到初始水平以上，然后下降到其以下。","始终低于初始水平。"]},"topics":["golden-rule"]},{"num":49,"type":"mc","question":"When an economy's capital is below the Golden Rule level, reaching the Golden Rule level:","options":["produces lower consumption at all times in the future.","requires higher consumption levels at all times.","requires initially reducing consumption to increase consumption in the future.","requires initially increasing consumption to decrease consumption in the future."],"answer":"C","images":null,"translation":{"question":"当一个经济的资本低于黄金律水平时，达到黄金律水平：","options":["会导致未来任何时候的消费都更低。","要求任何时候都有更高的消费水平。","要求先减少消费，以在未来增加消费。","要求先增加消费，以在未来减少消费。"]},"topics":["golden-rule"]},{"num":50,"type":"mc","question":"An increase in the saving rate starting from a steady state with less capital than the Golden Rule causes investment to ______ in the transition to the new steady state.","options":["increase","decrease","first increase and then decrease","first decrease and then increase"],"answer":"A","images":null,"translation":{"question":"从资本少于黄金律的稳态出发，提高储蓄率会在向新稳态过渡的过程中使投资 ______。","options":["增加","减少","先增加后减少","先减少后增加"]},"topics":["golden-rule"]},{"num":51,"type":"mc","question":"In an economy with population growth at rate n, the change in capital stock per worker is given by the equation:","options":["Dk = sf (k) + dk.","Dk = sf (k) – dk.","Dk = sf (k) + (d + n) k.","Dk = sf (k) – (d + n) k."],"answer":"D","images":null,"translation":{"question":"在一个人口增长率为 n 的经济中，人均资本存量的变化由以下方程给出：","options":["Δk = sf(k) + δk。","Δk = sf(k) – δk。","Δk = sf(k) + (δ + n)k。","Δk = sf(k) – (δ + n)k。"]},"topics":["population-growth"]},{"num":52,"type":"mc","question":"The formula for the steady-state ratio of capital to labor (k*) with population growth at rate n but no technological change, where s is the saving rate, is s:","options":["divided by the sum of the depreciation rate plus n.","multiplied by the sum of the depreciation rate plus n.","divided by the product of f (k*) and the sum of the depreciation rate plus n.","multiplied by f (k*) divided by the sum of the depreciation rate plus n."],"answer":"D","images":null,"translation":{"question":"在人口增长率为 n 但没有技术变化的情况下，稳态资本—劳动比 (k*) 的公式中，s 为储蓄率，s：","options":["除以折旧率与 n 之和。","乘以折旧率与 n 之和。","除以 f(k*) 与折旧率加 n 之和的乘积。","乘以 f(k*) 再除以折旧率与 n 之和。"]},"topics":["population-growth"]},{"num":53,"type":"mc","question":"In the Solow growth model of an economy with population growth but no technological change, the break-even level of investment must do all of the following except:","options":["offset the depreciation of existing capital.","provide capital for new workers.","equal the marginal productivity of capital (MPK).","keep the level of capital per worker constant."],"answer":"C","images":null,"translation":{"question":"在人口增长但没有技术变化的索洛增长模型中，盈亏平衡投资水平必须做到以下所有，除了：","options":["抵消现有资本的折旧。","为新工人提供资本。","等于资本的边际生产率 (MPK)。","保持人均资本水平不变。"]},"topics":["population-growth"]},{"num":54,"type":"mc","question":"In the Solow growth model of an economy with population growth but no technological change, if population grows at rate n, then capital in the steady state grows at rate ______, and output grows at rate ______ in the steady state.","options":["n; n","n; 0","0; 0","0; n"],"answer":"A","images":null,"translation":{"question":"在人口增长但没有技术变化的索洛增长模型中，如果人口以速率 n 增长，则在稳态下资本以速率 ______ 增长，产出以速率 ______ 增长。","options":["n；n","n；0","0；0","0；n"]},"topics":["population-growth"]},{"num":55,"type":"mc","question":"In the Solow growth model of an economy with population growth but no technological change, if population grows at rate n, total output in the steady state grows at rate ______, and output per worker grows at rate ______ in the steady state.","options":["n; n","n; 0","0; 0","0; n"],"answer":"B","images":null,"translation":{"question":"在人口增长但没有技术变化的索洛增长模型中，如果人口以速率 n 增长，则在稳态下总产出以速率 ______ 增长，人均产出以速率 ______ 增长。","options":["n；n","n；0","0；0","0；n"]},"topics":["population-growth"]},{"num":56,"type":"mc","question":"Assume that two economies are identical in every way except that one has a higher population growth rate. According to the Solow growth model, in the steady state, the country with the higher population growth rate will have a ______ level of output per person and ______ rate of growth of output per worker compared to the country with the lower population growth rate.","options":["higher; the same","higher; a higher","lower; the same","lower; a lower"],"answer":"C","images":null,"translation":{"question":"假设两个经济在所有方面都相同，只是其中一个人口增长率更高。根据索洛增长模型，在稳态下，与人口增长率较低的国家相比，人口增长率较高的国家将有 ______ 的人均产出水平和 ______ 的人均产出增长率。","options":["更高；相同","更高；更高","更低；相同","更低；更低"]},"topics":["population-growth"]},{"num":57,"type":"mc","question":"In the Solow growth model, an economy in the steady state with a population growth rate of n but no technological growth will exhibit a growth rate of output per worker at rate:","options":["0.","n.","d.","(n + d)."],"answer":"A","images":null,"translation":{"question":"在索洛增长模型中，处于稳态、人口增长率为 n 但没有技术增长的经济，其人均产出增长率为：","options":["0。","n。","δ。","(n + δ)。"]},"topics":["population-growth"]},{"num":58,"type":"mc","question":"In the Solow growth model, an economy in the steady state with a population growth rate of n but no technological growth will exhibit a growth rate of total output at rate:","options":["0.","n.","d.","(n + d)."],"answer":"B","images":null,"translation":{"question":"在索洛增长模型中，处于稳态、人口增长率为 n 但没有技术增长的经济，其总产出增长率为：","options":["0。","n。","δ。","(n + δ)。"]},"topics":["population-growth"]},{"num":59,"type":"mc","question":"In the Solow growth model, if two countries are otherwise identical (with the same production function, same saving rate, same depreciation rate, and same rate of population growth) except that Country Large has a population of 1 billion workers and Country Small has a population of 10 million workers, the steady-state level of output per worker will be _____, and the steady-state growth rate of output per worker will be _____.","options":["the same in both countries; the same in both countries","higher in Country Large; higher in Country Large","higher in Country Small; higher in Country Small","higher in Country Large; higher in Country Small"],"answer":"A","images":null,"translation":{"question":"在索洛增长模型中，如果两个国家在其他方面完全相同（相同的生产函数、相同的储蓄率、相同的折旧率和相同的人口增长率），只是大国（Country Large）有 10 亿工人，小国（Country Small）有 1000 万工人，则稳态人均产出水平将 _____，稳态人均产出增长率将 _____。","options":["两国相同；两国相同","大国更高；大国更高","小国更高；小国更高","大国更高；小国更高"]},"topics":["population-growth"]},{"num":60,"type":"mc","question":"In the Solow growth model with population growth but no technological progress, the steady-state amount of investment can be thought of as a break-even amount of investment because the quantity of investment just equals the amount of:","options":["output needed to achieve the maximum level of consumption per worker.","capital needed to replace depreciated capital and to equip new workers.","saving needed to achieve the maximum level of output per worker.","output needed to make the capital per worker ratio equal to the marginal product of capital."],"answer":"B","images":null,"translation":{"question":"在人口增长但没有技术进步的索洛增长模型中，稳态投资量可以被视为盈亏平衡投资量，因为投资量恰好等于：","options":["实现人均消费最大水平所需的产出。","替换折旧资本并为新工人配备资本所需的资本。","实现人均产出最大水平所需的储蓄。","使人均资本比等于资本边际产量所需的产出。"]},"topics":["population-growth"]},{"num":61,"type":"mc","question":"In the Solow growth model, the steady state level of output per worker would be higher if the _____ increased or the _____ decreased.","options":["saving rate; depreciation rate","population growth rate; depreciation rate","depreciation rate; population growth rate","population growth rate; saving rate"],"answer":"A","images":null,"translation":{"question":"在索洛增长模型中，如果 _____ 上升或 _____ 下降，稳态人均产出水平会更高。","options":["储蓄率；折旧率","人口增长率；折旧率","折旧率；人口增长率","人口增长率；储蓄率"]},"topics":["population-growth"]},{"num":62,"type":"mc","question":"In the Solow growth model with population growth but no technological change, which of the following will generate a higher steady-state growth rate of total output?","options":["a higher saving rate","a lower depreciation rate","a higher population growth rate","a higher capital per worker ratio"],"answer":"C","images":null,"translation":{"question":"在人口增长但没有技术变化的索洛增长模型中，以下哪一项会产生更高的稳态总产出增长率？","options":["更高的储蓄率","更低的折旧率","更高的人口增长率","更高的人均资本比"]},"topics":["population-growth"]},{"num":63,"type":"mc","question":"In the Solow growth model, with a given production function, depreciation rate, saving rate, and no technological change, higher rates of population growth produce:","options":["higher steady-state ratios of capital per worker.","higher steady-state growth rates of output per worker.","higher steady-state growth rates of total output.","higher steady-state levels of output per worker."],"answer":"C","images":null,"translation":{"question":"在索洛增长模型中，给定生产函数、折旧率、储蓄率且没有技术变化，更高的人口增长率会产生：","options":["更高的人均资本稳态比率。","更高的人均产出稳态增长率。","更高的总产出稳态增长率。","更高的人均产出稳态水平。"]},"topics":["population-growth"]},{"num":64,"type":"mc","question":"In the Solow growth model with population growth but no technological progress, when the economy finds itself at the Golden Rule steady state, the marginal product of capital minus the rate of depreciation will equal:","options":["0.","the population growth rate.","the saving rate.","output per worker."],"answer":"B","images":null,"translation":{"question":"在人口增长但没有技术进步的索洛增长模型中，当经济处于黄金律稳态时，资本的边际产量减去折旧率将等于：","options":["0。","人口增长率。","储蓄率。","人均产出。"]},"topics":["golden-rule","population-growth"]},{"num":65,"type":"mc","question":"In the Solow growth model with population growth but no technological progress, if in the steady state the marginal product of capital equals 0.10, the depreciation rate equals 0.05, and the rate of population growth equals 0.03, then the capital per worker ratio ____ the Golden Rule level.","options":["is above","is below","is equal to","will move to"],"answer":"B","images":null,"translation":{"question":"在人口增长但没有技术进步的索洛增长模型中，如果在稳态下资本的边际产量等于 0.10，折旧率等于 0.05，人口增长率等于 0.03，则人均资本比 ____ 黄金律水平。","options":["高于","低于","等于","将移动到"]},"topics":["golden-rule","population-growth"]},{"num":66,"type":"mc","question":"An increase in the rate of population growth with no change in the saving rate:","options":["increases the steady-state level of capital per worker.","decreases the steady-state level of capital per worker.","does not affect the steady-state level of capital per worker.","decreases the rate of output growth in the short run."],"answer":"B","images":null,"translation":{"question":"在储蓄率不变的情况下，人口增长率上升：","options":["提高稳态人均资本水平。","降低稳态人均资本水平。","不影响稳态人均资本水平。","降低短期产出增长率。"]},"topics":["population-growth"]},{"num":67,"type":"mc","question":"Analysis of population growth around the world concludes that countries with high population growth tend to:","options":["have high income per worker.","have a lower level of income per worker than countries with low population growth.","have the same standard of living as other parts of the world.","tend to be the high-income-producing nations of the world."],"answer":"B","images":null,"translation":{"question":"对世界人口增长的分析得出结论：人口增长快的国家往往：","options":["有高的人均收入。","人均收入水平低于人口增长慢的国家。","与世界上其他地区有相同的生活水平。","往往是世界上高收入的国家。"]},"topics":["population-growth"]},{"num":68,"type":"mc","question":"According to Michael Kremer, large populations:","options":["require the capital stock to be spread thinly, thereby reducing living standards.","place great strains on an economy's productive resources, resulting in perpetual poverty.","are a prerequisite for technological advances and higher living standards.","are not a factor in determining living standards."],"answer":"C","images":null,"translation":{"question":"根据迈克尔·克雷默（Michael Kremer）的观点，大量人口：","options":["要求资本存量被摊薄，从而降低生活水平。","给经济的生产资源带来巨大压力，导致永久贫困。","是技术进步和更高生活水平的先决条件。","不是决定生活水平的因素。"]},"topics":["population-growth"]},{"num":69,"type":"mc","question":"According to Thomas Malthus, large populations:","options":["require the capital stock to be spread thinly, thereby reducing living standards.","place great strains on an economy's productive resources, resulting in perpetual poverty.","are a prerequisite for technological advances and higher living standards.","are not a factor in determining living standards."],"answer":"B","images":null,"translation":{"question":"根据托马斯·马尔萨斯（Thomas Malthus）的观点，大量人口：","options":["要求资本存量被摊薄，从而降低生活水平。","给经济的生产资源带来巨大压力，导致永久贫困。","是技术进步和更高生活水平的先决条件。","不是决定生活水平的因素。"]},"topics":["population-growth"]},{"num":70,"type":"mc","question":"According to the Kremerian model, large populations improve living standards because:","options":["crowded conditions put more pressure on people to work hard.","there are more people who can make discoveries and contribute to innovation.","more people have the opportunity for leisure and recreation.","most people prefer to live with many other people."],"answer":"B","images":null,"translation":{"question":"根据克雷默模型，大量人口之所以能提高生活水平，是因为：","options":["拥挤的环境给人们施加更大压力去努力工作。","有更多的人能够做出发现并为创新做贡献。","更多的人有机会休闲和娱乐。","大多数人喜欢与很多人一起生活。"]},"topics":["population-growth"]},{"num":71,"type":"mc","question":"If Y = K0.3L0.7, then the per-worker production function is:","options":["Y = F(K / L).","Y / L = (K / L)0.3.","Y / L = (K / L)0.5.","Y / L = (K / L)0.7."],"answer":"B","images":null,"translation":{"question":"如果 Y = K^0.3 L^0.7，则人均生产函数为：","options":["Y = F(K / L)。","Y / L = (K / L)^0.3。","Y / L = (K / L)^0.5。","Y / L = (K / L)^0.7。"]},"topics":["solow-model"]},{"num":72,"type":"mc","question":"If y = k1/2, there is no population growth or technological progress, 5 percent of capital depreciates each year, and a country saves 20 percent of output each year, then the steady-state level of capital per worker is:","options":["2.","4.","8.","16."],"answer":"D","images":null,"translation":{"question":"如果 y = k^(1/2)，没有人口增长或技术进步，每年 5% 的资本折旧，且一个国家每年储蓄 20% 的产出，则稳态人均资本水平为：","options":["2。","4。","8。","16。"]},"topics":["solow-model"]},{"num":73,"type":"mc","question":"If y = k1/2, the country saves 10 percent of its output each year, and the steady-state level of capital per worker is 4, then the steady-state levels of output per worker and consumption per worker are:","options":["2 and 1.6, respectively.","2 and 1.8, respectively.","4 and 3.2, respectively.","4 and 3.6, respectively."],"answer":"B","images":null,"translation":{"question":"如果 y = k^(1/2)，该国每年储蓄其产出的 10%，稳态人均资本水平为 4，则稳态人均产出水平和人均消费水平分别为：","options":["2 和 1.6。","2 和 1.8。","4 和 3.2。","4 和 3.6。"]},"topics":["solow-model"]},{"num":74,"type":"mc","question":"Assume that two countries both have the per-worker production function y = k1/2, neither has population growth or technological progress, depreciation is 5 percent of capital in both countries, and country A saves 10 percent of output whereas country B saves 20 percent. If country A starts out with a capital–labor ratio of 4 and country B starts out with a capital–labor ratio of 2, in the long run:","options":["both country A and country B will have capital–labor ratios of 4.","both country A and country B will have capital–labor ratios of 16.","country A's capital–labor ratio will be 4, whereas country B's will be 16.","country A's capital–labor ratio will be 16, whereas country B's will be 4."],"answer":"C","images":null,"translation":{"question":"假设两个国家都有相同的人均生产函数 y = k^(1/2)，都没有人口增长或技术进步，两国的资本折旧率均为 5%，A 国储蓄 10% 的产出，而 B 国储蓄 20% 的产出。如果 A 国起始资本—劳动比为 4，B 国起始资本—劳动比为 2，那么在长期：","options":["A 国和 B 国的资本—劳动比都将为 4。","A 国和 B 国的资本—劳动比都将为 16。","A 国的资本—劳动比将为 4，而 B 国的将为 16。","A 国的资本—劳动比将为 16，而 B 国的将为 4。"]},"topics":["solow-model"]},{"num":75,"type":"mc","question":"Assume that a war reduces a country's labor force but does not directly affect its capital stock. Then the immediate impact will be that:","options":["total output will fall, but output per worker will rise.","total output will rise, but output per worker will fall.","both total output and output per worker will fall.","both total output and output per worker will rise."],"answer":"A","images":null,"translation":{"question":"假设一场战争减少了一个国家的劳动力，但并未直接影响其资本存量。那么直接影响将是：","options":["总产出下降，但人均产出上升。","总产出上升，但人均产出下降。","总产出和人均产出都下降。","总产出和人均产出都上升。"]},"topics":["solow-model"]},{"num":76,"type":"mc","question":"Assume that a war reduces a country's labor force but does not directly affect its capital stock. If the economy was in a steady state before the war and the saving rate does not change after the war, then, over time, capital per worker will ______, and output per worker will ______ as it returns to the steady state.","options":["decline; increase","increase; increase","decline; decrease","increase; decrease"],"answer":"C","images":null,"translation":{"question":"假设一场战争减少了一个国家的劳动力，但并未直接影响其资本存量。如果战前经济处于稳态，且战后储蓄率不变，那么随着经济回到稳态，人均资本将 ______，人均产出将 ______。","options":["下降；上升","上升；上升","下降；下降","上升；下降"]},"topics":["solow-model"]},{"num":77,"type":"mc","question":"If the U.S. production function is Cobb–Douglas with capital share 0.3, output growth is 3 percent per year, depreciation is 4 percent per year, and the Golden Rule steady-state capital–output ratio is 4.29, to reach the Golden Rule steady state, the saving rate must be:","options":["17.5 percent.","25 percent.","30 percent.","42.9 percent."],"answer":"C","images":null,"translation":{"question":"如果美国的生产函数是柯布—道格拉斯（Cobb–Douglas）型的，资本份额为 0.3，产出增长率为每年 3%，折旧率为每年 4%，黄金律稳态资本—产出比为 4.29，则要达到黄金律稳态，储蓄率必须为：","options":["17.5%。","25%。","30%。","42.9%。"]},"topics":["golden-rule"]},{"num":78,"type":"mc","question":"If an economy moves from a steady state with positive population growth to a zero population growth rate, then in the new steady state, total output growth will be ______, and growth of output per person will be ______.","options":["lower; lower","lower; the same as it was before","higher; higher than it was before","higher; lower"],"answer":"B","images":null,"translation":{"question":"如果一个经济从人口正增长的稳态转变为人口增长率为零的状态，那么在新的稳态下，总产出增长将 ______，人均产出增长将 ______。","options":["更低；更低","更低；与以前相同","更高；比以前更高","更高；更低"]},"topics":["population-growth"]},{"num":79,"type":"mc","question":"If the production function exhibits increasing returns to scale in the steady state, an increase in the rate of growth of population would lead to:","options":["growth in total output and growth in output per worker.","growth in total output but no growth in output per worker.","growth in total output but a decrease in output per worker.","no growth in total output or in output per worker."],"answer":"A","images":null,"translation":{"question":"如果生产函数在稳态下呈现规模报酬递增，人口增长率的上升会导致：","options":["总产出增长且人均产出增长。","总产出增长但人均产出不增长。","总产出增长但人均产出下降。","总产出和人均产出都不增长。"]},"topics":["population-growth"]},{"num":80,"type":"sa","question":"Assume that a country's production function is Y = K1/2L1/2 and there is no population growth or technological change. a. What is the per-worker production function y = f (k)? b. Assume that the country possesses 40,000 units of capital and 10,000 units of labor. What is Y? What is labor productivity computed from the per-worker production function? Is this value the same as labor productivity computed from the original production function? c. Assume that 10 percent of capital depreciates each year. What gross saving rate is necessary to make the given capital–labor ratio the steady-state capital–labor ratio? (Hint: In a steady state with no population growth or technological change, the saving rate multiplied by per-worker output must equal the depreciation rate multiplied by the capital–labor ratio.) d. If the saving rate equals the steady-state level, what is consumption per worker?","options":null,"answer":null,"images":null,"translation":{"question":"假设一个国家的生产函数为 Y = K^(1/2)L^(1/2)，没有人口增长或技术变化。a. 人均生产函数 y = f(k) 是什么？b. 假设该国拥有 40,000 单位资本和 10,000 单位劳动。Y 是多少？由人均生产函数计算的劳动生产率是多少？该值与由原始生产函数计算的劳动生产率相同吗？c. 假设每年 10% 的资本折旧。要使给定的资本—劳动比成为稳态资本—劳动比，必要的总储蓄率是多少？（提示：在没有人口增长或技术变化的稳态下，储蓄率乘以人均产出必须等于折旧率乘以资本—劳动比。）d. 如果储蓄率等于稳态水平，人均消费是多少？","options":null},"topics":["solow-model"],"answer_ref":"a. 两边除以 L：y = Y/L = (K/L)^{1/2} = k^{1/2}。b. Y = (40,000)^{1/2}×(10,000)^{1/2} = 200×100 = 20,000。劳动生产率 = Y/L = 2。由人均函数：k = K/L = 4，f(4) = 4^{1/2} = 2——两者一致。"},{"num":81,"type":"sa","question":"Assume that a country's per-worker production is y = k1/2, where y is output per worker and k is capital per worker. Assume also that 10 percent of capital depreciates per year (= 0.10) 2 and there is no population growth or technological change. a. If the saving rate (s) is 0.4, what are capital per worker, production per worker, and consumption per worker in the steady state? b. Solve for steady-state capital per worker, production per worker, and consumption per worker with s = 0.6. c. Solve for steady-state capital per worker, production per worker, and consumption per worker with s = 0.8. d. Is it possible to save too much? Why?","options":null,"answer":null,"images":null,"translation":{"question":"假设一个国家的人均生产为 y = k^(1/2)，其中 y 为人均产出，k 为人均资本。还假设每年 10% 的资本折旧（= 0.10），没有人口增长或技术变化。a. 如果储蓄率 (s) 为 0.4，稳态下的人均资本、人均生产和人均消费各是多少？b. 求解 s = 0.6 时的稳态人均资本、人均生产和人均消费。c. 求解 s = 0.8 时的稳态人均资本、人均生产和人均消费。d. 有可能储蓄过多吗？为什么？","options":null},"topics":["solow-model"],"answer_ref":"a. 稳态条件 s·f(k) = δk：0.4·k^{1/2} = 0.1k → k^{1/2} = 4 → 人均资本 k = 16，人均产出 y = 4，人均消费 c = (1−s)y = 0.6×4 = 2.4。b. s=0.6：k^{1/2} = 6 → k = 36，y = 6，c = 0.4×6 = 2.4。c. s=0.8：k^{1/2} = 8 → k = 64，y = 8，c = 0.2×8 = 1.6。d. 会。黄金律要求 MPK = 0.5k^{−1/2} = δ = 0.1 → k = 25，对应 s = δk/y = 0.5。比较可知 s=0.4 与 s=0.6 时 c 都为 2.4，s=0.8 时 c 降到 1.6——储蓄一旦超过黄金律水平（s>0.5），稳态人均消费反而下降，因为维持巨额资本所需的折旧吞噬了产出。所以存在\"储蓄过多\"。"},{"num":82,"type":"sa","question":"Suppose that two countries are exactly alike in every respect except that the citizens of country A have a higher saving rate than the citizens of country B. a. Which country will have the higher level of output per worker in the steady state? Illustrate graphically. b. Which country will have the faster rate of growth of output per worker in the steady state?","options":null,"answer":null,"images":null,"translation":{"question":"假设两个国家在所有方面完全相同，只是 A 国公民的储蓄率高于 B 国公民。a. 在稳态下哪个国家的人均产出水平更高？用图形说明。b. 在稳态下哪个国家的人均产出增长速度更快？","options":null},"topics":["solow-model"],"answer_ref":"a. A 国稳态人均产出更高：图（纵轴 y 与储蓄投资，横轴 k）上 A 国的 s·f(k) 线更高，与 δk 交于更高的 k* 与 y*。b. 稳态增长率相同（无技术进步时都为零）——储蓄率只决定水平，不决定长期增长率；两国人均收入增长率相同（都为0），只是 A 的水平更高。"},{"num":83,"type":"sa","question":"Suppose that two countries are exactly alike in every respect except that population grows at a faster rate in country A than in country B. a. Which country will have the higher level of output per worker in the steady state? Illustrate graphically. b. Which country will have the faster rate of growth of output per worker in the steady state?","options":null,"answer":null,"images":null,"translation":{"question":"假设两个国家在所有方面完全相同，只是 A 国的人口增长速度快于 B 国。a. 在稳态下哪个国家的人均产出水平更高？用图形说明。b. 在稳态下哪个国家的人均产出增长速度更快？","options":null},"topics":["population-growth"],"answer_ref":"a. B 国（人口增长较慢）稳态人均产出更高：(n+δ)k 线对 B 国更平缓，与 s·f(k) 的交点对应更高的 k*、y*。b. 稳态增长率相同——无技术进步时人均产出增长都为零；人口增长只影响水平，且使总人口以 n 增长。"},{"num":84,"type":"sa","question":"It rains so much in the country of Tropicana that capital equipment rusts out (depreciates) at a much faster rate than it does in the country of Sahara. If the countries are otherwise identical, in which country will the Golden Rule level of capital per worker be higher? Illustrate graphically.","options":null,"answer":null,"images":null,"translation":{"question":"特罗皮卡纳国（Tropicana）雨水很多，其资本设备锈蚀（折旧）的速度比撒哈拉国（Sahara）快得多。如果两国在其他方面相同，哪个国家的黄金律人均资本水平会更高？用图形说明。","options":null},"topics":["golden-rule"],"answer_ref":"撒哈拉国的黄金律人均资本更高。黄金律条件 MPK = δ（+n）：折旧率越高，资本边际产品必须越高才能达到最大消费，而 MPK 随 k 递减——因此高折旧的 Tropicana 黄金律资本量更低，低折旧的 Sahara 更高。图：δ_S 小 → (n+δ)k 平缓 → k_gold 大。"},{"num":85,"type":"sa","question":"The economy of Alpha can be described by the Solow growth model. The following are some characteristics of the Alpha economy: saving rate (s) 0.20 depreciation rate (d) 0.12 steady-state capital per worker (k) 4 population growth rate (n) 0.02 steady-state output per worker 20,000 a. What is the steady-state growth rate of output per worker in Alpha? b. What is the steady-state growth rate of total output in Alpha? c. What is the level of steady-state consumption per worker in Alpha? d. What is the steady-state level of investment per worker in Alpha?","options":null,"answer":null,"images":null,"translation":{"question":"阿尔法（Alpha）的经济可以用索洛增长模型来描述。以下是阿尔法经济的一些特征：储蓄率 (s) 0.20；折旧率 (δ) 0.12；稳态人均资本 (k) 4；人口增长率 (n) 0.02；稳态人均产出 20,000。a. 阿尔法稳态人均产出增长率是多少？b. 阿尔法稳态总产出增长率是多少？c. 阿尔法稳态人均消费水平是多少？d. 阿尔法稳态人均投资水平是多少？","options":null},"topics":["solow-model"],"answer_ref":"a. 人均产出稳态增长率 = 技术进步率 = 0。b. 总产出稳态增长率 = 人口增长率 n = 2%。c. 稳态条件 s·y = (n+δ)k → y/k = (n+δ)/s = 0.14/0.2 = 0.7。MPK = 资本份额 × y/k：若资本份额 0.3，MPK = 0.3×0.7 = 0.21（若份额 1/3 则为 0.233）。"},{"num":86,"type":"sa","question":"The initial steady-state level of capital per worker in Macroland is 5. The Golden Rule level of capital per worker in Macroland is 8. a. What must change in Macroland to achieve the Golden Rule steady state? b. Why might the Golden Rule steady state be preferred to the initial steady state? c. Why might some current workers in Macroland prefer the initial steady state to the Golden Rule steady state?","options":null,"answer":null,"images":null,"translation":{"question":"马克罗国（Macroland）初始稳态人均资本水平为 5。马克罗国黄金律人均资本水平为 8。a. 马克罗国必须改变什么才能达到黄金律稳态？b. 为什么黄金律稳态可能优于初始稳态？c. 为什么马克罗国的一些当前工人可能更偏好初始稳态而不是黄金律稳态？","options":null},"topics":["golden-rule"],"answer_ref":"a. 提高储蓄率，使投资曲线 s·f(k) 上移到与 δk 相交于 k=8。b. 黄金律稳态使稳态人均消费最大化——经济位于\"合意\"的资本水平。c. 当前工人可能反对：过渡期内必须提高储蓄率、压低当前消费来为更多资本积累融资；只有未来世代才能享受更高的消费水平。"},{"num":87,"type":"sa","question":"The economies of two countries, East and South, have the same production functions, depreciation rates, and saving rates. The economies of each country can be described by the Solow growth model. Population growth is faster in South than in East. a. In which country is the level of steady-state output per worker larger? Explain. b. In which country is the steady-state growth rate of output per worker larger? c. In which country is the growth rate of steady-state total output greater?","options":null,"answer":null,"images":null,"translation":{"question":"东国（East）和南国（South）两个国家的经济具有相同的生产函数、折旧率和储蓄率。每个国家的经济都可以用索洛增长模型来描述。南国的人口增长比东国快。a. 哪个国家的稳态人均产出水平更大？请解释。b. 哪个国家的稳态人均产出增长率更大？c. 哪个国家的稳态总产出增长率更大？","options":null},"topics":["population-growth"],"answer_ref":"a. East（人口增长较慢）更高：(n+δ)k 线更平缓 → 更高的 k* 与 y*。b. 稳态增长率相同（无技术进步时人均产出增长均为零）。人口增长只改变水平，不改变稳态增长率。"},{"num":88,"type":"sa","question":"One of the key distinctions made in the analysis of the Solow growth model is between changes in levels and changes in growth rates. How does an increase in the rate of population growth change the steady-state levels and growth rates of output and output per worker in the Solow model with no technological change?","options":null,"answer":null,"images":null,"translation":{"question":"索洛增长模型分析中的一个关键区别是水平变化与增长率变化之间的区别。在没有技术变化的索洛模型中，人口增长率的上升如何改变产出和人均产出的稳态水平与增长率？","options":null},"topics":["population-growth"],"answer_ref":"人口增长加快使 (n+δ)k 线变陡 → 稳态人均资本 k* 和人均产出 y* 的水平下降。稳态增长率：人均产出增长仍为零（无技术进步时）；总人口以 n 增长，故总产出以 n 增长——n 越高总产出增长越快，但人均水平更低。"},{"num":89,"type":"sa","question":"Explain the two uses of saving in the steady state in the Solow model with population growth but no technological progress.","options":null,"answer":null,"images":null,"translation":{"question":"在人口增长但没有技术进步的索洛模型中，请解释稳态下储蓄的两种用途。","options":null},"topics":["population-growth"],"answer_ref":"稳态下储蓄 s·y 恰好等于收支相抵投资 (n+δ)k，其用途有二：① 装备新增劳动力——人口增长要求给每个新工人配备与现有工人同样的人均资本（nk 部分）；② 替换折旧损耗的资本（δk 部分）。在稳态中，全部储蓄都用于这两项，没有任何净资本深化。"},{"num":90,"type":"sa","question":"Compare and contrast the impact of a faster rate of population growth on the standard of living (output per worker) in the models by Solow, Malthus, and Kremer.","options":null,"answer":null,"images":null,"translation":{"question":"比较并对照在索洛、马尔萨斯和克雷默模型中更快的人口增长对生活水平（人均产出）的影响。","options":null},"topics":["population-growth"],"answer_ref":"索洛模型：更快的人口增长降低稳态人均资本和人均产出——资本被摊薄到更多工人身上，生活水平下降。马尔萨斯模型：人口增长快于食物（土地固定），人均收入被钉在生存水平，人口越多越穷。克雷默模型：更多人口产生更多思想和创新者，技术随人口加速——人口增长提高人均收入。三者对\"人口增长与生活水准\"的预测方向完全不同。"},{"num":91,"type":"sa","question":"Consider two countries that are otherwise identical (they have the same saving rates and depreciation rates), but the population of Country Large is 100 million, while the population of Country Small is 10 million. Use the Solow model with no technological change to compare the steady-state levels of output per worker if: a. the population growth rates are the same in the two countries. b. the population growth rate is higher in Country Large.","options":null,"answer":null,"images":null,"translation":{"question":"考虑两个在其他方面相同的国家（它们有相同的储蓄率和折旧率），但大国（Country Large）的人口为 1 亿，而小国（Country Small）的人口为 1000 万。用没有技术变化的索洛模型比较稳态人均产出水平，如果：a. 两国的人口增长率相同。b. 大国的人口增长率更高。","options":null},"topics":["population-growth"],"answer_ref":"a. 人口增长率相同时：两国人均资本的稳态水平相同——索洛模型中稳态人均水平与人口规模无关；只是大国的总产出是大国的10倍。b. 人口增长率不同时：增长较慢的国家人均稳态产出更高（(n+δ)k 线更平缓）；人口规模仍然无关紧要。结论：决定人均收入水平的是 s、n、δ 等参数，不是国家大小。"},{"num":92,"type":"sa","question":"Larger quantities of steady-state capital have both a positive effect and a negative effect on consumption per worker in the Solow model (assuming no population growth or technological progress). Explain.","options":null,"answer":null,"images":null,"translation":{"question":"在索洛模型中（假设没有人口增长或技术进步），更大数量的稳态资本对人均消费既有正面影响又有负面影响。请解释。","options":null},"topics":["golden-rule"],"answer_ref":"正面：资本更多→人均产出更多→可用于消费的产品更多。负面：积累资本需要储蓄，即牺牲当前消费；维持更大的资本存量要替换更多折旧，维持成本更高。对消费 c=(1−s)f(k) 的净效应取决于所处位置：低于黄金律水平时正面占优，高于黄金律时负面占优。"},{"num":93,"type":"sa","question":"What is the marginal product of capital (MPK), as shown with the Solow model?","options":null,"answer":null,"images":null,"translation":{"question":"索洛模型所展示的资本的边际产量 (MPK) 是什么？","options":null},"topics":["solow-model"],"answer_ref":"资本边际产品（MPK）是在劳动（或有效劳动）不变时增加一单位资本所增加的产出：MPK = f(k+1) − f(k) ≈ f′(k)。在图上它是人均生产函数 f(k) 的斜率，随 k 增加而递减（资本边际报酬递减）。"},{"num":94,"type":"sa","question":"When does a steady state occur?","options":null,"answer":null,"images":null,"translation":{"question":"稳态何时出现？","options":null},"topics":["solow-model"],"answer_ref":"当人均投资等于收支相抵投资时达到稳态：s·f(k) = (n+δ)k（无人口增长时为 s·f(k) = δk；含技术进步时为 s·f(k) = (n+g+δ)k）。此时人均资本和人均产出不再变化。"},{"num":95,"type":"sa","question":"Define Golden Rule level of capital.","options":null,"answer":null,"images":null,"translation":{"question":"定义资本的黄金律水平。","options":null},"topics":["golden-rule"],"answer_ref":"黄金律资本水平：使稳态人均消费最大化的那个稳态人均资本量，满足 MPK = δ（含人口增长和技术进步时 MPK = n+g+δ）。此时人均消费 c = f(k) − (n+g+δ)k 达到最大。"},{"num":96,"type":"sa","question":"When an economy reaches a steady state other than the Golden Rule, what actions should policymakers take to achieve the Golden Rule steady state when: a. the economy begins with more capital than in the Golden Rule steady state? b. the economy begins with less capital than in the Golden Rule steady state?","options":null,"answer":null,"images":null,"translation":{"question":"当一个经济达到一个不是黄金律的稳态时，政策制定者应采取什么行动来达到黄金律稳态，当：a. 经济初始资本多于黄金律稳态时？b. 经济初始资本少于黄金律稳态时？","options":null},"topics":["golden-rule"],"answer_ref":"a. 若 k 高于黄金律水平：降低储蓄率——消费立即上升，资本随时间消耗下降到 k_gold。b. 若 k 低于黄金律水平：提高储蓄率——当期消费下降，经济逐步积累资本直至 k_gold，未来消费永久提高。"},{"num":97,"type":"sa","question":"How does population growth affect the steady state?","options":null,"answer":null,"images":null,"translation":{"question":"人口增长如何影响稳态？","options":null},"topics":["population-growth"],"answer_ref":"人口增长提高收支相抵投资：在储蓄率不变时，n 上升使稳态人均资本和人均产出下降。同时它决定了总产出在稳态中的增长率（=n）：人均产出不变，总量按人口速度扩张。人口增长还能解释\"越穷越生、越生越穷\"的循环。"},{"num":98,"type":"sa","question":"How does population growth help explain why some countries are poor and some are rich?","options":null,"answer":null,"images":null,"translation":{"question":"人口增长如何帮助解释为什么一些国家贫穷而一些国家富有？","options":null},"topics":["population-growth"],"answer_ref":"人口增长快的国家必须不断把储蓄用于装备新工人，摊薄了人均资本→人均产出低；人口增长慢的国家能把更多储蓄用于资本深化→人均资本与产出高、更富裕。结合储蓄率差异，这解释了国家间生活水平的巨大差距。"},{"num":99,"type":"sa","question":"What does the Malthusian model predict about population growth and its impact? How does the Kremerian model contradict the Malthusian model?","options":null,"answer":null,"images":null,"translation":{"question":"马尔萨斯模型对人口增长及其影响做出了什么预测？克雷默模型如何与马尔萨斯模型相矛盾？","options":null},"topics":["population-growth"],"answer_ref":"马尔萨斯模型：人口以几何级数增长、食物（土地）以算术级数增长→人均收入被钉在生存线上，人口增长降低生活水平。克雷默模型恰恰相反：纵观长期历史，人口越多产生的思想越多、技术进步越快，人均收入随人口增长而上升——更大的人口是繁荣之源而非灾难。"}]},{"num":9,"title":"Economic Growth II","questions":[{"num":1,"type":"mc","question":"The efficiency of labor:","options":["is the marginal product of labor.","is the rate of growth of the labor force.","depends on the knowledge, health, and skills of labor.","equals output per worker."],"answer":"C","images":null,"translation":{"question":"劳动的效率：","options":["是劳动的边际产量。","是劳动力的增长率。","取决于劳动的知识、健康和技能。","等于人均产出。"]},"topics":["technology-growth"]},{"num":2,"type":"mc","question":"The number of effective workers takes into account the number of workers and the:","options":["amount of capital available to each worker.","rate of growth of the number of workers.","efficiency of each worker.","saving rate of each worker."],"answer":"C","images":null,"translation":{"question":"有效工人的数量考虑了工人数量和：","options":["每个工人可获得的资本量。","工人数量的增长率。","每个工人的效率。","每个工人的储蓄率。"]},"topics":["technology-growth"]},{"num":3,"type":"mc","question":"The rate of labor-augmenting technological progress (g) is the growth rate of:","options":["labor.","the efficiency of labor.","capital.","output."],"answer":"B","images":null,"translation":{"question":"劳动扩张型技术进步率 (g) 是 ______ 的增长率。","options":["劳动","劳动效率","资本","产出"]},"topics":["technology-growth"]},{"num":4,"type":"mc","question":"The assumption that technological progress increases the efficiency of labor is called:","options":["endogenous technological progress.","the efficiency-wage model of economic growth.","labor-augmenting technological progress.","the Golden Rule model of economic growth."],"answer":"C","images":null,"translation":{"question":"技术进步提高劳动效率的假设被称为：","options":["内生技术进步。","经济增长的效率工资模型。","劳动扩张型技术进步。","经济增长的黄金律模型。"]},"topics":["technology-growth"]},{"num":5,"type":"mc","question":"If the labor force is growing at a 3 percent rate and the efficiency of a unit of labor is growing at a 2 percent rate, then the number of effective workers is growing approximately at a rate of:","options":["2 percent.","3 percent.","5 percent.","6 percent."],"answer":"C","images":null,"translation":{"question":"如果劳动力以 3% 的速度增长，而每单位劳动的效率以 2% 的速度增长，那么有效工人的数量大约以 ______ 的速度增长。","options":["2%","3%","5%","6%"]},"topics":["technology-growth"]},{"num":6,"type":"mc","question":"In a steady-state economy with a saving rate s, population growth n, depreciation rate d, and labor-augmenting technological progress g, the formula for the steady-state ratio of capital per effective worker (k*), in terms of output per effective worker (f (k*)), is","options":["sf (k) / (d + n + g).","s / ((f (k))(d + n + g)).","f (k) / ((s)(d + n + g)).","(s – f (k)) / (d + n + g)."],"answer":"A","images":null,"translation":{"question":"在一个储蓄率为 s、人口增长为 n、折旧率为 δ、劳动扩张型技术进步为 g 的稳态经济中，以每有效工人产出 (f(k*)) 表示的每有效工人资本稳态比率 (k*) 的公式为：","options":["sf(k) / (δ + n + g)。","s / ((f(k))(δ + n + g))。","f(k) / ((s)(δ + n + g))。","(s – f(k)) / (δ + n + g)。"]},"topics":["technology-growth"]},{"num":7,"type":"mc","question":"In the Solow growth model with population growth and labor-augmenting technological change, the break-even level of investment must cover:","options":["depreciating capital.","depreciating capital and capital for new workers.","depreciating capital and capital for new effective workers.","depreciating capital, capital for new workers, and capital for new effective workers."],"answer":"D","images":null,"translation":{"question":"在人口增长和劳动扩张型技术变化的索洛增长模型中，盈亏平衡投资水平必须覆盖：","options":["折旧的资本。","折旧的资本和为新工人提供的资本。","折旧的资本和为新的有效工人提供的资本。","折旧的资本、为新工人提供的资本和为新的有效工人提供的资本。"]},"topics":["technology-growth"]},{"num":8,"type":"mc","question":"In the Solow growth model, the steady-state growth rate of output per effective worker is ______, and the steady-state growth rate of output per actual worker is ______.","options":["the sum of the rate of technological progress plus the rate of population growth; zero","zero; the rate of technological progress","zero; zero","the rate of technological progress; the rate of population growth"],"answer":"B","images":null,"translation":{"question":"在索洛增长模型中，每有效工人产出的稳态增长率为 ______，每个实际工人产出的稳态增长率为 ______。","options":["技术进步率与人口增长率之和；零","零；技术进步率","零；零","技术进步率；人口增长率"]},"topics":["technology-growth"]},{"num":9,"type":"mc","question":"According to the Solow model, persistently rising living standards can only be explained by:","options":["population growth.","capital accumulation.","saving rates.","technological progress."],"answer":"D","images":null,"translation":{"question":"根据索洛模型，持续上升的生活水平只能由 ______ 来解释。","options":["人口增长","资本积累","储蓄率","技术进步"]},"topics":["technology-growth"]},{"num":10,"type":"mc","question":"In the Solow model with technological change, the Golden Rule level of capital is the steady state that maximizes:","options":["output per worker.","output per effective worker.","consumption per worker.","consumption per effective worker."],"answer":"D","images":null,"translation":{"question":"在具有技术变化的索洛模型中，黄金律资本水平是使 ______ 最大化的稳态。","options":["人均产出","每有效工人产出","人均消费","每有效工人消费"]},"topics":["technology-growth"]},{"num":11,"type":"mc","question":"With population growth at rate n and labor-augmenting technological progress at rate g, the Golden Rule steady state requires that the marginal product of capital (MPK):","options":["net of depreciation be equal to n + g.","net of depreciation be equal to the depreciation rate plus n + g.","plus n be equal to the depreciation rate plus g.","plus g be equal to the depreciation rate plus n."],"answer":"A","images":null,"translation":{"question":"在人口增长率为 n、劳动扩张型技术进步率为 g 的情况下，黄金律稳态要求资本的边际产量 (MPK)：","options":["扣除折旧后等于 n + g。","扣除折旧后等于折旧率加 n + g。","加上 n 等于折旧率加 g。","加上 g 等于折旧率加 n。"]},"topics":["technology-growth"]},{"num":12,"type":"mc","question":"In the Solow model with technological progress, the steady-state growth rate of capital per effective worker is:","options":["0.","g.","n.","n + g."],"answer":"A","images":null,"translation":{"question":"在具有技术进步的索洛模型中，每有效工人资本的稳态增长率为：","options":["0。","g。","n。","n + g。"]},"topics":["technology-growth"]},{"num":13,"type":"mc","question":"In the Solow model with technological progress, the steady-state growth rate of output per effective worker is:","options":["0.","g.","n.","n + g."],"answer":"A","images":null,"translation":{"question":"在具有技术进步的索洛模型中，每有效工人产出的稳态增长率为：","options":["0。","g。","n。","n + g。"]},"topics":["technology-growth"]},{"num":14,"type":"mc","question":"In the Solow model with technological progress, the steady-state growth rate of output per worker is:","options":["0.","g.","n.","n + g."],"answer":"B","images":null,"translation":{"question":"在具有技术进步的索洛模型中，人均产出的稳态增长率为：","options":["0。","g。","n。","n + g。"]},"topics":["technology-growth"]},{"num":15,"type":"mc","question":"In the Solow model with technological progress, the steady-state growth rate of total output is:","options":["0.","g.","n.","n + g."],"answer":"D","images":null,"translation":{"question":"在具有技术进步的索洛模型中，总产出的稳态增长率为：","options":["0。","g。","n。","n + g。"]},"topics":["technology-growth"]},{"num":16,"type":"mc","question":"Over the past 50 years in the United States:","options":["output per worker hour, capital stock per worker hour, the real wage, and the real rental price of capital have all increased about 2 percent per year.","output per worker hour, the real wage, and the real rental price of capital have all increased about 2 percent per year, whereas capital stock per worker hour has increased faster.","output per worker hour and the real wage have both increased about 2 percent per year, whereas capital stock per worker hour has increased faster and the real rental price of capital has remained about the same.","output per worker hour, the real wage, and capital stock per worker hour have all increased about 2 percent per year, whereas the real rental price of capital has remained about the same."],"answer":"D","images":null,"translation":{"question":"在过去 50 年里的美国：","options":["每工时产出、每工时资本存量、实际工资和资本的实际租赁价格都大约每年增长 2%。","每工时产出、实际工资和资本的实际租赁价格都大约每年增长 2%，而每工时资本存量增长更快。","每工时产出和实际工资都大约每年增长 2%，而每工时资本存量增长更快，资本的实际租赁价格大致保持不变。","每工时产出、实际工资和每工时资本存量都大约每年增长 2%，而资本的实际租赁价格大致保持不变。"]},"topics":["technology-growth"]},{"num":17,"type":"mc","question":"In the Solow model with technological progress, along the balanced growth path, by increasing the efficiency of labor at rate g:","options":["the real wage and the real rental price of capital both grow at rate g.","the real wage grows at rate g but the real rental price of capital is constant.","the real wage is constant but the real rental price of capital grows at rate g.","both the real wage and the real rental price of capital are constant."],"answer":"B","images":null,"translation":{"question":"在具有技术进步的索洛模型中，沿着平衡增长路径，通过以速率 g 提高劳动效率：","options":["实际工资和资本的实际租赁价格都以速率 g 增长。","实际工资以速率 g 增长，但资本的实际租赁价格不变。","实际工资不变，但资本的实际租赁价格以速率 g 增长。","实际工资和资本的实际租赁价格都不变。"]},"topics":["technology-growth"]},{"num":18,"type":"mc","question":"The balanced growth property of the Solow growth model with population growth and technological progress predicts which of the following sets of variables will grow at the same rate in the steady state?","options":["output per effective worker, capital per effective worker, real wage","output per worker, capital per worker, real wage","real rental price of capital, real wage, output per worker","capital–output ratio, output per worker, capital per worker"],"answer":"B","images":null,"translation":{"question":"具有人口增长和技术进步的索洛增长模型的平衡增长性质预测，在稳态下下列哪组变量将以相同的速率增长？","options":["每有效工人产出、每有效工人资本、实际工资","人均产出、人均资本、实际工资","资本的实际租赁价格、实际工资、人均产出","资本—产出比、人均产出、人均资本"]},"topics":["technology-growth"]},{"num":19,"type":"mc","question":"The Solow model predicts that two economies will converge if their economies have the same:","options":["capital stocks.","populations.","steady states.","production functions."],"answer":"C","images":null,"translation":{"question":"索洛模型预测，如果两个经济的 ______ 相同，它们将会趋同。","options":["资本存量","人口","稳态","生产函数"]},"topics":["technology-growth"]},{"num":20,"type":"mc","question":"Conditional convergence occurs when economies converge to:","options":["the same steady state as other economies.","the Golden Rule steady state.","the balanced-growth steady state.","their own individual steady states."],"answer":"D","images":null,"translation":{"question":"当经济趋同于 ______ 时，发生条件趋同。","options":["与其他经济相同的稳态","黄金律稳态","平衡增长稳态","它们各自自身的稳态"]},"topics":["technology-growth"]},{"num":21,"type":"mc","question":"If two economies are identical (including having the same saving rates, population growth rates, and efficiency of labor), but one economy has a smaller capital stock, then the steady-state level of income per worker in the economy with the smaller capital stock:","options":["will be at a lower level than in the steady state of the high capital economy.","will be at a higher level than in the steady state of the high capital economy.","will be at the same level as in the steady state of the high capital economy.","will be proportional to the ratio of the capital stocks in the two economies."],"answer":"C","images":null,"translation":{"question":"如果两个经济完全相同（包括有相同的储蓄率、人口增长率和劳动效率），但一个经济的资本存量较小，那么资本存量较小的经济的人均收入稳态水平：","options":["将低于高资本经济稳态的水平。","将高于高资本经济稳态的水平。","将与高资本经济稳态的水平相同。","将与两国资本存量之比成比例。"]},"topics":["technology-growth"]},{"num":22,"type":"mc","question":"If two economies are identical (with the same population growth rates and rates of technological progress), but one economy has a lower saving rate, then the steady-state level of income per worker in the economy with the lower saving rate:","options":["will be at a lower level than in the steady state of the high-saving economy.","will be at a higher level than in the steady state of the high-saving economy.","will be at the same level as in the steady state of the high-saving economy.","will grow at a slower rate than in the high-saving economy."],"answer":"A","images":null,"translation":{"question":"如果两个经济完全相同（人口增长率和技术进步率相同），但一个经济的储蓄率较低，那么储蓄率较低的经济的人均收入稳态水平：","options":["将低于高储蓄经济稳态的水平。","将高于高储蓄经济稳态的水平。","将与高储蓄经济稳态的水平相同。","将以比高储蓄经济更慢的速度增长。"]},"topics":["technology-growth"]},{"num":23,"type":"mc","question":"Empirical investigations into whether differences in income per person are the result of differences in the quantities of the factors of production available or differences in the efficiency with which the factors are employed typically find:","options":["a negative correlation between the quantity of factors and the efficiency of use.","a positive correlation between the quantity of factors and the efficiency of use.","no correlation between the quantity of factors and the efficiency of use.","large gaps between the quantity of factors accumulated and the efficiency of use."],"answer":"B","images":null,"translation":{"question":"关于人均收入差异是源于可获得生产要素数量的差异还是要素使用效率的差异，实证研究通常发现：","options":["要素数量与使用效率之间负相关。","要素数量与使用效率之间正相关。","要素数量与使用效率之间无相关性。","积累的要素数量与使用效率之间存在巨大差距。"]},"topics":["technology-growth"]},{"num":24,"type":"mc","question":"Hypotheses to explain the positive correlation between factor accumulation and production efficiency include each of the following except:","options":["the quality of a nation's institutions influences both factor accumulation and production efficiency.","capital accumulation causes greater production efficiency.","efficient economies make capital accumulation unnecessary.","an efficient economy encourages capital (including human capital) accumulation."],"answer":"C","images":null,"translation":{"question":"解释要素积累与生产效率之间正相关的假说包括以下所有，除了：","options":["一个国家制度的质量同时影响要素积累和生产效率。","资本积累导致更高的生产效率。","高效率的经济使资本积累变得不必要。","高效率的经济鼓励资本（包括人力资本）积累。"]},"topics":["technology-growth"]},{"num":25,"type":"mc","question":"International differences in income per person in accounting terms must be attributed to differences in ______ and/or ______.","options":["factor accumulation; production efficiency","constant returns to scale; the marginal product of capital","unemployment rates; depreciation rates","consumption; interest rates"],"answer":"A","images":null,"translation":{"question":"从核算角度看，各国人均收入的国际差异必须归因于 ______ 和/或 ______ 的差异。","options":["要素积累；生产效率","规模报酬不变；资本的边际产量","失业率；折旧率","消费；利率"]},"topics":["technology-growth"]},{"num":26,"type":"mc","question":"Differences in factor accumulation and/or differences in production efficiency must account for all international differences in:","options":["human capital and physical capital.","saving rates and population growth rate.","income per person.","labor efficiency."],"answer":"C","images":null,"translation":{"question":"要素积累的差异和/或生产效率的差异必然能解释所有的 ______ 国际差异。","options":["人力资本和物质资本","储蓄率和人口增长率","人均收入","劳动效率"]},"topics":["technology-growth"]},{"num":27,"type":"mc","question":"The majority of empirical evidence supports the hypothesis that economies that are open to trade _____ than comparable closed economies.","options":["grow more rapidly","have lower steady-state levels of income per worker due to foreign competition","have faster rates of population growth and technological progress","converge more slowly to a steady-state equilibrium"],"answer":"A","images":null,"translation":{"question":"多数经验证据支持这样的假说：对贸易开放的经济相比可比的封闭经济 ______。","options":["增长更快","由于外国竞争，人均收入的稳态水平更低","人口增长和技术进步的速度更快","更缓慢地趋同于稳态均衡"]},"topics":["growth-policy"]},{"num":28,"type":"mc","question":"If the marginal product of capital net depreciation equals 8 percent, the rate of growth of population equals 2 percent, and the rate of labor-augmenting technical progress equals 2 percent, to reach the Golden Rule level of the capital stock, the ____ rate in this economy must be _____.","options":["saving; increased","population growth; decreased","saving; decreased","population growth; increased"],"answer":"A","images":null,"translation":{"question":"如果资本边际产量扣除折旧后等于 8%，人口增长率等于 2%，劳动扩张型技术进步率等于 2%，那么要达到黄金律资本存量水平，该经济的 ______ 必须 ______。","options":["储蓄率；提高","人口增长率；降低","储蓄率；降低","人口增长率；提高"]},"topics":["technology-growth"]},{"num":29,"type":"mc","question":"If the marginal product of capital net of depreciation equals 10 percent and the rate of population growth equals 2 percent, then this economy will be at the Golden Rule steady state if the rate of technological progress equals _____ percent.","options":["0","2","8","10"],"answer":"C","images":null,"translation":{"question":"如果资本边际产量扣除折旧后等于 10%，人口增长率等于 2%，那么当技术进步率等于 _____ % 时，该经济将处于黄金律稳态。","options":["0","2","8","10"]},"topics":["technology-growth"]},{"num":30,"type":"mc","question":"Which of the following changes would bring the U.S. capital stock, currently below the Golden Rule level, closer to the steady-state, consumption-maximizing level?","options":["increasing the population growth rate","increasing the rate of capital depreciation","increasing the rate of technological progress","increasing the saving rate"],"answer":"D","images":null,"translation":{"question":"以下哪项变化会使目前低于黄金律水平的美国资本存量更接近消费最大化的稳态水平？","options":["提高人口增长率","提高资本折旧率","提高技术进步率","提高储蓄率"]},"topics":["growth-policy"]},{"num":31,"type":"mc","question":"Other things being equal, all of the following government policies are likely to increase national saving except:","options":["decreasing taxes on savings accounts.","running a budget deficit.","running a budget surplus.","retiring part of the national debt."],"answer":"B","images":null,"translation":{"question":"在其他条件相同的情况下，以下政府政策都可能增加国民储蓄，除了：","options":["降低储蓄账户的税收。","出现预算赤字。","出现预算盈余。","偿还部分国债。"]},"topics":["growth-policy"]},{"num":32,"type":"mc","question":"Economic research shows that ______ in explaining international differences in living standards.","options":["physical capital is more important than human capital","human capital is at least as important as physical capital","human capital is much more important than physical capital","infrastructure is the most important factor"],"answer":"B","images":null,"translation":{"question":"经济研究表明，在解释国际生活水平差异方面，______。","options":["物质资本比人力资本更重要","人力资本至少与物质资本同等重要","人力资本比物质资本重要得多","基础设施是最重要的因素"]},"topics":["growth-policy"]},{"num":33,"type":"mc","question":"A possible externality associated with the process of accumulating new capital is that:","options":["a reduction in labor productivity may occur.","new production processes may be devised.","old capital may be made more productive.","the government may need to adopt an industrial policy."],"answer":"B","images":null,"translation":{"question":"与新资本积累过程相关的一种可能外部性是：","options":["可能发生劳动生产率下降。","可能设计出新的生产流程。","旧资本可能变得更有效率。","政府可能需要采取产业政策。"]},"topics":["growth-policy"]},{"num":34,"type":"mc","question":"The type of legal system and the level of corruption in a country have been found to be:","options":["unrelated to the rate of economic growth in a country.","significant determinants of the rate of economic growth in a country.","important topics for political discussion, but not economic explanations of growth.","important variables explaining the Golden Rule level of capital."],"answer":"B","images":null,"translation":{"question":"研究发现，一个国家的法律体系类型和腐败水平：","options":["与该国经济增长率无关。","是该国经济增长率的重要决定因素。","是重要的政治讨论议题，但不是增长的经济学解释。","是解释黄金律资本水平的重要变量。"]},"topics":["growth-policy"]},{"num":35,"type":"mc","question":"One explanation for greater economic development in moderate versus tropical climates is that institutions established by colonial settlers in moderate climates ______, while institutions established by colonists in tropical climates ______.","options":["were based on English common law; were based on the Napoleonic Code","were based on the Napoleonic Code; were based on English common law","protected property rights; were extractive and authoritarian","were extractive and authoritarian; protected property rights"],"answer":"C","images":null,"translation":{"question":"温带气候比热带气候有更大经济发展的一个解释是，殖民者在温带气候建立的制度 ______，而殖民者在热带气候建立的制度 ______。","options":["基于英国普通法；基于拿破仑法典","基于拿破仑法典；基于英国普通法","保护产权；是掠夺性和威权主义的","是掠夺性和威权主义的；保护产权"]},"topics":["growth-policy"]},{"num":36,"type":"mc","question":"The recent worldwide slowdown in economic growth began in the early:","options":["1960s.","1970s.","1980s.","1990s."],"answer":"B","images":null,"translation":{"question":"最近世界范围的经济增长放缓始于 ______ 年代初。","options":["20世纪60","20世纪70","20世纪80","20世纪90"]},"topics":["technology-growth"]},{"num":37,"type":"mc","question":"If productivity growth in the United States had remained at its level before the recent productivity slowdown, real income today would be more than ______ percent higher.","options":["10","20","30","40"],"answer":"B","images":null,"translation":{"question":"如果美国的生产率增长保持在最近生产率放缓之前的水平，今天的实际收入将高出 ______ % 以上。","options":["10","20","30","40"]},"topics":["technology-growth"]},{"num":38,"type":"mc","question":"The productivity slowdown that began in the 1970s has been attributed, at least partly, to each of the following except:","options":["running out of new ideas about how to produce.","a deterioration in the quality of education.","a decline in the number of workers in the labor force.","a lower average level of experience among workers."],"answer":"C","images":null,"translation":{"question":"始于 20 世纪 70 年代的生产率放缓至少部分被归因于以下所有，除了：","options":["关于如何生产的新想法枯竭。","教育质量恶化。","劳动力中工人数量减少。","工人的平均经验水平降低。"]},"topics":["technology-growth"]},{"num":39,"type":"mc","question":"Increases in the rate of growth of income per person in the United States in the mid-1990s is mostly likely the result of:","options":["increases in human capital.","increases in physical capital.","advances in information technology.","an increase in the saving rate."],"answer":"C","images":null,"translation":{"question":"20 世纪 90 年代中期美国人均收入增长率上升最可能是 ______ 的结果。","options":["人力资本增加","物质资本增加","信息技术进步","储蓄率上升"]},"topics":["technology-growth"]},{"num":40,"type":"mc","question":"Endogenous growth theory rejects the assumption of exogenous:","options":["production functions.","rates of depreciation.","population growth rates.","technological change."],"answer":"D","images":null,"translation":{"question":"内生增长理论拒绝 ______ 外生的假设。","options":["生产函数","折旧率","人口增长率","技术变化"]},"topics":["endogenous-growth"]},{"num":41,"type":"mc","question":"In the Solow growth model, capital exhibits ______ returns. In the basic endogenous growth model, capital exhibits ______ returns.","options":["constant; diminishing","constant; constant","diminishing; constant","diminishing; diminishing"],"answer":"C","images":null,"translation":{"question":"在索洛增长模型中，资本呈现 ______ 报酬。在基本内生增长模型中，资本呈现 ______ 报酬。","options":["不变；递减","不变；不变","递减；不变","递减；递减"]},"topics":["endogenous-growth"]},{"num":42,"type":"mc","question":"In the basic endogenous growth model, income can grow forever—even without exogenous technological progress—because:","options":["the saving rate equals the rate of depreciation.","the saving rate exceeds the rate of depreciation.","capital does not exhibit diminishing returns.","capital exhibits diminishing returns."],"answer":"C","images":null,"translation":{"question":"在基本内生增长模型中，即使没有外生技术进步，收入也能永远增长，因为：","options":["储蓄率等于折旧率。","储蓄率超过折旧率。","资本不呈现报酬递减。","资本呈现报酬递减。"]},"topics":["endogenous-growth"]},{"num":43,"type":"mc","question":"The endogenous growth model's assumption of constant returns to capital is more plausible if capital is defined to include:","options":["plant and equipment.","knowledge.","depreciation.","technology."],"answer":"B","images":null,"translation":{"question":"如果资本被定义为包括 ______，内生增长模型关于资本报酬不变的假设就更合理。","options":["厂房和设备","知识","折旧","技术"]},"topics":["endogenous-growth"]},{"num":44,"type":"mc","question":"If Y is output, K is capital, u is the fraction of the labor force in universities, L is labor, and E is the stock of knowledge, and the production Y = F (K,(1 – u) EL) exhibits constant returns to scale, then output (Y) will double if:","options":["K is doubled.","K and u are doubled.","K and E are doubled.","L is doubled."],"answer":"C","images":null,"translation":{"question":"如果 Y 是产出，K 是资本，u 是劳动力中在大学的比例，L 是劳动，E 是知识存量，且生产函数 Y = F(K,(1 – u)EL) 呈现规模报酬不变，那么当 ______ 时产出 (Y) 将翻倍。","options":["K 翻倍","K 和 u 翻倍","K 和 E 翻倍","L 翻倍"]},"topics":["endogenous-growth"]},{"num":45,"type":"mc","question":"In the two-sector endogenous growth model, the saving rate (s) affects the steady-state:","options":["level of income.","growth rate of income.","level of income and growth rate of income.","growth rate of the stock of knowledge."],"answer":"A","images":null,"translation":{"question":"在两部门内生增长模型中，储蓄率 (s) 影响稳态的：","options":["收入水平。","收入增长率。","收入水平和收入增长率。","知识存量的增长率。"]},"topics":["endogenous-growth"]},{"num":46,"type":"mc","question":"In the two-sector endogenous growth model, the fraction of labor in universities (u) affects the steady-state:","options":["level of income.","growth rate of income.","level of income and growth rate of income.","level of income, growth rate of income, and growth rate of the stock of knowledge."],"answer":"D","images":null,"translation":{"question":"在两部门内生增长模型中，劳动力中在大学的比例 (u) 影响稳态的：","options":["收入水平。","收入增长率。","收入水平和收入增长率。","收入水平、收入增长率和知识存量的增长率。"]},"topics":["endogenous-growth"]},{"num":47,"type":"mc","question":"In the two-sector endogenous growth model, income growth persists because:","options":["the production function shifts exogenously.","the saving rate exceeds the rate of depreciation.","the creation of knowledge in universities never slows down.","the fraction of the labor force in universities is large."],"answer":"C","images":null,"translation":{"question":"在两部门内生增长模型中，收入增长持续存在是因为：","options":["生产函数外生地移动。","储蓄率超过折旧率。","大学中知识的创造从未减慢。","劳动力中在大学的比例很大。"]},"topics":["endogenous-growth"]},{"num":48,"type":"mc","question":"In the two-sector endogenous growth model, the steady-state stock of physical capital is determined by _____, and the growth in the stock of knowledge is determined by _____.","options":["the fraction of labor in universities; the saving rate","the efficiency of labor; the saving rate","the production function; the efficiency of labor","the saving rate; the fraction of labor in universities"],"answer":"D","images":null,"translation":{"question":"在两部门内生增长模型中，稳态物质资本存量由 ______ 决定，而知识存量的增长由 ______ 决定。","options":["劳动力中在大学的比例；储蓄率","劳动效率；储蓄率","生产函数；劳动效率","储蓄率；劳动力中在大学的比例"]},"topics":["endogenous-growth"]},{"num":49,"type":"mc","question":"Empirical results justify substantial government subsidies to research based on the finding that the:","options":["private return to research is greater than the social return to research.","private return to research is approximately equal to the social return to research.","private return to research is less than the social return to research.","private return to research is positive, but the social return to research is negative."],"answer":"C","images":null,"translation":{"question":"实证结果基于以下发现证明了政府对研究的大规模补贴是合理的：","options":["研究的私人回报大于社会回报。","研究的私人回报约等于社会回报。","研究的私人回报小于社会回报。","研究的私人回报为正，但社会回报为负。"]},"topics":["endogenous-growth"]},{"num":50,"type":"mc","question":"Schumpeter's thesis of “creative destruction” is an explanation of economic progress resulting from:","options":["using up scarce natural resources to create new products.","breaking down barriers to trade and development.","new product producers driving incumbent producers out of business.","creating new methods to destroy the environment."],"answer":"C","images":null,"translation":{"question":"熊彼特（Schumpeter）的“创造性破坏”论题是对由 ______ 所产生的经济进步的一种解释。","options":["耗尽稀缺自然资源以创造新产品","打破贸易和发展壁垒","新产品生产者把在位生产者挤出市场","创造破坏环境的新方法"]},"topics":["endogenous-growth"]},{"num":51,"type":"mc","question":"When capital increases by DK units, output increases by:","options":["DL units.","MPL × DL units.","DK units.","MPK × DK units."],"answer":"D","images":null,"translation":{"question":"当资本增加 ΔK 单位时，产出增加：","options":["ΔL 单位。","MPL × ΔL 单位。","ΔK 单位。","MPK × ΔK 单位。"]},"topics":["technology-growth"]},{"num":52,"type":"mc","question":"When capital increases by DK units and labor increases by DL units, output (DY) increases by:","options":["DK + DL units.","MPL + MPK units.","(MPK × DK) + (MPL × DL) units.","(MPL × DK) + (MPK × DK) units."],"answer":"C","images":null,"translation":{"question":"当资本增加 ΔK 单位、劳动增加 ΔL 单位时，产出 (ΔY) 增加：","options":["ΔK + ΔL 单位。","MPL + MPK 单位。","(MPK × ΔK) + (MPL × ΔL) 单位。","(MPL × ΔK) + (MPK × ΔK) 单位。"]},"topics":["technology-growth"]},{"num":53,"type":"mc","question":"Total factor productivity may be measured by:","options":["subtracting the rate of growth of capital input and the rate of growth of labor input from the rate of growth of output.","subtracting the rate of growth of capital input, multiplied by capital's share of output, plus the rate of growth of labor input, multiplied by labor's share of output, from the rate of growth of output.","adding the rate of growth of capital input to the rate of growth of labor input.","adding the rate of growth of capital input, multiplied by capital's share of output, to the rate of growth of labor input, multiplied by labor's share of output."],"answer":"B","images":null,"translation":{"question":"全要素生产率可以通过 ______ 来衡量。","options":["从产出增长率中减去资本投入增长率和劳动投入增长率。","从产出增长率中减去（资本投入增长率乘以资本的产出份额）加上（劳动投入增长率乘以劳动的产出份额）。","把资本投入增长率加到劳动投入增长率上。","把（资本投入增长率乘以资本的产出份额）加到（劳动投入增长率乘以劳动的产出份额）上。"]},"topics":["technology-growth"]},{"num":54,"type":"mc","question":"The Solow residual measures the portion of output growth that cannot be explained by growth in:","options":["capital and labor.","technology.","the money supply.","the saving rate."],"answer":"A","images":null,"translation":{"question":"索洛余值衡量的是产出增长中无法由 ______ 的增长解释的部分。","options":["资本和劳动","技术","货币供给","储蓄率"]},"topics":["technology-growth"]},{"num":55,"type":"mc","question":"Prescott interpreted fluctuations in the Solow residual as evidence that:","options":["technology shocks are an important source of short-run economic fluctuations.","the Solow growth model does not converge to a steady-state equilibrium.","endogenous growth models are better explanations of growth than the Solow model.","the marginal product of labor fluctuates more than the marginal product of capital."],"answer":"A","images":null,"translation":{"question":"普雷斯科特（Prescott）将索洛余值的波动解释为 ______ 的证据。","options":["技术冲击是短期经济波动的一个重要来源","索洛增长模型不会收敛到稳态均衡","内生增长模型比索洛模型更能解释增长","劳动的边际产量比资本的边际产量波动更大"]},"topics":["technology-growth"]},{"num":56,"type":"mc","question":"An alternative to Prescott's explanation of the cyclical behavior of the Solow residual is that it is the result of:","options":["labor hoarding in recession and cyclical mismeasurement of output.","bad weather, strict environmental regulations, and oil shocks.","declines in capital utilization and labor force participation.","technology shocks."],"answer":"A","images":null,"translation":{"question":"对普雷斯科特关于索洛余值周期性行为的解释的一种替代解释是，它是 ______ 的结果。","options":["衰退中的劳动储备和产出的周期性度量误差","恶劣天气、严格的环境法规和石油冲击","资本利用率和劳动力参与率的下降","技术冲击"]},"topics":["technology-growth"]},{"num":57,"type":"mc","question":"Labor hoarding refers to:","options":["keeping workers in low-wage jobs in order to reduce labor costs.","using less capital in production so that more workers will have jobs.","continuing to employ workers during a recession to ensure they will be available in the recovery.","contractually preventing workers from obtaining jobs with competing firms."],"answer":"C","images":null,"translation":{"question":"劳动储备（labor hoarding）指的是：","options":["把工人留在低薪岗位上以降低劳动成本。","在生产中使用更少的资本以便更多工人有工作。","在衰退期间继续雇用工人，以确保他们在复苏时可用。","通过合同阻止工人去竞争性企业获得工作。"]},"topics":["technology-growth"]},{"num":58,"type":"mc","question":"The Solow residual equals the percentage change in output:","options":["plus the percentage changes in factor inputs weighted by each factor's share of output.","minus the percentage changes in prices of factor inputs.","minus the percentage changes in factor inputs weighted by each factor's share of output.","plus the percentage changes in each factor's share of output."],"answer":"C","images":null,"translation":{"question":"索洛余值等于产出的百分比变化：","options":["加上各要素投入的百分比变化（按各要素的产出份额加权）。","减去要素投入价格的百分比变化。","减去各要素投入的百分比变化（按各要素的产出份额加权）。","加上各要素产出份额的百分比变化。"]},"topics":["technology-growth"]},{"num":59,"type":"mc","question":"The Solow residual will fall even if technology has not changed if there is:","options":["population growth.","endogenous growth.","labor hoarding.","balanced growth."],"answer":"C","images":null,"translation":{"question":"如果存在 ______，即使技术没有变化，索洛余值也会下降。","options":["人口增长","内生增长","劳动储备","平衡增长"]},"topics":["technology-growth"]},{"num":60,"type":"mc","question":"If the production function is y = k1/2, the steady-state value of y is:","options":["y = ((s + g) / (d + n))1/2.","y = (s + g) / (d + n).","y = (2 / (d + n + g))1/2.","y = s / (d + n + g)."],"answer":"D","images":null,"translation":{"question":"如果生产函数为 y = k^(1/2)，则 y 的稳态值为：","options":["y = ((s + g)/(δ + n))^(1/2)。","y = (s + g)/(δ + n)。","y = (2/(δ + n + g))^(1/2)。","y = s/(δ + n + g)。"]},"topics":["technology-growth"]},{"num":61,"type":"mc","question":"If the Japanese production function is Cobb–Douglas with capital share 0.3, output growth is 3 percent per year, depreciation is 4 percent per year, and the capital–output ratio is 2.5, the saving rate that is consistent with steady-state growth is:","options":["12.5 percent.","14 percent.","17.5 percent.","20 percent."],"answer":"C","images":null,"translation":{"question":"如果日本的生产函数是柯布—道格拉斯型的，资本份额为 0.3，产出增长率为每年 3%，折旧率为每年 4%，资本—产出比为 2.5，则与稳态增长一致的储蓄率为：","options":["12.5%。","14%。","17.5%。","20%。"]},"topics":["technology-growth"]},{"num":62,"type":"mc","question":"In a steady state with population growth and technological progress:","options":["the capital share of income increases.","the labor share of income increases.","the capital share of income, in some cases, increases, and sometimes the labor share increases.","the capital and labor shares of income are constant."],"answer":"D","images":null,"translation":{"question":"在人口增长和技术进步的稳态下：","options":["收入的资本份额增加。","收入的劳动份额增加。","有时收入的资本份额增加，有时劳动份额增加。","收入的资本份额和劳动份额保持不变。"]},"topics":["technology-growth"]},{"num":63,"type":"mc","question":"In a steady state with population growth and technological progress:","options":["the real rental price of capital is constant and the real wage grows at the rate of technological progress.","the real rental price of capital grows at the rate of technological progress and the real wage is constant.","both the real rental price of capital and the real wage grow at the rate of technological progress.","both the real rental price of capital and the real wage are constant."],"answer":"A","images":null,"translation":{"question":"在人口增长和技术进步的稳态下：","options":["资本的实际租赁价格不变，实际工资以技术进步率增长。","资本的实际租赁价格以技术进步率增长，实际工资不变。","资本的实际租赁价格和实际工资都以技术进步率增长。","资本的实际租赁价格和实际工资都不变。"]},"topics":["technology-growth"]},{"num":64,"type":"mc","question":"In comparing two countries with different levels of education but the same saving rate, population growth, and rate of technological progress, one would expect the more highly educated country to have:","options":["a higher growth rate of total income and a higher real wage.","a higher growth rate of total income and the same real wage.","the same growth rate of total income and a higher real wage.","the same growth rate of total income and the same real wage."],"answer":"C","images":null,"translation":{"question":"在比较两个教育水平不同但储蓄率、人口增长和技术进步率相同的国家时，人们会预期教育程度更高的国家有：","options":["更高的总收入增长率和更高的实际工资。","更高的总收入增长率和相同的实际工资。","相同的总收入增长率和更高的实际工资。","相同的总收入增长率和相同的实际工资。"]},"topics":["technology-growth"]},{"num":65,"type":"mc","question":"If the per-worker production function is y = Ak, where A is a positive constant, then the marginal product of capital:","options":["increases as k increases.","is constant as k increases.","decreases as k increases.","cannot be measured in this case."],"answer":"B","images":null,"translation":{"question":"如果人均生产函数为 y = Ak，其中 A 是正常数，则资本的边际产量：","options":["随着 k 增加而增加。","随着 k 增加而保持不变。","随着 k 增加而减少。","在这种情况下无法度量。"]},"topics":["endogenous-growth"]},{"num":66,"type":"mc","question":"If the production function is Y = AK2/3L1/3 in the land of Antegria, and the labor force increases by 5 percent while capital is constant, labor productivity, measured by Y / L, will:","options":["increase by 3.33 percent.","increase by 1.67 percent.","decrease by 1.67 percent.","decrease by 3.33 percent."],"answer":"D","images":null,"translation":{"question":"如果在安特格里亚国（Antegria）生产函数为 Y = AK^(2/3)L^(1/3)，劳动力增加 5% 而资本不变，则以 Y / L 衡量的劳动生产率将：","options":["增加 3.33%。","增加 1.67%。","减少 1.67%。","减少 3.33%。"]},"topics":["technology-growth"]},{"num":67,"type":"mc","question":"The rate of growth of labor productivity (Y / L) may be expressed as the rate of growth of total factor productivity:","options":["plus the capital share multiplied by the rate of growth of the capital–labor ratio.","minus the capital share multiplied by the rate of growth of the capital–labor ratio.","plus the rate of growth of capital productivity.","minus the rate of growth of capital productivity."],"answer":"A","images":null,"translation":{"question":"劳动生产率 (Y / L) 的增长率可以表示为全要素生产率的增长率：","options":["加上资本份额乘以资本—劳动比的增长率。","减去资本份额乘以资本—劳动比的增长率。","加上资本生产率的增长率。","减去资本生产率的增长率。"]},"topics":["technology-growth"]},{"num":68,"type":"mc","question":"Assume that an economy described by the Solow model is in a steady state with output and capital growing at 3 percent and labor growing at 1 percent. The capital share is 0.3. The growth-accounting equation indicates that the contributions to growth of capital, labor, and total factor productivity are:","options":["0 percent, 1 percent, and 2 percent, respectively.","0.3 percent, 0.7 percent, and 2 percent, respectively.","0.9 percent, 0.7 percent, and 1.4 percent, respectively.","1.8 percent, 0.3 percent, and 0.9 percent, respectively."],"answer":"C","images":null,"translation":{"question":"假设一个由索洛模型描述的经济处于稳态，产出和资本以 3% 增长，劳动以 1% 增长。资本份额为 0.3。增长核算方程表明，资本、劳动和全要素生产率对增长的贡献分别为：","options":["0%、1% 和 2%。","0.3%、0.7% 和 2%。","0.9%、0.7% 和 1.4%。","1.8%、0.3% 和 0.9%。"]},"topics":["technology-growth"]},{"num":69,"type":"sa","question":"Assume that a country's production function is Y = AK0.3L0.7. The ratio of capital to output is 3, the growth rate of output is 3 percent, and the depreciation rate is 4 percent. Capital is paid its marginal product. a. What is the marginal product of capital in this situation? b. If the economy is in a steady state, what must be the saving rate? c. What is the marginal product of capital if the economy reaches the Golden Rule level of capital? d. What must the saving rate be to achieve the Golden Rule level of capital?","options":null,"answer":null,"images":null,"translation":{"question":"假设一个国家的生产函数为 Y = AK^0.3 L^0.7。资本—产出比为 3，产出增长率为 3%，折旧率为 4%。资本按其边际产量获得报酬。a. 在这种情形下资本的边际产量是多少？b. 如果经济处于稳态，储蓄率必须是多少？c. 如果经济达到黄金律资本水平，资本的边际产量是多少？d. 要达到黄金律资本水平，储蓄率必须是多少？","options":null},"topics":["technology-growth"],"answer_ref":"a. 资本收入份额 0.3，K/Y = 3 → MPK = 资本份额×Y/K = 0.3/3 = 0.10。b. 稳态条件 s = (n+g+δ)(K/Y)。总产出增长 n+g = 3%，故 s = (0.03+0.04)×3 = 0.21（21%）。c. 若经济处于黄金律稳态：MPK = n+g+δ = 0.07。当前 MPK=0.10 > 0.07，说明资本尚少于黄金律水平，提高储蓄率可增加稳态消费。"},{"num":70,"type":"sa","question":"Use the data in the exhibit to complete the two tasks below. Exhibit: Factors of Production Data Period Y K L Share of Labor in Output 1 100 200 100 0.5 1 106 205 102 0.5 3 111 210 104 0.5 4 110.5 215 104 0.5 5 110 220 104 0.5 a. Compute and report the value of growth in total factor productivity ((At – At–1)/At–1) in each period from periods 2 through 5. Assume that the value of A is 1.000 in period 1. Report the value of A in each period. b. Does the value of A rise in each period? If it declines, do you think this decline is because technological progress works backward? If so, explain your answer. If not, provide another explanation.","options":null,"answer":null,"images":null,"translation":{"question":"使用下表中的数据完成以下两项任务。生产要素数据：时期 | Y | K | L | 劳动在产出中的份额：1 | 100 | 200 | 100 | 0.5；2 | 106 | 205 | 102 | 0.5；3 | 111 | 210 | 104 | 0.5；4 | 110.5 | 215 | 104 | 0.5；5 | 110 | 220 | 104 | 0.5。a. 计算并报告从第 2 期到第 5 期每一期全要素生产率的增长 ((At – At–1)/At–1) 的值。假设第 1 期 A 的值为 1.000。报告每一期 A 的值。b. A 的值在每一期都上升吗？如果它下降，你认为这种下降是因为技术进步倒退吗？如果是，请解释你的答案。如果不是，请提供另一种解释。","options":null},"topics":["technology-growth"],"answer_ref":"用增长核算 ΔA/A = ΔY/Y − 资本份额×ΔK/K − 劳动份额×ΔL/L，份额各0.5：第2期：Y+6%、K+2.5%、L+2% → TFP增长 ≈ 6 − 1.25 − 1 = 3.75%。第3期：Y+4.72%、K+2.44%、L+1.96% → ≈ 4.72 − 1.22 − 0.98 = 2.52%。第4期：Y−0.45%、K+2.38%、L 不变 → ≈ −0.45 − 1.19 = −1.64%。第5期：Y−0.90%、K+2.33% → ≈ −0.90 − 1.16 = −2.06%。A 的绝对水平由 A = Y/(K^0.5 L^0.5) 逐年递推（第1期给定为1.000），TFP 增长率由正转负说明效率在恶化。"},{"num":71,"type":"sa","question":"Suppose a government is able to permanently reduce its budget deficit. Use the Solow growth model of Chapter 9 to graphically illustrate the impact of a permanent government deficit reduction on the steady-state capital–labor ratio and the steady-state level of output per worker. Be sure to label the: a. axes; b. curves; c. initial steady-state levels; d. terminal steady-state levels; and e. the direction curves shift.","options":null,"answer":null,"images":null,"translation":{"question":"假设一个政府能够永久减少其预算赤字。用第 9 章的索洛增长模型以图形方式说明永久性政府赤字减少对稳态资本—劳动比和稳态人均产出水平的影响。务必标注：a. 坐标轴；b. 曲线；c. 初始稳态水平；d. 最终稳态水平；e. 曲线移动的方向。","options":null},"topics":["growth-policy"],"answer_ref":"图：横轴 k，纵轴 y 及投资/收支相抵投资。赤字削减→公共储蓄→国民储蓄 s 上升→s·f(k) 曲线上旋→与 (n+g+δ)k 的交点由 k₁* 右移至 k₂*，y* 相应上升。过渡期内人均产出增长暂时加快，但稳态增长率（=g）不变——政策提高的是水平，不是长期增长率。"},{"num":72,"type":"sa","question":"Suppose a government is able to impose controls that limit the number of children people can have. Use the Solow growth model of Chapter 9 to graphically illustrate the impact of the slower rate of population growth on the steady-state capital–labor ratio and the steady-state level of output per worker. Be sure to label the: a. axes; b. curves; c. initial steady-state levels; d. terminal steady-state levels; and e. the direction curves shift.","options":null,"answer":null,"images":null,"translation":{"question":"假设一个政府能够实施限制人们生育子女数量的管制措施。用第 9 章的索洛增长模型以图形方式说明人口增长放缓对稳态资本—劳动比和稳态人均产出水平的影响。务必标注：a. 坐标轴；b. 曲线；c. 初始稳态水平；d. 最终稳态水平；e. 曲线移动的方向。","options":null},"topics":["growth-policy"],"answer_ref":"图：生育控制使 n 下降→(n+δ)k 线变缓→与 s·f(k) 交于更高的 k* 与 y*。结论：稳态人均资本和人均产出水平上升；稳态增长率不变（人均产出增长仍为零，无技术进步时）；总产出增长率由原来的 n 降至更低的 n。"},{"num":73,"type":"sa","question":"Two countries, Highland and Lowland, are described by the Solow growth model. Both countries are identical, except that the rate of labor-augmenting technological progress is higher in Highland than in Lowland. a. In which country is the steady-state growth rate of output per effective worker higher? b. In which country is the steady-state growth rate of total output higher? c. Does the Solow growth model predict that the two economies will converge to the same steady state?","options":null,"answer":null,"images":null,"translation":{"question":"高地国（Highland）和低地国（Lowland）两个国家由索洛增长模型描述。两国完全相同，只是高地的劳动扩张型技术进步率高于低地。a. 哪个国家的每有效工人产出的稳态增长率更高？b. 哪个国家的总产出的稳态增长率更高？c. 索洛增长模型是否预测这两个经济会趋同于相同的稳态？","options":null},"topics":["technology-growth"],"answer_ref":"a. 相同——稳态中每有效工人产出的增长率都为零。b. Highland 更高——总产出增长率 = n+g，其 g 更大。c. 不，索洛模型不预测各国增长率趋同：稳态增长率由外生参数（n、g）决定且可永久不同；只有水平上有条件收敛。"},{"num":74,"type":"sa","question":"Based on the Solow growth model with population growth and labor-augmenting technological progress, explain how each of the following policies would affect the steady-state level and steady-state growth rate of total output per person: a. a reduction in the government's budget deficit b. grants to support research and development c. tax incentives to increase private saving d. greater protection of private property rights","options":null,"answer":null,"images":null,"translation":{"question":"基于具有人口增长和劳动扩张型技术进步的索洛增长模型，解释以下每项政策将如何影响人均总产出的稳态水平和稳态增长率：a. 减少政府预算赤字；b. 支持研发的拨款；c. 增加私人储蓄的税收激励；d. 加强对私人产权的保护。","options":null},"topics":["growth-policy"],"answer_ref":"a. 削减赤字：提高储蓄率→人均产出水平上升；稳态增长率不变。b. 研发资助：提高技术进步率 g→人均产出水平与稳态增长率都提高（唯一持久的增长效应）。c. 储蓄激励：水平上升，稳态增长率不变。d. 贸易保护：索洛框架下不影响稳态增长率，且因资源配置效率下降可能降低产出水平。"},{"num":75,"type":"sa","question":"Explain how the Solow growth model differs from models of endogenous growth with respect to: a. the sources of technological progress. b. returns to capital.","options":null,"answer":null,"images":null,"translation":{"question":"从以下方面解释索洛增长模型与内生增长模型有何不同：a. 技术进步的来源。b. 资本的报酬。","options":null},"topics":["endogenous-growth"],"answer_ref":"a. 技术来源：索洛模型中技术进步是外生的（给定 g，不知从何而来）；内生增长模型中技术由模型内部决定——研发、人力资本投资、干中学等经济活动创造知识。b. 资本回报：索洛模型中资本（人均）边际报酬递减，故增长最终停滞，需外生技术进步维持增长；内生模型（如 AK 模型）中广义资本报酬不变，储蓄与投资本身即可产生持续增长。"},{"num":76,"type":"sa","question":"Income per person exceeds $25,000 in many countries but it is below $1,000 per person in many other countries. Based on the Solow growth model, suggest at least four possible explanations for this gap in living standards.","options":null,"answer":null,"images":null,"translation":{"question":"在许多国家人均收入超过 25,000 美元，但在其他许多国家人均收入低于 1,000 美元。基于索洛增长模型，为这一生活水平差距提出至少四种可能的解释。","options":null},"topics":["technology-growth"],"answer_ref":"可能的解释（任答四点）：① 储蓄率不同——高储蓄国家积累了更多人均资本；② 人口增长率不同——高 n 摊薄了人均资本；③ 人力资本（教育、健康）积累不同；④ 制度与政策质量不同——产权保护、法治、政治稳定、政府效率决定资本的使用效率；⑤ 对外开放与技术获取程度不同。模型提示：差距主要来自稳态参数的差异，而非单纯资本量。"},{"num":77,"type":"sa","question":"The economy of Glovania can be described by the Solow growth model. At the steady state, in Glovania the labor force grows at 3 percent per year, labor-augmenting technology increases at 2 percent per year, the saving rate is 15 percent per year, and the rate of capital depreciation is 10 percent per year. Choosing from among the following variables—output per effective worker, output per worker, total output, labor force, capital per worker, and capital per effective worker—which variables will be growing at a: a. 2 percent rate? b. 3 percent rate? c. 5 percent rate? d. 0 percent rate?","options":null,"answer":null,"images":null,"translation":{"question":"格洛瓦尼亚国（Glovania）的经济可以用索洛增长模型描述。在稳态下，格洛瓦尼亚的劳动力每年增长 3%，劳动扩张型技术每年提高 2%，储蓄率为每年 15%，资本折旧率为每年 10%。从以下变量中选择——每有效工人产出、人均产出、总产出、劳动力、人均资本和每有效工人资本——哪些变量将以以下速率增长：a. 2% 速率？b. 3% 速率？c. 5% 速率？d. 0% 速率？","options":null},"topics":["technology-growth"],"answer_ref":"稳态增长率三档：每有效工人产出 = 0（不增长）；人均（每工人）产出 = g = 2%；总产出 = n+g = 5%。各水平变量分别按各自口径以相应速率永续增长。"},{"num":78,"type":"sa","question":"What is the difference between convergence and conditional convergence with respect to predictions of the Solow growth model? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"就索洛增长模型的预测而言，趋同与条件趋同有什么区别？请解释。","options":null},"topics":["technology-growth"],"answer_ref":"收敛：穷国比富国增长更快，最终趋于相同收入水平。条件收敛：各国只向各自的稳态收敛——由于储蓄率、人口增长率、技术参数不同，稳态水平各异；距离自身稳态越远的国家增长越快。换言之，结构相似的国家才互相收敛，结构不同的国家收入差距可永久存在。"},{"num":79,"type":"sa","question":"Explain why a higher savings rate generates both positive and negative impacts on steady-state consumption per worker in the Solow growth model with population growth and technological change.","options":null,"answer":null,"images":null,"translation":{"question":"在具有人口增长和技术变化的索洛增长模型中，请解释为什么更高的储蓄率对稳态人均消费既有正面影响又有负面影响。","options":null},"topics":["technology-growth"],"answer_ref":"正面：储蓄多→资本多→人均产出多→消费的物质基础更雄厚。负面：更多储蓄意味着当前消费更少（资源被用于投资而非消费）；同时更大的资本存量要求更多的折旧与收支相抵投资去维持。低于黄金律时正面效应占优（提高储蓄可增加稳态消费），高于黄金律时负面效应占优。"},{"num":80,"type":"sa","question":"Suggest three explanations for the productivity slowdown experienced since 1972.","options":null,"answer":null,"images":null,"translation":{"question":"为自 1972 年以来经历的生产率放缓提出三种解释。","options":null},"topics":["technology-growth"],"answer_ref":"三种解释：① 石油冲击——1973、1979 年油价暴涨打乱了生产体系，能耗型产业受重创；② 劳动力构成变化——婴儿潮一代和大量女性进入劳动力市场，新工人经验不足，拉低了平均生产率；③ 度量问题——经济向服务业转移，产品质量改进（电脑、医疗）难以准确计入产出，实际生产率被低估。"},{"num":81,"type":"sa","question":"a. What is the Solow residual? b. Compare Prescott's interpretation of the fluctuations of the Solow residual over the business cycle with more standard explanations of these fluctuations.","options":null,"answer":null,"images":null,"translation":{"question":"a. 什么是索洛余值？b. 比较普雷斯科特对索洛余值在经济周期中波动的解释与对这些波动的更标准解释。","options":null},"topics":["technology-growth"],"answer_ref":"a. 索洛残差是产出增长中不能用资本和劳动投入增长解释的部分，即全要素生产率的增长：ΔA/A = ΔY/Y − αΔK/K − (1−α)ΔL/L。b. 普雷斯科特（实际经济周期理论）认为残差波动反映真实技术冲击，是经济周期的驱动者。更标准的解释：残差度量有误——衰退期资本与劳动的利用强度下降（设备闲置、劳动 hoarding、工时缩短），投入减少未被投入量指标捕捉，表现为\"生产率下降\"，而非技术真的退步。"},{"num":82,"type":"sa","question":"What is the efficiency of labor? How does technological progress effect efficiency of labor?","options":null,"answer":null,"images":null,"translation":{"question":"什么是劳动效率？技术进步如何影响劳动效率？","options":null},"topics":["technology-growth"],"answer_ref":"劳动效率是劳动中所蕴含的技术、知识、健康水平——生产函数写成 Y = F(K, E·L) 中的 E，即每个\"效率工人\"相当的人数。技术进步使 E 以速率 g 增长：同样的工人掌握更好的工具和方法，单位劳动产出提高，相当于劳动投入按 (1+g) 的速度无形增加。"},{"num":83,"type":"sa","question":"Are persistent increases in standard of living possible in a steady-state economy?","options":null,"answer":null,"images":null,"translation":{"question":"在稳态经济中，生活水平能否持续提高？","options":null},"topics":["technology-growth"],"answer_ref":"没有技术进步的稳态经济中不可能——人均产出（生活水平）恒定不变。有技术进步时则可以：人均产出以速率 g 永续增长。持久的（sustained）生活水平提高只能来自持续的技术进步，这是索洛模型最重要的政策含义之一。"},{"num":84,"type":"sa","question":"With technological progress, how is the Golden Rule of capital defined in the steady state?","options":null,"answer":null,"images":null,"translation":{"question":"在有技术进步的情况下，稳态下的资本黄金律是如何定义的？","options":null},"topics":["technology-growth"],"answer_ref":"含技术进步时黄金律定义为：使每有效工人消费最大化的稳态，条件是 MPK = δ + n + g（资本净边际产品等于人口增长率与技术进步率之和）。此时 c = f(k) − (n+g+δ)k 最大。"},{"num":85,"type":"sa","question":"What is balanced growth? Give an example.","options":null,"answer":null,"images":null,"translation":{"question":"什么是平衡增长？举一个例子。","options":null},"topics":["technology-growth"],"answer_ref":"平衡增长指索洛模型含技术进步的稳态特征：人均资本、人均产出、实际工资都以相同速率 g 增长，而资本-产出比、MPK、实际租赁价格、要素收入份额等保持不变。例子：美国几十年间人均GDP年均增长约2%，工资与资本回报份额大体稳定。"},{"num":86,"type":"sa","question":"What does the Solow model predict about convergence? Why does conditional convergence occur?","options":null,"answer":null,"images":null,"translation":{"question":"索洛模型对趋同做出了什么预测？为什么会出现条件趋同？","options":null},"topics":["technology-growth"],"answer_ref":"索洛模型预测条件收敛：具有相同储蓄率、人口增长率和技术参数的国家收敛于同一稳态，因此离自身稳态较远（较穷）的国家暂时增长更快。之所以是\"有条件的\"，是因为各国参数（s、n、g）不同，稳态不同——只有条件相近的国家才互相收敛。"},{"num":87,"type":"sa","question":"Suppose that two economies are identical, having the same saving rates, population growth rates, and efficiency of labor growth. What will be the steady-state level of income per person in the economy when a. One country has smaller capital stock than the other. b. One country has lower saving rate than the other.","options":null,"answer":null,"images":null,"translation":{"question":"假设两个经济完全相同，具有相同的储蓄率、人口增长率和劳动效率增长。当以下情况时，经济的人均收入稳态水平将是怎样的：a. 一个国家的资本存量比另一个小。b. 一个国家的储蓄率比另一个低。","options":null},"topics":["technology-growth"],"answer_ref":"a. 资本较少的国家距离共同稳态更远，短期内增长更快，最终两国收敛到相同的稳态人均收入。b. 储蓄率较低的国家收敛到较低的稳态人均收入；储蓄率只决定稳态水平，不改变稳态增长率（无技术进步时均为零）。"},{"num":88,"type":"sa","question":"What is an endogenous growth model? How is technological change determined in the two-sector endogenous model?","options":null,"answer":null,"images":null,"translation":{"question":"什么是内生增长模型？在两部门内生模型中，技术变化是如何决定的？","options":null},"topics":["endogenous-growth"],"answer_ref":"内生增长模型是指增长率由模型内部的经济决策决定、而非外生给定的增长理论（AK 模型、两部门模型等）。两部门模型中，经济分为产品生产部门和知识生产部门：配置到研发部门的劳动和资本生产出新思想，知识是非竞争品且可能报酬递增——投入越多资源于研究，技术进步率 g 越高，长期增长率内生于研发决策。"},{"num":89,"type":"sa","question":"Who proposed the concept of \"creative destruction\"? What does this concept mean?","options":null,"answer":null,"images":null,"translation":{"question":"谁提出了“创造性破坏”的概念？这个概念的含义是什么？","options":null},"topics":["endogenous-growth"],"answer_ref":"约瑟夫·熊彼特（Joseph Schumpeter）提出。创造性破坏指：技术创新在创造新产品、新企业、新产业的同时，使旧产品、旧技术、旧企业被淘汰、贬值、退出市场——经济增长的过程本质上就是新创造不断摧毁旧体系的过程。它解释了为何技术进步既带来增长也带来失业与行业消亡。"}]},{"num":10,"title":"Introduction to Economic Fluctuations","questions":[{"num":1,"type":"mc","question":"Business cycles are:","options":["regular and predictable.","irregular but predictable.","regular but unpredictable.","irregular and unpredictable."],"answer":"D","images":null,"translation":{"question":"经济周期是：","options":["有规律且可预测的。","无规律但可预测的。","有规律但不可预测的。","无规律且不可预测的。"]},"topics":["business-cycle"]},{"num":2,"type":"mc","question":"Short-run fluctuations in output and employment are called:","options":["sectoral shifts.","the classical dichotomy.","business cycles.","productivity slowdowns."],"answer":"C","images":null,"translation":{"question":"产出和就业的短期波动被称为：","options":["部门性转移。","古典二分法。","经济周期。","生产率放缓。"]},"topics":["business-cycle"]},{"num":3,"type":"mc","question":"Recessions typically, but not always, include at least ______ consecutive quarters of declining real GDP.","options":["two","four","six","eight"],"answer":"A","images":null,"translation":{"question":"衰退通常（但不总是）包含至少 ______ 个连续季度的实际GDP下降。","options":["两","四","六","八"]},"topics":["business-cycle"]},{"num":4,"type":"mc","question":"Over the business cycle, investment spending ______ consumption spending.","options":["is inversely correlated with","is more volatile than","has about the same volatility as","is less volatile than"],"answer":"B","images":null,"translation":{"question":"在整个经济周期中，投资支出 ______ 消费支出。","options":["与……呈反向相关","比……波动更大","与……波动程度大致相同","比……波动更小"]},"topics":["business-cycle"]},{"num":5,"type":"mc","question":"When GDP growth declines, investment spending typically ______ and consumption spending typically ______.","options":["increases; increases","increases; decreases","decreases; decreases","decreases; increases"],"answer":"C","images":null,"translation":{"question":"当GDP增长放缓时，投资支出通常 ______，消费支出通常 ______。","options":["增加；增加","增加；减少","减少；减少","减少；增加"]},"topics":["business-cycle"]},{"num":6,"type":"mc","question":"Okun's law is the ______ relationship between real GDP and the ______.","options":["negative; unemployment rate","negative; inflation rate","positive; unemployment rate","positive; inflation rate"],"answer":"A","images":null,"translation":{"question":"奥肯定律是实际GDP与 ______ 之间的 ______ 关系。","options":["负向；失业率","负向；通胀率","正向；失业率","正向；通胀率"]},"topics":["business-cycle"]},{"num":7,"type":"mc","question":"The version of Okun's law studied in Chapter 10 assumes that with no change in unemployment, real GDP normally grows by 3 percent over a year. If the unemployment rate rose by 2 percentage points over a year, Okun's law predicts that real GDP would:","options":["decrease by 1 percent.","decrease by 2 percent.","decrease by 3 percent.","increase by 1 percent."],"answer":"A","images":null,"translation":{"question":"第10章研究的奥肯定律版本假设，在失业率不变的情况下，实际GDP通常一年增长3%。如果一年内失业率上升2个百分点，奥肯定律预测实际GDP将：","options":["下降1%。","下降2%。","下降3%。","上升1%。"]},"topics":["business-cycle"]},{"num":8,"type":"mc","question":"Long-run growth in real GDP is determined primarily by ______, while short-run movements in real GDP are associated with ______.","options":["variations in labor-market utilization; technological progress","technological progress; variations in labor-market utilization","money supply growth rates; changes in velocity","changes in velocity; money supply growth rates"],"answer":"B","images":null,"translation":{"question":"实际GDP的长期增长主要由 ______ 决定，而实际GDP的短期变动与 ______ 相关。","options":["劳动力市场利用率的变化；技术进步","技术进步；劳动力市场利用率的变化","货币供给增长率；流通速度的变化","流通速度的变化；货币供给增长率"]},"topics":["business-cycle"]},{"num":9,"type":"mc","question":"Leading economic indicators are:","options":["the most popular economic statistics.","data that are used to construct the consumer price index and the unemployment rate.","variables that tend to fluctuate in advance of the overall economy.","standardized statistics compiled by the National Bureau of Economic Research."],"answer":"C","images":null,"translation":{"question":"领先经济指标是：","options":["最受欢迎的经济统计资料。","用于构建消费者价格指数和失业率的数据。","倾向于先于整体经济而波动的变量。","由国民经济研究局（NBER）编制的标准化统计数据。"]},"topics":["business-cycle"]},{"num":10,"type":"mc","question":"A decline in the Index of Supplier Deliveries is typically an indicator of a future _____ in economic production, and a narrowing of the interest rate spread between the 10-year Treasury note and 3-month Treasury bill is typically an indicator of a future _____ in economic production.","options":["increase; slowdown","increase; increase","slowdown; increase","slowdown; slowdown"],"answer":"D","images":null,"translation":{"question":"供应商交货指数的下降通常是未来经济生产 ______ 的指标，而10年期国债与3个月期国库券之间利差的收窄通常是未来经济生产 ______ 的指标。","options":["增加；放缓","增加；增加","放缓；增加","放缓；放缓"]},"topics":["business-cycle"]},{"num":11,"type":"mc","question":"The index of leading indicators compiled by the Conference Board includes 10 data series that are used to forecast economic activity about ______ in advance.","options":["1 month","6 to 9 months","1 to 2 years","5 to 10 years"],"answer":"B","images":null,"translation":{"question":"美国咨商会（Conference Board）编制的领先指标指数包含10个数据系列，用于提前约 ______ 预测经济活动。","options":["1个月","6到9个月","1到2年","5到10年"]},"topics":["business-cycle"]},{"num":12,"type":"mc","question":"Measures of average workweeks and of supplier deliveries (vendor performance) are included in the index of leading indicators, because shorter workweeks tend to indicate ______ future economic activity and slower deliveries tend to indicate ______ future economic activity.","options":["stronger; stronger","stronger; weaker","weaker; stronger","weaker; weaker"],"answer":"C","images":null,"translation":{"question":"平均每周工时和供应商交货（供货业绩）的指标被纳入领先指标指数，因为较短的每周工时往往预示未来经济活动 ______，而较慢的交货往往预示未来经济活动 ______。","options":["更强；更强","更强；更弱","更弱；更强","更弱；更弱"]},"topics":["business-cycle"]},{"num":13,"type":"mc","question":"Most economists believe that prices are:","options":["flexible in the short run but many are sticky in the long run.","flexible in the long run but many are sticky in the short run.","sticky in both the short and long runs.","flexible in both the short and long runs."],"answer":"B","images":null,"translation":{"question":"大多数经济学家认为价格：","options":["在短期内是弹性的，但许多在长期内是粘性的。","在长期内是弹性的，但许多在短期内是粘性的。","在短期和长期内都是粘性的。","在短期和长期内都是弹性的。"]},"topics":["ad-as"]},{"num":14,"type":"mc","question":"A 5 percent reduction in the money supply will, according to most economists, reduce prices 5 percent:","options":["in both the short run and the long run.","in neither the short nor the long run.","in the short run but lead to unemployment in the long run.","in the long run but lead to unemployment in the short run."],"answer":"D","images":null,"translation":{"question":"根据大多数经济学家的观点，货币供给减少5%会使价格下降5%：","options":["在短期和长期内都是如此。","在短期和长期内都不是如此。","在短期内如此，但在长期内导致失业。","在长期内如此，但在短期内导致失业。"]},"topics":["ad-as"]},{"num":15,"type":"mc","question":"Monetary neutrality, the irrelevance of the money supply in determining values of _____ variables, is generally thought to be a property of the economy in the long run.","options":["real","nominal","real and nominal","neither real nor nominal"],"answer":"A","images":null,"translation":{"question":"货币中性，即货币供给在决定 ______ 变量取值方面的无关性，通常被认为是经济在长期内的一种性质。","options":["实际","名义","实际和名义","既非实际也非名义"]},"topics":["ad-as"]},{"num":16,"type":"mc","question":"A difference between the economic long run and the short run is that:","options":["the classical dichotomy holds in the short run but not in the long run.","monetary and fiscal policy affect output only in the long run.","demand can affect output and employment in the short run, whereas supply is the ruling force in the long run.","prices and wages are sticky in the long run only."],"answer":"C","images":null,"translation":{"question":"经济长期与短期之间的一个区别是：","options":["古典二分法在短期成立而在长期不成立。","货币政策和财政政策只在长期影响产出。","在短期内需求能够影响产出和就业，而在长期内供给是主导力量。","价格和工资只在长期内是粘性的。"]},"topics":["ad-as"]},{"num":17,"type":"mc","question":"The aggregate demand curve is the ______ relationship between the quantity of output demanded and the ______.","options":["positive; money supply","negative; money supply","positive; price level","negative; price level"],"answer":"D","images":null,"translation":{"question":"总需求曲线是产出需求量与 ______ 之间的 ______ 关系。","options":["正向；货币供给","负向；货币供给","正向；价格水平","负向；价格水平"]},"topics":["ad-as"]},{"num":18,"type":"mc","question":"If an aggregate demand curve is drawn with real GDP (Y) along the horizontal axis and the price level (P) along the vertical axis, using the quantity theory of money as a theory of aggregate demand, this curve slopes ______ to the right and gets ______ as it moves farther to the right.","options":["downward; steeper","downward; flatter","upward; steeper","upward; flatter"],"answer":"B","images":null,"translation":{"question":"如果用横轴表示实际GDP（Y）、纵轴表示价格水平（P）来画出总需求曲线，并使用货币数量论作为总需求理论，则该曲线向右 ______，且越向右移动越 ______。","options":["向下倾斜；陡峭","向下倾斜；平缓","向上倾斜；陡峭","向上倾斜；平缓"]},"topics":["ad-as"]},{"num":19,"type":"mc","question":"The assumption of constant velocity in the quantity equation is the equivalent of the assumption of a constant:","options":["short-run aggregate supply curve.","long-run aggregate supply curve.","price level in the short run.","demand for real balances per unit of output."],"answer":"D","images":null,"translation":{"question":"数量方程中流通速度不变的假设，等价于假设 ______ 不变：","options":["短期总供给曲线。","长期总供给曲线。","短期内的价格水平。","每单位产出的实际货币余额需求。"]},"topics":["ad-as"]},{"num":20,"type":"mc","question":"Along an aggregate demand curve, which of the following are held constant?","options":["real output and prices","nominal output and velocity","the money supply and real output","the money supply and velocity"],"answer":"D","images":null,"translation":{"question":"沿着总需求曲线，以下哪项保持不变？","options":["实际产出和价格","名义产出和流通速度","货币供给和实际产出","货币供给和流通速度"]},"topics":["ad-as"]},{"num":21,"type":"mc","question":"According to the quantity theory of money, when velocity is constant, if output is higher, ______ real balances are required, and for fixed M this means ______ P.","options":["higher; lower","lower; higher","higher; higher","lower; lower"],"answer":"A","images":null,"translation":{"question":"根据货币数量论，当流通速度不变时，如果产出更高，则需要 ______ 实际货币余额，而在M固定的情况下，这意味着P ______。","options":["更多；更低","更少；更高","更多；更高","更少；更低"]},"topics":["ad-as"]},{"num":22,"type":"mc","question":"According to the quantity equation, if the velocity of money and the supply of money are fixed, and the price level increases, then the quantity of goods and services purchased:","options":["increases.","decreases.","does not change.","may either increase or decrease."],"answer":"B","images":null,"translation":{"question":"根据数量方程，如果货币流通速度和货币供给都固定，而价格水平上升，那么购买的商品和服务的数量：","options":["增加。","减少。","不变。","可能增加也可能减少。"]},"topics":["ad-as"]},{"num":23,"type":"mc","question":"For a fixed money supply, the aggregate demand curve slopes downward because at a lower price level, real money balances are ______, generating a ______ quantity of output demanded.","options":["higher; greater","higher; smaller","lower; greater","lower; smaller"],"answer":"A","images":null,"translation":{"question":"在货币供给固定的情况下，总需求曲线向下倾斜，因为在较低的价格水平下，实际货币余额 ______，从而产生 ______ 的产出需求量。","options":["更高；更大","更高；更小","更低；更大","更低；更小"]},"topics":["ad-as"]},{"num":24,"type":"mc","question":"Assuming velocity is constant, the aggregate demand curve tells us possible:","options":["combinations of M and Y for a given value of P.","combinations of M and P for a given value of Y.","combinations of P and Y for a given value of M.","results if the Federal Reserve reduces the money supply."],"answer":"C","images":null,"translation":{"question":"假设流通速度不变，总需求曲线告诉我们的是：","options":["在给定P值下M与Y的可能组合。","在给定Y值下M与P的可能组合。","在给定M值下P与Y的可能组合。","美联储减少货币供给时的结果。"]},"topics":["ad-as"]},{"num":25,"type":"mc","question":"When an aggregate demand curve is drawn with real GDP (Y) along the horizontal axis and the price level (P) along the vertical axis, if the money supply is decreased, then the aggregate demand curve will shift:","options":["downward and to the left.","downward and to the right.","upward and to the left.","upward and to the right."],"answer":"A","images":null,"translation":{"question":"当用横轴表示实际GDP（Y）、纵轴表示价格水平（P）画出总需求曲线时，如果货币供给减少，那么总需求曲线将：","options":["向下且向左移动。","向下且向右移动。","向上且向左移动。","向上且向右移动。"]},"topics":["ad-as"]},{"num":26,"type":"mc","question":"When the Federal Reserve reduces the money supply, at a given price level the amount of output demanded is ______, and the aggregate demand curve shifts ______.","options":["greater; inward","greater; outward","lower; inward","lower; outward"],"answer":"C","images":null,"translation":{"question":"当美联储减少货币供给时，在给定的价格水平下，产出的需求量 ______，总需求曲线 ______。","options":["更大；向内移动","更大；向外移动","更小；向内移动","更小；向外移动"]},"topics":["ad-as"]},{"num":27,"type":"mc","question":"The relationship between the quantity of goods and services supplied and the price level is called:","options":["aggregate demand.","aggregate supply.","aggregate investment.","aggregate production."],"answer":"B","images":null,"translation":{"question":"商品和服务的供给量与价格水平之间的关系被称为：","options":["总需求。","总供给。","总投资。","总生产。"]},"topics":["ad-as"]},{"num":28,"type":"mc","question":"A short-run aggregate supply curve shows fixed ______, and a long-run aggregate supply curve shows fixed ______.","options":["output; output","prices; prices","prices; output","output; prices"],"answer":"C","images":null,"translation":{"question":"短期总供给曲线表明 ______ 固定，而长期总供给曲线表明 ______ 固定。","options":["产出；产出","价格；价格","价格；产出","产出；价格"]},"topics":["ad-as"]},{"num":29,"type":"mc","question":"In the long run, the level of output is determined by the:","options":["interaction of supply and demand.","money supply and the levels of government spending and taxation.","amounts of capital and labor and the available technology.","preferences of the public."],"answer":"C","images":null,"translation":{"question":"在长期内，产出水平由 ______ 决定：","options":["供求的相互作用。","货币供给以及政府支出和税收的水平。","资本和劳动的数量以及可用的技术。","公众的偏好。"]},"topics":["ad-as"]},{"num":30,"type":"mc","question":"When a long-term aggregate supply curve is drawn with real GDP (Y) along the horizontal axis and the price level (P) along the vertical axis, this curve:","options":["slopes upward and to the right.","slopes downward and to the right.","is horizontal.","is vertical."],"answer":"D","images":null,"translation":{"question":"当用横轴表示实际GDP（Y）、纵轴表示价格水平（P）画出长期总供给曲线时，这条曲线：","options":["向右上方倾斜。","向右下方倾斜。","是水平的。","是垂直的。"]},"topics":["ad-as"]},{"num":31,"type":"mc","question":"The vertical long-run aggregate supply curve satisfies the classical dichotomy because the natural rate of output does not depend on:","options":["the labor supply.","the supply of capital.","the money supply.","technology."],"answer":"C","images":null,"translation":{"question":"垂直的长期总供给曲线满足古典二分法，因为自然产出率不依赖于：","options":["劳动供给。","资本供给。","货币供给。","技术。"]},"topics":["ad-as"]},{"num":32,"type":"mc","question":"If the long-run aggregate supply curve is vertical, then changes in aggregate demand affect:","options":["neither prices nor level of output.","both prices and level of output.","level of output but not prices.","prices but not level of output."],"answer":"D","images":null,"translation":{"question":"如果长期总供给曲线是垂直的，那么总需求的变化影响：","options":["价格和产出水平都不影响。","价格和产出水平都影响。","只影响产出水平而不影响价格。","只影响价格而不影响产出水平。"]},"topics":["ad-as"]},{"num":33,"type":"mc","question":"The natural level of output is:","options":["affected by aggregate demand.","the level of output at which the unemployment rate is zero.","the level of output at which the unemployment rate is at its natural level.","permanent and unchangeable."],"answer":"C","images":null,"translation":{"question":"自然产出水平是：","options":["受总需求影响的。","失业率为零时的产出水平。","失业率处于其自然水平时的产出水平。","永久不变且无法改变的。"]},"topics":["ad-as"]},{"num":34,"type":"mc","question":"If all prices are stuck at a predetermined level, then when a short-run aggregate supply curve is drawn with real GDP (Y) along the horizontal axis and the price level (P) along the vertical axis, this curve:","options":["is horizontal.","is vertical.","slopes upward and to the right.","slopes downward and to the right."],"answer":"A","images":null,"translation":{"question":"如果所有价格都固定在预定水平上，那么当用横轴表示实际GDP（Y）、纵轴表示价格水平（P）画出短期总供给曲线时，这条曲线：","options":["是水平的。","是垂直的。","向右上方倾斜。","向右下方倾斜。"]},"topics":["ad-as"]},{"num":35,"type":"mc","question":"If the short-run aggregate supply curve is horizontal, then changes in aggregate demand affect:","options":["level of output but not prices.","prices but not level of output.","both prices and level of output.","neither prices nor level of output."],"answer":"A","images":null,"translation":{"question":"如果短期总供给曲线是水平的，那么总需求的变化影响：","options":["只影响产出水平而不影响价格。","只影响价格而不影响产出水平。","价格和产出水平都影响。","价格和产出水平都不影响。"]},"topics":["ad-as"]},{"num":36,"type":"mc","question":"In the aggregate demand–aggregate supply model, short-run equilibrium occurs at the combination of output and prices where:","options":["aggregate demand equals long-run aggregate supply.","aggregate demand equals short-run aggregate supply.","aggregate demand equals short-run and long-run aggregate supply.","short-run aggregate supply equals long-run aggregate supply."],"answer":"B","images":null,"translation":{"question":"在总需求—总供给模型中，短期均衡出现在产出与价格的组合满足 ______ 之处：","options":["总需求等于长期总供给。","总需求等于短期总供给。","总需求同时等于短期总供给和长期总供给。","短期总供给等于长期总供给。"]},"topics":["ad-as"]},{"num":37,"type":"mc","question":"The short-run aggregate supply curve is horizontal at:","options":["a level of output determined by aggregate demand.","the natural level of output.","the level of output at which the economy's resources are fully employed.","a fixed price level."],"answer":"D","images":null,"translation":{"question":"短期总供给曲线在 ______ 处是水平的：","options":["由总需求决定的产出水平。","自然产出水平。","经济资源得到充分利用时的产出水平。","一个固定的价格水平。"]},"topics":["ad-as"]},{"num":38,"type":"mc","question":"The short run refers to a period:","options":["of several days.","during which prices are sticky and cyclical unemployment may occur.","during which capital and labor are fully employed.","during which there are no fluctuations."],"answer":"B","images":null,"translation":{"question":"短期是指：","options":["几天的时期。","价格是粘性的、可能出现周期性失业的时期。","资本和劳动都得到充分利用的时期。","不存在波动的时期。"]},"topics":["ad-as"]},{"num":39,"type":"mc","question":"If the short-run aggregate supply curve is horizontal and the long-run aggregate supply curve is vertical, then a change in the money supply will change ______ in the short run and change ______ in the long run.","options":["only prices; only output","only output; only prices","both prices and output; only prices","both prices and output; both prices and output"],"answer":"B","images":null,"translation":{"question":"如果短期总供给曲线是水平的，而长期总供给曲线是垂直的，那么货币供给的变化在短期内改变 ______，在长期内改变 ______。","options":["只有价格；只有产出","只有产出；只有价格","价格和产出；只有价格","价格和产出；价格和产出"]},"topics":["ad-as"]},{"num":40,"type":"mc","question":"In the aggregate demand–aggregate supply model, long-run equilibrium occurs at the combination of output and prices where:","options":["aggregate demand is greater than long-run aggregate supply.","aggregate demand equals short-run aggregate supply.","aggregate demand equals short-run and long-run aggregate supply.","short-run aggregate supply equals long-run aggregate supply."],"answer":"C","images":null,"translation":{"question":"在总需求—总供给模型中，长期均衡出现在产出与价格的组合满足 ______ 之处：","options":["总需求大于长期总供给。","总需求等于短期总供给。","总需求同时等于短期总供给和长期总供给。","短期总供给等于长期总供给。"]},"topics":["ad-as"]},{"num":41,"type":"mc","question":"If a short-run equilibrium occurs at a level of output above the natural rate, then in the transition to the long run prices will ______, and output will ______.","options":["increase; increase","decrease; decrease","increase; decrease","decrease; increase"],"answer":"C","images":null,"translation":{"question":"如果短期均衡出现在高于自然率的产出水平上，那么在向长期过渡的过程中，价格将 ______，产出将 ______。","options":["上升；上升","下降；下降","上升；下降","下降；上升"]},"topics":["ad-as"]},{"num":42,"type":"mc","question":"If the short-run aggregate supply curve is horizontal and the Fed increases the money supply, then:","options":["output and employment will increase in the short run.","output and employment will decrease in the short run.","prices will increase in the short run.","prices will decrease in the short run."],"answer":"A","images":null,"translation":{"question":"如果短期总供给曲线是水平的，而美联储增加货币供给，那么：","options":["短期内产出和就业将增加。","短期内产出和就业将减少。","短期内价格将上升。","短期内价格将下降。"]},"topics":["ad-as"]},{"num":43,"type":"mc","question":"Assume that the economy starts from long-run equilibrium. If the Federal Reserve increases the money supply, then ______ increase(s) in the short run, and ______ increase(s) in the long run.","options":["prices; output","output; prices","output; output","prices; prices"],"answer":"B","images":null,"translation":{"question":"假设经济从长期均衡出发。如果美联储增加货币供给，那么短期内 ______ 增加，长期内 ______ 增加。","options":["价格；产出","产出；价格","产出；产出","价格；价格"]},"topics":["ad-as"]},{"num":44,"type":"mc","question":"Monetary neutrality is a characteristic of the aggregate demand–aggregate supply model in:","options":["both the short run and the long run.","neither the short run nor the long run.","the short run but not in the long run.","the long run but not in the short run."],"answer":"D","images":null,"translation":{"question":"货币中性是总需求—总供给模型在 ______ 的一种特征：","options":["短期和长期都是。","短期和长期都不是。","短期内是，但长期内不是。","长期内是，但短期内不是。"]},"topics":["ad-as"]},{"num":45,"type":"mc","question":"The economic response to the overnight reduction in the French money supply by 20 percent in 1724:","options":["confirmed the neutrality of money because no real variables were affected by this nominal change.","confirmed the quantity theory by leading to an immediate 20 percent reduction in the price level.","confirmed that money is not neutral in the short run because both output and prices dropped.","contradicted Okun's law because decreases in output were not associated with increases in unemployment."],"answer":"C","images":null,"translation":{"question":"1724年法国货币供给一夜之间减少20%后的经济反应：","options":["证实了货币中性，因为没有实际变量受到这一名义变化的影响。","证实了数量论，因为价格水平立即下降了20%。","证实了货币在短期内不是中性的，因为产出和价格都下降了。","与奥肯定律相矛盾，因为产出的下降并未伴随失业率的上升。"]},"topics":["ad-as"]},{"num":46,"type":"mc","question":"When the French money supply was reduced by 45 percent over a period of seven months in 1724, the only values in the economy that adjusted fully and instantaneously were:","options":["prices in grain markets.","real wages.","foreign exchange rates.","interest rates."],"answer":"C","images":null,"translation":{"question":"1724年法国货币供给在七个月内减少45%时，经济中唯一完全且即时调整的变量是：","options":["谷物市场的价格。","实际工资。","外汇汇率。","利率。"]},"topics":["ad-as"]},{"num":47,"type":"mc","question":"Stabilization policy refers to policy actions aimed at:","options":["reducing the severity of short-run economic fluctuations.","equalizing incomes of households in the economy.","maintaining constant shares of output going to labor and capital.","preventing increases in the poverty rate."],"answer":"A","images":null,"translation":{"question":"稳定化政策是指旨在 ______ 的政策行动：","options":["减轻短期经济波动的严重程度。","使经济中各家庭的收入均等化。","维持劳动和资本所得产出份额不变。","防止贫困率上升。"]},"topics":["ad-as"]},{"num":48,"type":"mc","question":"Which of the following is an example of a demand shock?","options":["a large increase in the price of oil","the introduction and greater availability of credit cards","a drought that destroys agricultural crops","unions obtain a substantial wage increase"],"answer":"B","images":null,"translation":{"question":"以下哪项是需求冲击的一个例子？","options":["石油价格的大幅上涨。","信用卡的推出和更广泛的可获得性。","一场摧毁农作物的干旱。","工会争取到大幅加薪。"]},"topics":["ad-as"]},{"num":49,"type":"mc","question":"If the short-run aggregate supply curve is horizontal, and each member of the general public chooses to hold a larger fraction of his or her income as cash balances, then:","options":["output and employment will increase in the short run.","output and employment will decrease in the short run.","prices will increase in the short run.","prices will decrease in the short run."],"answer":"B","images":null,"translation":{"question":"如果短期总供给曲线是水平的，并且每个公众成员都选择将收入的更大一部分以现金余额形式持有，那么：","options":["短期内产出和就业将增加。","短期内产出和就业将减少。","短期内价格将上升。","短期内价格将下降。"]},"topics":["ad-as"]},{"num":50,"type":"mc","question":"Holding output, Y, fixed, a reduction in the demand for money is the equivalent of a(n) _______ in velocity and will shift the aggregate demand curve to the _____.","options":["increase; right","increase; left","decrease; right","decrease; left"],"answer":"A","images":null,"translation":{"question":"在产出Y保持不变的情况下，货币需求的减少等价于流通速度的 ______，并将使总需求曲线向 ______ 移动。","options":["提高；右","提高；左","降低；右","降低；左"]},"topics":["ad-as"]},{"num":51,"type":"mc","question":"Starting from long-run equilibrium, if the velocity of money increases (due to, for example, the invention of automatic teller machines), the Fed might be able to stabilize output by:","options":["decreasing the money supply.","increasing the money supply.","decreasing the price level.","increasing the price level."],"answer":"A","images":null,"translation":{"question":"从长期均衡出发，如果货币流通速度提高（例如由于自动柜员机的发明），美联储或许能够通过 ______ 来稳定产出：","options":["减少货币供给。","增加货币供给。","降低价格水平。","提高价格水平。"]},"topics":["ad-as"]},{"num":52,"type":"mc","question":"Exhibit: Shift in Aggregate Demand In this graph, initially the economy is at point E, with price P0 and output Ȳ ? aggregate demand is given by curve AD0, and SRAS and LRAS represent, respectively, short-run and long-run aggregate supply. Now assume that the aggregate demand curve shifts so that it is represented by AD1. The economy moves first to point ______ and then, in the long run, to point ______.","options":["A; D","D; A","C; B","B; C"],"answer":"C","images":null,"translation":{"question":"图表：总需求的移动 在该图中，经济最初位于点E，价格为P0、产出为Ȳ，总需求由曲线AD0给出，SRAS和LRAS分别代表短期和长期总供给。现在假设总需求曲线移动为AD1。经济首先移动到点 ______，然后在长期内移动到点 ______。","options":["A；D","D；A","C；B","B；C"]},"topics":["ad-as"]},{"num":53,"type":"mc","question":"Exhibit: Shift in Aggregate Demand Assume that the economy is initially at point A with aggregate demand given by AD2. A shift in the aggregate demand curve to AD0 could be the result of either a(n) ______ in the money supply or a(n) ______ in velocity.","options":["increase; increase","increase; decrease","decrease; increase","decrease; decrease"],"answer":"A","images":["c10_img0.png"],"translation":{"question":"图表：总需求的移动 假设经济最初位于点A，总需求由AD2给出。总需求曲线移动到AD0，可能是由于货币供给的 ______ 或流通速度的 ______。","options":["增加；增加","增加；减少","减少；增加","减少；减少"]},"topics":["ad-as"]},{"num":54,"type":"mc","question":"A supply shock does not occur when:","options":["a drought destroys crops.","unions push wages up.","the Fed increases the money supply.","an oil cartel increases world oil prices."],"answer":"C","images":["c10_img1.png"],"translation":{"question":"在 ______ 情况下不会发生供给冲击：","options":["干旱摧毁农作物。","工会推动工资上涨。","美联储增加货币供给。","石油卡特尔提高世界石油价格。"]},"topics":["ad-as"]},{"num":55,"type":"mc","question":"A favorable supply shock occurs when:","options":["environmental protection laws raise costs of production.","the Fed increases the money supply.","unions push wages up.","an oil cartel breaks up and oil prices fall."],"answer":"D","images":null,"translation":{"question":"当 ______ 时发生有利的供给冲击：","options":["环境保护法提高生产成本。","美联储增加货币供给。","工会推动工资上涨。","石油卡特尔解体、油价下跌。"]},"topics":["ad-as"]},{"num":56,"type":"mc","question":"An adverse supply shock ______ the short-run aggregate supply curve ______ the natural level of output.","options":["raises; but cannot affect","raises; and may also lower","lowers; but cannot affect","lowers; and may also lower"],"answer":"B","images":null,"translation":{"question":"不利的供给冲击 ______ 短期总供给曲线，并且 ______ 自然产出水平。","options":["抬高；但不能影响","抬高；还可能降低","压低；但不能影响","压低；还可能降低"]},"topics":["ad-as"]},{"num":57,"type":"mc","question":"If the short-run aggregate supply curve is horizontal, an increase in union aggressiveness that pushes wages and prices up will result in ______ prices and ______ output in the short run.","options":["higher; lower","lower; higher","higher; higher","lower; lower"],"answer":"A","images":null,"translation":{"question":"如果短期总供给曲线是水平的，那么推动工资和价格上涨的工会激进程度的提高，在短期内会导致价格 ______、产出 ______。","options":["更高；更低","更低；更高","更高；更高","更低；更低"]},"topics":["ad-as"]},{"num":58,"type":"mc","question":"Exhibit: Supply Shock In this graph, assume that the economy starts at point A, and there is a favorable supply shock that does not last forever. In this situation, point ______ represents short-run equilibrium, and point ______ represents long-run equilibrium.","options":["B; C","B; A","E; D","E; A"],"answer":"D","images":null,"translation":{"question":"图表：供给冲击 在该图中，假设经济从点A出发，并且发生一次不会永远持续的有利供给冲击。在这种情况下，点 ______ 代表短期均衡，点 ______ 代表长期均衡。","options":["B；C","B；A","E；D","E；A"]},"topics":["ad-as"]},{"num":59,"type":"mc","question":"Exhibit: Supply Shock Assume that the economy is at point B. With no further shocks or policy moves, the economy in the long run will be at point:","options":["A.","B.","C.","D."],"answer":"A","images":["c10_img2.png"],"translation":{"question":"图表：供给冲击 假设经济位于点B。在没有进一步冲击或政策行动的情况下，经济在长期内将位于点：","options":["A。","B。","C。","D。"]},"topics":["ad-as"]},{"num":60,"type":"mc","question":"Exhibit: Supply Shock Assume that the economy is at point E. With no further shocks or policy moves, the economy in the long run will be at point:","options":["A.","B.","C.","D."],"answer":"A","images":["c10_img3.png"],"translation":{"question":"图表：供给冲击 假设经济位于点E。在没有进一步冲击或政策行动的情况下，经济在长期内将位于点：","options":["A。","B。","C。","D。"]},"topics":["ad-as"]},{"num":61,"type":"mc","question":"Exhibit: Supply Shock Assume that the economy starts at point A, and there is a drought that severely reduces agricultural output in the economy for just one year. In this situation, point ______ represents the short-run equilibrium immediately following the drought, and point ______ represents the eventual long-run equilibrium.","options":["B; C","B; A","E; D","D; A"],"answer":"B","images":["c10_img4.png"],"translation":{"question":"图表：供给冲击 假设经济从点A出发，并且发生一场仅持续一年的严重减少农业产出的干旱。在这种情况下，点 ______ 代表干旱之后紧随的短期均衡，点 ______ 代表最终的长期均衡。","options":["B；C","B；A","E；D","D；A"]},"topics":["ad-as"]},{"num":62,"type":"mc","question":"In the short run, a favorable supply shock causes:","options":["both prices and output to rise.","prices to rise and output to fall.","prices to fall and output to rise.","both prices and output to fall."],"answer":"C","images":["c10_img5.png"],"translation":{"question":"在短期内，有利的供给冲击会导致：","options":["价格和产出都上升。","价格上升、产出下降。","价格下降、产出上升。","价格和产出都下降。"]},"topics":["ad-as"]},{"num":63,"type":"mc","question":"Stagflation occurs when prices ______ and output ______.","options":["fall; falls","fall; increases","rise; falls","rise; increases"],"answer":"C","images":null,"translation":{"question":"当价格 ______ 且产出 ______ 时，发生滞胀。","options":["下降；下降","下降；上升","上升；下降","上升；上升"]},"topics":["ad-as"]},{"num":64,"type":"mc","question":"The dilemma facing the Federal Reserve in the event that an unfavorable supply shock moves the economy away from the natural rate of output is that monetary policy can either return output to the natural rate but with a ______ price level or allow the price level to return to its original level but with a ______ level of output in the short run.","options":["higher; higher","higher; lower","lower; lower","lower; higher"],"answer":"B","images":null,"translation":{"question":"当不利的供给冲击使经济偏离自然产出率时，美联储面临的两难是：货币政策要么使产出回到自然率，但价格水平 ______；要么让价格水平回到原水平，但短期内产出水平 ______。","options":["更高；更高","更高；更低","更低；更低","更低；更高"]},"topics":["ad-as"]},{"num":65,"type":"mc","question":"If the Fed accommodates an adverse supply shock, output falls ______, and prices rise ______.","options":["less; more","less; less","more; less","more; more"],"answer":"A","images":null,"translation":{"question":"如果美联储对不利的供给冲击进行适应性调节，那么产出下降 ______，价格上升 ______。","options":["更少；更多","更少；更少","更多；更少","更多；更多"]},"topics":["ad-as"]},{"num":66,"type":"mc","question":"Starting from long-run equilibrium, without policy intervention, the long-run impact of a temporary adverse supply shock is that prices will:","options":["be permanently higher, and output will be restored to the natural rate.","return to the old level, and output will be restored to the natural rate.","be permanently higher, and output will be permanently lower.","return to the old level, but output will be permanently lower."],"answer":"B","images":null,"translation":{"question":"从长期均衡出发，在没有政策干预的情况下，一次暂时性不利供给冲击的长期影响是价格将：","options":["永久更高，而产出将恢复到自然率。","回到原水平，而产出将恢复到自然率。","永久更高，而产出将永久更低。","回到原水平，但产出将永久更低。"]},"topics":["ad-as"]},{"num":67,"type":"mc","question":"Starting from long-run equilibrium, if a drought pushes up food prices throughout the economy, the Fed could move the economy more rapidly back to full employment output by:","options":["increasing the money supply, but at the cost of permanently higher prices.","decreasing the money supply, but at the cost of permanently lower prices.","increasing the money supply, which would restore the original price level.","decreasing the money supply, which would restore the original price level."],"answer":"A","images":null,"translation":{"question":"从长期均衡出发，如果一场干旱推高了整个经济的食品价格，美联储可以通过 ______ 使经济更快地回到充分就业产出：","options":["增加货币供给，但代价是价格永久更高。","减少货币供给，但代价是价格永久更低。","增加货币供给，这将恢复原来的价格水平。","减少货币供给，这将恢复原来的价格水平。"]},"topics":["ad-as"]},{"num":68,"type":"mc","question":"If a change in government regulations allows banks to start paying interest on checking accounts, this will:","options":["increase the demand for money.","decrease the demand for money.","have no effect on the demand for money.","increase the demand for currency but decrease the demand for checking accounts."],"answer":"A","images":null,"translation":{"question":"如果政府法规的改变允许银行开始对活期存款（支票账户）支付利息，这将：","options":["增加货币需求。","减少货币需求。","对货币需求没有影响。","增加通货需求但减少活期存款需求。"]},"topics":["ad-as"]},{"num":69,"type":"mc","question":"If the demand for money increases, but the Fed keeps the money supply the same, then in the short run output will:","options":["fall, and in the long run prices will remain unchanged.","remain unchanged, and in the long run prices will fall.","remain unchanged, and in the long run prices will remain unchanged.","fall, and in the long run prices will fall."],"answer":"D","images":null,"translation":{"question":"如果货币需求增加，但美联储保持货币供给不变，那么短期内产出将 ______，长期内价格将 ______。","options":["下降；保持不变","保持不变；下降","保持不变；保持不变","下降；下降"]},"topics":["ad-as"]},{"num":70,"type":"mc","question":"If the Fed reduces the money supply by 5 percent and the quantity theory of money is true, then output will fall 5 percent in the short run, and:","options":["prices will remain unchanged in the long run.","output will fall 5 percent in the long run.","prices will fall 5 percent in the long run.","output will remain unchanged in the long run."],"answer":"C","images":null,"translation":{"question":"如果美联储将货币供给减少5%，且货币数量论成立，那么短期内产出将下降5%，并且：","options":["长期内价格将保持不变。","长期内产出将下降5%。","长期内价格将下降5%。","长期内产出将保持不变。"]},"topics":["ad-as"]},{"num":71,"type":"mc","question":"Making use of Okun's law, if the Fed reduces the money supply 5 percent and the quantity theory of money is true, then the unemployment rate will rise about:","options":["5 percent in both the short run and the long run.","2.5 percent in both the short run and the long run.","5 percent in the short run but will return to its natural rate in the long run.","2.5 percent in the short run but will return to its natural rate in the long run."],"answer":"D","images":null,"translation":{"question":"利用奥肯定律，如果美联储将货币供给减少5%且货币数量论成立，那么失业率将上升约：","options":["在短期和长期内都上升5%。","在短期和长期内都上升2.5%。","短期内上升5%，但长期内将回到其自然率。","短期内上升2.5%，但长期内将回到其自然率。"]},"topics":["ad-as"]},{"num":72,"type":"mc","question":"If the Fed reduces the money supply by 5 percent, then the real interest rate will:","options":["rise in both the short run and the long run.","rise in the short run but return to its original equilibrium level in the long run.","rise in the short run but fall below its original equilibrium level in the long run.","be unaffected in both the short run and the long run."],"answer":"B","images":null,"translation":{"question":"如果美联储将货币供给减少5%，那么实际利率将：","options":["在短期和长期内都上升。","短期内上升，但长期内回到其原来的均衡水平。","短期内上升，但长期内降到其原来的均衡水平以下。","在短期和长期内都不受影响。"]},"topics":["ad-as"]},{"num":73,"type":"mc","question":"If Central Bank A cares only about keeping the price level stable and Central Bank B cares only about keeping output at its natural level, then in response to an exogenous decrease in the velocity of money:","options":["both Central Bank A and Central Bank B should increase the quantity of money.","Central Bank A should increase the quantity of money, whereas Central Bank B should keep it stable.","Central Bank A should keep the quantity of money stable, whereas Central Bank B should increase it.","both Central Bank A and Central Bank B should keep the quantity of money stable."],"answer":"A","images":null,"translation":{"question":"如果中央银行A只关心保持价格水平稳定，而中央银行B只关心保持产出处于自然水平，那么面对货币流通速度的外生下降：","options":["中央银行A和中央银行B都应增加货币数量。","中央银行A应增加货币数量，而中央银行B应保持其稳定。","中央银行A应保持货币数量稳定，而中央银行B应增加它。","中央银行A和中央银行B都应保持货币数量稳定。"]},"topics":["ad-as"]},{"num":74,"type":"mc","question":"If Central Bank A cares only about keeping the price level stable and Central Bank B cares only about keeping output at its natural level, then in response to an exogenous increase in the price of oil:","options":["both Central Bank A and Central Bank B should increase the quantity of money.","Central Bank A should increase the quantity of money, whereas Central Bank B should keep it stable.","Central Bank A should decrease the quantity of money, whereas Central Bank B should increase it.","both Central Bank A and Central Bank B should keep the quantity of money stable."],"answer":"C","images":null,"translation":{"question":"如果中央银行A只关心保持价格水平稳定，而中央银行B只关心保持产出处于自然水平，那么面对石油价格的外生上涨：","options":["中央银行A和中央银行B都应增加货币数量。","中央银行A应增加货币数量，而中央银行B应保持其稳定。","中央银行A应减少货币数量，而中央银行B应增加它。","中央银行A和中央银行B都应保持货币数量稳定。"]},"topics":["ad-as"]},{"num":75,"type":"sa","question":"Assume that the long-run aggregate supply curve is vertical at Y = 3,000 while the short-run aggregate supply curve is horizontal at P = 1.0. The aggregate demand curve is Y = 2 × M / P, and M = 1,500. a. If the economy is initially in long-run equilibrium, what are the values of P and Y? b. What is the velocity of money in this case? c. Suppose because banks start paying interest on checking accounts, the aggregate demand function shifts to Y = 1.5 × M / P. What are the short-run values of P and Y? d. What is the velocity of money in this case? e. With the new aggregate demand function, once the economy adjusts to long-run equilibrium, what are P and Y? f. What is the velocity now?","options":null,"answer":null,"images":null,"translation":{"question":"假设长期总供给曲线在 Y = 3,000 处垂直，而短期总供给曲线在 P = 1.0 处水平。总需求曲线为 Y = 2 × M / P，且 M = 1,500。a. 若经济最初处于长期均衡，P 和 Y 的值是多少？b. 此时货币流通速度是多少？c. 假设由于银行开始对活期存款支付利息，总需求函数移动为 Y = 1.5 × M / P。短期内的 P 和 Y 是多少？d. 此时货币流通速度是多少？e. 在新的总需求函数下，一旦经济调整到长期均衡，P 和 Y 是多少？f. 此时货币流通速度是多少？","options":null},"topics":["ad-as"],"answer_ref":"a. 长期均衡 Y=3000，由 AD 方程：3000 = 2×1500/P → P = 1.0。b. 货币数量论 MV=PY：V = 2。c. 支票账户付息使持有货币更有吸引力，货币需求上升、流通速度 V 下降→AD 曲线左移。短期：价格粘于 P=1.0，产出降至 3000 以下；长期：价格水平下降，产出回到 3000（货币中性）。"},{"num":76,"type":"sa","question":"Assume that the long-run aggregate supply curve is vertical at Y = 3,000, while the short-run aggregate supply curve is horizontal at P = 1.0. The aggregate demand curve is Y = 3 × M / P, and M = 1,000. a. If the economy is initially in long-run equilibrium, what are the values of P and Y? b. Now suppose a supply shock moves the short-run aggregate supply curve to P = 1.5. What are the new short-run P and Y? c. If the aggregate demand curve and long-run aggregate supply curve are unchanged, what are the long-run equilibrium P and Y after the supply shock? d. Suppose that after the supply shock the Fed wanted to hold output at its long-run level. What level of M would be required? If this level of M were maintained, what would be long-run equilibrium P and Y?","options":null,"answer":null,"images":null,"translation":{"question":"假设长期总供给曲线在 Y = 3,000 处垂直，而短期总供给曲线在 P = 1.0 处水平。总需求曲线为 Y = 3 × M / P，且 M = 1,000。a. 若经济最初处于长期均衡，P 和 Y 的值是多少？b. 现在假设一次供给冲击使短期总供给曲线移动到 P = 1.5。新的短期 P 和 Y 是多少？c. 如果总需求曲线和长期总供给曲线不变，供给冲击之后的长期均衡 P 和 Y 是多少？d. 假设在供给冲击之后，美联储希望将产出保持在其长期水平上。需要将 M 设为多少？如果维持这一 M 水平，长期均衡的 P 和 Y 将是多少？","options":null},"topics":["ad-as"],"answer_ref":"a. 长期均衡：3000 = 3×1000/P → P = 1.0，Y = 3000。b. 供给冲击使 SRAS 上移至 P=1.5：短期均衡 P=1.5，Y = 3×1000/1.5 = 2000——滞胀。长期：工资价格缓慢下调，SRAS 回到 P=1.0，产出恢复到 3000。"},{"num":77,"type":"sa","question":"The principal method the Federal Reserve uses to change the money supply is open-market operations. Use the aggregate demand–aggregate supply model to illustrate graphically the impact in the short run and the long run of a Federal Reserve decision to increase open-market purchases. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; v. the short-run equilibrium values; and vi. the long-run equilibrium values. State in words what happens to prices and output in the short run and the long run.","options":null,"answer":null,"images":null,"translation":{"question":"美联储用来改变货币供给的主要方法是公开市场操作。请用总需求—总供给模型，以图形说明美联储增加公开市场购买的决定在短期和长期内的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 短期均衡值；vi. 长期均衡值。并用文字说明价格和产出在短期和长期内分别发生什么变化。","options":null},"topics":["ad-as"],"answer_ref":"图（P 纵轴、Y 横轴）：公开市场买入→M↑→AD 右移。短期：沿 SRAS 从 E₀ 移到 E₁，P 由 P₀ 升至 P₁，Y 超过自然率。长期：预期物价上调，SRAS 左移，回到 LRAS 上 E₂——价格进一步升至 P₂，产出回到自然率。结论：货币政策短期改变产出，长期只改变价格。"},{"num":78,"type":"sa","question":"The advent of interest-earning checking accounts in the early 1980s led many households to keep a larger proportion of their wealth in checking accounts. Use the aggregate demand–aggregate supply model to illustrate graphically the impact in the short run and the long run of this change in money demand. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; v. the short-run equilibrium values; and vi. the long-run equilibrium values. State in words what happens to prices and output in the short run and the long run.","options":null,"answer":null,"images":null,"translation":{"question":"20世纪80年代初生息活期存款账户的出现，使许多家庭将其财富的更大比例保持在活期存款账户中。请用总需求—总供给模型，以图形说明这一货币需求变化在短期和长期内的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 短期均衡值；vi. 长期均衡值。并用文字说明价格和产出在短期和长期内分别发生什么变化。","options":null},"topics":["ad-as"],"answer_ref":"图：付息支票使货币需求增加。短期：货币需求↑（LM 左移）→AD 左移：P 不变（粘性），Y 降至自然率以下，r 上升。长期：预期价格下调，SRAS 下移，产出回到自然率，价格水平更低，利率回到原值。货币需求增加只改变价格和短期产出，长期是中性的。"},{"num":79,"type":"sa","question":"Suppose that droughts in the Southeast and floods in the Midwest substantially reduce food production in the United States. Use the aggregate demand–aggregate supply model to illustrate graphically the impact in the short run and the long run of this adverse supply shock. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; v. the short-run equilibrium values; and vi. the long-run equilibrium values. State in words what happens to prices and output in the short run and the long run.","options":null,"answer":null,"images":null,"translation":{"question":"假设东南部的干旱和中西部的洪灾大幅减少了美国的食品生产。请用总需求—总供给模型，以图形说明这一不利供给冲击在短期和长期内的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 短期均衡值；vi. 长期均衡值。并用文字说明价格和产出在短期和长期内分别发生什么变化。","options":null},"topics":["ad-as"],"answer_ref":"图：不利供给冲击（SRAS 左移）。短期：P 由 P₀ 升至 P₁，Y 由 Y* 降至 Y₁——物价上涨+产出下降（滞胀）。长期：衰退缺口使工资与价格回落，SRAS 逐步右移回初始位置，经济自动回到 E₀。"},{"num":80,"type":"sa","question":"Suppose that laws are passed banning labor unions and that resulting lower labor costs are passed along to consumers in the form of lower prices. Use the aggregate demand–aggregate supply model to illustrate graphically the impact in the short run and the long run of this favorable supply shock. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; v. the short-run equilibrium values; and vi. the long-run equilibrium values. State in words what happens to prices and output in the short run and the long run.","options":null,"answer":null,"images":null,"translation":{"question":"假设通过了禁止工会的法律，由此降低的劳动力成本以更低价格的形式传递给消费者。请用总需求—总供给模型，以图形说明这一有利供给冲击在短期和长期内的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 短期均衡值；vi. 长期均衡值。并用文字说明价格和产出在短期和长期内分别发生什么变化。","options":null},"topics":["ad-as"],"answer_ref":"图：有利供给冲击（SRAS 右移）。短期：P 由 P₀ 降至 P₁，Y 升至 Y₁（高于自然率）。长期：过热使工资物价回升，SRAS 左移回初始位置，经济回到原均衡 E₀——价格下降只是暂时的。"},{"num":81,"type":"sa","question":"Suppose you are an economist working for the Federal Reserve when droughts in the Southeast and floods in the Midwest substantially reduce food production in the United States. Use the aggregate demand–aggregate supply model to illustrate graphically your policy recommendation to accommodate this adverse supply shock, assuming that your top priority is maintaining full employment in the economy. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; and v. the terminal equilibrium values. State in words what happens to prices and output as a combined result of the supply shock and the recommended Federal Reserve accommodation.","options":null,"answer":null,"images":null,"translation":{"question":"假设你是为美联储工作的经济学家，此时东南部的干旱和中西部的洪灾大幅减少了美国的食品生产。请用总需求—总供给模型，以图形说明你对这一不利供给冲击进行适应性调节的政策建议，假设你的首要目标是维持经济中的充分就业。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。并用文字说明在供给冲击与所建议的美联储适应性调节共同作用的结果下，价格和产出会发生什么变化。","options":null},"topics":["ad-as"],"answer_ref":"建议：扩张货币/财政政策使 AD 右移，直到与新的 SRAS 相交于 Y=3000（充分就业）。图：AD₀→AD₁ 右移，短期均衡沿 SRAS 由 Y₁ 回到 3000。代价：价格水平被永久推高至更高水平（冲击被\" accommodated\"，物价停留在高位）。"},{"num":82,"type":"sa","question":"The long-run and short-run aggregate supply curves reflect fundamental differences between long-run and short-run macroeconomic analysis. a. Graphically illustrate the long-run and short-run aggregate supply curves. Be sure to label the axes. b. What determines the level of output in the long run versus the short run? c. How do prices behave differently in the long run and the short run?","options":null,"answer":null,"images":null,"translation":{"question":"长期和短期总供给曲线反映了长期与短期宏观经济分析之间的根本差异。a. 用图形说明长期和短期总供给曲线，务必标注坐标轴。b. 长期与短期内分别是什么决定产出水平？c. 价格在长期和短期内的表现有何不同？","options":null},"topics":["ad-as"],"answer_ref":"a. 图：纵轴 P、横轴 Y；LRAS 垂直于 Y*（自然产出），SRAS 向上倾斜（或水平的凯恩斯情形），AD 向下倾斜。b. 长期产出由要素供给与技术决定（Y = F(K,L)），与价格无关；短期产出由总需求决定——价格粘性使经济可偏离自然率。c. 长期价格完全弹性，名义变量随需求调整而产出不变；短期价格（工资）粘性，需求变动主要引起产出和就业变化。"},{"num":83,"type":"sa","question":"The economy of Macroland is initially in long-run equilibrium. A severe drought causes an adverse supply shock. a. What happens to prices and output in the short run? b. What would happen to prices and output in the long run if there is no policy accommodation? c. If the Central Bank of Macroland wants to prevent the short-run changes in price and output, what policy action could it take? How would the results of this policy action differ from the prices and output that would result in the long run with no policy action?","options":null,"answer":null,"images":null,"translation":{"question":"Macroland 经济最初处于长期均衡。一场严重的干旱造成了不利的供给冲击。a. 短期内价格和产出会发生什么变化？b. 如果没有政策适应性调节，长期内价格和产出会发生什么变化？c. 如果 Macroland 的中央银行想要阻止价格和产出的短期变化，它可以采取什么政策行动？这一政策行动的结果与没有政策行动时长期内的价格和产出会有何不同？","options":null},"topics":["ad-as"],"answer_ref":"a. 短期：SRAS 左移，P 上升、Y 下降（滞胀）。b. 长期无政策：产出低于自然率→工资下降→SRAS 右移回位，P、Y 恢复原值（过程缓慢且痛苦）。c. 央行可扩大货币供给/增加总需求（AD 右移），使产出回到自然率，但价格水平被永久抬高。"},{"num":84,"type":"sa","question":"A central bank reduces the money supply in an economy initially in long-run equilibrium. a. What will happen to output and prices in the short run? b. What will happen to unemployment in the short run? c. What will happen to output and prices in the long run?","options":null,"answer":null,"images":null,"translation":{"question":"某中央银行在一个最初处于长期均衡的经济中减少货币供给。a. 短期内产出和价格会发生什么变化？b. 短期内失业会发生什么变化？c. 长期内产出和价格会发生什么变化？","options":null},"topics":["ad-as"],"answer_ref":"a. 短期：M↓→AD 左移：P 下降、Y 降至自然率以下。b. 短期失业率上升（产出下降，奥肯定律）。c. 长期：工资价格下调，SRAS 右移：产出回到自然率，价格水平永久性地更低（货币中性）。"},{"num":85,"type":"sa","question":"An oil cartel effectively increases the price of oil by 100 percent, leading to an adverse supply shock in both Country A and Country B. Both countries were in long-run equilibrium at the same level of output and prices at the time of the shock. The central bank of Country A takes no stabilizing policy actions. After the short-run impacts of the adverse supply shock become apparent, the central bank of Country B increases the money supply to return the economy to full employment. a. Describe the short-run impact of the adverse supply shock on prices and output in each country. b. Compare the long-run impact of the adverse supply shock on prices and output in each country.","options":null,"answer":null,"images":null,"translation":{"question":"一个石油卡特尔将油价有效提高了100%，从而在 A 国和 B 国都造成了不利的供给冲击。冲击发生时，两国都处于相同产出和价格水平的长期均衡。A 国的中央银行不采取任何稳定化政策行动。在不利供给冲击的短期影响显现之后，B 国的中央银行增加货币供给以使经济回到充分就业。a. 描述不利供给冲击对各国价格和产出的短期影响。b. 比较不利供给冲击对各国价格和产出的长期影响。","options":null},"topics":["ad-as"],"answer_ref":"A 国（无政策）：短期 P↑、Y↓；长期工资下调使 SRAS 回移，经济缓慢回到原 P 与原 Y。B 国（央行在冲击后扩张货币）：AD 右移，产出较快恢复到充分就业，但价格水平永久高于原水平（通货膨胀被引入）。差异：A 国\"长期正确但短期痛苦\"，B 国\"短期无痛但物价永久抬升\"。"},{"num":86,"type":"sa","question":"Explain the meaning of monetary neutrality and illustrate graphically that there is monetary neutrality in the long run in the aggregate demand–aggregate supply model. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; v. the short-run equilibrium values; and vi. the long-run equilibrium values. Explain in words what your graph illustrates.","options":null,"answer":null,"images":null,"translation":{"question":"请解释货币中性的含义，并在总需求—总供给模型中用图形说明长期内存在货币中性。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 短期均衡值；vi. 长期均衡值。并用文字解释你的图形说明了什么。","options":null},"topics":["ad-as"],"answer_ref":"货币中性：货币供给变动在长期只影响名义变量（价格），不影响实际变量（产出、就业、实际利率）。图：M↑→AD 右移；短期均衡 E₁（P₁，Y>自然率）；长期预期调整后 SRAS 左移，E₂ 位于垂直 LRAS 上：Y 回到自然率，P 与货币同比例上升。文字：短期货币非中性（价格粘性），长期完全中性——货币只决定价格水平。"},{"num":87,"type":"sa","question":"You are given information about the following leading indicators. For each indicator, explain whether the information suggests that a recession or expansion should be expected in the future. a. Average initial weekly claims for unemployment insurance rise. b. New building permits issued increases. c. The interest rate spread between the 10-year Treasury note and the 3-month Treasury bill narrows. d. The Index of Supplier Deliveries falls.","options":null,"answer":null,"images":null,"translation":{"question":"你获得了以下领先指标的信息。对于每个指标，请解释这些信息表明未来应该预期衰退还是扩张。a. 失业保险的平均首次每周申请人数上升。b. 新发放的建筑许可证数量增加。c. 10年期国债与3个月期国库券之间的利差收窄。d. 供应商交货指数下降。","options":null},"topics":["business-cycle"],"answer_ref":"a. 首次申请失业救济人数上升——未来经济活动走弱信号→预期衰退。b. 新建筑许可增加——投资扩张信号→预期扩张。c. 10 年期与 3 个月国债利差收窄——通常预示增长放缓→预期衰退（利差收窄往往领先于倒挂与衰退）。"},{"num":88,"type":"sa","question":"Monetary policy can be either a stabilizing influence on the economy or a source of instability. Give an explanation for both possibilities.","options":null,"answer":null,"images":null,"translation":{"question":"货币政策既可以是对经济的稳定力量，也可以是不稳定的来源。请对这两种可能性分别给出解释。","options":null},"topics":["ad-as"],"answer_ref":"稳定作用：央行逆周期操作——需求不足时增货币、需求过热时减货币，缓冲产出与就业的波动。不稳定来源：①政策时滞（识别、决策、生效层层滞后），行动落地时经济已转向，反而放大周期；②预测失误；③政治压力导致过度刺激；④承诺与可信度问题使预期紊乱。货币政策既可能熨平波动，也可能成为波动的来源。"},{"num":89,"type":"sa","question":"What are the defining features of a recession?","options":null,"answer":null,"images":null,"translation":{"question":"衰退的定义性特征是什么？","options":null},"topics":["business-cycle"],"answer_ref":"衰退的特征：实际GDP显著且广泛地下降（常用定义为连续两个季度负增长）；收入、就业、工业生产、零售销售同步下滑；失业率持续上升；经济衰退是\"经济活动显著下降、遍及各经济部门、持续数月以上\"。"},{"num":90,"type":"sa","question":"What is the relationship between unemployment and real GDP?","options":null,"answer":null,"images":null,"translation":{"question":"失业与实际GDP之间的关系是什么？","options":null},"topics":["business-cycle"],"answer_ref":"奥肯定律（Okun's law）：失业率与实际GDP呈负相关——实际GDP增长低于潜在水平（或下降）时失业率上升。经验比例约为 2:1：实际GDP相对潜在水平每低 2%，失业率比自然率高约 1 个百分点。"},{"num":91,"type":"sa","question":"What is the difference between the short run and the long run?","options":null,"answer":null,"images":null,"translation":{"question":"短期和长期之间的区别是什么？","options":null},"topics":["ad-as"],"answer_ref":"短期：工资和价格粘性（菜单成本、合同），需求变动引起产出和就业的波动。长期：价格完全弹性，市场出清，产出由资本、劳动和技术固定于自然率，需求变动只改变价格。这是凯恩斯短期分析与古典长期分析的分界。"},{"num":92,"type":"sa","question":"What is aggregate demand? Why is the aggregate demand curve downward sloping?","options":null,"answer":null,"images":null,"translation":{"question":"什么是总需求？为什么总需求曲线向下倾斜？","options":null},"topics":["ad-as"],"answer_ref":"总需求是经济中对商品和服务的总支出：Y = C+I+G+NX。向右下方倾斜的三个原因：①财富效应——P 下降提高实际货币余额与财富，消费增加；②利率效应——P 下降减少货币需求、利率下降，投资增加；③汇率效应——P 下降使利率降、本币贬值，净出口增加。三个渠道都使价格越低、需求量越大。"},{"num":93,"type":"sa","question":"Why is the aggregate supply curve vertical in the long run and horizontal in the short run?","options":null,"answer":null,"images":null,"translation":{"question":"为什么总供给曲线在长期内是垂直的，而在短期内是水平的？","options":null},"topics":["ad-as"],"answer_ref":"长期垂直：价格与工资完全弹性，产出固定在自然率（由要素与技术决定），物价变化只改变名义变量。短期水平（极端凯恩斯情形）：名义工资价格完全固定（菜单成本、合同约束），企业在既定价格下愿意供给任何数量的产品，产出完全由总需求决定——经济萧条时短期总供给可视为水平线。"},{"num":94,"type":"sa","question":"Explain the concepts of shocks in aggregate demand and aggregate supply.","options":null,"answer":null,"images":null,"translation":{"question":"请解释总需求和总供给冲击的概念。","options":null},"topics":["ad-as"],"answer_ref":"需求冲击是使 AD 曲线移动的事件：货币供给变化、财政扩张/紧缩、消费者信心与财富变动、净出口变动等——价格粘性下它们短期内改变产出。供给冲击是使 AS 曲线移动的事件：油价、旱灾、工资法、生产率等——不利供给冲击使 P 与 Y 反向变动（滞胀），有利供给冲击则相反。"},{"num":95,"type":"sa","question":"What is stabilization policy?","options":null,"answer":null,"images":null,"translation":{"question":"什么是稳定化政策？","options":null},"topics":["ad-as"],"answer_ref":"稳定化政策是政府和央行为平抑经济波动、使产出维持在自然率附近而采取的政策：用货币政策（调货币供给/利率）和财政政策（调 G、T）移动总需求，以抵消需求与供给冲击，稳定产出、就业和价格水平。"}]},{"num":11,"title":"Aggregate Demand I","questions":[{"num":1,"type":"mc","question":"John Maynard Keynes wrote that low income and high unemployment in economic downturns should be blamed on:","options":["low levels of capital.","an untrained labor force.","inadequate technology.","low aggregate demand."],"answer":"D","images":null,"translation":{"question":"约翰·梅纳德·凯恩斯写道，经济低迷中的低收入和高失业应归咎于：","options":["资本水平低。","劳动力未经训练。","技术不足。","总需求低。"]},"topics":["islm-model"]},{"num":2,"type":"mc","question":"According to classical theory, national income depends on ______, while Keynes proposed that ______ determines the level of national income.","options":["aggregate demand; aggregate supply","aggregate supply; aggregate demand","monetary policy; fiscal policy","fiscal policy; monetary policy"],"answer":"B","images":null,"translation":{"question":"根据古典理论，国民收入取决于 ______，而凯恩斯提出 ______ 决定国民收入水平。","options":["总需求；总供给","总供给；总需求","货币政策；财政政策","财政政策；货币政策"]},"topics":["islm-model"]},{"num":3,"type":"mc","question":"The IS–LM model takes ______ as exogenous.","options":["the price level and national income","the price level","national income","the interest rate"],"answer":"B","images":null,"translation":{"question":"IS–LM 模型把 ______ 视为外生的。","options":["价格水平和国民收入","价格水平","国民收入","利率"]},"topics":["islm-model"]},{"num":4,"type":"mc","question":"Two interpretations of the IS–LM model are that the model explains:","options":["the determination of income in the short run when prices are fixed or what shifts the aggregate demand curve.","the short-run quantity theory of income or the short-run Fisher effect.","the determination of investment and saving or what shifts the liquidity preference schedule.","changes in government spending and taxes or the determination of the supply of real money balances."],"answer":"A","images":null,"translation":{"question":"对 IS–LM 模型的两种解释是，该模型解释：","options":["价格固定时短期收入的确定，或者什么使总需求曲线移动。","收入的短期数量论或者短期费雪效应。","投资和储蓄的确定，或者什么使流动性偏好曲线移动。","政府支出和税收的变化，或者实际货币余额供给的确定。"]},"topics":["islm-model"]},{"num":5,"type":"mc","question":"The IS curve plots the relationship between the interest rate and ______ that arises in the market for ______.","options":["national income; goods and services","the price level; goods and services","national income; money","the price level; money"],"answer":"A","images":null,"translation":{"question":"IS 曲线描绘的是利率与 ______ 之间的关系，该关系产生于 ______ 市场。","options":["国民收入；产品和服务","价格水平；产品和服务","国民收入；货币","价格水平；货币"]},"topics":["is-curve"]},{"num":6,"type":"mc","question":"In the Keynesian-cross model, actual expenditures equal:","options":["GDP.","the money supply.","the supply of real balances.","unplanned inventory investment."],"answer":"A","images":null,"translation":{"question":"在凯恩斯交叉模型中，实际支出等于：","options":["GDP。","货币供给。","实际货币余额的供给。","非计划存货投资。"]},"topics":["is-curve"]},{"num":7,"type":"mc","question":"In the Keynesian-cross model, actual expenditures differ from planned expenditures by the amount of:","options":["liquidity preference.","the government-purchases multiplier.","unplanned inventory investment.","real money balances."],"answer":"C","images":null,"translation":{"question":"在凯恩斯交叉模型中，实际支出与计划支出相差的数量为：","options":["流动性偏好。","政府购买乘数。","非计划存货投资。","实际货币余额。"]},"topics":["is-curve"]},{"num":8,"type":"mc","question":"Planned expenditure is a function of:","options":["planned investment.","planned government spending and taxes.","planned investment, government spending, and taxes.","national income and planned investment, government spending, and taxes."],"answer":"D","images":null,"translation":{"question":"计划支出是 ______ 的函数：","options":["计划投资。","计划政府支出和税收。","计划投资、政府支出和税收。","国民收入以及计划投资、政府支出和税收。"]},"topics":["is-curve"]},{"num":9,"type":"mc","question":"When planned expenditure is drawn on a graph as a function of income, the slope of the line is:","options":["between minus one and zero.","between zero and one.","one.","greater than one."],"answer":"B","images":null,"translation":{"question":"当计划支出作为收入的函数画在图形上时，这条线的斜率是：","options":["介于负一和零之间。","介于零和一之间。","一。","大于一。"]},"topics":["is-curve"]},{"num":10,"type":"mc","question":"The equilibrium condition in the Keynesian-cross analysis in a closed economy is:","options":["income equals consumption plus investment plus government spending.","planned expenditure equals consumption plus planned investment plus government spending.","actual expenditure equals planned expenditure.","actual saving equals actual investment."],"answer":"C","images":null,"translation":{"question":"封闭经济中凯恩斯交叉分析的均衡条件是：","options":["收入等于消费加投资加政府支出。","计划支出等于消费加计划投资加政府支出。","实际支出等于计划支出。","实际储蓄等于实际投资。"]},"topics":["is-curve"]},{"num":11,"type":"mc","question":"When firms experience unplanned inventory accumulation, they typically:","options":["build new plants.","lay off workers and reduce production.","hire more workers and increase production.","call for more government spending."],"answer":"B","images":null,"translation":{"question":"当企业经历非计划存货积累时，它们通常会：","options":["建造新工厂。","裁员并减少生产。","雇用更多工人并增加生产。","呼吁更多政府支出。"]},"topics":["is-curve"]},{"num":12,"type":"mc","question":"The equilibrium of the Keynesian cross shows:","options":["determination of equilibrium income and the interest rate in the short run.","determination of equilibrium income and the interest rate in the long run.","equality of planned expenditure and income in the short run.","equality of planned expenditure and income in the long run."],"answer":"C","images":null,"translation":{"question":"凯恩斯交叉模型的均衡表明：","options":["短期内均衡收入和利率的确定。","长期内均衡收入和利率的确定。","短期内计划支出与收入的相等。","长期内计划支出与收入的相等。"]},"topics":["is-curve"]},{"num":13,"type":"mc","question":"Exhibit: Keynesian Cross In this graph, the equilibrium levels of income and expenditure are:","options":["Y1 and PE1.","Y2 and PE2.","Y3 and PE3.","Y3 and PE4."],"answer":"B","images":null,"translation":{"question":"图表：凯恩斯交叉 在该图中，收入和支出的均衡水平是：","options":["Y1 和 PE1。","Y2 和 PE2。","Y3 和 PE3。","Y3 和 PE4。"]},"topics":["is-curve"]},{"num":14,"type":"mc","question":"Exhibit: Keynesian Cross In this graph, if firms are producing at level Y1, then inventories will ______, inducing firms to ______ production.","options":["rise; increase","rise; decrease","fall; increase","fall; decrease"],"answer":"C","images":["c11_img0.png"],"translation":{"question":"图表：凯恩斯交叉 在该图中，如果企业在 Y1 水平生产，那么存货将 ______，促使企业 ______ 生产。","options":["上升；增加","上升；减少","下降；增加","下降；减少"]},"topics":["is-curve"]},{"num":15,"type":"mc","question":"Exhibit: Keynesian Cross In this graph, if firms are producing at level Y3, then inventories will ______, inducing firms to ______ production.","options":["rise; increase","rise; decrease","fall; increase","fall; decrease"],"answer":"B","images":["c11_img1.png"],"translation":{"question":"图表：凯恩斯交叉 在该图中，如果企业在 Y3 水平生产，那么存货将 ______，促使企业 ______ 生产。","options":["上升；增加","上升；减少","下降；增加","下降；减少"]},"topics":["is-curve"]},{"num":16,"type":"mc","question":"The government-purchases multiplier indicates how much ______ change(s) in response to a $1 change in government purchases.","options":["the budget deficit","consumption","income","real balances"],"answer":"C","images":["c11_img2.png"],"translation":{"question":"政府购买乘数表示政府购买每变动1美元，______ 会变动多少。","options":["预算赤字","消费","收入","实际货币余额"]},"topics":["is-curve"]},{"num":17,"type":"mc","question":"In the Keynesian-cross model, if the MPC equals 0.75, then a $2 billion increase in government spending increases planned expenditures by ______ and increases the equilibrium level of income by ______.","options":["$2 billion; $4 billion","$0.75 billion; $1 billion","$0.75 billion; $0.75 billion","$1 billion; $4 billion"],"answer":"A","images":null,"translation":{"question":"在凯恩斯交叉模型中，如果边际消费倾向（MPC）等于 0.75，那么政府支出增加20亿美元会使计划支出增加 ______，并使收入的均衡水平增加 ______。","options":["20亿美元；40亿美元","7.5亿美元；10亿美元","7.5亿美元；7.5亿美元","10亿美元；40亿美元"]},"topics":["is-curve"]},{"num":18,"type":"mc","question":"According to the Keynesian-cross analysis, when there is a shift upward in the government-purchases schedule by an amount DG, then equilibrium income rises by:","options":["one unit.","DG.","DG divided by one minus the marginal propensity to consume.","DG multiplied one plus the marginal propensity to consume."],"answer":"C","images":null,"translation":{"question":"根据凯恩斯交叉分析，当政府购买曲线向上移动 DG 时，均衡收入上升：","options":["一个单位。","DG。","DG 除以 1 减边际消费倾向。","DG 乘以 1 加边际消费倾向。"]},"topics":["is-curve"]},{"num":19,"type":"mc","question":"In the Keynesian-cross model with an MPC > 0, if government purchases increase by 250, then the equilibrium level of income:","options":["increases by 250.","increases by more than 250.","decreases by 250.","increases but by less than 250."],"answer":"B","images":null,"translation":{"question":"在边际消费倾向 MPC > 0 的凯恩斯交叉模型中，如果政府购买增加250，那么收入的均衡水平：","options":["增加250。","增加超过250。","减少250。","增加但少于250。"]},"topics":["is-curve"]},{"num":20,"type":"mc","question":"In the Keynesian-cross model, fiscal policy has a multiplying effect on income because fiscal policy:","options":["increases the amount of money in the economy.","changes income, which changes consumption, which further changes income.","is government spending and, therefore, more powerful than private spending.","changes the interest rate."],"answer":"B","images":null,"translation":{"question":"在凯恩斯交叉模型中，财政政策对收入具有乘数效应，因为财政政策：","options":["增加了经济中的货币数量。","改变收入，收入改变消费，消费又进一步改变收入。","是政府支出，因此比私人支出更强大。","改变利率。"]},"topics":["is-curve"]},{"num":21,"type":"mc","question":"According to the Keynesian-cross analysis, if MPC stands for marginal propensity to consume, then a rise in taxes of DT will:","options":["decrease equilibrium income by DT.","decrease equilibrium income by DT / (1 – MPC).","decrease equilibrium income by DT (MPC) / (1 – MPC).","not affect equilibrium income at all."],"answer":"C","images":null,"translation":{"question":"根据凯恩斯交叉分析，如果 MPC 代表边际消费倾向，那么税收上升 DT 将：","options":["使均衡收入减少 DT。","使均衡收入减少 DT / (1 – MPC)。","使均衡收入减少 DT (MPC) / (1 – MPC)。","完全不使均衡收入改变。"]},"topics":["is-curve"]},{"num":22,"type":"mc","question":"In the Keynesian-cross model, if taxes are reduced by 100, then planned expenditures ______ for any given level of income.","options":["increase by 100","increase by more than 100","decrease by 100","increase but by less than 100"],"answer":"D","images":null,"translation":{"question":"在凯恩斯交叉模型中，如果税收减少100，那么在任何给定的收入水平下，计划支出：","options":["增加100。","增加超过100。","减少100。","增加但少于100。"]},"topics":["is-curve"]},{"num":23,"type":"mc","question":"In the Keynesian-cross model, if taxes are reduced by 250, then the equilibrium level of income:","options":["increases by 250.","increases by more than 250.","decreases by 250.","increases, but by less than 250."],"answer":"B","images":null,"translation":{"question":"在凯恩斯交叉模型中，如果税收减少250，那么收入的均衡水平：","options":["增加250。","增加超过250。","减少250。","增加但少于250。"]},"topics":["is-curve"]},{"num":24,"type":"mc","question":"The tax multiplier indicates how much ______ change(s) in response to a $1 change in taxes.","options":["the budget deficit","consumption","income","real balances"],"answer":"C","images":null,"translation":{"question":"税收乘数表示税收每变动1美元，______ 会变动多少。","options":["预算赤字","消费","收入","实际货币余额"]},"topics":["is-curve"]},{"num":25,"type":"mc","question":"In the Keynesian-cross model with a given MPC >0, the government-expenditure multiplier ______ the tax multiplier.","options":["is larger than","equals","is smaller than","is the inverse of the"],"answer":"A","images":null,"translation":{"question":"在给定 MPC > 0 的凯恩斯交叉模型中，政府支出乘数 ______ 税收乘数。","options":["大于","等于","小于","是……的倒数"]},"topics":["is-curve"]},{"num":26,"type":"mc","question":"In the Keynesian-cross model, if the MPC equals 0.75, then a $3 billion decrease in taxes increases planned expenditures by ______ and increases the equilibrium level of income by ______.","options":["$3 billion; $9 billion","$2.25 billion; $6.75 billion","$2.25 billion; $2.25 billion","$3 billion; $3 billion"],"answer":"B","images":null,"translation":{"question":"在凯恩斯交叉模型中，如果 MPC 等于 0.75，那么税收减少30亿美元会使计划支出增加 ______，并使收入的均衡水平增加 ______。","options":["30亿美元；90亿美元","22.5亿美元；67.5亿美元","22.5亿美元；22.5亿美元","30亿美元；30亿美元"]},"topics":["is-curve"]},{"num":27,"type":"mc","question":"Both Keynesians and supply-siders believe a tax cut will lead to growth:","options":["and both agree it works through incentive effects.","but Keynesians believe it works through incentive effects whereas supply-siders believe it works through aggregate demand.","but Keynesians believe it works through aggregate demand whereas supply-siders believe it works through incentive effects.","and both agree it works through aggregate demand."],"answer":"C","images":null,"translation":{"question":"凯恩斯主义者和供给学派都认为减税会带来增长：","options":["并且双方都同意它是通过激励效应起作用的。","但凯恩斯主义者认为它是通过激励效应起作用的，而供给学派认为它是通过总需求起作用的。","但凯恩斯主义者认为它是通过总需求起作用的，而供给学派认为它是通过激励效应起作用的。","并且双方都同意它是通过总需求起作用的。"]},"topics":["is-curve"]},{"num":28,"type":"mc","question":"The Keynesian-cross analysis assumes planned investment:","options":["is fixed, and so does the IS analysis.","depends on the interest rate, and so does the IS analysis.","is fixed, whereas the IS analysis assumes it depends on the interest rate.","depends on expenditure, and so does the IS analysis."],"answer":"C","images":null,"translation":{"question":"凯恩斯交叉分析假设计划投资：","options":["是固定的，IS 分析也如此假设。","取决于利率，IS 分析也如此假设。","是固定的，而 IS 分析假设它取决于利率。","取决于支出，IS 分析也如此假设。"]},"topics":["is-curve"]},{"num":29,"type":"mc","question":"The simple investment function shows that investment ______ as ______ increases.","options":["decreases; the interest rate","increases; the interest rate","decreases; government spending","increases; government spending"],"answer":"A","images":null,"translation":{"question":"简单的投资函数表明，随着 ______ 上升，投资 ______。","options":["减少；利率","增加；利率","减少；政府支出","增加；政府支出"]},"topics":["is-curve"]},{"num":30,"type":"mc","question":"An increase in the interest rate:","options":["reduces planned investment because the interest rate is the cost of borrowing to finance investment projects.","increases planned investment because people who make money from interest have more money to invest.","has no effect on investment.","may be caused by a drop in investment demand."],"answer":"A","images":null,"translation":{"question":"利率上升：","options":["会减少计划投资，因为利率是为投资项目融资的借贷成本。","会增加计划投资，因为从利息中赚钱的人有更多资金可投资。","对投资没有影响。","可能是由投资需求的下降引起的。"]},"topics":["is-curve"]},{"num":31,"type":"mc","question":"An explanation for the slope of the IS curve is that as the interest rate increases, the quantity of investment ______, and this shifts the expenditure function ______, thereby decreasing income.","options":["increases; downward","increases; upward","decreases; upward","decreases; downward"],"answer":"D","images":null,"translation":{"question":"对 IS 曲线斜率的一种解释是，随着利率上升，投资数量 ______，这使支出函数 ______，从而减少收入。","options":["增加；向下移动","增加；向上移动","减少；向上移动","减少；向下移动"]},"topics":["is-curve"]},{"num":32,"type":"mc","question":"In the Keynesian-cross model, a decrease in the interest rate ______ planned investment spending and ______ the equilibrium level of income.","options":["increases; increases","increases; decreases","decreases; decreases","decreases; increases"],"answer":"A","images":null,"translation":{"question":"在凯恩斯交叉模型中，利率下降 ______ 计划投资支出，并 ______ 收入的均衡水平。","options":["增加；增加","增加；减少","减少；减少","减少；增加"]},"topics":["is-curve"]},{"num":33,"type":"mc","question":"When drawn on a graph with income along the horizontal axis and the interest rate along the vertical axis, the IS curve:","options":["is vertical.","is horizontal.","slopes upward and to the right.","slopes downward and to the right."],"answer":"D","images":null,"translation":{"question":"当用横轴表示收入、纵轴表示利率画出图形时，IS 曲线：","options":["是垂直的。","是水平的。","向右上方倾斜。","向右下方倾斜。"]},"topics":["is-curve"]},{"num":34,"type":"mc","question":"Along any given IS curve:","options":["tax rates are fixed, but government spending varies.","government spending is fixed, but taxes vary.","both government spending and taxes vary.","both government spending and taxes are fixed."],"answer":"D","images":null,"translation":{"question":"沿着任何给定的 IS 曲线：","options":["税率是固定的，但政府支出是变化的。","政府支出是固定的，但税收是变化的。","政府支出和税收都是变化的。","政府支出和税收都是固定的。"]},"topics":["is-curve"]},{"num":35,"type":"mc","question":"The IS curve shifts when any of the following economic variables change except:","options":["the interest rate.","government spending.","taxes.","the marginal propensity to consume."],"answer":"A","images":null,"translation":{"question":"当以下任何经济变量改变时 IS 曲线都会移动，除了：","options":["利率。","政府支出。","税收。","边际消费倾向。"]},"topics":["is-curve"]},{"num":36,"type":"mc","question":"An increase in government spending generally shifts the IS curve:","options":["downward and to the left.","upward and to the right.","upward and to the left.","downward and to the right."],"answer":"B","images":null,"translation":{"question":"政府支出的增加通常使 IS 曲线：","options":["向下且向左移动。","向上且向右移动。","向上且向左移动。","向下且向右移动。"]},"topics":["is-curve"]},{"num":37,"type":"mc","question":"An increase in taxes shifts the IS curve:","options":["downward and to the left.","upward and to the right.","upward and to the left.","downward and to the right."],"answer":"A","images":null,"translation":{"question":"税收的增加使 IS 曲线：","options":["向下且向左移动。","向上且向右移动。","向上且向左移动。","向下且向右移动。"]},"topics":["is-curve"]},{"num":38,"type":"mc","question":"Based on the Keynesian model, one reason to support government spending increases over tax cuts as measures to increase output is that:","options":["government spending increases the MPC more than tax cuts.","the government-spending multiplier is larger than the tax multiplier.","government-spending increases do not lead to unplanned changes in inventories, but tax cuts do.","increases in government spending increase planned spending, but tax cuts reduce planned spending."],"answer":"B","images":null,"translation":{"question":"基于凯恩斯模型，支持用增加政府支出而非减税来增加产出的一个理由是：","options":["政府支出比减税更能提高 MPC。","政府支出乘数大于税收乘数。","政府支出的增加不会导致非计划的存货变化，而减税会。","政府支出的增加会增加计划支出，但减税会减少计划支出。"]},"topics":["is-curve"]},{"num":39,"type":"mc","question":"Gary Becker's criticism of government spending on infrastructure as part of President Obama's stimulus plan was that:","options":["spending on infrastructure would not increase production in the economy.","there is a conflict between where spending on infrastructure would benefit employment and where infrastructure is most needed.","government spending on infrastructure is less effective in increasing production than an equal amount of private spending on infrastructure.","government spending on infrastructure only increases demand, but tax cuts increase demand and supply."],"answer":"B","images":null,"translation":{"question":"加里·贝克尔对作为奥巴马总统刺激计划一部分的基础设施政府支出的批评是：","options":["基础设施支出不会增加经济中的生产。","在基础设施支出有利于就业的地方与最需要基础设施的地方之间存在冲突。","在增加生产方面，政府的基础设施支出不如等量的私人基础设施支出有效。","政府的基础设施支出只增加需求，而减税则同时增加需求和供给。"]},"topics":["is-curve"]},{"num":40,"type":"mc","question":"One argument in favor of tax cuts over spending-based fiscal stimulus is that:","options":["tax cuts increase the MPC by a larger amount than government spending.","tax cuts temporarily increase planned spending, but government spending permanently increases private spending.","in theory the tax multiplier is larger than the government spending multiplier.","historically tax cuts have been more successful than spending-based fiscal stimulus."],"answer":"D","images":null,"translation":{"question":"支持减税而非以支出为基础的财政刺激的一个论点是：","options":["减税比政府支出更能提高 MPC。","减税会暂时增加计划支出，但政府支出会永久增加私人支出。","理论上税收乘数大于政府支出乘数。","从历史上看，减税比以支出为基础的财政刺激更成功。"]},"topics":["is-curve"]},{"num":41,"type":"mc","question":"Changes in fiscal policy shift the:","options":["LM curve.","money demand curve.","money supply curve.","IS curve."],"answer":"D","images":null,"translation":{"question":"财政政策的变化会使 ______ 移动：","options":["LM 曲线。","货币需求曲线。","货币供给曲线。","IS 曲线。"]},"topics":["is-curve"]},{"num":42,"type":"mc","question":"Along an IS curve all of the following are always true except:","options":["planned expenditures equal actual expenditures.","planned expenditures equal income.","the demand for real balances equals the supply of real balances.","there are no unplanned changes in inventories."],"answer":"C","images":null,"translation":{"question":"沿着 IS 曲线，以下所有说法都始终成立，除了：","options":["计划支出等于实际支出。","计划支出等于收入。","实际货币余额的需求等于实际货币余额的供给。","不存在非计划的存货变化。"]},"topics":["is-curve"]},{"num":43,"type":"mc","question":"An IS curve shows combinations of:","options":["taxes and government spending.","nominal money balances and price levels.","interest rates and income that bring equilibrium in the market for real balances.","interest rates and income that bring equilibrium in the market for goods and services."],"answer":"D","images":null,"translation":{"question":"IS 曲线表示 ______ 的组合：","options":["税收和政府支出。","名义货币余额和价格水平。","使实际货币余额市场达到均衡的利率和收入。","使产品和服务市场达到均衡的利率和收入。"]},"topics":["is-curve"]},{"num":44,"type":"mc","question":"According to the theory of liquidity preference, the supply of real money balances:","options":["decreases as the interest rate increases.","increases as the interest rate increases.","increases as income increases.","is fixed by the central bank."],"answer":"D","images":null,"translation":{"question":"根据流动性偏好理论，实际货币余额的供给：","options":["随着利率上升而减少。","随着利率上升而增加。","随着收入上升而增加。","由中央银行固定。"]},"topics":["lm-curve"]},{"num":45,"type":"mc","question":"If the interest rate is above the equilibrium value, the:","options":["demand for real balances exceeds the supply.","supply of real balances exceeds the demand.","market for real balances clears.","demand for real balances increases."],"answer":"B","images":null,"translation":{"question":"如果利率高于均衡值，那么：","options":["实际货币余额的需求超过供给。","实际货币余额的供给超过需求。","实际货币余额市场出清。","实际货币余额的需求增加。"]},"topics":["lm-curve"]},{"num":46,"type":"mc","question":"Exhibit: Market for Real Money Balances Based on the graph, the equilibrium levels of interest rates and real money balances are:","options":["r1 and M1 / P1","r2 and M2 / P2","r3 and M2 / P2","r3 and M3 / P3"],"answer":"B","images":null,"translation":{"question":"图表：实际货币余额市场 根据该图，利率和实际货币余额的均衡水平是：","options":["r1 和 M1 / P1","r2 和 M2 / P2","r3 和 M2 / P2","r3 和 M3 / P3"]},"topics":["lm-curve"]},{"num":47,"type":"mc","question":"Exhibit: Market for Real Money Balances Based on the graph, if the interest rate is r1, then people will ______ bonds, and the interest rate will ______.","options":["sell; rise","sell; fall","buy; rise","buy; fall"],"answer":"D","images":["c11_img3.png"],"translation":{"question":"图表：实际货币余额市场 根据该图，如果利率为 r1，那么人们将 ______ 债券，利率将 ______。","options":["卖出；上升","卖出；下降","买入；上升","买入；下降"]},"topics":["lm-curve"]},{"num":48,"type":"mc","question":"Exhibit: Market for Real Money Balances Based on the graph, if the interest rate is r3, then people will ______ bonds, and the interest rate will ______.","options":["sell; rise","sell; fall","buy; rise","buy; fall"],"answer":"A","images":["c11_img4.png"],"translation":{"question":"图表：实际货币余额市场 根据该图，如果利率为 r3，那么人们将 ______ 债券，利率将 ______。","options":["卖出；上升","卖出；下降","买入；上升","买入；下降"]},"topics":["lm-curve"]},{"num":49,"type":"mc","question":"The theory of liquidity preference states that, other things being equal, an increase in the real money supply will:","options":["lower the interest rate.","raise the interest rate.","have no effect on the interest rate.","first lower and then raise the interest rate."],"answer":"A","images":["c11_img5.png"],"translation":{"question":"流动性偏好理论表明，在其他条件相同的情况下，实际货币供给的增加将：","options":["降低利率。","提高利率。","对利率没有影响。","先降低后提高利率。"]},"topics":["lm-curve"]},{"num":50,"type":"mc","question":"According to the theory of liquidity preference, decreasing the money supply will ______ nominal interest rates in the short run, and, according to the Fisher effect, decreasing the money supply will ______ nominal interest rates in the long run.","options":["increase; increase","increase; decrease","decrease; decrease","decrease; increase"],"answer":"B","images":null,"translation":{"question":"根据流动性偏好理论，减少货币供给在短期内将 ______ 名义利率；而根据费雪效应，减少货币供给在长期内将 ______ 名义利率。","options":["提高；提高","提高；降低","降低；降低","降低；提高"]},"topics":["lm-curve"]},{"num":51,"type":"mc","question":"In the liquidity preference model, what adjusts to move the money market to equilibrium following a change in the money supply?","options":["planned spending","the interest rate","production","the price level"],"answer":"B","images":null,"translation":{"question":"在流动性偏好模型中，货币供给发生变化后，是什么进行调整以使货币市场达到均衡？","options":["计划支出","利率","生产","价格水平"]},"topics":["lm-curve"]},{"num":52,"type":"mc","question":"The theory of liquidity preference states that the quantity of real money balances demanded is:","options":["negatively related to both the interest rate and income.","positively related to both the interest rate and income.","positively related to the interest rate and negatively related to income.","negatively related to the interest rate and positively related to income."],"answer":"D","images":null,"translation":{"question":"流动性偏好理论表明，实际货币余额的需求量与利率 ______ 相关，与收入 ______ 相关。","options":["负；负","正；正","正；负","负；正"]},"topics":["lm-curve"]},{"num":53,"type":"mc","question":"With the real money supply held constant, the theory of liquidity preference implies that a higher income level will be consistent with:","options":["no change in the interest rate.","a lower interest rate.","a higher interest rate.","first a lower and then a higher interest rate."],"answer":"C","images":null,"translation":{"question":"在实际货币供给保持不变的情况下，流动性偏好理论意味着更高的收入水平将与 ______ 相一致：","options":["利率不变。","更低的利率。","更高的利率。","先更低后更高的利率。"]},"topics":["lm-curve"]},{"num":54,"type":"mc","question":"The LM curve, in the usual case:","options":["is vertical.","is horizontal.","slopes down to the right.","slopes up to the right."],"answer":"D","images":null,"translation":{"question":"在通常情形下，LM 曲线：","options":["是垂直的。","是水平的。","向右下方倾斜。","向右上方倾斜。"]},"topics":["lm-curve"]},{"num":55,"type":"mc","question":"An LM curve shows combinations of:","options":["taxes and government spending.","nominal money balances and price levels.","interest rates and income, which bring equilibrium in the market for real money balances.","interest rates and income, which bring equilibrium in the market for goods and services."],"answer":"C","images":null,"translation":{"question":"LM 曲线表示 ______ 的组合：","options":["税收和政府支出。","名义货币余额和价格水平。","使实际货币余额市场达到均衡的利率和收入。","使产品和服务市场达到均衡的利率和收入。"]},"topics":["lm-curve"]},{"num":56,"type":"mc","question":"A decrease in the real money supply, other things being equal, will shift the LM curve:","options":["downward and to the left.","upward and to the left.","downward and to the right.","upward and to the right."],"answer":"B","images":null,"translation":{"question":"在其他条件相同的情况下，实际货币供给的减少将使 LM 曲线：","options":["向下且向左移动。","向上且向左移动。","向下且向右移动。","向上且向右移动。"]},"topics":["lm-curve"]},{"num":57,"type":"mc","question":"A decrease in the nominal money supply, other things being equal, will shift the LM curve:","options":["upward and to the right.","downward and to the right.","downward and to the left.","upward and to the left."],"answer":"D","images":null,"translation":{"question":"在其他条件相同的情况下，名义货币供给的减少将使 LM 曲线：","options":["向上且向右移动。","向下且向右移动。","向下且向左移动。","向上且向左移动。"]},"topics":["lm-curve"]},{"num":58,"type":"mc","question":"An increase in income raises money ______ and ______ the equilibrium interest rate.","options":["demand; raises","demand; lowers","supply; raises","supply; lowers"],"answer":"A","images":null,"translation":{"question":"收入的增加提高货币 ______，并 ______ 均衡利率。","options":["需求；提高","需求；降低","供给；提高","供给；降低"]},"topics":["lm-curve"]},{"num":59,"type":"mc","question":"Changes in monetary policy shift the:","options":["LM curve.","planned spending curve.","money demand curve.","IS curve."],"answer":"A","images":null,"translation":{"question":"货币政策的变化会使 ______ 移动：","options":["LM 曲线。","计划支出曲线。","货币需求曲线。","IS 曲线。"]},"topics":["lm-curve"]},{"num":60,"type":"mc","question":"The LM curve shows combinations of ______ that are consistent with equilibrium in the market for real money balances.","options":["inflation and unemployment","the price level and real output","the interest rate and the level of income","the interest rate and real money balances"],"answer":"C","images":null,"translation":{"question":"LM 曲线表示与实际货币余额市场均衡相一致的 ______ 的组合。","options":["通货膨胀和失业","价格水平和实际产出","利率和收入水平","利率和实际货币余额"]},"topics":["lm-curve"]},{"num":61,"type":"mc","question":"In the money market, an increase in the money supply:","options":["lowers income.","raises income.","has no effect on income.","lowers velocity."],"answer":"B","images":null,"translation":{"question":"在货币市场中，货币供给的增加：","options":["降低收入。","提高收入。","对收入没有影响。","降低流通速度。"]},"topics":["lm-curve"]},{"num":62,"type":"mc","question":"The LM curve generally determines:","options":["income.","the interest rate.","both income and the interest rate.","neither income nor the interest rate."],"answer":"D","images":null,"translation":{"question":"LM 曲线单独通常决定：","options":["收入。","利率。","收入和利率两者。","既不是收入也不是利率。"]},"topics":["lm-curve"]},{"num":63,"type":"mc","question":"The IS and LM curves together generally determine:","options":["income only.","the interest rate only.","both income and the interest rate.","income, the interest rate, and the price level."],"answer":"C","images":null,"translation":{"question":"IS 和 LM 曲线结合起来通常决定：","options":["只有收入。","只有利率。","收入和利率两者。","收入、利率和价格水平。"]},"topics":["islm-model"]},{"num":64,"type":"mc","question":"The interest rate determines ______ in the goods market and money ______ in the money market.","options":["government spending; demand","government spending; supply","investment spending; demand","investment spending; supply"],"answer":"C","images":null,"translation":{"question":"利率在产品市场中决定 ______，在货币市场中决定货币 ______。","options":["政府支出；需求","政府支出；供给","投资支出；需求","投资支出；供给"]},"topics":["islm-model"]},{"num":65,"type":"mc","question":"The intersection of the IS and LM curves determines the values of:","options":["r, Y, and P, given G, T, and M.","r, Y, and M, given G, T, and P.","r and Y, given G, T, M, and P.","p and Y, given G, T, and M."],"answer":"C","images":null,"translation":{"question":"IS 和 LM 曲线的交点决定了 ______ 的取值：","options":["r、Y 和 P，给定 G、T 和 M。","r、Y 和 M，给定 G、T 和 P。","r 和 Y，给定 G、T、M 和 P。","p 和 Y，给定 G、T 和 M。"]},"topics":["islm-model"]},{"num":66,"type":"mc","question":"Equilibrium levels of income and interest rates are ______ related in the goods and services market, and equilibrium levels of income and interest rates are ______ related in the market for real money balances.","options":["positively; positively","positively; negatively","negatively; negatively","negatively; positively"],"answer":"D","images":null,"translation":{"question":"在产品和服务市场中，均衡的收入与利率水平呈 ______ 关系；在实际货币余额市场中，均衡的收入与利率水平呈 ______ 关系。","options":["正；正","正；负","负；负","负；正"]},"topics":["islm-model"]},{"num":67,"type":"mc","question":"The IS–LM model is generally used:","options":["only in the short run.","only in the long run.","both in the short run and in the long run.","in determining the price level."],"answer":"A","images":null,"translation":{"question":"IS–LM 模型通常用于：","options":["只在短期。","只在长期。","短期和长期都用于。","确定价格水平。"]},"topics":["islm-model"]},{"num":68,"type":"mc","question":"According to the Keynesian-cross analysis, if the marginal propensity to consume is 0.6 and government expenditures and autonomous taxes are both increased by 100, equilibrium income will rise by:","options":["0.","100.","150.","250."],"answer":"B","images":null,"translation":{"question":"根据凯恩斯交叉分析，如果边际消费倾向为 0.6，且政府支出和自主税收都增加100，均衡收入将上升：","options":["0。","100。","150。","250。"]},"topics":["is-curve"]},{"num":69,"type":"mc","question":"In the Keynesian-cross analysis, if the consumption function is given by C = 20 + 0.7 (Y – T), and planned investment is 100, G is 100, and T is 100, then equilibrium Y is:","options":["350.","600.","950.","1,100."],"answer":"D","images":null,"translation":{"question":"在凯恩斯交叉分析中，如果消费函数为 C = 20 + 0.7 (Y – T)，计划投资为 100，G 为 100，T 为 100，那么均衡 Y 是：","options":["350。","600。","950。","1,100。"]},"topics":["is-curve"]},{"num":70,"type":"mc","question":"Using the Keynesian-cross analysis, assume that the consumption function is given by C = 200 + 0.7 (Y – T). If planned investment is 100 and T is 100, then the level of G needed to make equilibrium Y equal 1,000 is:","options":["170.","200.","250.","350."],"answer":"A","images":null,"translation":{"question":"用凯恩斯交叉分析，假设消费函数为 C = 200 + 0.7 (Y – T)。如果计划投资为 100，T 为 100，那么使均衡 Y 等于 1,000 所需的 G 水平是：","options":["170。","200。","250。","350。"]},"topics":["is-curve"]},{"num":71,"type":"mc","question":"In the Keynesian-cross analysis, assume that the analysis of taxes is changed so that taxes, T, are made a function of income, as in T = T + tY, where T and t are parameters of the tax code and t is positive but less than 1. As compared to a case where t is zero, the multiplier for government purchases in this case will:","options":["not change.","be smaller.","be bigger.","be equal to 1."],"answer":"B","images":null,"translation":{"question":"在凯恩斯交叉分析中，假设对税收的分析做了修改，使税收 T 成为收入的函数，即 T = T + tY，其中 T 和 t 是税法的参数，t 为正但小于 1。与 t 为零的情形相比，此时政府购买的乘数将：","options":["不变。","更小。","更大。","等于 1。"]},"topics":["is-curve"]},{"num":72,"type":"mc","question":"Assume that the money demand function is (M / P)d = 2,200 – 200r, where r is the interest rate in percent. The money supply M is 2,000, and the price level P is 2. The equilibrium interest rate is ______ percent.","options":["2","4","6","8"],"answer":"C","images":null,"translation":{"question":"假设货币需求函数为 (M / P)d = 2,200 – 200r，其中 r 是以百分比表示的利率。货币供给 M 为 2,000，价格水平 P 为 2。均衡利率为 ______%。","options":["2","4","6","8"]},"topics":["lm-curve"]},{"num":73,"type":"mc","question":"Assume that the money demand function is (M / P)d = 2,200 – 200r, where r is the interest rate in percent. The money supply M is 2,000, and the price level P is 2. If the price level is fixed and the supply of money is raised to 2,800, then the equilibrium interest rate will:","options":["drop by 4 percent.","drop by 2 percent.","drop by 1 percent.","remain unchanged."],"answer":"B","images":null,"translation":{"question":"假设货币需求函数为 (M / P)d = 2,200 – 200r，其中 r 是以百分比表示的利率。货币供给 M 为 2,000，价格水平 P 为 2。如果价格水平固定，且货币供给提高到 2,800，那么均衡利率将：","options":["下降 4 个百分点。","下降 2 个百分点。","下降 1 个百分点。","保持不变。"]},"topics":["lm-curve"]},{"num":74,"type":"mc","question":"Assume that the money demand function is (M / P)d = 2,200 – 200r, where r is the interest rate in percent. If the price level is fixed at P=2, and the Fed wants to fix the interest rate at 7 percent, it should set the money supply at:","options":["2,000.","1,800.","1,600.","1,400."],"answer":"C","images":null,"translation":{"question":"假设货币需求函数为 (M / P)d = 2,200 – 200r，其中 r 是以百分比表示的利率。如果价格水平固定在 P=2，而美联储希望把利率固定在 7%，它应该把货币供给设为：","options":["2,000。","1,800。","1,600。","1,400。"]},"topics":["lm-curve"]},{"num":75,"type":"sa","question":"Consider a closed economy to which the Keynesian-cross analysis applies. Consumption is given by the equation C = 200 + 2 / 3 (Y – T). Planned investment is 300, as are government spending and taxes. a. If Y is 1,500, what is planned spending? What is inventory accumulation or decumulation? Should equilibrium Y be higher or lower than 1,500? b. What is equilibrium Y? c. What are equilibrium consumption, private saving, public saving, and national saving? d. How much does equilibrium income decrease when G is reduced to 200? What is the multiplier for government spending?","options":null,"answer":null,"images":null,"translation":{"question":"考虑一个适用于凯恩斯交叉分析的封闭经济。消费由方程 C = 200 + 2 / 3 (Y – T) 给出。计划投资为 300，政府支出和税收也都是 300。a. 若 Y 为 1,500，计划支出是多少？存货积累或减少是多少？均衡 Y 应高于还是低于 1,500？b. 均衡 Y 是多少？c. 均衡消费、私人储蓄、公共储蓄和国民储蓄各是多少？d. 当 G 减少到 200 时，均衡收入减少多少？政府支出乘数是多少？","options":null},"topics":["is-curve"],"answer_ref":"a. 计划支出 PE = C+I+G = 200 + (2/3)(1500−300) + 300 + 300 = 1600。Y=1500 < PE=1600，库存减少（去存货 100），均衡收入应更高。b. 均衡：Y = 200 + (2/3)(Y−300) + 600 → (1/3)Y = 600 → Y = 1800。c. C = 200 + (2/3)×1500 = 1200；支出乘数 = 1/(1−2/3) = 3。"},{"num":76,"type":"sa","question":"Assume that the consumption function is given by C = 200 + 0.5 (Y – T), and the investment function is I = 1,000 – 200r, where r is measured in percent, G equals 300, and T equals 200. a. What is the numerical formula for the IS curve? (Hint: Substitute for C, I, and G in the equation Y = C + I + G and then write an equation for Y as a function of r or r as a function of Y.) Express the equation two ways: (1) Y as a function of r; (2) r as a function of Y. b. What is the slope of the IS curve? c. If r is 1 percent, what is I? What is Y? If r is 3 percent, what is I? What is Y? If r is 5 percent, what is I? What is Y? d. If G increases, does the IS curve shift upward and to the right or downward and to the left?","options":null,"answer":null,"images":null,"translation":{"question":"假设消费函数为 C = 200 + 0.5 (Y – T)，投资函数为 I = 1,000 – 200r，其中 r 以百分比计，G 等于 300，T 等于 200。a. IS 曲线的数值公式是什么？（提示：将 C、I 和 G 代入方程 Y = C + I + G，然后写出 Y 作为 r 的函数或 r 作为 Y 的函数的方程。）用两种方式表达该方程：(1) Y 作为 r 的函数；(2) r 作为 Y 的函数。b. IS 曲线的斜率是多少？c. 若 r 为 1%，I 是多少？Y 是多少？若 r 为 3%，I 是多少？Y 是多少？若 r 为 5%，I 是多少？Y 是多少？d. 若 G 增加，IS 曲线是向上且向右移动，还是向下且向左移动？","options":null},"topics":["is-curve"],"answer_ref":"IS 曲线：Y = 200 + 0.5(Y−200) + 1000 − 200r + 300 → 0.5Y = 1400 − 200r → Y = 2800 − 400r，或 r = 7 − Y/400。"},{"num":77,"type":"sa","question":"Assume that money demand is given by (M / P)d = 0.5Y – 100r, and (M / P)s equals 800. a. Write the LM curve two ways, expressing Y as a function of r and r as a function of Y. (Hint: Write the LM curve only relating Y and r using the equilibrium condition for the market for real money balances.) b. What is the slope of the LM curve (where r is on the y-axis and Y on the x-axis)? c. If r is 1 percent, what is Y along the LM curve? If r is 3 percent, what is Y along the LM curve? If r is 5 percent, what is Y along the LM curve? d. If M/P increases, does the LM curve shift upward and to the left or downward and to the right? e. If M increases and P is constant, does the LM curve shift upward and to the left or downward and to the right? f. If P increases and M is constant, does the LM curve shift upward and to the left or downward and to the right?","options":null,"answer":null,"images":null,"translation":{"question":"假设货币需求由 (M / P)d = 0.5Y – 100r 给出，且 (M / P)s 等于 800。a. 用两种方式写出 LM 曲线，将 Y 表示为 r 的函数，以及将 r 表示为 Y 的函数。（提示：利用实际货币余额市场的均衡条件，写出只涉及 Y 和 r 的 LM 曲线。）b. LM 曲线的斜率是多少（其中 r 在 y 轴上，Y 在 x 轴上）？c. 若 r 为 1%，沿 LM 曲线的 Y 是多少？若 r 为 3%，沿 LM 曲线的 Y 是多少？若 r 为 5%，沿 LM 曲线的 Y 是多少？d. 若 M/P 增加，LM 曲线是向上且向左移动，还是向下且向右移动？e. 若 M 增加而 P 不变，LM 曲线是向上且向左移动，还是向下且向右移动？f. 若 P 增加而 M 不变，LM 曲线是向上且向左移动，还是向下且向右移动？","options":null},"topics":["lm-curve"],"answer_ref":"a. 由 800 = 0.5Y − 100r：Y = 1600 + 200r；r = 0.005Y − 8。b. 斜率 dr/dY = 0.005（r 以百分点计）。c. r=1：Y = 1600 + 200×1 = 1800。"},{"num":78,"type":"sa","question":"a. Suppose Congress decides to reduce the budget deficit by cutting government spending. Use the Keynesian-cross model to illustrate graphically the impact of a reduction in government purchases on the equilibrium level of income. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curve shifts; and v. the terminal equilibrium values. b. Explain in words what happens to equilibrium income as a result of the cut in government spending and the time horizon appropriate for this analysis.","options":null,"answer":null,"images":null,"translation":{"question":"a. 假设国会决定通过削减政府支出来减少预算赤字。请用凯恩斯交叉模型以图形说明政府购买减少对收入均衡水平的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。b. 用文字解释政府支出削减后均衡收入会发生什么变化，以及这一分析适用的时间范围。","options":null},"topics":["is-curve"],"answer_ref":"a. 图（45°线模型：横轴 Y，纵轴支出）：计划支出线平行下移 ΔG，与 45° 线交于更低的均衡收入。b. G↓→计划支出↓→原均衡处出现非意愿存货积累→企业减产→收入与消费连锁下降→均衡收入减少 ΔG/(1−MPC)。乘数放大了初始冲击。"},{"num":79,"type":"sa","question":"a. Suppose Congress passes legislation that significantly reduces taxes. Use the Keynesian-cross model to illustrate graphically the impact of a reduction in taxes on the equilibrium level of income. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curve shifts; and v. the terminal equilibrium values. b. Explain in words what happens to equilibrium income as a result of the tax cut and the time horizon appropriate for this analysis.","options":null,"answer":null,"images":null,"translation":{"question":"a. 假设国会通过了一项大幅减税的立法。请用凯恩斯交叉模型以图形说明税收减少对收入均衡水平的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。b. 用文字解释减税后均衡收入会发生什么变化，以及这一分析适用的时间范围。","options":null},"topics":["is-curve"],"answer_ref":"a. 图：减税使计划支出线上移 MPC×减税额（截距上移），与 45° 线交于更高的均衡收入。b. 税收↓→可支配收入↑→消费↑→存货减少→产出扩大→收入增加再带动消费：均衡收入增加 [MPC/(1−MPC)]×ΔT。税收乘数小于支出乘数，因第一轮只影响消费中的一部分。"},{"num":80,"type":"sa","question":"a. Use the Keynesian-cross model to illustrate graphically the impact of an increase in the interest rate on the equilibrium level of income. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curve shifts; and v. the terminal equilibrium values. b. Explain in words what happens to equilibrium income as a result of the increase in the interest rate.","options":null,"answer":null,"images":null,"translation":{"question":"a. 请用凯恩斯交叉模型以图形说明利率上升对收入均衡水平的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。b. 用文字解释利率上升后均衡收入会发生什么变化。","options":null},"topics":["is-curve"],"answer_ref":"a. 图：利率↑使投资减少，计划支出线下移，与 45° 线交于更低收入。b. r↑→计划投资 I(r)↓→计划支出↓→均衡收入下降——这是把利率引入商品市场的关键渠道（也是 IS 曲线向下倾斜的基础）。"},{"num":81,"type":"sa","question":"a. Graphically illustrate the impact of an open-market purchase by the Federal Reserve on the equilibrium interest rate in the market for real money balances. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curve shifts; and v. the terminal equilibrium values. b. Explain in words what happens to the equilibrium interest rate as a result of the open-market purchase.","options":null,"answer":null,"images":null,"translation":{"question":"a. 用图形说明美联储的公开市场买入对实际货币余额市场均衡利率的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。b. 用文字解释公开市场买入后均衡利率会发生什么变化。","options":null},"topics":["lm-curve"],"answer_ref":"a. 图（实际货币余额市场：横轴 M/P，纵轴 r）：供给曲线由 M̅/P 右移至 M′/P，需求曲线不变，均衡利率由 r₁ 降至 r₂。b. 公开市场买入增加货币供给→在原有利率下货币供过于求→公众购买债券→债券价格上升、收益率即利率下降。"},{"num":82,"type":"sa","question":"a. As an economy moves into a recession, income falls. Illustrate graphically the impact of a decrease in income on the equilibrium interest rate in the market for real money balances. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curve shifts; and v. the terminal equilibrium values. b. Explain in words what happens to the equilibrium interest rate as a result of the fall in income.","options":null,"answer":null,"images":null,"translation":{"question":"a. 当经济陷入衰退时，收入下降。请用图形说明收入下降对实际货币余额市场均衡利率的冲击。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。b. 用文字解释收入下降后均衡利率会发生什么变化。","options":null},"topics":["lm-curve"],"answer_ref":"a. 图：收入下降使货币需求曲线左移，均衡利率由 r₁ 降至 r₂。b. Y↓→交易性货币需求↓→货币需求曲线左移→在供给不变时利率下降。衰退有自动压低利率、刺激投资的稳定机制。"},{"num":83,"type":"sa","question":"In explaining the 2003 bill to cut taxes, President Bush is quoted as saying, “When people have more money, they can spend it on goods and services.” a. In the IS–LM model, will a tax cut change the money supply in the economy? Does a change in the money supply shift the IS or the LM curve? b. In the IS–LM model, does a tax cut shift the IS or the LM curve? c. Based on your answers in a and b, how can you reconcile the president's statement with economics? Can you suggest how his statement could be modified to be consistent with the IS–LM model?","options":null,"answer":null,"images":null,"translation":{"question":"在解释2003年减税法案时，布什总统被引述说：“当人们有更多钱时，他们就能把钱花在商品和服务上。”a. 在 IS–LM 模型中，减税会改变经济中的货币供给吗？货币供给的改变会使 IS 曲线还是 LM 曲线移动？b. 在 IS–LM 模型中，减税会使 IS 曲线还是 LM 曲线移动？c. 根据你在 a 和 b 中的回答，你如何调和总统的这一说法与经济学的关系？你能建议如何修改他的说法以使其与 IS–LM 模型一致吗？","options":null},"topics":["islm-model"],"answer_ref":"a. 减税不改变货币供给；货币供给的变动移动 LM 曲线。b. 减税通过提高可支配收入增加消费，移动 IS 曲线（右移）。c. 收入上升来自 IS 右移与乘数过程，而非\"人们有钱就花\"这么简单：利率上升会挤出部分投资，使最终增幅小于简单乘数预测；但均衡收入确实增加。"},{"num":84,"type":"sa","question":"Two identical countries, Country A and Country B, can each be described by a Keynesian-cross model. The MPC is 0.7 in each country. Country A decides to increase spending by $2 billion, while Country B decides to cut taxes by $2 billion. In which country will the new equilibrium level of income be greater?","options":null,"answer":null,"images":null,"translation":{"question":"两个完全相同的国家，A 国和 B 国，都可用凯恩斯交叉模型来描述。两国的 MPC 都是 0.7。A 国决定增加支出20亿美元，而 B 国决定减税20亿美元。哪个国家新的收入均衡水平会更大？","options":null},"topics":["is-curve"],"answer_ref":"A 国（增支 20 亿）：ΔY = 20/(1−0.7) ≈ 66.7 亿。B 国（减税 20 亿）：ΔY = [0.7/(1−0.7)]×20 ≈ 46.7 亿。A 国的新均衡收入更高——支出乘数 1/(1−MPC)=3.33 大于税收乘数 MPC/(1−MPC)=2.33，因为减税的第一轮只刺激消费的一部分。"},{"num":85,"type":"sa","question":"a. The interest rate affects which variable in (1) the market for goods and services and (2) the market for real money balances? b. The level of income affects which variable in (1) the market for goods and services and (2) the market for real money balances?","options":null,"answer":null,"images":null,"translation":{"question":"a. 利率分别影响 (1) 产品和服务市场以及 (2) 实际货币余额市场中的哪个变量？b. 收入水平分别影响 (1) 产品和服务市场以及 (2) 实际货币余额市场中的哪个变量？","options":null},"topics":["islm-model"],"answer_ref":"a. (1) 商品与服务市场：利率影响投资 I。(2) 实际货币余额市场：利率是\"货币的价格\"，使货币供求相等。b. (1) 商品市场：收入影响消费（进而通过乘数影响均衡）。(2) 货币市场：收入影响交易性货币需求。两个市场通过 (r, Y) 这对变量互相咬合。"},{"num":86,"type":"sa","question":"Compare the predicted impact of an increase in the money supply in the liquidity preference model versus the impact predicted by the quantity theory and the Fisher effect. Can you reconcile this difference?","options":null,"answer":null,"images":null,"translation":{"question":"比较流动性偏好模型与数量论及费雪效应对货币供给增加所预测的影响。你能调和这一差异吗？","options":null},"topics":["lm-curve"],"answer_ref":"流动性偏好（短期、价格粘性）：M↑→r↓，实际利率下降。数量论与费雪效应（长期、价格弹性）：货币增长只提高通胀与名义利率，实际利率不变。调和：短期价格不能调整，货币变动影响实际利率与产出；长期货币中性，货币增长完全反映在通胀与名义利率上。两个结论分别对应两个时间框架。"},{"num":87,"type":"sa","question":"The IS–LM model simultaneously determines equilibrium in two markets. a. Which two markets? b. What two variables adjust to bring equilibrium in the markets?","options":null,"answer":null,"images":null,"translation":{"question":"IS–LM 模型同时确定两个市场的均衡。a. 是哪两个市场？b. 哪两个变量进行调整以使市场达到均衡？","options":null},"topics":["islm-model"],"answer_ref":"a. 商品与服务（可贷资金/商品）市场和货币市场（实际货币余额市场）。b. 利率 r 和收入水平 Y 两个变量同时调整，使两个市场同时出清——r 主要在货币市场定价、Y 由商品市场决定，二者联立。"},{"num":88,"type":"sa","question":"a. Graphically illustrate how an increase in income affects the equilibrium levels of saving, investment, and the interest rate in the loanable funds model. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curve shifts; and v. the terminal equilibrium values. b. Explain in words what happens to the equilibrium levels of saving, investment, and the interest rates as a result of the increase in income.","options":null,"answer":null,"images":null,"translation":{"question":"a. 用图形说明在可贷资金模型中，收入增加如何影响储蓄、投资和利率的均衡水平。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。b. 用文字解释收入增加后储蓄、投资和利率的均衡水平会发生什么变化。","options":null},"topics":["islm-model"],"answer_ref":"a. 图（可贷资金：纵轴 r，横轴 S/I）：收入↑→储蓄曲线右移（S=Y−C−G），投资曲线不变→r 由 r₁ 降至 r₂，S 与 I 同额增加。b. 收入增加同时提高意愿储蓄与均衡投资量，靠的是利率下降既刺激投资又抑制部分储蓄意愿。"},{"num":89,"type":"sa","question":"How can the government expenditure multiplier be reinterpreted in terms of the marginal propensity to save MPS = 1 – MPC?","options":null,"answer":null,"images":null,"translation":{"question":"如何用边际储蓄倾向 MPS = 1 – MPC 来重新解释政府支出乘数？","options":null},"topics":["is-curve"],"answer_ref":"乘数 = 1/(1−MPC) = 1/MPS：每轮支出中有一部分（MPS）漏入储蓄而不再循环。把每轮增量求和：1 + (1−MPS) + (1−MPS)² + … = 1/MPS。边际储蓄倾向越高（MPC 越低），漏损越快，乘数越小。"},{"num":90,"type":"sa","question":"The diagram below shows how a rise in government expenditure (G) shifts the IS curve from IS1 to IS2. What are the levels of investments in Y1 and Y2 for a fixed r?","options":null,"answer":null,"images":null,"translation":{"question":"下图显示了政府支出 (G) 的上升如何使 IS 曲线从 IS1 移动到 IS2。在固定的 r 下，Y1 和 Y2 处的投资水平分别是多少？","options":null},"topics":["is-curve"],"answer_ref":"投资只取决于利率：r 固定时，无论 Y₁ 还是 Y₂，投资水平都相同（I = I(r)）。IS 右移提高收入，但在给定利率下不引起投资变化——收入上升与利率上升相伴发生时，才会出现投资被挤出。"},{"num":91,"type":"sa","question":"A downward-sloping investment function yields a falling IS curve, but a downward-sloping demand for real money balance curve yields a rising LM curve. Why?","options":null,"answer":null,"images":["c11_img6.png"],"translation":{"question":"向下倾斜的投资函数产生向下倾斜的 IS 曲线，而向下倾斜的实际货币余额需求曲线却产生向上倾斜的 LM 曲线。为什么？","options":null},"topics":["islm-model"],"answer_ref":"IS 向下倾斜：r↑→I(r)↓→计划支出↓→均衡 Y↓，故 Y 与 r 负相关。LM 向上倾斜：Y↑→交易性货币需求↑→在货币供给固定时，必须提高 r 来压缩投机性需求，才能维持货币市场均衡，故 Y 与 r 正相关。两曲线斜率来自货币需求对 r 与 Y 的不同敏感度。"},{"num":92,"type":"sa","question":"The demand for money helps determine the equilibrium level of the interest rate, even though holding money does not earn any interest income. How is this possible?","options":null,"answer":null,"images":null,"translation":{"question":"尽管持有货币不获得任何利息收入，货币需求却有助于决定利率的均衡水平。这怎么可能？","options":null},"topics":["lm-curve"],"answer_ref":"货币虽不付息，但提供流动性便利（交易媒介，省去频繁兑换证券的麻烦）。利率是持有货币的机会成本——利率越高，持币越不划算，货币需求越少。货币市场均衡条件 M/P = L(Y, r) 中，r 作为价格使供求相等；货币需求随 r 递减保证了均衡利率的存在与唯一。"},{"num":93,"type":"sa","question":"Assume that planned expenditure consists of consumption, investment, and government expenditures only and that investment and government expenditures are fixed. Further, assume that consumption C = c (Y – tY), where tY denotes taxes as a function of income. Calculate the equilibrium level of Y and the government expenditure multiplier.","options":null,"answer":null,"images":null,"translation":{"question":"假设计划支出仅由消费、投资和政府支出构成，且投资和政府支出是固定的。进一步假设消费 C = c (Y – tY)，其中 tY 表示作为收入函数的税收。请计算均衡的 Y 水平和政府支出乘数。","options":null},"topics":["is-curve"],"answer_ref":"Y = c(Y−tY) + Ī + Ḡ → Y[1 − c(1−t)] = Ī + Ḡ → 均衡收入 Y = (Ī+Ḡ)/[1 − c(1−t)]。政府支出乘数 = 1/[1 − c(1−t)] = 1/(1 − MPC + MPC·t)。税收随收入上升（t>0）自动构成稳定器，使乘数变小。"},{"num":94,"type":"sa","question":"Assume that a government decides to maintain a constant interest rate in the money market and adjusts the money supply accordingly. What would be the impact of such a policy on the LM curve and on the IS curve?","options":null,"answer":null,"images":null,"translation":{"question":"假设一个政府决定在货币市场中维持不变的利率，并相应地调整货币供给。这一政策会对 LM 曲线和 IS 曲线产生什么影响？","options":null},"topics":["islm-model"],"answer_ref":"央行维持利率不变→货币供给随货币需求内生调整→LM 曲线在该利率水平呈水平线（完全利率目标制）。IS 曲线不受影响，但财政政策完全有效：IS 右移不再引起利率上升，不存在挤出效应，收入按简单乘数扩张。"},{"num":95,"type":"sa","question":"Assume an economy where the consumption function is defined as C = CC + cY, and the investment function is defined as I = mr, where Y is total income, and r is the interest rate. What does the slope of the IS curve depend on?","options":null,"answer":null,"images":null,"translation":{"question":"假设某经济的消费函数定义为 C = CC + cY，投资函数定义为 I = mr，其中 Y 为总收入，r 为利率。IS 曲线的斜率取决于什么？","options":null},"topics":["is-curve"],"answer_ref":"由 Y = CC + cY + m·r → (1−c)Y = CC + m·r → dr/dY = (1−c)/m。IS 斜率取决于：①边际消费倾向 c——c 越大斜率越小（IS 越平缓）；②投资对利率的敏感度 m——m 越大斜率越小。IS 的平坦程度由消费与投资的利率/收入敏感度共同决定。"}]},{"num":12,"title":"Aggregate Demand II","questions":[{"num":1,"type":"mc","question":"The interaction of the IS curve and the LM curve determines:","options":["the price level and the inflation rate.","the level of output and the price level.","investment and the money supply.","the equilibrium level of the interest rate and output."],"answer":"D","images":null,"translation":{"question":"IS 曲线与 LM 曲线的相互作用决定了：","options":["价格水平与通胀率。","产出水平与价格水平。","投资与货币供给。","利率与产出的均衡水平。"]},"topics":["islm-policy"]},{"num":2,"type":"mc","question":"Exhibit: IS–LM Fiscal Policy Based on the graph, starting from equilibrium at interest rate r1 and income Y1, a decrease in government spending would generate the new equilibrium combination of interest rate and income:","options":["r2, Y2.","r3, Y2.","r2, Y3.","r1, Y2."],"answer":"B","images":null,"translation":{"question":"图：IS–LM 财政政策。根据该图，从利率 r1、收入 Y1 的均衡出发，政府支出减少将产生新的利率与收入均衡组合：","options":["r2，Y2。","r3，Y2。","r2，Y3。","r1，Y2。"]},"topics":["islm-policy"]},{"num":3,"type":"mc","question":"Exhibit: IS–LM Fiscal Policy Based on the graph, starting from equilibrium at interest rate r1 and income Y1, an increase in government spending would generate the new equilibrium combination of interest rate and income:","options":["r2, Y2","r3, Y2","r2, Y3","r3, Y3"],"answer":"C","images":["c12_img0.png"],"translation":{"question":"图：IS–LM 财政政策。根据该图，从利率 r1、收入 Y1 的均衡出发，政府支出增加将产生新的利率与收入均衡组合：","options":["r2，Y2。","r3，Y2。","r2，Y3。","r3，Y3。"]},"topics":["islm-policy"]},{"num":4,"type":"mc","question":"Exhibit: IS–LM Fiscal Policy Based on the graph, starting from equilibrium at interest rate r1 and income Y1, a tax cut would generate the new equilibrium combination of interest rate and income:","options":["r2, Y2.","r3, Y2.","r2, Y3.","r3, Y3."],"answer":"C","images":["c12_img1.png"],"translation":{"question":"图：IS–LM 财政政策。根据该图，从利率 r1、收入 Y1 的均衡出发，减税将产生新的利率与收入均衡组合：","options":["r2，Y2。","r3，Y2。","r2，Y3。","r3，Y3。"]},"topics":["islm-policy"]},{"num":5,"type":"mc","question":"If the LM curve is vertical and government spending rises by G, in the IS–LM analysis, then equilibrium income rises by:","options":["G / (1 – MPC).","more than zero but less than G / (1 – MPC).","G.","zero."],"answer":"D","images":["c12_img2.png"],"translation":{"question":"如果 LM 曲线是垂直的，且政府支出增加 G，则在 IS–LM 分析中，均衡收入增加：","options":["G / (1 – MPC)。","大于零但小于 G / (1 – MPC)。","G。","零。"]},"topics":["islm-policy"]},{"num":6,"type":"mc","question":"If MPC = 0.6 (and there are no income taxes) when G increases by 200, then the IS curve for any given interest rate shifts to the right by:","options":["200.","300.","400.","500."],"answer":"D","images":null,"translation":{"question":"如果 MPC = 0.6（且没有所得税），当 G 增加 200 时，在任一给定利率下 IS 曲线向右移动：","options":["200。","300。","400。","500。"]},"topics":["islm-policy"]},{"num":7,"type":"mc","question":"If MPC = 0.6 (and there are no income taxes but only lump-sum taxes) when T decreases by 200, then the IS curve for any given interest rate shifts to the right by:","options":["100.","200.","300.","400."],"answer":"C","images":null,"translation":{"question":"如果 MPC = 0.6（且没有所得税，只有定额税），当 T 减少 200 时，在任一给定利率下 IS 曲线向右移动：","options":["100。","200。","300。","400。"]},"topics":["islm-policy"]},{"num":8,"type":"mc","question":"In the IS–LM model in a closed economy, an increase in government spending increases the interest rate and crowds out:","options":["prices.","investment.","the money supply.","taxes."],"answer":"B","images":null,"translation":{"question":"在封闭经济的 IS–LM 模型中，政府支出增加会提高利率并挤出：","options":["价格。","投资。","货币供给。","税收。"]},"topics":["islm-policy"]},{"num":9,"type":"mc","question":"Using the IS–LM analysis, if the LM curve is not horizontal, the multiplier for an increase in government spending is ______ for an increase in government purchases using the Keynesian-cross analysis.","options":["larger than the multiplier","the same as the multiplier","smaller than the multiplier","sometimes larger and sometimes smaller than the multiplier"],"answer":"C","images":null,"translation":{"question":"用 IS–LM 分析，如果 LM 曲线不是水平的，政府支出增加的乘数与用凯恩斯交叉分析政府购买增加的乘数相比：","options":["更大。","相同。","更小。","有时更大有时更小。"]},"topics":["islm-policy"]},{"num":10,"type":"mc","question":"The reason that the income response to a fiscal expansion is generally less in the IS–LM model than it is in the Keynesian-cross model is that the Keynesian-cross model assumes that:","options":["investment is not affected by the interest rate, whereas in the IS–LM model fiscal expansion raises the interest rate and crowds out investment.","investment is not affected by the interest rate, whereas in the IS–LM model fiscal expansion lowers the interest rate and crowds out investment.","investment is autonomous, whereas in the IS–LM model fiscal expansion encourages higher investment, which raises the interest rate.","the price level is fixed, whereas in the IS–LM model it is allowed to vary."],"answer":"A","images":null,"translation":{"question":"IS–LM 模型中收入对财政扩张的反应通常小于凯恩斯交叉模型的原因是，凯恩斯交叉模型假设：","options":["投资不受利率影响，而在 IS–LM 模型中财政扩张会提高利率并挤出投资。","投资不受利率影响，而在 IS–LM 模型中财政扩张会降低利率并挤出投资。","投资是自发的，而在 IS–LM 模型中财政扩张鼓励更高的投资，从而抬高利率。","价格水平固定，而在 IS–LM 模型中价格水平允许变动。"]},"topics":["islm-policy"]},{"num":11,"type":"mc","question":"In the IS–LM model, changes in taxes initially affect planned expenditures through:","options":["consumption.","investment.","government spending.","the interest rate."],"answer":"A","images":null,"translation":{"question":"在 IS–LM 模型中，税收变化最初通过以下哪项影响计划支出：","options":["消费。","投资。","政府支出。","利率。"]},"topics":["islm-policy"]},{"num":12,"type":"mc","question":"In the IS–LM analysis, the increase in income resulting from a tax cut is ______ the increase in income resulting from an equal rise in government spending.","options":["usually less than","usually greater than","usually equal to","sometimes less and sometimes greater than"],"answer":"A","images":null,"translation":{"question":"在 IS–LM 分析中，减税带来的收入增加与等量政府支出增加带来的收入增加相比：","options":["通常小于。","通常大于。","通常等于。","有时小于有时大于。"]},"topics":["islm-policy"]},{"num":13,"type":"mc","question":"Exhibit: IS–LM Monetary Policy Based on the graph, starting from equilibrium at interest rate r1 and income Y1, a decrease in the money supply would generate the new equilibrium combination of interest rate and income:","options":["r2, Y2","r3, Y2","r2, Y3","r3, Y3"],"answer":"A","images":null,"translation":{"question":"图：IS–LM 货币政策。根据该图，从利率 r1、收入 Y1 的均衡出发，货币供给减少将产生新的利率与收入均衡组合：","options":["r2，Y2。","r3，Y2。","r2，Y3。","r3，Y3。"]},"topics":["islm-policy"]},{"num":14,"type":"mc","question":"Exhibit: IS–LM Monetary Policy Based on the graph, starting from equilibrium at interest rate r1 and income Y1, an increase in the money supply would generate the new equilibrium combination of interest rate and income:","options":["r2, Y2.","r3, Y2.","r2, Y3.","r3, Y3."],"answer":"D","images":["c12_img3.png"],"translation":{"question":"图：IS–LM 货币政策。根据该图，从利率 r1、收入 Y1 的均衡出发，货币供给增加将产生新的利率与收入均衡组合：","options":["r2，Y2。","r3，Y2。","r2，Y3。","r3，Y3。"]},"topics":["islm-policy"]},{"num":15,"type":"mc","question":"In the IS–LM model when M / P rises, in short-run equilibrium, in the usual case the interest rate ______ and output ______.","options":["rises; falls","rises; rises","falls; rises","falls; falls"],"answer":"C","images":["c12_img4.png"],"translation":{"question":"在 IS–LM 模型中，当 M / P 上升时，在短期均衡中，通常利率 ______，产出 ______。","options":["上升；下降","上升；上升","下降；上升","下降；下降"]},"topics":["islm-policy"]},{"num":16,"type":"mc","question":"In the IS–LM model when M remains constant but P rises, in short-run equilibrium, in the usual case the interest rate ______ and output ______.","options":["rises; falls","rises; rises","falls; rises","falls; falls"],"answer":"A","images":null,"translation":{"question":"在 IS–LM 模型中，当 M 保持不变但 P 上升时，在短期均衡中，通常利率 ______，产出 ______。","options":["上升；下降","上升；上升","下降；上升","下降；下降"]},"topics":["islm-policy"]},{"num":17,"type":"mc","question":"In the IS–LM model when the Federal Reserve decreases the money supply, the public ______ bonds, and the interest rate ______, leading to a(n) ______ in investment and income. This is called the monetary transmission mechanism.","options":["buy; rises; increase","sell; falls; decrease","sell; rises; decrease","buy; rises; decrease"],"answer":"C","images":null,"translation":{"question":"在 IS–LM 模型中，当美联储减少货币供给时，公众 ______ 债券，利率 ______，导致投资和收入 ______。这被称为货币传导机制。","options":["买入；上升；增加","卖出；下降；减少","卖出；上升；减少","买入；上升；减少"]},"topics":["islm-policy"]},{"num":18,"type":"mc","question":"Exhibit: Policy Interaction Based on the graph, starting from equilibrium at interest rate r3, income Y2, IS1, and LM1, if there is an increase in government spending that shifts the IS curve to IS2, then in order to keep the interest rate constant, the Federal Reserve should _____ the money supply, shifting to _____.","options":["increase; LM2","decrease; LM2","increase; LM3","decrease; LM3"],"answer":"A","images":null,"translation":{"question":"图：政策互动。根据该图，从利率 r3、收入 Y2、IS1 和 LM1 的均衡出发，若政府支出增加使 IS 曲线移至 IS2，则为保持利率不变，美联储应 ______ 货币供给，移至 ______。","options":["增加；LM2","减少；LM2","增加；LM3","减少；LM3"]},"topics":["islm-policy"]},{"num":19,"type":"mc","question":"Exhibit: Policy Interaction Based on the graph, starting from equilibrium at interest rate r3, income Y2, IS1, and LM1, if there is an increase in government spending that shifts the IS curve to IS2, then in order to keep output constant, the Federal Reserve should _____ the money supply, shifting to _____.","options":["increase; LM2","decrease; LM2","increase; LM3","decrease; LM3"],"answer":"D","images":["c12_img5.png"],"translation":{"question":"图：政策互动。根据该图，从利率 r3、收入 Y2、IS1 和 LM1 的均衡出发，若政府支出增加使 IS 曲线移至 IS2，则为保持产出不变，美联储应 ______ 货币供给，移至 ______。","options":["增加；LM2","减少；LM2","增加；LM3","减少；LM3"]},"topics":["islm-policy"]},{"num":20,"type":"mc","question":"Exhibit: Policy Interaction Based on the graph, starting from equilibrium at interest rate r3, income Y2, IS1, and LM1, if there is an increase in government spending that shifts the IS curve to IS2 and the Federal Reserve does not change the money supply, the new equilibrium combination of interest and income will be _____.","options":["r1, Y2","r2, Y3","r3, Y3","r3, Y4"],"answer":"B","images":["c12_img6.png"],"translation":{"question":"图：政策互动。根据该图，从利率 r3、收入 Y2、IS1 和 LM1 的均衡出发，若政府支出增加使 IS 曲线移至 IS2，且美联储不改变货币供给，则新的利率与收入均衡组合将为 ______。","options":["r1，Y2","r2，Y3","r3，Y3","r3，Y4"]},"topics":["islm-policy"]},{"num":21,"type":"mc","question":"An increase in investment demand for any given level of income and interest rates—due, for example, to more optimistic “animal spirits”—will, within the IS–LM framework, ______ output and ______ interest rates.","options":["increase; lower","increase; raise","lower; lower","lower; raise"],"answer":"B","images":["c12_img7.png"],"translation":{"question":"在任一给定收入和利率水平下，投资需求增加——例如由于更乐观的“动物精神”——将在 IS–LM 框架内 ______ 产出并 ______ 利率。","options":["增加；降低","增加；提高","降低；降低","降低；提高"]},"topics":["islm-policy"]},{"num":22,"type":"mc","question":"An increase in consumer saving for any given level of income will shift the:","options":["LM curve upward and to the left.","LM curve downward and to the right.","IS curve downward and to the left.","IS curve upward and to the right."],"answer":"C","images":null,"translation":{"question":"在任一给定收入水平下，消费者储蓄增加将使：","options":["LM 曲线向上向左移动。","LM 曲线向下向右移动。","IS 曲线向下向左移动。","IS 曲线向上向右移动。"]},"topics":["islm-policy"]},{"num":23,"type":"mc","question":"An increase in the demand for money, at any given income level and level of interest rates, will, within the IS–LM framework, ______ output and ______ interest rates.","options":["increase; lower","increase; raise","lower; lower.","lower; raise"],"answer":"D","images":null,"translation":{"question":"在任一给定收入和利率水平下，货币需求增加将在 IS–LM 框架内 ______ 产出并 ______ 利率。","options":["增加；降低","增加；提高","降低；降低","降低；提高"]},"topics":["islm-policy"]},{"num":24,"type":"mc","question":"In the IS–LM model, a decrease in the interest rate would be the result of a(n):","options":["increase in the money supply.","increase in government purchases.","decrease in taxes.","increase in money demand."],"answer":"A","images":null,"translation":{"question":"在 IS–LM 模型中，利率下降会是以下哪项的结果：","options":["货币供给增加。","政府购买增加。","减税。","货币需求增加。"]},"topics":["islm-policy"]},{"num":25,"type":"mc","question":"In the IS–LM model, a decrease in output would be the result of a(n):","options":["decrease in taxes.","increase in the money supply.","increase in money demand.","increase in government purchases."],"answer":"C","images":null,"translation":{"question":"在 IS–LM 模型中，产出下降会是以下哪项的结果：","options":["减税。","货币供给增加。","货币需求增加。","政府购买增加。"]},"topics":["islm-policy"]},{"num":26,"type":"mc","question":"The U.S. recession of 2001 can be explained in part by a declining stock market and terrorist attacks. Both of these shocks can be represented in the IS–LM model by shifting the ______ curve to the ______.","options":["LM; right","LM; left","IS; right","IS; left"],"answer":"D","images":null,"translation":{"question":"2001 年的美国衰退可部分由股市下跌和恐怖袭击来解释。这两类冲击在 IS–LM 模型中可表示为 ______ 曲线向 ______ 移动。","options":["LM；右","LM；左","IS；右","IS；左"]},"topics":["islm-policy"]},{"num":27,"type":"mc","question":"One policy response to the U.S. economic slowdown of 2001 was tax cuts. This policy response can be represented in the IS–LM model by shifting the ______ curve to the ______.","options":["LM; right","LM; left","IS; right","IS; left"],"answer":"C","images":null,"translation":{"question":"对美国 2001 年经济放缓的一项政策反应是减税。这一政策反应在 IS–LM 模型中可表示为 ______ 曲线向 ______ 移动。","options":["LM；右","LM；左","IS；右","IS；左"]},"topics":["islm-policy"]},{"num":28,"type":"mc","question":"One policy response to the U.S. economic slowdown of 2001 was to increase money growth. This policy response can be represented in the IS–LM model by shifting the ______ curve to the ______.","options":["LM; right","LM; left","IS; right","IS; left"],"answer":"A","images":null,"translation":{"question":"对美国 2001 年经济放缓的一项政策反应是提高货币增长。这一政策反应在 IS–LM 模型中可表示为 ______ 曲线向 ______ 移动。","options":["LM；右","LM；左","IS；右","IS；左"]},"topics":["islm-policy"]},{"num":29,"type":"mc","question":"The aggregate demand curve generally slopes downward and to the right because, for any given money supply M, a higher price level P causes a ______ real money supply M / P, which ______ the interest rate and ______ spending.","options":["lower; raises; reduces","higher; lowers; increases","lower; lowers; increases","higher; raises; reduces"],"answer":"A","images":null,"translation":{"question":"总需求曲线一般向右下方倾斜，因为对于任一给定的货币供给 M，较高的价格水平 P 会导致 ______ 的实际货币供给 M / P，从而 ______ 利率并 ______ 支出。","options":["更低；提高；减少","更高；降低；增加","更低；降低；增加","更高；提高；减少"]},"topics":["islm-policy"]},{"num":30,"type":"mc","question":"An economic change that does not shift the aggregate demand curve is a change in:","options":["the money supply.","the investment function.","the price level.","taxes."],"answer":"C","images":null,"translation":{"question":"不会使总需求曲线移动的经济变化是：","options":["货币供给的变化。","投资函数的变化。","价格水平的变化。","税收的变化。"]},"topics":["islm-policy"]},{"num":31,"type":"mc","question":"An increase in the money supply shifts the ______ curve to the right, and the aggregate demand curve ______.","options":["IS; shifts to the right","IS; does not shift","LM; shifts to the right","LM; does not shift"],"answer":"C","images":null,"translation":{"question":"货币供给增加使 ______ 曲线向右移动，总需求曲线 ______。","options":["IS；向右移动","IS；不移动","LM；向右移动","LM；不移动"]},"topics":["islm-policy"]},{"num":32,"type":"mc","question":"A tax cut shifts the ______ curve to the right, and the aggregate demand curve ______.","options":["IS; shifts to the right","IS; does not shift","LM; shifts to the right","LM; does not shift"],"answer":"A","images":null,"translation":{"question":"减税使 ______ 曲线向右移动，总需求曲线 ______。","options":["IS；向右移动","IS；不移动","LM；向右移动","LM；不移动"]},"topics":["islm-policy"]},{"num":33,"type":"mc","question":"A decrease in the price level shifts the ______ curve to the right, and the aggregate demand curve ______.","options":["IS; shifts to the right","IS; does not shift","LM; shifts to the right","LM; does not shift"],"answer":"D","images":null,"translation":{"question":"价格水平下降使 ______ 曲线向右移动，总需求曲线 ______。","options":["IS；向右移动","IS；不移动","LM；向右移动","LM；不移动"]},"topics":["islm-policy"]},{"num":34,"type":"mc","question":"A change in income in the IS–LM model resulting from a change in the price level is represented by a ______ aggregate demand curve, while a change in income in the IS–LM model for a given price level is represented by a ______ aggregate demand curve.","options":["movement along the; shift in the","shift in the; movement along the","vertical; horizontal","horizontal; vertical"],"answer":"A","images":null,"translation":{"question":"IS–LM 模型中由价格水平变化引起的收入变化由总需求曲线的 ______ 表示，而给定价格水平下 IS–LM 模型中的收入变化由总需求曲线的 ______ 表示。","options":["沿……移动；移动","移动；沿……移动","垂直的；水平的","水平的；垂直的"]},"topics":["islm-policy"]},{"num":35,"type":"mc","question":"Exhibit: IS–LM to Aggregate Demand Based on the graph, which is the correct ordering of the price levels and money supplies?","options":["P1 > P2 and M1 > M2","P1 > P2 and M1 < M2","P1 < P2 and M1 > M2","P1 < P2 and M1 < M2"],"answer":"B","images":null,"translation":{"question":"图：从 IS–LM 到总需求。根据该图，价格水平和货币供给的正确排序是哪个？","options":["P1 > P2 且 M1 > M2","P1 > P2 且 M1 < M2","P1 < P2 且 M1 > M2","P1 < P2 且 M1 < M2"]},"topics":["islm-policy"]},{"num":36,"type":"mc","question":"A movement along an aggregate demand curve corresponds to a change in income in the IS–LM model ______, while a shift in an aggregate demand curve corresponds to a change in income in the IS–LM model ______.","options":["resulting from a change in monetary policy; resulting from a change in fiscal policy","resulting from a change in fiscal policy; resulting from a change in monetary policy","at a given price level; resulting from a change in the price level","resulting from a change in the price level; at a given price level"],"answer":"D","images":["c12_img8.png"],"translation":{"question":"沿总需求曲线的移动对应于 IS–LM 模型中 ______ 引起的收入变化，而总需求曲线的移动对应于 IS–LM 模型中 ______ 引起的收入变化。","options":["货币政策变化；财政政策变化","财政政策变化；货币政策变化","给定价格水平下；价格水平变化","价格水平变化；给定价格水平下"]},"topics":["islm-policy"]},{"num":37,"type":"mc","question":"Starting from a short-run equilibrium greater than the natural rate of output, as the economy returns to a long-run equilibrium:","options":["both output and the price level will increase.","output will decrease, but the price level will increase.","output will increase, but the price level will decrease.","both output and the price level will decrease."],"answer":"B","images":null,"translation":{"question":"从高于自然产出率的短期均衡出发，当经济回到长期均衡时：","options":["产出和价格水平都将上升。","产出将下降，但价格水平将上升。","产出将上升，但价格水平将下降。","产出和价格水平都将下降。"]},"topics":["islm-policy"]},{"num":38,"type":"mc","question":"If the short-run IS–LM equilibrium occurs at a level of income below the natural level of output, then in the long run the price level will ______, shifting the ______ curve to the right and returning output to the natural level.","options":["increase; IS","decrease; IS","increase; LM","decrease; LM"],"answer":"D","images":null,"translation":{"question":"如果短期 IS–LM 均衡发生在低于自然产出水平的收入水平上，那么长期中价格水平将 ______，使 ______ 曲线向右移动，并使产出回到自然水平。","options":["上升；IS","下降；IS","上升；LM","下降；LM"]},"topics":["islm-policy"]},{"num":39,"type":"mc","question":"Exhibit: Short Run to Long Run Based on the graph, if the economy starts from a short-term equilibrium at A, then the long-run equilibrium will be at ____, with a _____ price level.","options":["B; higher","B; lower","C; higher","C; lower"],"answer":"B","images":null,"translation":{"question":"图：短期到长期。根据该图，若经济从 A 点的短期均衡出发，则长期均衡将在 ______，价格水平 ______。","options":["B；更高","B；更低","C；更高","C；更低"]},"topics":["islm-policy"]},{"num":40,"type":"mc","question":"Exhibit: Short Run to Long Run Based on the graph, if the economy starts from a short-term equilibrium at D, then the long-run equilibrium will be at ____, with a _____ price level.","options":["B; higher","B; lower","C; higher","C; lower"],"answer":"C","images":["c12_img9.png"],"translation":{"question":"图：短期到长期。根据该图，若经济从 D 点的短期均衡出发，则长期均衡将在 ______，价格水平 ______。","options":["B；更高","B；更低","C；更高","C；更低"]},"topics":["islm-policy"]},{"num":41,"type":"mc","question":"Analysis of the short run and long run indicates that the ______ assumptions are most appropriate in ______.","options":["classical; both the short run and the long run","Keynesian; both the short run and the long run","classical; the short run, whereas the Keynesian assumptions are most appropriate in the long run","Keynesian; the short run, whereas the classical assumptions are most appropriate in the long run"],"answer":"D","images":["c12_img10.png"],"translation":{"question":"短期和长期分析表明，______ 假设在 ______ 最合适。","options":["古典；短期和长期","凯恩斯；短期和长期","古典；短期，而凯恩斯假设在长期最合适","凯恩斯；短期，而古典假设在长期最合适"]},"topics":["islm-policy"]},{"num":42,"type":"mc","question":"The money hypothesis suggests that the Great Depression was caused by a:","options":["leftward shift in the IS curve.","rightward shift in the IS curve.","leftward shift in the LM curve.","rightward shift in the LM curve."],"answer":"C","images":null,"translation":{"question":"货币假说认为大萧条是由以下哪项引起的：","options":["IS 曲线向左移动。","IS 曲线向右移动。","LM 曲线向左移动。","LM 曲线向右移动。"]},"topics":["great-depression"]},{"num":43,"type":"mc","question":"The Pigou effect suggests that falling prices will increase income because real balances influence ______ and will shift the ______ curve.","options":["money demand; LM","the money supply; LM","consumer spending; IS","government spending; IS"],"answer":"C","images":null,"translation":{"question":"庇古效应认为价格下跌会增加收入，因为实际余额影响 ______ 并会使 ______ 曲线移动。","options":["货币需求；LM","货币供给；LM","消费支出；IS","政府支出；IS"]},"topics":["great-depression"]},{"num":44,"type":"mc","question":"If real money balances enter the IS–LM model both through the theory of liquidity preference and the Pigou effect, then a fall in the price level will shift:","options":["only the LM curve.","only the IS curve.","both the LM and the IS curves.","neither the LM nor the IS curve."],"answer":"C","images":null,"translation":{"question":"如果实际货币余额通过流动性偏好理论和庇古效应同时进入 IS–LM 模型，那么价格水平下降将使：","options":["只有 LM 曲线移动。","只有 IS 曲线移动。","LM 和 IS 曲线都移动。","LM 和 IS 曲线都不移动。"]},"topics":["great-depression"]},{"num":45,"type":"mc","question":"The debt-deflation theory of the Great Depression suggests that an ______ deflation redistributes wealth in such a way as to ______ spending on goods and services.","options":["unexpected; reduce","unexpected; increase","expected; reduce","expected; increase"],"answer":"A","images":null,"translation":{"question":"大萧条的债务-通缩理论认为，______ 通货紧缩会以 ______ 商品和服务支出的方式重新分配财富。","options":["未预期到的；减少","未预期到的；增加","预期到的；减少","预期到的；增加"]},"topics":["great-depression"]},{"num":46,"type":"mc","question":"The debt-deflation hypothesis explains the fall in income as a consequence of unexpected deflation transferring wealth ______, and that creditors have a ______ propensity to consume than debtors.","options":["from debtors to creditors; smaller","from debtors to creditors; larger","from creditors to debtors; smaller","from creditors to debtors; larger"],"answer":"A","images":null,"translation":{"question":"债务-通缩假说将收入下降解释为未预期到的通货紧缩将财富从 ______ 转移的结果，且债权人的消费倾向比债务人 ______。","options":["债务人转移到债权人；更小","债务人转移到债权人；更大","债权人转移到债务人；更小","债权人转移到债务人；更大"]},"topics":["great-depression"]},{"num":47,"type":"mc","question":"Investment depends on the ______ interest rate, and money demand depends on the ______ interest rate.","options":["real; real","nominal; nominal","real; nominal","nominal; real"],"answer":"C","images":null,"translation":{"question":"投资取决于 ______ 利率，货币需求取决于 ______ 利率。","options":["实际；实际","名义；名义","实际；名义","名义；实际"]},"topics":["islm-policy"]},{"num":48,"type":"mc","question":"In the IS–LM model, starting with zero expected inflation, if expected inflation becomes negative, then the:","options":["IS curve shifts leftward.","IS curve shifts rightward.","LM curve shifts leftward.","LM curve shifts rightward."],"answer":"A","images":null,"translation":{"question":"在 IS–LM 模型中，从零预期通胀出发，如果预期通胀变为负，则：","options":["IS 曲线向左移动。","IS 曲线向右移动。","LM 曲线向左移动。","LM 曲线向右移动。"]},"topics":["islm-policy","great-depression"]},{"num":49,"type":"mc","question":"One explanation for the impact of expected price changes on the level of output is that an increase in expected deflation ______ the nominal interest rate and ______ the real interest rate, so that investment spending declines.","options":["lowers; raises","raises; lowers","raises; raises","lowers; lowers"],"answer":"A","images":null,"translation":{"question":"预期价格变化对产出水平影响的一种解释是，预期通缩增加会 ______ 名义利率并 ______ 实际利率，从而使投资支出下降。","options":["降低；提高","提高；降低","提高；提高","降低；降低"]},"topics":["islm-policy","great-depression"]},{"num":50,"type":"mc","question":"Other things equal, an expected deflation can change demand by:","options":["lowering the demand for money, thus shifting the LM curve.","increasing the demand for money, thus shifting the LM curve.","raising the real interest rate for any given nominal interest rate, thus reducing desired investment.","lowering the real interest rate for any given nominal interest rate, thus increasing desired investment."],"answer":"C","images":null,"translation":{"question":"其他条件不变，预期通缩可以通过以下方式改变需求：","options":["降低货币需求，从而使 LM 曲线移动。","增加货币需求，从而使 LM 曲线移动。","对于任一给定名义利率提高实际利率，从而减少合意投资。","对于任一给定名义利率降低实际利率，从而增加合意投资。"]},"topics":["islm-policy","great-depression"]},{"num":51,"type":"mc","question":"During the financial crisis of 2008–2009, many financial institutions stopped making loans even to creditworthy customers, which could be represented in the IS–LM model as a(n):","options":["expansionary shift in the IS curve.","contractionary shift in the IS curve.","expansionary shift in the LM curve.","contractionary shift in the LM curve."],"answer":"B","images":null,"translation":{"question":"在 2008–2009 年金融危机期间，许多金融机构甚至停止向有信誉的客户放贷，这在 IS–LM 模型中可表示为：","options":["IS 曲线的扩张性移动。","IS 曲线的紧缩性移动。","LM 曲线的扩张性移动。","LM 曲线的紧缩性移动。"]},"topics":["islm-policy"]},{"num":52,"type":"mc","question":"A liquidity trap occurs when:","options":["banks have too much currency and close their doors to new customers.","the central bank mistakenly prints too much money, generating hyperinflation.","interest rates fall so low that monetary policy is no longer effective.","dams and locks are built to prevent flooding."],"answer":"C","images":null,"translation":{"question":"流动性陷阱发生在：","options":["银行持有过多货币并拒绝新客户时。","央行错误地印刷过多货币、引发恶性通胀时。","利率降到极低、货币政策不再有效时。","为防止洪水而修建水坝和船闸时。"]},"topics":["islm-policy"]},{"num":53,"type":"mc","question":"The slope of the IS curve depends on:","options":["the interest sensitivity of investment and the amount of government spending.","the interest sensitivity of investment and the marginal propensity to consume.","the interest sensitivity of investment and the tax rates.","tax rates and government spending."],"answer":"B","images":null,"translation":{"question":"IS 曲线的斜率取决于：","options":["投资的利率敏感性和政府支出额。","投资的利率敏感性和边际消费倾向。","投资的利率敏感性和税率。","税率和政府支出。"]},"topics":["islm-policy"]},{"num":54,"type":"mc","question":"A given increase in taxes shifts the IS curve more to the left the:","options":["larger the marginal propensity to consume.","smaller the marginal propensity to consume.","larger the government spending.","smaller the government spending."],"answer":"A","images":null,"translation":{"question":"给定的增税使 IS 曲线向左移动得越多，当：","options":["边际消费倾向越大。","边际消费倾向越小。","政府支出越大。","政府支出越小。"]},"topics":["islm-policy"]},{"num":55,"type":"mc","question":"The LM curve is steeper the ______ the interest sensitivity of money demand and the ______ the effect of income on money demand.","options":["greater; greater","greater; smaller","smaller; smaller","smaller; greater"],"answer":"D","images":null,"translation":{"question":"货币需求的利率敏感性越 ______，收入对货币需求的影响越 ______，LM 曲线越陡。","options":["大；大","大；小","小；小","小；大"]},"topics":["islm-policy"]},{"num":56,"type":"mc","question":"If the demand function for money is M / P = 0.5Y – 100r, then the slope of the LM curve is:","options":["0.001.","0.005.","0.01.","0.05."],"answer":"B","images":null,"translation":{"question":"如果货币需求函数为 M / P = 0.5Y – 100r，则 LM 曲线的斜率为：","options":["0.001。","0.005。","0.01。","0.05。"]},"topics":["islm-policy"]},{"num":57,"type":"mc","question":"If the demand function for money is M / P = 0.2Y – 200r, and if M / P increases by 100, then the LM curve for any given interest rate shifts to the:","options":["left by 100.","left by 500.","right by 100.","right by 500."],"answer":"D","images":null,"translation":{"question":"如果货币需求函数为 M / P = 0.2Y – 200r，且 M / P 增加 100，则任一给定利率下 LM 曲线移动：","options":["向左 100。","向左 500。","向右 100。","向右 500。"]},"topics":["islm-policy"]},{"num":58,"type":"mc","question":"Other things equal, a given change in government spending has a larger effect on demand the:","options":["flatter the LM curve.","steeper the LM curve.","smaller the interest sensitivity of money demand.","larger the income sensitivity of money demand."],"answer":"A","images":null,"translation":{"question":"其他条件不变，给定的政府支出变化对需求的影响越大，当：","options":["LM 曲线越平坦。","LM 曲线越陡。","货币需求的利率敏感性越小。","货币需求的收入敏感性越大。"]},"topics":["islm-policy"]},{"num":59,"type":"mc","question":"Other things equal, a given change in government spending has a larger effect on demand the:","options":["flatter the IS curve.","steeper the IS curve.","larger the interest sensitivity of expenditure demand.","smaller the interest sensitivity of money demand."],"answer":"B","images":null,"translation":{"question":"其他条件不变，给定的政府支出变化对需求的影响越大，当：","options":["IS 曲线越平坦。","IS 曲线越陡。","支出需求的利率敏感性越大。","货币需求的利率敏感性越小。"]},"topics":["islm-policy"]},{"num":60,"type":"mc","question":"If money demand does not depend on the interest rate, then the LM curve is ______, and ______ policy has no effect on output.","options":["horizontal; fiscal","vertical; fiscal","horizontal; monetary","vertical; monetary"],"answer":"B","images":null,"translation":{"question":"如果货币需求不取决于利率，则 LM 曲线是 ______ 的，______ 政策对产出没有影响。","options":["水平；财政","垂直；财政","水平；货币","垂直；货币"]},"topics":["islm-policy"]},{"num":61,"type":"mc","question":"If neither investment nor consumption depends on the interest rate, then the IS curve is ______, and ______ policy has no effect on output.","options":["vertical; monetary","horizontal; monetary","vertical; fiscal","horizontal; fiscal"],"answer":"A","images":null,"translation":{"question":"如果投资和消费都不取决于利率，则 IS 曲线是 ______ 的，______ 政策对产出没有影响。","options":["垂直；货币","水平；货币","垂直；财政","水平；财政"]},"topics":["islm-policy"]},{"num":62,"type":"mc","question":"Economists who believe that fiscal policy is more potent than monetary policy argue that the:","options":["responsiveness of investment to the interest rate is small.","responsiveness of investment to the interest rate is large.","IS curve is nearly horizontal.","LM curve is nearly vertical."],"answer":"A","images":null,"translation":{"question":"认为财政政策比货币政策更有力的经济学家主张：","options":["投资对利率的反应性很小。","投资对利率的反应性很大。","IS 曲线接近水平。","LM 曲线接近垂直。"]},"topics":["islm-policy"]},{"num":63,"type":"mc","question":"Economists who believe that monetary policy is more potent than fiscal policy argue that the:","options":["responsiveness of money demand to the interest rate is large.","responsiveness of money demand to the interest rate is small.","IS curve is nearly vertical.","LM curve is nearly horizontal."],"answer":"B","images":null,"translation":{"question":"认为货币政策比财政政策更有力的经济学家主张：","options":["货币需求对利率的反应性很大。","货币需求对利率的反应性很小。","IS 曲线接近垂直。","LM 曲线接近水平。"]},"topics":["islm-policy"]},{"num":64,"type":"mc","question":"According to the IS–LM model, when the government increases taxes and government purchases by equal amounts:","options":["income, the interest rate, consumption, and investment are unchanged.","income and the interest rate rise, whereas consumption and investment fall.","income and the interest rate fall, whereas consumption and interest rise.","income, the interest rate, consumption, and investment all rise."],"answer":"B","images":null,"translation":{"question":"根据 IS–LM 模型，当政府等量增加税收和政府购买时：","options":["收入、利率、消费和投资都不变。","收入和利率上升，而消费和投资下降。","收入和利率下降，而消费和投资上升。","收入、利率、消费和投资都上升。"]},"topics":["islm-policy"]},{"num":65,"type":"mc","question":"If consumption is given by C = 200 + 0.75(Y – T) and investment is given by I = 200 – 25r, then the formula for the IS curve is:","options":["Y = 400 – 0.75T – 25r + G.","Y = 1,600 – 3T – 100r + 4G.","Y = 400 + 0.75T – 25r – G.","Y = 1,600 + 3T – 100r – 4G."],"answer":"B","images":null,"translation":{"question":"如果消费由 C = 200 + 0.75(Y – T) 给出，投资由 I = 200 – 25r 给出，则 IS 曲线的公式为：","options":["Y = 400 – 0.75T – 25r + G。","Y = 1,600 – 3T – 100r + 4G。","Y = 400 + 0.75T – 25r – G。","Y = 1,600 + 3T – 100r – 4G。"]},"topics":["islm-policy"]},{"num":66,"type":"mc","question":"If the IS curve is given by Y = 1,700 – 100r and the LM curve is given by Y = 500 + 100r, then equilibrium income and interest rate are given by:","options":["Y = 1,100, r = 6 percent.","Y = 1,200, r = 5 percent.","Y = 1,000, r = 5 percent.","Y = 1,100, r = 5 percent."],"answer":"A","images":null,"translation":{"question":"如果 IS 曲线由 Y = 1,700 – 100r 给出，LM 曲线由 Y = 500 + 100r 给出，则均衡收入和利率为：","options":["Y = 1,100，r = 6%。","Y = 1,200，r = 5%。","Y = 1,000，r = 5%。","Y = 1,100，r = 5%。"]},"topics":["islm-policy"]},{"num":67,"type":"mc","question":"If the IS curve is given by Y = 1,700 – 100r, the money demand function is given by (M/P)d = Y – 100r, the money supply is 1,000, and the price level is 2, then if the money supply is raised to 1,200, equilibrium income rises by:","options":["200 and the interest rate falls by 2 percent.","100 and the interest rate falls by 1 percent.","50 and the interest rate falls by 0.5 percent.","200 and the interest rate remains unchanged."],"answer":"C","images":null,"translation":{"question":"如果 IS 曲线由 Y = 1,700 – 100r 给出，货币需求函数由 (M/P)d = Y – 100r 给出，货币供给为 1,000，价格水平为 2，那么当货币供给提高到 1,200 时，均衡收入增加：","options":["200，且利率下降 2 个百分点。","100，且利率下降 1 个百分点。","50，且利率下降 0.5 个百分点。","200，且利率保持不变。"]},"topics":["islm-policy"]},{"num":68,"type":"mc","question":"An increase in the money supply:","options":["increases income and lowers the interest rate in both the short run and in the long run.","increases income in both the short run and in the long run but leaves the interest rate unchanged in the long run.","lowers the interest rate in both the short run and in the long run but leaves income unchanged in the long run.","lowers the interest rate and increases income in the short run but leaves both unchanged in the long run."],"answer":"D","images":null,"translation":{"question":"货币供给增加：","options":["在短期和长期都提高收入并降低利率。","在短期和长期都提高收入，但在长期利率保持不变。","在短期和长期都降低利率，但在长期收入保持不变。","在短期降低利率并提高收入，但在长期两者都不变。"]},"topics":["islm-policy"]},{"num":69,"type":"mc","question":"An increase in government spending raises income:","options":["and the interest rate in the short run but leaves both unchanged in the long run.","in the short run but leaves it unchanged in the long run, while lowering investment.","in the short run but leaves it unchanged in the long run, while lowering consumption.","and the interest rate in both the short run and in the long run."],"answer":"B","images":null,"translation":{"question":"政府支出增加使收入：","options":["和利率在短期上升，但在长期两者都不变。","在短期上升，但在长期不变，同时降低投资。","在短期上升，但在长期不变，同时降低消费。","和利率在短期和长期都上升。"]},"topics":["islm-policy"]},{"num":70,"type":"mc","question":"An increase in taxes lowers income:","options":["and the interest rate in the short run but leaves both unchanged in the long run.","in the short run but leaves it unchanged in the long run, while increasing consumption and lowering investment.","in the short run but leaves it unchanged in the long run, while lowering consumption and increasing investment.","and the interest rate in both the short run and in the long run."],"answer":"C","images":null,"translation":{"question":"增税使收入：","options":["和利率在短期下降，但在长期两者都不变。","在短期下降，但在长期不变，同时增加消费并降低投资。","在短期下降，但在长期不变，同时降低消费并增加投资。","和利率在短期和长期都下降。"]},"topics":["islm-policy"]},{"num":71,"type":"sa","question":"Assume the following model of the economy, with the price level fixed at 1.0: C = 0.8(Y – T) T = 1,000 I = 800 – 20r G = 1,000 Y = C + I + G Ms / P = Md / P = 0.4Y – 40r Ms = 1,200 a. Write a formula for the IS curve, showing Y as a function of r alone. (Hint: Substitute out C, I, G, and T.) b. Write a formula for the LM curve, showing Y as a function of r alone. (Hint: Substitute out M / P.) c. What are the short-run equilibrium values of Y, r, Y – T, C, I, private saving, public saving, and national saving? Check by ensuring that C + I + G = Y and national saving equals I. d. Assume that G increases by 200. By how much will Y increase in short-run equilibrium? What is the government-purchases multiplier (the change in Y divided by the change in G)? e. Assume that G is back at its original level of 1,000, but Ms (the money supply) increases by 200. By how much will Y increase in short-run equilibrium? What is the multiplier for money supply (the change in Y divided by the change in Ms)?","options":null,"answer":null,"images":null,"translation":{"question":"假设如下经济模型，价格水平固定为 1.0：C = 0.8(Y – T)  T = 1,000  I = 800 – 20r  G = 1,000  Y = C + I + G  Ms / P = Md / P = 0.4Y – 40r  Ms = 1,200  a. 写出 IS 曲线的公式，将 Y 表示为仅含 r 的函数。（提示：代入消去 C、I、G 和 T。）b. 写出 LM 曲线的公式，将 Y 表示为仅含 r 的函数。（提示：代入消去 M / P。）c. Y、r、Y – T、C、I、私人储蓄、公共储蓄和国民储蓄的短期均衡值各是多少？通过验证 C + I + G = Y 且国民储蓄等于 I 来检验。d. 假设 G 增加 200。短期均衡中 Y 会增加多少？政府购买乘数（Y 的变化量除以 G 的变化量）是多少？e. 假设 G 回到原来 1,000 的水平，但 Ms（货币供给）增加 200。短期均衡中 Y 会增加多少？货币供给乘数（Y 的变化量除以 Ms 的变化量）是多少？","options":null},"topics":["islm-policy"],"answer_ref":"a. IS：Y = 0.8(Y−1000) + 800 − 20r + 1000 → 0.2Y = 1000 − 20r → Y = 5000 − 100r。b. LM：1200 = 0.4Y − 40r → Y = 3000 + 100r。c. 联立：5000 − 100r = 3000 + 100r → r = 10，Y = 4000。d. 回代：C = 0.8×3000 = 2400，I = 800 − 200 = 600，T=1000，G=1000；验证 2400+600+1000 = 4000 ✓。"},{"num":72,"type":"sa","question":"Assume that an economy is characterized by the following equations: C = 100 + (2 / 3) (Y – T) T = 600 G = 500 I = 800 – (50 / 3) r Ms / P = Md / P = 0.5Y – 50r a. Write the numerical IS curve for the economy, expressing Y as a numerical function of G, T, and r. b. Write the numerical LM curve for this economy, expressing r as a function of Y and M / P. c. Solve for the equilibrium values of Y and r, assuming P = 1.0 and M = 1,200. How do they change when P = 2.0? Check by computing C, I, and G. d. Write the numerical aggregate demand curve for this economy, expressing Y as a function of G, T, and M / P.","options":null,"answer":null,"images":null,"translation":{"question":"假设某经济由以下方程描述：C = 100 + (2 / 3)(Y – T)  T = 600  G = 500  I = 800 – (50 / 3)r  Ms / P = Md / P = 0.5Y – 50r  a. 写出该经济的数值 IS 曲线，将 Y 表示为 G、T 和 r 的数值函数。b. 写出该经济的数值 LM 曲线，将 r 表示为 Y 和 M / P 的函数。c. 假设 P = 1.0 且 M = 1,200，求解 Y 和 r 的均衡值。当 P = 2.0 时它们如何变化？通过计算 C、I 和 G 来检验。d. 写出该经济的数值总需求曲线，将 Y 表示为 G、T 和 M / P 的函数。","options":null},"topics":["islm-policy"],"answer_ref":"a. IS：Y = 100 + (2/3)(Y−600) + 800 − (50/3)r + 500 → (1/3)Y = 1000 − (50/3)r → Y = 3000 − 50r；一般形式 Y = 300 + 3G − 2T + 3I 部分展开即 Y = 3(100 + G + 800 − (50/3)r) − 2T = 3000 − 50r（代入 G=500、T=600）。b. LM：由 M/P = 0.5Y − 50r 得 r = 0.01Y − (M/P)/50。c. 均衡：令 IS=LM，代入给定 M/P 即可解出 Y 与 r（若给定 M 值，代入即得数值解）。"},{"num":73,"type":"sa","question":"Assume that an economy is described by the IS curve Y = 3,600 + 3G – 2T – 150r and the LM curve Y = 2 M / P + 100r [or r = 0.01Y – 0.02 (M / P)]. The investment function for this economy is 1,000 – 50r. The consumption function is C = 200 + (2 / 3)(Y – T). Long-run equilibrium output for this economy is 4,000. The price level is 1.0. a. Assume that government spending is fixed at 1,200. The government wants to achieve a level of investment equal to 900 and also achieve Y = 4,000. What level of r is needed for I = 900? What levels of T and M must be set to achieve the two goals? What will be the levels of private saving, public saving, and national saving? (Hint: Check C + I + G = Y.) b. Now assume that the government wants to cut taxes to 1,000. With G set at 1,200, what will the interest rate be at Y = 4,000? What must be the value of M? What will I be? What will be the levels of private, public, and national saving? (Hint: Check C + I + G = Y.) c. Which set of policies may be referred to as tight fiscal, loose money? Which set of policies may be referred to as loose fiscal, tight money? Which “policy mix” most encourages investment?","options":null,"answer":null,"images":null,"translation":{"question":"假设某经济由 IS 曲线 Y = 3,600 + 3G – 2T – 150r 和 LM 曲线 Y = 2 M / P + 100r（或 r = 0.01Y – 0.02 (M / P)）描述。该经济的投资函数为 1,000 – 50r。消费函数为 C = 200 + (2 / 3)(Y – T)。该经济的长期均衡产出为 4,000。价格水平为 1.0。a. 假设政府支出固定为 1,200。政府希望实现投资水平 900 并同时实现 Y = 4,000。要达到 I = 900 需要什么水平的 r？为实现这两个目标必须设定什么水平的 T 和 M？私人储蓄、公共储蓄和国民储蓄的水平将各是多少？（提示：检验 C + I + G = Y。）b. 现在假设政府想减税到 1,000。当 G 设为 1,200 时，Y = 4,000 时的利率将是多少？M 的值必须是多少？I 将是多少？私人储蓄、公共储蓄和国民储蓄的水平将各是多少？（提示：检验 C + I + G = Y。）c. 哪组政策可被称为紧缩财政、宽松货币？哪组政策可被称为宽松财政、紧缩货币？哪种“政策组合”最鼓励投资？","options":null},"topics":["islm-policy"],"answer_ref":"a. 思路：G 固定 1200，IS：Y = 3600 + 3600 − 2T − 150r = 7200 − 2T − 150r。政府政策变动给出 T 或 M 后，与 LM（Y = 2M/P + 100r）联立求解；长期均衡产出 4000、P=1.0 是参照基准——长期中任何使产出偏离 4000 的缺口都会通过价格调整回归。解题时先把 IS、LM 联立解出短期 r、Y，再与 Y=4000 比较判断缺口方向。"},{"num":74,"type":"sa","question":"How can the Fed keep the economy from falling into a recession if the budget deficit is reduced? Use the IS–LM model to illustrate graphically the impact of both the fiscal policy reducing the deficit and the monetary policy, which prevents output from falling. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; and v. the terminal equilibrium values.","options":null,"answer":null,"images":null,"translation":{"question":"如果预算赤字减少，美联储如何防止经济陷入衰退？用 IS–LM 模型图示减少赤字的财政政策和防止产出下降的货币政策两者的影响。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。","options":null},"topics":["islm-policy"],"answer_ref":"图：赤字削减（G↓或T↑）→IS 左移（Y 有下降趋势）；Fed 同时扩大货币供给→LM 右移。结果：两条曲线配合，新均衡与原均衡收入相同（免于衰退），但利率明显更低——货币政策对冲了财政紧缩的紧缩效应（d. 双曲线相交于原 Y、更低 r 处）。"},{"num":75,"type":"sa","question":"Use the IS–LM model to illustrate graphically the impact on output and interest rates of a one-time increase in the price level due to a large increase in oil prices. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; and v. the terminal equilibrium values.","options":null,"answer":null,"images":null,"translation":{"question":"用 IS–LM 模型图示石油价格大幅上涨导致价格水平一次性上升对产出和利率的影响。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。","options":null},"topics":["islm-policy"],"answer_ref":"图：油价大涨一次性抬高 P→实际货币余额 M/P 下降→LM 左移：均衡沿 IS 上移——r 由 r₁ 升至 r₂，Y 由 Y₁ 降至 Y₂（产出下降、利率上升）。供给冲击造成的 P 上升与需求拉动的 P 上升不同：它同时压低产出。"},{"num":76,"type":"sa","question":"Suppose that people finally realize that they must save a larger proportion of their income in order to retire and that they simultaneously begin to use new technology that allows them to reduce their holdings of real cash balances as a proportion of their income. Use the IS–LM model to illustrate graphically the impact of these two changes in household behavior on output and interest rates. Be sure to label: i. the axes; ii. the curves; iii. the initial equilibrium values; iv. the direction the curves shift; and v. the terminal equilibrium values.","options":null,"answer":null,"images":null,"translation":{"question":"假设人们最终意识到必须储蓄更大比例的收入以备退休，同时他们开始使用新技术，从而能够降低所持有的实际现金余额占收入的比例。用 IS–LM 模型图示这两项家庭行为变化对产出和利率的影响。务必标注：i. 坐标轴；ii. 曲线；iii. 初始均衡值；iv. 曲线移动的方向；v. 最终均衡值。","options":null},"topics":["islm-policy"],"answer_ref":"两股力量：①储蓄倾向上升→消费函数下移→IS 左移（压低 Y、压低 r）；②货币需求减少→LM 右移（抬高 Y、压低 r）。综合：利率 r 确定无疑地下降；对产出的影响不确定——取决于 IS 与 LM 移动的相对幅度。"},{"num":77,"type":"sa","question":"Use the IS–LM model to illustrate graphically the impact of the Pigou effect on the equilibrium level of income and interest rate during the Great Depression, when prices were falling.","options":null,"answer":null,"images":null,"translation":{"question":"用 IS–LM 模型图示大萧条期间（当价格下跌时）庇古效应对均衡收入和利率水平的影响。","options":null},"topics":["great-depression"],"answer_ref":"图（大萧条，P 持续下降）：P↓→实际余额 M/P↑。庇古效应：财富增加→消费↑→IS 右移；同时 M/P↑→LM 右移。两曲线右移使均衡收入回升、利率下降——即使名义利率已很低，物价下跌通过实际余额仍能刺激经济走向充分就业。"},{"num":78,"type":"sa","question":"Assume that initially everyone expects the price level to stay the same. Now the Federal Reserve announces that it will increase the rate of money growth in one year. People now expect inflation. Use the IS–LM model to illustrate graphically the impact of expected inflation on the level of output and on the real and nominal interest rates.","options":null,"answer":null,"images":null,"translation":{"question":"假设最初每个人都预期价格水平保持不变。现在美联储宣布将在一年后提高货币增长率。人们现在预期通胀。用 IS–LM 模型图示预期通胀对产出水平以及实际利率和名义利率的影响。","options":null},"topics":["islm-policy"],"answer_ref":"图：预期通胀↑→名义利率 i = r + π^e 中，在货币需求函数里起作用的 i 上升→货币需求↑→LM 左移；但投资取决于实际利率 r = i − π^e，给定 i 下 r↓→I↑→IS 右移。结果：名义利率上升，实际利率下降，产出基本不变或略升。预期通胀把实际利率与名义利率劈开，政策效应随预期改变。"},{"num":79,"type":"sa","question":"Assume that the economy is initially in short-run equilibrium at a level of output above the natural rate. Use the IS–LM model to illustrate graphically how the levels of income and interest rates change as the economy returns to the natural rate of output in the long run.","options":null,"answer":null,"images":null,"translation":{"question":"假设经济最初处于高于自然率的产出水平的短期均衡。用 IS–LM 模型图示经济在长期回到自然产出率时收入和利率水平如何变化。","options":null},"topics":["islm-policy"],"answer_ref":"图：短期均衡在自然率之上（Y₁>Y*）→物价上涨→M/P 下降→LM 左移：沿 IS 移动，r 由 r₁ 升至 r₂，Y 降回 Y*。长期均衡：产出回到自然率，利率更高、价格更高——IS-LM 框架中经济靠价格调整自我回归。"},{"num":80,"type":"sa","question":"Two identical countries, Alpha and Beta, can be described by the IS–LM model in the short run. The governments of both countries cut taxes by the same amount. The Central Bank of Alpha follows a policy of holding a constant money supply. The Central Bank of Beta follows a policy of holding a constant interest rate. Compare the impact of the tax cut on income and interest rates in the two countries.","options":null,"answer":null,"images":null,"translation":{"question":"两个相同的国家 Alpha 和 Beta 可以用短期 IS–LM 模型描述。两国政府等量减税。Alpha 中央银行采取保持货币供给不变的政策。Beta 中央银行采取保持利率不变的政策。比较减税对两国收入和利率的影响。","options":null},"topics":["islm-policy"],"answer_ref":"Alpha（货币量不变）：减税→IS 右移→Y↑、r↑，投资被部分挤出。Beta（利率钉住）：LM 保持水平，货币供给随需求调整——无挤出，Y 增幅更大（等于简单乘数效果），r 不变。两国收入都上升，Beta 升得更多、利率不变；Alpha 利率上升更多。"},{"num":81,"type":"sa","question":"Policymakers are contemplating undertaking either an increase in government spending or an increase in the money supply. Either policy is forecast to have the same impact on income in the short run. Use the IS–LM model to compare the impact on consumption and investment of the two policy alternatives.","options":null,"answer":null,"images":null,"translation":{"question":"政策制定者正在考虑要么增加政府支出、要么增加货币供给。预测两种政策对短期收入有相同的影响。用 IS–LM 模型比较两种政策方案对消费和投资的影响。","options":null},"topics":["islm-policy"],"answer_ref":"G↑（IS 右移）：Y↑、C↑，但 r↑→I↓（挤出）。M↑（LM 右移）：Y↑、C↑，且 r↓→I↑。两者同幅增加收入时：财政政策使消费增加但投资减少；货币政策使消费和投资同时增加。对总需求的结构影响不同——这也是政策搭配的重要依据。"},{"num":82,"type":"sa","question":"A decrease in government spending reduces output more in the Keynesian-cross model than in the IS–LM model. Explain why this is true.","options":null,"answer":null,"images":null,"translation":{"question":"政府支出减少在凯恩斯交叉模型中对产出的降低作用大于在 IS–LM 模型中。解释为什么这是正确的。","options":null},"topics":["islm-policy"],"answer_ref":"凯恩斯交叉假设利率与投资固定，G↓ 的紧缩通过乘数完全传导（乘数 1/(1−MPC)）。IS-LM 中收入下降→货币需求↓→r↓→I↑，部分抵消了支出的下降——收入反馈到货币市场再传回商品市场，形成稳定回路，故产出降幅更小。IS-LM 在简单乘数之上加了一层利率缓冲。"},{"num":83,"type":"sa","question":"Compare the impact of a tax cut on consumption, investment, output, and interest rates in the classical model of Chapter 3 versus the IS–LM model.","options":null,"answer":null,"images":null,"translation":{"question":"比较减税在第三章的古典模型与 IS–LM 模型中对消费、投资、产出和利率的影响。","options":null},"topics":["islm-policy"],"answer_ref":"古典模型（第3章）：产出固定于自然率，减税↑C、↓S→r↑→I 等量下降（完全挤出）：C↑、I↓、Y 不变、r↑。IS-LM：价格短期粘性，减税→IS 右移→Y↑、C↑、r↑，I 部分被挤出。差异：古典中产出不变、完全挤出；IS-LM 中产出上升、部分挤出。"},{"num":84,"type":"sa","question":"An increase in money supply shifts the LM curve to the right, but an increase in money demand shifts the LM curve to the left. Explain why there is a difference.","options":null,"answer":null,"images":null,"translation":{"question":"货币供给增加使 LM 曲线向右移动，但货币需求增加使 LM 曲线向左移动。解释为什么会有区别。","options":null},"topics":["islm-policy"],"answer_ref":"M↑→在每一 Y 上，需要更低的 r 使货币需求增加到与新供给相等→LM 右移。货币需求↑→在每一 Y 上，需要更高的 r（或更低的 Y）把需求压回到固定供给→LM 左移。供给增加使\"同样的 Y 配更低的 r\"，需求增加则相反——方向相反所以移动方向相反。"},{"num":85,"type":"sa","question":"Assume that the economy is initially in a short-run equilibrium at a level of output below the natural rate. a. Use the IS–LM model to graphically illustrate (1) how the economy will adjust in the long-run if the no policy action is taken and (2) the long-run equilibrium if fiscal policy is used to return the economy to the natural rate of output. b. Explain how investment, the interest rate, and the price level differ in the new long-run equilibrium in the two cases.","options":null,"answer":null,"images":null,"translation":{"question":"假设经济最初处于低于自然率的产出水平的短期均衡。a. 用 IS–LM 模型图示（1）若不采取政策行动经济在长期将如何调整，以及（2）若用财政政策使经济回到自然产出率的长期均衡。b. 解释在两种情况下，新的长期均衡中投资、利率和价格水平有何不同。","options":null},"topics":["islm-policy"],"answer_ref":"a. (1) 无政策：Y<自然率→P↓→M/P↑→LM 右移→产出回到自然率，利率降到 r₂。(2) 财政扩张：IS 右移直接恢复产出，利率升到 r₂′。b. 无政策路径：r 更低→I 更高；财政路径：r 更高→I 更低（挤出）。长期看，靠价格自我修正的国家投资水平更高；选择财政政策的国家以更低的私人投资为代价换取更快复苏。"},{"num":86,"type":"sa","question":"If inflation is bad, why isn't deflation good? Use the IS–LM model to explain how deflation could result in a contraction in output.","options":null,"answer":null,"images":null,"translation":{"question":"如果通胀是坏事，为什么通缩不是好事？用 IS–LM 模型解释通缩如何导致产出收缩。","options":null},"topics":["great-depression"],"answer_ref":"通缩看似物价便宜，实则有害：①预期通缩使实际利率 r = i − π^e 上升（名义利率零下限下更是如此）→投资崩溃→IS 左移；②债务-通缩：物价下跌加重实际债务负担，企业与家庭破产、支出萎缩。IS-LM 中：LM 右移（M/P↑）的扩张效应敌不过 IS 左移的收缩效应→产出收缩。通缩是比温和通胀更危险的状态。"},{"num":87,"type":"sa","question":"The LM curve can shift to the right if there is an increase in the supply of money or a fall in the price level. In which case is this movement along the aggregate demand curve, and in which case is this a shift of the aggregate demand curve? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"货币供给增加或价格水平下降都能使 LM 曲线向右移动。哪种情况是沿总需求曲线的移动，哪种情况是总需求曲线的移动？解释。","options":null},"topics":["islm-policy"],"answer_ref":"P 下降→M/P↑→LM 右移：沿 AD 曲线移动（P 是纵轴变量，属量内变化）。M↑→LM 右移：在每一价格水平下都有更多产出→AD 曲线整体右移（外生变量变化）。判别标准：引起 LM 移动的因素若本身就是 AD 坐标轴上的变量（P），则是沿 AD 移动；否则是 AD 平移。"},{"num":88,"type":"sa","question":"What are shocks? How do shocks respond to the IS and LM curves?","options":null,"answer":null,"images":null,"translation":{"question":"什么是冲击？冲击如何作用于 IS 曲线和 LM 曲线？","options":null},"topics":["islm-policy"],"answer_ref":"冲击是使均衡偏离的外生事件。对 IS 的冲击（消费、投资、政府购买、净出口的变化——如信心、财富、财政政策）使 IS 曲线移动；对货币需求的冲击（金融创新、支付习惯）使 LM 曲线移动。总需求冲击经 IS 或 LM 传导：IS 冲击沿 LM 改变 r 与 Y；LM 冲击沿 IS 改变 r 与 Y。"},{"num":89,"type":"sa","question":"When an economy expands its monetary and fiscal policies, how is the aggregate demand curve affected?","options":null,"answer":null,"images":null,"translation":{"question":"当经济扩张其货币政策和财政政策时，总需求曲线如何受到影响？","options":null},"topics":["islm-policy"],"answer_ref":"货币扩张→LM 右移→每一价格水平下 Y 增加→AD 右移。财政扩张（G↑或T↓）→IS 右移→同样使 AD 右移。双扩张并用时 AD 大幅右移——在短期抬升产出，长期只抬升价格（货币中性）。"},{"num":90,"type":"sa","question":"What are the spending hypothesis and monetary hypothesis? Illustrate your answer with examples.","options":null,"answer":null,"images":null,"translation":{"question":"什么是支出假说和货币假说？举例说明你的答案。","options":null},"topics":["great-depression"],"answer_ref":"支出假说：大萧条源于 IS 左移——1929 年股灾摧毁财富、消费与投资信心崩溃、银行倒闭使投资骤降（Temin 等）。货币假说：大萧条源于 LM 左移——美联储允许货币供给在 1930–33 年萎缩约三分之一（Friedman-Schwartz），通缩推高实际利率。两假说都画出向左移动的总需求，区别在初始冲击来自商品市场还是货币市场。"},{"num":91,"type":"sa","question":"To stabilize falling prices in 1930, what did Pigou suggest?","options":null,"answer":null,"images":null,"translation":{"question":"为稳定 1930 年下跌的物价，庇古提出了什么建议？","options":null},"topics":["great-depression"],"answer_ref":"庇古（Pigou）主张依靠实际余额效应：让工资与物价下降。物价下跌→公众持有的实际货币余额 M/P 增加→财富感上升→消费增加（IS 右移），经济即使在低利率下也能恢复充分就业——无需财政扩张。"},{"num":92,"type":"sa","question":"Under what condition does a liquidity trap occur?","options":null,"answer":null,"images":null,"translation":{"question":"在什么条件下会发生流动性陷阱？","options":null},"topics":["islm-policy"],"answer_ref":"流动性陷阱发生在利率极低（接近零）时：货币需求对利率无限敏感，LM 呈水平——人们预期利率只能上升（债券价格只能跌），愿意持有任何新增的货币（货币需求弹性无穷大）。此时央行增发的货币全部被货币需求吸收，利率降无可降，货币政策失效，只能靠财政政策。"}]},{"num":14,"title":"Aggregate Supply","questions":[{"num":1,"type":"mc","question":"The basic aggregate supply equation implies that output exceeds natural output when the price level is:","options":["low.","high.","less than the expected price level.","greater than the expected price level."],"answer":"D","images":null,"translation":{"question":"基本总供给方程意味着，当价格水平 ______ 时，产出超过自然产出。","options":["低。","高。","低于预期价格水平。","高于预期价格水平。"]},"topics":["expectations-as"]},{"num":2,"type":"mc","question":"Some firms do not instantly adjust the prices they charge in response to changes in demand for all of the following reasons except:","options":["it is costly to alter prices.","they do not want to annoy their frequent customers.","prices do not adjust when there is perfect competition.","some prices are set by long-term contracts between firms and customers."],"answer":"C","images":null,"translation":{"question":"有些企业不会立即调整其收费价格以应对需求变化，以下都是原因，除了：","options":["改变价格成本很高。","他们不想惹恼常客。","在完全竞争下价格不会调整。","一些价格由企业与客户之间的长期合同设定。"]},"topics":["expectations-as"]},{"num":3,"type":"mc","question":"According to the sticky-price model:","options":["all firms announce their prices in advance.","all firms set their prices in accord with observed prices and output.","some firms set their prices according to the aggregate supply equation.","some firms announce their prices in advance, and some firms set their prices in accord with observed prices and output."],"answer":"D","images":null,"translation":{"question":"根据粘性价格模型：","options":["所有企业都提前宣布其价格。","所有企业都根据观察到的价格和产出来设定其价格。","一些企业根据总供给方程来设定其价格。","一些企业提前宣布其价格，另一些企业根据观察到的价格和产出来设定其价格。"]},"topics":["expectations-as"]},{"num":4,"type":"mc","question":"According to the sticky-price model, other things being equal, the greater the proportion s of firms that follow the sticky-price rule, the ______ the ______ in output in response to an unexpected price increase.","options":["greater; increase","smaller; increase","greater; decrease","smaller; decrease"],"answer":"A","images":null,"translation":{"question":"根据粘性价格模型，其他条件不变，遵循粘性价格规则的企业比例 s 越大，则对未预期到的价格上涨，产出 ______ 越 ______。","options":["越大；增加","越小；增加","越大；减少","越小；减少"]},"topics":["expectations-as"]},{"num":5,"type":"mc","question":"Each of the two models of short-run aggregate supply is based on some market imperfection. In the sticky-price model, the imperfection is that:","options":["some firms do not adjust their prices instantly to changes in demand.","expectations are formed adaptively rather than rationally.","firms confuse changes in the overall level of prices with changes in relative prices.","the real wage adjusts to bring labor supply and labor demand into equilibrium."],"answer":"A","images":null,"translation":{"question":"两种短期总供给模型都基于某种市场不完善。在粘性价格模型中，不完善之处是：","options":["一些企业不立即调整其价格以应对需求变化。","预期是适应性而非理性形成的。","企业混淆了价格总体水平的变化与相对价格的变化。","实际工资调整使劳动供给和劳动需求达到均衡。"]},"topics":["expectations-as"]},{"num":6,"type":"mc","question":"Based on the sticky-price model, the short-run aggregate supply curve will be steeper the greater the:","options":["target nominal-wage rate.","target real-wage rate.","proportion of firms with flexible prices.","proportion of firms with sticky prices."],"answer":"C","images":null,"translation":{"question":"基于粘性价格模型，短期总供给曲线越陡，当以下哪项越大时：","options":["目标名义工资率。","目标实际工资率。","弹性价格企业的比例。","粘性价格企业的比例。"]},"topics":["expectations-as"]},{"num":7,"type":"mc","question":"According to the sticky-price model, output will be at the natural level if:","options":["firms expect a high price level and the demand for goods is high.","the proportion of firms with flexible prices equals the proportion of firms with sticky prices.","the price level equals the expected price level.","expectations are formed adaptively, but not if expectations are formed rationally."],"answer":"C","images":null,"translation":{"question":"根据粘性价格模型，产出将处于自然水平，如果：","options":["企业预期高价格水平且商品需求高。","弹性价格企业的比例等于粘性价格企业的比例。","价格水平等于预期价格水平。","预期是适应性形成的，而理性形成预期时则不然。"]},"topics":["expectations-as"]},{"num":8,"type":"mc","question":"According to the sticky-price model, deviations of output from the natural level are _____ deviations of the price level from the expected price level.","options":["positively associated with","negatively associated with","not related to","equal to"],"answer":"A","images":null,"translation":{"question":"根据粘性价格模型，产出偏离自然水平的程度与价格水平偏离预期价格水平的程度 ______。","options":["正相关","负相关","不相关","相等"]},"topics":["expectations-as"]},{"num":9,"type":"mc","question":"The imperfect-information model assumes that producers find it difficult to distinguish between changes in:","options":["real wages and nominal wages.","the overall level of prices and relative prices.","the overall level of prices and the expected level of prices.","cost-push inflation and demand-pull inflation."],"answer":"B","images":null,"translation":{"question":"不完全信息模型假设生产者难以区分以下哪项的变化：","options":["实际工资与名义工资。","价格总体水平与相对价格。","价格总体水平与预期价格水平。","成本推动型通胀与需求拉动型通胀。"]},"topics":["expectations-as"]},{"num":10,"type":"mc","question":"According to the imperfect-information model, when the price level rises by the amount the producer expected it to rise, the producer:","options":["increases production.","does not change production.","decreases production.","hires more workers."],"answer":"B","images":null,"translation":{"question":"根据不完全信息模型，当价格水平按生产者预期的幅度上升时，生产者：","options":["增加生产。","不改变生产。","减少生产。","雇用更多工人。"]},"topics":["expectations-as"]},{"num":11,"type":"mc","question":"According to the imperfect-information model, when the price level falls but the producer did not expect it to fall, the producer:","options":["increases production.","does not change production.","decreases production.","hires more workers."],"answer":"C","images":null,"translation":{"question":"根据不完全信息模型，当价格水平下降但生产者未预期到下降时，生产者：","options":["增加生产。","不改变生产。","减少生产。","雇用更多工人。"]},"topics":["expectations-as"]},{"num":12,"type":"mc","question":"After examining international data, the economist Robert Lucas found that aggregate demand has the biggest effect on output in countries where aggregate demand:","options":["and prices are most stable.","and prices are most variable.","is most stable but prices are most variable.","is most variable but prices are most stable."],"answer":"A","images":null,"translation":{"question":"在考察了国际数据之后，经济学家罗伯特·卢卡斯发现，总需求对产出影响最大的国家，是那些总需求：","options":["和价格都最稳定的国家。","和价格都最波动的国家。","最稳定但价格最波动的国家。","最波动但价格最稳定的国家。"]},"topics":["expectations-as"]},{"num":13,"type":"mc","question":"According to the imperfect-information model, in countries in which there is a great deal of variability of prices:","options":["the response of output to unexpected changes in prices will be relatively large.","the response of output to unexpected changes in prices will be relatively small.","output will respond negatively to an unexpected rise in prices.","output will not respond to an unexpected change in prices."],"answer":"B","images":null,"translation":{"question":"根据不完全信息模型，在价格存在大量波动的国家中：","options":["产出对未预期到的价格变化的反应将相对较大。","产出对未预期到的价格变化的反应将相对较小。","产出将对未预期到的价格上涨做出负向反应。","产出将不对未预期到的价格变化做出反应。"]},"topics":["expectations-as"]},{"num":14,"type":"mc","question":"In the context of the sticky-price model, the higher the average rate of inflation, the more frequently firms must adjust their prices, which implies that a high rate of inflation:","options":["has no effect on the slope of the short-run aggregate supply curve.","should make the short-run aggregate supply curve flatter.","makes the short-run aggregate supply curve steeper.","causes prices to be sticky."],"answer":"C","images":null,"translation":{"question":"在粘性价格模型的背景下，平均通胀率越高，企业必须越频繁地调整其价格，这意味着高通胀率：","options":["对短期总供给曲线的斜率没有影响。","应使短期总供给曲线更平坦。","使短期总供给曲线更陡。","导致价格粘性。"]},"topics":["expectations-as"]},{"num":15,"type":"mc","question":"The short-run aggregate supply curve is drawn for a given:","options":["output level.","price level.","expected price level.","level of aggregate demand."],"answer":"C","images":null,"translation":{"question":"短期总供给曲线是针对给定的 ______ 绘制的：","options":["产出水平。","价格水平。","预期价格水平。","总需求水平。"]},"topics":["expectations-as"]},{"num":16,"type":"mc","question":"Both models of aggregate supply discussed in Chapter 14 imply that if the price level is higher than expected, then output ______ natural rate of output.","options":["exceeds the","falls below the","equals the","moves to a different"],"answer":"A","images":null,"translation":{"question":"第 14 章讨论的两种总供给模型都意味着，如果价格水平高于预期，则产出 ______ 自然产出率。","options":["超过","低于","等于","移至不同的"]},"topics":["expectations-as"]},{"num":17,"type":"mc","question":"Starting from the natural level of output, an unexpected monetary contraction will cause output and the price level to ______ in the short run; and in the long run the expected price level will ______, causing the level of output to return to the natural level.","options":["increase; increase","increase; decrease","decrease; decrease","decrease; increase"],"answer":"C","images":null,"translation":{"question":"从自然产出水平出发，未预期到的货币紧缩将使产出和价格水平在短期 ______；在长期，预期价格水平将 ______，使产出水平回到自然水平。","options":["上升；上升","上升；下降","下降；下降","下降；上升"]},"topics":["expectations-as"]},{"num":18,"type":"mc","question":"The model of aggregate demand and aggregate supply is consistent with short-run monetary ______ and long-run monetary ______.","options":["neutrality; neutrality","nonneutrality; nonneutrality","neutrality; nonneutrality","nonneutrality; neutrality"],"answer":"D","images":null,"translation":{"question":"总需求与总供给模型与短期货币 ______ 和长期货币 ______ 一致。","options":["中性；中性","非中性；非中性","中性；非中性","非中性；中性"]},"topics":["expectations-as"]},{"num":19,"type":"mc","question":"Along an aggregate supply curve, if the level of output is less than the natural level of output, then the price level is:","options":["greater than the expected price level.","less than the expected price level.","equal to the natural price level.","stuck at the existing price level."],"answer":"B","images":null,"translation":{"question":"沿总供给曲线，如果产出水平低于自然产出水平，则价格水平：","options":["高于预期价格水平。","低于预期价格水平。","等于自然价格水平。","卡在现有价格水平上。"]},"topics":["expectations-as"]},{"num":20,"type":"mc","question":"Which of the following will shift the aggregate supply curve up to the left?","options":["an increase in the price level","a decrease in the level of output","an increase in the expected price level","a decrease in the price level"],"answer":"C","images":null,"translation":{"question":"以下哪项将使总供给曲线向左上方移动？","options":["价格水平上升。","产出水平下降。","预期价格水平上升。","价格水平下降。"]},"topics":["expectations-as"]},{"num":21,"type":"mc","question":"In the short run, if the price level is greater than the expected price level, then in the long run the aggregate:","options":["demand curve will shift leftward.","demand curve will shift rightward.","supply curve will shift upward.","supply curve will shift downward."],"answer":"C","images":null,"translation":{"question":"在短期，如果价格水平高于预期价格水平，则在长期总：","options":["需求曲线将向左移动。","需求曲线将向右移动。","供给曲线将向上移动。","供给曲线将向下移动。"]},"topics":["expectations-as"]},{"num":22,"type":"mc","question":"Exhibit: AD–AS Shifts Starting from long-run equilibrium at A with output equal to and the price level equal to P1, if there is an unexpected monetary contraction that shifts aggregate demand from AD1 to AD3, then the short-run nonneutrality of money is represented by the movement from:","options":["A to B","A to G","A to C","A to D"],"answer":"B","images":null,"translation":{"question":"图：AD–AS 移动。从 A 点的长期均衡出发（产出等于自然水平、价格水平等于 P1），若发生未预期到的货币紧缩，使总需求从 AD1 移至 AD3，则货币的短期非中性由从 ______ 的移动表示：","options":["A 到 B","A 到 G","A 到 C","A 到 D"]},"topics":["expectations-as"]},{"num":23,"type":"mc","question":"Exhibit: AD–AS Shifts Starting from long-run equilibrium at A with output equal to and the price level equal to P1, if there is an unexpected monetary contraction that shifts aggregate demand from AD1 to AD3, then the long-run neutrality of money is represented by the movement from:","options":["A to B","A to G","A to C","A to D"],"answer":"A","images":["c14_img0.png"],"translation":{"question":"图：AD–AS 移动。从 A 点的长期均衡出发（产出等于自然水平、价格水平等于 P1），若发生未预期到的货币紧缩，使总需求从 AD1 移至 AD3，则货币的长期中性由从 ______ 的移动表示：","options":["A 到 B","A 到 G","A 到 C","A 到 D"]},"topics":["expectations-as"]},{"num":24,"type":"mc","question":"The Phillips curve shows a ______ relationship between inflation and unemployment, and the short-run aggregate supply curve shows a ______ relationship between the price level and output.","options":["positive; positive","positive; negative","negative; negative","negative; positive"],"answer":"D","images":["c14_img1.png"],"translation":{"question":"菲利普斯曲线显示通胀与失业之间存在 ______ 关系，短期总供给曲线显示价格水平与产出之间存在 ______ 关系。","options":["正；正","正；负","负；负","负；正"]},"topics":["phillips-curve"]},{"num":25,"type":"mc","question":"According to the Phillips curve, other things being equal, inflation depends positively on:","options":["expected inflation.","the unemployment rate.","the rate of technological change.","the quantities of capital and labor."],"answer":"A","images":null,"translation":{"question":"根据菲利普斯曲线，其他条件不变，通胀正向取决于：","options":["预期通胀。","失业率。","技术变化率。","资本和劳动的数量。"]},"topics":["phillips-curve"]},{"num":26,"type":"mc","question":"If the short-run aggregate supply curve is steep, the Phillips curve will be:","options":["flat.","steep.","backward bending.","unrelated to the slope of the short-run aggregate supply curve."],"answer":"B","images":null,"translation":{"question":"如果短期总供给曲线很陡，则菲利普斯曲线将：","options":["平坦。","陡峭。","向后弯曲。","与短期总供给曲线的斜率无关。"]},"topics":["phillips-curve"]},{"num":27,"type":"mc","question":"Along a short-run aggregate supply curve, output is related to unexpected movements in the ______. Along a Phillips curve, unemployment is related to unexpected movements in the ______.","options":["price level; inflation rate","inflation rate; price level","unemployment rate; price level","price level; level of output"],"answer":"A","images":null,"translation":{"question":"沿短期总供给曲线，产出与 ______ 的未预期变动相关。沿菲利普斯曲线，失业与 ______ 的未预期变动相关。","options":["价格水平；通胀率","通胀率；价格水平","失业率；价格水平","价格水平；产出水平"]},"topics":["phillips-curve"]},{"num":28,"type":"mc","question":"All of the following are ways that the modern Phillips curve differs from the relationship observed by A. W. Phillips in 1958 except that the modern Phillips curve:","options":["substitutes the output gap for unemployment.","includes supply shocks.","includes expected inflation.","substitutes price inflation for wage inflation."],"answer":"A","images":null,"translation":{"question":"以下都是现代菲利普斯曲线与 A. W. 菲利普斯 1958 年观察到的关系不同之处，除了现代菲利普斯曲线：","options":["用产出缺口替代失业。","包含供给冲击。","包含预期通胀。","用价格通胀替代工资通胀。"]},"topics":["phillips-curve"]},{"num":29,"type":"mc","question":"The NAIRU is the:","options":["North American institutional rate of unemployment.","natural aggregate investment return on utilization.","nonaccelerating inflation rate of unemployment.","normal American inelastic rate of unemployment."],"answer":"C","images":null,"translation":{"question":"NAIRU 是：","options":["北美制度性失业率。","利用率的自然总投资回报。","非加速通胀失业率。","正常的美国非弹性失业率。"]},"topics":["phillips-curve"]},{"num":30,"type":"mc","question":"If the equation for a country's Phillips curve is p = 0.02 – 0.8(u – 0.05), where p is the rate of inflation and u is the unemployment rate, what is the short-run inflation rate when unemployment is 4 percent (0.04)?","options":["above 2 percent (0.02)","below 2 percent (0.02)","2 percent (0.02)","–2 percent (–0.02)"],"answer":"A","images":null,"translation":{"question":"如果一国的菲利普斯曲线方程为 p = 0.02 – 0.8(u – 0.05)，其中 p 为通胀率、u 为失业率，那么当失业率为 4%（0.04）时，短期通胀率是多少？","options":["高于 2%（0.02）。","低于 2%（0.02）。","2%（0.02）。","–2%（–0.02）。"]},"topics":["phillips-curve"]},{"num":31,"type":"mc","question":"The assumption of adaptive expectations for inflation means that people will form their expectations of inflation by:","options":["taking all information into account using the best economic model available.","asking the opinions of experts.","basing their opinions on recently observed inflation.","flipping a coin."],"answer":"C","images":null,"translation":{"question":"对通胀的适应性预期假设意味着，人们将通过 ______ 来形成其通胀预期：","options":["使用可得的最佳经济模型考虑所有信息。","询问专家的意见。","基于最近观察到的通胀。","掷硬币。"]},"topics":["expectations-as"]},{"num":32,"type":"mc","question":"Inflation inertia is represented in the aggregate supply–aggregate demand model by continuing upward shifts in the:","options":["aggregate demand curve.","short-run aggregate supply curve.","long-run aggregate supply curve.","aggregate demand and short-run aggregate supply curves."],"answer":"D","images":null,"translation":{"question":"在总供给-总需求模型中，通胀惯性由 ______ 的持续向上移动表示：","options":["总需求曲线。","短期总供给曲线。","长期总供给曲线。","总需求曲线和短期总供给曲线。"]},"topics":["phillips-curve"]},{"num":33,"type":"mc","question":"To illustrate inflation inertia in an aggregate demand–aggregate supply model, the short-run aggregate supply curve shifts upward because of increases in ______, and the aggregate demand curve shifts upward because of increases in ______.","options":["the expected price level; the money supply","the money supply; the expected price level","output; the price level","the price level; output"],"answer":"A","images":null,"translation":{"question":"为在总需求-总供给模型中说明通胀惯性，短期总供给曲线因 ______ 增加而上移，总需求曲线因 ______ 增加而上移。","options":["预期价格水平；货币供给","货币供给；预期价格水平","产出；价格水平","价格水平；产出"]},"topics":["phillips-curve"]},{"num":34,"type":"mc","question":"In the case of demand-pull inflation, other things being equal:","options":["both the inflation rate and the unemployment rate rise at the same time.","the unemployment rate rises but the inflation rate falls.","the inflation rate rises but the unemployment rate falls.","both the inflation rate and the unemployment rate fall."],"answer":"C","images":null,"translation":{"question":"在需求拉动型通胀的情况下，其他条件不变：","options":["通胀率和失业率同时上升。","失业率上升但通胀率下降。","通胀率上升但失业率下降。","通胀率和失业率都下降。"]},"topics":["phillips-curve"]},{"num":35,"type":"mc","question":"In the case of cost-push inflation, other things being equal:","options":["both the inflation rate and the unemployment rate rise at the same time.","the unemployment rate rises but the inflation rate falls.","the inflation rate rises but the unemployment rate falls.","both the inflation rate and the unemployment rate fall."],"answer":"C","images":null,"translation":{"question":"在成本推动型通胀的情况下，其他条件不变：","options":["通胀率和失业率同时上升。","失业率上升但通胀率下降。","通胀率上升但失业率下降。","通胀率和失业率都下降。"]},"topics":["phillips-curve"]},{"num":36,"type":"mc","question":"Exhibit: AD–AS Shifts Starting from long-run equilibrium at A with output equal to and the price level equal to P1, a cost-push inflation would be represented by a shift from:","options":["AD1 to AD2","AD1 to AD3","AS1 to AS2","AS1 to AS3"],"answer":"C","images":null,"translation":{"question":"图：AD–AS 移动。从 A 点的长期均衡出发（产出等于自然水平、价格水平等于 P1），成本推动型通胀将由从 ______ 的移动表示：","options":["AD1 到 AD2","AD1 到 AD3","AS1 到 AS2","AS1 到 AS3"]},"topics":["phillips-curve"]},{"num":37,"type":"mc","question":"Exhibit: AD–AS Shifts Starting from long-run equilibrium at A with output equal to and the price level equal to P1, a demand-pull inflation would be represented by a shift from:","options":["AD1 to AD2","AD1 to AD3","AS1 to AS2","AS1 to AS3"],"answer":"A","images":["c14_img2.png"],"translation":{"question":"图：AD–AS 移动。从 A 点的长期均衡出发（产出等于自然水平、价格水平等于 P1），需求拉动型通胀将由从 ______ 的移动表示：","options":["AD1 到 AD2","AD1 到 AD3","AS1 到 AS2","AS1 到 AS3"]},"topics":["phillips-curve"]},{"num":38,"type":"mc","question":"The short-run Phillips curve:","options":["shifts upward if expected inflation increases.","shifts upward if expected inflation decreases.","shifts downward if expected inflation increases.","is vertical."],"answer":"A","images":["c14_img3.png"],"translation":{"question":"短期菲利普斯曲线：","options":["若预期通胀上升则向上移动。","若预期通胀下降则向上移动。","若预期通胀上升则向下移动。","是垂直的。"]},"topics":["phillips-curve"]},{"num":39,"type":"mc","question":"The Phillips curve analysis described in Chapter 14 implies that there is a negative tradeoff between inflation and unemployment in:","options":["both the short run and the long run.","the short run only.","the long run only.","neither the short run nor the long run."],"answer":"B","images":null,"translation":{"question":"第 14 章描述的菲利普斯曲线分析意味着，通胀与失业之间存在负向权衡：","options":["在短期和长期都存在。","仅在短期。","仅在长期。","在短期和长期都不存在。"]},"topics":["phillips-curve"]},{"num":40,"type":"mc","question":"The tradeoff between inflation and unemployment does not exist in the long run because people will adjust their expectations so that expected inflation:","options":["exceeds the inflation rate.","equals the inflation rate.","is below the inflation rate.","equals the inflation rate of the previous year."],"answer":"B","images":null,"translation":{"question":"长期中通胀与失业之间的权衡不存在，因为人们会调整其预期，使预期通胀：","options":["超过通胀率。","等于通胀率。","低于通胀率。","等于前一年的通胀率。"]},"topics":["phillips-curve"]},{"num":41,"type":"mc","question":"Analysis of the short-run Phillips curve suggests that policymakers who want to reduce unemployment in the short run should ______ aggregate demand at a cost of generating ______ inflation.","options":["increase; higher","increase; lower","decrease; higher","decrease; lower"],"answer":"A","images":null,"translation":{"question":"短期菲利普斯曲线的分析表明，想在短期降低失业率的政策制定者应 ______ 总需求，代价是产生 ______ 通胀。","options":["增加；更高","增加；更低","减少；更高","减少；更低"]},"topics":["phillips-curve"]},{"num":42,"type":"mc","question":"Exhibit: Short-Run Phillips Curve As the short-run Phillips curve shifts from A to B to C to D, policymakers face:","options":["the same tradeoff between inflation and unemployment.","a lower rate of inflation for any level of unemployment.","a higher rate of inflation for any level of unemployment.","higher than expected inflation rates and lower unemployment rates."],"answer":"B","images":null,"translation":{"question":"图：短期菲利普斯曲线。当短期菲利普斯曲线从 A 移到 B 再到 C 再到 D 时，政策制定者面临：","options":["通胀与失业之间相同的权衡。","任何失业率水平下更低的通胀率。","任何失业率水平下更高的通胀率。","高于预期的通胀率和更低的失业率。"]},"topics":["phillips-curve"]},{"num":43,"type":"mc","question":"Exhibit: Short-Run Phillips Curve As the short-run Phillips curve shifts from A to B to C to D:","options":["the expected rate of inflation is unchanged at every level of unemployment.","there is a lower-than-expected rate of inflation at every level of unemployment.","there is a higher-than-expected rate of inflation for every level of unemployment.","the natural rate of unemployment increases."],"answer":"B","images":["c14_img4.png"],"translation":{"question":"图：短期菲利普斯曲线。当短期菲利普斯曲线从 A 移到 B 再到 C 再到 D 时：","options":["每个失业率水平下的预期通胀率都不变。","每个失业率水平下的通胀率都低于预期。","每个失业率水平下的通胀率都高于预期。","自然失业率上升。"]},"topics":["phillips-curve"]},{"num":44,"type":"mc","question":"The sacrifice ratio measures the:","options":["number of percentage points of the money supply that must be reduced to reduce inflation by 1 percentage point.","extra taxes that must be paid to balance the budget.","number of months of real gross domestic product (GDP) that must be forgone to reduce the inflation rate by 1 percentage point.","percentage of a year's real gross domestic product (GDP) that must be forgone to reduce inflation by 1 percentage point."],"answer":"D","images":["c14_img5.png"],"translation":{"question":"牺牲率衡量的是：","options":["为降低 1 个百分点通胀所需减少的货币供给的百分点数。","为平衡预算必须缴纳的额外税收。","为降低 1 个百分点通胀所需放弃的实际国内生产总值（GDP）的月数。","为降低 1 个百分点通胀所需放弃的一年实际国内生产总值（GDP）的百分比。"]},"topics":["sacrifice-ratio"]},{"num":45,"type":"mc","question":"The percentage of a year's real GDP that must be forgone to reduce inflation by 1 percentage point is called the:","options":["NAIRU.","short-run Phillips curve.","sacrifice ratio.","Okun's law."],"answer":"C","images":null,"translation":{"question":"为降低 1 个百分点通胀所需放弃的一年实际 GDP 的百分比被称为：","options":["NAIRU。","短期菲利普斯曲线。","牺牲率。","奥肯定律。"]},"topics":["sacrifice-ratio"]},{"num":46,"type":"mc","question":"Assume that the sacrifice ratio for an economy is 4. If the central bank wishes to reduce inflation from 10 percent to 5 percent, this will cost the economy ______ percent of one year's GDP.","options":["4","5","20","40"],"answer":"C","images":null,"translation":{"question":"假设某经济的牺牲率为 4。若央行希望将通胀率从 10% 降到 5%，这将使经济付出 ______ % 的一年 GDP。","options":["4","5","20","40"]},"topics":["sacrifice-ratio"]},{"num":47,"type":"mc","question":"The rational-expectations point of view, in the most extreme case, holds that if policymakers are credibly committed to reducing inflation, and rational people understand that commitment and quickly lower their inflation expectations, then the sacrifice ratio will be approximately:","options":["5.","2.8.","1.","0."],"answer":"D","images":null,"translation":{"question":"理性预期观点在最极端的情况下认为，如果政策制定者可信地承诺降低通胀，且理性的人理解这一承诺并迅速降低其通胀预期，那么牺牲率将约为：","options":["5。","2.8。","1。","0。"]},"topics":["sacrifice-ratio"]},{"num":48,"type":"mc","question":"All of the following are requirements for reducing inflation without causing a recession except:","options":["workers and firms must form expectations rationally.","the plan must be announced before expectations are formed.","the plan must be believed by workers and firms.","the government's budget must be balanced."],"answer":"D","images":null,"translation":{"question":"以下都是无衰退降低通胀的要求，除了：","options":["工人和企业必须理性地形成预期。","计划必须在预期形成之前宣布。","计划必须被工人和企业相信。","政府预算必须平衡。"]},"topics":["sacrifice-ratio"]},{"num":49,"type":"mc","question":"Advocates of the rational-expectations approach predict that a credible policy to lower inflation will result in a loss of output that is ______ than expected based on the sacrifice ratio.","options":["larger","smaller","the same","sometimes larger and sometimes slower"],"answer":"B","images":null,"translation":{"question":"理性预期方法的拥护者预测，可信的降低通胀政策导致的产出损失将 ______ 基于牺牲率的预期。","options":["大于","小于","等于","有时大于有时更慢于"]},"topics":["sacrifice-ratio"]},{"num":50,"type":"mc","question":"The estimate of the sacrifice ratio from the Volcker disinflation is approximately:","options":["5–6.","2.5–3.","1–1.5.","0–0.5."],"answer":"B","images":null,"translation":{"question":"沃尔克反通胀的牺牲率估计约为：","options":["5–6。","2.5–3。","1–1.5。","0–0.5。"]},"topics":["sacrifice-ratio"]},{"num":51,"type":"mc","question":"The hypothesis that hysteresis may play an important role in macroeconomics implies, among other things, that:","options":["the history of economic thought is important to macroeconomics.","workers get hysterical during long depressions.","hysteresis lowers the sacrifice ratio.","the natural rate of unemployment may increase if unemployment is high for a long period of time."],"answer":"D","images":null,"translation":{"question":"滞后效应可能在宏观经济学中起重要作用的假说意味着，除其他外：","options":["经济思想史对宏观经济学很重要。","工人在长期萧条中会变得歇斯底里。","滞后效应降低牺牲率。","若失业长期高企，自然失业率可能上升。"]},"topics":["sacrifice-ratio"]},{"num":52,"type":"mc","question":"According to the natural-rate hypothesis, fluctuations in aggregate demand affect output in:","options":["both the short run and the long run.","only in the short run.","only in the long run.","in neither the short run nor the long run."],"answer":"B","images":null,"translation":{"question":"根据自然率假说，总需求的波动影响产出：","options":["在短期和长期。","仅在短期。","仅在长期。","在短期和长期都不。"]},"topics":["expectations-as"]},{"num":53,"type":"mc","question":"According to the natural-rate hypothesis, output will be at the natural rate:","options":["if inflation exceeds expected inflation.","if inflation falls below expected inflation.","if inflation meets expectations in the short run.","if aggregate demand affects output in the long run."],"answer":"C","images":null,"translation":{"question":"根据自然率假说，产出将处于自然率，当：","options":["通胀超过预期通胀时。","通胀低于预期通胀时。","短期中通胀符合预期时。","总需求在长期影响产出时。"]},"topics":["expectations-as"]},{"num":54,"type":"mc","question":"A recession may alter an economy's natural rate of unemployment in all of the following ways except by:","options":["changing an unemployed individual's attitude toward work.","reducing an unemployed worker's job skills.","permanently reducing the money supply.","altering the wage-setting process."],"answer":"C","images":null,"translation":{"question":"衰退可能通过以下所有方式改变经济的自然失业率，除了：","options":["改变失业者对工作的态度。","降低失业者的工作技能。","永久减少货币供给。","改变工资设定过程。"]},"topics":["sacrifice-ratio"]},{"num":55,"type":"mc","question":"The idea that the natural rate of unemployment is increased following extended periods of unemployment is called:","options":["Okun's law.","the Phillips curve.","the natural-rate hypothesis.","hysteresis."],"answer":"D","images":null,"translation":{"question":"长期失业后自然失业率上升的观点被称为：","options":["奥肯定律。","菲利普斯曲线。","自然率假说。","滞后效应（hysteresis）。"]},"topics":["sacrifice-ratio"]},{"num":56,"type":"mc","question":"If the hypothesis of hysteresis is correct and output is lost even after a period of disinflation, the sacrifice ratio for an economy will:","options":["increase.","decrease.","remain unchanged.","be zero."],"answer":"A","images":null,"translation":{"question":"如果滞后效应假说正确，且在一段反通胀时期之后产出仍有损失，则经济的牺牲率将：","options":["上升。","下降。","保持不变。","为零。"]},"topics":["sacrifice-ratio"]},{"num":57,"type":"mc","question":"According to the natural-rate hypothesis, the levels of output and unemployment depend on:","options":["aggregate demand in the short run but not in the long run.","aggregate demand in the long run but not in the short run.","the natural rate of unemployment in the short run but the natural rate of inflation in the long run.","the natural rate of inflation in the short run but the natural rate of unemployment in the long run."],"answer":"A","images":null,"translation":{"question":"根据自然率假说，产出和失业的水平取决于：","options":["短期而非长期的总需求。","长期而非短期的总需求。","短期的自然失业率但长期的通胀自然率。","短期的通胀自然率但长期的自然失业率。"]},"topics":["expectations-as"]},{"num":58,"type":"mc","question":"Each of the following conditions will tend to reduce the sacrifice ratio except when:","options":["workers and firms set wages and prices based on rational expectations.","policymakers make credible commitments to policy changes.","announcements of policy changes are made before workers and firms have formed expectations.","the concept of hysteresis accurately describes the impact of history on the natural rate of unemployment."],"answer":"D","images":null,"translation":{"question":"以下每种条件都将趋于降低牺牲率，除了当：","options":["工人和企业基于理性预期设定工资和价格。","政策制定者对政策变化做出可信承诺。","政策变化的宣布在工人和企业形成预期之前做出。","滞后效应概念准确描述了历史对自然失业率的影响。"]},"topics":["sacrifice-ratio"]},{"num":59,"type":"mc","question":"The endogenous variables of “The Mother of All Models” in the appendix to Chapter 14 include the level of output, the natural rate of output, the price level, and:","options":["the real and nominal interest rates.","the money supply.","the world price level.","government purchases."],"answer":"A","images":null,"translation":{"question":"第 14 章附录中“万模之母”的内生变量包括产出水平、自然产出率、价格水平以及：","options":["实际利率和名义利率。","货币供给。","世界价格水平。","政府购买。"]},"topics":["expectations-as"]},{"num":60,"type":"mc","question":"All of the following are exogenous variables in “The Mother of All Models” in the appendix to Chapter 14 except the:","options":["world interest rate.","labor force.","world real interest rate.","price level."],"answer":"D","images":null,"translation":{"question":"以下都是第 14 章附录中“万模之母”的外生变量，除了：","options":["世界利率。","劳动力。","世界实际利率。","价格水平。"]},"topics":["expectations-as"]},{"num":61,"type":"mc","question":"If price expectations are assumed to be correct, money demand is proportional to income, and there are no international capital flows, then the mother of all models in the appendix to Chapter 14 corresponds to which of the following special cases?","options":["classical closed economy","classical open economy","IS–LM model","Mundell–Fleming model with floating exchange rate"],"answer":"A","images":null,"translation":{"question":"如果假设价格预期正确、货币需求与收入成比例、且不存在国际资本流动，那么第 14 章附录中的万模之母对应于以下哪个特例？","options":["古典封闭经济","古典开放经济","IS–LM 模型","浮动汇率的 Mundell–Fleming 模型"]},"topics":["expectations-as"]},{"num":62,"type":"mc","question":"If price expectations are assumed to be correct, money demand is proportional to income, and net capital flow is infinitely elastic, then the mother of all models in the appendix to Chapter 14 corresponds to which of the following special cases?","options":["classical closed economy","classical open economy","IS–LM model","Mundell–Fleming model with floating exchange rate"],"answer":"B","images":null,"translation":{"question":"如果假设价格预期正确、货币需求与收入成比例、且净资本流动无限弹性，那么第 14 章附录中的万模之母对应于以下哪个特例？","options":["古典封闭经济","古典开放经济","IS–LM 模型","浮动汇率的 Mundell–Fleming 模型"]},"topics":["expectations-as"]},{"num":63,"type":"mc","question":"If the short-run aggregate supply curve is assumed to be horizontal and money demand is proportional to income, then the mother of all models in the appendix to Chapter 14 corresponds to which of the following special cases?","options":["classical closed economy","aggregate demand and aggregate supply","IS–LM model","Mundell–Fleming model with floating exchange rate"],"answer":"B","images":null,"translation":{"question":"如果假设短期总供给曲线是水平的、且货币需求与收入成比例，那么第 14 章附录中的万模之母对应于以下哪个特例？","options":["古典封闭经济","总需求与总供给","IS–LM 模型","浮动汇率的 Mundell–Fleming 模型"]},"topics":["expectations-as"]},{"num":64,"type":"mc","question":"If the short-run aggregate supply curve is assumed to be horizontal and there are no international capital flows, then the mother of all models in the appendix to Chapter 14 corresponds to which of the following special cases?","options":["classical closed economy","aggregate demand and aggregate supply","IS–LM model","Mundell–Fleming model with floating exchange rate"],"answer":"C","images":null,"translation":{"question":"如果假设短期总供给曲线是水平的、且不存在国际资本流动，那么第 14 章附录中的万模之母对应于以下哪个特例？","options":["古典封闭经济","总需求与总供给","IS–LM 模型","浮动汇率的 Mundell–Fleming 模型"]},"topics":["expectations-as"]},{"num":65,"type":"mc","question":"If the short-run aggregate supply curve is assumed to be horizontal and international capital flows are infinitely elastic, then the mother of all models in the appendix to Chapter 14 corresponds to which of the following special cases?","options":["classical closed economy","aggregate demand and aggregate supply","IS–LM model","Mundell–Fleming model with floating exchange rate"],"answer":"D","images":null,"translation":{"question":"如果假设短期总供给曲线是水平的、且国际资本流动无限弹性，那么第 14 章附录中的万模之母对应于以下哪个特例？","options":["古典封闭经济","总需求与总供给","IS–LM 模型","浮动汇率的 Mundell–Fleming 模型"]},"topics":["expectations-as"]},{"num":66,"type":"mc","question":"If the short-run aggregate supply curve is assumed to be horizontal, international capital flows are infinitely elastic, and the nominal exchange rate is fixed, then the mother of all models in the appendix to Chapter 14 corresponds to which of the following special cases?","options":["classical open economy","IS–LM model","Mundell–Fleming model with floating exchange rate","Mundell–Fleming model with fixed exchange rate"],"answer":"D","images":null,"translation":{"question":"如果假设短期总供给曲线是水平的、国际资本流动无限弹性、且名义汇率固定，那么第 14 章附录中的万模之母对应于以下哪个特例？","options":["古典开放经济","IS–LM 模型","浮动汇率的 Mundell–Fleming 模型","固定汇率的 Mundell–Fleming 模型"]},"topics":["expectations-as"]},{"num":67,"type":"mc","question":"In the sticky-price model, if no firms have flexible prices, the short-run aggregate supply schedule will:","options":["be vertical.","be steeper than it would be if some firms had flexible prices.","slope upward to the right.","be horizontal."],"answer":"D","images":null,"translation":{"question":"在粘性价格模型中，如果没有企业拥有弹性价格，则短期总供给曲线将：","options":["是垂直的。","比一些企业拥有弹性价格时更陡。","向右上方倾斜。","是水平的。"]},"topics":["expectations-as"]},{"num":68,"type":"mc","question":"Assume that an economy has the Phillips curve p = p–1 – 0.5 (u – 0.06). Then the natural rate of unemployment is:","options":["0.5.","0.12.","0.06.","0.03."],"answer":"C","images":null,"translation":{"question":"假设某经济的菲利普斯曲线为 p = p–1 – 0.5 (u – 0.06)。则自然失业率为：","options":["0.5。","0.12。","0.06。","0.03。"]},"topics":["phillips-curve"]},{"num":69,"type":"mc","question":"Assume that an economy has the Phillips curve p = p–1 – 0.5 (u – 0.06). How many percentage-point-years of cyclical unemployment are needed to reduce inflation by 5 percentage points?","options":["20","10","5","2.5"],"answer":"B","images":null,"translation":{"question":"假设某经济的菲利普斯曲线为 p = p–1 – 0.5 (u – 0.06)。降低 5 个百分点通胀需要多少百分点-年的周期性失业？","options":["20","10","5","2.5"]},"topics":["sacrifice-ratio"]},{"num":70,"type":"mc","question":"The government can lower inflation with a low sacrifice ratio if the:","options":["money supply is reduced slowly.","public has adaptive expectations.","short-run aggregate supply schedule is relatively flat.","public rationally believe that policymakers are committed to reducing inflation."],"answer":"D","images":null,"translation":{"question":"政府能够以低牺牲率降低通胀，如果：","options":["货币供给缓慢减少。","公众有适应性预期。","短期总供给曲线相对平坦。","公众理性地相信政策制定者致力于降低通胀。"]},"topics":["sacrifice-ratio"]},{"num":71,"type":"mc","question":"If only unanticipated changes in the money supply affect real GDP, the public has rational expectations, and everyone has the same information about the state of the economy, then:","options":["monetary policy can be used to systematically stabilize output.","monetary policy cannot be used to systematically stabilize output.","a policy of keeping the money supply constant is optimal.","a policy of adjusting the money supply in response to the state of the economy is optimal."],"answer":"B","images":null,"translation":{"question":"如果只有未预期到的货币供给变化影响实际 GDP，公众有理性预期，且每个人都有关于经济状况的相同信息，则：","options":["货币政策可被用来系统地稳定产出。","货币政策不能被用来系统地稳定产出。","保持货币供给不变的政策是最优的。","根据经济状况调整货币供给的政策是最优的。"]},"topics":["expectations-as"]},{"num":72,"type":"sa","question":"Assume that an economy is governed by the Phillips curve p = pe – 0.5 (u – 0.06), where p = (P – P–1) / P–1, pe = p–1, and 0.06 is the natural rate of unemployment. Suppose that, in period zero, p = 0.03 and pe = 0.03—that is, that the economy is experiencing steady inflation at a 3-percent rate. a. Now assume that the government decides to impose whatever demand is necessary to cut unemployment to 0.04. Suppose the government follows this policy for periods 1 through 5. Create a table of p and pe for these five periods. b. Assume that, for periods 6 through 10, the government decides to hold unemployment at 0.06. Create another table of p and pe for these five periods. Is there any reason to expect the inflation rate to go back to 0.03? c. If the government persisted in its behavior under part a, do you think the public would continue for long forming expectations according to pe = p–1? Why?","options":null,"answer":null,"images":null,"translation":{"question":"假设某经济由菲利普斯曲线 p = pe – 0.5 (u – 0.06) 支配，其中 p = (P – P–1) / P–1，pe = p–1，且 0.06 为自然失业率。假设在第 0 期，p = 0.03 且 pe = 0.03——也就是说，经济正以 3% 的通胀率稳定运行。a. 现在假设政府决定施加必要需求把失业率降到 0.04。假设政府在第 1 到第 5 期执行这一政策。为这五个时期创建 p 和 pe 的表格。b. 假设在第 6 到第 10 期，政府决定把失业率保持在 0.06。为这五个时期创建另一个 p 和 pe 的表格。有什么理由预期通胀率会回到 0.03 吗？c. 如果政府持续执行 a 部分中的行为，你认为公众会长期按照 pe = p–1 形成预期吗？为什么？","options":null},"topics":["phillips-curve","expectations-as"],"answer_ref":"a. 设政府把失业率压在自然率之下（如 u=0.04）：π₁ = 0.03 − 0.5×(0.04−0.06) = 0.04；此后 πe 随之上调，π 逐年上升：π₂ = 0.05、π₃ = 0.06……每期加速 0.5×(u−un) 个百分点。b. 只要 u<un，通胀就持续加速——短期内能换得低于自然率的失业，代价是不断攀升的通货膨胀，最终被迫回到自然失业率。"},{"num":73,"type":"sa","question":"Assume that an economy is initially operating at the natural rate of output. Use the model of aggregate demand and aggregate supply (using the upward-sloping short-run aggregate supply curve) to illustrate graphically the short-run and long-run effects on price and output of a reduction in government spending that produces a budget surplus.","options":null,"answer":null,"images":null,"translation":{"question":"假设某经济最初在自然产出率运行。用总需求与总供给模型（使用向上倾斜的短期总供给曲线）图示政府支出减少（产生预算盈余）对价格和产出的短期和长期影响。","options":null},"topics":["expectations-as"],"answer_ref":"图（向上倾斜的 SRAS）：G↓→AD 左移。短期：沿 SRAS 从 E₀ 到 E₁——P 由 P₀ 降至 P₁，Y 降至自然率以下（衰退缺口）。长期：工资与预期价格下调，SRAS 右移回位——产出回到自然率，价格水平永久性地更低（P₂<P₀）。预算盈余以短期产出损失换取长期更低的价格水平。"},{"num":74,"type":"sa","question":"Assume that an economy is initially at the natural rate of unemployment. a. Use a Phillips curve diagram to illustrate graphically how the inflation rate and unemployment rate respond both in the short run and in the long run to an unexpected expansionary monetary policy. b. Use a Phillips curve diagram to illustrate graphically how the inflation rate and unemployment rate respond both in the short run and in the long run to the announcement of a credible plan of expansionary monetary policy when people have rational expectations.","options":null,"answer":null,"images":null,"translation":{"question":"假设某经济最初处于自然失业率。a. 用菲利普斯曲线图图示未预期到的扩张性货币政策如何使通胀率和失业率在短期和长期做出反应。b. 用菲利普斯曲线图图示当人们有理性预期时，可信的扩张性货币政策计划的宣布如何使通胀率和失业率在短期和长期做出反应。","options":null},"topics":["phillips-curve"],"answer_ref":"a. 意外货币扩张：沿短期菲利普斯曲线 SRPC 移动——π 上升、u 降至自然率之下；长期预期通胀跟上，SRPC 上移，u 回到自然率，停在更高的 π。b. 意外货币紧缩：π 下降、u 升至自然率之上；长期 SRPC 下移，u 回到自然率，π 稳定在更低水平。两种情形长期都只改变通胀、不改变失业。"},{"num":75,"type":"sa","question":"The firms and workers in Alpha form expectations adaptively. The firms and workers in Omega form expectations rationally. Their otherwise identical economies are initially in equilibrium at the natural level of output with 10 percent inflation. The central banks of both Alpha and Omega make credible commitments to reduce the growth rates of money until they achieve 2 percent inflation. Compare and contrast the adjustment process to the new equilibrium at the lower rate of inflation in both countries.","options":null,"answer":null,"images":null,"translation":{"question":"Alpha 国的企业和工人形成适应性预期。Omega 国的企业和工人形成理性预期。两国其他方面相同的经济最初处于自然产出水平、10% 通胀的均衡。Alpha 和 Omega 的央行都做出可信承诺，降低货币增长率直到实现 2% 通胀。比较两国在较低通胀率下向新均衡调整的过程。","options":null},"topics":["expectations-as","sacrifice-ratio"],"answer_ref":"Alpha（适应性预期）：央行承诺不被相信，只有连续兑现低通胀实绩后预期才缓慢下调——通胀从10%降到2%需要长期把失业率压在自然率之上，付出巨大的牺牲率。Omega（理性预期+可信承诺）：宣布立即改变预期的通胀，工资价格随之下调——通胀几乎无痛苦地直接降到2%，失业率始终贴近自然率。结论：预期的形成方式决定反通胀的成本。"},{"num":76,"type":"sa","question":"For each of the two models of short-run aggregate supply (sticky price and imperfect information) compare the following characteristics: a. the nature of the market imperfection that generates the short-run movements in output associated with unexpected movements in the price level. b. whether prices are flexible or fixed.","options":null,"answer":null,"images":null,"translation":{"question":"对于两种短期总供给模型（粘性价格和不完全信息），比较以下特征：a. 产生与价格水平未预期变动相关的短期产出变动的市场不完善的性质。b. 价格是弹性的还是固定的。","options":null},"topics":["expectations-as"],"answer_ref":"粘性价格模型：市场不完善在于企业调整价格有成本（菜单成本/合同），部分企业价格短期固定；价格对固定价企业是\"固定的\"。不完全信息模型：不完善在于当事人不知道总体价格水平，把一般物价变动误认为相对价格变动；价格本身完全弹性，只是信息不完全。两者都使未预期物价上涨带动产出增加，但机制一在名义价格刚性，一在信息噪声。"},{"num":77,"type":"sa","question":"a. What is the sacrifice ratio? b. What is one factor that could possibly lower the sacrifice ratio for an economy? c. What is one factor that could possibly increase the sacrifice ratio for an economy?","options":null,"answer":null,"images":null,"translation":{"question":"a. 什么是牺牲率？b. 什么因素可能降低某经济的牺牲率？c. 什么因素可能提高某经济的牺牲率？","options":null},"topics":["sacrifice-ratio"],"answer_ref":"a. 牺牲率：通胀率每降低1个百分点所必须放弃的一年实际GDP百分比。b. 可能降低的因素：理性预期与央行可信度（无痛苦反通胀）、指数化程度低、工资合同期短、劳动力市场灵活。c. 可能提高的因素：长期指数化合同、适应性预期、央行历史失信、通胀惯性大。"},{"num":78,"type":"sa","question":"Use the aggregate demand–aggregate supply model to graphically illustrate the difference between demand-pull and cost-push inflation. Explain your graphs in words.","options":null,"answer":null,"images":null,"translation":{"question":"用总需求-总供给模型图示需求拉动型通胀与成本推动型通胀之间的区别。用文字解释你的图。","options":null},"topics":["phillips-curve"],"answer_ref":"需求拉动型：AD 右移沿 SRAS 上行——P 与 Y 同升（过热）；菲利普斯图上沿 SRAS 曲线向左上方移动（低失业、高通胀）。成本推动型：SRAS 左移——P 升而 Y 降（滞胀）；菲利普斯曲线整体右移，同样的失业率对应更高通胀。图形差异在于移动的是哪条曲线。"},{"num":79,"type":"sa","question":"Illustrate the short-run and long-run impact of an unexpected monetary contraction using both the AD–AS model and the Phillips curve. Assume the economy starts at full employment.","options":null,"answer":null,"images":null,"translation":{"question":"用 AD–AS 模型和菲利普斯曲线说明未预期到的货币紧缩的短期和长期影响。假设经济始于充分就业。","options":null},"topics":["phillips-curve"],"answer_ref":"AD-AS：意外紧缩→AD 左移：短期 P 降、Y 降至自然率以下；长期预期价格下调，SRAS 右移，Y 回自然率、P 更低。菲利普斯：沿 SRPC 向右下方移动（π↓、u↑高于自然率）；长期 SRPC 随预期下调而下移，u 回自然率、π 稳定于更低水平。两图互为镜像。"},{"num":80,"type":"sa","question":"How would an adverse supply shock change the short-run tradeoff between inflation and unemployment? Illustrate your answer using a Phillips curve diagram.","options":null,"answer":null,"images":["c14_img6.png"],"translation":{"question":"不利的供给冲击会如何改变通胀与失业之间的短期权衡？用菲利普斯曲线图说明你的答案。","options":null},"topics":["phillips-curve"],"answer_ref":"不利供给冲击使菲利普斯曲线整体右移：任一失业率下通胀更高——短期取舍恶化。要在冲击后维持原失业率需接受更高通胀；要把通胀压回原水平则需把失业率推到更高。图形：SRPC₀ 右移至 SRPC₁，与自然率垂线交于更高通胀点。"},{"num":81,"type":"sa","question":"Assume that people form expectations rationally and that the sticky-price model describes the aggregate supply curve in the economy. For each of the following scenarios explain whether or not monetary policy can have real effects on the economy. a. The central bank determines monetary policy using the same information available to all firms and at the same time firms are setting prices, so that both firms and policymakers have all of the same information. b. The central bank determines monetary policy after firms have set prices using information not available at the time prices were set.","options":null,"answer":null,"images":null,"translation":{"question":"假设人们理性地形成预期，且粘性价格模型描述经济中的总供给曲线。对于以下每种情形，解释货币政策是否会对经济产生实际影响。a. 央行使用与所有企业可获得的相同信息、且在企业设定价格的同一时间决定货币政策，因此企业和政策制定者都拥有所有相同信息。b. 央行在企业设定价格之后、使用设定价格时不可获得的信息来决定货币政策。","options":null},"topics":["expectations-as"],"answer_ref":"a. 若央行与所有企业同时获得相同信息并据此制定政策，则政策是可被预期的——理性预期下没有意外，货币变动不影响实际产出（只有未预期到的货币才有实际效应）。b. 若央行能基于企业定价之后才获得的信息（或政策本身出乎预期）行动，则货币冲击在价格粘住时发生，产生真实的产出效应。关键不在理性预期本身，而在于\"意外\"。"},{"num":82,"type":"sa","question":"An economy is initially in equilibrium at the natural level. The central bank increases the money supply. Graphically illustrate and explain short-run monetary nonneutrality and long-run monetary neutrality using the AD–AS model.","options":null,"answer":null,"images":null,"translation":{"question":"某经济最初处于自然水平的均衡。央行增加货币供给。用 AD–AS 模型图示并解释短期货币非中性和长期货币中性。","options":null},"topics":["expectations-as"],"answer_ref":"短期非中性：M↑→AD 右移，价格粘性下主要体现为产出与就业增加（物价升幅小于长期）。长期中性：预期价格上调，SRAS 左移，产出回到自然率，物价与货币同比例上升——只有名义变量改变。图：E₀→E₁（短期，Y↑P↑）→E₂（长期，Y回到自然率，P更高）。"},{"num":83,"type":"sa","question":"What is the shape of the short-run supply curve? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"短期供给曲线的形状是什么？解释。","options":null},"topics":["expectations-as"],"answer_ref":"短期总供给曲线向右上方倾斜（极端凯恩斯情形下水平）。原因三说：粘性价格（部分企业调价慢）、粘性工资（名义工资合同锁定）、不完全信息（厂商误判相对价格）。物价上升时三者都使企业增加产量——斜率取决于价格与工资的调整速度。"},{"num":84,"type":"sa","question":"Explain economist Robert Lucas's arguments justifying the imperfect-information model?","options":null,"answer":null,"images":null,"translation":{"question":"解释经济学家罗伯特·卢卡斯论证不完全信息模型的论点。","options":null},"topics":["expectations-as"],"answer_ref":"卢卡斯论证：单个生产者只观察到自己产品的价格，不知道总价格水平。当自身产品价格上升时，他理性地推断一部分是相对价格上升（应增产）、一部分是总体通胀（不应增产）。在信息不完全下，他把一部分归因于相对价格——总体物价意外上升时，众多厂商都误增产量，总产出随之上升。理性预期+信息摩擦共同推导出总供给与未预期价格正相关。"},{"num":85,"type":"sa","question":"How does the Phillips curve explain the tradeoff between the unemployment and inflation? Illustrate with a graph.","options":null,"answer":null,"images":null,"translation":{"question":"菲利普斯曲线如何解释失业与通胀之间的权衡？用图说明。","options":null},"topics":["phillips-curve"],"answer_ref":"菲利普斯曲线 π = πe − β(u − un)：在自然率附近，失业率低于自然率时通胀上升、高于时通胀下降——短期权衡取舍。图：向下倾斜的 SRPC 与垂直的长期菲利普斯曲线 LRPC 交于 (un, πe) 点；政策只能沿 SRPC 短期移动。"},{"num":86,"type":"sa","question":"Does the Phillips curve relationship between unemployment and inflation hold in the long run? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"菲利普斯曲线所表示的失业与通胀之间的关系在长期成立吗？解释。","options":null},"topics":["phillips-curve"],"answer_ref":"长期不成立。预期通胀会调整到等于实际通胀，菲利普斯曲线退化为自然率处的垂直线——任何通胀率下失业都回到自然率。试图永久压低失业只会导致通胀（最终加速）而无失业收益。短期权衡是暂时的，长期无权衡。"},{"num":87,"type":"sa","question":"How is demand-pull inflation different from cost-push inflation?","options":null,"answer":null,"images":null,"translation":{"question":"需求拉动型通胀与成本推动型通胀有何不同？","options":null},"topics":["phillips-curve"],"answer_ref":"需求拉动：总需求过度增长（货币扩张、财政刺激）沿总供给拉上价格——\"过多的货币追逐过少的商品\"，伴随产出扩张。成本推动：供给面冲击（油价、工资推动）推高成本，SRAS 左移，物价上升而产出下降——滞胀。前者根源在需求，后者在供给。"},{"num":88,"type":"sa","question":"What is the natural rate hypothesis? Explain the term NAIRU.","options":null,"answer":null,"images":null,"translation":{"question":"什么是自然率假说？解释 NAIRU 一词。","options":null},"topics":["phillips-curve"],"answer_ref":"自然率假说：无论通胀如何，失业率趋于其自然率——政策只能暂时改变失业。NAIRU（非加速通货膨胀失业率）：通胀保持稳定时的失业率；低于它通胀加速上升，高于它通胀回落。NAIRU 即自然率的现代表述。"},{"num":89,"type":"sa","question":"Is the sacrifice ratio a cost to reduce inflation? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"牺牲率是降低通胀的代价吗？解释。","options":null},"topics":["sacrifice-ratio"],"answer_ref":"是。牺牲率度量反通胀的实际代价：通胀每降1个百分点需要累计放弃多少GDP（及相伴的失业痛苦）。例如牺牲率5意味着降2点通胀要付出约10%的年GDP——它提醒决策者反通胀政策有真实成本，且成本大小取决于可信度与预期。"}]},{"num":15,"title":"A Dynamic Model of Economic Fluctuations","questions":[{"num":1,"type":"mc","question":"In the dynamic model, the demand for goods and services will ____ as the natural rate of output increases and _____ as the real interest rate increases.","options":["increase; increase","increase; decrease","decrease; decrease","decrease; increase"],"answer":"B","images":null,"translation":{"question":"在动态模型中，当自然产出水平上升时，商品和服务的需求会______；而当实际利率上升时，需求会______。","options":["增加；增加","增加；减少","减少；减少","减少；增加"]},"topics":["dad-das"]},{"num":2,"type":"mc","question":"In the dynamic model, changes in fiscal policy are captured in changes in the:","options":["natural rate of interest.","expected rate of inflation.","demand shock.","natural level of output."],"answer":"C","images":null,"translation":{"question":"在动态模型中，财政政策的变化体现在______的变化中。","options":["自然利率","预期通胀率","需求冲击","自然产出水平"]},"topics":["dad-das"]},{"num":3,"type":"mc","question":"A higher real interest rate reduces the demand for goods and services by:","options":["shifting the dynamic aggregate supply curve.","decreasing the natural level of output.","increasing inflation expectations.","reducing investment and consumption spending."],"answer":"D","images":null,"translation":{"question":"较高的实际利率通过______来减少对商品和服务的需求。","options":["移动动态总供给曲线","降低自然产出水平","提高通胀预期","减少投资和消费支出"]},"topics":["dad-das"]},{"num":4,"type":"mc","question":"For any level of inflation, long-run growth ____ the demand for goods and services.","options":["increases","decreases","does not change","may either increase or decrease"],"answer":"A","images":null,"translation":{"question":"对于任一通胀水平，长期增长会______对商品和服务的需求。","options":["增加","减少","不改变","可能增加也可能减少"]},"topics":["dad-das"]},{"num":5,"type":"mc","question":"Which of the following would be represented by a positive value of the demand shock, et?","options":["an irrational wave of optimism among investors","a decrease in government spending","an aggressive increase in oil prices by a cartel","an increase in the central bank's inflation target"],"answer":"A","images":null,"translation":{"question":"以下哪一项会以需求冲击 et 取正值来表示？","options":["投资者中一股非理性的乐观情绪浪潮","政府支出减少","卡特尔大幅抬高油价","央行通胀目标上升"]},"topics":["dad-das"]},{"num":6,"type":"mc","question":"Which of the following would be represented by a negative value of the random demand shock, et?","options":["an irrational wave of optimism among investors","a decrease in government spending","an aggressive increase in oil prices by a cartel","a decrease in the central bank's inflation target"],"answer":"B","images":null,"translation":{"question":"以下哪一项会以随机需求冲击 et 取负值来表示？","options":["投资者中一股非理性的乐观情绪浪潮","政府支出减少","卡特尔大幅抬高油价","央行通胀目标下调"]},"topics":["dad-das"]},{"num":7,"type":"mc","question":"The real interest rate at which, in the absence of any shock, the demand for goods and services equals the natural rate of output is called the _____ rate of interest.","options":["ex ante","ex post","natural","nominal"],"answer":"C","images":null,"translation":{"question":"在没有任何冲击的情况下，使商品和服务的需求等于自然产出水平的那个实际利率被称为______利率。","options":["事前","事后","自然","名义"]},"topics":["dad-das"]},{"num":8,"type":"mc","question":"According to the Fisher equation, the real interest rate equals the nominal interest rate minus the:","options":["natural rate of interest.","expected rate of inflation.","expected rate of interest.","ex ante rate of interest."],"answer":"B","images":null,"translation":{"question":"根据费雪方程，实际利率等于名义利率减去______。","options":["自然利率","预期通胀率","预期利率","事前利率"]},"topics":["dad-das"]},{"num":9,"type":"mc","question":"The ex ante real interest rate that prevails at time t equals:","options":["it – Etpt","it – Etpt + 1","it – pt","it – pt + 1"],"answer":"B","images":null,"translation":{"question":"在时间 t 上存在的（事前）实际利率等于：","options":["it – Etpt","it – Etpt + 1","it – pt","it – pt + 1"]},"topics":["dad-das"]},{"num":10,"type":"mc","question":"The ex post real interest rate at time t equals:","options":["it – Etpt","it – Etpt + 1","it – pt","it – pt + 1"],"answer":"D","images":null,"translation":{"question":"在时间 t 上的（事后）实际利率等于：","options":["it – Etpt","it – Etpt + 1","it – pt","it – pt + 1"]},"topics":["dad-das"]},{"num":11,"type":"mc","question":"The nominal interest rate, it, is the nominal rate of return between periods:","options":["t – 1 and t","t and t + 1","t – 1 and t + 1","t and t + 2"],"answer":"B","images":null,"translation":{"question":"名义利率 it 是______两期之间的名义收益率。","options":["t – 1 与 t","t 与 t + 1","t – 1 与 t + 1","t 与 t + 2"]},"topics":["dad-das"]},{"num":12,"type":"mc","question":"According to the Phillips curve, the inflation rate depends on all of the following except:","options":["previously expected inflation.","an exogenous supply shock.","the real interest rate.","the deviation of output from its natural rate."],"answer":"C","images":null,"translation":{"question":"根据菲利普斯曲线，通胀率取决于以下所有因素，除了：","options":["此前预期的通胀","外生供给冲击","实际利率","产出对其自然水平的偏离"]},"topics":["dad-das"]},{"num":13,"type":"mc","question":"According to the Phillips curve, inflation depends on expected inflation because:","options":["the real interest rate depends on the expected rate of inflation.","the central bank sets its target inflation rate based on the expected rate of inflation.","the natural level of output depends on the expected rate of inflation.","when some firms set prices in advance, expected inflation influences future prices."],"answer":"D","images":null,"translation":{"question":"根据菲利普斯曲线，通胀取决于预期通胀，因为：","options":["实际利率取决于预期通胀率","央行根据预期通胀率设定其目标通胀率","自然产出水平取决于预期通胀率","当一些企业提前定价时，预期通胀会影响未来的价格"]},"topics":["dad-das"]},{"num":14,"type":"mc","question":"According to the Phillips curve, firms raise prices when output is _____ the natural level of output or, equivalently, when the unemployment rate is _____ the natural rate of unemployment.","options":["above; above","above; below","below; below","below; above"],"answer":"B","images":null,"translation":{"question":"根据菲利普斯曲线，当产出______自然产出水平时，或者等价地，当失业率______自然失业率时，企业会提高价格。","options":["高于；高于","高于；低于","低于；低于","低于；高于"]},"topics":["dad-das"]},{"num":15,"type":"mc","question":"In the dynamic model, the supply shock variable, ut, is a variable appearing in which of the following equations of the model?","options":["Fisher equation","Phillips curve","monetary-policy rule","adaptive expectations"],"answer":"B","images":null,"translation":{"question":"在动态模型中，供给冲击变量 ut 出现在该模型的以下哪个方程中？","options":["费雪方程","菲利普斯曲线","货币政策规则","适应性预期"]},"topics":["dad-das"]},{"num":16,"type":"mc","question":"Which of the following would be represented by a positive value of the random supply shock, ut?","options":["an irrational wave of optimism among investors","an increase in government spending","widespread drought leading to large increases in food prices","an increase in the central bank's inflation target"],"answer":"C","images":null,"translation":{"question":"以下哪一项会以随机供给冲击 ut 取正值来表示？","options":["投资者中一股非理性的乐观情绪浪潮","政府支出增加","导致食品价格大幅上涨的大范围干旱","央行通胀目标上升"]},"topics":["dad-das"]},{"num":17,"type":"mc","question":"The dynamic model of aggregate demand and aggregate supply assumes that people form expectations of inflation based on:","options":["forecasts optimally using all available information.","recently observed inflation.","the central bank's inflation target.","the difference between the nominal and real interest rate."],"answer":"B","images":null,"translation":{"question":"动态总需求与动态总供给模型假设人们基于______来形成通胀预期。","options":["最优地利用所有可得信息进行预测","近期观察到的通胀","央行的通胀目标","名义利率与实际利率之差"]},"topics":["dad-das"]},{"num":18,"type":"mc","question":"Expectations of inflation based on recently observed inflation is called the assumption of _____ expectations.","options":["natural","rational","dynamic","adaptive"],"answer":"D","images":null,"translation":{"question":"基于近期观察到的通胀来形成通胀预期，被称为______预期假设。","options":["自然","理性","动态","适应性"]},"topics":["dad-das"]},{"num":19,"type":"mc","question":"According to the monetary policy rule, when inflation is at its target level and output is at the natural level, then the real interest rate equals the:","options":["nominal rate of interest.","target rate of inflation.","natural rate of interest.","current rate of inflation."],"answer":"C","images":null,"translation":{"question":"根据货币政策规则，当通胀处于目标水平、产出处于自然水平时，实际利率等于______。","options":["名义利率","目标通胀率","自然利率","当前通胀率"]},"topics":["dad-das"]},{"num":20,"type":"mc","question":"According to the monetary policy rule, the central bank sets the nominal interest rate so that the real interest rate increases when inflation ____ its target or output ____ its natural level.","options":["rises above; rises above","rises above; falls below","falls below; falls below","falls below; rises above"],"answer":"A","images":null,"translation":{"question":"根据货币政策规则，央行设定名义利率，使得当通胀______其目标，或产出______其自然水平时，实际利率上升。","options":["升到高于；升到高于","升到高于；降到低于","降到低于；降到低于","降到低于；升到高于"]},"topics":["dad-das"]},{"num":21,"type":"mc","question":"To follow a monetary policy rule, the central bank raises the nominal interest rate by:","options":["raising the inflation target.","decreasing the money supply.","increasing the GDP gap.","decreasing inflation expectations."],"answer":"B","images":null,"translation":{"question":"为遵循货币政策规则，央行通过______来提高名义利率。","options":["提高通胀目标","减少货币供给","扩大 GDP 缺口","降低通胀预期"]},"topics":["dad-das"]},{"num":22,"type":"mc","question":"In order to achieve the target for the nominal interest rate established by the monetary policy rule, the central bank adjusts:","options":["the inflation rate.","the natural rate of interest.","the money supply.","the inflation target."],"answer":"C","images":null,"translation":{"question":"为了实现货币政策规则所设定的名义利率目标，央行会调整______。","options":["通胀率","自然利率","货币供给","通胀目标"]},"topics":["dad-das"]},{"num":23,"type":"mc","question":"The monetary policy rule specified in the dynamic model of aggregate demand and aggregate supply indicates that the central bank adjusts interest rates in response to fluctuations in:","options":["inflation expectations.","money supply and money demand.","inflation and output.","nominal and real exchange rates."],"answer":"C","images":null,"translation":{"question":"动态总需求与动态总供给模型所设定的货币政策规则表明，央行会根据______的波动来调整利率。","options":["通胀预期","货币供给与货币需求","通胀与产出","名义与实际汇率"]},"topics":["dad-das"]},{"num":24,"type":"mc","question":"John Taylor's rule for setting the federal funds rate proposes increasing the nominal federal funds rate as inflation _____ and the GDP gap _____.","options":["increases; increases","increases; decreases","decreases; increases","decreases; decreases"],"answer":"A","images":null,"translation":{"question":"约翰·泰勒设定联邦基金利率的规则提出：当通胀______且 GDP 缺口______时，应提高名义联邦基金利率。","options":["上升；扩大","上升；缩小","下降；扩大","下降；缩小"]},"topics":["dad-das"]},{"num":25,"type":"mc","question":"According to the Taylor rule, when real GDP is below its natural level, the nominal federal funds rate should be _____, and when inflation exceeds 2 percent, the nominal federal funds rate should be _____.","options":["raised; raised","raised; lowered","lowered; raised","lowered; lowered"],"answer":"C","images":null,"translation":{"question":"根据泰勒规则，当实际 GDP 低于其自然水平时，名义联邦基金利率应被______；当通胀超过 2% 时，名义联邦基金利率应被______。","options":["上调；上调","上调；下调","下调；上调","下调；下调"]},"topics":["dad-das"]},{"num":26,"type":"mc","question":"All of the following are endogenous variables in the dynamic model of aggregate demand and aggregate supply except:","options":["Yt, output","pt* the central bank's inflation target","rt, the real interest rate","Etpt + 1, expected inflation"],"answer":"B","images":null,"translation":{"question":"以下都是动态总需求与动态总供给模型中的内生变量，除了：","options":["Yt（产出）","pt*（央行的通胀目标）","rt（实际利率）","Etpt + 1（预期通胀率）"]},"topics":["dad-das"]},{"num":27,"type":"mc","question":"Which of the following is an exogenous variable in the dynamic model of aggregate demand and aggregate supply?","options":["Etpt + 1, expected inflation","rt, the real interest rate","pt, inflation","ut, supply shock"],"answer":"D","images":null,"translation":{"question":"以下哪一个是动态总需求与动态总供给模型中的外生变量？","options":["Etpt + 1（预期通胀率）","rt（实际利率）","pt（通胀率）","ut（供给冲击）"]},"topics":["dad-das"]},{"num":28,"type":"mc","question":"Which of the following is an endogenous variable in the dynamic model of aggregate demand and aggregate supply?","options":["pt, inflation","pt* the central bank's inflation target","r, the natural rate of interest","pt – 1, the previous period's inflation"],"answer":"A","images":null,"translation":{"question":"以下哪一个是动态总需求与动态总供给模型中的内生变量？","options":["pt（通胀率）","pt*（央行的通胀目标）","r（自然利率）","pt – 1（上一期的通胀率）"]},"topics":["dad-das"]},{"num":29,"type":"mc","question":"Long-run equilibrium occurs in the dynamic model of aggregate demand and aggregate supply when:","options":["dynamic aggregate demand equals dynamic aggregate supply.","there are no shocks and inflation is stable.","the demand shock equals the supply shock.","the nominal interest rate equals the real interest rate."],"answer":"B","images":null,"translation":{"question":"在动态总需求与动态总供给模型中，当______时，实现长期均衡。","options":["动态总需求等于动态总供给","没有冲击且通胀稳定","需求冲击等于供给冲击","名义利率等于实际利率"]},"topics":["dad-das"]},{"num":30,"type":"mc","question":"At long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, the nominal interest rate it equals all of the following except:","options":["r + pt","rt + pt","r + Etpt + 1","r + rt"],"answer":"D","images":null,"translation":{"question":"在动态总需求与动态总供给模型的长期均衡下，名义利率 it 等于以下所有各项，除了：","options":["r + pt","rt + pt","r + Etpt + 1","r + rt"]},"topics":["dad-das"]},{"num":31,"type":"mc","question":"At long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, the demand and supply shocks et and ut equal _____, and current inflation pt equals _____.","options":["0; 0","0; pt – 1","pt; 0","r"],"answer":"B","images":null,"translation":{"question":"在动态总需求与动态总供给模型的长期均衡下，需求冲击 et 和供给冲击 ut 等于______，当前通胀 pt 等于______。","options":["0；0","0；pt – 1","pt；0","r"]},"topics":["dad-das"]},{"num":32,"type":"mc","question":"That output Yt and the real interest rate rt do not depend on the central bank's inflation target in long-run equilibrium in the dynamic model of aggregate demand and aggregate supply demonstrates:","options":["monetary neutrality.","an impulse response function.","adaptive expectations.","Taylor's principle."],"answer":"A","images":null,"translation":{"question":"在动态总需求与动态总供给模型的长期均衡中，产出 Yt 和实际利率 rt 不依赖于央行的通胀目标，这一点证明了：","options":["货币中性","脉冲响应函数","适应性预期","泰勒原理"]},"topics":["dad-das"]},{"num":33,"type":"mc","question":"Of the five endogenous variables in the dynamic model of aggregate demand and aggregate supply, which two real variables do not depend on monetary policy in long-run equilibrium?","options":["Yt and pt","it and rt","Etpt + 1 and pt","Yt and rt"],"answer":"D","images":null,"translation":{"question":"在动态总需求与动态总供给模型的五个内生变量中，哪两个实际变量在长期均衡下不依赖于货币政策？","options":["Yt 和 pt","it 和 rt","Etpt + 1 和 pt","Yt 和 rt"]},"topics":["dad-das"]},{"num":34,"type":"mc","question":"Of the five endogenous variables in the dynamic model of aggregate demand and aggregate supply, which are the nominal variables that will change in long-run equilibrium if the central bank changes its inflation target?","options":["Yt, rt, and it","Yt, it, and Etpt + 1","pt, it, and Etpt + 1","rt, pt, and it"],"answer":"C","images":null,"translation":{"question":"在动态总需求与动态总供给模型的五个内生变量中，如果央行改变其通胀目标，哪些名义变量会在长期均衡中发生变化？","options":["Yt、rt 和 it","Yt、it 和 Etpt + 1","pt、it 和 Etpt + 1","rt、pt 和 it"]},"topics":["dad-das"]},{"num":35,"type":"mc","question":"At long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, which variables will equal the central bank's target rate of inflation?","options":["the current inflation rate, but not the expected inflation rate","the expected inflation rate, but not the current inflation rate","both the current and expected rates of inflation","neither the current nor the expected rates of inflation"],"answer":"C","images":null,"translation":{"question":"在动态总需求与动态总供给模型的长期均衡下，哪些变量会等于央行的目标通胀率？","options":["当前通胀率，而非预期通胀率","预期通胀率，而非当前通胀率","当前通胀率和预期通胀率两者","当前通胀率和预期通胀率两者都不是"]},"topics":["dad-das"]},{"num":36,"type":"mc","question":"The dynamic aggregate supply curve shows the short-run relation between:","options":["the natural rate of output and inflation.","the natural rate of output and expected rate of inflation.","output and inflation.","output and the natural rate of interest."],"answer":"C","images":null,"translation":{"question":"动态总供给曲线显示的是______之间的短期关系。","options":["自然产出水平与通胀","自然产出水平与预期通胀率","产出与通胀","产出与自然利率"]},"topics":["dad-das"]},{"num":37,"type":"mc","question":"The dynamic aggregate supply curve is derived from:","options":["the Fisher equation and adaptive expectations.","the Phillips curve and adaptive expectations.","the monetary policy rule and the Fisher equation.","the Phillips curve and the monetary policy rule."],"answer":"B","images":null,"translation":{"question":"动态总供给曲线是由______推导出来的。","options":["费雪方程与适应性预期","菲利普斯曲线与适应性预期","货币政策规则与费雪方程","菲利普斯曲线与货币政策规则"]},"topics":["dad-das"]},{"num":38,"type":"mc","question":"The dynamic aggregate supply curve illustrates a short-run _____ relationship between output and _____.","options":["positive; inflation","positive; the price level","negative; inflation","negative; the price level"],"answer":"A","images":null,"translation":{"question":"动态总供给曲线表明产出与______之间存在短期______关系。","options":["正；通胀","正；价格水平","负；通胀","负；价格水平"]},"topics":["dad-das"]},{"num":39,"type":"mc","question":"The upward slope of the dynamic aggregate supply curve indicates that, holding other factors constant, high levels of economic activity are associated with:","options":["the natural level of output.","the inflation target.","positive supply shocks.","high inflation."],"answer":"D","images":null,"translation":{"question":"动态总供给曲线向上倾斜表明，在其他因素不变的情况下，较高的经济活动水平与______相关联。","options":["自然产出水平","通胀目标","正向供给冲击","高通胀"]},"topics":["dad-das"]},{"num":40,"type":"mc","question":"The dynamic aggregate supply curve will shift if any of the following changes except the:","options":["current inflation rate.","past inflation rate.","natural level of output.","supply shock."],"answer":"A","images":null,"translation":{"question":"动态总供给曲线会在以下任一因素发生变化时移动，除了：","options":["当前通胀率","过去的通胀率","自然产出水平","供给冲击"]},"topics":["dad-das"]},{"num":41,"type":"mc","question":"The dynamic aggregate demand curve is derived from each of the following equations of the model of aggregate demand and aggregate supply except:","options":["the Fisher equation.","the Phillips curve.","adaptive expectations.","the monetary policy rule."],"answer":"B","images":null,"translation":{"question":"动态总需求曲线是由总需求与总供给模型的以下各方程推导出来的，除了：","options":["费雪方程","菲利普斯曲线","适应性预期","货币政策规则"]},"topics":["dad-das"]},{"num":42,"type":"mc","question":"The dynamic aggregate demand curve illustrates the _____ relationship between the quantity of output in the short run and _____.","options":["positive; inflation","positive; the price level","negative; inflation","negative; the price level"],"answer":"C","images":null,"translation":{"question":"动态总需求曲线表明短期产出数量与______之间存在______关系。","options":["正；通胀","正；价格水平","负；通胀","负；价格水平"]},"topics":["dad-das"]},{"num":43,"type":"mc","question":"The dynamic aggregate demand curve will shift if any of the following changes except the:","options":["current inflation rate.","inflation target.","natural level of output.","demand shock."],"answer":"A","images":null,"translation":{"question":"动态总需求曲线会在以下任一因素发生变化时移动，除了：","options":["当前通胀率","通胀目标","自然产出水平","需求冲击"]},"topics":["dad-das"]},{"num":44,"type":"mc","question":"Which of the following is not held constant along a dynamic aggregate demand curve?","options":["the inflation target","the natural rate of output","the demand shock","the money supply"],"answer":"D","images":null,"translation":{"question":"沿动态总需求曲线，以下哪一项不是保持不变的？","options":["通胀目标","自然产出水平","需求冲击","货币供给"]},"topics":["dad-das"]},{"num":45,"type":"mc","question":"The dynamic aggregate demand curve is downward sloping because as inflation falls, the central bank reduces the nominal interest rate by more than the fall in the inflation rate, which _____the real interest rate and _____ the quantity of goods and services demanded.","options":["decreases; decreases","decreases; increases","increases; increases","increases; decreases"],"answer":"B","images":null,"translation":{"question":"动态总需求曲线向下倾斜，是因为当通胀下降时，央行降低名义利率的幅度超过通胀率的降幅，这会______实际利率并______所需求的商品和服务的数量。","options":["降低；减少","降低；增加","提高；增加","提高；减少"]},"topics":["dad-das"]},{"num":46,"type":"mc","question":"According to the monetary policy rule (assuming qp > 0) when inflation increases, the central bank increases the nominal interest rate by _____ the increase in the rate of inflation, which _____ the real interest rate.","options":["more than; increases","less than; decreases","an amount equal to; does not change","less than; increases"],"answer":"A","images":null,"translation":{"question":"根据货币政策规则（假设 qp > 0），当通胀上升时，央行提高名义利率的幅度______通胀率的升幅，这会______实际利率。","options":["大于；提高","小于；降低","等于；不改变","小于；提高"]},"topics":["dad-das"]},{"num":47,"type":"mc","question":"The dynamic aggregate demand curve will shift to the right if there is a:","options":["tax cut.","cut in government spending.","decrease in the money supply.","cut in oil prices when the cartel falls apart."],"answer":"A","images":null,"translation":{"question":"如果出现______，动态总需求曲线将向右移动。","options":["减税","削减政府支出","货币供给减少","卡特尔瓦解导致油价下跌"]},"topics":["dad-das"]},{"num":48,"type":"mc","question":"When the central bank lowers its target inflation rate, it _____ the nominal and real interest rate, which shifts the dynamic aggregate demand curve to the _____.","options":["lowers; right","lowers; left","raises; right","raises; left"],"answer":"D","images":null,"translation":{"question":"当央行下调其目标通胀率时，它会______名义利率和实际利率，从而使动态总需求曲线向______移动。","options":["降低；右","降低；左","提高；右","提高；左"]},"topics":["dad-das"]},{"num":49,"type":"mc","question":"To reduce the demand for goods and services, the central bank will ____ its target inflation rate and _____ nominal and real interest rates.","options":["reduce; decrease","reduce; increase","raise; decrease","raise; increase"],"answer":"B","images":null,"translation":{"question":"为减少对商品和服务的需求，央行会______其目标通胀率，并______名义利率和实际利率。","options":["降低；降低","降低；提高","提高；降低","提高；提高"]},"topics":["dad-das"]},{"num":50,"type":"mc","question":"The short-run equilibrium in the dynamic model of aggregate demand and aggregate supply is determined by the intersection of the:","options":["DADt and DASt – 1.","DADt and DASt.","Yt and DASt.","DADt – 1 and Yt."],"answer":"B","images":null,"translation":{"question":"动态总需求与动态总供给模型中的短期均衡由______的交点决定。","options":["DADt 与 DASt – 1","DADt 与 DASt","Yt 与 DASt","DADt – 1 与 Yt"]},"topics":["dad-das"]},{"num":51,"type":"mc","question":"The short-run equilibrium in the dynamic model of aggregate demand and supply determines the:","options":["inflation rate and inflation target.","real interest rate and natural level of output.","level of output and inflation rate.","natural level of output and level of output."],"answer":"C","images":null,"translation":{"question":"动态总需求与动态总供给模型中的短期均衡决定了：","options":["通胀率与通胀目标","实际利率与自然产出水平","产出水平与通胀率","自然产出水平与产出水平"]},"topics":["dad-das"]},{"num":52,"type":"mc","question":"In the dynamic model of aggregate demand and aggregate supply, one period in time is connected to the next period through:","options":["the monetary policy rule.","demand shocks.","inflation expectation.","the natural level of output."],"answer":"C","images":null,"translation":{"question":"在动态总需求与动态总供给模型中，一个时期通过______与下一个时期相连接。","options":["货币政策规则","需求冲击","通胀预期","自然产出水平"]},"topics":["dad-das"]},{"num":53,"type":"mc","question":"In the dynamic model of aggregate demand and aggregate supply, changes in the natural level of output change:","options":["the DAD curve but not the DAS curve.","the DAS curve but not the DAD curve.","both the DAD curve and the DAS curve.","neither the DAD nor the DAS curve."],"answer":"C","images":null,"translation":{"question":"在动态总需求与动态总供给模型中，自然产出水平的变化会改变：","options":["DAD 曲线，但不改变 DAS 曲线","DAS 曲线，但不改变 DAD 曲线","DAD 曲线和 DAS 曲线两者","DAD 曲线和 DAS 曲线都不改变"]},"topics":["dad-das"]},{"num":54,"type":"mc","question":"In the dynamic model of aggregate demand and aggregate supply, increases in the natural level of output lead to _____ in output and ______ in inflation.","options":["increases; increases","increases; no change","no change; increases","no change; no change"],"answer":"B","images":null,"translation":{"question":"在动态总需求与动态总供给模型中，自然产出水平的提高会导致产出______、通胀______。","options":["增加；上升","增加；不变","不变；上升","不变；不变"]},"topics":["dad-das"]},{"num":55,"type":"mc","question":"Increases in the natural level of output allow the economy to produce _____ goods and services and make people want to buy _____ goods and services.","options":["fewer; fewer","fewer; more","more; more","more; fewer"],"answer":"C","images":null,"translation":{"question":"自然产出水平的提高使经济能够生产______的商品和服务，并让人们想要购买______的商品和服务。","options":["更少；更少","更少；更多","更多；更多","更多；更少"]},"topics":["dad-das"]},{"num":56,"type":"mc","question":"Beginning at long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, in the period in which a positive supply shock occurs, the DAS curve _____, and the DAD curve _____.","options":["shifts upward; shifts rightward","shifts upward; does not shift","does not shift; does not shift","shifts downward; shifts leftward"],"answer":"B","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，在正向供给冲击发生的那一期，DAS 曲线______，而 DAD 曲线______。","options":["向上移动；向右移动","向上移动；不移动","不移动；不移动","向下移动；向左移动"]},"topics":["dad-das"]},{"num":57,"type":"mc","question":"Starting from long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, a one-period positive supply shock causes output to:","options":["remain above the natural level for only one period.","remain above the natural level for more than one period.","remain below the natural level for only one period.","remain below the natural level for more than one period."],"answer":"D","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，一个为期一期的正向供给冲击会使产出：","options":["仅在自然水平之上保持一期","在自然水平之上保持多期","仅在自然水平之下保持一期","在自然水平之下保持多期"]},"topics":["dad-das"]},{"num":58,"type":"mc","question":"Starting from long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, output immediately decreases as a result of a one-period positive supply shock because:","options":["the central bank raises the nominal and real interest rates in response to the increase in inflation.","the higher prices generate a negative demand shock that reduces output.","the natural level of output falls in response to the increase in inflation.","the central bank increases the target rate of inflation in response to the increase in inflation."],"answer":"A","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，一个为期一期的正向供给冲击使产出立即下降，是因为：","options":["央行为应对通胀上升而提高名义利率和实际利率","较高的价格产生减少产出的负向需求冲击","自然产出水平因通胀上升而下降","央行为应对通胀上升而提高目标通胀率"]},"topics":["dad-das"]},{"num":59,"type":"mc","question":"Graphs that illustrate the time paths of endogenous variables when a shock hits the economy are called:","options":["monetary policy paths.","dynamic shock figures.","impulse response functions.","endogenous growth models."],"answer":"C","images":null,"translation":{"question":"当冲击冲击经济时，说明内生变量时间路径的图形被称为：","options":["货币政策路径","动态冲击图","脉冲响应函数","内生增长模型"]},"topics":["dad-das"]},{"num":60,"type":"mc","question":"Beginning at long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, in the first period of a four-period positive demand shock, the DAS curve _____, and the DAD curve _____.","options":["shifts upward; shifts rightward","does not shift; shifts rightward","does not shift; does not shift","shifts downward; shifts leftward"],"answer":"B","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，在一个为期四期的正向需求冲击的第一期，DAS 曲线______，而 DAD 曲线______。","options":["向上移动；向右移动","不移动；向右移动","不移动；不移动","向下移动；向左移动"]},"topics":["dad-das"]},{"num":61,"type":"mc","question":"Beginning at long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, in the first period of a multi-period positive demand shock, output _____, and inflation _____.","options":["increases; increases","increases; decreases","decreases; decreases","decreases; increases"],"answer":"A","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，在一个多期正向需求冲击的第一期，产出______，通胀______。","options":["增加；上升","增加；下降","减少；下降","减少；上升"]},"topics":["dad-das"]},{"num":62,"type":"mc","question":"Beginning at long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, in the periods after a multiperiod positive demand shock occurs, the DAS shifts upward because:","options":["the central bank increases the target rate of inflation in response to higher rates of inflation.","the deviation of output from the natural level of output increases as result of higher rates of inflation.","higher rates of inflation generate positive supply shocks.","expectations of inflation increase as a result of higher inflation in previous periods."],"answer":"D","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，在多期正向需求冲击发生之后的各期，DAS 曲线向上移动，是因为：","options":["央行为应对更高的通胀率而提高目标通胀率","产出对自然产出水平的偏离因更高的通胀率而增大","更高的通胀率产生正向供给冲击","由于前几期通胀更高，通胀预期上升"]},"topics":["dad-das"]},{"num":63,"type":"mc","question":"Starting from long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, a five-period positive demand shock causes output to _____ until returning to the natural level in the long run.","options":["remain continuously above the natural level of output","move above and then below the natural level of output","remain continuously below the natural level of output","move below and then above the natural level of output"],"answer":"B","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，一个为期五期的正向需求冲击会使产出______，直到长期中回到自然水平。","options":["持续保持在自然产出水平之上","先移到自然产出水平之上，然后再移到其之下","持续保持在自然产出水平之下","先移到自然产出水平之下，然后再移到其之上"]},"topics":["dad-das"]},{"num":64,"type":"mc","question":"Starting from long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, a temporary five-period tax increase causes output to _____ returning to the natural level in the long run.","options":["remain continuously above the natural level of output until","move above and then below the natural level of output until","remain continuously below the natural level of output until","move below and then above the natural level of output before"],"answer":"D","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，一个为期五期的暂时性增税会使产出______，然后在长期中回到自然水平。","options":["持续保持在自然产出水平之上，直到","先移到自然产出水平之上，然后再移到其之下，直到","持续保持在自然产出水平之下，直到","先移到自然产出水平之下，然后再移到其之上，之后"]},"topics":["dad-das"]},{"num":65,"type":"mc","question":"Beginning at long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, if the central bank permanently reduces its inflation target, then in the first period after the policy change, the DAS curve _____, and the DAD curve _____.","options":["shifts upward; shifts rightward","does not shift; shifts leftward","does not shift; does not shift","shifts downward; shifts leftward"],"answer":"B","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，如果央行永久性下调其通胀目标，那么在政策变化后的第一期，DAS 曲线______，而 DAD 曲线______。","options":["向上移动；向右移动","不移动；向左移动","不移动；不移动","向下移动；向左移动"]},"topics":["dad-das"]},{"num":66,"type":"mc","question":"Beginning at long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, if the central bank permanently reduces its inflation target, then in the initial period after the policy change, output _____, and inflation _____.","options":["increases; increases","increases; decreases","decreases; decreases","decreases; increases"],"answer":"C","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，如果央行永久性下调其通胀目标，那么在政策变化后的最初一期，产出______，通胀______。","options":["增加；上升","增加；下降","减少；下降","减少；上升"]},"topics":["dad-das"]},{"num":67,"type":"mc","question":"Beginning at long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, in the periods after a permanent reduction in the central bank's inflation target, the DAS shifts downward because:","options":["the natural level of output increases in response to the lower rates of inflation.","the deviation of output from the natural level of output increases as a result of lower rates of inflation.","lower rates of inflation generate negative supply shocks.","expectations of inflation decrease as a result of lower inflation in previous periods."],"answer":"D","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，在央行永久性下调通胀目标之后的各期，DAS 曲线向下移动，是因为：","options":["自然产出水平因更低的通胀率而上升","产出对自然产出水平的偏离因更低的通胀率而增大","更低的通胀率产生负向供给冲击","由于前几期通胀更低，通胀预期下降"]},"topics":["dad-das"]},{"num":68,"type":"mc","question":"Starting from long-run equilibrium in the dynamic model of aggregate demand and aggregate supply, a permanent reduction in the central bank's inflation target causes the nominal interest rate to:","options":["decline continuously until reaching a lower level in the long run.","increase initially and then decline until reaching a lower level in the long run.","decline immediately to a lower level in the long run.","fall below and then rise continuously to long-run level below the initial level."],"answer":"B","images":null,"translation":{"question":"从动态总需求与动态总供给模型的长期均衡出发，央行永久性下调通胀目标会使名义利率：","options":["持续下降，直到长期中达到一个更低的水平","先上升、然后下降，直到长期中达到一个更低的水平","立即下降到一个更低的长期水平","先降到更低水平之下，然后持续上升到一个低于初始水平的长期水平"]},"topics":["dad-das"]},{"num":69,"type":"mc","question":"In the dynamic model of aggregate demand and aggregate supply, if the central bank chooses a large value of qp and a small value of qY, then the DAD curve will be relatively _____, and supply shocks will have relatively ____ impacts on inflation than output.","options":["flat; larger","flat; smaller","steep; larger","steep; smaller"],"answer":"B","images":null,"translation":{"question":"在动态总需求与动态总供给模型中，如果央行选择较大的 qp 值和较小的 qY 值，那么 DAD 曲线将相对______，供给冲击对通胀的影响相对______于对产出的影响。","options":["平坦；更大","平坦；更小","陡峭；更大","陡峭；更小"]},"topics":["dad-das"]},{"num":70,"type":"mc","question":"A central bank that chooses a small value of qp and a large value of qY is choosing less _____ at the expense of more _____.","options":["inflation; output","output; inflation","inflation variability; output variability","output variability; inflation variability"],"answer":"D","images":null,"translation":{"question":"选择较小 qp 值和较大 qY 值的央行，是选择了更少的______，而代价是更多的______。","options":["通胀；产出","产出；通胀","通胀波动性；产出波动性","产出波动性；通胀波动性"]},"topics":["dad-das"]},{"num":71,"type":"mc","question":"A central bank that chooses a large value of qp and a small value of qY is choosing to obtain less _____ at the expense of more _____.","options":["inflation; output","output; inflation","inflation variability; output variability","output variability; inflation variability Equation: Monetary Policy Rule it = pt + r + qp(pt – p*t) + qY(Yt – )"],"answer":"C","images":null,"translation":{"question":"选择较大 qp 值和较小 qY 值的央行，是为了获得更少的______，而代价是更多的______。","options":["通胀；产出","产出；通胀","通胀波动性；产出波动性","产出波动性；通胀波动性"]},"topics":["dad-das"]},{"num":72,"type":"mc","question":"Equation: Monetary Policy Rule it = pt + r + qp(pt – p*t) + qY(Yt – t) Given the monetary policy rule of the dynamic model of aggregate demand and aggregate supply, if the inflation rate increases by 1 percentage point, by how much does the nominal interest increase?","options":["1","1 + r","1 + qp",""],"answer":"C","images":null,"translation":{"question":"方程：货币政策规则 it = pt + r + qp(pt – p*t) + qY(Yt – t)。给定动态总需求与动态总供给模型的货币政策规则，如果通胀率上升 1 个百分点，名义利率会上升多少？","options":["1","1 + r","1 + qp",""]},"topics":["dad-das"]},{"num":73,"type":"mc","question":"According to the Taylor principle, for inflation to be stable, the central bank must respond to an increase in inflation with ____ increase in the nominal interest rate.","options":["no","an equal","a greater","a smaller"],"answer":"C","images":null,"translation":{"question":"根据泰勒原理，为使通胀保持稳定，央行必须以______来应对通胀上升。","options":["不调整名义利率","幅度相等的名义利率上调","幅度更大的名义利率上调","幅度更小的名义利率上调"]},"topics":["dad-das"]},{"num":74,"type":"sa","question":"Use the model of dynamic aggregate demand and aggregate supply to graphically illustrate the impact of a temporary four-period increase in taxes (a four-period negative demand shock) on output and inflation when the economy is initially at long-run equilibrium. Explain the time path of output and inflation in words.","options":null,"answer":null,"images":null,"translation":{"question":"用动态总需求与动态总供给模型，图示说明在经济最初处于长期均衡时，为期四个时期的暂时性增税（一个为期四期的负向需求冲击）对产出和通胀的影响。用文字说明产出和通胀的时间路径。","options":null},"topics":["dad-das"],"answer_ref":"图（DAD-DAS，横轴Y纵轴π）：临时增税→DAD 左移（仅4期）。路径：冲击当期产出骤降、缺口为负；通胀随后逐期下滑；增税存续期内产出维持在自然率之下；第5期税收复原，DAD 回移——产出跳升回自然率附近，但因前期通胀已低，预期通胀偏低使产出小幅过冲，随后π与Y围绕目标小幅振荡收敛。文字：临时需求收缩使通胀下行滞后、产出先降后升。"},{"num":75,"type":"sa","question":"Use the model of dynamic aggregate demand and aggregate supply to graphically illustrate the impact on output and inflation of an exceptional weather pattern that results in a one-period glut of food worldwide that reduces food prices (a one-period negative supply shock) when the economy is initially at long-run equilibrium. Explain the time path of output and inflation in words.","options":null,"answer":null,"images":null,"translation":{"question":"用动态总需求与动态总供给模型，图示说明在经济最初处于长期均衡时，导致全球粮食供应过剩一期、从而压低食品价格的异常天气模式（一个为期一期的负向供给冲击）对产出和通胀的影响。用文字说明产出和通胀的时间路径。","options":null},"topics":["dad-das"],"answer_ref":"图：全球性丰收使食品价格大跌——一期正向供给冲击，DAS 右移一期。当期：通胀下降、产出升至自然率之上；下一期 DAS 回位，但偏低的预期通胀与惯性使产出略低于自然率、通胀略高于目标；随后二者交替收敛回目标。路径呈\"π↓Y↑→π↑Y↓\"的交替波形。"},{"num":76,"type":"sa","question":"Use the model of dynamic aggregate demand and aggregate supply to graphically illustrate the impact of a permanent increase in the central bank's inflation target when the economy is initially at long-run equilibrium. Explain the time path of output and inflation in words.","options":null,"answer":null,"images":null,"translation":{"question":"用动态总需求与动态总供给模型，图示说明在经济最初处于长期均衡时，央行永久性提高其通胀目标的影响。用文字说明产出和通胀的时间路径。","options":null},"topics":["dad-das"],"answer_ref":"图：通胀目标永久上调→政策规则截距上移→DAD 永久右移。路径：当期产出升至自然率以上、通胀开始爬升；由于目标改变是永久的，经济逐步过渡——产出逐渐回落至自然率，通胀逐渐收敛到更高目标。没有振荡，是单调过渡：短期小繁荣换永久更高通胀。"},{"num":77,"type":"sa","question":"Central Bank A conducts monetary policy according to the following monetary policy rule: i = p + 2.0 + 0.90 (p – 2.0) + 0.10 (Y – 100), and Central Bank B conducts monetary according to the following monetary policy rule: i = p + 2.0 + 0.10 (p – 2.0) +0 .90 (Y – 100), where i is the nominal interest rate measured in percent, p is the inflation rate measured in percent, and Y is output measured as a percentage of the natural level of output. The economies of the two countries are otherwise identical and operate as described by the dynamic model of aggregate demand and aggregate supply. a. In which country will the dynamic aggregate demand curve be steeper? Explain. b. If a positive supply shock of the same magnitude hits both countries, which country will experience the greatest variability in output? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"央行 A 按照以下货币政策规则实施货币政策：i = p + 2.0 + 0.90 (p – 2.0) + 0.10 (Y – 100)；央行 B 按照以下货币政策规则实施货币政策：i = p + 2.0 + 0.10 (p – 2.0) + 0.90 (Y – 100)。其中 i 为以百分比衡量的名义利率，p 为以百分比衡量的通胀率，Y 为以自然产出水平的百分比衡量的产出。两国经济在其他方面完全相同，并按动态总需求与动态总供给模型运行。a. 哪个国家的动态总需求曲线更陡峭？请解释。b. 如果同等幅度的正向供给冲击同时冲击两国，哪个国家的产出波动性最大？请解释。","options":null},"topics":["dad-das"],"answer_ref":"两行规则仅在响应系数上有别：A 行对通胀响应0.90、对产出缺口0.10——典型的\"通胀鹰派\"：通胀每升1点，名义利率升0.9点（接近满足泰勒原则），实际利率随通胀上升，通胀得以稳定，但产出缺口放任较多。B 行对产出响应0.90、对通胀0.10——\"就业优先\"：产出稳定良好，但通胀响应不足一一对应，实际利率随通胀下降，通胀易脱锚。A 的设计更稳健。"},{"num":78,"type":"sa","question":"Use the model of dynamic aggregate demand and aggregate supply to compare the time paths of output and inflation in response to a one-period positive demand shock versus a one-period positive supply shock.","options":null,"answer":null,"images":null,"translation":{"question":"用动态总需求与动态总供给模型，比较面对一个为期一期的正向需求冲击与一个为期一期的正向供给冲击时，产出和通胀的时间路径。","options":null},"topics":["dad-das"],"answer_ref":"一期正向需求冲击（DAD 右移一期）：当期 π 与 Y 同升；之后惯性使 π 继续偏高、预期通胀上移推高 DAS，产出回落并在随后一期略低于自然率，再振荡收敛。一期正向供给冲击（DAS 右移一期）：当期 π↓ 而 Y↑——方向相反；下一期 DAS 回位，π 反弹偏高、Y 略低于自然率，同样振荡收敛但相位相反。核心差别：需求冲击使 π、Y 同向变动，供给冲击使其反向变动。"},{"num":79,"type":"sa","question":"How does the AD–AS model take a novel approach to explaining money supply effects on economic fluctuations?","options":null,"answer":null,"images":null,"translation":{"question":"AD–AS 模型如何以一种新颖的方法解释货币供给对经济波动的影响？","options":null},"topics":["dad-das"],"answer_ref":"新颖之处：货币不再以外生增长率直接进入模型，而是经由货币政策规则——央行根据通胀与产出缺口设定名义利率（DAD 的推导核心），再通过费雪方程与实际利率挂钩。货币供给的效应被内生化、规则化：是\"央行对冲击的反应\"而非\"货币数量本身\"在驱动波动，这是现代货币政策分析的框架。"},{"num":80,"type":"sa","question":"What is the difference between the ex ante real interest rate and the real interest rate? Explain the Fisher equation used by the AD–AS model in light of this difference.","options":null,"answer":null,"images":null,"translation":{"question":"事前实际利率与实际利率有什么区别？结合这一区别，解释 AD–AS 模型所用的费雪方程。","options":null},"topics":["dad-das"],"answer_ref":"事前实际利率 r = i − πe（用预期通胀计算，决策时已知）；事后（ex post）实际利率 = i − π（用实际通胀，事后才知）；两者之差即通胀预测误差。模型采用费雪方程 r = i − πe：消费投资决策在通胀揭晓前做出，取决于预期实际利率。这使预期成为传导货币政策的枢纽。"},{"num":81,"type":"sa","question":"According to the monetary policy rule, under what condition does the real interest rate equal the natural rate of interest? What does the Taylor principle suggest for a monetary policy design?","options":null,"answer":null,"images":null,"translation":{"question":"根据货币政策规则，在什么条件下实际利率等于自然利率？泰勒原理对货币政策设计有何启示？","options":null},"topics":["dad-das"],"answer_ref":"当通胀等于目标且产出等于自然产出时，规则中两个括号项均为零，实际利率等于自然利率。泰勒原则：对通胀的响应系数应大于1——通胀升1点，名义利率升超过1点，使实际利率随通胀上升，从而压制需求、锚定通胀；系数小于1则经济不稳定（通胀自我实现）。"},{"num":82,"type":"sa","question":"Illustrate with graphs the dynamic aggregate demand curve (DAD) and dynamic aggregate supply curve (DAS).","options":null,"answer":null,"images":null,"translation":{"question":"用图形说明动态总需求曲线（DAD）和动态总供给曲线（DAS）。","options":null},"topics":["dad-das"],"answer_ref":"DAD：在(π,Y)空间向下倾斜——π↑→央行按规则提高名义利率→实际利率↑→需求与产出↓（由IS曲线+政策规则+费雪方程推出）。DAS：向上倾斜——π↑推高预期通胀与当期价格，产出沿粘性价格供给增加；每期随预期更新而移动。图形：交点为当期均衡，随冲击两线逐期移动。"},{"num":83,"type":"sa","question":"Fill in the blanks: As a dynamic response to a positive supply shock in the short run, the DAS curve shifts (say in period t) ___________ while the DAD curve ___________, causing inflation to ___________ and output to _____________.","options":null,"answer":null,"images":null,"translation":{"question":"填空：作为短期对正向供给冲击的动态反应，（设在第 t 期）DAS 曲线向__________移动，而 DAD 曲线__________，导致通胀__________、产出__________。","options":null},"topics":["dad-das"],"answer_ref":"DAS 右移，DAD 不变，通胀下降，产出上升。（正向供给冲击：短期供给能力扩大，价格走低、产出走高。）"},{"num":84,"type":"sa","question":"What is stagflation? How does it occur as a result of a shock to the aggregate supply curve?","options":null,"answer":null,"images":null,"translation":{"question":"什么是滞胀？它如何因总供给曲线的冲击而产生？","options":null},"topics":["dad-das"],"answer_ref":"滞胀 = 停滞（产出低、失业高）+ 通胀并存。机制：不利供给冲击（油价、工资成本）使 DAS 左移——价格上升的同时产出下降。与需求冲击不同，供给冲击使通胀与产出反向恶化：政策若扩张需求保产出，则通胀更高；若压通胀，则产出更低——两难。"}]},{"num":16,"title":"Alternative Perspectives on Stabilization Policy","questions":[{"num":1,"type":"mc","question":"Economists who view the economy as inherently unstable generally argue that:","options":["stabilization policy is too dangerous to be used.","the economy should be stimulated when it is depressed and slowed when it is overheated.","the economy should be slowed when it is depressed and stimulated when it is overheated.","monetary and fiscal policies should follow rigid rules of constant growth."],"answer":"B","images":null,"translation":{"question":"认为经济本质上不稳定的经济学家通常主张：","options":["稳定化政策太危险，不应使用","经济萧条时应加以刺激，经济过热时应加以抑制","经济萧条时应加以抑制，经济过热时应加以刺激","货币政策和财政政策应遵循恒定增长的僵硬规则"]},"topics":["rules-discretion"]},{"num":2,"type":"mc","question":"Economists who view the economy as naturally stable often argue that:","options":["monetary and fiscal policies should not be used to fine-tune the economy.","the economy should be stimulated when it is depressed and slowed when it is overheated.","the economy should be slowed when it is depressed and stimulated when it is overheated.","economists should act to stimulate or slow the economy on the basis of forecasts in order to assure that the policy actions are timely."],"answer":"A","images":null,"translation":{"question":"认为经济天然稳定的经济学家通常主张：","options":["货币政策和财政政策不应被用来对经济进行微调","经济萧条时应加以刺激，经济过热时应加以抑制","经济萧条时应加以抑制，经济过热时应加以刺激","经济学家应根据预测来刺激或抑制经济，以确保政策行动及时"]},"topics":["rules-discretion"]},{"num":3,"type":"mc","question":"Active economic policy seeks to do all of the following except:","options":["offset fluctuations in real GDP.","use monetary and fiscal policy to shift aggregate demand.","respond to changing economic conditions.","take a hands-off approach to macroeconomic policy."],"answer":"D","images":null,"translation":{"question":"积极的（主动的）经济政策旨在做以下所有事情，除了：","options":["抵消实际 GDP 的波动","运用货币政策和财政政策来移动总需求","对不断变化的经济状况作出反应","对宏观经济政策采取不干预的方式"]},"topics":["rules-discretion"]},{"num":4,"type":"mc","question":"Arguments in favor of passive economic policy include all of the following except:","options":["monetary and fiscal policies work with long and variable lags, which can produce destabilizing results.","economic forecasts have too large a margin of error to be useful in formulating stabilization policy.","recessions do not reduce economic well-being, so using monetary and fiscal policy for stabilization is unnecessary.","the Great Depression could have been avoided if the Federal Reserve had pursued a policy of steady money growth."],"answer":"C","images":null,"translation":{"question":"支持消极（被动）经济政策的论据包括以下所有，除了：","options":["货币政策和财政政策的作用存在长而可变的时滞，可能产生不稳定化的结果","经济预测的误差幅度太大，无法用于制定稳定化政策","衰退不会降低经济福利，因此没有必要运用货币政策和财政政策进行稳定化","如果美联储（Federal Reserve）当初实行稳定的货币增长政策，大萧条本可以避免"]},"topics":["rules-discretion"]},{"num":5,"type":"mc","question":"Arguments in favor of active economic policy include all of the following except:","options":["failing to use monetary and fiscal policy leads to inefficient fluctuations in output and employment.","the Great Depression could have been avoided if the Federal Reserve had pursued a policy of steady money growth.","fluctuations in real GDP have been less severe following World War II than prior to World War I.","failure of policymakers to respond to large contractionary shocks to private spending caused the Great Depression."],"answer":"B","images":null,"translation":{"question":"支持积极经济政策的论据包括以下所有，除了：","options":["不运用货币政策和财政政策会导致产出和就业的无效率波动","如果美联储当初实行稳定的货币增长政策，大萧条本可以避免","第二次世界大战以后实际 GDP 的波动不如第一次世界大战以前那么剧烈","决策者未能对私人支出的巨大收缩性冲击作出反应，导致了大萧条"]},"topics":["rules-discretion"]},{"num":6,"type":"mc","question":"Increasing government spending when the economy is in a recession is an example of:","options":["active monetary policy.","active fiscal policy.","passive monetary policy.","passive fiscal policy."],"answer":"B","images":null,"translation":{"question":"经济处于衰退时增加政府支出，是______的一个例子。","options":["积极货币政策","积极财政政策","消极货币政策","消极财政政策"]},"topics":["rules-discretion"]},{"num":7,"type":"mc","question":"The lags involved in implementing monetary and fiscal policy are:","options":["short and predictable.","long and predictable.","short and variable.","long and variable."],"answer":"D","images":null,"translation":{"question":"实施货币政策和财政政策所涉及的时滞是：","options":["短而可预测的","长而可预测的","短而可变的","长而可变的"]},"topics":["policy-lags"]},{"num":8,"type":"mc","question":"The time between a shock to the economy and the policy action responding to that shock is called the:","options":["automatic stabilizer.","time inconsistency of policy.","inside lag.","outside lag."],"answer":"C","images":null,"translation":{"question":"从经济受到冲击到对此冲击作出反应的政策行动之间的时间被称为：","options":["自动稳定器","政策的时间不一致性","内在时滞（inside lag）","外在时滞（outside lag）"]},"topics":["policy-lags"]},{"num":9,"type":"mc","question":"The time between a policy action and its influence on the economy is called the:","options":["automatic stabilizer.","time inconsistency of policy.","inside lag.","outside lag."],"answer":"D","images":null,"translation":{"question":"从政策行动到其影响经济之间的时间被称为：","options":["自动稳定器","政策的时间不一致性","内在时滞（inside lag）","外在时滞（outside lag）"]},"topics":["policy-lags"]},{"num":10,"type":"mc","question":"Fiscal policy has a relatively long ______ lag, and monetary policy has a relatively long ______ lag.","options":["inside; outside","outside; inside","inside; inside","outside; outside"],"answer":"A","images":null,"translation":{"question":"财政政策有相对较长的______时滞，而货币政策有相对较长的______时滞。","options":["内在；外在","外在；内在","内在；内在","外在；外在"]},"topics":["policy-lags"]},{"num":11,"type":"mc","question":"The lag between the time that economic stimulus is needed and the time that a tax cut is passed by Congress is an example of a:","options":["fiscal inside lag.","fiscal outside lag.","monetary inside lag.","monetary outside lag."],"answer":"A","images":null,"translation":{"question":"从需要经济刺激到国会（Congress）通过减税之间的时滞，是______的一个例子。","options":["财政的内在时滞","财政的外在时滞","货币的内在时滞","货币的外在时滞"]},"topics":["policy-lags"]},{"num":12,"type":"mc","question":"The lag between the time that the money supply is increased and the time that investment expenditures increase is an example of a:","options":["fiscal inside lag.","fiscal outside lag.","monetary inside lag.","monetary outside lag."],"answer":"D","images":null,"translation":{"question":"从货币供给增加到投资支出增加之间的时滞，是______的一个例子。","options":["财政的内在时滞","财政的外在时滞","货币的内在时滞","货币的外在时滞"]},"topics":["policy-lags"]},{"num":13,"type":"mc","question":"The time between when a recession begins and when the central bank lowers interest rates to stimulate aggregate demand is an example of an:","options":["inside lag of monetary policy.","outside lag of monetary policy.","inside lag of fiscal policy.","outside lag of fiscal policy."],"answer":"A","images":null,"translation":{"question":"从衰退开始到央行降低利率以刺激总需求之间的时间，是______的一个例子。","options":["货币政策的内在时滞","货币政策的外在时滞","财政政策的内在时滞","财政政策的外在时滞"]},"topics":["policy-lags"]},{"num":14,"type":"mc","question":"The time between when government spending increases and when aggregate demand starts to increase is an example of an:","options":["inside lag of monetary policy.","outside lag of monetary policy.","inside lag of fiscal policy.","outside lag of fiscal policy."],"answer":"D","images":null,"translation":{"question":"从政府支出增加到总需求开始增加之间的时间，是______的一个例子。","options":["货币政策的内在时滞","货币政策的外在时滞","财政政策的内在时滞","财政政策的外在时滞"]},"topics":["policy-lags"]},{"num":15,"type":"mc","question":"Advocates of passive policy argue that because monetary and fiscal policy lags are:","options":["short and fixed, these policies should not be used to offset shocks.","long and variable, these policies should not be used to offset shocks.","short and fixed these, policies should be used to offset shocks.","long and variable these, policies should be used to offset shocks."],"answer":"B","images":null,"translation":{"question":"消极政策的倡导者主张，由于货币政策和财政政策的时滞是：","options":["短而固定的，因此不应使用这些政策来抵消冲击","长而可变的，因此不应使用这些政策来抵消冲击","短而固定的，因此应使用这些政策来抵消冲击","长而可变的，因此应使用这些政策来抵消冲击"]},"topics":["policy-lags"]},{"num":16,"type":"mc","question":"All of the following could be considered automatic stabilizers except:","options":["transfer payments that increase during recessions.","discretionary changes in taxes.","a system of unemployment insurance.","the federal income tax."],"answer":"B","images":null,"translation":{"question":"以下所有都可以被视为自动稳定器，除了：","options":["在衰退期间增加的转移支付","税收的相机（酌情）变动","失业保险制度","联邦所得税"]},"topics":["rules-discretion"]},{"num":17,"type":"mc","question":"Automatic stabilizers:","options":["require congressional action before each time that they are put into effect.","have no outside lag.","have no inside lag.","have long and variable inside lags."],"answer":"C","images":null,"translation":{"question":"自动稳定器：","options":["每次生效之前都需要国会的行动","没有外在时滞","没有内在时滞","具有长而可变的内在时滞"]},"topics":["policy-lags"]},{"num":18,"type":"mc","question":"Policies that stimulate or depress the economy without any deliberate policy change are called:","options":["leading indicators.","time-inconsistent policies.","rational expectations policies.","automatic stabilizers."],"answer":"D","images":null,"translation":{"question":"在没有任何刻意政策变动的情况下刺激或抑制经济的政策被称为：","options":["先行指标","时间不一致的政策","理性预期政策","自动稳定器"]},"topics":["rules-discretion"]},{"num":19,"type":"mc","question":"Which of the following is an example of a fiscal policy that has no inside lag?","options":["a decrease in income tax rates","an ongoing unemployment insurance program","an increase in government spending for job training","a reduction in the age at which people become eligible for retirement benefits"],"answer":"B","images":null,"translation":{"question":"以下哪一项是没有内在时滞的财政政策的例子？","options":["降低所得税税率","一项持续进行的失业保险计划","增加用于职业培训的政府支出","降低人们有资格领取退休福利的年龄"]},"topics":["policy-lags"]},{"num":20,"type":"mc","question":"Macroeconometric models of the economy:","options":["usually consist of only a few equations.","require no assumptions about monetary and fiscal policy.","require assumptions about monetary and fiscal policy.","give excellent predictions, regardless of assumptions about monetary and fiscal policy."],"answer":"C","images":null,"translation":{"question":"经济的宏观计量模型：","options":["通常只由少数几个方程组成","不需要关于货币政策和财政政策的假设","需要关于货币政策和财政政策的假设","无论关于货币政策和财政政策的假设如何，都能给出出色的预测"]},"topics":["policy-lags"]},{"num":21,"type":"mc","question":"What are two types of tools that economists use to forecast future economic developments?","options":["leading indicators and macroeconometric models","direct imputations and indirect attributions","visual assessment and global positioning","monetary instruments and fiscal instruments"],"answer":"A","images":null,"translation":{"question":"经济学家用来预测未来经济走势的两类工具是什么？","options":["先行指标和宏观计量模型","直接归集和间接归因","视觉评估和全球定位","货币工具和财政工具"]},"topics":["policy-lags"]},{"num":22,"type":"mc","question":"The Lucas critique argues that because the way people form expectations is based ______ on government policies, economists ______ predict the effect of a change in policy without taking changing expectations into account.","options":["partly; cannot","only partly; can","in no way; can","in no way; cannot"],"answer":"A","images":null,"translation":{"question":"卢卡斯批判（Lucas critique）认为，由于人们形成预期的方式______依赖于政府政策，因此经济学家在不考虑预期变化的情况下______预测政策变化的影响。","options":["部分地；不能","只是部分地；能","完全不；能","完全不；不能"]},"topics":["rules-discretion"]},{"num":23,"type":"mc","question":"If people's expectations of inflation are formed rationally rather than based on adaptive expectations and if policymakers make a credible policy move to reduce inflation, then the costs of reducing inflation will be ______ traditional estimates of the sacrifice ratio.","options":["much higher than","much lower than","exactly equal to","approximately two percent greater than"],"answer":"B","images":null,"translation":{"question":"如果人们的通胀预期是理性形成而非基于适应性预期，并且决策者作出可信的降低通胀的政策举措，那么降低通胀的代价将______传统的牺牲率估计值。","options":["远高于","远低于","恰好等于","约高出 2 个百分点"]},"topics":["rules-discretion"]},{"num":24,"type":"mc","question":"According to advocates of rational expectations, traditional estimates of the sacrifice ratio are unreliable because they:","options":["ignore inside lags.","overestimate outside lags.","are based on adaptive expectations.","are time inconsistent."],"answer":"C","images":null,"translation":{"question":"根据理性预期的倡导者，传统的牺牲率估计值不可靠，因为它们：","options":["忽略了内在时滞","高估了外在时滞","基于适应性预期","是时间不一致的"]},"topics":["rules-discretion"]},{"num":25,"type":"mc","question":"According to the Lucas critique, when economists evaluate alternative policies they must take into consideration:","options":["how the policies will affect expectations and behavior.","whether the policy will offset the impact of automatic stabilizers.","the stage of the political business cycle in which the policy is to be implemented.","the length of the inside lags associated with the policies."],"answer":"A","images":null,"translation":{"question":"根据卢卡斯批判，经济学家在评估各种备选政策时，必须考虑：","options":["这些政策将如何影响预期和行为","该政策是否会抵消自动稳定器的影响","该政策实施时所处的政治经济周期阶段","与这些政策相关的内在时滞的长度"]},"topics":["rules-discretion"]},{"num":26,"type":"mc","question":"If all past economic fluctuations resulted from inept economic policies, then the historical evidence would support using:","options":["active macroeconomic policy only.","passive macroeconomic policy only.","either active or passive macroeconomic policy.","neither active nor passive macroeconomic policy."],"answer":"B","images":null,"translation":{"question":"如果过去所有的经济波动都源于拙劣的经济政策，那么历史证据将支持使用：","options":["仅积极宏观经济政策","仅消极宏观经济政策","积极或消极宏观经济政策皆可","既不积极也不消极的宏观经济政策"]},"topics":["rules-discretion"]},{"num":27,"type":"mc","question":"The differing interpretations of the historical record of the Great Depression provide support for using:","options":["active macroeconomic policy only.","passive macroeconomic policy only.","either active or passive macroeconomic policy.","neither active nor passive macroeconomic policy."],"answer":"C","images":null,"translation":{"question":"对大萧条历史记录的不同解读，为使用______提供了支持。","options":["仅积极宏观经济政策","仅消极宏观经济政策","积极或消极宏观经济政策皆可","既不积极也不消极的宏观经济政策"]},"topics":["rules-discretion"]},{"num":28,"type":"mc","question":"According to Christina Romer, the reduction in real economic volatility in the period since World War II compared to the period before World War I is the result of improved economic:","options":["policy.","performance.","data.","forecasting."],"answer":"C","images":null,"translation":{"question":"根据克里斯蒂娜·罗默（Christina Romer）的观点，第二次世界大战以来相比第一次世界大战以前真实经济波动性的降低，是经济______改善的结果。","options":["政策","表现","数据","预测"]},"topics":["rules-discretion"]},{"num":29,"type":"mc","question":"Policy is conducted by rule if policymakers:","options":["announce in advance how policy will respond to various situations and commit themselves to following through on this announcement.","are free to size up the situation case by case and choose whatever policy seems appropriate at the time.","set policy according to election results, i.e., set policy by rule of the ballot box.","manipulate policy to ensure both low inflation and unemployment on election day."],"answer":"A","images":null,"translation":{"question":"如果决策者______，那么政策就是按规则实施的。","options":["事先宣布政策将如何应对各种情况，并承诺履行这一宣布","可以逐案评估局势，并选择当时看似适当的任何政策","根据选举结果制定政策，即按票箱的规则制定政策","操纵政策以确保选举日当天低通胀和低失业率兼得"]},"topics":["rules-discretion"]},{"num":30,"type":"mc","question":"Policy is conducted by discretion if policymakers:","options":["announce in advance how policy will respond to various situations and commit themselves to following through on this announcement.","are free to size up the situation case by case and choose whatever policy seems appropriate at the time.","announce and maintain a constant growth rate of the money supply.","announce and achieve a balanced government budget."],"answer":"B","images":null,"translation":{"question":"如果决策者______，那么政策就是相机（酌情）实施的。","options":["事先宣布政策将如何应对各种情况，并承诺履行这一宣布","可以逐案评估局势，并选择当时看似适当的任何政策","宣布并维持一个恒定的货币供给增长率","宣布并实现政府预算平衡"]},"topics":["rules-discretion"]},{"num":31,"type":"mc","question":"A policy rule:","options":["must specify money growth at a constant rate.","must specify an active policy.","must specify a passive policy.","may specify either an active or a passive policy."],"answer":"D","images":null,"translation":{"question":"一项政策规则：","options":["必须规定货币以恒定速度增长","必须规定一项积极政策","必须规定一项消极政策","可以规定积极政策或消极政策"]},"topics":["rules-discretion"]},{"num":32,"type":"mc","question":"Conducting fiscal policy so that G = T, where G is government expenditures and T is tax revenue, is an example of a(n):","options":["active rule.","passive rule.","discretionary policy.","automatic stabilizer."],"answer":"B","images":null,"translation":{"question":"按 G = T（其中 G 为政府支出，T 为税收收入）来实施财政政策，是______的一个例子。","options":["积极规则","消极规则","相机政策","自动稳定器"]},"topics":["rules-discretion"]},{"num":33,"type":"mc","question":"Conducting fiscal policy so that G = T + b (u – un), where G is government expenditures, T is tax revenue, u is the unemployment rate, un is the natural rate of unemployment, and b is a positive number, is an example of a(n):","options":["active rule.","passive rule.","discretionary policy.","automatic stabilizer."],"answer":"A","images":null,"translation":{"question":"按 G = T + b (u – un)（其中 G 为政府支出，T 为税收收入，u 为失业率，un 为自然失业率，b 为正数）来实施财政政策，是______的一个例子。","options":["积极规则","消极规则","相机政策","自动稳定器"]},"topics":["rules-discretion"]},{"num":34,"type":"mc","question":"Conducting monetary policy so that the federal funds rate = p + 0.5(p – 2) + 0.5 (GDP gap), where the federal funds rate is the nominal federal funds interest rate, p is the annual inflation rate, and GDP gap is the percentage shortfall of real GDP from its natural level, is an example of:","options":["an active policy rule.","a passive policy rule.","discretionary policy.","an automatic stabilizer."],"answer":"A","images":null,"translation":{"question":"按联邦基金利率 = p + 0.5(p – 2) + 0.5 (GDP 缺口)（其中联邦基金利率为名义联邦基金利率，p 为年通胀率，GDP 缺口为实际 GDP 低于其自然水平的百分比）来实施货币政策，是______的一个例子。","options":["一项积极政策规则","一项消极政策规则","相机政策","一个自动稳定器"]},"topics":["rules-discretion"]},{"num":35,"type":"mc","question":"Conducting monetary policy so that the federal funds rate = 0.05, where the federal funds rate is the nominal federal funds interest rate, is an example of:","options":["an active policy rule.","a passive policy rule.","discretionary policy.","an automatic stabilizer."],"answer":"B","images":null,"translation":{"question":"按联邦基金利率 = 0.05（其中联邦基金利率为名义联邦基金利率）来实施货币政策，是______的一个例子。","options":["一项积极政策规则","一项消极政策规则","相机政策","一个自动稳定器"]},"topics":["rules-discretion"]},{"num":36,"type":"mc","question":"An argument in favor of allowing discretionary macroeconomic policy is that:","options":["policymakers may make erratic shifts in policy in response to changing political situations.","uninformed policymakers may choose incorrect policies.","the objectives of policymakers may be in conflict with the well-being of the public.","giving policymakers flexibility will allow them to respond to changing conditions."],"answer":"D","images":null,"translation":{"question":"支持允许相机宏观经济政策的一个论据是：","options":["决策者可能会为应对不断变化的政治局势而作出不稳定的政策转变","信息不足的决策者可能会选择错误的政策","决策者的目标可能与公众的福祉相冲突","给予决策者灵活性将使他们能够对不断变化的情况作出反应"]},"topics":["rules-discretion"]},{"num":37,"type":"mc","question":"The political business cycle refers to the:","options":["pattern of holding primaries, conventions, and general elections every four years.","cycle of electing U.S. representatives every two years, the U.S. president every four years, and U.S. senators every six years.","manipulation of the economy to win elections.","pattern of recession and expansion that follows every election."],"answer":"C","images":null,"translation":{"question":"政治经济周期（political business cycle）指的是：","options":["每四年举行初选、代表大会和大选的模式","每两年选举美国众议员、每四年选举美国总统、每六年选举美国参议员的周期","为赢得选举而操纵经济","每次选举之后出现的衰退与扩张模式"]},"topics":["rules-discretion"]},{"num":38,"type":"mc","question":"A time-inconsistency problem in macroeconomic policy can occur when the policymaker:","options":["is made to follow a strict and an inflexible rule.","has discretion in the short run but follows a rule in the long run.","changes stated policy because it benefits their current circumstance at the expense of public trust.","has no discretion."],"answer":"C","images":null,"translation":{"question":"当决策者______时，宏观经济政策中可能出现时间不一致性问题。","options":["被迫遵循一项严格而不灵活的规则","在短期拥有相机权但在长期遵循规则","为了有利于自身当前处境而牺牲公众信任来改变已宣布的政策","没有相机权"]},"topics":["rules-discretion"]},{"num":39,"type":"mc","question":"If the Fed has discretion to choose its own policy and announces a policy of low inflation, then:","options":["the policymaker is required to make the money supply grow at a low rate.","private economic agents are sure to believe the announcement because it is credible.","private economic actors are likely to discount the policy because the Fed has an incentive to renege on its policy once expectations are formed.","the Fed is certain to renege on its policy once expectations are formed because then it can lower unemployment with minimum inflation."],"answer":"C","images":null,"translation":{"question":"如果美联储有权自行选择政策，并宣布一项低通胀政策，那么：","options":["决策者被要求使货币供给以低速增长","私人经济主体肯定会相信这一宣布，因为它是可信的","私人经济主体很可能会对该政策打折扣，因为一旦预期形成，美联储就有动机违背其政策","一旦预期形成，美联储必定会违背其政策，因为这样它就能以最小的通胀降低失业率"]},"topics":["rules-discretion"]},{"num":40,"type":"mc","question":"Policymakers may be better able to achieve their goals using a fixed policy rule rather than using discretion if they face the problem of:","options":["short and predictable inside lags.","time-inconsistent policy.","short and predictable outside lags.","weak automatic stabilizers."],"answer":"B","images":null,"translation":{"question":"如果决策者面临______的问题，那么他们使用固定的政策规则可能比使用相机权更能实现其目标。","options":["短而可预测的内在时滞","时间不一致的政策","短而可预测的外在时滞","薄弱的自动稳定器"]},"topics":["rules-discretion"]},{"num":41,"type":"mc","question":"When a government honors its debt obligations, this is an example of:","options":["discretionary fiscal policy.","discretionary monetary policy.","a fiscal policy rule.","a monetary policy rule."],"answer":"C","images":null,"translation":{"question":"当政府履行其债务义务时，这是______的一个例子。","options":["相机财政政策","相机货币政策","一项财政政策规则","一项货币政策规则"]},"topics":["rules-discretion"]},{"num":42,"type":"mc","question":"A situation where policymakers have the incentive to deviate from their initial course of action once other agents in the economy have acted is called a(n):","options":["rational expectation.","outside lag.","time-inconsistent policy.","active policy rule."],"answer":"C","images":null,"translation":{"question":"决策者在经济中的其他主体已经采取行动之后，有动机偏离其最初行动方针的情形，被称为：","options":["理性预期","外在时滞","时间不一致的政策","积极政策规则"]},"topics":["rules-discretion"]},{"num":43,"type":"mc","question":"As Secretary of the Treasury, Alexander Hamilton opposed the time-inconsistent policy of:","options":["repaying debt.","raising taxes.","repudiating debt.","reducing taxes."],"answer":"C","images":null,"translation":{"question":"作为财政部长，亚历山大·汉密尔顿（Alexander Hamilton）反对______这一时间不一致的政策。","options":["偿还债务","增税","赖账（拒付债务）","减税"]},"topics":["rules-discretion"]},{"num":44,"type":"mc","question":"Monetarists believe all of the following except:","options":["fluctuations in the money supply are responsible for most fluctuations in the economy.","the Fed should keep the money supply growing at a steady rate.","slow and steady growth of the money supply would yield stable output, employment, and prices.","the Fed should adjust the money supply to adjust to various shocks to the economy."],"answer":"D","images":null,"translation":{"question":"货币主义者相信以下所有观点，除了：","options":["货币供给的波动是经济中大多数波动的原因","美联储应使货币供给保持稳定增长","货币供给缓慢而稳定的增长将带来稳定的产出、就业和物价","美联储应调整货币供给以适应经济的各种冲击"]},"topics":["rules-discretion"]},{"num":45,"type":"mc","question":"Monetary policy rules that target nominal variables would target any of the following except the:","options":["price level.","money supply","unemployment rate.","level of nominal GDP."],"answer":"C","images":null,"translation":{"question":"以名义变量为目标的货币政策规则会以以下任何一项为目标，除了：","options":["价格水平","货币供给","失业率","名义 GDP 水平"]},"topics":["inflation-targeting"]},{"num":46,"type":"mc","question":"If the velocity of money varies a great deal, steady growth of the money supply is a(n):","options":["ineffective way to stabilize aggregate demand.","example of discretionary monetary policy.","automatic stabilizer.","active policy rule."],"answer":"A","images":null,"translation":{"question":"如果货币流通速度变化很大，那么货币供给的稳定增长是：","options":["一种无效的稳定总需求的方式","相机货币政策的一个例子","一个自动稳定器","一项积极政策规则"]},"topics":["rules-discretion"]},{"num":47,"type":"mc","question":"A monetary policy rule that targets nominal GDP would ______ money growth when nominal GDP rises above the target and ______ money growth when nominal GDP falls below the target.","options":["reduce; raise","raise; reduce","reduce; reduce","raise; raise"],"answer":"A","images":null,"translation":{"question":"以名义 GDP 为目标的货币政策规则，会在名义 GDP 升至目标之上时______货币增长，并在名义 GDP 降至目标之下时______货币增长。","options":["减少；增加","增加；减少","减少；减少","增加；增加"]},"topics":["inflation-targeting"]},{"num":48,"type":"mc","question":"Unlike a monetarist policy rule, an inflation target has the advantage of:","options":["eliminating the need to announce the policy target.","providing a real target rather than a nominal one.","allowing the central bank unlimited discretion.","insulating the economy from changes in money velocity."],"answer":"D","images":null,"translation":{"question":"与货币主义的政策规则不同，通胀目标制的优点是：","options":["免除了宣布政策目标的必要","提供的是实际目标而非名义目标","允许央行拥有无限的相机权","使经济免受货币流通速度变化的影响"]},"topics":["inflation-targeting"]},{"num":49,"type":"mc","question":"Inflation targeting is a monetary policy rule that requires the central bank to adjust _____ in order to attain the desired inflation rate.","options":["a price index","the velocity of money","nominal GDP","the money supply"],"answer":"D","images":null,"translation":{"question":"通胀目标制是一项货币政策规则，它要求央行调整______以实现期望的通胀率。","options":["一个价格指数","货币流通速度","名义 GDP","货币供给"]},"topics":["inflation-targeting"]},{"num":50,"type":"mc","question":"Although real variables such as unemployment and real GDP are the best measures of economic performance, most economists do not advocate manipulating money supply directly to hit a real target because:","options":["they believe a constant growth rate of the money supply is the best way to stabilize real GDP or unemployment.","if the Fed chose a target that was not natural output or the natural unemployment rate, the result would be accelerating inflation or deflation.","if the Fed chose a target for the unemployment rate above the natural rate, the result would be accelerating inflation.","if the Fed chose a target for the unemployment rate below the natural rate, the result would be accelerating deflation."],"answer":"B","images":null,"translation":{"question":"虽然失业率和实际 GDP 等实际变量是衡量经济表现的最佳指标，但大多数经济学家并不主张直接操纵货币供给来达到实际目标，因为：","options":["他们认为货币供给的恒定增长率是稳定实际 GDP 或失业率的最佳方式","如果美联储选择的目标不是自然产出或自然失业率，结果将是加速的通胀或通缩","如果美联储选择高于自然失业率的失业率目标，结果将是加速的通胀","如果美联储选择低于自然失业率的失业率目标，结果将是加速的通缩"]},"topics":["inflation-targeting"]},{"num":51,"type":"mc","question":"In practice, inflation targeting is better considered as operating with constrained discretion rather than according to a policy rule because central banks with inflation targets typically:","options":["are not allowed to adjust the target in the event of shocks.","set the inflation target as a range rather than as a particular number.","are not held accountable for achieving their target.","must achieve their target regardless of economic conditions."],"answer":"B","images":null,"translation":{"question":"在实践中，通胀目标制最好被视为在受约束的相机权下运行，而非按照政策规则运行，因为设有通胀目标的央行通常会：","options":["在发生冲击时不得调整目标","将通胀目标设为一个区间，而非一个特定数字","不被追究实现目标的责任","无论经济状况如何都必须实现其目标"]},"topics":["inflation-targeting"]},{"num":52,"type":"mc","question":"Economic research finds that greater central-bank independence is ______ correlated with lower and more stable inflation as well as ______ correlated with the average growth and variability of real GDP.","options":["strongly; strongly","strongly; not","not; strongly","not; not"],"answer":"B","images":null,"translation":{"question":"经济研究发现，更大的央行独立性与更低、更稳定的通胀______相关，与实际 GDP 的平均增长和波动性______相关。","options":["强；强","强；不","不；强","不；不"]},"topics":["inflation-targeting"]},{"num":53,"type":"mc","question":"Central-bank independence refers to:","options":["whether central banks pursue monetary policy by rules or discretion.","the situation that occurs when the inside lag of monetary policy is not related to the outside lag.","the extent to which automatic stabilizers are relied on to cushion economic volatility.","the degree of separation between central-bank decision making and political influence."],"answer":"D","images":null,"translation":{"question":"央行独立性指的是：","options":["央行是按规则还是按相机权实施货币政策","货币政策的内在时滞与外在时滞不相关时所出现的情形","在多大程度上依赖自动稳定器来缓冲经济波动","央行决策与政治影响之间的分离程度"]},"topics":["inflation-targeting"]},{"num":54,"type":"mc","question":"Countries with greater central-bank independence can achieve lower rates of inflation:","options":["at the cost of higher levels of unemployment.","at the cost of slower growth rates of real GDP.","at the cost of greater volatility of real GDP.","with no apparent real economic costs."],"answer":"D","images":null,"translation":{"question":"央行独立性更强的国家能够实现更低的通胀率：","options":["以更高的失业水平为代价","以实际 GDP 更慢的增长率为代价","以实际 GDP 更大的波动性为代价","且没有明显的实际经济代价"]},"topics":["inflation-targeting"]},{"num":55,"type":"mc","question":"Economic science has provided convincing evidence in favor of the:","options":["rule favoring a constant rate of growth of the money supply.","rule favoring use of the money supply to hit a nominal GDP target.","rule requiring a constantly balanced budget for the federal government.","fact that there is no simple and compelling case for any particular view of macroeconomic policy."],"answer":"D","images":null,"translation":{"question":"经济科学已经提供了令人信服的证据，支持：","options":["主张货币供给以恒定速度增长的规则","主张利用货币供给来达到名义 GDP 目标的规则","要求联邦政府预算始终保持平衡的规则","对于宏观经济政策的任何特定观点都不存在简单而有力论据这一事实"]},"topics":["rules-discretion"]},{"num":56,"type":"mc","question":"The Phillips curve describing an economy takes the form u = un – a(p – Ep). The central bank directly sets the inflation rate to minimize the following loss function, L (u, p) = u + gp2. The symbol u denotes the unemployment rates, un is the natural rate of unemployment, p is the inflation rate, Ep is the expected inflation rate, and a and g are behavioral response parameters of the economy. Private agents form their expectations rationally before the central bank sets the inflation rate. The optimal inflation rate when the central bank operates using a fixed rule will be ______. The optimal inflation rate when the central bank operates with discretion will be ______.","options":["un; 0","0; un","0; a/(2g)","a/(2g); 0"],"answer":"C","images":null,"translation":{"question":"描述某一经济的菲利普斯曲线形如 u = un – a(p – Ep)。央行直接设定通胀率，以最小化以下损失函数 L(u, p) = u + gp2。符号 u 表示失业率，un 为自然失业率，p 为通胀率，Ep 为预期通胀率，a 和 g 为经济的行为反应参数。私人主体在央行设定通胀率之前理性地形成预期。当央行按固定规则运行时，最优通胀率将是______。当央行按相机权运行时，最优通胀率将是______。","options":["un；0","0；un","0；a/(2g)","a/(2g)；0"]},"topics":["rules-discretion"]},{"num":57,"type":"mc","question":"The Phillips curve describing an economy takes the form u = un – a(p – Ep). The central bank directly sets the inflation rate to minimize the following loss function, L (u, p) = u + gp2. The symbol u denotes the unemployment rates, un is the natural rate of unemployment, p is the inflation rate, Ep is the expected inflation rate, and a and g are behavioral response parameters of the economy. Private agents form their expectations rationally before the central bank sets the inflation rate. In an economy in which the central bank dislikes inflation much more than unemployment:","options":["a will be very large.","a will be very small.","g will be very large.","g will be very small."],"answer":"C","images":null,"translation":{"question":"描述某一经济的菲利普斯曲线形如 u = un – a(p – Ep)。央行直接设定通胀率，以最小化以下损失函数 L(u, p) = u + gp2。符号 u 表示失业率，un 为自然失业率，p 为通胀率，Ep 为预期通胀率，a 和 g 为经济的行为反应参数。私人主体在央行设定通胀率之前理性地形成预期。在一个央行对通胀的厌恶远甚于失业的经济中：","options":["a 将非常大","a 将非常小","g 将非常大","g 将非常小"]},"topics":["rules-discretion"]},{"num":58,"type":"mc","question":"The Phillips curve describing an economy takes the form u = un – a(p – Ep). The central bank directly sets the inflation rate to minimize the following loss function, L (u, p) = u + gp2. The symbol u denotes the unemployment rates, un is the natural rate of unemployment, p is the inflation rate, Ep is the expected inflation rate, and a and g are behavioral response parameters of the economy. Private agents form their expectations rationally before the central bank sets the inflation rate. Compared to making monetary policy with discretion, the optimal inflation rate will be ______ under a fixed rule and the unemployment rate will be ______.","options":["higher; lower","higher; the same","lower; lower","lower; the same"],"answer":"D","images":null,"translation":{"question":"描述某一经济的菲利普斯曲线形如 u = un – a(p – Ep)。央行直接设定通胀率，以最小化以下损失函数 L(u, p) = u + gp2。符号 u 表示失业率，un 为自然失业率，p 为通胀率，Ep 为预期通胀率，a 和 g 为经济的行为反应参数。私人主体在央行设定通胀率之前理性地形成预期。与按相机权制定货币政策相比，在固定规则下最优通胀率将______，失业率将______。","options":["更高；更低","更高；相同","更低；更低","更低；相同"]},"topics":["rules-discretion"]},{"num":59,"type":"mc","question":"The time-inconsistency problem in discretionary policymaking about unemployment and inflation can be effectively avoided when the:","options":["policymaker has and is known to have an extremely strong preference for very low inflation.","policymaker does not care about the rate of inflation and simply sets policy to avoid unemployment.","private agents in the economy are not “rational.”","policymaker has more information than do the private agents in the economy."],"answer":"A","images":null,"translation":{"question":"当______时，关于失业和通胀的相机决策中的时间不一致性问题可以被有效避免。","options":["决策者拥有、并且众所周知地拥有对极低通胀的极强偏好","决策者不在乎通胀率，只是单纯为规避失业而制定政策","经济中的私人主体不是“理性的”","决策者比经济中的私人主体拥有更多信息"]},"topics":["rules-discretion"]},{"num":60,"type":"mc","question":"A central bank operating with discretion can achieve the same outcome as the central bank committed to a fixed rule of zero inflation if:","options":["there are no inside lags.","there are no outside lags.","the central bank dislikes unemployment much more than inflation.","the central bank dislikes inflation much more than unemployment."],"answer":"D","images":null,"translation":{"question":"如果______，那么按相机权运行的央行能够取得与承诺零通胀固定规则的央行相同的结果。","options":["不存在内在时滞","不存在外在时滞","央行对失业的厌恶远甚于通胀","央行对通胀的厌恶远甚于失业"]},"topics":["rules-discretion"]},{"num":61,"type":"mc","question":"Assume that the Democrats always had a policy of high money growth while the Republicans followed a policy of low money growth, and the economy had a standard Phillips curve. Then, if the two parties took regular terms in office:","options":["there would be no political business cycle, but inflation would be higher under the Democrats.","there would be no political business cycle, but inflation would be higher under the Republicans.","unemployment would be lower under the Democrats, but inflation would be higher.","both unemployment and inflation would be higher under the Democrats."],"answer":"A","images":null,"translation":{"question":"假设民主党一直实行高货币增长政策，而共和党实行低货币增长政策，且经济具有一条标准的菲利普斯曲线。那么，如果两党定期轮流执政：","options":["将不存在政治经济周期，但民主党执政时通胀会更高","将不存在政治经济周期，但共和党执政时通胀会更高","民主党执政时失业率会更低，但通胀会更高","民主党执政时失业率和通胀都会更高"]},"topics":["rules-discretion"]},{"num":62,"type":"mc","question":"If a city passes laws limiting rents on apartments but promises to exempt buildings not yet built:","options":["construction of new buildings will not be discouraged.","construction of new buildings may be discouraged.","builders will not expect the city to renege on its promise.","the city will have no incentive to renege on its promise."],"answer":"B","images":null,"translation":{"question":"如果某城市通过限制公寓租金的法律，但承诺对尚未建造的房屋予以豁免：","options":["新房屋的建设将不会受到抑制","新房屋的建设可能会受到抑制","建筑商将不会预期该城市会违背其承诺","该城市将没有动机违背其承诺"]},"topics":["rules-discretion"]},{"num":63,"type":"sa","question":"Assume that in a certain economy, the LM curve is given by Y = 2,000r – 2,000 + 2 (M / P), and the IS curve is given by Y = 8,000 – 2,000r + u, where u is a shock that is equal to +200 half the time and –200 half the time. The price level (P) is fixed at 1.0. The natural rate of output is 4,000. The government wants to keep output as close as possible to 4,000 and does not care about anything else. Consider the following two policy rules: i. Set the money supply M equal to 1,000 and keep it there. ii. Manipulate M from day to day to keep the interest rate constant at 2 percent. a. Under rule i, what will Y be when u = +200? What will Y be under rule i when u = –200? b. Under rule ii, what will Y be when u = +200? What will Y be under rule ii when u = –200? c. Which rule will keep output closer to 4,000?","options":null,"answer":null,"images":null,"translation":{"question":"假设在某一经济中，LM 曲线由 Y = 2,000r – 2,000 + 2 (M / P) 给出，IS 曲线由 Y = 8,000 – 2,000r + u 给出，其中 u 是一个冲击，一半时间等于 +200，一半时间等于 –200。价格水平 (P) 固定为 1.0。自然产出率为 4,000。政府希望使产出尽可能接近 4,000，且不在乎其他任何事情。考虑以下两条政策规则：i. 将货币供给 M 设定为 1,000 并保持不变。ii. 逐日操纵 M 以使利率恒定保持在 2%。a. 在规则 i 下，当 u = +200 时 Y 是多少？在规则 i 下，当 u = –200 时 Y 是多少？b. 在规则 ii 下，当 u = +200 时 Y 是多少？在规则 ii 下，当 u = –200 时 Y 是多少？c. 哪条规则能使产出更接近 4,000？","options":null},"topics":["rules-discretion"],"answer_ref":"冲击在IS曲线上：LM：Y = 2000r − 2000 + 2M/P；IS：Y = 8000 − 2000r + u。要 Y=4000，由IS得 r = (8000+u−4000)/2000 = 2 + u/2000。代入LM：4000 = 4000+u−2000+2M/P → M/P = 1000 − u/2。政策：u=+200时 M=900；u=−200时 M=1100——用货币政策精确对冲IS冲击，产出恒为4000（不管利率）。"},{"num":64,"type":"sa","question":"Assume that in a certain economy, the LM curve is given by Y = 2,000r – 2,000 + 2 (M / P) + u, where u is a shock that is equal to +200 half the time and –200 half the time, and the IS curve is given by Y = 8,000 – 2,000r. The price level (P) is fixed at 1.0. The natural rate of output is 4,000. The government wants to keep output as close as possible to 4,000 and does not care about anything else. Consider the following two policy rules: i. Set the money supply M equal to 1,000 and keep it there. ii. Manipulate M from day to day to keep the interest rate constant at 2 percent. a. Under rule i, what will Y be when u = +200? Under rule i, what will Y be when u = –200? b. Under rule ii, what will Y be when u = +200? Under rule ii, what will Y be when u = –200? c. Which rule will keep output closer to 4,000?","options":null,"answer":null,"images":null,"translation":{"question":"假设在某一经济中，LM 曲线由 Y = 2,000r – 2,000 + 2 (M / P) + u 给出，其中 u 是一个冲击，一半时间等于 +200，一半时间等于 –200；IS 曲线由 Y = 8,000 – 2,000r 给出。价格水平 (P) 固定为 1.0。自然产出率为 4,000。政府希望使产出尽可能接近 4,000，且不在乎其他任何事情。考虑以下两条政策规则：i. 将货币供给 M 设定为 1,000 并保持不变。ii. 逐日操纵 M 以使利率恒定保持在 2%。a. 在规则 i 下，当 u = +200 时 Y 是多少？在规则 i 下，当 u = –200 时 Y 是多少？b. 在规则 ii 下，当 u = +200 时 Y 是多少？在规则 ii 下，当 u = –200 时 Y 是多少？c. 哪条规则能使产出更接近 4,000？","options":null},"topics":["rules-discretion"],"answer_ref":"冲击在LM曲线上，应用财政政策对冲：LM：Y = 2000r − 2000 + 2M/P + u。要 Y=4000 且 M/P=1000，得 r = (4000+2000−2000−u)/2000 = 2 − u/2000。代入IS：4000 = 8000 − 2000r + u_G → u_G = 2000r − 4000 = −u。即冲击为+200时把G减少200，为−200时把G增加200。一般原则：货币对冲IS冲击，财政对冲LM冲击——谁远离冲击源就用谁。"},{"num":65,"type":"sa","question":"Let the symbol p stand for the rate of inflation, with Ep the expected inflation rate, both measured in percentage. The letter u is the unemployment rate and un is the natural rate of unemployment. Suppose the short-run Phillips curve is u = un – a (p – Ep) applies in a certain economy. The Fed's loss function is L (u, p) = u + gp2. The analysis in the appendix to textbook Chapter 16 shows that if the Fed minimizes its loss function under the assumption that Ep is fixed and “rational” private agents know this, the expected inflation rate will be Ep = a/2g, and this will also be the inflation rate the government chooses. a. Suppose that a = 0.5 and g = 0.05. What are the expected and actual inflation rates? b. Suppose a = 0.5 and g = 0.50. In this case, does the Fed have greater or lesser relative distaste for inflation than in part a? What are the expected and actual inflation rates with g = 0.50? Why do they differ from the inflation rates in part a?","options":null,"answer":null,"images":null,"translation":{"question":"设符号 p 代表通胀率，Ep 为预期通胀率，二者均以百分比衡量。字母 u 为失业率，un 为自然失业率。假设短期菲利普斯曲线 u = un – a (p – Ep) 适用于某一经济。美联储的损失函数为 L(u, p) = u + gp2。教科书第 16 章附录的分析表明，如果美联储在 Ep 固定的假设下最小化其损失函数，且“理性的”私人主体知晓这一点，那么预期通胀率将为 Ep = a/2g，这同时也将是政府选择的通胀率。a. 假设 a = 0.5 且 g = 0.05。预期通胀率和实际通胀率各是多少？b. 假设 a = 0.5 且 g = 0.50。在这种情况下，美联储对通胀的相对厌恶比 a 小题中是更大还是更小？当 g = 0.50 时，预期通胀率和实际通胀率各是多少？它们为何与 a 小题中的通胀率不同？","options":null},"topics":["rules-discretion"],"answer_ref":"央行在预期通胀给定时选择π最小化 L = un − a(π−πe) + gπ²。一阶条件：−a + 2gπ = 0 → 最优通胀 π* = a/(2g)。通胀权重g越大、菲利普斯曲线越平坦（a越小），央行选择的通胀越低；相机抉择下通胀系统性高于零——时间不一致性的来源。"},{"num":66,"type":"sa","question":"You are hired as a consultant to set up the central bank of a new country. Suggest at least two possible ways to structure the central bank to keep inflation levels low.","options":null,"answer":null,"images":null,"translation":{"question":"你被聘为顾问，负责组建一个新国家的央行。请提出至少两种可能的央行架构方式，以使通胀水平保持在低位。","options":null},"topics":["inflation-targeting","rules-discretion"],"answer_ref":"① 法律授予央行独立性并明确低通胀使命（独立央行实证上通胀更低，如通胀目标制的央行）；② 任命\"保守派\"央行行长——对通胀赋予高于社会平均的权重（Rogoff 的保守中央银行家理论）；③ 用明确规则或通胀目标约束相机抉择；④ 与央行签订绩效合约（通胀超标则受罚）。任答两种。"},{"num":67,"type":"sa","question":"For each of the following policies, indicate whether the policy is i. a monetary or a fiscal policy, ii an active or a passive policy, and iii a policy by rules or with discretion: a. The central bank follows a policy of allowing the money supply to grow at a constant 4 percent per year. b. A government follows a policy of keeping government spending over a calendar year equal to government revenue over the calendar year. c. The central bank uses judgment to adjust the growth of the money supply based on expectations of what will happen to output and inflation over the next five years. d. The government keeps tax laws unchanging and allows government spending to change, depending on which spending bills are passed by the legislature. e. The central bank follows a policy of adjusting the money supply according to a formula based on deviations of unemployment from the natural rate of unemployment.","options":null,"answer":null,"images":null,"translation":{"question":"对于以下每项政策，指出该项政策是 i. 货币政策还是财政政策，ii. 积极政策还是消极政策，以及 iii. 按规则还是按相机权实施的政策：a. 央行实行允许货币供给每年以恒定 4% 的速度增长的政策。b. 政府实行使一个日历年度内的政府支出等于该年度政府收入的政策。c. 央行依据对未来五年产出和通胀走势的预期，运用判断来调整货币供给的增长。d. 政府保持税法不变，并根据立法机关通过了哪些支出法案来允许政府支出变化。e. 央行实行根据失业率对自然失业率的偏离、按公式调整货币供给的政策。","options":null},"topics":["rules-discretion"],"answer_ref":"a. 货币供给每年固定增长4%：货币政策、消极（不随周期调整）政策、按规则行事。b. 政府让年度支出等于收入（平衡预算规则）：财政政策、消极政策、按规则行事。（分类标准：货币vs财政看工具；积极vs消极看是否逆周期；规则vs相机抉择看承诺。）"},{"num":68,"type":"sa","question":"The central banks of two nearly identical countries, Fixland and Flexland, desire low inflation and low unemployment. There is a similar short-run tradeoff between unemployment and unexpected inflation in both countries. Private agents in both Fixland and Flexland form expectations rationally and understand the incentives that central banks may have to renege on low-inflation policies. Initially, the rates of inflation and unemployment are the same in both countries. The central bank of Fixland makes a credible announcement that it will operate according to a low-inflation rule. The central bank of Flexland announces that it plans to follow a low-inflation policy, but retains the right to deviate from this policy at its discretion. a. In which country would you expect the rate of inflation to be lower? b. In which country would you expect the unemployment rate to be lower?","options":null,"answer":null,"images":null,"translation":{"question":"两个几乎相同的国家——固定国（Fixland）和灵活国（Flexland）——的央行都希望低通胀和低失业。两国在失业与未预期通胀之间都存在类似的短期权衡。固定国和灵活国的私人主体都理性地形成预期，并理解央行可能有动机违背低通胀政策。最初，两国的通胀率和失业率相同。固定国央行可信地宣布它将按照低通胀规则运行。灵活国央行宣布它计划遵循低通胀政策，但保留酌情偏离该政策的权利。a. 你预期哪个国家的通胀率会更低？b. 你预期哪个国家的失业率会更低？","options":null},"topics":["rules-discretion"],"answer_ref":"可信承诺的关键作用：Fixland（可信）——预期通胀随承诺立即下调，菲利普斯曲线关系下通胀降到2%而失业不高于自然率，反通胀近乎无痛苦。Flexland（央行有食言前科）——公众不信，预期通胀维持高位，要把实际通胀压下来必须长期维持失业高于自然率，牺牲率很高。两国菲利普斯结构相同，结局迥异——差别只在可信度。"},{"num":69,"type":"sa","question":"The following notice appeared on a full page of the Wall Street Journal on February 9, 2009: \"There is no disagreement that we need action by our government, a recovery plan that will help to jumpstart the economy.”—President-Elect Barack Obama, January 9, 2009 With all due respect, Mr. President, that is not true. Notwithstanding reports that all economists are now Keynesians and that we all support a big increase in the burden of government, we the undersigned do not believe that more government spending is a way to improve economic performance. More government spending by Hoover and Roosevelt did not pull the United States out of the Great Depression in the 1930s. More government spending did not solve Japan's “lost decade” in the 1990s. As such, it is a triumph of hope over experience to believe that more government spending will help the United States today. To improve the economy, policymakers should focus on reforms that remove impediments to work, saving, investment and production. Lower tax rates and a reduction in the burden of government are the best ways of using fiscal policy to boost growth. The statement was signed by more than 200 economists, including 3 Nobel Laureates. a. Comment on the extent to which the disagreement between the president and the economists involves a disagreement about whether policy should be passive or active. b. Identify the rationale(s) used to support the economists' position.","options":null,"answer":null,"images":null,"translation":{"question":"以下声明于 2009 年 2 月 9 日刊登在《华尔街日报》(Wall Street Journal) 的一个整版上：“毫无争议的是，我们需要政府采取行动，需要一个有助于迅速启动经济的复苏计划。”——当选总统巴拉克·奥巴马（Barack Obama），2009 年 1 月 9 日。恕我直言，总统先生，那并非事实。尽管有报道称所有经济学家如今都是凯恩斯主义者，且我们都支持大幅增加政府负担，但我们这些署名者并不认为增加政府支出是改善经济表现的办法。胡佛（Hoover）和罗斯福（Roosevelt）时期的更多政府支出并没有使美国走出 20 世纪 30 年代的大萧条。更多政府支出也没有解决日本 20 世纪 90 年代的“失去的十年”。因此，相信更多政府支出如今能帮助美国，是用希望战胜了经验。为改善经济，决策者应聚焦于消除对工作、储蓄、投资和生产障碍的改革。降低税率和减轻政府负担是利用财政政策促进增长的最佳方式。该声明由 200 多位经济学家签署，其中包括 3 位诺贝尔奖得主。a. 评论一下，总统与经济学家之间的分歧在多大程度上涉及政策应消极还是积极的分歧。b. 指出用来支持经济学家立场的理由。","options":null},"topics":["rules-discretion"],"answer_ref":"这封广告信说明经济学家对积极财政刺激存在实质分歧。反对方理由：政策时滞长、效果到来时经济或已自愈；政府支出挤出私人投资；赤字加重未来税负（李嘉图等价下甚至无效）；支出投向效率低、政治色彩浓；部分经济学家主张以货币宽松或减税代替。\"所有经济学家都支持刺激\"不成立——分歧本身就揭示了积极政策的局限。"},{"num":70,"type":"sa","question":"Compare two procedures for conducting monetary policy: Method 1: Maintain a steady money growth of 6 percent per year Method 2: Maintain a steady inflation rate of 3 percent per year Be sure to consider whether the methods involve (1) active or passive monetary policy and (2) rules or discretion. Discuss why one method might be preferred over the other.","options":null,"answer":null,"images":null,"translation":{"question":"比较实施货币政策的两种程序：方法 1：维持每年 6% 的稳定货币增长。方法 2：维持每年 3% 的稳定通胀率。务必考虑这些方法涉及的是 (1) 积极还是消极的货币政策，以及 (2) 规则还是相机权。讨论为何一种方法可能优于另一种方法。","options":null},"topics":["rules-discretion","inflation-targeting"],"answer_ref":"方法1（货币固定增长6%）：消极政策、按规则行事。方法2（通胀目标3%）：目标本身是规则，但为盯住目标需不断调整工具——操作层面是积极的、按规则框架行事。偏好理由：货币流通速度不稳定使货币增长成为不可靠的名义锚；通胀目标直接锚定最终目标、透明度与可信度更高、对冲击的反应更灵活。故现代央行普遍偏好通胀目标制。"},{"num":71,"type":"sa","question":"Explain why each of the following statements is a rationale for conducting active or passive policy: a. Economic circumstances can change dramatically between the time that an economic downturn begins and the time when policy actions have an effect on the economy. b. Economists are not very accurate forecasters. c. Increases in government spending generate increases in economic output. d. Fluctuations in economic output have been less severe since World War II.","options":null,"answer":null,"images":null,"translation":{"question":"解释为什么以下每项陈述都是实施积极或消极政策的理由：a. 从经济下行开始到政策行动对经济产生影响之间，经济状况可能发生剧烈变化。b. 经济学家并不是非常准确的预测者。c. 政府支出的增加会带来经济产出的增加。d. 第二次世界大战以来，经济产出的波动已不那么剧烈。","options":null},"topics":["policy-lags","rules-discretion"],"answer_ref":"a. 时滞漫长→消极政策理由（政策落地时经济已转向，反添波动）。b. 预测不准→消极政策理由（瞄不准的靶不如不射）。c. 政府支出能增加产出→积极政策理由（财政有乘数效应）。d. 经济波动代价高昂→积极政策理由（稳定产出与就业值得干预）。两句支持积极（c、d），两句支持消极（a、b）。"},{"num":72,"type":"sa","question":"Many times a monetary policy does not have the effect on the economy that is desired by the regulator. Why does this happen?","options":null,"answer":null,"images":null,"translation":{"question":"很多时候，一项货币政策并不会对经济产生监管者所期望的效果。为什么会这样？","options":null},"topics":["policy-lags"],"answer_ref":"货币政策达不到预期效果的原因：①传导时滞长且不确定；②金融体系受损时信用渠道阻塞（危机中银行惜贷）；③流动性陷阱——利率降无可降；④预期与可信度问题——私人部门不相信承诺则政策失效；⑤货币需求/流通速度不稳定；⑥国际资本流动抵消；⑦政治压力扭曲决策。"},{"num":73,"type":"sa","question":"Fiscal policy is a tool the government uses to steer the economy of a country. What are the advantages of active fiscal policy over passive fiscal policy?","options":null,"answer":null,"images":null,"translation":{"question":"财政政策是政府用来引导一国经济的工具。积极财政政策相对于消极财政政策有哪些优势？","options":null},"topics":["rules-discretion"],"answer_ref":"积极财政政策的优势：① 能精准定向——援助特定地区、群体或行业；② 当货币政策失效时（零利率下限、流动性陷阱）仍有效；③ 直接形成总需求，乘数见效快；④ 自动稳定器无需决策时滞即可平滑波动；⑤ 若投向基础设施，还兼有提升长期供给能力之效。"},{"num":74,"type":"sa","question":"Automatic stabilizers start stabilizing the economy as soon as it deviates from its normal course. Explain with an example how this works in a recession.","options":null,"answer":null,"images":null,"translation":{"question":"自动稳定器在经济一旦偏离其正常轨道时就立即开始稳定经济。请举例说明它在衰退中是如何起作用的。","options":null},"topics":["policy-lags","rules-discretion"],"answer_ref":"例：累进所得税+失业救济。衰退时工人收入下降→适用税率自动降低、缴税自动减少，同时失业者自动领取救济——可支配收入比收入下降得慢，消费得以托底。整个过程无需立法、即时启动，产出缺口被自动部分吸收；扩张期则相反：收入升→税赋升、救济支出降——经济过热自动降温。"},{"num":75,"type":"sa","question":"Does the public's expectation of a policy influence its effectiveness?","options":null,"answer":null,"images":null,"translation":{"question":"公众对一项政策的预期是否会影响该政策的有效性？","options":null},"topics":["rules-discretion"],"answer_ref":"影响显著（卢卡斯批判）：政策效果取决于它是否被预期到。被预期到的系统性政策在理性预期下对产出无实际影响；对政策的预期还会改变当前行为（如预期未来增税则当前增加储蓄——李嘉图等价）。因此\"同样的政策\"在预期环境不同时效果完全不同，政策分析必须把预期反应纳入模型。"},{"num":76,"type":"sa","question":"Give an example of an economic policy that the government, after announcing the economic policy, will be tempted to renege.","options":null,"answer":null,"images":null,"translation":{"question":"举一个例子，说明政府在宣布某项经济政策之后会有动机去违背它。","options":null},"topics":["rules-discretion"],"answer_ref":"例：政府宣布\"为低收入家庭提供购房补贴将永久终止\"——宣布后因压力在选前恢复补贴（时间不一致）；或央行宣布零通胀承诺，经济疲软时受诱惑制造意外通胀换取短期就业；或宣布基础设施计划后改变税种融资。共同特征：宣布时的最优与事后执行时的最优不一致。"},{"num":77,"type":"sa","question":"Given that the Philip curve defines an economy as [[IMG:c16_img0.png]] where [[IMG:c16_img1.png]] is the unemployment rate and p is the inflation rate, and the loss function which tells the social cost of unemployment and inflation is [[IMG:c16_img2.png]],calculate the optimal level of inflation for the economy taking expected inflation as given.","options":null,"answer":null,"images":null,"translation":{"question":"给定菲利普斯曲线将某一经济定义为 [[IMG:c16_img0.png]]，其中 [[IMG:c16_img1.png]] 为失业率、p 为通胀率，而说明失业和通胀社会成本的损失函数为 [[IMG:c16_img2.png]]，请在给定预期通胀的情况下计算该经济的最优通胀水平。","options":null},"topics":["rules-discretion"],"answer_ref":"在 πe 给定下选择π最小化 L = un − a(π−πe) + gπ²。对π求导：dL/dπ = −a + 2gπ = 0 → 最优通胀 π* = a/(2g)。含义：菲利普斯曲线越陡（a越大）央行越倾向高通胀，通胀权重g越大则越低。"},{"num":78,"type":"sa","question":"The people of Country A believe that their regulators are committed to a zero inflation policy, while the people of Country B do not believe that their regulators are committed to a zero inflation policy. What difference does this make if regulators of both the countries announce a policy that will lower inflation?","options":null,"answer":null,"images":null,"translation":{"question":"A 国人民相信其监管者致力于零通胀政策，而 B 国人民不相信其监管者致力于零通胀政策。如果两国监管者都宣布一项将降低通胀的政策，这会造成什么差别？","options":null},"topics":["rules-discretion"],"answer_ref":"差别巨大：A国（可信）——宣布降通胀后预期立即下调，工资价格随之调整，通胀下降而失业几乎不升（低牺牲率）。B国（不可信）——公众按高通胀定价，要把通胀压下来必须长期维持衰退，失业显著高于自然率（高牺牲率）。宣布同样的政策，可信者事半功倍。"}]},{"num":17,"title":"Government Debt and Budget Deficits","questions":[{"num":1,"type":"mc","question":"When a government spends more than it collects in taxes, it runs a:","options":["trade deficit.","trade surplus.","budget surplus.","budget deficit."],"answer":"D","images":null,"translation":{"question":"当政府支出大于税收收入时，它出现：","options":["贸易逆差。","贸易顺差。","预算盈余。","预算赤字。"]},"topics":["debt-measure"]},{"num":2,"type":"mc","question":"Government debt equals the:","options":["difference between current government purchases and taxes.","difference between saving and investment.","sum of past budget deficits and surpluses.","M1 money supply."],"answer":"C","images":null,"translation":{"question":"政府债务等于：","options":["当期政府购买与税收之差。","储蓄与投资之差。","过去预算赤字与盈余之和。","M1货币供给。"]},"topics":["debt-measure"]},{"num":3,"type":"mc","question":"The amount by which government spending exceeds government revenues is called the ______, and the accumulation of past government borrowing is called the ______.","options":["deficit; debt","debt; deficit","devaluation; deflation","deflation; devaluation"],"answer":"A","images":null,"translation":{"question":"政府支出超过政府收入的数额称为 ______，过去政府借款的累积称为 ______。","options":["赤字；债务","债务；赤字","贬值；通货紧缩","通货紧缩；贬值"]},"topics":["debt-measure"]},{"num":4,"type":"mc","question":"If the debt of the U.S. federal government in 2016 was divided equally among the people in the United States, then the debt per person would equal approximately:","options":["$4,400.","$44,000.","$53,000.","$153,000."],"answer":"B","images":null,"translation":{"question":"若把2016年美国联邦政府的债务在美国人中平均分摊，则人均债务大约为：","options":["4,400美元。","44,000美元。","53,000美元。","153,000美元。"]},"topics":["debt-measure"]},{"num":5,"type":"mc","question":"Compared to the size of government debt as a percentage of GDP in other major industrial countries, the federal government of the United States:","options":["is one of the most heavily indebted governments.","has accumulated a relatively small debt.","has accumulated somewhat greater than average debt.","is one of the least indebted governments."],"answer":"C","images":null,"translation":{"question":"与其他主要工业国家政府债务占GDP的比重相比，美国联邦政府：","options":["是负债最重的政府之一。","积累的债务相对较小。","积累的债务略高于平均水平。","是负债最轻的政府之一。"]},"topics":["debt-measure"]},{"num":6,"type":"mc","question":"Historically, the primary cause of increases in government debt has been:","options":["printing too much money.","cutting taxes.","increasing interest rates.","financing wars."],"answer":"D","images":null,"translation":{"question":"历史上，政府债务增加的首要原因是：","options":["印钞过多。","减税。","提高利率。","为战争融资。"]},"topics":["debt-dynamics"]},{"num":7,"type":"mc","question":"The large increase in U.S. government debt between 1980 and 1995 was unusual because it occurred:","options":["during peacetime.","during an extended recessionary period.","without increased government spending.","without tax cuts."],"answer":"A","images":null,"translation":{"question":"1980至1995年间美国政府债务的大幅增加不同寻常，因为它发生在：","options":["和平时期。","一个漫长的衰退期。","政府支出没有增加的情况下。","没有减税的情况下。"]},"topics":["debt-dynamics"]},{"num":8,"type":"mc","question":"Holding other factors constant, the ratio of government debt to GDP can decrease as a result of any of the following changes except:","options":["decreases in government spending.","increases in GDP.","decreases in tax revenues.","decreases in transfer payments."],"answer":"C","images":null,"translation":{"question":"其他因素不变时，以下变化都能使政府债务占GDP的比重下降，除了：","options":["政府支出减少。","GDP增加。","税收收入减少。","转移支付减少。"]},"topics":["debt-dynamics"]},{"num":9,"type":"mc","question":"If government debt is not changing, then:","options":["the economy is at long-run equilibrium.","the government's budget must be balanced.","GDP must equal the natural rate of output.","capital per worker is constant."],"answer":"B","images":null,"translation":{"question":"若政府债务不变，则：","options":["经济处于长期均衡。","政府预算必定平衡。","GDP必定等于自然产出水平。","人均资本保持不变。"]},"topics":["debt-measure"]},{"num":10,"type":"mc","question":"The factors most responsible for forecasts of the U.S. government debt spiraling out of control in the next half century are the projected:","options":["slowdowns in the rates of technological change and human capital growth.","decrease in high-skilled domestic workers and the increase in immigration of low-skilled workers into the United States.","aging of the U.S. population and rising health care costs.","increase in international competition and the outsourcing of U.S. jobs."],"answer":"C","images":null,"translation":{"question":"导致预测美国未来半个世纪政府债务将失控的最主要因素是：","options":["技术进步与人力资本增长的放缓。","美国高技能国内劳动者减少、低技能移民增加。","美国人口老龄化与医疗成本上升。","国际竞争加剧与美国就业外包。"]},"topics":["debt-dynamics"]},{"num":11,"type":"mc","question":"An increase in the elderly population of a country affects fiscal policy most directly because:","options":["the elderly generally are not required to pay taxes.","governments provide pensions and health care for the elderly.","the elderly favor high interest rates on their savings.","governments spend more on education as the proportion of the elderly increases."],"answer":"B","images":null,"translation":{"question":"一国老年人口增加最直接地影响财政政策，因为：","options":["老年人通常不需要纳税。","政府为老年人提供养老金和医疗保健。","老年人偏好其储蓄获得高利率。","随着老年人比例增加，政府在教育上支出更多。"]},"topics":["debt-dynamics"]},{"num":12,"type":"mc","question":"In a time of inflation when the government budget is balanced in the conventional sense, the real (i.e., deflated) value of the government debt is:","options":["growing at the rate of inflation.","growing but at a rate less than the rate of inflation.","constant.","decreasing at the rate of inflation."],"answer":"D","images":null,"translation":{"question":"通胀时期，当按常规口径政府预算平衡时，政府债务的实际（即经通缩调整的）价值：","options":["以通胀率增长。","在增长但增速低于通胀率。","保持不变。","以通胀率下降。"]},"topics":["debt-measure"]},{"num":13,"type":"mc","question":"In a time of inflation when the real (i.e., deflated) value of the government debt is constant, the conventionally:","options":["reported government budget will show a deficit equal to the inflation rate times the outstanding debt.","reported government budget will show a deficit equal to less than the inflation rate times the outstanding debt.","reported government budget will be balanced.","measured government budget will show a surplus equal to the inflation rate times the outstanding debt."],"answer":"A","images":null,"translation":{"question":"通胀时期，当政府债务的实际价值不变时，常规口径报告的政府预算将显示：","options":["等于通胀率乘以未偿债务的赤字。","小于通胀率乘以未偿债务的赤字。","平衡的预算。","等于通胀率乘以未偿债务的盈余。"]},"topics":["debt-measure"]},{"num":14,"type":"mc","question":"Assume that the nominal interest rate is 11 percent, the inflation rate is 8 percent, and government debt at the beginning of the year equals $4 trillion. By how much is the government budget deficit overstated as a result of inflation?","options":["$0.12 trillion","$0.32 trillion","$0.44 trillion","$0.80 trillion"],"answer":"B","images":null,"translation":{"question":"假设名义利率为11%，通胀率为8%，年初政府债务为4万亿美元。由于通胀，政府预算赤字被高估了多少？","options":["0.12万亿美元。","0.32万亿美元。","0.44万亿美元。","0.80万亿美元。"]},"topics":["debt-measure"]},{"num":15,"type":"mc","question":"A deficit adjusted for inflation should include only government spending used to make _____ interest payments.","options":["real","nominal","foreign","domestic"],"answer":"A","images":null,"translation":{"question":"经通胀调整的赤字应只包括用于支付 ______ 利息的政府支出。","options":["实际","名义","对外","对内"]},"topics":["debt-measure"]},{"num":16,"type":"mc","question":"If the government debt, D, equals $5 trillion, the nominal interest rate is 7 percent, and the real interest rate is 3 percent, then nominal budget deficit overstates the real deficit by $ ___ trillion.","options":["0.35","0.20","0.15","0.07"],"answer":"B","images":null,"translation":{"question":"若政府债务 D 等于5万亿美元，名义利率为7%，实际利率为3%，则名义预算赤字比实际赤字高估 ______ 万亿美元。","options":["0.35","0.20","0.15","0.07"]},"topics":["debt-measure"]},{"num":17,"type":"mc","question":"Current measures of the U.S. federal government's budget deficit account for all of the following except:","options":["government expenditures.","government revenues.","changes in government indebtedness.","changes in government capital assets."],"answer":"D","images":null,"translation":{"question":"当前美国联邦政府预算赤字的衡量包括以下所有，除了：","options":["政府支出。","政府收入。","政府负债的变动。","政府资本资产的变动。"]},"topics":["debt-measure"]},{"num":18,"type":"mc","question":"If capital budgeting procedures were employed, then a budget deficit would be measured as:","options":["the sum of government debt.","the change in government debt.","the change in government debt minus the change in government capital assets.","the change in government capital assets."],"answer":"C","images":null,"translation":{"question":"若采用资本预算程序，则预算赤字应衡量为：","options":["政府债务之和。","政府债务的变动。","政府债务的变动减去政府资本资产的变动。","政府资本资产的变动。"]},"topics":["debt-measure"]},{"num":19,"type":"mc","question":"When the federal government incurs additional debt to acquire an asset, under current budgeting procedures the deficit ______, while under capital budgeting procedures the deficit ______.","options":["does not change; increases","increases; does not change","does not change; decreases","decreases; does not change"],"answer":"B","images":null,"translation":{"question":"当联邦政府为购置资产而增加债务时，按现行预算程序赤字 ______，而按资本预算程序赤字 ______。","options":["不变；增加","增加；不变","不变；减少","减少；不变"]},"topics":["debt-measure"]},{"num":20,"type":"mc","question":"Capital budgeting is a procedure that:","options":["adjusts the deficit for inflation.","estimates what the deficit would be if the economy were operating at the natural rate of output.","accounts for assets as well as liabilities.","measures the impact of fiscal policy on the lifetime incomes of individuals of different ages."],"answer":"C","images":null,"translation":{"question":"资本预算是一种程序，它：","options":["对赤字进行通胀调整。","估计经济在自然产出水平运行时赤字会是多少。","既核算资产也核算负债。","衡量财政政策对不同年龄个体一生收入的影响。"]},"topics":["debt-measure"]},{"num":21,"type":"mc","question":"Under capital budgeting, all of the following transactions would affect the federal budget deficit except the federal government's:","options":["sending a check to a welfare recipient.","sending a check to the state of Massachusetts.","selling a highway to the state of New York and using the proceeds to retire federal debt.","selling an office building."],"answer":"C","images":null,"translation":{"question":"在资本预算下，以下交易都会影响联邦预算赤字，除了联邦政府：","options":["向福利领取者寄出支票。","向马萨诸塞州寄出支票。","把一条公路卖给纽约州并用所得偿还联邦债务。","出售一栋办公楼。"]},"topics":["debt-measure"]},{"num":22,"type":"mc","question":"The amount the government would owe if a borrower were to default on a government-guaranteed loan is an example of:","options":["capital budgeting.","a contingent liability.","a cyclically adjusted liability.","Ricardian equivalence."],"answer":"B","images":null,"translation":{"question":"若借款人对政府担保贷款违约，政府将欠下的金额是 ______ 的一个例子：","options":["资本预算。","或有负债。","周期性调整负债。","李嘉图等价。"]},"topics":["debt-measure"]},{"num":23,"type":"mc","question":"The debt of the United States government is underreported in the view of many economists because all of the following liabilities are excluded except:","options":["future pensions of government employees.","debt owed to foreigners.","future Social Security benefits.","government guarantees of student loans."],"answer":"B","images":null,"translation":{"question":"许多经济学家认为美国政府债务被低估了，因为以下负债都被排除在外，除了：","options":["政府雇员未来的养老金。","欠外国人的债务。","未来的社会保障福利。","政府对学生贷款的担保。"]},"topics":["debt-measure"]},{"num":24,"type":"mc","question":"The cyclically adjusted budget deficit:","options":["adjusts the deficit for inflation.","estimates what the deficit would be if the economy were operating at the natural rate of output.","accounts for assets as well as liabilities.","measures the impact of fiscal policy on the lifetime incomes of individuals of different ages."],"answer":"B","images":null,"translation":{"question":"周期性调整的预算赤字：","options":["对赤字进行通胀调整。","估计经济在自然产出水平运行时赤字会是多少。","既核算资产也核算负债。","衡量财政政策对不同年龄个体一生收入的影响。"]},"topics":["debt-measure"]},{"num":25,"type":"mc","question":"Cyclically adjusted budgets are useful because they:","options":["systematically account for changes in government assets and liabilities.","reflect policy changes but not current economic conditions.","account for tax burdens on different generations of taxpayers.","correctly account for the impact of inflation on government indebtedness."],"answer":"B","images":null,"translation":{"question":"周期性调整的预算之所以有用，是因为它：","options":["系统地核算政府资产负债的变动。","反映政策变化而不反映当前经济状况。","核算不同代纳税人的税收负担。","正确核算通胀对政府负债的影响。"]},"topics":["debt-measure"]},{"num":26,"type":"mc","question":"Assume that a government has a balanced budget when the economy is at full employment. If the economy then enters a recession, with no change in tax or spending laws, then the budget of the government is most likely to:","options":["remain balanced.","be in deficit.","be in surplus.","be in either deficit or surplus, depending on the severity of the recession."],"answer":"B","images":null,"translation":{"question":"假设经济处于充分就业时政府预算平衡。若经济随后进入衰退，且税收和支出法律不变，则政府预算最可能：","options":["保持平衡。","出现赤字。","出现盈余。","视衰退的严重程度而出现赤字或盈余。"]},"topics":["debt-measure"]},{"num":27,"type":"mc","question":"Each of the following changes would allow the measured budget deficit to provide a truer picture of fiscal policy except:","options":["correcting for the effects of inflation.","offsetting changes in government liabilities with changes in government assets.","excluding some liabilities altogether.","correcting for the effects of the business cycle."],"answer":"C","images":null,"translation":{"question":"以下变化都能使衡量的预算赤字更真实地反映财政政策，除了：","options":["修正通胀的影响。","用政府资产的变动抵消政府负债的变动。","完全排除某些负债。","修正经济周期的影响。"]},"topics":["debt-measure"]},{"num":28,"type":"mc","question":"According to the traditional view of government debt, if taxes are cut without cutting government spending, then the long-run effects will be ______ steady-state capital and ______ consumption.","options":["higher; higher","lower; lower","higher; lower","lower; higher"],"answer":"B","images":null,"translation":{"question":"根据政府债务的传统观点，若减税而不削减政府支出，则长期效应将是稳态资本 ______、消费 ______。","options":["更高；更高","更低；更低","更高；更低","更低；更高"]},"topics":["ricardian"]},{"num":29,"type":"mc","question":"According to the traditional view of government debt, if taxes are cut without cutting government spending, then the short-run effects will be:","options":["higher output and lower unemployment.","higher output and higher unemployment.","no change in output or unemployment.","no change in output and higher unemployment."],"answer":"A","images":null,"translation":{"question":"根据政府债务的传统观点，若减税而不削减政府支出，则短期效应将是：","options":["产出更高、失业更低。","产出更高、失业更高。","产出与失业都不变。","产出不变、失业更高。"]},"topics":["ricardian"]},{"num":30,"type":"mc","question":"According to the traditional view of government debt, if taxes are cut without cutting government spending, then the international effect initially will be a capital ______ and a trade ______.","options":["inflow; deficit","inflow; surplus","outflow; deficit","outflow; surplus"],"answer":"A","images":null,"translation":{"question":"根据政府债务的传统观点，若减税而不削减政府支出，则国际效应最初将是资本 ______、贸易 ______。","options":["流入；逆差","流入；顺差","流出；逆差","流出；顺差"]},"topics":["ricardian"]},{"num":31,"type":"mc","question":"According to the traditional view of government debt, if taxes are cut without a cut in government spending, then in the United States this situation will lead to ______ net indebtedness on the part of the United States to foreign countries and ______ net exports.","options":["more; more","more; fewer","less; fewer","less; more"],"answer":"B","images":null,"translation":{"question":"根据政府债务的传统观点，若减税而不削减政府支出，则在美国这一情形将导致美国对外国 ______ 净负债、______ 净出口。","options":["更多；更多","更多；更少","更少；更少","更少；更多"]},"topics":["ricardian"]},{"num":32,"type":"mc","question":"According to the traditional viewpoint of government debt, a tax cut without a cut in government spending:","options":["stimulates consumer spending in the short run and reduces national saving.","stimulates consumer spending in the short run and reduces private saving.","has no effect on consumer spending but reduces national saving.","has no effect on consumer spending but reduces private saving."],"answer":"A","images":null,"translation":{"question":"根据政府债务的传统观点，减税而不削减政府支出：","options":["短期刺激消费者支出并减少国民储蓄。","短期刺激消费者支出并减少私人储蓄。","对消费者支出没有影响但减少国民储蓄。","对消费者支出没有影响但减少私人储蓄。"]},"topics":["ricardian"]},{"num":33,"type":"mc","question":"According to the traditional view of government debt (as in the Mundell–Fleming model), if taxes are cut without cutting government spending, then the short-run effects are a(n) ______ of the dollar and a(n) ______ in net exports.","options":["appreciation; increase","appreciation; decrease","depreciation; increase","depreciation; decrease"],"answer":"B","images":null,"translation":{"question":"根据政府债务的传统观点（如蒙代尔–弗莱明模型），若减税而不削减政府支出，则短期效应是美元 ______、净出口 ______。","options":["升值；增加","升值；减少","贬值；增加","贬值；减少"]},"topics":["ricardian"]},{"num":34,"type":"mc","question":"According to the traditional view of government debt (as in the IS–LM model), if taxes are cut without cutting government spending, then in the short run interest rates will ______, and investment will ______.","options":["increase; increase","increase; decrease","decrease; decrease","decrease; increase"],"answer":"B","images":null,"translation":{"question":"根据政府债务的传统观点（如 IS–LM 模型），若减税而不削减政府支出，则短期利率将 ______，投资将 ______。","options":["上升；增加","上升；减少","下降；减少","下降；增加"]},"topics":["ricardian"]},{"num":35,"type":"mc","question":"According to supply siders, tax cuts can raise total tax revenue if the tax cuts generate large enough:","options":["decrease in aggregate supply.","increase in aggregate supply.","decrease in the money supply.","increase in the money supply."],"answer":"B","images":null,"translation":{"question":"供给学派认为，若减税引起足够大的 ______，减税就能提高总税收收入：","options":["总供给减少。","总供给增加。","货币供给减少。","货币供给增加。"]},"topics":["ricardian"]},{"num":36,"type":"mc","question":"Government tax policy can affect aggregate supply as well as aggregate demand because changes in taxes change the:","options":["supply of money in the economy.","length of the inside lag of fiscal policy.","incentives to work and invest.","tradeoff between inflation and unemployment."],"answer":"C","images":null,"translation":{"question":"政府税收政策既影响总供给也影响总需求，因为税收变动改变：","options":["经济中的货币供给。","财政政策内在时滞的长度。","工作与投资的激励。","通胀与失业之间的权衡。"]},"topics":["ricardian"]},{"num":37,"type":"mc","question":"Ricardian equivalence refers to the same impact of financing government:","options":["whether by printing money or raising taxes.","in the long run as in the short run.","whether by debt or taxes.","in an open economy as in a closed economy."],"answer":"C","images":null,"translation":{"question":"李嘉图等价是指政府无论以 ______ 融资，其影响都相同：","options":["印钞还是增税。","长期还是短期。","债务还是税收。","开放经济还是封闭经济。"]},"topics":["ricardian"]},{"num":38,"type":"mc","question":"The logic of Ricardian equivalence implies that:","options":["tax cuts do not influence consumer spending but changes in government spending do.","neither tax cuts nor changes in government spending affect consumer spending.","tax cuts combined with future decreases in government spending will decrease consumer spending.","if the government cuts taxes and increases current government spending, consumer spending will increase."],"answer":"A","images":null,"translation":{"question":"李嘉图等价的逻辑意味着：","options":["减税不影响消费者支出，但政府支出的变动会影响。","减税和政府支出的变动都不影响消费者支出。","减税加上未来政府支出减少将减少消费者支出。","若政府减税并增加当期政府支出，消费者支出将增加。"]},"topics":["ricardian"]},{"num":39,"type":"mc","question":"According to the theory of Ricardian equivalence, if consumers are forward-looking, they will view a tax cut combined with no plans to reduce government spending as ______, so their consumption will ______.","options":["additional disposable income; increase","additional disposable income; remain unchanged","a rescheduling of taxes into the future; increase","a rescheduling of taxes into the future; remain unchanged"],"answer":"D","images":null,"translation":{"question":"根据李嘉图等价理论，若消费者具有前瞻性，他们会把减税加上不打算削减政府支出视为 ______，因此其消费将 ______。","options":["额外的可支配收入；增加","额外的可支配收入；保持不变","把税收推迟到未来；增加","把税收推迟到未来；保持不变"]},"topics":["ricardian"]},{"num":40,"type":"mc","question":"According to the theory of Ricardian equivalence, tax cuts combined with no plans to reduce government spending ______ public saving and ______ private saving.","options":["reduce; reduce","reduce; increase","increase; increase","increase; reduce"],"answer":"B","images":null,"translation":{"question":"根据李嘉图等价理论，减税加上不打算削减政府支出会 ______ 公共储蓄、______ 私人储蓄。","options":["减少；减少","减少；增加","增加；增加","增加；减少"]},"topics":["ricardian"]},{"num":41,"type":"mc","question":"A debt-financed tax cut will ______ saving in the traditional view and ______ saving in the view of Ricardian equivalence.","options":["increase; increase","decrease; decrease","decrease; increase","decrease; not change"],"answer":"D","images":null,"translation":{"question":"债务融资的减税在传统观点下会 ______ 储蓄，在李嘉图等价观点下会 ______ 储蓄。","options":["增加；增加","减少；减少","减少；增加","减少；不变"]},"topics":["ricardian"]},{"num":42,"type":"mc","question":"A debt-financed tax cut will ______ current consumption in the traditional view and ______ current consumption in the view of Ricardian equivalence.","options":["increase; increase","increase; decrease","increase; not change","decrease; decrease"],"answer":"C","images":null,"translation":{"question":"债务融资的减税在传统观点下会 ______ 当期消费，在李嘉图等价观点下会 ______ 当期消费。","options":["增加；增加","增加；减少","增加；不变","减少；减少"]},"topics":["ricardian"]},{"num":43,"type":"mc","question":"All of the following are arguments against Ricardian equivalence except:","options":["consumers make consumption decisions myopically.","consumers are rational and forward-looking in consumption decision-making.","consumers are borrowing constrained.","consumers do not expect future taxes to fall on them."],"answer":"B","images":null,"translation":{"question":"以下都是反对李嘉图等价的论据，除了：","options":["消费者做消费决策时是短视的。","消费者在消费决策中是理性的、前瞻的。","消费者受借贷约束。","消费者不预期未来税收会落在自己身上。"]},"topics":["ricardian"]},{"num":44,"type":"mc","question":"Suppose a household considers only current income in making consumption decisions. This is an example of:","options":["Ricardian equivalence.","the permanent-income hypothesis.","myopia.","the life-cycle model."],"answer":"C","images":null,"translation":{"question":"假设一个家庭在做消费决策时只考虑当期收入。这是 ______ 的一个例子：","options":["李嘉图等价。","永久收入假说。","短视。","生命周期模型。"]},"topics":["ricardian"]},{"num":45,"type":"mc","question":"In response to a tax cut, the consumption of a consumer who is borrowing constrained ______, whereas the consumption of a forward-looking, unconstrained consumer acting in accord with Ricardian equivalence ______.","options":["increases; increases","increases; remains unchanged","remains unchanged; remains unchanged","remains unchanged; increases"],"answer":"B","images":null,"translation":{"question":"面对减税，受借贷约束消费者的消费 ______，而按李嘉图等价行事的前瞻性、无约束消费者的消费 ______。","options":["增加；增加","增加；保持不变","保持不变；保持不变","保持不变；增加"]},"topics":["ricardian"]},{"num":46,"type":"mc","question":"When President George H. W. Bush lowered tax withholding in 1992 without lowering the amount of taxes owed, surveys showed that:","options":["almost everyone spent the higher take-home pay.","almost everyone saved the higher take-home pay.","a majority of respondents said they would spend the higher take-home pay, but a significant minority said they would save it.","a majority of respondents said they would save the higher take-home pay, but a significant minority said they would spend it."],"answer":"D","images":null,"translation":{"question":"当老布什（George H. W. Bush）总统1992年在不降低应纳税额的情况下降低预扣税时，调查显示：","options":["几乎所有人都花掉了更高的税后工资。","几乎所有人都储蓄了更高的税后工资。","多数受访者表示会花掉更高的税后工资，但少数人表示会储蓄。","多数受访者表示会储蓄更高的税后工资，但少数人表示会花掉。"]},"topics":["ricardian"]},{"num":47,"type":"mc","question":"Given a reduction in income tax withheld, but no change in income tax owed, households that act according to Ricardian equivalence would ______ the extra take-home pay, while those facing binding borrowing constraints would ______ the extra-take home pay.","options":["spend; spend","spend; save","save; save","save; spend"],"answer":"D","images":null,"translation":{"question":"在预扣所得税减少但应纳税额不变的情况下，按李嘉图等价行事的家庭会 ______ 额外的税后工资，而面临紧借贷约束的家庭会 ______ 额外的税后工资。","options":["花掉；花掉","花掉；储蓄","储蓄；储蓄","储蓄；花掉"]},"topics":["ricardian"]},{"num":48,"type":"mc","question":"Assume that nobody cares about the economic well-being of future generations. Then the Ricardian equivalence view of the effect of debt-financed tax cuts is:","options":["totally invalid.","still fully valid because the government has the option to levy taxes to pay off the full debt in just a few years.","still fully valid as long as the government cuts spending also.","still partially valid because most of the taxpayers will live and pay taxes for a substantial number of years after the tax cut."],"answer":"D","images":null,"translation":{"question":"假设没有人关心未来几代人的经济福利。那么关于债务融资减税效应的李嘉图等价观点：","options":["完全不成立。","仍然完全成立，因为政府可以选择在短短几年内征税偿还全部债务。","只要政府同时削减支出，就仍然完全成立。","仍然部分成立，因为大多数纳税人在减税后还会生活并纳税很多年。"]},"topics":["ricardian"]},{"num":49,"type":"mc","question":"In the United States, having a balanced budget is currently enforced for:","options":["the federal government.","no state governments.","all state governments.","many state governments."],"answer":"D","images":null,"translation":{"question":"在美国，目前平衡预算的要求适用于：","options":["联邦政府。","没有任何州政府。","所有州政府。","许多州政府。"]},"topics":["debt-dynamics"]},{"num":50,"type":"mc","question":"One reason for not requiring a balanced federal budget at all times is that with a balanced-budget rule:","options":["expenditures are not limited because, if the government wants to raise expenditures, it just raises taxes.","in a recession the automatic stabilizing powers of our system of taxes and transfers could not work.","the distorting features of the tax system are minimized.","it is possible to shift the burden of a war from current to future generations."],"answer":"B","images":null,"translation":{"question":"不要求联邦政府始终保持预算平衡的一个原因是，在平衡预算规则下：","options":["支出不受限制，因为政府想增加支出就可以增税。","衰退时税收与转移支付体系的自动稳定作用无法发挥。","税收体系的扭曲特征被最小化。","有可能把战争负担从当前一代转移到未来几代。"]},"topics":["debt-dynamics"]},{"num":51,"type":"mc","question":"Tax smoothing is a desirable policy because it:","options":["reduces the distortions of incentives caused by taxes.","reduces budget deficits in periods of recession.","eliminates the impact of automatic stabilizers.","is consistent with a balanced budget."],"answer":"A","images":null,"translation":{"question":"税收平滑（熨平税收）是一项可取的政策，因为它：","options":["减少税收造成的激励扭曲。","减少衰退时期的预算赤字。","消除自动稳定器的影响。","与平衡预算一致。"]},"topics":["debt-dynamics"]},{"num":52,"type":"mc","question":"One way to shift the tax burden from the current generation to future generations is to finance a war:","options":["by raising taxes.","by printing money.","by running a budget surplus.","by running a budget deficit."],"answer":"D","images":null,"translation":{"question":"把战争负担从当前一代转移到未来几代的一种方式是为战争融资：","options":["通过增税。","通过印钞。","通过实现预算盈余。","通过实现预算赤字。"]},"topics":["debt-dynamics"]},{"num":53,"type":"mc","question":"To minimize the disincentives of very high taxes, a policy of tax smoothing requires a budget ______ in years of unusually low government revenue and a budget ______ in years of unusually high government expenditures.","options":["surplus; deficit","deficit; surplus","surplus; surplus","deficit; deficit"],"answer":"D","images":null,"translation":{"question":"为了最小化极高税收造成的负激励，税收平滑政策要求在政府收入异常低的年份实行预算 ______，在政府支出异常高的年份实行预算 ______。","options":["盈余；赤字","赤字；盈余","盈余；盈余","赤字；赤字"]},"topics":["debt-dynamics"]},{"num":54,"type":"mc","question":"Using fiscal policy, including automatic stabilizers, to stabilize output over a business cycle is not consistent with:","options":["rational expectations.","inflation targeting.","the natural-rate hypothesis.","a strict balanced-budget rule."],"answer":"D","images":null,"translation":{"question":"利用财政政策（包括自动稳定器）在经济周期中稳定产出，与 ______ 不一致：","options":["理性预期。","通胀目标制。","自然率假说。","严格的平衡预算规则。"]},"topics":["debt-dynamics"]},{"num":55,"type":"mc","question":"Monetary policy is linked to fiscal policy when government spending is financed by:","options":["taxes.","borrowing from banks.","borrowing from foreigners.","printing money."],"answer":"D","images":null,"translation":{"question":"当政府支出通过 ______ 融资时，货币政策与财政政策联系在一起：","options":["税收。","向银行借款。","向外国人借款。","印钞。"]},"topics":["debt-dynamics"]},{"num":56,"type":"mc","question":"Financing a budget deficit by ______ leads to inflation, and inflation ______ the real value of government debt.","options":["issuing debt; increases","issuing debt; decreases","printing money; increases","printing money; decreases"],"answer":"D","images":null,"translation":{"question":"通过 ______ 为预算赤字融资会导致通胀，而通胀会 ______ 政府债务的实际价值。","options":["发行债务；增加","发行债务；减少","印钞；增加","印钞；减少"]},"topics":["debt-dynamics"]},{"num":57,"type":"mc","question":"Hyperinflations typically occur when governments:","options":["attempt to keep the unemployment rate below the natural rate.","finance spending with the inflation tax.","set inflation targets too high.","use discretionary monetary policy to stabilize output."],"answer":"B","images":null,"translation":{"question":"恶性通胀通常发生在政府 ______ 时：","options":["试图把失业率维持在自然率以下。","用通胀税为支出融资。","把通胀目标定得过高。","用相机抉择货币政策稳定产出。"]},"topics":["debt-dynamics"]},{"num":58,"type":"mc","question":"To force politicians to judge whether government spending is worth the costs, some economists have argued for:","options":["a balanced-budget rule for fiscal policy.","a constant money-growth rule for monetary policy.","avoiding the assumption of any contingent liabilities.","the application of Ricardian equivalence."],"answer":"A","images":null,"translation":{"question":"为了迫使政治家判断政府支出是否物有所值，一些经济学家主张：","options":["对财政政策实行平衡预算规则。","对货币政策实行货币增长不变的规则。","避免承担任何或有负债。","应用李嘉图等价。"]},"topics":["debt-dynamics"]},{"num":59,"type":"mc","question":"The possibility of capital flight is likely to be greater at higher levels of government debt because there is a greater:","options":["temptation to default on the debt.","likelihood that the government will begin issuing indexed bonds.","probability that a balanced budget will be adopted by the government.","potential for tax smoothing policies to be eliminated."],"answer":"A","images":null,"translation":{"question":"政府债务水平越高，资本外逃的可能性越大，因为：","options":["债务违约的诱惑更大。","政府开始发行指数化债券的可能性更大。","政府采纳平衡预算的可能性更大。","税收平滑政策被取消的可能性更大。"]},"topics":["debt-dynamics"]},{"num":60,"type":"mc","question":"High levels of government debt that raise investors' fear of a government default on debt will result in capital ______ and a(n) ______ of the country's exchange rate.","options":["outflows; depreciation","outflows; appreciation","inflows; depreciation","inflows; appreciation"],"answer":"A","images":null,"translation":{"question":"高水平的政府债务使投资者担心政府债务违约，将导致资本 ______、该国汇率 ______。","options":["外流；贬值","外流；升值","流入；贬值","流入；升值"]},"topics":["debt-dynamics"]},{"num":61,"type":"sa","question":"Compare the traditional view versus the view of Ricardian equivalence of the effects of a debt-financed tax cut on: a. national saving. b. current consumption. c. the real interest rate.","options":null,"answer":null,"images":null,"translation":{"question":"比较传统观点与李嘉图等价观点对债务融资减税在以下方面效应的不同看法：a. 国民储蓄。b. 当期消费。c. 实际利率。","options":null},"topics":["ricardian"],"answer_ref":"a. 国民储蓄：传统观点——减税刺激当前消费，国民储蓄下降；李嘉图等价——家庭把减税额全部存起来以备未来缴税，私人储蓄增量恰好等于公共储蓄减量，国民储蓄不变。b. 当前消费：传统观点上升；李嘉图等价不变。c. 实际利率：传统观点上升；李嘉图等价不变。"},{"num":62,"type":"sa","question":"Many people are concerned about the budget deficit of the U.S. federal government. Suggest at least three possible negative economic effects of a budget deficit and three possible economic benefits of a budget deficit.","options":null,"answer":null,"images":null,"translation":{"question":"许多人担心美国联邦政府的预算赤字。请至少提出预算赤字的三种可能的负面经济效应和三种可能的经济收益。","options":null},"topics":["ricardian"],"answer_ref":"负面影响：① 减少国民储蓄→利率上升、挤出私人投资，资本积累放慢；② 把税负转嫁未来世代，代际不公；③ 债务累积可能引发财政危机、通胀或违约风险。正面作用：① 实现税收平滑——战争/衰退时以债代税，避免畸高税率扭曲经济；② 减税改善工作与投资的激励（供给效应）；③ 衰退期赤字自动稳定总需求。"},{"num":63,"type":"sa","question":"The U.S. Treasury reports the budget deficit or surplus of the federal government. Give at least one reason why the measured budget deficit might overstate the “true” deficit and at least one reason the measured figure might understate the “true” deficit.","options":null,"answer":null,"images":null,"translation":{"question":"美国财政部报告联邦政府的预算赤字或盈余。请给出至少一个衡量出的预算赤字可能高估“真实”赤字的原因，以及至少一个衡量数值可能低估“真实”赤字的原因。","options":null},"topics":["debt-measure"],"answer_ref":"高估真实赤字的理由：通胀——名义利息支付夸大了债务的实际成本，按实际利率计算赤字应下调；政府持有资产（如国有资产）可抵减债务。低估真实赤字的理由：隐性负债未入账——未来社会保障、医疗保险待遇支付的现值、政府担保与养老金义务都不计入官方赤字。"},{"num":64,"type":"sa","question":"Explain how tax cuts can affect both aggregate demand and aggregate supply.","options":null,"answer":null,"images":null,"translation":{"question":"解释减税如何同时影响总需求和总供给。","options":null},"topics":["ricardian"],"answer_ref":"对总需求：减税→可支配收入↑→消费↑→IS/AD 右移，短期产出与价格上升。对总供给：降低边际税率提高工作、储蓄、投资的税后回报→劳动供给与资本积累增加→长期总供给（潜在产出）右移。需求效应短期见效，供给效应长期更重要。"},{"num":65,"type":"sa","question":"What is Ricardian equivalence? Give at least three reasons Ricardian equivalence might not correctly describe an economy.","options":null,"answer":null,"images":null,"translation":{"question":"什么是李嘉图等价？请至少给出三个李嘉图等价可能无法正确描述经济的理由。","options":null},"topics":["ricardian"],"answer_ref":"李嘉图等价：债务融资的减税不改变消费与国民储蓄——家庭预期未来加税，把减税额作为储蓄留给后代缴税。其可能失效的理由：① 借贷约束——受流动性约束的家庭会花掉减税；② 短视与有限生命——当代人不把后代税负完全内生化；③ 代际再分配预期——未来税落在别人头上；④ 税收是扭曲性的，未来税种与税率不确定。"},{"num":66,"type":"sa","question":"Graphically illustrate the traditional view of the short-run impacts of a debt-financed tax cut on: a. interest rates and output in a closed economy in the short run, using the IS–LM model. b. exchange rates and output in a small open economy with a flexible exchange rate in the short run, using the Mundell–Fleming model.","options":null,"answer":null,"images":null,"translation":{"question":"用图形说明传统观点下债务融资减税的短期影响：a. 用 IS–LM 模型说明封闭经济短期内的利率与产出。b. 用蒙代尔–弗莱明模型说明浮动汇率的小型开放经济短期内的汇率与产出。","options":null},"topics":["ricardian"],"answer_ref":"a. 封闭经济短期（IS-LM）：减税→IS 右移：Y↑、r↑；利率上升挤出部分私人投资。b. 小国浮动汇率（蒙代尔-弗莱明）：减税→IS* 右移：利率被世界利率钉住，本币升值（ε↑），净出口完全挤出——产出Y不变。两种情形下利率渠道不同，开放经济下汇率替利率承担调整。"},{"num":67,"type":"sa","question":"Graphically illustrate the traditional view of the long-run impacts of a debt-financed tax cut on: a. saving, investment, and real interest rate using the classical model (Chapter 3). b. steady state capital per worker and output per worker using the Solow growth model.","options":null,"answer":null,"images":null,"translation":{"question":"用图形说明传统观点下债务融资减税的长期影响：a. 用古典模型（第3章）说明储蓄、投资与实际利率。b. 用索洛增长模型说明稳态人均资本与人均产出。","options":null},"topics":["ricardian"],"answer_ref":"a. 古典模型：T↓、G不变→国民储蓄S↓→可贷资金供给左移→r↑→I↓——投资被一对一挤出。b. 索洛模型：国民储蓄率下降→稳态人均资本 k*↓、人均产出 y*↓——债务融资的减税挤掉了资本积累，长期生活水平更低。"},{"num":68,"type":"sa","question":"Using the model of aggregate demand–aggregate supply to illustrate the traditional view, graphically compare the short-run and long-run impact of debt-financed tax cuts on: a. output. b. prices.","options":null,"answer":null,"images":null,"translation":{"question":"用总需求–总供给模型说明传统观点，用图形比较债务融资减税对以下方面的短期和长期影响：a. 产出。b. 价格。","options":null},"topics":["ricardian"],"answer_ref":"a. 产出：短期上升（AD 右移，价格粘性）；长期回到自然率——工资价格调整后 SRAS 左移，产出复原。b. 价格：短期随需求上升；长期进一步上升后稳定在新的更高水平。图：E₀→E₁（短期Y↑P↑）→E₂（长期Y=Y*，P更高）。"},{"num":69,"type":"sa","question":"War is the generator of debt burden for countries. How does war generate debt for a country?","options":null,"answer":null,"images":null,"translation":{"question":"战争是国家债务负担的制造者。战争如何为一国制造债务？","options":null},"topics":["debt-dynamics"],"answer_ref":"战争使政府支出激增而税收难以同步提高（战时加税空间有限），财政缺口只能靠举债填补；同时战争破坏税基（生产萎缩）、降低税收。历史上大规模战争（如二战）几乎都伴随债务率飙升——战争是政府债务最主要的生成器。"},{"num":70,"type":"sa","question":"A country with total debt of $500 million has a nominal interest rate of 10 percent and a real interest rate of 6 percent. Is the budget deficit of the country underestimated or overestimated, and by how much?","options":null,"answer":null,"images":null,"translation":{"question":"某国总债务为5亿美元，名义利率为10%，实际利率为6%。该国的预算赤字是被低估还是高估了？高估（或低估）了多少？","options":null},"topics":["debt-measure"],"answer_ref":"通胀率 = 名义利率 − 实际利率 = 10% − 6% = 4%。官方（名义）赤字高估了真实（实际）赤字，高估额 = 通胀率×债务总额 = 4%×5亿 = 2,000万美元。真实赤字 = 名义赤字 − 2,000万。"},{"num":71,"type":"sa","question":"The government of Moneyland decides that it is not going to change its spending but will decrease the taxes. According to the theory of Ricardian equivalence, what will be the effects of the government action on national saving?","options":null,"answer":null,"images":null,"translation":{"question":"货币国（Moneyland）政府决定不改变支出，但将减税。根据李嘉图等价理论，这一政府行为对国民储蓄有什么影响？","options":null},"topics":["ricardian"],"answer_ref":"按李嘉图等价：支出不变、减税→公众预期未来加税，把减税所得全部储蓄→私人储蓄增加量恰好等于公共储蓄减少量→国民储蓄不变，利率与投资也不变。政府行动的效果只是改变了储蓄的部门构成。"},{"num":72,"type":"sa","question":"\"The baby-boom generation is responsible for pushing the U.S. economy into more debt.\" Is this statement true or false? Give reasons supporting your answer.","options":null,"answer":null,"images":null,"translation":{"question":"“婴儿潮一代是使美国经济负债更多的罪魁祸首。”这一说法是对还是错？请给出支持你答案的理由。","options":null},"topics":["debt-dynamics"],"answer_ref":"说法过于简单化：赤字源于支出大于收入的政府选择，而非某一代人\"造成\"。不过有合理成分：婴儿潮一代退休使社保与医保支出（隐性负债）激增，在税收不变时会推高赤字。但根源是制度承诺与收支政策，把责任归于一代人不准确——国会随时可以调整福利与税收。"},{"num":73,"type":"sa","question":"Spending more than earning will always cause a deficit in the budget and is always considered a bad thing. Is there a possibility that a budget deficit in any economy can have some advantages, too? Give two examples of these advantages, if any.","options":null,"answer":null,"images":null,"translation":{"question":"支出大于收入总会导致预算赤字，且总被认为是坏事。任何一个经济体的预算赤字是否也可能有一些好处？如果有，请给出两个这种好处的例子。","options":null},"topics":["debt-dynamics"],"answer_ref":"可以，有两例：① 税收平滑——战争或大萧条期间以赤字融资代替骤增税收，避免税率剧烈波动造成的效率损失；② 逆周期稳定——衰退期赤字（自动或相机）支撑总需求、托底就业，繁荣期自然回收。赤字在正确的时间（衰退）与理由（平滑/稳定）下是政策工具而非坏事。"},{"num":74,"type":"sa","question":"In 2014, the United States had budget deficit of $483 billion. Some economists say that this deficit is understated. Why do they say this?","options":null,"answer":null,"images":null,"translation":{"question":"2014年，美国有4,830亿美元的预算赤字。一些经济学家说这一赤字被低估了。他们为什么这样说？","options":null},"topics":["debt-measure"],"answer_ref":"因为官方赤字是现金口径，漏掉了随婴儿潮退休而快速累积的社保、医疗保险隐性负债（未来支付的现值），也不含政府担保等或有负债；同时部分支出（如某些基建投资）被当消费而非资产形成。把这些计入，真实财政缺口远大于4,830亿。"},{"num":75,"type":"sa","question":"Printing money increases inflation. The higher the inflation, the lower the real value of debt. So why is this method not used to pay debts?","options":null,"answer":null,"images":null,"translation":{"question":"印钞会推高通胀。通胀越高，债务的实际价值越低。那么为什么不用这种方法来偿还债务呢？","options":null},"topics":["debt-dynamics"],"answer_ref":"因为通胀本质上是对持币者征税且代价高昂：① 通胀税任意侵蚀居民购买力；② 名义利率按费雪效应上升，债权人要求补偿，债务成本反而攀升；③ 产生鞋底成本、菜单成本、相对价格与税收扭曲；④ 破坏央行可信度与币值稳定。一旦预期形成，印钞偿债失效——这不是免费的午餐，而是对整个经济的隐性课税。"}]},{"num":18,"title":"The Financial System","questions":[{"num":1,"type":"mc","question":"The financial system refers to the:","options":["mechanism that transfers wealth from consumers to corporations.","institutions that facilitate the flow of funds between savers and investors.","technology that allows money to circulate in the economy.","government regulations that govern the terms of borrowing and lending."],"answer":"B","images":null,"translation":{"question":"金融体系是指：","options":["把财富从消费者转移给企业的机制。","促进储蓄者与投资者之间资金流动的机构。","使货币在经济中流通的技术。","规范借贷条款的政府法规。"]},"topics":["financial-system"]},{"num":2,"type":"mc","question":"The allocation of resources between those who want to save and those who want to borrow is accomplished through:","options":["the velocity of money.","fiscal policy.","the financial system.","foreign trade."],"answer":"C","images":null,"translation":{"question":"想储蓄者与想借款者之间的资源配置是通过 ______ 完成的：","options":["货币流通速度。","财政政策。","金融体系。","对外贸易。"]},"topics":["financial-system"]},{"num":3,"type":"mc","question":"Funds flow directly between savers and investors in financial _____ and flow indirectly between savers and investors through financial _____.","options":["stocks; bonds","intermediaries; markets","bonds; stocks","markets; intermediaries"],"answer":"D","images":null,"translation":{"question":"资金在金融 ______ 中直接地在储蓄者与投资者之间流动，并通过金融 ______ 间接地在储蓄者与投资者之间流动。","options":["股票；债券","中介机构；市场","债券；股票","市场；中介机构"]},"topics":["financial-system"]},{"num":4,"type":"mc","question":"A document representing an interest-bearing debt of the issuer, usually a corporation or government, is called:","options":["equity.","stock.","a bond.","capital."],"answer":"C","images":null,"translation":{"question":"代表发行者（通常是企业或政府）付息债务的凭证被称为：","options":["股权。","股票。","债券。","资本。"]},"topics":["financial-system"]},{"num":5,"type":"mc","question":"A bond (or debt instrument) is a(n):","options":["ownership claim by the shareholder of a firm.","loan to a firm.","ongoing relationship between customers and a firm.","legal restriction on products a firm may produce."],"answer":"B","images":null,"translation":{"question":"债券（或债务工具）是：","options":["企业股东的股权主张。","对企业的贷款。","客户与企业之间的持续关系。","对企业可生产产品的法律限制。"]},"topics":["financial-system"]},{"num":6,"type":"mc","question":"Stocks are:","options":["loans to a firm.","assets plus liabilities of a firm.","leverage in a firm.","shares of ownership in a firm."],"answer":"D","images":null,"translation":{"question":"股票是：","options":["对企业的贷款。","企业的资产加负债。","企业的杠杆。","企业所有权的份额。"]},"topics":["financial-system"]},{"num":7,"type":"mc","question":"Purchasers of bonds issued by companies are _____ of the company, while purchasers of shares of stock issued by a company are _____ of the company.","options":["creditors; debtors","debtors; creditors","creditors; partial owners","partial owners; debtors"],"answer":"C","images":null,"translation":{"question":"购买企业发行的债券者是企业的 ______，而购买企业发行的股票者是企业的 ______。","options":["债权人；债务人","债务人；债权人","债权人；部分所有者","部分所有者；债务人"]},"topics":["financial-system"]},{"num":8,"type":"mc","question":"Issuing bonds is called _____ financing, while issuing stocks is called _____ financing.","options":["debt; equity","equity; debt","capital; investment","private; public"],"answer":"A","images":null,"translation":{"question":"发行债券称为 ______ 融资，而发行股票称为 ______ 融资。","options":["债务；股权","股权；债务","资本；投资","私人；公开"]},"topics":["financial-system"]},{"num":9,"type":"mc","question":"Obtaining funds for a business by borrowing through the bond market is called _____ finance.","options":["money","liability","debt","equity"],"answer":"C","images":null,"translation":{"question":"通过债券市场借款为企业融资称为 ______ 融资。","options":["货币","负债","债务","股权"]},"topics":["financial-system"]},{"num":10,"type":"mc","question":"Obtaining funds for a business by issuing ownership shares through the stock market is called _____ finance.","options":["money","liability","debt","equity"],"answer":"D","images":null,"translation":{"question":"通过股票市场发行所有权份额为企业融资称为 ______ 融资。","options":["货币","负债","债务","股权"]},"topics":["financial-system"]},{"num":11,"type":"mc","question":"Institutions that stand between savers and investors, helping to direct financial resources to their best use, are called:","options":["financial markets.","financial intermediaries.","financial regulators.","financial capitalists."],"answer":"B","images":null,"translation":{"question":"处于储蓄者与投资者之间、帮助把金融资源配置到最佳用途的机构被称为：","options":["金融市场。","金融中介。","金融监管机构。","金融资本家。"]},"topics":["financial-system"]},{"num":12,"type":"mc","question":"All of the following are examples of financial intermediaries except:","options":["commercial banks.","stock exchanges.","pension funds.","insurance companies."],"answer":"B","images":null,"translation":{"question":"以下都是金融中介的例子，除了：","options":["商业银行。","证券交易所。","养老基金。","保险公司。"]},"topics":["financial-system"]},{"num":13,"type":"mc","question":"A dislike of randomness in economic circumstances is called:","options":["rational expectations.","risk aversion.","adverse selection.","moral hazard."],"answer":"B","images":null,"translation":{"question":"对经济处境中随机性的厌恶被称为：","options":["理性预期。","风险厌恶。","逆向选择。","道德风险。"]},"topics":["risk-diversification"]},{"num":14,"type":"mc","question":"Reducing risk by holding many imperfectly correlated assets is called:","options":["diversification.","moral hazard.","risk aversion.","leveraging."],"answer":"A","images":null,"translation":{"question":"通过持有许多不完全相关的资产来降低风险被称为：","options":["分散化。","道德风险。","风险厌恶。","加杠杆。"]},"topics":["risk-diversification"]},{"num":15,"type":"mc","question":"Risk that affects many businesses at the same time is called _____ risk, while risk associated with individual businesses is called _____ risk.","options":["asymmetric; symmetric","symmetric; asymmetric","systematic; idiosyncratic","idiosyncratic; systematic"],"answer":"C","images":null,"translation":{"question":"同时影响许多企业的风险称为 ______ 风险，而与单个企业相关的风险称为 ______ 风险。","options":["不对称；对称","对称；不对称","系统性；特有（非系统性）","特有（非系统性）；系统性"]},"topics":["risk-diversification"]},{"num":16,"type":"mc","question":"Diversification allows savers to largely eliminate:","options":["risk aversion.","idiosyncratic risk.","systematic risk.","risk premiums."],"answer":"B","images":null,"translation":{"question":"分散化使储蓄者能够基本消除：","options":["风险厌恶。","特有风险（非系统性风险）。","系统性风险。","风险溢价。"]},"topics":["risk-diversification"]},{"num":17,"type":"mc","question":"Financial intermediaries that sell shares to savers and use their funds to buy diversified pools of assets are called:","options":["pension funds.","insurance companies.","mutual funds.","commercial banks."],"answer":"C","images":null,"translation":{"question":"向储蓄者出售份额、并用其资金购买分散化资产组合的金融中介被称为：","options":["养老基金。","保险公司。","共同基金。","商业银行。"]},"topics":["financial-system"]},{"num":18,"type":"mc","question":"Two types of problems that arise due to asymmetric information are:","options":["systematic risk and idiosyncratic risk.","risk aversion and diversification","illiquidity and insolvency.","moral hazard and adverse selection."],"answer":"D","images":null,"translation":{"question":"由信息不对称引起的两类问题是：","options":["系统性风险与特有风险。","风险厌恶与分散化。","流动性不足与资不抵债。","道德风险与逆向选择。"]},"topics":["asymmetric-information"]},{"num":19,"type":"mc","question":"A situation in which one party to an economic transaction has more knowledge about the transaction than the other is called:","options":["risk aversion.","asymmetric information.","systematic risk","learning by doing."],"answer":"B","images":null,"translation":{"question":"经济交易的一方比另一方更了解该交易的情形被称为：","options":["风险厌恶。","信息不对称。","系统性风险。","干中学。"]},"topics":["asymmetric-information"]},{"num":20,"type":"mc","question":"Adverse selection concerns hidden knowledge about _____, while moral hazard concerns hidden knowledge about _____.","options":["systematic risk; idiosyncratic risk","attributes; actions","equity finance; debt finance","financial markets; financial intermediaries"],"answer":"B","images":null,"translation":{"question":"逆向选择涉及关于 ______ 的隐藏信息，而道德风险涉及关于 ______ 的隐藏信息。","options":["系统性风险；特有风险","特征（属性）；行为","股权融资；债务融资","金融市场；金融中介"]},"topics":["asymmetric-information"]},{"num":21,"type":"mc","question":"Adverse selection may cause lenders to be offered opportunities to finance only:","options":["the most desirable business ventures.","less desirable business ventures.","risk-free business ventures.","diversified business ventures."],"answer":"B","images":null,"translation":{"question":"逆向选择可能导致贷款人只被提供为 ______ 融资的机会：","options":["最理想的商业项目。","不太理想的商业项目。","无风险的商业项目。","分散化的商业项目。"]},"topics":["asymmetric-information"]},{"num":22,"type":"mc","question":"The risk that imperfectly monitored agents will act in dishonest or otherwise inappropriate ways is called:","options":["adverse selection.","moral hazard.","systematic risk.","risk aversion."],"answer":"B","images":null,"translation":{"question":"被监督不充分的代理人会以不诚实或其他不当方式行事的风险被称为：","options":["逆向选择。","道德风险。","系统性风险。","风险厌恶。"]},"topics":["asymmetric-information"]},{"num":23,"type":"mc","question":"When a borrower uses borrowed funds to engage in activities that are detrimental to the profitability of the business venture that was financed, there is a problem of:","options":["adverse selection.","moral hazard.","systematic risk.","risk aversion."],"answer":"B","images":null,"translation":{"question":"当借款人用借来的资金从事有损于所融资商业项目盈利能力的活动时，就存在 ______ 问题：","options":["逆向选择。","道德风险。","系统性风险。","风险厌恶。"]},"topics":["asymmetric-information"]},{"num":24,"type":"mc","question":"Which of the following is an example of moral hazard?","options":["The healthiest people buy life insurance.","The sickest people buy health insurance.","A person with health insurance rides a motorcycle without wearing a helmet.","A person with life insurance exercises daily and eats healthy foods."],"answer":"C","images":null,"translation":{"question":"以下哪个是道德风险的例子？","options":["最健康的人买人寿保险。","病得最重的人买健康保险。","有健康保险的人不戴头盔骑摩托车。","有人寿保险的人每天锻炼并吃健康食物。"]},"topics":["asymmetric-information"]},{"num":25,"type":"mc","question":"Which of the following is an example of adverse selection?","options":["A careful driver buys extra insurance protection when renting a car.","The sickest people buy health insurance.","A person with health insurance rides a motorcycle without wearing a helmet.","A person with life insurance exercises daily and eats healthy foods."],"answer":"B","images":null,"translation":{"question":"以下哪个是逆向选择的例子？","options":["谨慎的司机租车时购买额外的保险保障。","病得最重的人买健康保险。","有健康保险的人不戴头盔骑摩托车。","有人寿保险的人每天锻炼并吃健康食物。"]},"topics":["asymmetric-information"]},{"num":26,"type":"mc","question":"Banks help mitigate the problem of moral hazard in lending by:","options":["requiring lengthy applications for loans.","making loans to many different types of borrowers.","adjusting the amount of the loan to fit the requirements of the borrower.","monitoring the business after a loan is made to the business."],"answer":"D","images":null,"translation":{"question":"银行通过 ______ 帮助缓解贷款中的道德风险问题：","options":["要求冗长的贷款申请。","向许多不同类型的借款人放贷。","调整贷款金额以符合借款人的要求。","在贷款发放给企业后对企业进行监督。"]},"topics":["asymmetric-information"]},{"num":27,"type":"mc","question":"Banks help mitigate the problem of adverse selection in lending by:","options":["developing expertise in evaluating the business prospects of loan applicants.","making loans to many different types of borrowers.","adjusting the amount of the loan to fit the requirements of the borrower.","monitoring the business after a loan is made to the business."],"answer":"A","images":null,"translation":{"question":"银行通过 ______ 帮助缓解贷款中的逆向选择问题：","options":["培养评估贷款申请人商业前景的专业能力。","向许多不同类型的借款人放贷。","调整贷款金额以符合借款人的要求。","在贷款发放给企业后对企业进行监督。"]},"topics":["asymmetric-information"]},{"num":28,"type":"mc","question":"A well-functioning financial system does all of the following except:","options":["foster economic growth by directing savings to its most productive use.","allocate risk among market participants.","eliminate systematic risk through diversification.","direct resources from savers to borrowers."],"answer":"C","images":null,"translation":{"question":"运转良好的金融体系能做到以下所有，除了：","options":["把储蓄引导到最有效率的使用上以促进经济增长。","在市场参与者之间分配风险。","通过分散化消除系统性风险。","把资源从储蓄者引导到借款人。"]},"topics":["financial-system"]},{"num":29,"type":"mc","question":"Governments can reduce the problem of moral hazard by:","options":["requiring licenses be obtained before starting a business.","prosecuting fraud and malfeasance.","keeping interest rates low.","reducing corporate income tax rates."],"answer":"B","images":null,"translation":{"question":"政府可以通过 ______ 减少道德风险问题：","options":["要求创业前获得执照。","起诉欺诈和渎职行为。","保持低利率。","降低企业所得税税率。"]},"topics":["asymmetric-information"]},{"num":30,"type":"mc","question":"Governments can reduce the problem of adverse selection by:","options":["requiring disclosure about investment projects and a firm's finances.","providing loans from public funds.","keeping interest rates low.","reducing corporate income tax rates."],"answer":"A","images":null,"translation":{"question":"政府可以通过 ______ 减少逆向选择问题：","options":["要求披露投资项目和企业财务状况。","用公共资金提供贷款。","保持低利率。","降低企业所得税税率。"]},"topics":["asymmetric-information"]},{"num":31,"type":"mc","question":"A major disruption in the financial system that impedes the economy's ability to intermediate between those who want to save and those who want to borrow and invest is called a:","options":["moral hazard.","speculative bubble.","financial crisis.","stagflation."],"answer":"C","images":null,"translation":{"question":"金融体系中阻碍经济在储蓄者与借贷投资者之间进行中介的重大扰乱被称为：","options":["道德风险。","投机泡沫。","金融危机。","滞胀。"]},"topics":["financial-crisis"]},{"num":32,"type":"mc","question":"A rise in the price of an asset above its fundamental value is called a(n):","options":["financial panic.","insolvency.","liquidity crisis","speculative bubble."],"answer":"D","images":null,"translation":{"question":"资产价格上升到其基本面价值之上被称为：","options":["金融恐慌。","资不抵债。","流动性危机。","投机泡沫。"]},"topics":["financial-crisis"]},{"num":33,"type":"mc","question":"An asset-price bubble bursts if there is:","options":["a panic cycle of asset sales and falling asset prices.","a statement from the central bank stating that the bubble is over.","an excess demand for an asset that raises asset prices.","a sharp decrease in interest rates that pricks the asset-price bubble."],"answer":"A","images":null,"translation":{"question":"若出现 ______，资产价格泡沫就会破裂：","options":["资产抛售与资产价格下跌的恐慌循环。","央行关于泡沫已结束的声明。","推高资产价格的资产超额需求。","刺破资产价格泡沫的利率大幅下降。"]},"topics":["financial-crisis"]},{"num":34,"type":"mc","question":"The asset price that experienced a boom prior to the 2008–2009 recession was the price of:","options":["oil.","residential real estate.","technology stocks.","food."],"answer":"B","images":null,"translation":{"question":"在2008–2009年衰退之前经历繁荣的资产价格是 ______ 的价格：","options":["石油。","住宅房地产。","科技股。","食品。"]},"topics":["financial-crisis"]},{"num":35,"type":"mc","question":"The housing price boom prior to the 2008–2009 recession was fueled by all of the following except:","options":["unusually large increases in building material costs.","lax lending standards.","government policies promoting homeownership.","homebuyers' expectations of never-declining home prices."],"answer":"A","images":null,"translation":{"question":"2008–2009年衰退之前的房价繁荣由以下所有因素推动，除了：","options":["建筑材料成本异常大幅上涨。","宽松的放贷标准。","政府促进拥有住房的政策。","购房者对房价永不下跌的预期。"]},"topics":["financial-crisis"]},{"num":36,"type":"mc","question":"Subprime borrowers are borrowers:","options":["who obtain loans at interest rates below the prime rate.","most likely to make their loan payments on time.","with risky credit profiles.","who borrow to purchase smaller homes."],"answer":"C","images":null,"translation":{"question":"次级借款人是指：","options":["以低于优惠利率的利率获得贷款的借款人。","最有可能按时偿还贷款的借款人。","信用状况有风险的借款人。","借款购买较小住房的借款人。"]},"topics":["financial-crisis"]},{"num":37,"type":"mc","question":"Falling house prices generate widespread insolvency of financial institutions by:","options":["reducing the value of collateral assets.","reducing the value of liabilities.","increasing the value of assets.","increasing capital."],"answer":"A","images":null,"translation":{"question":"房价下跌通过 ______ 使金融机构普遍资不抵债：","options":["降低抵押资产的价值。","降低负债的价值。","提高资产的价值。","增加资本。"]},"topics":["financial-crisis"]},{"num":38,"type":"mc","question":"The precipitous fall in the price of assets that takes place when financial institutions must sell their assets quickly in the midst of a crisis is called a(n):","options":["insolvency.","subprime sale","speculative bubble.","fire sale."],"answer":"D","images":null,"translation":{"question":"金融危机中金融机构不得不迅速抛售资产时所发生的资产价格骤跌被称为：","options":["资不抵债。","次级出售。","投机泡沫。","抛售（fire sale）。"]},"topics":["financial-crisis"]},{"num":39,"type":"mc","question":"The mortgage defaults during the 2008–2009 financial crisis severely reduced the capital positions of:","options":["major investment banks.","government-sponsored enterprises involved in the mortgage market.","a large insurance company (AIG).","all of the above."],"answer":"D","images":null,"translation":{"question":"2008–2009年金融危机期间的抵押贷款违约严重削弱了 ______ 的资本状况：","options":["主要投资银行。","参与抵押贷款市场的政府支持企业。","一家大型保险公司（AIG）。","以上全部。"]},"topics":["financial-crisis"]},{"num":40,"type":"mc","question":"One avenue by which a loss of confidence in one financial institution spreads to another financial institution is through:","options":["a steep decline in asset prices driven by fire sales to restore liquidity.","a sharp decline in interest rates to compensate for added risk.","an increase in government deposit-insurance coverage.","a rapid slowdown in the withdrawal of deposits."],"answer":"A","images":null,"translation":{"question":"对一家金融机构信心丧失蔓延到另一家金融机构的途径之一是通过：","options":["为恢复流动性而抛售资产所驱动的资产价格大幅下跌。","为补偿新增风险而出现的利率大幅下降。","政府存款保险覆盖范围的扩大。","存款提取的迅速放缓。"]},"topics":["financial-crisis"]},{"num":41,"type":"mc","question":"The TED spread is an indicator of:","options":["expected defaults in the mortgage market.","expected inflation.","worries about the solvency of the banking system.","the ease or tightness of monetary policy."],"answer":"C","images":null,"translation":{"question":"TED利差是 ______ 的一个指标：","options":["抵押贷款市场的预期违约。","预期通胀。","对银行体系清偿能力的担忧。","货币政策的宽松或紧缩。"]},"topics":["financial-crisis"]},{"num":42,"type":"mc","question":"The TED spread is the difference between the interest rate paid on _____ and the interest rate paid on _____.","options":["three-month U.S. certificates of deposit; three-month EuroDollar loans","overnight interbank loans in London; overnight interbank loans in the United States","four-week Treasury bills; overnight federal funds","three-month EuroDollar interbank loans; three-month Treasury bills"],"answer":"D","images":null,"translation":{"question":"TED利差是 ______ 支付的利率与 ______ 支付的利率之差：","options":["三个月美国存单；三个月欧洲美元贷款","伦敦隔夜银行间贷款；美国隔夜银行间贷款","四周国库券；隔夜联邦基金","三个月欧洲美元银行间贷款；三个月国库券"]},"topics":["financial-crisis"]},{"num":43,"type":"mc","question":"If banks fear failure and become more conservative in making loans, then the sharp decline in bank lending is called a credit:","options":["crunch.","hazard.","bubble.","swap."],"answer":"A","images":null,"translation":{"question":"若银行担心倒闭而在放贷上变得更保守，则银行放贷的急剧下降被称为信贷：","options":["紧缩（credit crunch）。","危害。","泡沫。","互换。"]},"topics":["financial-crisis"]},{"num":44,"type":"mc","question":"A credit crunch reduces aggregate demand by:","options":["increasing the exchange rate.","increasing interest rates.","reducing consumption and investment spending.","reducing the money supply."],"answer":"C","images":null,"translation":{"question":"信贷紧缩通过 ______ 减少总需求：","options":["提高汇率。","提高利率。","减少消费和投资支出。","减少货币供给。"]},"topics":["financial-crisis"]},{"num":45,"type":"mc","question":"The effect of the financial crisis of 2008–2009 on the real economy in the United States was a(n) _____ in aggregate demand, a(n) _____ in output, and a(n) _________ in the unemployment rate.","options":["increase; increase; increase","decrease; decrease; decrease","decrease; increase; increase","decrease; decrease; increase"],"answer":"D","images":null,"translation":{"question":"2008–2009年金融危机对美国实体经济的影响是总需求 ______、产出 ______、失业率 ______。","options":["增加；增加；增加","减少；减少；减少","减少；增加；增加","减少；减少；增加"]},"topics":["financial-crisis"]},{"num":46,"type":"mc","question":"To the extent that low interest rates contributed to the financial crisis of 2008–2009, the blame for this policy lies with:","options":["the Federal Reserve.","investment banks.","rating agencies.","mortgage brokers."],"answer":"A","images":null,"translation":{"question":"就低利率促成了2008–2009年金融危机而言，这一政策的责任在于：","options":["美联储。","投资银行。","评级机构。","抵押贷款经纪人。"]},"topics":["financial-crisis"]},{"num":47,"type":"mc","question":"To the extent that mortgage defaults contributed to the financial crisis of 2008–2009, blame for these actions lies with:","options":["homebuyers who borrowed more than they could afford to repay.","mortgage brokers who encouraged households to borrow excessively.","government policymakers who pursued policies to encourage homeownership","all of the above."],"answer":"D","images":null,"translation":{"question":"就抵押贷款违约促成了2008–2009年金融危机而言，这些行为的责任在于：","options":["借款超过偿还能力的购房者。","鼓励家庭过度借款的抵押贷款经纪人。","推行鼓励拥有住房政策的政府决策者。","以上全部。"]},"topics":["financial-crisis"]},{"num":48,"type":"mc","question":"To the extent that risky mortgage-backed securities that were sold to buyers who were not fully aware of the risks contributed to the financial crisis of 2008–2009, blame for this action lies with:","options":["homebuyers.","mortgage brokers.","investment banks.","the Federal Reserve."],"answer":"C","images":null,"translation":{"question":"就卖给未完全了解风险的买家的高风险抵押贷款支持证券促成了2008–2009年金融危机而言，这一行为的责任在于：","options":["购房者。","抵押贷款经纪人。","投资银行。","美联储。"]},"topics":["financial-crisis"]},{"num":49,"type":"mc","question":"To the extent that the undervaluation of the riskiness of mortgage-backed securities contributed to the financial crisis of 2008–2009, blame for this mistake lies with:","options":["mortgage brokers.","investment banks.","rating agencies.","government policymakers."],"answer":"C","images":null,"translation":{"question":"就对抵押贷款支持证券风险的低估促成了2008–2009年金融危机而言，这一错误的责任在于：","options":["抵押贷款经纪人。","投资银行。","评级机构。","政府决策者。"]},"topics":["financial-crisis"]},{"num":50,"type":"mc","question":"Conventional monetary and fiscal policies used in a recession are aimed at:","options":["increasing aggregate supply.","increasing aggregate demand.","decreasing aggregate supply.","decreasing aggregate demand."],"answer":"B","images":null,"translation":{"question":"衰退中使用的常规货币政策和财政政策旨在：","options":["增加总供给。","增加总需求。","减少总供给。","减少总需求。"]},"topics":["financial-crisis"]},{"num":51,"type":"mc","question":"During the 2008–2009 period, the conventional monetary policy response was to _____ the target federal funds rate, while the conventional fiscal policy response was to _____ taxes and to _____ government spending.","options":["increase; increase; increase","decrease; decrease; decrease","increase; increase; decrease","decrease; decrease; increase"],"answer":"D","images":null,"translation":{"question":"在2008–2009年期间，常规货币政策的应对是 ______ 联邦基金目标利率，而常规财政政策的应对是 ______ 税收、______ 政府支出。","options":["提高；提高；提高","降低；降低；降低","提高；提高；降低","降低；降低；提高"]},"topics":["financial-crisis"]},{"num":52,"type":"mc","question":"Conventional monetary policy was limited during the 2008–2009 financial crisis because the central bank could not:","options":["sell enough bonds through open market operations.","print a sufficient quantity of money.","reduce the target interest rate below zero.","adjust the discount rate quickly enough."],"answer":"C","images":null,"translation":{"question":"常规货币政策在2008–2009年金融危机期间受到限制，因为央行无法：","options":["通过公开市场操作卖出足够的债券。","印制足够数量的货币。","把目标利率降到零以下。","足够迅速地调整贴现率。"]},"topics":["financial-crisis"]},{"num":53,"type":"mc","question":"Conventional fiscal policy was limited during the 2008–2009 financial crisis because of:","options":["concerns about increasing the government's budget deficit and debt.","difficulties paying out tax rebates.","the inability of the government to reduce spending below zero.","the inability of the government to raise taxes above 100 percent of income."],"answer":"A","images":null,"translation":{"question":"常规财政政策在2008–2009年金融危机期间受到限制，是因为：","options":["对增加政府预算赤字和债务的担忧。","发放退税的困难。","政府无法把支出降到零以下。","政府无法把税收提高到收入的100%以上。"]},"topics":["financial-crisis"]},{"num":54,"type":"mc","question":"Conventional monetary and fiscal policies during a financial crisis are aimed at _____, while acting as a lender of last resort or injecting government funds into the financial system during a financial crisis is aimed at _____.","options":["increasing output; reducing inflation","expanding aggregate demand; restoring confidence in the financial system","increasing corporate wealth; increasing household wealth","expanding aggregate supply; reducing the national debt"],"answer":"B","images":null,"translation":{"question":"金融危机期间的常规货币政策和财政政策旨在 ______，而在金融危机期间充当最后贷款人或向金融体系注入政府资金旨在 ______。","options":["增加产出；降低通胀","扩张总需求；恢复对金融体系的信心","增加企业财富；增加家庭财富","扩张总供给；减少国家债务"]},"topics":["financial-crisis"]},{"num":55,"type":"mc","question":"A bank with assets worth less than liabilities is said to be _____, while a bank without adequate funds immediately available to make promised payments is said to be _____.","options":["inflated; inverted","inverted; inflated","insolvent; illiquid","illiquid; insolvent"],"answer":"C","images":null,"translation":{"question":"资产价值低于负债的银行被称为 ______，而没有足够立即可用资金来履行承诺支付的银行被称为 ______。","options":["膨胀；倒置","倒置；膨胀","资不抵债；流动性不足","流动性不足；资不抵债"]},"topics":["financial-crisis"]},{"num":56,"type":"mc","question":"An illiquid bank can become insolvent when it:","options":["refuses to make promised payments.","sells additional stock to obtain funds.","sells assets at fire-sale prices to meet liquidity demands.","can extend the due dates of its liabilities."],"answer":"C","images":null,"translation":{"question":"流动性不足的银行在 ______ 时可能变得资不抵债：","options":["拒绝履行承诺支付。","增发股票以获得资金。","为满足流动性需求而以抛售价出售资产。","能够延长其负债的到期日。"]},"topics":["financial-crisis"]},{"num":57,"type":"mc","question":"When the central bank acts as a lender of last resort, it:","options":["requires the borrower to put up collateral.","is able to confiscate some of the borrower's assets.","requires voting rights on the borrower's board of directors.","takes over ownership of the borrower."],"answer":"A","images":null,"translation":{"question":"当央行充当最后贷款人时，它：","options":["要求借款人提供抵押品。","能够没收借款人的部分资产。","要求在借款人董事会中拥有投票权。","接管借款人的所有权。"]},"topics":["financial-crisis"]},{"num":58,"type":"mc","question":"The principal purpose of a central bank acting as a lender of last resort is to:","options":["prevent the failure of insolvent financial institutions.","maintain the liquidity of the financial system.","provide adequate funds to finance the government's spending.","keep interest rates as low as possible."],"answer":"B","images":null,"translation":{"question":"央行充当最后贷款人的主要目的是：","options":["防止资不抵债的金融机构倒闭。","维持金融体系的流动性。","提供足够资金为政府支出融资。","尽可能保持低利率。"]},"topics":["financial-crisis"]},{"num":59,"type":"mc","question":"During the 2008–2009 financial crisis, the Federal Reserve served as a lender of last resort by providing liquidity to:","options":["both banks and shadow banks with reliable collateral.","any insolvent domestic borrower in the economy.","state and local governments.","households that were underwater on their mortgages."],"answer":"A","images":null,"translation":{"question":"在2008–2009年金融危机期间，美联储充当最后贷款人，向 ______ 提供流动性：","options":["拥有可靠抵押品的银行和影子银行。","经济中任何资不抵债的国内借款人。","州和地方政府。","抵押贷款资不抵债的家庭。"]},"topics":["financial-crisis"]},{"num":60,"type":"mc","question":"Ideally, the purpose of providing funds to insolvent banks beyond required insurance payouts is to:","options":["transfer funds from taxpayers to financial institutions.","give taxpayers ownership in a commercial bank.","reward political loyalty.","prevent bank failures from multiplying."],"answer":"D","images":null,"translation":{"question":"理想情况下，向资不抵债的银行提供超过必需保险赔付资金的目的在于：","options":["把资金从纳税人转移到金融机构。","让纳税人拥有商业银行的所有权。","奖励政治忠诚。","防止银行倒闭蔓延。"]},"topics":["financial-crisis"]},{"num":61,"type":"mc","question":"The phrase _____ describes a firm so central to that financial system that policymakers will not allow it to enter bankruptcy.","options":["“no bank left behind”","“too big to fail”","“don't fail, don't bail”","“laissez-faire bank”"],"answer":"B","images":null,"translation":{"question":"短语 ______ 描述的是这样一种企业：它对金融体系至关重要，决策者不会允许其破产。","options":["“不让任何银行掉队”","“太大而不能倒”","“不倒闭、不救助”","“自由放任银行”"]},"topics":["financial-crisis"]},{"num":62,"type":"mc","question":"Deposit insurance is an example of ______ used to prop up the financial system.","options":["a giveaway of public funds","risky lending","a capital injection","conventional monetary policy"],"answer":"A","images":null,"translation":{"question":"存款保险是用于支撑金融体系的 ______ 的一个例子：","options":["公共资金的赠予。","风险放贷。","资本注入。","常规货币政策。"]},"topics":["financial-crisis"]},{"num":63,"type":"mc","question":"The government making loans that are secured by collateral of dubious value to prop up the financial system is an example of:","options":["a giveaway of public funds.","risky lending.","a capital injection.","conventional monetary policy."],"answer":"B","images":null,"translation":{"question":"政府发放以价值可疑的抵押品作担保的贷款来支撑金融体系，是 ______ 的一个例子：","options":["公共资金的赠予。","风险放贷。","资本注入。","常规货币政策。"]},"topics":["financial-crisis"]},{"num":64,"type":"mc","question":"The government purchasing ownership stakes in a faltering financial institution in order to prop up the financial system is an example of:","options":["a giveaway of public funds.","risky lending.","a capital injection.","conventional monetary policy."],"answer":"C","images":null,"translation":{"question":"政府购买一家陷入困境的金融机构的所有权份额以支撑金融体系，是 ______ 的一个例子：","options":["公共资金的赠予。","风险放贷。","资本注入。","常规货币政策。"]},"topics":["financial-crisis"]},{"num":65,"type":"mc","question":"The benefit of stricter capital requirements for shadow banks is _____, while the cost is _____.","options":["the end of risk-taking behavior; the development of more profitable opportunities","increased monitoring of risk-taking behavior; higher executive compensation","enhancing financial stability; impeding financial intermediation","lower inflation; higher unemployment"],"answer":"C","images":null,"translation":{"question":"对影子银行实行更严格资本要求的好处是 ______，而成本是 ______。","options":["结束冒险行为；发展更有利可图的机会","加强对冒险行为的监督；更高的高管薪酬","增强金融稳定；阻碍金融中介","更低通胀；更高失业"]},"topics":["financial-crisis"]},{"num":66,"type":"mc","question":"All of the following are examples of shadow banks except:","options":["Bear Sterns","AIG","Bank of America","Lehman Brothers"],"answer":"C","images":null,"translation":{"question":"以下都是影子银行的例子，除了：","options":["贝尔斯登（Bear Sterns）。","AIG。","美国银行（Bank of America）。","雷曼兄弟（Lehman Brothers）。"]},"topics":["financial-crisis"]},{"num":67,"type":"mc","question":"Proponents of restricting the size of financial institutions believe this policy will _____, while opponents believe this policy will _____.","options":["allow firms to take advantage of economies of scale; increase the volatility of the financial system.","reduce the number of financial institutions; give institutions the incentive to take excessive risks.","eliminate the need for deposit insurance; encourage imprudent risk taking","make the financial system more stable; lead to higher costs"],"answer":"D","images":null,"translation":{"question":"主张限制金融机构规模的人认为这一政策将 ______，而反对者认为这一政策将 ______。","options":["让企业利用规模经济；增加金融体系的波动性","减少金融机构数量；给机构冒过度风险的激励","消除存款保险的需要；鼓励不审慎的风险承担","使金融体系更稳定；导致更高的成本"]},"topics":["financial-crisis"]},{"num":68,"type":"mc","question":"Two policies that are intended to make the financial system more stable by restricting the size of financial institutions are:","options":["to offer cheaper loans to large financial institutions and to make larger capital injections available for larger banks.","to lower the cost of deposit insurance for large banks and to provide incentives for large banks to make speculative investments.","to restrict mergers among large banks and to require higher capital requirements for large banks.","to allow large banks to be more highly leveraged and to increase deposit insurance coverage for depositors at large banks."],"answer":"C","images":null,"translation":{"question":"旨在通过限制金融机构规模使金融体系更稳定的两项政策是：","options":["向大型金融机构提供更便宜的贷款，为更大的银行提供更大规模的资本注入。","降低大型银行存款保险成本，并为大型银行进行投机性投资提供激励。","限制大型银行之间的合并，并要求大型银行持有更高的资本。","允许大型银行更高杠杆，并提高大型银行存款人的存款保险覆盖。"]},"topics":["financial-crisis"]},{"num":69,"type":"mc","question":"The Volcker rule restricts excessive risk taking by commercial banks by:","options":["prohibiting banks from making certain kinds of speculative investments.","increasing the amount of capital banks must hold.","decreasing the deposit insurance coverage of depositors in commercial banks.","limiting the compensation that bank executives can be paid."],"answer":"A","images":null,"translation":{"question":"沃尔克规则通过 ______ 限制商业银行的过度风险承担：","options":["禁止银行进行某些类型的投机性投资。","提高银行必须持有的资本量。","降低商业银行存款人的存款保险覆盖。","限制银行高管的薪酬。"]},"topics":["financial-crisis"]},{"num":70,"type":"mc","question":"Prior to the financial crisis of 2008–2009, financial regulation in the United States consisted of a _____ system of regulators, which the Dodd-Frank Act sought to improve upon by _____ the number of regulatory bodies.","options":["coordinated; increasing","coordinated; decreasing","fragmented; increasing","fragmented; decreasing"],"answer":"C","images":null,"translation":{"question":"在2008–2009年金融危机之前，美国的金融监管由 ______ 的监管机构体系组成，而《多德-弗兰克法案》试图通过 ______ 监管机构数量来改进它。","options":["协调；增加","协调；减少","分散；增加","分散；减少"]},"topics":["financial-crisis"]},{"num":71,"type":"mc","question":"Which of the following policies are intended to reduce the likelihood of future financial crises?","options":["restricting the size of financial firms","limiting excessive risk taking","reforming regulatory agencies","all of the above"],"answer":"D","images":null,"translation":{"question":"以下哪些政策旨在降低未来发生金融危机的可能性？","options":["限制金融企业的规模。","限制过度的风险承担。","改革监管机构。","以上全部。"]},"topics":["financial-crisis"]},{"num":72,"type":"mc","question":"The purpose of the Financial Services Oversight Council, which was created by the Dodd-Frank Act, is to:","options":["replace the existing regulatory agencies with one agency to enforce all financial regulations.","oversee private credit rating agencies.","determine appropriate levels of executive compensation for firms in the financial system.","coordinate activities of the various regulatory agencies."],"answer":"D","images":null,"translation":{"question":"由《多德-弗兰克法案》设立的金融服务监督委员会的目的是：","options":["用一个机构取代现有监管机构以执行所有金融监管。","监督私营信用评级机构。","确定金融体系中企业高管的适当薪酬水平。","协调各监管机构的活动。"]},"topics":["financial-crisis"]},{"num":73,"type":"mc","question":"Sovereign debt refers to debt issued:","options":["without collateral.","with no rating by a credit-rating agency.","by governments.","with a promise to repay in a foreign currency."],"answer":"C","images":null,"translation":{"question":"主权债务是指 ______ 发行的债务：","options":["无抵押。","未经信用评级机构评级。","由政府。","承诺以外币偿还。"]},"topics":["financial-crisis"]},{"num":74,"type":"mc","question":"The potential problem faced by the rest of Europe in the event of a Greek debt default is:","options":["the inability of the European Central Bank to conduct open market operations.","the risk of banks holding Greek debt becoming insolvent.","an increase in the number of U.S. dollars traded per euro in the foreign exchange market.","the strain on the European banking system, while banks in the rest of the world would be unaffected."],"answer":"B","images":null,"translation":{"question":"若希腊发生债务违约，欧洲其他国家面临的潜在问题是：","options":["欧洲央行无法进行公开市场操作。","持有希腊债务的银行可能资不抵债的风险。","外汇市场上每欧元兑换的美元数量增加。","欧洲银行体系承受压力，而世界其他地区的银行不受影响。"]},"topics":["financial-crisis"]},{"num":75,"type":"sa","question":"a. What is the difference between an illiquid bank and an insolvent bank? b. Would the Federal Reserve's lender of last resort function be the most appropriate remedy for an illiquid bank or an insolvent bank? Explain. c. Would the FDIC's resolution authority be the most appropriate remedy for an illiquid bank or an insolvent bank? Explain.","options":null,"answer":null,"images":null,"translation":{"question":"a. 流动性不足的银行与资不抵债的银行有什么区别？b. 美联储的最后贷款人职能对流动性不足的银行还是资不抵债的银行是最合适的补救措施？请解释。c. 联邦存款保险公司（FDIC）的处置权对流动性不足的银行还是资不抵债的银行是最合适的补救措施？请解释。","options":null},"topics":["financial-crisis"],"answer_ref":"a. 流动性不足的银行：资产大于负债，但资产难以迅速变现偿付到期债务（期限错配）；资不抵债的银行：负债已超过资产（资不抵债）。b. 最后贷款人适合流动性不足的银行：美联储以优质资产为抵押放贷，帮其渡过挤兑，防范恐慌蔓延；对资不抵债者放贷是填无底洞。c. FDIC 处置权适合资不抵债的银行：接管、清盘或并购，保障受保存款人；流动性不足的银行不需要处置，只需流动性支持。"},{"num":76,"type":"sa","question":"Identify whether each of the following situations is a case of adverse selection or moral hazard. Explain. a. Jasper knows, but the car rental company does not know when he is trying to rent a car during a blizzard in Wisconsin, that Jasper grew up in a tropical climate and has no idea how to drive in cold weather and snowy conditions. b. Joan has received a loan from the bank to finance the purchase of more inventory for her quilt shop, but she intends to use the money (without telling the bank) to go on a safari in Africa. c. Some companies sell annuities, which are policies that make periodic payments as long as the purchaser lives. Jane is trying to buy an annuity. Jane knows, but the annuity issuers do not know, that people in Jane's family routinely live to age 100.","options":null,"answer":null,"images":null,"translation":{"question":"判断以下每种情形属于逆向选择还是道德风险。请解释。a. 贾斯珀在威斯康星州暴风雪中试图租车时，他自己知道、但租车公司不知道他是在热带气候中长大、完全不知道如何在寒冷和下雪条件下开车。b. 琼从银行获得了一笔贷款，用于为其被子店购买更多存货，但她打算（不告诉银行）用这笔钱去非洲游猎。c. 一些公司出售年金，即只要购买者活着就定期付款的保单。简想买年金。简自己知道、但年金发行者不知道简的家人通常活到100岁。","options":null},"topics":["asymmetric-information"],"answer_ref":"a. 逆向选择：交易发生前的隐藏特征——Jasper 缺乏雪地驾驶能力这一信息租车公司无法获知，高风险客户更可能在这类天气下租车。b. 道德风险：交易发生后的隐藏行为——Joan 获得贷款后改变行为（如把资金投入高风险项目、懈怠还款），银行无法全程监控。"},{"num":77,"type":"sa","question":"How do deposit insurance and the “too big to fail” policy increase moral hazard?","options":null,"answer":null,"images":null,"translation":{"question":"存款保险和“太大而不能倒”政策如何增加道德风险？","options":null},"topics":["asymmetric-information"],"answer_ref":"存款保险使储户无需关心银行风险（受保存款无损失之忧），失去监督与挤兑约束；银行因此更敢冒险——道德风险。\"大而不能倒\"让大型银行债权人相信政府必救，约束进一步放松，大银行风险敞口更大。安全网越厚，市场纪律越弱。"},{"num":78,"type":"sa","question":"Provide one example from the 2008–2009 financial crisis of how the following types of policies were used to respond to the crisis: a. conventional monetary and fiscal policy b. lender of last resort c. injections of government funds","options":null,"answer":null,"images":null,"translation":{"question":"从2008–2009年金融危机中各举一个例子，说明以下类型的政策是如何用于应对危机的：a. 常规货币政策和财政政策 b. 最后贷款人 c. 政府资金注入","options":null},"topics":["financial-crisis"],"answer_ref":"a. 常规政策：美联储把联邦基金利率从5.25%降至0–0.25%；财政上2009年通过ARRA刺激法案（约7,870亿美元减税与支出）。b. 最后贷款人：美联储创设多项工具——扩大贴现窗口、定期拍卖工具（TAF）、向货币市场基金和商业票据市场放贷（CPFF）、通过摩根大通救助贝尔斯登。c. 注资：TARP（7,000亿美元问题资产救助计划）向银行体系注资（购买优先股）、救助汽车业与AIG。"},{"num":79,"type":"sa","question":"Provide one argument in favor of and one argument against each of the following proposals to prevent future financial crises. a. require shadow banks to hold more capital b. give the FDIC resolution authority over shadow banks c. impose higher capital requirements on larger banks d. prohibit banks from making speculative investments","options":null,"answer":null,"images":null,"translation":{"question":"对以下每一项防止未来金融危机的提议，各给出一个赞成理由和一个反对理由。a. 要求影子银行持有更多资本 b. 赋予FDIC对影子银行的处置权 c. 对更大的银行实行更高的资本要求 d. 禁止银行进行投机性投资","options":null},"topics":["financial-crisis"],"answer_ref":"a. 影子银行更多资本金：赞成——降低其杠杆与挤兑风险；反对——监管套利下业务会流向更暗处，抬高社会融资成本。b. 给FDIC对影子银行的处置权：赞成——可有序清算、避免雷曼式混乱；反对——等于扩大安全网，制造新的道德 hazard。c. 大银行更高资本要求：赞成——缩小TBTF；反对——规模惩罚可能损害效率，风险转移到非银体系。d. 禁止自营投机（沃尔克规则）：赞成——用受保存款赌博的公共风险下降；反对——自营与做市/对冲难以区分，市场流动性受损。"},{"num":80,"type":"sa","question":"Provide specific examples from the 2008–2009 financial crisis of each of the five stages of a financial crisis: a. asset-price booms and busts b. insolvencies of financial institutions c. falling confidence in the financial system d. credit crunch e. recession","options":null,"answer":null,"images":null,"translation":{"question":"从2008–2009年金融危机中各举一个具体例子，说明金融危机五个阶段中的每一阶段：a. 资产价格繁荣与崩溃 b. 金融机构资不抵债 c. 对金融体系信心下降 d. 信贷紧缩 e. 衰退","options":null},"topics":["financial-crisis"],"answer_ref":"a. 资产价格暴涨暴跌：2000年代房价泡沫及随后的暴跌。b. 金融机构资不抵债：2008年9月雷曼兄弟破产；贝尔斯登被接管、AIG濒临倒闭。c. 金融体系信心崩塌：货币市场基金Reserve Primary Fund跌破1美元面值，引发影子银行挤兑。d. 信贷紧缩：银行间市场冻结，TED利差飙升至历史高位，企业贷款枯竭。e. 衰退：2007年12月–2009年6月大衰退，失业率升至10%。"},{"num":81,"type":"sa","question":"What is the difference between systematic and idiosyncratic risk? Which type of risk can be almost eliminated through diversification?","options":null,"answer":null,"images":null,"translation":{"question":"系统性风险与特有风险有什么区别？哪种风险几乎可以通过分散化消除？","options":null},"topics":["risk-diversification"],"answer_ref":"系统性风险：影响整个市场/宏观经济的共同风险（衰退、危机），无法靠分散化消除。特质性（idiosyncratic）风险：个别公司/行业特有的风险。可通过持有多元化资产组合几乎完全消除的是特质性风险；系统性风险只能对冲或承受，无法靠分散消除。"},{"num":82,"type":"sa","question":"Suppose Bank A has a leverage ratio of 20 and Bank B has a leverage ratio of 10. Explain the meaning of these ratios and what would happen to each of these banks if the value of their assets fell by 6 percent.","options":null,"answer":null,"images":null,"translation":{"question":"假设银行A的杠杆率为20，银行B的杠杆率为10。解释这些比率的含义，以及若两家银行的资产价值下跌6%，它们各自会发生什么。","options":null},"topics":["financial-crisis"],"answer_ref":"杠杆率 = 总资产/自有资本。A行20倍：资产跌6%→资本被抹去20×6%=120%→资不抵债、破产。B行10倍：6%×10=60%→资本还剩40%，虽受重创仍可存续。杠杆越高，同样的资产损失对资本的放大倍数越大，越脆弱。"},{"num":83,"type":"sa","question":"Use the aggregate demand–aggregate supply model to graphically illustrate the impact of a financial crisis on output and prices in an economy in the short run. Explain the factors that cause changes from the initial equilibrium to the new short-run equilibrium.","options":null,"answer":null,"images":null,"translation":{"question":"用总需求–总供给模型以图形说明金融危机短期内对经济产出和价格的影响。解释导致从初始均衡变化到新的短期均衡的因素。","options":null},"topics":["financial-crisis"],"answer_ref":"图：金融危机→财富缩水与信贷紧缩→C、I骤减→AD 左移。短期新均衡：产出大幅下降（低于自然率），物价因粘性仅小幅下降。成因分解：消费下滑（财富效应、预防性储蓄）、投资崩塌（信贷可得性骤减、不确定性）、银行惜贷使利率渠道受阻——金融系统把局部冲击放大为总需求崩溃。"},{"num":84,"type":"sa","question":"What are the benefits of a well-functioning financial system? What are the costs of a financial crisis?","options":null,"answer":null,"images":null,"translation":{"question":"运转良好的金融体系有哪些好处？金融危机有哪些成本？","options":null},"topics":["financial-system","financial-crisis"],"answer_ref":"良好金融体系的收益：把储蓄高效配置给最有生产力的投资；跨时跨人的风险分散；提供流动性；生产信息以甄别项目——支撑资本积累与创新、提高生活水平。危机的成本：信贷紧缩引发深度衰退与高失业，财富蒸发，政府救助的财政负担，复苏缓慢且可能留下长期产出损失（疤痕效应）。"},{"num":85,"type":"sa","question":"“A fire-sale can make illiquid institutions insolvent.” Explain how.","options":null,"answer":null,"images":null,"translation":{"question":"“抛售会使流动性不足的机构变得资不抵债。”请解释其原因。","options":null},"topics":["financial-crisis"],"answer_ref":"贱卖（fire sale）：机构被迫以远低于公允价值的价格抛售资产；按市值计价的会计使其他持有同类资产的机构账面同步缩水——一家机构的贱卖侵蚀别家的资本。资产负债表连锁反应下，原本只是缺流动性（资产仍大于负债）的机构被下跌的市价拖成资不抵债。恐慌的自我实现机制。"},{"num":86,"type":"sa","question":"There are systematic risks and idiosyncratic risks. Which risks can be mitigated by whom and how?","options":null,"answer":null,"images":null,"translation":{"question":"存在系统性风险和特有风险。哪些风险可以由谁、以何种方式缓解？","options":null},"topics":["risk-diversification"],"answer_ref":"特质性风险：由个人和金融机构通过分散化（投资组合、保险大数法则）化解。系统性风险：无法分散，只能由宏观当局管理——政府与央行以资本监管、压力测试、存款保险、最后贷款人、逆周期货币政策等工具防范与吸收。"},{"num":87,"type":"sa","question":"By definition, “shadow banks are a diverse set of financial institutions that perform some functions similar to banks, but do so outside the regulatory system that applies to traditional banking.” In the recession of 2008, the government financially rescued many shadow banks. Was this a moral hazard? If yes, then why did the government do this?","options":null,"answer":null,"images":null,"translation":{"question":"按定义，“影子银行是一类多样的金融机构，它们履行一些与银行类似的功能，但在适用于传统银行业的监管体系之外运作。”在2008年的衰退中，政府用资金救助了许多影子银行。这是否构成道德风险？如果是，政府为什么这样做？","options":null},"topics":["asymmetric-information"],"answer_ref":"是——救助确认了\"出问题有人兜底\"，强化冒险激励（道德风险），且把私人收益与公共风险分离。政府仍出手，是因为系统性风险压倒一切：影子银行与传统银行体系盘根错节（货币市场基金、回购、衍生品），任其倒闭将引发连锁违约与大萧条级衰退——两害相权，先止住崩溃，再补监管。"},{"num":88,"type":"sa","question":"What were the mistakes of the following parties that eventually led to the recession of 2008–2009? a. Homebuyers b. Government policymakers c. Investment banks","options":null,"answer":null,"images":null,"translation":{"question":"以下各方犯了什么错误，最终导致了2008–2009年的衰退？a. 购房者 b. 政府决策者 c. 投资银行","options":null},"topics":["financial-crisis"],"answer_ref":"a. 购房者：借入超出偿付能力的贷款（无收入证明、低首付、诱惑利率），把房价只涨不跌当信仰，投机购房。b. 政策制定者：长期低利率助推泡沫、以政策鼓励购房、对按揭贷款与衍生品市场监管缺位、监管体系割裂。c. 投资银行：把毒资产证券化全球分销（次贷CDO）、杠杆率过高、依赖短期批发融资、风险模型忽视违约相关性——雷曼等高杠杆机构率先倒下。"},{"num":89,"type":"sa","question":"Why was the recession of 2008–2009 sometimes also referred as the “subprime crisis”?","options":null,"answer":null,"images":null,"translation":{"question":"为什么2008–2009年的衰退有时也被称为“次级贷款危机”？","options":null},"topics":["financial-crisis"],"answer_ref":"因为危机的导火索是次级抵押贷款市场：2006年起次贷违约率飙升→按揭证券（MBS/CDO）价格崩塌→持有这些证券的金融机构（雷曼等）资不抵债→连锁反应。危机的震中与第一块多米诺骨牌都在次贷，故被称为\"次贷危机\"。"},{"num":90,"type":"sa","question":"\"The less healthy a person is, the more likely he or she is to purchase insurance.\" This is a fact stated by an employee of a health insurance company. Is this issue related to adverse selection? If yes, how?","options":null,"answer":null,"images":null,"translation":{"question":"“一个人越不健康，就越可能购买保险。”这是一家健康保险公司员工陈述的一个事实。这个问题与逆向选择有关吗？如果有关，是如何相关的？","options":null},"topics":["asymmetric-information"],"answer_ref":"是，教科书式的逆向选择：投保前个人知道自己的健康状况而保险公司不知道；越不健康的人投保意愿越强，保险池被高风险人群占据——赔付率高于预期→保费上调→相对健康者退出→池子更不健康（\"死亡螺旋\"）。事前信息不对称导致市场结构恶化，正是 adverse selection 的定义。"},{"num":91,"type":"sa","question":"What are the problems that hinder any direct transaction between the lender and borrower? What role do banks play in mitigating those issues?","options":null,"answer":null,"images":null,"translation":{"question":"有哪些问题阻碍贷款人与借款人之间的直接交易？银行在缓解这些问题方面发挥什么作用？","options":null},"topics":["asymmetric-information"],"answer_ref":"障碍：①信息不对称——逆向选择（借款人自知风险，贷款人难分辨）与道德风险（资金可能被滥用）；②交易成本——搜寻、评估、谈判、监督借款人的成本高；③规模与期限错配——小额储蓄难以直接形成大额长期贷款。银行的作用：筛选借款人（化解逆向选择）、监督资金用途（化解道德风险）、把小额存款汇集成大额贷款、转换期限与风险、分散风险。"},{"num":92,"type":"sa","question":"How does the TED spread indicate the confidence level the people in an economy have in the banking system?","options":null,"answer":null,"images":null,"translation":{"question":"TED利差如何反映一个经济体中人们对银行体系的信心水平？","options":null},"topics":["financial-crisis"],"answer_ref":"TED利差 = 银行同业拆借利率（LIBOR）− 国库券利率，度量银行体系 perceived 信用风险。差幅收窄=银行互信、体系稳健；差幅扩大=银行彼此不信任、担心交易对手违约。2008年TED利差飙升至450个基点以上，是市场信心崩塌最直观的指标。"},{"num":93,"type":"sa","question":"What was the effect of the recession of 2008–2009 on output and prices? Give one example of conventional monetary policies and fiscal policies used by the government to fix the problem.","options":null,"answer":null,"images":null,"translation":{"question":"2008–2009年的衰退对产出和价格有什么影响？各举一个政府用于解决问题的常规货币政策和财政政策的例子。","options":null},"topics":["financial-crisis"],"answer_ref":"影响：产出大幅收缩（大衰退，GDP峰值到谷底约降4%以上），物价短暂转负后长期低通胀，失业率升至10%。常规货币政策：美联储把联邦基金利率从5.25%一路降至0–0.25%（零利率下限）；常规财政政策：2009年ARRA刺激计划（约7,870亿美元，含减税、基建、州政府援助）及TARP金融救助。"}]}],"topics":[{"id":"macro-intro","name":"What Macroeconomists Study","zh":"宏观经济学导论","chapters":[1],"summary":"宏观经济学研究整体经济现象：为什么有些国家增长快、什么引起衰退、通胀率由什么决定、失业为何存在。\n核心问题：经济增长、经济波动、通胀、失业。"},{"id":"macro-models","name":"Economic Models & Variables","zh":"经济模型与变量","chapters":[1],"summary":"经济学家用模型解释变量间关系，模型是现实的简化。\n内生变量：模型内部决定的变量；外生变量：模型外部给定的变量。\n例：需求-供给模型中，价格和数量是内生的，收入、偏好是外生的。"},{"id":"market-clearing","name":"Market Clearing & Prices","zh":"市场出清与价格","chapters":[1],"summary":"市场出清假设：价格可以自由调整，使供给等于需求。\n弹性价格：能迅速调整以出清市场；粘性价格：调整缓慢。\n多数经济学家认为长期价格有弹性、短期价格有粘性。"},{"id":"gdp-accounting","name":"GDP Accounting","zh":"GDP 核算","chapters":[2],"summary":"GDP＝既定时期一国境内生产的最终产品与服务的市场价值。\n核算方法：支出法（Y=C+I+G+NX）、收入法、生产法。\n只算最终品、当期生产、市场价值；二手交易、存货变动有特殊处理。"},{"id":"cpi-inflation","name":"CPI & Inflation","zh":"CPI 与通胀衡量","chapters":[2],"summary":"CPI＝一篮子商品与服务的当期成本相对基期成本之比，衡量生活成本。\n通胀率＝物价总水平的增长率。\nCPI 缺陷：替代偏差、新产品偏差、质量变化偏差。GDP平减指数与CPI的区别在于篮子构成。"},{"id":"unemployment-measure","name":"Measuring Unemployment","zh":"失业率与劳动力","chapters":[2],"summary":"劳动力＝就业者＋失业者；失业率＝失业人数÷劳动力。\n劳动参与率＝劳动力÷成年人口。\n奥肯定律：失业率与GDP之间存在负相关关系。"},{"id":"national-income","name":"National Income & Factor Markets","zh":"国民收入与要素市场","chapters":[3],"summary":"总收入等于总产出：Y = F(K, L)。\n要素价格由要素市场供求决定；竞争性企业按边际产品支付要素报酬。\n总产出在资本和劳动之间分配，各得其边际产品。"},{"id":"cobb-douglas","name":"Cobb-Douglas Production Function","zh":"柯布-道格拉斯生产函数","chapters":[3],"summary":"Y = A·K^α·L^(1-α)，规模报酬不变。\n资本收入份额＝MPK·K/Y＝α；劳动收入份额＝MPL·L/Y＝1-α。\n常用作宏观生产函数，性质优良（边际报酬递减、规模报酬不变）。"},{"id":"money-functions","name":"Money & Its Functions","zh":"货币与货币职能","chapters":[4],"summary":"货币职能：交易媒介、计价单位、价值储藏。\n货币量度量：M1（通货＋活期存款等）、M2（M1＋储蓄存款等）。\n法定货币：无内在价值、因法令而流通。"},{"id":"banking-fractional","name":"Fractional-Reserve Banking","zh":"部分准备金银行","chapters":[4],"summary":"部分准备金银行制：银行只保留一部分存款作准备金，其余贷出。\n货币创造：货币乘数 m = 1/rr（rr为法定准备金率）。\n银行通过存贷循环创造货币，但受准备金率限制。"},{"id":"money-supply-control","name":"Central Bank & Money Supply","zh":"央行与货币供给","chapters":[4],"summary":"央行控制货币供给的工具：公开市场操作、准备金率、再贴现率。\n货币供给模型：M = m × B（m为货币乘数，B为基础货币）。\n公开市场购买增加基础货币，扩张货币供给。"},{"id":"quantity-theory","name":"Quantity Theory of Money","zh":"货币数量论","chapters":[5],"summary":"交易方程：M·V = P·T（M货币量、V流通速度、P价格、T交易量）。\n货币数量论：V和T基本稳定，货币量决定价格水平。\n长期中，货币增长→通胀同比例上升。"},{"id":"seigniorage-hyper","name":"Seigniorage & Hyperinflation","zh":"铸币税与恶性通胀","chapters":[5],"summary":"铸币税：政府通过印钞获得的收入（实际税收的一种）。\n恶性通胀：物价每月上涨超过50%。\n原因：政府大规模印钞为赤字融资→通胀预期→货币需求崩溃。"},{"id":"fisher-effect","name":"Fisher Effect & Interest Rates","zh":"费雪效应与利率","chapters":[5],"summary":"实际利率 r = 名义利率 i − 预期通胀 πᵉ。\n费雪效应：名义利率随预期通胀一对一调整，实际利率不变。\n区分事前（预期）实际利率与事后（实际）实际利率。"},{"id":"inflation-costs","name":"Costs of Inflation","zh":"通胀成本","chapters":[5],"summary":"预期通胀的成本：鞋底成本、菜单成本、相对价格扭曲、税收扭曲。\n未预期通胀的成本：财富在债务人与债权人之间再分配。\n通缩（物价下跌）同样有害，抑制消费与投资。"},{"id":"trade-nex","name":"Net Exports & Capital Flows","zh":"净出口与资本流动","chapters":[6],"summary":"NX = S − I：净出口等于储蓄减投资，也等于净资本流出。\n贸易顺差→对外净贷出；贸易逆差→对外净借入。\n开放经济恒等式：Y = C + I + G + NX。"},{"id":"exchange-rate","name":"Exchange Rates","zh":"汇率","chapters":[6],"summary":"名义汇率：两种货币的相对价格。实际汇率＝名义汇率×国内价格/国外价格（ε=e·P/P*）。\n实际汇率衡量两国商品的相对价格，影响净出口。\n实际汇率上升（本币升值）→净出口下降。"},{"id":"ppp","name":"Purchasing Power Parity","zh":"购买力平价","chapters":[6],"summary":"购买力平价（PPP）：一价定律在国际层面的应用。\n实际汇率应为1，即同样货币在不同国家购买力相同。\nPPP长期成立较好，短期受贸易壁垒、非贸易品等因素影响。"},{"id":"natural-rate","name":"Natural Rate of Unemployment","zh":"自然失业率","chapters":[7],"summary":"自然失业率：经济长期均衡时的失业率（充分就业水平）。\n由离职率 s 与找到工作率 f 决定：U/L = s/(s+f)。\n包括摩擦性失业与结构性失业，不含周期性失业。"},{"id":"job-search","name":"Job Search & Frictional Unemployment","zh":"就业搜寻与摩擦性失业","chapters":[7],"summary":"摩擦性失业：工人在找合适工作过程中产生的失业。\n原因：部门转移、不同企业/地区差异、信息不完全。\n公共政策：就业服务机构、失业保障（可能延长搜寻时间）。"},{"id":"wage-rigidity","name":"Wage Rigidity & Structural Unemployment","zh":"工资刚性与结构性失业","chapters":[7],"summary":"结构性失业：工资高于市场出清水平导致的失业（供大于求）。\n工资刚性来源：最低工资法、工会、效率工资。\n效率工资理论：高工资提高生产率（营养、减少流动、逆向选择、激励）。"},{"id":"solow-model","name":"Solow Growth Model","zh":"索洛增长模型","chapters":[8],"summary":"索洛模型：资本积累 Δk = s·f(k) − (δ+n)·k。\n稳态：投资恰好弥补折旧与人口增长，人均资本 k 不变。\n储蓄率提高→更高稳态k和y，但不影响长期增长率。"},{"id":"golden-rule","name":"Golden Rule","zh":"黄金律","chapters":[8],"summary":"黄金律资本水平：使人均消费最大化的稳态。\n条件：MPK = δ + n（资本边际产品等于折旧加人口增长率）。\n储蓄率过高或过低都会降低稳态消费。"},{"id":"population-growth","name":"Population Growth","zh":"人口增长与增长模型","chapters":[8],"summary":"人口增长 n 提高：稀释资本（降低稳态人均资本）。\n含人口增长的稳态：Δk = s·f(k) − (δ+n)·k。\n人口增长降低稳态人均收入，但总产出以 n 增长。"},{"id":"technology-growth","name":"Technological Progress","zh":"技术进步与增长","chapters":[9],"summary":"劳动增进型技术进步：Y = F(K, L×E)，E为劳动效率。\n稳态增长：人均产出以技术进步率 g 增长。\n技术进步是长期人均收入持续增长的唯一来源。"},{"id":"endogenous-growth","name":"Endogenous Growth Theory","zh":"内生增长理论","chapters":[9],"summary":"内生增长模型：Y = A·K，资本边际产品不递减。\n增长率由模型内决定（储蓄率、知识外溢等）。\n与索洛模型区别：长期增长由内生化因素驱动，而非外生技术。"},{"id":"growth-policy","name":"Growth Policies","zh":"增长政策","chapters":[9],"summary":"促进增长的公共政策：提高储蓄与投资、教育（人力资本）、研发。\n产权保护与政治稳定促进投资。\n创新激励与知识扩散存在权衡。"},{"id":"business-cycle","name":"Business Cycle Facts","zh":"经济周期事实","chapters":[10],"summary":"经济周期：产出与就业的短期波动。\n衰退：实际GDP温和下降；萧条：严重下降。\n典型事实：消费与投资顺周期、投资波动更大、失业逆周期。"},{"id":"ad-as","name":"Aggregate Demand & Supply","zh":"总需求与总供给","chapters":[10],"summary":"总需求（AD）：价格水平与总需求量的负向关系（财富效应、利率效应、汇率效应）。\n总供给（AS）：长期垂直（产出由要素决定），短期水平（价格粘性）。\n冲击→AD/AS移动→短期波动。"},{"id":"is-curve","name":"IS Curve","zh":"IS 曲线","chapters":[11],"summary":"IS曲线：产品市场均衡时利率与收入的组合。\nY = C(Y−T) + I(r) + G，利率上升→投资下降→收入下降。\nIS曲线向右下倾斜；财政扩张（G↑或T↓）使IS右移。"},{"id":"lm-curve","name":"LM Curve","zh":"LM 曲线","chapters":[11],"summary":"LM曲线：货币市场均衡时利率与收入的组合。\n实际货币余额需求 L(r, Y) 等于供给 M/P。\n收入上升→货币需求增加→利率上升；LM向右上倾斜；货币扩张使LM右移。"},{"id":"islm-model","name":"IS-LM Model","zh":"IS-LM 模型","chapters":[11],"summary":"IS-LM模型：产品市场与货币市场同时均衡。\nIS与LM交点决定均衡利率 r 与均衡收入 Y。\n用于分析财政政策与货币政策的短期效应。"},{"id":"islm-policy","name":"IS-LM Policy Analysis","zh":"IS-LM 政策分析","chapters":[12],"summary":"财政扩张：IS右移→收入↑利率↑，挤出部分投资。\n货币扩张：LM右移→收入↑利率↓。\n政策有效性取决于IS/LM斜率（如流动性陷阱、投资陷阱）。"},{"id":"great-depression","name":"The Great Depression","zh":"大萧条解释","chapters":[12],"summary":"大萧条（1929-1933）：产出与就业大幅下降。\n解释：支出假说（IS大幅左移）、货币假说（LM左移）、价格紧缩效应。\n实际货币余额下降与通缩加剧了衰退。"},{"id":"phillips-curve","name":"Phillips Curve","zh":"菲利普斯曲线","chapters":[14],"summary":"菲利普斯曲线：通胀与失业的负相关关系。\nπ = πᵉ − β(u − uⁿ) + v，通胀取决于预期通胀、失业缺口与供给冲击。\n短期存在权衡，长期垂直（预期调整）。"},{"id":"expectations-as","name":"Expectations & Aggregate Supply","zh":"预期与总供给","chapters":[14],"summary":"适应性预期：根据过去通胀形成预期；理性预期：利用所有信息最优化预测。\n总供给取决于价格与预期价格的偏差。\n未预期货币政策短期有效，理性预期下系统性政策无效（政策无效性命题）。"},{"id":"sacrifice-ratio","name":"Sacrifice Ratio & Disinflation","zh":"牺牲率与反通胀","chapters":[14],"summary":"牺牲率：降低1个百分点通胀所需放弃的GDP百分比。\n反通胀：降低通胀率的过程，伴随短期产出损失。\n可信的政策承诺可降低牺牲率（预期快速调整）。"},{"id":"policy-lags","name":"Policy Lags","zh":"政策时滞","chapters":[16],"summary":"政策时滞：内在时滞（认识与决策）与外在时滞（政策生效）。\n货币政策外在时滞长；财政政策内在时滞长。\n时滞使反周期政策可能顺周期，加剧波动。"},{"id":"rules-discretion","name":"Rules vs. Discretion","zh":"规则与相机抉择","chapters":[16],"summary":"相机抉择：政策制定者逐期最优选择；规则：预先承诺固定政策。\n时间不一致：政策制定者有事后偏离承诺的激励。\n规则能增强可信度、降低通胀预期（如通胀目标制）。"},{"id":"inflation-targeting","name":"Inflation Targeting","zh":"通胀目标制","chapters":[16],"summary":"通胀目标制：央行公开承诺一个通胀目标并以此指导政策。\n增强政策透明度与可信度，锚定通胀预期。\n泰勒规则：名义利率对通胀缺口与产出缺口反应。"},{"id":"ricardian","name":"Ricardian Equivalence","zh":"李嘉图等价","chapters":[17],"summary":"李嘉图等价：政府债务融资与税收融资等价（消费者理性前瞻）。\n减税+增发债券→家庭预期未来增税→储蓄增加，消费不变。\n前提：理性预期、无流动性约束、代际利他。"},{"id":"debt-measure","name":"Measuring Government Debt","zh":"政府债务衡量","chapters":[17],"summary":"政府债务：政府历年赤字的累积。\n预算赤字＝支出−收入。\n衡量问题：未调整通胀、未计资产、未含隐性负债、未计经济周期影响。"},{"id":"debt-dynamics","name":"Debt Dynamics","zh":"债务动态","chapters":[17],"summary":"债务负担：债务/GDP比率，取决于利率、增长率与基础赤字。\n当 r > g 时，债务负担趋于上升，需基础盈余维持。\n债务可持续性要求债务增长不超过经济增长。"},{"id":"financial-system","name":"Financial System & Institutions","zh":"金融体系与金融机构","chapters":[18],"summary":"金融体系：连接储蓄者与借款人的机构与市场。\n直接融资：通过金融市场（债券、股票）；间接融资：通过金融中介（银行、共同基金）。\n债券＝债务融资（对企业的贷款）；股票＝股权融资（企业所有权份额）。"},{"id":"risk-diversification","name":"Risk & Diversification","zh":"风险与分散化","chapters":[18],"summary":"风险厌恶：人们厌恶经济处境中的不确定性。\n分散化：持有许多不完全相关的资产以降低风险。\n系统性风险（影响所有企业）无法分散；特有风险（单个企业）可分散消除。"},{"id":"asymmetric-information","name":"Asymmetric Information","zh":"信息不对称","chapters":[18],"summary":"信息不对称：交易一方比另一方了解更多信息。\n逆向选择：关于特征的隐藏信息（事前，高风险者更愿交易）。\n道德风险：关于行为的隐藏信息（事后，代理人不当行为）。\n银行通过评估借款人（缓解逆向选择）与贷后监督（缓解道德风险）。"},{"id":"financial-crisis","name":"Financial Crises & Policy","zh":"金融危机与应对政策","chapters":[18],"summary":"金融危机：金融中介能力受阻的重大扰乱。\n阶段：资产泡沫与破裂→机构资不抵债→信心下降→信贷紧缩→衰退。\n应对：常规货币财政政策、最后贷款人、资本注入；监管改革（沃尔克规则、多德-弗兰克法案）。"},{"id":"dad-das","name":"Dynamic Model of Economic Fluctuations (DAD-DAS)","zh":"动态总需求-总供给模型","chapters":[15],"summary":"动态模型：把总需求、总供给与货币政策规则动态联系起来。\nDAD 曲线：通胀与产出负相关（由需求方程、费雪方程、货币政策规则推导）。\nDAS 曲线：即菲利普斯曲线 π = π₋₁ + φ(Y − Ȳ) + v。\n货币政策规则：央行对通胀缺口与产出缺口做出反应（泰勒规则，含泰勒原则）。\n用于分析需求/供给冲击的动态响应与长期均衡。"}]};
